-- bootstrap / identity
-- note: keeps the legacy global alias while using a lower-case internal namespace.
-- ═══════════════════════════════════════════════════════════════════════════════════

local script_version = "v1.0.0"
local script_release_date = "2026-08-02"

local minigames = _G.minigames or _G.MG or {}
_G.minigames = minigames
_G.MG = minigames

-- direct-call compatibility
-- note: this preserves existing multi-return call sites without protected execution.
local function direct_call(callback, ...)
    return true, callback(...)
end

local function direct_call_trace(callback, _, ...)
    return true, callback(...)
end

