function minigames.LogInfo(msg)
    if minigames.S and minigames.S.cleanBootConsoleV205 == true then
        return
    end
    if Logger and Logger.LogInfo then
        Logger.LogInfo("[" .. minigames.NAME .. "] " .. tostring(msg))
    end
end

function minigames.LogError(msg)
    if Logger and Logger.LogError then
        Logger.LogError("[" .. minigames.NAME .. "] " .. tostring(msg))
    else
        minigames.LogInfo("[ERROR] " .. tostring(msg))
    end
end

function minigames.Toast(title, msg, duration)
    duration = duration or 4000

    if GUI and GUI.AddToast then
        direct_call(function()
            GUI.AddToast(tostring(title), tostring(msg), duration)
        end)
    end

    minigames.LogInfo(tostring(title) .. " | " .. tostring(msg))
end

function minigames.Hash(name)
    return Utils.Joaat("MG164_" .. tostring(name))
end

function minigames.Now()
    if MISC and MISC.GET_GAME_TIMER then
        local ok, result = direct_call(function()
            return MISC.GET_GAME_TIMER()
        end)
        if ok and result then return result end
    end

    if Utils and Utils.GetTimeEpocheMs then
        local ok, result = direct_call(function()
            return Utils.GetTimeEpocheMs()
        end)
        if ok and result then return result end
    end

    return math.floor(os.clock() * 1000)
end

function minigames.Yield(ms)
    -- v0.061:
    -- cherax can reject script.yield inside feature/tick callback fibers.
    -- wargames now uses timer-based work instead of yielding from callbacks.
    -- keeping this as a safe no-op prevents cleanup/teleport/round features from throwing.
    return
end

function minigames.Queue(fn)
    if Script and Script.QueueJob then
        Script.QueueJob(fn)
    else
        fn()
    end
end

function minigames.ClampInt(value, minValue, maxValue)
    value = tonumber(value) or minValue
    value = math.floor(value)

    if value < minValue then return minValue end
    if value > maxValue then return maxValue end

    return value
end

function minigames.ClampFloat(value, minValue, maxValue)
    value = tonumber(value) or minValue

    if value < minValue then return minValue end
    if value > maxValue then return maxValue end

    return value
end

function minigames.DegToRad(degrees)
    return (degrees or 0.0) * math.pi / 180.0
end

function minigames.SafeMkdir(path)
    path = tostring(path or "")
    if path == "" then return false end

    -- cherax does not expose command-shell execution in every lua environment.
    -- use the supported file manager directly so queued boot cannot call nil.
    if FileMgr and FileMgr.CreateDir then
        FileMgr.CreateDir(path)
        return true
    end

    return false
end

function minigames.SetFeatureInt(hash, value)
    local f = FeatureMgr.GetFeature(hash)
    if not f then return end

    if f.SetIntValue then
        direct_call(function() f:SetIntValue(value) end)
    elseif f.SetValue then
        direct_call(function() f:SetValue(value) end)
    end
end

function minigames.SetFeatureBool(hash, value)
    local f = FeatureMgr.GetFeature(hash)
    if not f then return end

    if f.SetBoolValue then
        direct_call(function() f:SetBoolValue(value == true) end)
    elseif f.SetValue then
        direct_call(function() f:SetValue(value == true) end)
    end
end

function minigames.GetFeatureInt(hash, fallback)
    local f = FeatureMgr.GetFeature(hash)

    if f and f.GetIntValue then
        local ok, value = direct_call(function()
            return f:GetIntValue()
        end)

        if ok and value ~= nil then
            return tonumber(value) or fallback
        end
    end

    return fallback
end

function minigames.GetFeatureBool(hash, fallback)
    local f = FeatureMgr.GetFeature(hash)

    if f and f.IsToggled then
        local ok, value = direct_call(function()
            return f:IsToggled()
        end)

        if ok and value ~= nil then
            return value == true
        end
    end

    return fallback
end


------------------------------------------------------------
-- feature helper compatibility
------------------------------------------------------------
-- v0.059b:
-- some wargames ui files use mg.addtoggle for simple toggles.
-- older modular builds only had addtoggleontick, so this keeps
-- the ui file compatible without changing the wargames logic.
------------------------------------------------------------

function minigames.AddToggle(hash, name, desc, callback, defaultValue)
    local feature = FeatureMgr.AddFeature(
        hash,
        name,
        eFeatureType.Toggle,
        desc or "",
        callback
    )

    if feature and feature.SetDefaultValue then
        feature:SetDefaultValue(defaultValue == true):Reset()
    end

    return feature
end

function minigames.AddButton(hash, name, desc, callback)
    return FeatureMgr.AddFeature(
        hash,
        name,
        eFeatureType.Button,
        desc or "",
        callback
    )
end

function minigames.AddToggleOnTick(hash, name, desc, callback, defaultValue)
    -- v0.064:
    -- this used to register ecallbacktrigger.ontick, which made heavy wargames
    -- callbacks run constantly and caused vehicle freeze/stutter.
    -- it is now a normal toggle helper. the scheduler does timed work safely.
    local feature = FeatureMgr.AddFeature(
        hash,
        name,
        eFeatureType.Toggle,
        desc or "",
        callback
    )

    if feature and feature.SetDefaultValue then
        feature:SetDefaultValue(defaultValue == true):Reset()
    end

    return feature
end

function minigames.AddButton(hash, name, desc, callback, threaded)
    return FeatureMgr.AddFeature(hash, name, eFeatureType.Button, desc, callback, threaded == true, threaded == true)
end

function minigames.BuildNatives()
    if not Natives then
        minigames.LogInfo("Natives missing. Native helpers disabled.")
        return false
    end

    if not Natives.InvokeVoid or not Natives.InvokeInt or not Natives.InvokeFloat or not Natives.InvokeBool or not Natives.InvokeV3 then
        minigames.LogInfo("Required native invoke helpers missing.")
        return false
    end

    minigames.Inv = {
        Void = Natives.InvokeVoid,
        Int = Natives.InvokeInt,
        Float = Natives.InvokeFloat,
        Bool = Natives.InvokeBool,
        String = Natives.InvokeString,
        V3Raw = Natives.InvokeV3
    }

    function minigames.Inv.V3(hash, ...)
        return V3.New(minigames.Inv.V3Raw(hash, ...))
    end

    MISC = MISC or {}
    HUD = HUD or {}
    GRAPHICS = GRAPHICS or {}
    PLAYER = PLAYER or {}
    ENTITY = ENTITY or {}
    PED = PED or {}
    VEHICLE = VEHICLE or {}
