function minigames.DrawRect(x, y, w, h, r, g, b, a)
    if not minigames.S.nativeOK or not GRAPHICS then return end
    direct_call(function()
        GRAPHICS.DRAW_RECT(x, y, w, h, r, g, b, a, false)
    end)
end

function minigames.DrawText(text, x, y, size, r, g, b, a, font)
    if not minigames.S.nativeOK or not HUD then return end

    direct_call(function()
        HUD.SET_TEXT_FONT(font or 7)
        HUD.SET_TEXT_SCALE(0.0, size + 0.0)
        HUD.SET_TEXT_COLOUR(r or 255, g or 255, b or 255, a or 255)
        HUD.SET_TEXT_CENTRE(true)
        HUD.SET_TEXT_DROP_SHADOW()
        HUD.SET_TEXT_OUTLINE()
        HUD.BEGIN_TEXT_COMMAND_DISPLAY_TEXT("STRING")
        HUD.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME(tostring(text))
        HUD.END_TEXT_COMMAND_DISPLAY_TEXT(x + 0.0, y + 0.0)
    end)
end


function minigames.RandomInt(minValue, maxValue)
    minValue = tonumber(minValue) or 0
    maxValue = tonumber(maxValue) or minValue
    if maxValue < minValue then minValue, maxValue = maxValue, minValue end
    return math.random(minValue, maxValue)
end

minigames.C.DEFAULT_BOUNTY_INTERVAL_MS = 180000


function minigames.QueueImmediate(fn)
    -- runs work directly with direct call. use for short no-yield actions.
    if type(fn) ~= "function" then
        return false, "not_function"
    end

    local ok, err = direct_call(fn)

    if not ok then
        minigames.LogError("QueueImmediate failed: " .. tostring(err))
        return false, err
    end

    return true, "ok"
end


function minigames.SafeIsToggled(feature, fallbackHash, fallbackValue)
    local fallback = fallbackValue == true

    if feature ~= nil then
        local ok, result = direct_call(function()
            return feature:IsToggled()
        end)

        if ok and result ~= nil then
            return result == true
        end
    end

    if fallbackHash ~= nil and FeatureMgr and FeatureMgr.GetFeature then
        local okGet, f = direct_call(function()
            return FeatureMgr.GetFeature(fallbackHash)
        end)

        if okGet and f ~= nil then
            local okToggle, result = direct_call(function()
                return f:IsToggled()
            end)

            if okToggle and result ~= nil then
                return result == true
            end
        end
    end

    return fallback
end

function minigames.SafeRenderFeature(hash)
    local ok, err = direct_call(function()
        ClickGUI.RenderFeature(hash)
    end)

    if not ok then
        minigames.LogError("RenderFeature failed | hash=" .. tostring(hash) .. " | err=" .. tostring(err))
    end

    return ok
end


