-- intro / hud renderer
------------------------------------------------------------
-- v0.065b:
-- lightweight renderer for the minigames startup title/subtitle.
-- this does not re-enable heavy wargames ontick logic.
------------------------------------------------------------

function minigames.DrawText(text, x, y, size, r, g, b, a, font)
    if not HUD then
        return
    end

    direct_call(function()
        if HUD.SET_TEXT_FONT then
            HUD.SET_TEXT_FONT(font or 7)
        end

        if HUD.SET_TEXT_SCALE then
            HUD.SET_TEXT_SCALE(0.0, size + 0.0)
        end

        if HUD.SET_TEXT_COLOUR then
            HUD.SET_TEXT_COLOUR(r or 255, g or 255, b or 255, a or 255)
        end

        if HUD.SET_TEXT_CENTRE then
            HUD.SET_TEXT_CENTRE(true)
        end

        if HUD.SET_TEXT_DROP_SHADOW then
            HUD.SET_TEXT_DROP_SHADOW()
        end

        if HUD.SET_TEXT_OUTLINE then
            HUD.SET_TEXT_OUTLINE()
        end

        if HUD.BEGIN_TEXT_COMMAND_DISPLAY_TEXT then
            HUD.BEGIN_TEXT_COMMAND_DISPLAY_TEXT("STRING")
        end

        if HUD.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME then
            HUD.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME(tostring(text))
        end

        if HUD.END_TEXT_COMMAND_DISPLAY_TEXT then
            HUD.END_TEXT_COMMAND_DISPLAY_TEXT(x + 0.0, y + 0.0)
        end
    end)
end

function minigames.DrawIntro()
    if minigames.S.introEnabled == false then
        return
    end

    local now = minigames.Now()

    if not minigames.S.introStartMs or minigames.S.introStartMs == 0 then
        minigames.S.introStartMs = now
    end

    local duration = minigames.S.introDurationMs or 7200
    local fadeStart = minigames.S.introFadeStartMs or 2800
    local elapsed = now - minigames.S.introStartMs

    if elapsed > duration then
        return
    end

    local alpha = 255

    if elapsed > fadeStart then
        local fadeElapsed = elapsed - fadeStart
        local fadeDuration = duration - fadeStart

        if fadeDuration <= 0 then
            alpha = 0
        else
            alpha = math.floor(math.max(0, math.min(255, 255 * (1.0 - fadeElapsed / fadeDuration))))
        end
    end

    -- red heading, driftgod-style intro energy.
    minigames.DrawText(minigames.TITLE or "MINIGAMES", 0.5, 0.36, 1.42, 255, 45, 45, alpha, 7)
    minigames.DrawText(minigames.SUBTITLE or "Turn the lobby into your personal playground.", 0.5, 0.455, 0.44, 255, 255, 255, alpha, 4)
end

function minigames.ResetIntro()
    minigames.S.introStartMs = minigames.Now()
end


