function minigames.DrawRect(x, y, w, h, r, g, b, a)
    if not GRAPHICS or not GRAPHICS.DRAW_RECT then
        return
    end

    direct_call(function()
        GRAPHICS.DRAW_RECT(x + 0.0, y + 0.0, w + 0.0, h + 0.0, r or 0, g or 0, b or 0, a or 120, false)
    end)
