function minigames.GetCurrentMinigameLabel()
    if minigames.LandOnIt and minigames.LandOnIt.S and minigames.LandOnIt.S.active == true then
        return "Land On It"
    end

    if minigames.S and minigames.S.wargamesSystemsActive == true then
        if minigames.S.noBountyMode == true or minigames.S.wargamesNoBountiesActive == true then
            return "WarGames - No Bounties"
        end

        return "WarGames"
    end

    if minigames.S and (minigames.S.respawnVehiclesOnPlayerRespawn == true or minigames.S.spawnVehiclesOnRespawn == true) then
        return "WarGames Respawn"
    end

    return "None"
end

function minigames.GetHudPlayersSummary()
    local activeCount = 0

    if minigames.S and minigames.S.activePlayers then
        activeCount = #(minigames.S.activePlayers or {})
    end

    local line = "Players: " .. tostring(activeCount)

    if activeCount > 0 then
        local names = {}
        local maxNames = minigames.S.hudMaxPlayerNames or 3

        for i, playerId in ipairs(minigames.S.activePlayers or {}) do
            if i > maxNames then
                break
            end

            table.insert(names, minigames.GetPlayerName(playerId))
        end

        if #names > 0 then
            line = line .. " | " .. table.concat(names, ", ")

            if activeCount > maxNames then
                line = line .. " +" .. tostring(activeCount - maxNames)
            end
        end
    end

    return line
end

function minigames.GetCurrentVehicleRoundLabel()
    if minigames.WarGames and minigames.WarGames.GetCurrentRoundVehicle then
        local ok, vehicle = direct_call(function()
            return minigames.WarGames.GetCurrentRoundVehicle()
        end)

        if ok and vehicle then
            return tostring(vehicle.label or vehicle.name or "Unknown")
        end
    end

    if minigames.WarGames and minigames.WarGames.GetSelectedVehicle then
        local ok, vehicle = direct_call(function()
            return minigames.WarGames.GetSelectedVehicle()
        end)

        if ok and vehicle then
            return tostring(vehicle.label or vehicle.name or "Unknown")
        end
    end

    if minigames.S and minigames.S.lastVehicleName then
        return tostring(minigames.S.lastVehicleName)
    end

    return "None"
end

function minigames.GetMinigameHudLines()
    local lines = {}

    table.insert(lines, "Current Minigame: " .. minigames.GetCurrentMinigameLabel())

    local current = minigames.GetCurrentMinigameLabel()

    if current == "Land On It" and minigames.LandOnIt and minigames.LandOnIt.S then
        table.insert(lines, "Objective: Land on the Mall")
        table.insert(lines, "Vehicle: " .. tostring(minigames.LandOnIt.S.selectedVehicle or "Oppressor MK1"))
        table.insert(lines, "Last: " .. tostring(minigames.LandOnIt.S.lastStatus or "None"))
    elseif current ~= "None" then
        table.insert(lines, "Round Vehicle: " .. minigames.GetCurrentVehicleRoundLabel())
        table.insert(lines, "Respawn Vehicles: " .. tostring(minigames.S.spawnVehiclesOnRespawn == true or minigames.S.respawnVehiclesOnPlayerRespawn == true))
        table.insert(lines, "Bounties: " .. tostring(minigames.S.autoBountyEnabled == true or minigames.S.autoBountyRunning == true))
        table.insert(lines, "No Cops: " .. tostring(minigames.S.noCopsEnabled == true or minigames.S.peacekeeperNoCops == true))
    else
        table.insert(lines, "Status: Waiting for a minigame")
        table.insert(lines, "Tip: Activate WarGames or Land On It")
    end

    table.insert(lines, minigames.GetHudPlayersSummary())

    if minigames.S and minigames.S.hudShowLastStatus ~= false then
        local status = minigames.S.lastWarGamesSystemsError or minigames.S.lastSchedulerError or minigames.S.lastVehicleStatus or "None"
        if status ~= "None" and status ~= "" then
            table.insert(lines, "Last: " .. tostring(status))
        end
    end

    return lines
end

function minigames.DrawMinigamesHud()
    if not minigames.S or minigames.S.minigamesHudEnabled == false then
        return
    end

    -- keep hud lightweight and readable.
    local lines = minigames.GetMinigameHudLines()
    local x = minigames.S.minigamesHudX or 0.875
    local y = minigames.S.minigamesHudY or 0.475
    local width = minigames.S.minigamesHudW or 0.210
    local headerH = 0.028
    local lineH = 0.023
    local height = headerH + (#lines * lineH) + 0.020

    -- background + header bar.
    minigames.DrawRect(x, y, width, height, 0, 0, 0, minigames.S.minigamesHudAlpha or 125)
    minigames.DrawRect(x, y - (height / 2.0) + (headerH / 2.0), width, headerH, 145, 35, 45, 185)

    minigames.DrawText("MINIGAMES", x, y - (height / 2.0) + 0.005, 0.255, 255, 255, 255, 235, 7)

    local startY = y - (height / 2.0) + headerH + 0.006

    for i, line in ipairs(lines) do
        minigames.DrawText(tostring(line), x, startY + ((i - 1) * lineH), 0.210, 240, 240, 240, 230, 4)
    end
end

function minigames.ResetMinigamesHudPosition()
    minigames.S.minigamesHudX = 0.875
    minigames.S.minigamesHudY = 0.475
    minigames.S.minigamesHudW = 0.210
    minigames.S.minigamesHudAlpha = 125
end


