-- compact minigames status hud
------------------------------------------------------------
-- v0.075:
-- k-script-style compact hud box:
-- red title bar, small black body, compact wargames/land on it stats.
------------------------------------------------------------

function minigames.ShortName(name, maxLen)
    name = tostring(name or "Unknown")
    maxLen = maxLen or 14

    if #name <= maxLen then
        return name
    end

    return string.sub(name, 1, maxLen - 1) .. "…"
end

function minigames.FormatDuration(ms)
    ms = tonumber(ms or 0) or 0
    if ms < 0 then ms = 0 end

    local total = math.floor(ms / 1000)
    local h = math.floor(total / 3600)
    local m = math.floor((total % 3600) / 60)
    local s = total % 60

    if h > 0 then
        return string.format("%02d:%02d:%02d", h, m, s)
    end

    return string.format("%02d:%02d", m, s)
end

function minigames.GetVehicleRoundByOffset(offset)
    offset = tonumber(offset or 0) or 0

    local vehicles = nil

    if minigames.WarGames and minigames.WarGames.Vehicles then
        vehicles = minigames.WarGames.Vehicles
    elseif minigames.WARGAMES_VEHICLES then
        vehicles = minigames.WARGAMES_VEHICLES
    elseif minigames.Vehicles then
        vehicles = minigames.Vehicles
    end

    if type(vehicles) ~= "table" or #vehicles == 0 then
        return "None"
    end

    local index = 1

    if minigames.S then
        index = tonumber(minigames.S.currentRoundVehicleIndex or minigames.S.selectedVehicleIndex or minigames.S.selectedMinigameVehicle or 1) or 1
    end

    local count = #vehicles
    local resolved = ((index - 1 + offset) % count) + 1
    local vehicle = vehicles[resolved]

    if type(vehicle) ~= "table" then
        return tostring(vehicle or "None")
    end

    return tostring(vehicle.label or vehicle.name or vehicle.shortName or vehicle.model or "Unknown")
end

function minigames.GetTrackedVehicleCount()
    local count = 0

    local candidates = {
        minigames.S and minigames.S.trackedVehicles,
        minigames.S and minigames.S.spawnedVehicles,
        minigames.S and minigames.S.wargamesVehicles,
        minigames.S and minigames.S.trackedWarGamesVehicles,
        minigames.WarGames and minigames.WarGames.S and minigames.WarGames.S.spawnedVehicles
    }

    for _, tbl in ipairs(candidates) do
        if type(tbl) == "table" then
            local c = 0
            for _, _ in pairs(tbl) do
                c = c + 1
            end

            if c > count then
                count = c
            end
        end
    end

    return count
end

function minigames.GetClearedVehicleCount()
    if not minigames.S then return 0 end

    return tonumber(
        minigames.S.totalVehiclesCleared or
        minigames.S.vehiclesClearedTotal or
        minigames.S.destroyedVehicleCleanupCount or
        minigames.S.vehicleCleanupDeletedTotal or
        minigames.S.cleanedVehicleCount or
        0
    ) or 0
end

function minigames.GetPlayerSessionDurationMs(playerId)
    playerId = minigames.ClampInt(playerId or 0, 0, 31)

    local now = minigames.Now()

    local joined =
        (minigames.S and minigames.S.playerJoinedAtMs and minigames.S.playerJoinedAtMs[playerId]) or
        (minigames.S and minigames.S.playerFirstSeenMs and minigames.S.playerFirstSeenMs[playerId]) or
        (minigames.S and minigames.S.joinedAtMs and minigames.S.joinedAtMs[playerId]) or
        0

    joined = tonumber(joined or 0) or 0

    if joined <= 0 then
        return 0
    end

    return now - joined
end

function minigames.GetPlayerKillStreak(playerId)
    playerId = minigames.ClampInt(playerId or 0, 0, 31)

    if not minigames.S then return 0 end

    local sources = {
        minigames.S.vehicleKillStreaks,
        minigames.S.killStreaks,
        minigames.S.playerKillStreaks,
        minigames.S.wargamesKillStreaks
    }

    for _, src in ipairs(sources) do
        if type(src) == "table" and src[playerId] ~= nil then
            return tonumber(src[playerId] or 0) or 0
        end
    end

    return 0
end

function minigames.GetGodVehicleRemainingMs(playerId)
    playerId = minigames.ClampInt(playerId or 0, 0, 31)

    if not minigames.S then return 0 end

    local now = minigames.Now()
    local sources = {
        minigames.S.godVehicleUntilMs,
        minigames.S.vehicleGodModeUntilMs,
        minigames.S.playerGodVehicleUntilMs,
        minigames.S.perkVehicleGodUntilMs
    }

    for _, src in ipairs(sources) do
        if type(src) == "table" and src[playerId] ~= nil then
            local untilMs = tonumber(src[playerId] or 0) or 0
            if untilMs > now then
                return untilMs - now
            end
        end
    end

    return 0
end

function minigames.GetTopPlayersForHud(metric, limit)
    limit = limit or 3
    local rows = {}

    for _, playerId in ipairs((minigames.S and minigames.S.activePlayers) or {}) do
        local value = 0

        if metric == "kills" then
            value = minigames.GetPlayerKillStreak(playerId)
        elseif metric == "session" then
            value = minigames.GetPlayerSessionDurationMs(playerId)
        elseif metric == "god" then
            value = minigames.GetGodVehicleRemainingMs(playerId)
        end

        if value and value > 0 then
            table.insert(rows, {
                playerId = playerId,
                name = minigames.GetPlayerName(playerId),
                value = value
            })
        end
    end

    table.sort(rows, function(a, b)
        return (a.value or 0) > (b.value or 0)
    end)

    while #rows > limit do
        table.remove(rows, #rows)
    end

    return rows
end

function minigames.GetCompactHudLines()
    local lines = {}

    local current = minigames.GetCurrentMinigameLabel and minigames.GetCurrentMinigameLabel() or "None"

    table.insert(lines, minigames.FitHudText("Mode: " .. tostring(current)))

    if current == "Land On It" then
        table.insert(lines, minigames.FitHudText("Goal: Land on Mall"))
        table.insert(lines, minigames.FitHudText("Vehicle: MK1"))
        if minigames.LandOnIt and minigames.LandOnIt.S then
            table.insert(lines, minigames.FitHudText("Last: " .. tostring(minigames.LandOnIt.S.lastStatus or "Ready")))
        end
    else
        table.insert(lines, minigames.FitHudText("Vehicle: " .. tostring(minigames.GetVehicleRoundByOffset(0))))
        table.insert(lines, minigames.FitHudText("- " .. tostring(minigames.GetVehicleRoundByOffset(-1)) .. "   + " .. tostring(minigames.GetVehicleRoundByOffset(1))))
        table.insert(lines, minigames.FitHudText(minigames.GetHudVehicleStatsText and minigames.GetHudVehicleStatsText() or ("Vehicles: " .. tostring(minigames.GetTrackedVehicleCount()) .. "  Cleared: " .. tostring(minigames.GetClearedVehicleCount()))))
    end

    local activeCount = #(minigames.S and minigames.S.activePlayers or {})
    table.insert(lines, minigames.FitHudText("Players: " .. tostring(activeCount)))

    local kills = minigames.GetTopPlayersForHud("kills", 3)
    if #kills > 0 then
        table.insert(lines, "Kill Streaks:")
        for _, row in ipairs(kills) do
            table.insert(lines, minigames.FitHudText(tostring(row.name) .. ": " .. tostring(row.value)))
        end
    end

    local sessions = minigames.GetTopPlayersForHud("session", 3)
    if #sessions > 0 then
        table.insert(lines, "Session:")
        for _, row in ipairs(sessions) do
            table.insert(lines, minigames.FitHudText(tostring(row.name) .. ": " .. minigames.FormatDuration(row.value)))
        end
    else
        local names = {}
        for i, playerId in ipairs((minigames.S and minigames.S.activePlayers) or {}) do
            if i > 3 then break end
            table.insert(names, minigames.ShortName(minigames.GetPlayerName(playerId), 10))
        end
        if #names > 0 then
            table.insert(lines, minigames.FitHudText(table.concat(names, ", ")))
        end
    end

    local gods = minigames.GetTopPlayersForHud("god", 3)
    if #gods > 0 then
        table.insert(lines, "God Vehicles:")
        for _, row in ipairs(gods) do
            table.insert(lines, minigames.FitHudText(tostring(row.name) .. ": " .. minigames.FormatDuration(row.value)))
        end
    end

    return lines
end

function minigames.ResetCompactHudPosition()
    if minigames.ApplyBestCompactHudPreset then minigames.ApplyBestCompactHudPreset() end
end



