------------------------------------------------------------
-- v0.077 compact hud tuning + quiet cleanup helpers
------------------------------------------------------------



function minigames.CompactHudMove(dx, dy)
    minigames.S.compactHudX = math.max(0.02, math.min(0.98, (minigames.S.compactHudX or 0.260) + dx))
    minigames.S.compactHudY = math.max(0.02, math.min(0.98, (minigames.S.compactHudY or 0.885) + dy))
end

function minigames.CompactHudWidthStep(amount)
    if minigames.SetCompactHudWidth then
        minigames.SetCompactHudWidth((minigames.S.compactHudW or 0.145) + amount)
    else
        minigames.S.compactHudW = math.max(0.095, math.min(0.320, (minigames.S.compactHudW or 0.145) + amount))
    end
end

function minigames.CompactHudTextStep(amount)
    minigames.S.compactHudTextScale = math.max(0.115, math.min(0.240, (minigames.S.compactHudTextScale or 0.165) + amount))
end

function minigames.CompactHudAlphaStep(amount)
    minigames.S.compactHudAlpha = math.max(30, math.min(220, (minigames.S.compactHudAlpha or 112) + amount))
end

function minigames.CompactHudLinesStep(amount)
    minigames.S.compactHudMaxLines = math.max(5, math.min(18, (minigames.S.compactHudMaxLines or 11) + amount))
end

function minigames.CompactHudHeaderText()
    local mode = minigames.GetCurrentMinigameLabel and minigames.GetCurrentMinigameLabel() or "None"
    if mode and mode ~= "None" then
        return "MINIGAMES - " .. tostring(mode)
    end
    return "MINIGAMES"
end

function minigames.ShouldLogCleanupStatus(deleted, failed, attempted, reason)
    deleted = tonumber(deleted or 0) or 0
    failed = tonumber(failed or 0) or 0
    attempted = tonumber(attempted or 0) or 0
    reason = tostring(reason or "cleanup")
    local mode = tonumber(minigames.S.cleanupLogMode or 1) or 1
    local now = minigames.Now()
    if mode <= 0 then return false end
    if failed > 0 or deleted > 0 then return true end
    if mode >= 3 then return true end
    if mode >= 2 then
        local key = "lastCleanupSummaryLogMs_" .. reason
        local last = minigames.S[key] or 0
        local interval = minigames.S.cleanupSummaryLogIntervalMs or 300000
        if last == 0 or now - last >= interval then
            minigames.S[key] = now
            return true
        end
    end
    return false
end

function minigames.LogCleanupStatus(message, deleted, failed, attempted, reason)
    minigames.S.lastVehicleCleanupStatus = tostring(message)
    if minigames.ShouldLogCleanupStatus and minigames.ShouldLogCleanupStatus(deleted, failed, attempted, reason) then
        minigames.LogInfo(message)
    end
end


------------------------------------------------------------
-- v0.078 hud text / interactive panel helpers
------------------------------------------------------------

function minigames.DrawTextLeft(text, x, y, size, r, g, b, a, font)
    if not HUD then
        return
    end

    direct_call(function()
        if HUD.SET_TEXT_FONT then
            HUD.SET_TEXT_FONT(font or 4)
        end

        if HUD.SET_TEXT_SCALE then
            HUD.SET_TEXT_SCALE(0.0, size + 0.0)
        end

        if HUD.SET_TEXT_COLOUR then
            HUD.SET_TEXT_COLOUR(r or 255, g or 255, b or 255, a or 255)
        end

        if HUD.SET_TEXT_CENTRE then
            HUD.SET_TEXT_CENTRE(false)
        end

        if HUD.SET_TEXT_DROP_SHADOW then
            HUD.SET_TEXT_DROP_SHADOW()
        end

        if HUD.SET_TEXT_OUTLINE then
            HUD.SET_TEXT_OUTLINE()
        end

        if HUD.BEGIN_TEXT_COMMAND_DISPLAY_TEXT then
            HUD.BEGIN_TEXT_COMMAND_DISPLAY_TEXT("STRING")
        end

        if HUD.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME then
            HUD.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME(tostring(text))
        end

        if HUD.END_TEXT_COMMAND_DISPLAY_TEXT then
            HUD.END_TEXT_COMMAND_DISPLAY_TEXT(x + 0.0, y + 0.0)
        end
    end)
end

function minigames.GetCompactHudCharLimit()
    local width = (minigames.S and minigames.S.compactHudW) or 0.115
    local scale = (minigames.S and minigames.S.compactHudTextScale) or 0.200

    -- larger text means fewer chars. this is tuned for gta hud text.
    local chars = math.floor(width / math.max(0.00385 * (scale / 0.20), 0.0028))

    if chars < 8 then chars = 8 end
    if chars > 48 then chars = 48 end

    return chars
end

function minigames.FitHudText(text, reservedChars)
    text = tostring(text or "")
    reservedChars = tonumber(reservedChars or 0) or 0

    local maxLen = minigames.GetCompactHudCharLimit() - reservedChars

    if maxLen < 8 then
        maxLen = 8
    end

    if #text <= maxLen then
        return text
    end

    return string.sub(text, 1, maxLen - 1) .. "…"
end

function minigames.SetCompactHudWidth(width)
    width = tonumber(width or 0.115) or 0.115

    if width < 0.085 then width = 0.085 end
    if width > 0.320 then width = 0.320 end

    minigames.S.compactHudW = width
end

function minigames.ApplyBestCompactHudPreset()
    -- user-tested v0.078 baseline.
    minigames.S.compactHudX = 0.220
    minigames.S.compactHudY = 0.895
    minigames.S.compactHudW = 0.115
    minigames.S.compactHudAlpha = 70
    minigames.S.compactHudMaxLines = 11
    minigames.S.compactHudTextScale = 0.200
    minigames.S.compactHudHeaderScale = 0.205
end

function minigames.ApplyReadableCompactHudPreset()
    minigames.S.compactHudX = 0.220
    minigames.S.compactHudY = 0.895
    minigames.S.compactHudW = 0.145
    minigames.S.compactHudAlpha = 85
    minigames.S.compactHudMaxLines = 11
    minigames.S.compactHudTextScale = 0.185
    minigames.S.compactHudHeaderScale = 0.205
end

function minigames.ToggleCompactHudExpanded()
    minigames.S.compactHudExpanded = not (minigames.S.compactHudExpanded == true)

    if minigames.S.compactHudExpanded then
        minigames.S.compactHudMaxLines = 18
        minigames.S.compactHudW = math.max(minigames.S.compactHudW or 0.115, 0.165)
    else
        minigames.S.compactHudMaxLines = 11
        minigames.S.compactHudW = math.min(minigames.S.compactHudW or 0.115, 0.145)
    end
end


-- v0.078 override:
-- left-aligned compact hud, text uses full width, and button-like hints are visual only.
function minigames.DrawCompactMinigamesHud()
    if not minigames.S or minigames.S.compactHudEnabled == false then
        return
    end

    local lines = minigames.GetCompactHudLines()
    local x = minigames.S.compactHudX or 0.220
    local y = minigames.S.compactHudY or 0.895
    local width = minigames.S.compactHudW or 0.115
    local headerH = 0.024
    local lineH = 0.020
    local padding = 0.006
    local maxLines = minigames.S.compactHudMaxLines or 11

    while #lines > maxLines do
        table.remove(lines)
    end

    local height = headerH + (#lines * lineH) + (padding * 2.0)

    local left = x - (width / 2.0)
    local top = y - (height / 2.0)
    local textX = left + 0.006

    minigames.DrawRect(x, y, width, height, 0, 0, 0, minigames.S.compactHudAlpha or 70)
    minigames.DrawRect(x, top + (headerH / 2.0), width, headerH, 150, 25, 35, 205)

    -- header stays centered-ish, body is left aligned.
    minigames.DrawText(minigames.FitHudText(minigames.CompactHudHeaderText and minigames.CompactHudHeaderText() or "MINIGAMES"), x, top + 0.0035, (minigames.S.compactHudHeaderScale or 0.205), 255, 255, 255, 238, 7)

    local startY = top + headerH + 0.004

    for i, line in ipairs(lines) do
        minigames.DrawTextLeft(minigames.FitHudText(tostring(line)), textX, startY + ((i - 1) * lineH), (minigames.S.compactHudTextScale or 0.200), 235, 235, 235, 230, 4)
    end

    -- visual button row. these are not clickable in gta hud draw mode.
    -- real clickable controls are inside minigames > settings > interactive hud panel.
    if minigames.S.compactHudShowVisualButtons ~= false then
        local buttonY = top + height - 0.010
        local bw = 0.018
        minigames.DrawRect(left + 0.014, buttonY, bw, 0.014, 45, 45, 45, 120)
        minigames.DrawRect(left + 0.035, buttonY, bw, 0.014, 45, 45, 45, 120)
-- v0.121 removed hud +/- button draw:         mg.drawtext("-", left + 0.014, buttony - 0.008, 0.170, 255, 255, 255, 210, 7)
-- v0.121 removed hud +/- button draw:         mg.drawtext("+", left + 0.035, buttony - 0.008, 0.170, 255, 255, 255, 210, 7)
    end
end

function minigames.DrawMinigamesHud()
    minigames.DrawCompactMinigamesHud()
end


