function minigames.SetHudInteractionPreset(mode)
    mode = tonumber(mode or 1) or 1

    if mode < 1 then mode = 1 end
    if mode > 5 then mode = 5 end

    minigames.S.hudInteractionPreset = mode

    local names = {
        [1] = "Feature Buttons",
        [2] = "ImGui Buttons",
        [3] = "Small Buttons",
        [4] = "Selectable Rows",
        [5] = "Hybrid Compact Panel"
    }

    minigames.Toast("HUD Preset", "Selected: " .. tostring(names[mode] or mode), 3000)
    minigames.LogInfo("[HUD Preset] selected mode=" .. tostring(mode) .. " | " .. tostring(names[mode] or "Unknown"))
end

function minigames.GetHudInteractionPresetName()
