        [2] = "ImGui Buttons",
        [3] = "Small Buttons",
        [4] = "Selectable Rows",
        [5] = "Hybrid Compact Panel"
    }

    return names[mode] or "Unknown"
end

function minigames.HudActionSpawnAll()
    if minigames.WarGames and minigames.WarGames.SpawnCurrentVehicleToAll then
        minigames.WarGames.SpawnCurrentVehicleToAll("HUD Interaction Panel")
        return
    end

    if minigames.SpawnVehicleForAllPlayers then
        minigames.SpawnVehicleForAllPlayers("HUD Interaction Panel")
        return
    end

    if minigames.WarGames and minigames.WarGames.SpawnVehicleToAll then
        minigames.WarGames.SpawnVehicleToAll("HUD Interaction Panel")
        return
    end

    minigames.Toast("HUD Action", "Spawn all function not found.", 3500)
    minigames.LogError("[HUD Action] Spawn all function not found.")
end

function minigames.HudActionForceBounties()
    if minigames.WarGames and minigames.WarGames.ForceBountyAll then
        minigames.WarGames.ForceBountyAll("HUD Interaction Panel")
        return
    end

    if minigames.ForceBountyAll then
        minigames.ForceBountyAll("HUD Interaction Panel")
        return
    end

    if minigames.ApplyBountiesToAll then
        minigames.ApplyBountiesToAll("HUD Interaction Panel")
        return
    end

    minigames.Toast("HUD Action", "Force bounty all function not found.", 3500)
    minigames.LogError("[HUD Action] Force bounty all function not found.")
end

function minigames.HudActionCleanupVehicles()
    if minigames.CleanupDestroyedWarGamesVehicles then
        minigames.CleanupDestroyedWarGamesVehicles("HUD Interaction Panel")
        return
    end

    if minigames.CleanupWarGamesVehicles then
        minigames.CleanupWarGamesVehicles("HUD Interaction Panel")
        return
    end

    if minigames.ForceDeleteAllTrackedWarGamesVehicles then
        minigames.ForceDeleteAllTrackedWarGamesVehicles("HUD Interaction Panel")
        return
    end

    minigames.Toast("HUD Action", "Cleanup function not found.", 3500)
    minigames.LogError("[HUD Action] Cleanup function not found.")
end

function minigames.HudActionNextRound()
    if minigames.ForceNextVehicleRound then
        minigames.ForceNextVehicleRound("HUD Interaction Panel")
        return
    end

    if minigames.RollNextVehicleRound then
        minigames.RollNextVehicleRound("HUD Interaction Panel")
        return
    end

    if minigames.VehicleRoundTick then
        minigames.S.lastVehicleRoundChangeMs = 0
        minigames.VehicleRoundTick()
        return
    end

    minigames.Toast("HUD Action", "Next round function not found.", 3500)
    minigames.LogError("[HUD Action] Next round function not found.")
end

function minigames.HudActionToggleExpanded()
    if minigames.ToggleCompactHudExpanded then
        minigames.ToggleCompactHudExpanded()
        return
    end

    minigames.S.compactHudExpanded = not (minigames.S.compactHudExpanded == true)
    minigames.Toast("HUD", "Expanded=" .. tostring(minigames.S.compactHudExpanded), 2500)
end

function minigames.HudActionPrintStatus()
    if minigames.PrintDebug then
        minigames.PrintDebug()
    elseif minigames.PrintWarGamesDebug then
        minigames.PrintWarGamesDebug()
    else
        minigames.LogInfo("[HUD Action] Current minigame=" .. tostring(minigames.GetCurrentMinigameLabel and minigames.GetCurrentMinigameLabel() or "None"))
        minigames.Toast("HUD", "Printed simple status.", 2500)
    end
end


------------------------------------------------------------
-- v0.083 actual red hud render modes
------------------------------------------------------------
-- this controls the real red-banner minigames hud:
--
-- minigames
-- mode: ...
-- vehicle: ...
-- - prev + next
-- vehicles / cleared
-- players / session
--
-- mode 1 = native gta drawrect/drawtext hud, not clickable.
-- mode 2 = imgui.button red hud panel, clickable while menu accepts imgui input.
-- mode 3 = imgui.smallbutton compact red hud panel.
-- mode 4 = imgui.selectable row red hud panel.
-- mode 5 = hybrid red hud panel, recommended.
------------------------------------------------------------

function minigames.SetActualHudMode(mode)
    mode = tonumber(mode or 1) or 1

    if mode < 1 then mode = 1 end
    if mode > 5 then mode = 5 end

    minigames.S.actualHudMode = mode

    local names = {
        [1] = "Native Draw HUD",
        [2] = "ImGui Button HUD",
        [3] = "ImGui SmallButton HUD",
        [4] = "ImGui Selectable HUD",
        [5] = "Hybrid Clickable HUD"
    }

    minigames.Toast("Actual HUD Mode", tostring(names[mode] or mode), 3000)
    minigames.LogInfo("[Actual HUD Mode] selected=" .. tostring(mode) .. " | " .. tostring(names[mode] or "Unknown"))
end

function minigames.GetActualHudModeName()
    local mode = tonumber(minigames.S.actualHudMode or 1) or 1

    local names = {
        [1] = "Native Draw HUD",
        [2] = "ImGui Button HUD",
        [3] = "ImGui SmallButton HUD",
        [4] = "ImGui Selectable HUD",
        [5] = "Hybrid Clickable HUD"
    }

    return names[mode] or "Unknown"
end

function minigames.ActualHudPrevVehicle()
    if minigames.ForcePreviousVehicleRound then
        minigames.ForcePreviousVehicleRound("Actual Red HUD")
        return
    end

    if minigames.S then
        local vehicles = nil

        if minigames.WarGames and minigames.WarGames.Vehicles then
            vehicles = minigames.WarGames.Vehicles
        elseif minigames.WARGAMES_VEHICLES then
            vehicles = minigames.WARGAMES_VEHICLES
        elseif minigames.Vehicles then
            vehicles = minigames.Vehicles
        end

        if type(vehicles) == "table" and #vehicles > 0 then
            local index = tonumber(minigames.S.currentRoundVehicleIndex or minigames.S.selectedVehicleIndex or minigames.S.selectedMinigameVehicle or 1) or 1
            index = index - 1
            if index < 1 then index = #vehicles end

            minigames.S.currentRoundVehicleIndex = index
            minigames.S.selectedVehicleIndex = index
            minigames.S.selectedMinigameVehicle = index

            minigames.Toast("HUD Vehicle", "Previous: " .. tostring(minigames.GetVehicleRoundByOffset and minigames.GetVehicleRoundByOffset(0) or index), 2500)
            return
        end
    end

    minigames.Toast("HUD Vehicle", "Previous vehicle method not found.", 3000)
end

function minigames.ActualHudNextVehicle()
    if minigames.HudActionNextRound then
        minigames.HudActionNextRound()
        return
    end

    if minigames.ForceNextVehicleRound then
        minigames.ForceNextVehicleRound("Actual Red HUD")
        return
    end

    if minigames.S then
        local vehicles = nil

        if minigames.WarGames and minigames.WarGames.Vehicles then
            vehicles = minigames.WarGames.Vehicles
        elseif minigames.WARGAMES_VEHICLES then
            vehicles = minigames.WARGAMES_VEHICLES
        elseif minigames.Vehicles then
            vehicles = minigames.Vehicles
        end

        if type(vehicles) == "table" and #vehicles > 0 then
            local index = tonumber(minigames.S.currentRoundVehicleIndex or minigames.S.selectedVehicleIndex or minigames.S.selectedMinigameVehicle or 1) or 1
            index = index + 1
            if index > #vehicles then index = 1 end

            minigames.S.currentRoundVehicleIndex = index
            minigames.S.selectedVehicleIndex = index
            minigames.S.selectedMinigameVehicle = index

            minigames.Toast("HUD Vehicle", "Next: " .. tostring(minigames.GetVehicleRoundByOffset and minigames.GetVehicleRoundByOffset(0) or index), 2500)
            return
        end
    end

    minigames.Toast("HUD Vehicle", "Next vehicle method not found.", 3000)
end

