    if mode == 1 then
        if minigames.DrawCompactMinigamesHud_NativeOriginal then
            minigames.DrawCompactMinigamesHud_NativeOriginal()
        end
    elseif mode == 2 then
        minigames.RenderActualHudImguiButtons()
    elseif mode == 3 then
