-- - clickable controls live in cherax menu tabs only.
-- - any old actual hud mode button now silently falls back to native.
------------------------------------------------------------

function minigames.SafeHudLogOnce(msg)
    minigames.S = minigames.S or {}
    if minigames.S.safeHudNoticeLogged == true then
        return
    end
    minigames.S.safeHudNoticeLogged = true
    minigames.LogInfo(tostring(msg))
end

function minigames.ApplyFinalNativeHudDefaults()
    minigames.S = minigames.S or {}
    minigames.S.actualHudMode = 1
    minigames.S.compactHudEnabled = true
    minigames.S.hudMenuPanelEnabled = true
    minigames.S.compactHudShowVisualButtons = true

    -- user-tested visual baseline.
    minigames.S.compactHudX = minigames.S.compactHudX or 0.220
    minigames.S.compactHudY = minigames.S.compactHudY or 0.895
    minigames.S.compactHudW = minigames.S.compactHudW or 0.115
    minigames.S.compactHudTextScale = minigames.S.compactHudTextScale or 0.200
    minigames.S.compactHudAlpha = minigames.S.compactHudAlpha or 70
    minigames.S.compactHudMaxLines = minigames.S.compactHudMaxLines or 11
end

function minigames.SetActualHudMode(mode)
