------------------------------------------------------------
-- v0.092 final clean hud layer
------------------------------------------------------------
-- final alpha rules:
-- 1. hud only shows when a minigame is active.
-- 2. red hud is visual-only native draw.
-- 3. clickable controls live in cherax menu.
-- 4. player list is limited to 3.
-- 5. hud is bottom-anchored and expands upward.
------------------------------------------------------------

function minigames.IsAnyMinigameActive()
    if minigames.S == nil then
        return false
    end

    if minigames.S.wargamesActive == true then return true end
    if minigames.S.warGamesActive == true then return true end
    if minigames.S.landOnItActive == true then return true end
    if minigames.S.currentMinigame ~= nil and minigames.S.currentMinigame ~= "" and minigames.S.currentMinigame ~= "None" then return true end

    if minigames.WarGames and minigames.WarGames.S and minigames.WarGames.S.active == true then return true end
    if minigames.LandOnIt and minigames.LandOnIt.S and minigames.LandOnIt.S.active == true then return true end

    return false
end

function minigames.GetCurrentMinigameLabel()
    if minigames.S then
        if minigames.S.currentMinigame and minigames.S.currentMinigame ~= "" and minigames.S.currentMinigame ~= "None" then
            return tostring(minigames.S.currentMinigame)
        end

        if minigames.S.wargamesActive == true or minigames.S.warGamesActive == true then
            return "WarGames"
        end

        if minigames.S.landOnItActive == true then
            return "Land On It"
        end
    end

    if minigames.WarGames and minigames.WarGames.S and minigames.WarGames.S.active == true then
        return "WarGames"
    end

    if minigames.LandOnIt and minigames.LandOnIt.S and minigames.LandOnIt.S.active == true then
        return "Land On It"
    end

    return "None"
end

function minigames.GetHudPlayerRows(maxCount)
    maxCount = tonumber(maxCount or 3) or 3

    local rows = {}

    local candidates = {}

    if minigames.S and type(minigames.S.activePlayers) == "table" then
        candidates = minigames.S.activePlayers
    elseif minigames.GetActivePlayers then
        local ok, result = direct_call(function()
            return minigames.GetActivePlayers()
        end)

        if ok and type(result) == "table" then
            candidates = result
        end
    end

    if type(candidates) ~= "table" then
        candidates = {}
    end

    -- if activeplayers is array-like.
    for _, value in pairs(candidates) do
        if #rows >= maxCount then break end

        local playerId = nil
        local name = nil

        if type(value) == "table" then
            playerId = value.id or value.playerId or value.index
            name = value.name
        else
            playerId = value
        end

        if not name and minigames.GetPlayerName and playerId ~= nil then
            name = minigames.GetPlayerName(playerId)
        end

        if name == nil then
            name = tostring(playerId or "Player")
        end

        local joinedMs = 0
        if minigames.S and minigames.S.playerJoinMs and playerId ~= nil then
            joinedMs = tonumber(minigames.S.playerJoinMs[playerId] or 0) or 0
        end

        local duration = 0
        if joinedMs > 0 and minigames.Now then
            duration = math.max(0, minigames.Now() - joinedMs)
        end

        table.insert(rows, {
            id = playerId,
            name = tostring(name),
            durationMs = duration
        })
    end

    -- fallback to local player if no rows.
    if #rows == 0 then
        local id = 0
        if minigames.GetLocalPlayerId then
            local ok, result = direct_call(function()
                return minigames.GetLocalPlayerId()
            end)
            if ok and result ~= nil then id = result end
        end

        local name = "Player"
        if minigames.GetPlayerName then
            local ok, result = direct_call(function()
                return minigames.GetPlayerName(id)
            end)
            if ok and result then name = result end
        end

        table.insert(rows, { id = id, name = tostring(name), durationMs = 0 })
    end

    return rows
end

function minigames.FormatHudDuration(ms)
    ms = tonumber(ms or 0) or 0
    local total = math.floor(ms / 1000)

    local h = math.floor(total / 3600)
    local m = math.floor((total % 3600) / 60)
    local s = total % 60

    if h > 0 then
        return string.format("%02d:%02d:%02d", h, m, s)
    end

    return string.format("%02d:%02d", m, s)
end

function minigames.GetCompactHudLines()
    local lines = {}

    local mode = minigames.GetCurrentMinigameLabel()
    local vehicle = "None"

    if minigames.GetVehicleRoundByOffset then
        vehicle = tostring(minigames.GetVehicleRoundByOffset(0) or "None")
    elseif minigames.S and minigames.S.currentVehicleLabel then
        vehicle = tostring(minigames.S.currentVehicleLabel)
    end

    local prevVehicle = "None"
    local nextVehicle = "None"

    if minigames.GetVehicleRoundByOffset then
        prevVehicle = tostring(minigames.GetVehicleRoundByOffset(-1) or "None")
        nextVehicle = tostring(minigames.GetVehicleRoundByOffset(1) or "None")
    end

    local tracked = 0
    local cleared = 0

    if minigames.GetTrackedVehicleCount then
        local ok, result = direct_call(minigames.GetTrackedVehicleCount)
        if ok and result ~= nil then tracked = result end
    end

    if minigames.GetClearedVehicleCount then
        local ok, result = direct_call(minigames.GetClearedVehicleCount)
        if ok and result ~= nil then cleared = result end
    elseif minigames.S and minigames.S.clearedVehicleCount then
        cleared = minigames.S.clearedVehicleCount
    end

    local playerRows = minigames.GetHudPlayerRows(3)

    table.insert(lines, minigames.FitHudText("Mode: " .. tostring(mode)))
    table.insert(lines, minigames.FitHudText("Vehicle: " .. tostring(vehicle)))
    table.insert(lines, minigames.FitHudText("- " .. tostring(prevVehicle) .. "  + " .. tostring(nextVehicle)))
    table.insert(lines, minigames.FitHudText(minigames.GetHudVehicleStatsText and minigames.GetHudVehicleStatsText() or ("Vehicles: " .. tostring(tracked) .. "  Cleared: " .. tostring(cleared))))
    table.insert(lines, minigames.FitHudText("Players: " .. tostring(#playerRows)))
    table.insert(lines, "Session:")

    for _, row in ipairs(playerRows) do
        table.insert(lines, minigames.FitHudText(tostring(row.name) .. ": " .. minigames.FormatHudDuration(row.durationMs)))
    end

    return lines
end

function minigames.DrawCompactMinigamesHud()
    if not minigames.S or minigames.S.compactHudEnabled == false then
        return
    end

    if minigames.S.hudOnlyWhenMinigameActive ~= false and not minigames.IsAnyMinigameActive() then
        return
    end

    local lines = minigames.GetCompactHudLines()
    local x = minigames.S.compactHudX or 0.220
    local bottomY = minigames.S.compactHudY or 0.895
    local width = minigames.S.compactHudW or 0.115
    local headerH = 0.024
    local lineH = 0.020
    local padding = 0.006
    local maxLines = minigames.S.compactHudMaxLines or 9

    while #lines > maxLines do
        table.remove(lines)
    end

    local height = headerH + (#lines * lineH) + (padding * 2.0)

    -- bottom anchored: more rows expand upward instead of pushing downward.
    local y = bottomY - (height / 2.0)
    local left = x - (width / 2.0)
    local top = y - (height / 2.0)
    local textX = left + 0.006

    minigames.DrawRect(x, y, width, height, 0, 0, 0, minigames.S.compactHudAlpha or 70)
    minigames.DrawRect(x, top + (headerH / 2.0), width, headerH, 150, 25, 35, 205)

    minigames.DrawText(minigames.FitHudText("MINIGAMES"), x, top + 0.0035, (minigames.S.compactHudHeaderScale or 0.205), 255, 255, 255, 238, 7)

    local startY = top + headerH + 0.004

    for i, line in ipairs(lines) do
        if minigames.DrawTextLeft then
            minigames.DrawTextLeft(minigames.FitHudText(tostring(line)), textX, startY + ((i - 1) * lineH), (minigames.S.compactHudTextScale or 0.200), 235, 235, 235, 230, 4)
        else
            minigames.DrawText(minigames.FitHudText(tostring(line)), x, startY + ((i - 1) * lineH), (minigames.S.compactHudTextScale or 0.200), 235, 235, 235, 230, 4)
        end
    end

    if minigames.S.compactHudShowVisualButtons ~= false then
        local buttonY = bottomY - 0.010
        local bw = 0.018
        minigames.DrawRect(left + 0.014, buttonY, bw, 0.014, 45, 45, 45, 120)
        minigames.DrawRect(left + 0.035, buttonY, bw, 0.014, 45, 45, 45, 120)
-- v0.121 removed hud +/- button draw:         mg.drawtext("-", left + 0.014, buttony - 0.008, 0.170, 255, 255, 255, 210, 7)
-- v0.121 removed hud +/- button draw:         mg.drawtext("+", left + 0.035, buttony - 0.008, 0.170, 255, 255, 255, 210, 7)
    end
end

function minigames.DrawMinigamesHud()
    minigames.DrawCompactMinigamesHud()
end

function minigames.ApplyFinalAlphaDefaults()
    minigames.S = minigames.S or {}

    minigames.S.actualHudMode = 1
    minigames.S.compactHudEnabled = true
    minigames.S.hudOnlyWhenMinigameActive = true
    minigames.S.compactHudMaxPlayers = 3
    minigames.S.compactHudMaxLines = 9
    minigames.S.compactHudX = minigames.S.compactHudX or 0.220
    minigames.S.compactHudY = minigames.S.compactHudY or 0.895
    minigames.S.compactHudW = minigames.S.compactHudW or 0.115
    minigames.S.compactHudTextScale = minigames.S.compactHudTextScale or 0.200
    minigames.S.compactHudAlpha = minigames.S.compactHudAlpha or 70
    minigames.S.hudMenuPanelEnabled = true
end


------------------------------------------------------------
-- v0.094 final hud active-state override
------------------------------------------------------------
function minigames.IsAnyMinigameActive()
    if minigames.S == nil then return false end

    if minigames.S.wargamesSystemsActive == true then return true end
    if minigames.S.wargamesActive == true then return true end
    if minigames.S.warGamesActive == true then return true end
    if minigames.S.wargamesNoBountyMode == true then return true end
    if minigames.S.landOnItActive == true then return true end
    if minigames.S.currentMinigame ~= nil and minigames.S.currentMinigame ~= "" and minigames.S.currentMinigame ~= "None" then return true end

    if minigames.WarGames and minigames.WarGames.S and minigames.WarGames.S.active == true then return true end
    if minigames.LandOnIt and minigames.LandOnIt.S and minigames.LandOnIt.S.active == true then return true end

    return false
end

function minigames.GetCurrentMinigameLabel()
    if minigames.S then
        if minigames.S.currentMinigame and minigames.S.currentMinigame ~= "" and minigames.S.currentMinigame ~= "None" then
            return tostring(minigames.S.currentMinigame)
        end

        if minigames.S.wargamesSystemsActive == true or minigames.S.wargamesActive == true or minigames.S.warGamesActive == true then
            if minigames.S.wargamesNoBountyMode == true then
                return "WarGames - No Bounties"
            end
            return "WarGames"
        end

        if minigames.S.landOnItActive == true then
            return "Land On It"
        end
    end

    return "None"
end


