function minigames.EnsurePlayerTables()
    minigames.Player = minigames.Player or {}

    minigames.Player.bountyTracked = minigames.Player.bountyTracked or {}
    minigames.Player.bountyTrackedAtMs = minigames.Player.bountyTrackedAtMs or {}
    minigames.Player.bountyMissing = minigames.Player.bountyMissing or {}

    minigames.Player.respawnEnabled = minigames.Player.respawnEnabled or {}
    minigames.Player.wasDead = minigames.Player.wasDead or {}
    minigames.Player.deathDetectedMs = minigames.Player.deathDetectedMs or {}
    minigames.Player.respawnReadyMs = minigames.Player.respawnReadyMs or {}
    minigames.Player.deathReason = minigames.Player.deathReason or {}
    minigames.Player.lastPedHandle = minigames.Player.lastPedHandle or {}
    minigames.Player.lastHealth = minigames.Player.lastHealth or {}

    minigames.Player.respawnCycleActive = minigames.Player.respawnCycleActive or {}
    minigames.Player.respawnVehicleSpawnedThisCycle = minigames.Player.respawnVehicleSpawnedThisCycle or {}
    minigames.Player.respawnVehicleSpawnedAtMs = minigames.Player.respawnVehicleSpawnedAtMs or {}
    minigames.Player.respawnSpawnLockUntilMs = minigames.Player.respawnSpawnLockUntilMs or {}
    minigames.Player.respawnDeathSerial = minigames.Player.respawnDeathSerial or {}
    minigames.Player.respawnLastSpawnDeathSerial = minigames.Player.respawnLastSpawnDeathSerial or {}

    minigames.Player.activeWarGamesVehicle = minigames.Player.activeWarGamesVehicle or {}

    return minigames.Player
end

function minigames.IsWarGamesBountyAllowed()
    if not minigames.S then return false end
    if minigames.S.wargamesNoBountyMode == true then return false end
    if minigames.S.autoBountyRunning == true then return true end
    if minigames.S.autoBountyEnabled == true then return true end
    if minigames.S.wargamesSystemsActive == true and minigames.S.wargamesNoBountyMode ~= true then return true end
    return false
end

minigames.EnsurePlayerTables()


------------------------------------------------------------
-- v0.120 final hud override: adaptive compact hud
------------------------------------------------------------
-- removes old hud clutter:
-- - session:
-- - player list rows
-- - +/- visual rows
-- - "" -- removed hud +/- row v0.121 previous/next row
--
-- hud now adapts by active minigame and shows live wargames stats.
------------------------------------------------------------

function minigames.HudSafeString(value, fallback)
    if value == nil then return fallback or "None" end
    local s = tostring(value)
    if s == "" or s == "nil" then return fallback or "None" end
    return s
end

function minigames.GetHudActivePlayerCount()
    if minigames.S and type(minigames.S.activePlayers) == "table" then
        return #minigames.S.activePlayers
    end

    if minigames.GetActivePlayers then
        local ok, list = direct_call(minigames.GetActivePlayers)
        if ok and type(list) == "table" then return #list end
    end

    return 0
end

function minigames.GetCurrentMinigameLabel()
    if minigames.S and minigames.S.activeMinigame and tostring(minigames.S.activeMinigame) ~= "" then
        return tostring(minigames.S.activeMinigame)
    end

    if minigames.LandOnIt and minigames.LandOnIt.S and minigames.LandOnIt.S.active == true then
        return "Land On It"
    end

    if minigames.S and (minigames.S.landOnItActive == true or minigames.S.landOnItRunning == true) then
        return "Land On It"
    end

    if minigames.S and (minigames.S.driftGodActive == true or minigames.S.driftGodRunning == true) then
        return "DriftGod"
    end

    if minigames.S and (minigames.S.beastActive == true or minigames.S.beastRunning == true) then
        return "Beast"
    end

    if minigames.S and (
        minigames.S.wargamesSystemsActive == true
        or minigames.S.wargamesNoBountyMode == true
        or minigames.S.wargamesNoBountiesActive == true
        or minigames.S.spawnVehicleOnPlayerRespawn == true
        or minigames.S.spawnVehiclesOnRespawn == true
        or minigames.S.respawnVehiclesOnPlayerRespawn == true
    ) then
        if minigames.S.noBountyMode == true or minigames.S.wargamesNoBountyMode == true or minigames.S.wargamesNoBountiesActive == true then
            return "WarGames - No Bounties"
        end
        return "WarGames"
    end

    return "None"
end

function minigames.GetHudVehiclePool()
    if minigames.WarGames and type(minigames.WarGames.VehiclePool) == "table" and #minigames.WarGames.VehiclePool > 0 then
        return minigames.WarGames.VehiclePool
    end
    if minigames.WarGames and type(minigames.WarGames.Vehicles) == "table" and #minigames.WarGames.Vehicles > 0 then
        return minigames.WarGames.Vehicles
    end
    if type(minigames.WARGAMES_VEHICLES) == "table" and #minigames.WARGAMES_VEHICLES > 0 then
        return minigames.WARGAMES_VEHICLES
    end
    if type(minigames.Vehicles) == "table" and #minigames.Vehicles > 0 then
        return minigames.Vehicles
    end
    return nil
end

function minigames.GetHudVehicleIndex()
    local pool = minigames.GetHudVehiclePool()
    if not pool or #pool <= 0 then return 1 end

    local index = 1
    if minigames.S then
        index = tonumber(
            minigames.S.roundVehicleIndex
            or minigames.S.currentRoundVehicleIndex
            or minigames.S.selectedVehicleIndex
            or minigames.S.selectedMinigameVehicle
            or minigames.S.currentVehicleIndex
            or 1
        ) or 1
    end

    if minigames.WarGames and minigames.WarGames.State and minigames.WarGames.State.selectedVehicleIndex then
        index = tonumber(minigames.WarGames.State.selectedVehicleIndex) or index
    end

    if index < 1 then index = 1 end
    if index > #pool then index = #pool end
    return index
end

function minigames.GetHudVehicleLabel(vehicle)
    if type(vehicle) ~= "table" then return tostring(vehicle or "None") end
    return tostring(vehicle.label or vehicle.name or vehicle.shortName or vehicle.model or "Unknown")
end

function minigames.GetVehicleRoundByOffset(offset)
    offset = tonumber(offset or 0) or 0

    if offset == 0 and minigames.WarGames and minigames.WarGames.GetCurrentVehicle then
        local ok, vehicle = direct_call(function() return minigames.WarGames.GetCurrentVehicle() end)
        if ok and vehicle then return minigames.GetHudVehicleLabel(vehicle) end
    end

    if offset == 0 and minigames.WarGames and minigames.WarGames.GetCurrentRoundVehicle then
        local ok, vehicle = direct_call(function() return minigames.WarGames.GetCurrentRoundVehicle() end)
        if ok and vehicle then return minigames.GetHudVehicleLabel(vehicle) end
    end

    local pool = minigames.GetHudVehiclePool()
    if not pool or #pool <= 0 then
        return minigames.S and (minigames.S.currentVehicleLabel or minigames.S.lastVehicleName) or "None"
    end

    local index = minigames.GetHudVehicleIndex()
    local resolved = ((index - 1 + offset) % #pool) + 1
    return minigames.GetHudVehicleLabel(pool[resolved])
end

function minigames.GetTrackedVehicleCount()
    local count = 0
    local candidates = {
        minigames.S and minigames.S.trackedVehicles,
        minigames.S and minigames.S.spawnedVehicles,
        minigames.S and minigames.S.wargamesVehicles,
        minigames.S and minigames.S.trackedWarGamesVehicles,
        minigames.WarGames and minigames.WarGames.S and minigames.WarGames.S.spawnedVehicles
    }

    for _, tbl in ipairs(candidates) do
        if type(tbl) == "table" then
            local c = 0
            for _, entry in pairs(tbl) do
                if entry then c = c + 1 end
            end
            if c > count then count = c end
        end
    end

    return count
end

function minigames.GetClearedVehicleCount()
    if not minigames.S then return 0 end

    local candidates = {
        minigames.S.totalVehiclesCleared,
        minigames.S.vehiclesCleared,
        minigames.S.vehiclesClearedTotal,
        minigames.S.destroyedVehicleCleanupCount,
        minigames.S.vehicleCleanupDeletedTotal,
        minigames.S.cleanedVehicleCount,
        minigames.S.clearedVehicleCount,
        minigames.S.cleanupDeletedCount,
        minigames.S.pedwarsCleanupStats and minigames.S.pedwarsCleanupStats.deleted,
    }

    local best = 0
    for _, value in ipairs(candidates) do
        if tonumber(value) and tonumber(value) > best then best = tonumber(value) end
    end
    return best
end

function minigames.GetAdaptiveLandOnItHudLines()
    local lines = {}
    table.insert(lines, minigames.FitHudText("Mode: Land On It"))
    local vehicle = "MK1 / Shamal"
    if minigames.LandOnIt and minigames.LandOnIt.S then
        vehicle = minigames.LandOnIt.S.selectedVehicle or minigames.LandOnIt.S.vehicle or vehicle
    end
    table.insert(lines, minigames.FitHudText("Vehicle: " .. tostring(vehicle)))
    if minigames.LandOnIt and minigames.LandOnIt.S and minigames.LandOnIt.S.target then
        table.insert(lines, minigames.FitHudText("Target: " .. tostring(minigames.LandOnIt.S.target)))
    else
        table.insert(lines, minigames.FitHudText("Target: Mall / Maze"))
    end
    table.insert(lines, minigames.FitHudText("Players: " .. tostring(minigames.GetHudActivePlayerCount())))
    return lines
end

function minigames.GetAdaptiveDriftGodHudLines()
    local lines = {}
    table.insert(lines, minigames.FitHudText("Mode: DriftGod"))
    table.insert(lines, minigames.FitHudText("Score: " .. tostring((minigames.S and minigames.S.driftScore) or 0)))
    table.insert(lines, minigames.FitHudText("Best: " .. tostring((minigames.S and minigames.S.driftBestScore) or 0)))
    table.insert(lines, minigames.FitHudText("Players: " .. tostring(minigames.GetHudActivePlayerCount())))
    return lines
end

function minigames.GetAdaptiveBeastHudLines()
    local lines = {}
    table.insert(lines, minigames.FitHudText("Mode: Beast"))
    if minigames.S and minigames.S.beastPlayer then
        table.insert(lines, minigames.FitHudText("Beast: " .. tostring(minigames.S.beastPlayer)))
    end
    table.insert(lines, minigames.FitHudText("Players: " .. tostring(minigames.GetHudActivePlayerCount())))
    return lines
end

function minigames.GetAdaptiveWarGamesHudLines(mode)
    local lines = {}
    table.insert(lines, minigames.FitHudText("Mode: " .. tostring(mode or "WarGames")))
    table.insert(lines, minigames.FitHudText("Vehicle: " .. tostring(minigames.GetVehicleRoundByOffset(0))))

    -- optional next vehicle line. no old "" -- removed hud +/- row v0.121 decorator row.
    if minigames.S and minigames.S.hudShowNextVehicle == true then
        table.insert(lines, minigames.FitHudText("Next: " .. tostring(minigames.GetVehicleRoundByOffset(1))))
    end

    table.insert(lines, minigames.FitHudText(minigames.GetHudVehicleStatsText and minigames.GetHudVehicleStatsText() or ("Vehicles: " .. tostring(minigames.GetTrackedVehicleCount()) .. "  Cleared: " .. tostring(minigames.GetClearedVehicleCount()))))
    table.insert(lines, minigames.FitHudText("Players: " .. tostring(minigames.GetHudActivePlayerCount())))

    if minigames.S and minigames.S.hudShowRespawnStatus == true and minigames.S.lastRespawnStatus then
        table.insert(lines, minigames.FitHudText("Respawn: " .. tostring(minigames.S.lastRespawnStatus)))
    end

    return lines
end

function minigames.GetCompactHudLines()
    local mode = minigames.GetCurrentMinigameLabel()

    if minigames.S and type(minigames.S.activeMinigameHudLines) == "table" then
        local lines = {}
        for _, line in ipairs(minigames.S.activeMinigameHudLines) do
            table.insert(lines, minigames.FitHudText(tostring(line)))
        end
        return lines
    end

    if mode == "None" then
        return { minigames.FitHudText("Mode: None") }
    end

    if mode == "Land On It" then
        return minigames.GetAdaptiveLandOnItHudLines()
    end

    if mode == "DriftGod" then
        return minigames.GetAdaptiveDriftGodHudLines()
    end

    if mode == "Beast" then
        return minigames.GetAdaptiveBeastHudLines()
    end

    if tostring(mode):find("WarGames") then
        return minigames.GetAdaptiveWarGamesHudLines(mode)
    end

    return {
        minigames.FitHudText("Mode: " .. tostring(mode)),
        minigames.FitHudText("Players: " .. tostring(minigames.GetHudActivePlayerCount()))
    }
end

function minigames.GetMinigameHudLines()
    return minigames.GetCompactHudLines()
end

function minigames.CompactHudHeaderText()
    return "MINIGAMES"
end

-- disable old decorative/session rows globally.
if minigames.S then
    minigames.S.hudShowSessionPlayers = false
    minigames.S.hudShowPlusMinusButtons = false
    minigames.S.hudShowPrevNextDecorators = false
    minigames.S.hudMaxPlayerNames = 0
    minigames.S.hudMaxPlayerRows = 0
end

------------------------------------------------------------
-- v0.129 direct fix: hud reads spawnedwargamesvehicles
------------------------------------------------------------
-- important:
-- the real raw spawn tracker writes to mg.s.spawnedwargamesvehicles.
-- previous hud bridges forgot that exact table name, so ids logged correctly
-- while vehicles still displayed 0.
------------------------------------------------------------

function minigames.CountWarGamesTrackedVehicleTables()
    local S = minigames.S or {}
    local WG = minigames.WarGames or {}
    local WGS = WG.S or {}

    local tables = {
        S.spawnedWarGamesVehicles,        -- real table used by registerwargamesvehicle()
        S.spawnedWarGamesVehicleRecords,
        S.trackedWarGamesVehicles,
        S.warGamesTrackedVehicles,
        S.wargamesTrackedVehicles,
        S.spawnedVehicles,
        S.respawnVehicles,
        S.respawnTrackedVehicles,
        S.playerRespawnVehicles,
        S.vehicleTrackingById,
        S.trackedVehicles,
        WG.spawnedWarGamesVehicles,
        WG.spawnedVehicles,
        WG.trackedVehicles,
        WGS.spawnedWarGamesVehicles,
        WGS.spawnedVehicles,
        WGS.trackedVehicles,
    }

    local bestActive = 0
    local bestRaw = 0
    local missing = 0
    local deleted = 0

    local function exists(entity)
        if entity == nil or entity == 0 then return false end
        if ENTITY and ENTITY.DOES_ENTITY_EXIST then
            local ok, result = direct_call(function()
                return ENTITY.DOES_ENTITY_EXIST(entity)
            end)
            return ok and result == true
        end
        return true
    end

    for _, tbl in ipairs(tables) do
        if type(tbl) == "table" then
            local active = 0
            local raw = 0
            local tblMissing = 0
            local tblDeleted = 0

            for _, entry in pairs(tbl) do
                if entry ~= nil then
                    raw = raw + 1

                    if type(entry) == "table" then
                        if entry.deleted == true or entry.cleared == true then
                            tblDeleted = tblDeleted + 1
                        else
                            local entity = entry.entity or entry.handle or entry.vehicle or entry.veh or entry.vehicleHandle
                            if entity == nil then
                                active = active + 1
                            elseif exists(entity) then
                                active = active + 1
                            else
                                tblMissing = tblMissing + 1
                            end
                        end
                    else
                        if exists(entry) then
                            active = active + 1
                        else
                            tblMissing = tblMissing + 1
                        end
                    end
                end
            end

            if raw > bestRaw then bestRaw = raw end
            if active > bestActive then bestActive = active end
            if tblMissing > missing then missing = tblMissing end
            if tblDeleted > deleted then deleted = tblDeleted end
        end
    end

    -- prefer active, but if entity checks fail/aren't available, show raw so hud doesn't lie at 0.
    local visibleActive = bestActive
    if visibleActive <= 0 and bestRaw > 0 then
        visibleActive = bestRaw - deleted
    end
    if visibleActive < 0 then visibleActive = 0 end

    local cleared = math.max(
        tonumber(S.vehiclesCleared or 0) or 0,
        tonumber(S.vehicleClearedCount or 0) or 0,
        tonumber(S.totalVehiclesCleared or 0) or 0,
        tonumber(S.deletedWarGamesVehicleCount or 0) or 0,
        tonumber(S.cleanedVehicleCount or 0) or 0,
        tonumber(S.cleanupDeletedCount or 0) or 0,
        missing,
        deleted
    )

    S.hudVehiclesCount = visibleActive
    S.hudClearedVehiclesCount = cleared
    S.vehiclesTrackedHud = visibleActive
    S.vehiclesClearedHud = cleared
    S.lastHudVehicleCounterStatus =
        "active=" .. tostring(visibleActive) ..
        " raw=" .. tostring(bestRaw) ..
        " missing=" .. tostring(missing) ..
        " deleted=" .. tostring(deleted) ..
        " cleared=" .. tostring(cleared)

    return visibleActive, cleared, bestRaw, missing, deleted
end

function minigames.GetTrackedVehicleCount()
    local active = select(1, minigames.CountWarGamesTrackedVehicleTables())
    return tonumber(active or 0) or 0
end

function minigames.GetClearedVehicleCount()
    local cleared = select(2, minigames.CountWarGamesTrackedVehicleTables())
    return tonumber(cleared or 0) or 0
end

function minigames.GetHudVehicleStatsText()
    return "Vehicles: " .. tostring(minigames.GetTrackedVehicleCount()) .. "  Cleared: " .. tostring(minigames.GetClearedVehicleCount())
end

if minigames.HUD then
    function minigames.HUD.GetTrackedVehicleCount()
        return minigames.GetTrackedVehicleCount()
    end

    function minigames.HUD.GetClearedVehicleCount()
        return minigames.GetClearedVehicleCount()
    end
end


------------------------------------------------------------
-- v0.137 wargames log filter wrapper
------------------------------------------------------------
-- this keeps errors visible but hides wargames heartbeat / round spam by default.
-- it wraps mg.loginfo once and preserves mg.loginfounfiltered for important startup/debug lines.
if minigames.LogInfo and minigames.__v137LogFilterInstalled ~= true then
    minigames.__v137LogFilterInstalled = true
    minigames.LogInfoUnfiltered = minigames.LogInfoUnfiltered or minigames.LogInfo

    local __mg137_original_log_info = minigames.LogInfo

    minigames.LogInfo = function(message)
        local msg = tostring(message or "")

        if minigames.Debug and minigames.Debug.ShouldPrintWarGamesLogV137 then
            local shouldPrint, channel = minigames.Debug.ShouldPrintWarGamesLogV137(msg)

            if shouldPrint ~= true then
                minigames.S = minigames.S or {}
                minigames.S.suppressedWarGamesLogCount = (tonumber(minigames.S.suppressedWarGamesLogCount or 0) or 0) + 1
                minigames.S.lastSuppressedWarGamesLogChannel = channel
                minigames.S.lastSuppressedWarGamesLog = msg
                return
            end
        end

        return __mg137_original_log_info(message)
    end

    minigames.LogInfoUnfiltered("[WarGames Debug] Log filter wrapper installed.")
end


