function minigames.ShouldPrintLogV138(message)
    local channel = minigames.ClassifyLogV138(message)

    if channel == "details" then
        return true, channel
    end

    if channel == "error" then
        return minigames.S.wargamesDebugErrors == true, channel
    end

    if channel == "boot" then
        return minigames.S.wargamesDebugBoot == true, channel
    end

    if channel == "heartbeat" then
