    end

    return true, channel
end

if minigames.LogInfo and minigames.__v138ExpandedLogFilterInstalled ~= true then
    minigames.__v138ExpandedLogFilterInstalled = true

    -- preserve the real original logger as best as possible.
    minigames.LogInfoUnfiltered = minigames.LogInfoUnfiltered or minigames.LogInfo

