        end

        -- use the real logger for allowed messages.
        return __mg138_previous_log_info(message)
    end

    if minigames.LogInfoUnfiltered then
        minigames.LogInfoUnfiltered("[WarGames Debug] v0.138 expanded early filter installed.")
    end
end


