function minigames.ShouldPrintLogV140(message)
    local channel = minigames.ClassifyLogV140(message)

    if channel == "summary" then return true, channel end
    if channel == "error" then return minigames.S.wargamesDebugErrors == true, channel end

    -- master mute: all non-error/non-summary minigames/wargames operational logs are hidden.
    if minigames.S.wargamesMuteLogs == true then
        return false, channel == "normal" and "muted" or channel
    end

    if channel == "boot" then return minigames.S.wargamesDebugBoot == true, channel end
    if channel == "heartbeat" then return minigames.S.wargamesDebugHeartbeat == true, channel end
    if channel == "round" then return minigames.S.wargamesDebugRounds == true, channel end
    if channel == "vehicle" then return minigames.S.wargamesDebugVehicles == true, channel end
    if channel == "systemdump" then return minigames.S.wargamesDebugSystemDump == true, channel end
    if channel == "activation" then return minigames.S.wargamesDebugActivation == true, channel end
    if channel == "bounty" then return minigames.S.wargamesDebugBounty == true, channel end
    if channel == "respawnwatcher" then return minigames.S.wargamesDebugRespawnWatcher == true, channel end

    return true, channel
end

