    local function gatedLogV140(message)
        local shouldPrint, channel = minigames.ShouldPrintLogV140(message)
        if shouldPrint ~= true then
            minigames.S.suppressedWarGamesLogCount = (tonumber(minigames.S.suppressedWarGamesLogCount or 0) or 0) + 1
            minigames.S.lastSuppressedWarGamesLogChannel = channel
            minigames.S.lastSuppressedWarGamesLog = tostring(message or "")
            return
        end
        return minigames.TrueRawLogInfoV140(message)
    end

    minigames.LogInfo = gatedLogV140
    minigames.LogInfoUnfiltered = gatedLogV140
    minigames.RawLogInfoV139 = gatedLogV140
end

function minigames.ClassifyLogV139(message) return minigames.ClassifyLogV140(message) end
function minigames.ShouldPrintLogV139(message) return minigames.ShouldPrintLogV140(message) end
function minigames.ClassifyLogV138(message) return minigames.ClassifyLogV140(message) end
function minigames.ShouldPrintLogV138(message) return minigames.ShouldPrintLogV140(message) end

------------------------------------------------------------
-- cherax vehicle helper safety
------------------------------------------------------------
minigames.WarGames.CheraxVehicleHelperSpecsV140 = {
    { key = "vehicle_god_mode", name = "Vehicle God Mode", hashes = { 2317809390, 2236350100 } },
    { key = "auto_repair", name = "Auto Repair", hashes = { 2718601735 } },
    { key = "anti_missile_lock_on", name = "Anti Missile Lock On", hashes = { 1576032325 } },
}

function minigames.WarGames.SafeFeatureIsOnV140(feature)
    if not feature then return false end
    if feature.IsToggled then
        local ok, value = direct_call(function() return feature:IsToggled() end)
        if ok and value ~= nil then return value == true end
    end
    if feature.GetBoolValue then
        local ok, value = direct_call(function() return feature:GetBoolValue() end)
        if ok and value ~= nil then return value == true end
    end
    if feature.GetValue then
        local ok, value = direct_call(function() return feature:GetValue() end)
        if ok and value ~= nil then return value == true or value == 1 end
    end
    return false
end

function minigames.WarGames.FindCheraxFeatureV140(spec)
    if not FeatureMgr or not spec then return nil, "FeatureMgr unavailable" end

    if FeatureMgr.GetFeatureByName and spec.name then
        local ok, f = direct_call(function() return FeatureMgr.GetFeatureByName(spec.name) end)
        if ok and f then return f, "name:" .. spec.name end
    end

    for _, hash in ipairs(spec.hashes or {}) do
        if FeatureMgr.GetFeatureByHash then
            local ok, f = direct_call(function() return FeatureMgr.GetFeatureByHash(hash) end)
            if ok and f then return f, "hash:" .. tostring(hash) end
        end
        if FeatureMgr.GetFeature then
            local ok, f = direct_call(function() return FeatureMgr.GetFeature(hash) end)
            if ok and f then return f, "hash:" .. tostring(hash) end
        end
    end

    return nil, "not found"
end

function minigames.WarGames.SetCheraxFeatureV140(feature, value)
    if not feature then return false, "missing feature" end
    value = value == true

    local before = minigames.WarGames.SafeFeatureIsOnV140(feature)
    if before == value then return true, "already" end

    if feature.SetToggled then
        local ok = direct_call(function() feature:SetToggled(value) end)
        if ok and minigames.WarGames.SafeFeatureIsOnV140(feature) == value then return true, "SetToggled" end
    end

    if feature.SetBoolValue then
        local ok = direct_call(function() feature:SetBoolValue(value) end)
        if ok then direct_call(function() if feature.TriggerCallback then feature:TriggerCallback() end end) end
        if ok and minigames.WarGames.SafeFeatureIsOnV140(feature) == value then return true, "SetBoolValue" end
    end

    if feature.SetValue then
        local ok = direct_call(function() feature:SetValue(value) end)
        if ok then direct_call(function() if feature.TriggerCallback then feature:TriggerCallback() end end) end
        if ok and minigames.WarGames.SafeFeatureIsOnV140(feature) == value then return true, "SetValueBool" end

        ok = direct_call(function() feature:SetValue(value and 1 or 0) end)
        if ok then direct_call(function() if feature.TriggerCallback then feature:TriggerCallback() end end) end
        if ok and minigames.WarGames.SafeFeatureIsOnV140(feature) == value then return true, "SetValueInt" end
    end

    if feature.Toggle then
        local ok = direct_call(function() feature:Toggle(value) end)
        if ok and minigames.WarGames.SafeFeatureIsOnV140(feature) == value then return true, "Toggle(value)" end

        ok = direct_call(function() feature:Toggle() end)
        if ok and minigames.WarGames.SafeFeatureIsOnV140(feature) == value then return true, "Toggle()" end
    end

    return minigames.WarGames.SafeFeatureIsOnV140(feature) == value, "best_effort"
end

function minigames.WarGames.DisableCheraxVehicleHelpersV140(reason)
    if minigames.S.wargamesAutoDisableCheraxVehicleHelpers == false then return true end

    minigames.S.wgCheraxSafetyActive = true
    minigames.S.wgCheraxSafetyRestore = minigames.S.wgCheraxSafetyRestore or {}
    minigames.S.wgCheraxSafetyLastReason = tostring(reason or "WarGames active")

    local changed = 0
    local found = 0

    for _, spec in ipairs(minigames.WarGames.CheraxVehicleHelperSpecsV140 or {}) do
        local feature, source = minigames.WarGames.FindCheraxFeatureV140(spec)
        local wasOn = minigames.WarGames.SafeFeatureIsOnV140(feature)

        if feature then found = found + 1 end

        local record = minigames.S.wgCheraxSafetyRestore[spec.key]
        if not record then
            record = { name = spec.name, source = source, wasOn = wasOn, disabledByWarGames = false }
            minigames.S.wgCheraxSafetyRestore[spec.key] = record
        end

        if feature and wasOn then
            local ok, method = minigames.WarGames.SetCheraxFeatureV140(feature, false)
            if ok then
                record.disabledByWarGames = true
                record.method = method
                changed = changed + 1
            else
                record.error = method
            end
        end
    end

    minigames.S.lastCheraxVehicleHelperSafety =
        "active | found=" .. tostring(found) .. " disabled=" .. tostring(changed) .. " | reason=" .. tostring(reason or "WarGames active")
    return true
end

function minigames.WarGames.RestoreCheraxVehicleHelpersV140(reason)
    local restore = minigames.S.wgCheraxSafetyRestore or {}
    local restored = 0
    local attempted = 0

    for _, spec in ipairs(minigames.WarGames.CheraxVehicleHelperSpecsV140 or {}) do
        local record = restore[spec.key]
        if record and record.disabledByWarGames == true and record.wasOn == true then
            attempted = attempted + 1
            local feature = minigames.WarGames.FindCheraxFeatureV140(spec)
            if feature then
                local ok = minigames.WarGames.SetCheraxFeatureV140(feature, true)
                if ok then restored = restored + 1 end
            end
        end
    end

    minigames.S.wgCheraxSafetyActive = false
    minigames.S.wgCheraxSafetyRestore = {}
    minigames.S.lastCheraxVehicleHelperSafety =
        "restored | attempted=" .. tostring(attempted) .. " restored=" .. tostring(restored) .. " | reason=" .. tostring(reason or "WarGames off")
    return true
end

function minigames.WarGames.AreWarGamesMasterTogglesOnV140()
    local systems = false
    local noBounties = false

    if minigames.GetFeatureBool and minigames.H then
        systems = minigames.GetFeatureBool(minigames.H.WARGAMES_ACTIVATE_SYSTEMS, false) == true
        noBounties = minigames.GetFeatureBool(minigames.H.WARGAMES_ACTIVATE_SYSTEMS_NO_BOUNTIES, false) == true
    end

    return systems or noBounties or minigames.S.wargamesSystemsActive == true or minigames.S.wargamesNoBountyMode == true
end

function minigames.WarGames.SyncCheraxVehicleHelpersV140(reason, forceActive)
    local active = forceActive
    if active == nil then active = minigames.WarGames.AreWarGamesMasterTogglesOnV140() end

    if active then
        return minigames.WarGames.DisableCheraxVehicleHelpersV140(reason or "WarGames active")
    end

    if minigames.S.wgCheraxSafetyActive == true or minigames.S.wgCheraxSafetyRestore then
        return minigames.WarGames.RestoreCheraxVehicleHelpersV140(reason or "WarGames inactive")
    end

    return true
end


------------------------------------------------------------
-- v0.141 hard mute: wargames respawn heartbeat
------------------------------------------------------------
-- explicitly catches lines like:
-- [wargames respawn] heartbeat | players=15 | localid=0 | watched=15 ...
-- also catches compressed/truncated repeats ending with "(2)".
function minigames.IsMutedRespawnHeartbeatV141(message)
    local msg = tostring(message or ""):lower()

    if msg:find("%[wargames respawn%] heartbeat") then
        return true
    end

    if msg:find("wargames respawn") and msg:find("heartbeat") then
        return true
    end

    if msg:find("players=") and msg:find("localid=") and msg:find("watched=") and msg:find("spawnonrespawn=true") then
        return true
    end

    if msg:find("remoterespawn=true") and msg:find("watcher=true") and msg:find("errors=0") then
        return true
    end

    return false
end

local __mg141_old_should_print_log = minigames.ShouldPrintLogV139 or minigames.ShouldPrintLogV138 or minigames.ShouldPrintLogV137
function minigames.ShouldPrintLogV139(message)
    if minigames.S and minigames.S.muteWarGamesLogs ~= false then
        if minigames.IsMutedRespawnHeartbeatV141 and minigames.IsMutedRespawnHeartbeatV141(message) then
            minigames.S.suppressedWarGamesLogCount = (tonumber(minigames.S.suppressedWarGamesLogCount or 0) or 0) + 1
            minigames.S.lastSuppressedWarGamesLogChannel = "heartbeat"
            minigames.S.lastSuppressedWarGamesLog = tostring(message or "")
            return false, "heartbeat"
        end
    end

    if __mg141_old_should_print_log then
        return __mg141_old_should_print_log(message)
    end

    return true, "normal"
end

function minigames.ShouldPrintLogV138(message)
    return minigames.ShouldPrintLogV139(message)
end

function minigames.ShouldPrintLogV137(message)
    return minigames.ShouldPrintLogV139(message)
end

-- re-wrap the active logger so this patch applies even if older wrappers were already installed.
if minigames.LogInfo and minigames.__v141RespawnHeartbeatMuteInstalled ~= true then
    minigames.__v141RespawnHeartbeatMuteInstalled = true
    minigames.RawLogInfoV141 = minigames.RawLogInfoV139 or minigames.RawLogInfoV138 or minigames.LogInfoUnfiltered or minigames.LogInfo

    local function gatedLogV141(message)
        local shouldPrint, channel = minigames.ShouldPrintLogV139(message)

        if shouldPrint ~= true then
            minigames.S.suppressedWarGamesLogCount = (tonumber(minigames.S.suppressedWarGamesLogCount or 0) or 0) + 1
            minigames.S.lastSuppressedWarGamesLogChannel = channel
            minigames.S.lastSuppressedWarGamesLog = tostring(message or "")
            return
        end

        return minigames.RawLogInfoV141(message)
    end

    minigames.LogInfo = gatedLogV141
    minigames.LogInfoUnfiltered = gatedLogV141
end
end

