embedded_modules['LandOnIt\\remote_teleport.lua'] = function()
--[[
    minigames/landonit/remote_teleport.lua
    build: v0.171-alpha

    experimental cherax built-in remote teleport triggers.

    user note:
    - documentation appeared to expose:
      remote teleport -> send all to mall
      remote teleport -> send all to mt. chilliad
      teleport all to me
      send all to my waypoint

    this file tries those built-in feature names safely.
]]

minigames.LandOnIt = minigames.LandOnIt or {}

minigames.LandOnIt.RemoteTeleportFeatureNames = {
    SendAllToMazeBank = {
        "Send All to Maze Bank",
        "Send All To Maze Bank",
        "Remote Teleport: Send All to Maze Bank",
        "Remote Teleport - Send All to Maze Bank"
    },
    SendAllToChilliad = {
        "Send All to Mt. Chilliad",
        "Send All To Mt. Chilliad",
        "Send All to Mount Chilliad",
        "Send All To Mount Chilliad",
        "Remote Teleport: Send All to Mt. Chilliad",
        "Remote Teleport - Send All to Mt. Chilliad"
    },
    TeleportAllToMe = {
        "Teleport All To Me",
        "Teleport All to Me",
        "Remote Teleport: Teleport All To Me",
        "Remote Teleport - Teleport All To Me"
    },
    SendAllToWaypoint = {
        "Send All To My Waypoint",
        "Send All to My Waypoint",
        "Teleport All To My Waypoint",
        "Remote Teleport: Send All To My Waypoint",
        "Remote Teleport - Send All To My Waypoint"
    }
}

function minigames.LandOnIt.TriggerBuiltInRemoteTeleport(key)
    local names = minigames.LandOnIt.RemoteTeleportFeatureNames[key] or {}
    local lastErr = "none"

    for _, name in ipairs(names) do
        local okGet, feature = direct_call(function()
            return FeatureMgr.GetFeatureByName(name)
        end)

        if okGet and feature then
            local okTrigger, errTrigger = direct_call(function()
                feature:TriggerCallback()
            end)

            if okTrigger then
                minigames.LandOnIt.S.lastRemoteTeleportStatus = "Triggered built-in remote teleport: " .. tostring(name)
                minigames.Toast("Remote Teleport", minigames.LandOnIt.S.lastRemoteTeleportStatus, 5000)
                minigames.LogInfo("[Land On It] " .. minigames.LandOnIt.S.lastRemoteTeleportStatus)
                return true, name
            end

            lastErr = tostring(errTrigger)
        else
            lastErr = "feature not found: " .. tostring(name)
        end
    end

    minigames.LandOnIt.S.lastRemoteTeleportStatus =
        "Failed built-in remote teleport key=" ..
        tostring(key) ..
        " | lastErr=" ..
        tostring(lastErr)

    minigames.Toast("Remote Teleport Failed", minigames.LandOnIt.S.lastRemoteTeleportStatus, 6000)
    minigames.LogError("[Land On It] " .. minigames.LandOnIt.S.lastRemoteTeleportStatus)

    return false, lastErr
end

function minigames.LandOnIt.SearchRemoteTeleportFeatures()
    if not FeatureMgr or not FeatureMgr.SearchFeatures then
        minigames.Toast("Remote Teleport Search", "FeatureMgr.SearchFeatures unavailable.", 4000)
        return
    end

    local ok, results = direct_call(function()
        return FeatureMgr.SearchFeatures("Teleport")
    end)

    minigames.LogInfo("========== Remote Teleport Feature Search ==========")
    minigames.LogInfo("Search ok=" .. tostring(ok))

    if ok and type(results) == "table" then
        for i, feature in ipairs(results) do
            local name = "unknown"
            local hash = "unknown"
            local desc = ""

            direct_call(function()
                name = feature:GetName()
            end)

            direct_call(function()
                hash = feature:GetHash()
            end)

            direct_call(function()
                desc = feature:GetDescription()
            end)

            minigames.LogInfo("Result " .. tostring(i) .. " | hash=" .. tostring(hash) .. " | name=" .. tostring(name) .. " | desc=" .. tostring(desc))
        end
    end

    minigames.LogInfo("===================================================")
    minigames.Toast("Remote Teleport Search", "Printed teleport feature search to log.", 4000)
end
end

