function minigames.LandOnIt.RenderMain()
    if ClickGUI.BeginCustomChildWindow("Land On It - Main") then
        ClickGUI.RenderFeature(minigames.LandOnIt.H.ACTIVATE)
        ClickGUI.RenderFeature(minigames.LandOnIt.H.TP_RUNWAY)
        ClickGUI.RenderFeature(minigames.LandOnIt.H.SPAWN_MK1_ALL)
        ClickGUI.RenderFeature(minigames.LandOnIt.H.TP_MALL)
        ClickGUI.RenderFeature(minigames.LandOnIt.H.PRINT_DEBUG)

        if ImGui then
            ImGui.Text("Objective:")
            ImGui.Text("Land on Mall with the chosen vehicle.")
            ImGui.Text("")
            ImGui.Text("Personal reward note:")
            ImGui.Text("First 3 players to land on Mall with X vehicle get X dollars!")
            ImGui.Text("")
            ImGui.Text("Current focus: Oppressor MK1.")
            ImGui.Text("Shamal: manual host setup for now.")
            ImGui.Text("Last Status: " .. tostring(minigames.LandOnIt.S.lastStatus))
        end

        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.LandOnIt.RenderVehicles()
    if ClickGUI.BeginCustomChildWindow("Land On It - Vehicles") then
        ClickGUI.RenderFeature(minigames.LandOnIt.H.SPAWN_MK1_ALL)
        ClickGUI.RenderFeature(minigames.LandOnIt.H.SPAWN_SHAMAL_SELF)
        ClickGUI.RenderFeature(minigames.LandOnIt.H.DISABLE_MK1_WEAPONS)
        ClickGUI.RenderFeature(minigames.LandOnIt.H.RANDOM_COLORS)
        ClickGUI.RenderFeature(minigames.LandOnIt.H.TP_BEFORE_SPAWN)

        if ImGui then
            ImGui.Text("MK1 setup:")
            ImGui.Text("- Spawn in front of everyone by default")
            ImGui.Text("- Try weaponless")
            ImGui.Text("- Random matching colors")
            ImGui.Text("- LANDONIT plate")
            ImGui.Text("Last Spawn: " .. tostring(minigames.LandOnIt.S.lastSpawnStatus))
        end

        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.LandOnIt.RenderRemoteTeleport()
    if ClickGUI.BeginCustomChildWindow("Experimental Built-In Remote Teleport") then
        ClickGUI.RenderFeature(minigames.LandOnIt.H.REMOTE_MAZE)
        ClickGUI.RenderFeature(minigames.LandOnIt.H.REMOTE_CHILLIAD)
        ClickGUI.RenderFeature(minigames.LandOnIt.H.REMOTE_TO_ME)
        ClickGUI.RenderFeature(minigames.LandOnIt.H.REMOTE_WAYPOINT)
        ClickGUI.RenderFeature(minigames.LandOnIt.H.SEARCH_REMOTE_TP)

        if ImGui then
            ImGui.Text("These try Cherax built-in features by name.")
            ImGui.Text("If they fail, press Search Remote Teleport Features and send the log.")
            ImGui.Text("Last Remote TP: " .. tostring(minigames.LandOnIt.S.lastRemoteTeleportStatus))
        end

        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.LandOnIt.Render()
    if ImGui and ImGui.BeginTabBar then
        if ImGui.BeginTabBar("LandOnItTabs") then
            if ImGui.BeginTabItem("Main") then
                minigames.LandOnIt.RenderMain()
                ImGui.EndTabItem()
            end

            if ImGui.BeginTabItem("Vehicles") then
                minigames.LandOnIt.RenderVehicles()
                ImGui.EndTabItem()
            end

            if ImGui.BeginTabItem("Remote TP") then
                minigames.LandOnIt.RenderRemoteTeleport()
                ImGui.EndTabItem()
            end

            ImGui.EndTabBar()
        end
    else
        minigames.LandOnIt.RenderMain()
        minigames.LandOnIt.RenderVehicles()
        minigames.LandOnIt.RenderRemoteTeleport()
    end
end

