embedded_modules['LandOnIt\\vehicles.lua'] = function()
--[[
    minigames/landonit/vehicles.lua
    build: v0.171-alpha

    vehicles:
    - oppressor mk1: automatic spawn-to-everyone button.
    - shamal: manual load/spawn for now.
]]

minigames.LandOnIt = minigames.LandOnIt or {}

minigames.LandOnIt.Vehicles = {
    MK1 = {
        label = "Oppressor MK1",
        shortName = "OppressorMK1",
        model = "oppressor",
        plate = "LANDONIT"
    },
    SHAMAL = {
        label = "Shamal",
        shortName = "Shamal",
        model = "shamal",
        plate = "LANDONIT",
        manualOnly = true
    }
}

function minigames.LandOnIt.ApplyVehicleStyle(vehicleEntity, vehicleData)
    if not vehicleEntity or vehicleEntity == 0 then
        return
    end

    direct_call(function()
        if minigames.ApplyRawVehicleUpgrades then
            minigames.ApplyRawVehicleUpgrades(vehicleEntity)
        end
    end)

    direct_call(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT then
            VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT(vehicleEntity, tostring(vehicleData.plate or "LANDONIT"))
        end
    end)

    direct_call(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_LIVERY then
            VEHICLE.SET_VEHICLE_LIVERY(vehicleEntity, -1)
        end

        if VEHICLE and VEHICLE.SET_VEHICLE_MOD then
            VEHICLE.SET_VEHICLE_MOD(vehicleEntity, 48, -1, false)
        end
    end)

    if minigames.LandOnIt.S.randomizeColors ~= false then
        -- reuse wargames random rgb/hex-style styling if available.
        if minigames.ApplyRandomWarGamesColor then
            minigames.ApplyRandomWarGamesColor(vehicleEntity)
        end
    end

    if vehicleData.shortName == "OppressorMK1" and minigames.LandOnIt.S.disableMk1Weapons ~= false then
        local ped = 0

        if PLAYER and PLAYER.PLAYER_PED_ID then
            direct_call(function()
                ped = PLAYER.PLAYER_PED_ID()
            end)
        end

        direct_call(function()
            if minigames.DisableVehicleWeaponsExperimental then
                minigames.DisableVehicleWeaponsExperimental(vehicleEntity, ped)
            end
        end)
    end
end

function minigames.LandOnIt.SpawnVehicleForPlayer(playerId, vehicleData)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if not minigames.IsPlayerActive(playerId) then
        return false, "inactive"
    end

    if not GTA or not GTA.SpawnVehicle then
        return false, "GTA.SpawnVehicle missing"
    end

    local spawnCoords, heading, coordStatus = nil, 0.0, "none"

    -- only use runway grid when the setup teleport toggle is on. default is front-of-player spawn.
    if minigames.LandOnIt.S.teleportToRunwayBeforeSpawn == true then
        local location = minigames.LandOnIt.GetRunwayTeleport and minigames.LandOnIt.GetRunwayTeleport() or nil

        if location then
            local spacing = 8.0
            local gridWidth = 4
            local index = minigames.ClampInt(playerId or 0, 0, 31)
            local col = index % gridWidth
            local row = math.floor(index / gridWidth)
            local centeredCol = col - ((gridWidth - 1) / 2.0)

            spawnCoords = {
                x = tonumber(location.x) + centeredCol * spacing,
                y = tonumber(location.y) + row * spacing,
                z = tonumber(location.z) + 1.0
            }

            heading = tonumber(location.heading or 0.0) or 0.0
            coordStatus = "runway_grid"
        end
    end

    if not spawnCoords then
        spawnCoords, heading, coordStatus = minigames.GetSpawnCoordsInFront(playerId)
    end

    if not spawnCoords then
        return false, coordStatus or "coords_failed"
    end

    local veh = nil
    local okSpawn, errSpawn = direct_call(function()
        veh = GTA.SpawnVehicle(vehicleData.model, spawnCoords.x, spawnCoords.y, spawnCoords.z, heading, true, true)
    end)

    if not okSpawn or not veh or veh == 0 then
        return false, errSpawn or "spawn_failed"
    end

    direct_call(function()
        if ENTITY and ENTITY.SET_ENTITY_AS_MISSION_ENTITY then
            ENTITY.SET_ENTITY_AS_MISSION_ENTITY(veh, true, true)
        end

        if ENTITY and ENTITY.SET_ENTITY_HEADING then
            ENTITY.SET_ENTITY_HEADING(veh, heading)
        end

        if VEHICLE and VEHICLE.SET_VEHICLE_ENGINE_ON then
            VEHICLE.SET_VEHICLE_ENGINE_ON(veh, true, true, false)
        end

        if VEHICLE and VEHICLE.SET_VEHICLE_ON_GROUND_PROPERLY then
            VEHICLE.SET_VEHICLE_ON_GROUND_PROPERLY(veh, 5.0)
        end
    end)

    minigames.LandOnIt.ApplyVehicleStyle(veh, vehicleData)

    table.insert(minigames.LandOnIt.S.spawnedVehicles, {
        entity = veh,
        playerId = playerId,
        model = vehicleData.model,
        label = vehicleData.label,
        spawnedAtMs = minigames.Now()
    })

    minigames.LogInfo(
        "[Land On It] spawned " ..
        tostring(vehicleData.label) ..
        " for " ..
        minigames.GetPlayerName(playerId) ..
        " | coordStatus=" ..
        tostring(coordStatus)
    )

    return true, "spawned"
end

function minigames.LandOnIt.SpawnMk1OnEveryone()
    minigames.RefreshPlayers()

    local vehicle = minigames.LandOnIt.Vehicles.MK1
    local spawned = 0
    local failed = 0

    if minigames.LandOnIt.S.teleportToRunwayBeforeSpawn == true then
        minigames.LandOnIt.TeleportAllToRunway()
    end

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        local ok, status = minigames.LandOnIt.SpawnVehicleForPlayer(playerId, vehicle)

        if ok then
            spawned = spawned + 1
        else
            failed = failed + 1
            minigames.LogError("[Land On It] MK1 spawn failed for player=" .. tostring(playerId) .. " | " .. tostring(status))
        end
    end

    minigames.LandOnIt.S.lastSpawnStatus =
        "MK1 spawn all complete | default front-of-player | spawned=" ..
        tostring(spawned) ..
        " failed=" ..
        tostring(failed)

    minigames.Toast("Land On It", minigames.LandOnIt.S.lastSpawnStatus, 5000)
    minigames.LandOnIt.SetStatus(minigames.LandOnIt.S.lastSpawnStatus)
end

function minigames.LandOnIt.SpawnShamalOnSelf()
    local vehicle = minigames.LandOnIt.Vehicles.SHAMAL
    local playerId = minigames.GetLocalPlayerId()

    local ok, status = minigames.LandOnIt.SpawnVehicleForPlayer(playerId, vehicle)

    if ok then
        minigames.Toast("Land On It", "Shamal spawned for self.", 4000)
    else
        minigames.Toast("Land On It", "Shamal spawn failed: " .. tostring(status), 5000)
    end
end

function minigames.LandOnIt.PrintDebug()
    minigames.LogInfo("========== Land On It Debug ==========")
    minigames.LogInfo("Active: " .. tostring(minigames.LandOnIt.S.active))
    minigames.LogInfo("Selected Vehicle: " .. tostring(minigames.LandOnIt.S.selectedVehicle))
    minigames.LogInfo("Disable MK1 Weapons: " .. tostring(minigames.LandOnIt.S.disableMk1Weapons))
    minigames.LogInfo("Randomize Colors: " .. tostring(minigames.LandOnIt.S.randomizeColors))
    minigames.LogInfo("Teleport To Runway Before Spawn: " .. tostring(minigames.LandOnIt.S.teleportToRunwayBeforeSpawn))
    minigames.LogInfo("Last Status: " .. tostring(minigames.LandOnIt.S.lastStatus))
    minigames.LogInfo("Last Spawn Status: " .. tostring(minigames.LandOnIt.S.lastSpawnStatus))
    minigames.LogInfo("Last Teleport Status: " .. tostring(minigames.LandOnIt.S.lastTeleportStatus))
    minigames.LogInfo("Spawned Vehicles Tracked: " .. tostring(#(minigames.LandOnIt.S.spawnedVehicles or {})))
    minigames.LogInfo("Reward Note: " .. tostring(minigames.LandOnIt.S.rewardNote))
    minigames.LogInfo("======================================")
    minigames.Toast("Land On It", "Printed debug to log.", 3000)
end
end

