-- ============================================================
-- embedded module: startup.lua
-- ============================================================
embedded_modules['startup.lua'] = function()
if minigames.EnsurePlayerTables then minigames.EnsurePlayerTables() end
-- minigames/startup.lua

math.randomseed(os.time())

minigames.SafeMkdir(minigames.ROOT)
minigames.SafeMkdir(minigames.ASSETS_ROOT)
minigames.SafeMkdir(minigames.SYSTEMS_ROOT)
minigames.SafeMkdir(minigames.WARGAMES_ROOT)
minigames.SafeMkdir(minigames.WARGAMES_VEHICLES_ROOT)
minigames.SafeMkdir(minigames.DRIFTGOD_ROOT)
minigames.SafeMkdir(minigames.BEAST_ROOT)

minigames.S.nativeOK = minigames.BuildNatives()

minigames.ResetSharedSettings()
minigames.ResetSystemSettings()

for playerId = 0, 31 do
    minigames.InitPlayerState(playerId)
end

minigames.KnownPlayers = {}
minigames.ActiveSet = {}

if minigames.WarGames and minigames.WarGames.ResetState then
    minigames.WarGames.ResetState()
end

minigames.S.selectedPlayerId = minigames.GetLocalPlayerId()
minigames.S.selectedPlayerName = minigames.GetPlayerName(minigames.S.selectedPlayerId)

minigames.RefreshPlayers()

minigames.Toast("Minigames Loaded", minigames.VERSION .. " | Fair vehicle enforcement ready", 7000)

minigames.LogInfo("Loaded " .. minigames.VERSION)
minigames.LogInfo("Build Date: " .. minigames.BUILD_DATE)
minigames.LogInfo("Root: " .. tostring(minigames.ROOT))
minigames.LogInfo("WarGames JSON Folder: " .. tostring(minigames.WarGames.VehicleJsonDir))
minigames.LogInfo("v0.058: WarGames includes vehicle rounds + fair vehicle enforcement.")
minigames.LogInfo("Default auto bounty interval: 180000ms.")
minigames.LogInfo("Fair vehicle enforcement default: current round vehicle only.")
minigames.LogInfo("Default vehicle engine: RAW Model Spawn.")
minigames.LogInfo("Players found: " .. tostring(minigames.S.activePlayerCount) .. " via " .. tostring(minigames.S.lastPlayerDiscoveryMethod))

    -- v0.059 stable vehicle rounds / styling
    minigames.S.autoRandomVehicleRounds = false
    minigames.S.vehicleRoundTimeMs = 180000
    minigames.S.roundVehicleIndex = minigames.S.roundVehicleIndex or 1
    minigames.S.previousRoundVehicleIndex = minigames.S.previousRoundVehicleIndex or 1
    minigames.S.roundStartedAtMs = 0
    minigames.S.lastVehicleRoundTickMs = 0
    minigames.S.roundChangeNotifyEnabled = true
    minigames.S.suppressRoundToggleSpamToast = true
    minigames.S.autoSpawnNewRoundVehicleToAll = true
    minigames.S.deletePreviousVehicleTypeOnChange = true
    minigames.S.deleteAllInactiveRoundVehicles = true

    minigames.S.forceWarGamesPlate = true
    minigames.S.removeVehicleLiveries = true
    minigames.S.randomizeVehicleColors = true
