if minigames.WarGames then
    minigames.WarGames.__v113_original_spawn_vehicle_on_all = minigames.WarGames.SpawnVehicleOnAll

    function minigames.WarGames.SpawnVehicleOnAll(force, reason)
        local reasonText = tostring(reason or "")
        local allowedManual = force == true and reasonText:lower():find("manual") ~= nil

        if not allowedManual then
            minigames.S.lastVehicleStatus =
                "AUTO Spawn All BLOCKED by v0.113 final override | force=" ..
                tostring(force) ..
                " | reason=" ..
                reasonText

            minigames.LogInfo("[WarGames Vehicles] " .. minigames.S.lastVehicleStatus)
            return false, "blocked_v113_final_override"
        end

        minigames.LogInfo("[WarGames Vehicles] Manual Force Spawn All allowed by v0.113 override.")
        return minigames.WarGames.__v113_original_spawn_vehicle_on_all(true, "Manual Force Spawn All")
    end

    function minigames.WarGames.ForceSpawnVehicleOnAllManual()
        return minigames.WarGames.SpawnVehicleOnAll(true, "Manual Force Spawn All")
    end
end

------------------------------------------------------------
-- v0.113 final override: local respawn cooldown neutralizer
------------------------------------------------------------
-- older wrappers can still log v0.108 cooldown blocked. this makes the setting
-- zero at runtime and provides a final wrapper that avoids blocking local respawn.
------------------------------------------------------------

if minigames.SpawnVehicleForPlayer then
    minigames.__v113_original_spawn_vehicle_for_player = minigames.SpawnVehicleForPlayer

    function minigames.SpawnVehicleForPlayer(playerId, vehicle, force, reason)
        playerId = minigames.ClampInt(playerId or 0, 0, 31)

        minigames.S.localRespawnMinimumSpawnGapMs = 0
        minigames.S.respawnMinimumSpawnGapMs = 0

        local localId = 0
        if minigames.GetLocalPlayerId then
            local okLocal, result = direct_call(minigames.GetLocalPlayerId)
            if okLocal and tonumber(result) ~= nil then
                localId = minigames.ClampInt(result, 0, 31)
            end
        end

        local isLocal = playerId == 0 or playerId == localId
        local reasonText = tostring(reason or "")
        local isRespawn = reasonText:lower():find("respawn") ~= nil or reasonText:lower():find("death") ~= nil

        if isRespawn and isLocal then
            if minigames.DeleteTrackedVehiclesForPlayer then
                direct_call(minigames.DeleteTrackedVehiclesForPlayer, playerId, "v0.113 before local respawn")
                direct_call(minigames.DeleteTrackedVehiclesForPlayer, 0, "v0.113 before local respawn")
            end
        end

        return minigames.__v113_original_spawn_vehicle_for_player(playerId, vehicle, force, reason)
    end
end

