    minigames.LogInfo(
        "[v0.113 Status] autoSpawnAllBlocked=" ..
        tostring(minigames.S.disableAutomaticSpawnAll) ..
        " | remoteRespawn=" ..
        tostring(minigames.S.spawnRespawnVehiclesForRemotePlayers) ..
        " | trackedVehicles=" ..
        tostring(tracked) ..
        " | localRespawnGap=" ..
        tostring(minigames.S.localRespawnMinimumSpawnGapMs)
    )
end


