------------------------------------------------------------
-- v0.115 safe delete overrides
------------------------------------------------------------
-- the fatal stack pointed at entity mission/delete natives. these native crashes
-- cannot be saved by direct call, so automatic cleanup must not call them.
------------------------------------------------------------

minigames.__v115_original_DeleteVehicleEntity = minigames.DeleteVehicleEntity
function minigames.DeleteVehicleEntity(vehicleEntity, reason)
    if minigames.S.disableAutomaticVehicleHardDelete == true then
        minigames.S.lastVehicleCleanupStatus = "soft delete skipped hard native delete | entity=" .. tostring(vehicleEntity) .. " | reason=" .. tostring(reason or "auto")
        return false, "hard_delete_disabled_v115"
    end

    if minigames.__v115_original_DeleteVehicleEntity then
        return minigames.__v115_original_DeleteVehicleEntity(vehicleEntity)
    end

    return false, "missing_original_delete"
end

minigames.__v115_original_DeleteEntitySafe = minigames.DeleteEntitySafe
function minigames.DeleteEntitySafe(entity, reason)
    if minigames.S.disableAutomaticVehicleHardDelete == true then
        minigames.S.lastVehicleCleanupStatus = "soft delete skipped DeleteEntitySafe | entity=" .. tostring(entity) .. " | reason=" .. tostring(reason or "auto")
        return false, "hard_delete_disabled_v115"
    end

    if minigames.__v115_original_DeleteEntitySafe then
        return minigames.__v115_original_DeleteEntitySafe(entity, reason)
    end

    return false, "missing_original_delete_safe"
end

-- cleanup now only prunes missing/stale tracking records. it will not call delete_entity.
minigames.__v115_original_CleanupWarGamesVehicles = minigames.CleanupWarGamesVehicles
function minigames.CleanupWarGamesVehicles(force)
    if minigames.S.disableAutomaticVehicleHardDelete == true then
        minigames.S.spawnedWarGamesVehicles = minigames.S.spawnedWarGamesVehicles or {}
        minigames.S.trackedVehicles = minigames.S.trackedVehicles or {}

        local beforeSpawned = #minigames.S.spawnedWarGamesVehicles
        local kept = {}
        local missing = 0

        for _, record in ipairs(minigames.S.spawnedWarGamesVehicles) do
            local entity = record and record.entity or 0
            local exists = false
            if entity and entity ~= 0 and minigames.EntityExists then
                local okExists, result = direct_call(minigames.EntityExists, entity)
                exists = okExists and result == true
            end

            if exists then
                kept[#kept + 1] = record
            else
                missing = missing + 1
            end
        end

        minigames.S.spawnedWarGamesVehicles = kept

        -- conservative tracked table prune: remove only records whose entity no longer exists.
        local trackingBefore = 0
        local trackingAfter = 0
        if type(minigames.S.trackedVehicles) == "table" then
            for key, entry in pairs(minigames.S.trackedVehicles) do
                trackingBefore = trackingBefore + 1
                local entity = entry and (entry.entity or entry.handle or entry.vehicle) or 0
                local exists = false
                if entity and entity ~= 0 and minigames.EntityExists then
                    local okExists, result = direct_call(minigames.EntityExists, entity)
                    exists = okExists and result == true
                end
                if not exists then
                    minigames.S.trackedVehicles[key] = nil
                else
                    trackingAfter = trackingAfter + 1
                end
            end
        end

        minigames.S.lastVehicleCleanupStatus =
            "soft cleanup only | spawnedBefore=" .. tostring(beforeSpawned) ..
            " spawnedAfter=" .. tostring(#kept) ..
            " missing=" .. tostring(missing) ..
            " trackingBefore=" .. tostring(trackingBefore) ..
            " trackingAfter=" .. tostring(trackingAfter)

        -- keep old heartbeat parser happy.
        return "cleanup deleted=0 attempted=0 failed=0 destroyed=0 unusedExpired=0 keptUsed=0 keptYoung=0 keptLiveUnused=0 missing=" ..
            tostring(missing) ..
            " tracking=" ..
            tostring(trackingAfter) ..
            " mode=soft-no-delete"
    end

    if minigames.__v115_original_CleanupWarGamesVehicles then
        return minigames.__v115_original_CleanupWarGamesVehicles(force)
    end

    return "cleanup unavailable"
end

function minigames.VehicleCleanupTick()
    -- soft cleanup only, and much slower.
    local now = minigames.Now()
    local last = minigames.S.lastVehicleCleanupScanMs or 0
    local interval = minigames.S.vehicleCleanupScanMs or 180000

    if last ~= 0 and now - last < interval then
        return
    end

    minigames.S.lastVehicleCleanupScanMs = now
    minigames.CleanupWarGamesVehicles(false)
end

------------------------------------------------------------
-- v0.115 serialized respawn queue
------------------------------------------------------------
minigames.__v115_original_EnqueueRespawnVehicleSpawn = minigames.EnqueueRespawnVehicleSpawn

function minigames.EnqueueRespawnVehicleSpawn(playerId, vehicle, serial, reason)
    minigames.S = minigames.S or {}
    minigames.Player = minigames.Player or {}
    minigames.S.serialRespawnQueue = minigames.S.serialRespawnQueue or {}
    minigames.S.serialRespawnQueuedByPlayer = minigames.S.serialRespawnQueuedByPlayer or {}
    minigames.Player.respawnVehicleSpawnedAtMs = minigames.Player.respawnVehicleSpawnedAtMs or {}

    playerId = minigames.ClampInt(playerId or 0, 0, 31)
    serial = tonumber(serial or 0) or 0

    local now = minigames.Now()
    local lastPlayerSpawn = minigames.Player.respawnVehicleSpawnedAtMs[playerId] or 0
    local perPlayerGap = minigames.S.serialRespawnPerPlayerGapMs or 12000

    if lastPlayerSpawn ~= 0 and now - lastPlayerSpawn < perPlayerGap then
        minigames.S.lastRespawnStatus =
            "serial queue skipped by per-player gap | player=" ..
            tostring(playerId) ..
            " | name=" ..
            minigames.GetPlayerName(playerId)

        minigames.LogInfo("[Respawn Queue v0.115] " .. minigames.S.lastRespawnStatus)
        return false, "per_player_gap_v115"
    end

    if minigames.S.serialRespawnQueuedByPlayer[playerId] == serial then
        return false, "already_serial_queued"
    end

    if #minigames.S.serialRespawnQueue >= (minigames.S.serialRespawnMaxQueue or 10) then
        minigames.S.lastRespawnStatus =
            "serial queue full; skipped " ..
            minigames.GetPlayerName(playerId) ..
            " | queue=" ..
            tostring(#minigames.S.serialRespawnQueue)

        minigames.LogError("[Respawn Queue v0.115] " .. minigames.S.lastRespawnStatus)
        return false, "queue_full_v115"
    end

    minigames.S.serialRespawnQueuedByPlayer[playerId] = serial
    minigames.S.serialRespawnQueue[#minigames.S.serialRespawnQueue + 1] = {
        playerId = playerId,
        vehicle = vehicle,
        serial = serial,
        reason = reason or "Serialized Respawn Watcher",
        queuedAtMs = now
    }

    minigames.LogInfo(
        "[Respawn Queue v0.115] serial queued | player=" ..
        tostring(playerId) ..
        " | name=" ..
        minigames.GetPlayerName(playerId) ..
        " | serial=" ..
        tostring(serial) ..
        " | queue=" ..
        tostring(#minigames.S.serialRespawnQueue)
    )

    if minigames.WarGames and minigames.WarGames.StartSerialRespawnQueueWorker then
        minigames.WarGames.StartSerialRespawnQueueWorker()
    end

    return true, "serial_queued_v115"
end

function minigames.WarGames.StartSerialRespawnQueueWorker()
    minigames.S = minigames.S or {}

    if minigames.S.serialRespawnWorkerRunning == true then
        return true, "running"
    end

    minigames.S.serialRespawnWorkerRunning = true

    local function worker()
        minigames.LogInfo("[Respawn Queue v0.115] worker started")

        if Script and Script.Yield then
            Script.Yield(minigames.S.serialRespawnInitialDelayMs or 450)
        end

        while minigames.S and minigames.S.serialRespawnQueue and #minigames.S.serialRespawnQueue > 0 do
            local item = table.remove(minigames.S.serialRespawnQueue, 1)

            if item then
                local playerId = minigames.ClampInt(item.playerId or 0, 0, 31)
                local serial = tonumber(item.serial or 0) or 0
                minigames.S.serialRespawnQueuedByPlayer[playerId] = nil

                local okJob, errJob = direct_call_trace(function()
                    if not minigames.IsPlayerActive(playerId) then
                        minigames.LogInfo("[Respawn Queue v0.115] skipped inactive | player=" .. tostring(playerId))
                        return
                    end

                    local spawnVehicle = item.vehicle
                    if not spawnVehicle and minigames.WarGames and minigames.WarGames.ResolveVehicle then
                        spawnVehicle = minigames.WarGames.ResolveVehicle("Serialized Respawn Spawn")
                    end

                    if not spawnVehicle then
                        minigames.LogError("[Respawn Queue v0.115] vehicle=nil | player=" .. tostring(playerId))
                        return
                    end

                    -- do not delete previous remote vehicles here. hard delete was the crash source.
                    local okSpawn, status = minigames.SpawnVehicleForPlayer(playerId, spawnVehicle, true, item.reason or "Serialized Respawn Watcher")

                    if okSpawn then
                        local nowSpawn = minigames.Now()
                        minigames.Player.respawnVehicleSpawnedAtMs[playerId] = nowSpawn
                        minigames.S.lastRespawnStatus =
                            "Serialized spawn success for " ..
                            minigames.GetPlayerName(playerId) ..
                            " | serial=" ..
                            tostring(serial)

                        minigames.LogInfo("[Respawn Queue v0.115] SUCCESS | " .. minigames.S.lastRespawnStatus)
                    else
                        minigames.S.lastRespawnStatus =
                            "Serialized spawn failed for " ..
                            minigames.GetPlayerName(playerId) ..
                            " | " ..
                            tostring(status)

                        minigames.LogError("[Respawn Queue v0.115] FAILED | " .. minigames.S.lastRespawnStatus .. " | LastVehicleError=" .. tostring(minigames.S.lastVehicleError))
                    end
                end, debug and debug.traceback or function(e) return tostring(e) end)

                if not okJob then
                    minigames.LogError("[Respawn Queue v0.115] worker item error | " .. tostring(errJob))
                end
            end

            if Script and Script.Yield then
                Script.Yield(minigames.S.serialRespawnSpawnGapMs or 1400)
            else
                break
            end
        end

        minigames.S.serialRespawnWorkerRunning = false
        minigames.LogInfo("[Respawn Queue v0.115] worker stopped")
    end

    if Script and Script.QueueJob then
        local okQueue, errQueue = direct_call(function()
            Script.QueueJob(worker)
        end)

        if not okQueue then
            minigames.S.serialRespawnWorkerRunning = false
            minigames.LogError("[Respawn Queue v0.115] QueueJob failed: " .. tostring(errQueue))
            return false, "queuejob_failed"
        end

        return true, "queued"
    end

    minigames.S.serialRespawnWorkerRunning = false
    return false, "queuejob_missing"
end

------------------------------------------------------------
-- v0.115 safe bounty batch override
------------------------------------------------------------
-- avoid applying bounty to 21 players in one frame. the fatal log's last script
-- event was script_event_bounty_over, so bounties must be paced.
------------------------------------------------------------

minigames.__v115_original_AutoBountyTick = minigames.WarGames and minigames.WarGames.AutoBountyTick
function minigames.WarGames.AutoBountyTick()
    if minigames.S.wargamesNoBountyMode == true then
        return
    end

    if minigames.S.wargamesSystemsActive ~= true and minigames.S.autoBountyRunning ~= true and minigames.S.autoBountyEnabled ~= true then
        return
    end

    local now = minigames.Now()
    minigames.S.autoBountyIntervalMs = 180000
    minigames.S.bountyIntervalMs = 180000
    minigames.S.autoBountyMaintainIntervalMs = 180000
    minigames.S.bountyMaintenanceIntervalMs = 180000

    local lastTick = minigames.S.lastSafeBountyTickMs or 0
    if lastTick ~= 0 and now - lastTick < (minigames.S.safeBountyGapMs or 2500) then
        return
    end

    minigames.S.lastSafeBountyTickMs = now

    if minigames.RefreshPlayers then
        direct_call(minigames.RefreshPlayers)
    end

    minigames.S.safeBountyCursor = (minigames.S.safeBountyCursor or 0) + 1
    local players = minigames.S.activePlayers or {}
    if #players <= 0 then return end
    if minigames.S.safeBountyCursor > #players then minigames.S.safeBountyCursor = 1 end

    local playerId = players[minigames.S.safeBountyCursor]
    if playerId == nil then return end

    if minigames.S.skipSelfBounty and minigames.IsSelf and minigames.IsSelf(playerId) then
        minigames.S.lastBountyStatus = "Safe bounty skipped self"
        return
    end

    if minigames.IsBountyTracked and minigames.IsBountyTracked(playerId) then
        minigames.S.lastBountyStatus = "Safe bounty skipped tracked | player=" .. tostring(playerId)
        return
    end

    local ok, status = minigames.WarGames.ForceBountyOnPlayer(playerId, "Auto Safe Refresh 180s Serialized")

    minigames.S.lastBountyStatus =
        "Safe bounty serialized | player=" ..
        tostring(playerId) ..
        " | name=" ..
        minigames.GetPlayerName(playerId) ..
        " | ok=" ..
        tostring(ok) ..
        " | status=" ..
        tostring(status)

    minigames.WarGames.BountyLog(minigames.S.lastBountyStatus)
end

minigames.__v115_original_ForceBountyOnAllPlayers = minigames.WarGames and minigames.WarGames.ForceBountyOnAllPlayers
function minigames.WarGames.ForceBountyOnAllPlayers()
    minigames.LogInfo("[WarGames Bounty] v0.115 blocked instant ForceBountyOnAllPlayers; use serialized AutoBountyTick.")
    minigames.Toast("WarGames Bounty", "Instant bounty-all blocked for stability. Serialized bounty remains active.", 5000)
    return false, "blocked_v115_serial_only"
end

------------------------------------------------------------
-- v0.115 activation safety
------------------------------------------------------------
-- systems with bounties no longer performs an instant 21-player bounty burst.
------------------------------------------------------------
minigames.__v115_original_ActivateSystems = minigames.WarGames and minigames.WarGames.ActivateSystems
function minigames.WarGames.ActivateSystems()
    local result = true
    if minigames.__v115_original_ActivateSystems then
        local ok, err = direct_call_trace(function()
            result = minigames.__v115_original_ActivateSystems()
        end, debug and debug.traceback or function(e) return tostring(e) end)
        if not ok then
            minigames.LogError("[WarGames Systems v0.115] ActivateSystems inner error swallowed: " .. tostring(err))
        end
    end

    minigames.S.spawnRespawnVehiclesForRemotePlayers = true
    minigames.S.remoteRespawnVehiclesEnabled = true
    minigames.S.respawnWatcherRunning = true
    minigames.S.spawnVehiclesOnRespawn = true
    minigames.S.respawnVehiclesOnPlayerRespawn = true
    minigames.S.spawnVehicleOnPlayerRespawn = true

    -- keep bounties enabled, but prevent instant mass burst.
    minigames.S.autoBountyRunning = true
    minigames.S.autoBountyEnabled = true
    minigames.S.autoBountyNewPlayers = false
    minigames.S.lastAutoBountyTickMs = minigames.Now() -- prevents older immediate 180s batch after activation
    minigames.S.lastSafeBountyTickMs = 0

    -- delete/fair cleanup are disabled in this stability build.
    minigames.S.autoCleanupWarGamesVehicles = false
    minigames.S.autoFairVehicleEnforcement = false
    minigames.S.fairVehicleEnforcementEnabled = false

    minigames.LogInfo("[WarGames Systems v0.115] activated | remote respawns ON | bounties serialized | hard delete OFF")
    return result
end

-- final scheduler wrapper: enforce stability flags every tick before older code runs.
if minigames.Scheduler and minigames.Scheduler.Tick then
    minigames.__v115_original_scheduler_tick = minigames.Scheduler.Tick
    function minigames.Scheduler.Tick()
        minigames.S.disableAutomaticVehicleHardDelete = true
        minigames.S.autoCleanupWarGamesVehicles = false
        minigames.S.autoFairVehicleEnforcement = false
        minigames.S.fairVehicleEnforcementEnabled = false
        minigames.S.spawnRespawnVehiclesForRemotePlayers = true
        minigames.S.remoteRespawnVehiclesEnabled = true
        minigames.S.autoBountyIntervalMs = 180000
        minigames.S.bountyIntervalMs = 180000
        minigames.S.autoBountyMaintainIntervalMs = 180000
        minigames.S.bountyMaintenanceIntervalMs = 180000

        local ok, err = direct_call_trace(function()
            minigames.__v115_original_scheduler_tick()
        end, debug and debug.traceback or function(e) return tostring(e) end)

        if not ok then
            minigames.LogError("[Scheduler v0.115] swallowed scheduler error: " .. tostring(err))
        end
    end
end

minigames.PrintV115Status = function()
    local q = minigames.S.serialRespawnQueue and #minigames.S.serialRespawnQueue or 0
    local tracked = 0
    if type(minigames.S.trackedVehicles) == "table" then
        for _, _ in pairs(minigames.S.trackedVehicles) do tracked = tracked + 1 end
    end

    minigames.LogInfo(
        "[v0.115 Status] remoteRespawn=" .. tostring(minigames.S.spawnRespawnVehiclesForRemotePlayers) ..
        " | queue=" .. tostring(q) ..
        " | worker=" .. tostring(minigames.S.serialRespawnWorkerRunning) ..
        " | hardDeleteDisabled=" .. tostring(minigames.S.disableAutomaticVehicleHardDelete) ..
        " | autoCleanup=" .. tostring(minigames.S.autoCleanupWarGamesVehicles) ..
        " | tracked=" .. tostring(tracked) ..
        " | bountyInterval=" .. tostring(minigames.S.autoBountyIntervalMs)
    )
end


------------------------------------------------------------
-- v0.116 final override: respawn queue gap fix
------------------------------------------------------------
-- log-confirmed bug from v0.115:
--   respawn ready -> [respawn queue v0.115] serial queue skipped by per-player gap
-- this happened because queuerespawnspawnonce set respawnvehiclespawnedatms before
-- enqueuerespawnvehiclespawn ran. the enqueue check then blocked its own request.
------------------------------------------------------------

minigames.VERSION = "v0.183-alpha"
minigames.S.serialRespawnPerPlayerGapMs = 0
minigames.S.serialRespawnSpawnGapMs = 1400
minigames.S.serialRespawnInitialDelayMs = 250
minigames.S.serialRespawnMaxQueue = 32
minigames.S.spawnRespawnVehiclesForRemotePlayers = true
minigames.S.disableAutomaticHardDelete = true
minigames.S.disableAutomaticDeleteEntity = true
minigames.S.disableAutomaticSpawnAll = true
minigames.S.autoBountyIntervalMs = 180000
minigames.S.bountyIntervalMs = 180000
minigames.S.autoBountyMaintainIntervalMs = 180000
minigames.S.bountyMaintenanceIntervalMs = 180000

minigames.LogInfo("Loaded " .. script_version)
minigames.LogInfo("FINAL OVERRIDE ACTIVE: respawn queue per-player gap disabled; queue no longer blocks itself.")
minigames.LogInfo("Respawn queue: remote players ON, serialized spawns ON, automatic hard delete OFF.")

function minigames.ResetRespawnQueueGapState(reason)
    minigames.Player = minigames.Player or {}
    minigames.S = minigames.S or {}
    minigames.Player.respawnVehicleSpawnedAtMs = minigames.Player.respawnVehicleSpawnedAtMs or {}
    minigames.S.serialRespawnQueuedByPlayer = minigames.S.serialRespawnQueuedByPlayer or {}

    for i = 0, 31 do
        minigames.Player.respawnVehicleSpawnedAtMs[i] = 0
        minigames.S.serialRespawnQueuedByPlayer[i] = nil
    end

    minigames.LogInfo("[Respawn Queue v0.116] reset per-player gap state | reason=" .. tostring(reason or "manual"))
end

-- replace the v0.115 queue with a no-self-blocking queue.
minigames.__v116_original_EnqueueRespawnVehicleSpawn = minigames.EnqueueRespawnVehicleSpawn
function minigames.EnqueueRespawnVehicleSpawn(playerId, vehicle, serial, reason)
    minigames.S = minigames.S or {}
    minigames.Player = minigames.Player or {}
    minigames.S.serialRespawnQueue = minigames.S.serialRespawnQueue or {}
    minigames.S.serialRespawnQueuedByPlayer = minigames.S.serialRespawnQueuedByPlayer or {}
    minigames.Player.respawnVehicleSpawnedAtMs = minigames.Player.respawnVehicleSpawnedAtMs or {}

    playerId = minigames.ClampInt(playerId or 0, 0, 31)
    serial = tonumber(serial or 0) or 0

    -- only prevent the exact same player+serial from being queued twice.
    -- do not use respawnvehiclespawnedatms here; queuerespawnspawnonce may touch it.
    if minigames.S.serialRespawnQueuedByPlayer[playerId] == serial then
        return false, "already_serial_queued_v116"
    end

    if #minigames.S.serialRespawnQueue >= (minigames.S.serialRespawnMaxQueue or 32) then
        minigames.S.lastRespawnStatus =
            "serial queue full; skipped " .. minigames.GetPlayerName(playerId) ..
            " | queue=" .. tostring(#minigames.S.serialRespawnQueue)
        minigames.LogError("[Respawn Queue v0.116] " .. minigames.S.lastRespawnStatus)
        return false, "queue_full_v116"
    end

    minigames.S.serialRespawnQueuedByPlayer[playerId] = serial
    minigames.S.serialRespawnQueue[#minigames.S.serialRespawnQueue + 1] = {
        playerId = playerId,
        vehicle = vehicle,
        serial = serial,
        reason = reason or "Serialized Respawn Watcher v0.116",
        queuedAtMs = minigames.Now()
    }

    minigames.S.lastRespawnStatus =
        "serial queued | player=" .. tostring(playerId) ..
        " | name=" .. minigames.GetPlayerName(playerId) ..
        " | serial=" .. tostring(serial) ..
        " | queue=" .. tostring(#minigames.S.serialRespawnQueue)

    minigames.LogInfo("[Respawn Queue v0.116] " .. minigames.S.lastRespawnStatus)

    if minigames.WarGames and minigames.WarGames.StartSerialRespawnQueueWorker then
        minigames.WarGames.StartSerialRespawnQueueWorker()
    end

    return true, "serial_queued_v116"
end

-- replace queuerespawnspawnonce so it does not mark spawn timestamps before enqueue.
minigames.__v116_original_QueueRespawnSpawnOnce = minigames.QueueRespawnSpawnOnce
function minigames.QueueRespawnSpawnOnce(playerId, vehicle, serial, reason)
    if minigames.EnsureRespawnLifecycleTables then
        minigames.EnsureRespawnLifecycleTables()
    end

    playerId = minigames.ClampInt(playerId or 0, 0, 31)
    serial = tonumber(serial or 0) or 0

    minigames.Player = minigames.Player or {}
    minigames.Player.respawnPhase = minigames.Player.respawnPhase or {}
    minigames.Player.respawnLastSpawnDeathSerial = minigames.Player.respawnLastSpawnDeathSerial or {}
    minigames.Player.respawnSpawnLockUntilMs = minigames.Player.respawnSpawnLockUntilMs or {}
    minigames.Player.wasDead = minigames.Player.wasDead or {}
    minigames.Player.deathDetectedMs = minigames.Player.deathDetectedMs or {}
    minigames.Player.respawnReadyMs = minigames.Player.respawnReadyMs or {}
    minigames.Player.respawnCycleActive = minigames.Player.respawnCycleActive or {}
    minigames.Player.respawnVehicleSpawnedThisCycle = minigames.Player.respawnVehicleSpawnedThisCycle or {}

    -- duplicate serial lock only. no time-gap block here.
    if minigames.Player.respawnLastSpawnDeathSerial[playerId] == serial then
        return false, "already_spawned_serial_v116"
    end

    minigames.Player.respawnPhase[playerId] = "queued"
    minigames.Player.respawnLastSpawnDeathSerial[playerId] = serial
    minigames.Player.respawnSpawnLockUntilMs[playerId] = minigames.Now() + (minigames.S.respawnSpawnCycleLockMs or 30000)
    minigames.Player.wasDead[playerId] = false
    minigames.Player.deathDetectedMs[playerId] = 0
    minigames.Player.respawnReadyMs[playerId] = 0
    minigames.Player.respawnCycleActive[playerId] = true
    minigames.Player.respawnVehicleSpawnedThisCycle[playerId] = true

    local queued, qStatus = minigames.EnqueueRespawnVehicleSpawn(playerId, vehicle, serial, reason or "Queued Respawn Watcher v0.116")

    if queued then
        minigames.S.lastRespawnStatus = "Queued respawn vehicle for " .. minigames.GetPlayerName(playerId) .. " | " .. tostring(qStatus)
        return true, qStatus
    end

    -- if queue failed due full/etc, unlock this serial so a later tick can retry.
    minigames.Player.respawnLastSpawnDeathSerial[playerId] = nil
    minigames.Player.respawnVehicleSpawnedThisCycle[playerId] = false
    minigames.Player.respawnPhase[playerId] = "ready_retry"

    minigames.S.lastRespawnStatus = "Failed to queue respawn vehicle for " .. minigames.GetPlayerName(playerId) .. " | " .. tostring(qStatus)
    minigames.LogError("[Respawn Watcher] " .. tostring(minigames.S.lastRespawnStatus))
    return false, qStatus
end

-- patch worker output/version + ensure spawn timestamp is set only after actual spawn success.
if minigames.WarGames then
    minigames.__v116_original_StartSerialRespawnQueueWorker = minigames.WarGames.StartSerialRespawnQueueWorker
    function minigames.WarGames.StartSerialRespawnQueueWorker()
        minigames.S = minigames.S or {}
        if minigames.S.serialRespawnWorkerRunning == true then
            return true, "running"
        end

        minigames.S.serialRespawnWorkerRunning = true

        local function worker()
            minigames.LogInfo("[Respawn Queue v0.116] worker started")

            if Script and Script.Yield then
                Script.Yield(minigames.S.serialRespawnInitialDelayMs or 250)
            end

            while minigames.S and minigames.S.serialRespawnQueue and #minigames.S.serialRespawnQueue > 0 do
                local item = table.remove(minigames.S.serialRespawnQueue, 1)

                if item then
                    local playerId = minigames.ClampInt(item.playerId or 0, 0, 31)
                    local serial = tonumber(item.serial or 0) or 0
                    minigames.S.serialRespawnQueuedByPlayer[playerId] = nil

                    local okJob, errJob = direct_call_trace(function()
                        if not minigames.IsPlayerActive(playerId) then
                            minigames.LogInfo("[Respawn Queue v0.116] skipped inactive | player=" .. tostring(playerId))
                            return
                        end

                        local spawnVehicle = item.vehicle
                        if not spawnVehicle and minigames.WarGames and minigames.WarGames.ResolveVehicle then
                            spawnVehicle = minigames.WarGames.ResolveVehicle("Serialized Respawn Spawn v0.116")
                        end

                        if not spawnVehicle then
                            minigames.LogError("[Respawn Queue v0.116] vehicle=nil | player=" .. tostring(playerId))
                            return
                        end

                        local okSpawn, status = minigames.SpawnVehicleForPlayer(playerId, spawnVehicle, true, item.reason or "Serialized Respawn Watcher v0.116")

                        if okSpawn then
                            minigames.Player.respawnVehicleSpawnedAtMs = minigames.Player.respawnVehicleSpawnedAtMs or {}
                            minigames.Player.respawnVehicleSpawnedAtMs[playerId] = minigames.Now()
                            minigames.S.lastRespawnStatus =
                                "Serialized spawn success for " .. minigames.GetPlayerName(playerId) ..
                                " | serial=" .. tostring(serial)
                            minigames.LogInfo("[Respawn Queue v0.116] SUCCESS | " .. minigames.S.lastRespawnStatus)
                        else
                            -- allow retry on next true death/respawn cycle by clearing serial lock.
                            minigames.Player.respawnLastSpawnDeathSerial[playerId] = nil
                            minigames.Player.respawnVehicleSpawnedThisCycle[playerId] = false
                            minigames.Player.respawnPhase[playerId] = "ready_retry"
                            minigames.S.lastRespawnStatus =
                                "Serialized spawn failed for " .. minigames.GetPlayerName(playerId) ..
                                " | " .. tostring(status)
                            minigames.LogError("[Respawn Queue v0.116] FAILED | " .. minigames.S.lastRespawnStatus .. " | LastVehicleError=" .. tostring(minigames.S.lastVehicleError))
                        end
                    end, debug and debug.traceback or function(e) return tostring(e) end)

                    if not okJob then
                        minigames.LogError("[Respawn Queue v0.116] worker item error | " .. tostring(errJob))
                    end
                end

                if Script and Script.Yield then
                    Script.Yield(minigames.S.serialRespawnSpawnGapMs or 1400)
                else
                    break
                end
            end

            minigames.S.serialRespawnWorkerRunning = false
            minigames.LogInfo("[Respawn Queue v0.116] worker stopped")
        end

        if Script and Script.QueueJob then
            local okQueue, errQueue = direct_call(function() Script.QueueJob(worker) end)
            if not okQueue then
                minigames.S.serialRespawnWorkerRunning = false
                minigames.LogError("[Respawn Queue v0.116] QueueJob failed: " .. tostring(errQueue))
                return false, "queuejob_failed"
            end
            return true, "queued"
        end

        minigames.S.serialRespawnWorkerRunning = false
        return false, "queuejob_missing"
    end
end

-- re-reset gap state when wargames respawn is enabled.
if minigames.WarGames and minigames.WarGames.SetSpawnVehicleOnPlayerRespawn then
    minigames.__v116_original_SetSpawnVehicleOnPlayerRespawn = minigames.WarGames.SetSpawnVehicleOnPlayerRespawn
    function minigames.WarGames.SetSpawnVehicleOnPlayerRespawn(enabled, reason)
        local result = minigames.__v116_original_SetSpawnVehicleOnPlayerRespawn(enabled, reason)
        if enabled == true then
            minigames.ResetRespawnQueueGapState("SetSpawnVehicleOnPlayerRespawn " .. tostring(reason or ""))
        end
        return result
    end
end


