-- best-effort set visible toggle defaults if feature objects are available.
if FeatureMgr and FeatureMgr.GetFeatureByHash and minigames.H then
    local function setToggle(hash, value)
        if not hash then return end
        local ok, feature = direct_call(function()
            return FeatureMgr.GetFeatureByHash(hash)
        end)
        if ok and feature then
            if feature.SetToggled then direct_call(function() feature:SetToggled(value == true) end) end
            if feature.SetBoolValue then direct_call(function() feature:SetBoolValue(value == true) end) end
        end
    end

    setToggle(minigames.H.WARGAMES_DEBUG_ERRORS, true)
    setToggle(minigames.H.WARGAMES_DEBUG_HEARTBEAT, false)
    setToggle(minigames.H.WARGAMES_DEBUG_ROUNDS, false)
end

if minigames.LogInfoUnfiltered then
    minigames.LogInfoUnfiltered("Loaded v0.171-alpha")
    minigames.LogInfoUnfiltered("WarGames debug toggles active: Errors ON, Heartbeat OFF, Rounds OFF.")
else
    minigames.LogInfo("Loaded " .. script_version)
