-- ============================================================
-- embedded module: systems\adaptive_hud.lua
-- ============================================================
embedded_modules['systems\\adaptive_hud.lua'] = function()
--[[
    minigames - adaptive hud
    v0.171-alpha

    hotfix:
    - fixes v0.123 boot failure caused by malformed lua in the plus/minus hud row filter.
    - keeps the compact hud behavior: no session list, no +/- rows, no '- none + none' row.
]]

minigames = minigames or {}
minigames.S = minigames.S or {}
minigames.HUD = minigames.HUD or {}

minigames.VERSION = "v0.183-alpha"

------------------------------------------------------------
-- settings / cleanup flags
------------------------------------------------------------
function minigames.HUD.ApplyAdaptiveOverrides()
    minigames.S.hudShowSessionPlayers = false
    minigames.S.hudShowPlusMinusButtons = false
    minigames.S.hudShowHudButtons = false
    minigames.S.hudShowControlButtons = false
    minigames.S.hudShowSessionButtons = false
    minigames.S.hudShowPrevNextDecorators = false
    minigames.S.hudDisablePlusMinusRows = true
    minigames.S.hudDisableButtonRows = true
    minigames.S.hudMaxPlayerRows = 0
    minigames.S.hudCompactMode = true
end

------------------------------------------------------------
-- safe helpers
------------------------------------------------------------
local function safeString(value, fallback)
    if value == nil then return fallback or "None" end
    local text = tostring(value)
    if text == "" or text == "nil" then return fallback or "None" end
    return text
end

local function tableCount(tbl)
    local count = 0
    if type(tbl) == "table" then
        for _, value in pairs(tbl) do
            if value ~= nil then count = count + 1 end
        end
    end
    return count
end

function minigames.HUD.GetPlayerCount()
    if minigames.GetActivePlayers then
        local ok, players = direct_call(minigames.GetActivePlayers)
        if ok and type(players) == "table" then
            return #players
        end
    end

    if minigames.S and type(minigames.S.activePlayers) == "table" then
        return #minigames.S.activePlayers
    end

    return 0
end

function minigames.HUD.GetTrackedVehicleCount()
    local sources = {
        minigames.S and minigames.S.trackedVehicles,
        minigames.S and minigames.S.spawnedVehicles,
        minigames.S and minigames.S.wargamesVehicles,
        minigames.S and minigames.S.trackedWarGamesVehicles,
    }

    local best = 0
    for _, source in ipairs(sources) do
        best = math.max(best, tableCount(source))
    end

    return best
end

function minigames.HUD.GetClearedVehicleCount()
    local candidates = {
        minigames.S and minigames.S.vehiclesCleared,
        minigames.S and minigames.S.clearedVehicles,
        minigames.S and minigames.S.vehicleClearedCount,
        minigames.S and minigames.S.totalVehiclesCleared,
        minigames.S and minigames.S.cleanupDeletedCount,
        minigames.S and minigames.S.pedwarsCleanupStats and minigames.S.pedwarsCleanupStats.deleted,
    }

    for _, value in ipairs(candidates) do
        local numberValue = tonumber(value)
        if numberValue then return numberValue end
    end

    return 0
end

------------------------------------------------------------
-- vehicle helpers
------------------------------------------------------------
function minigames.HUD.GetVehiclePool()
    if minigames.WarGames and type(minigames.WarGames.VehiclePool) == "table" then
        return minigames.WarGames.VehiclePool
    end

    if minigames.WarGames and type(minigames.WarGames.Vehicles) == "table" then
        return minigames.WarGames.Vehicles
    end

    return nil
end

function minigames.HUD.GetVehicleLabel(vehicle)
    if not vehicle then return "None" end
    if type(vehicle) == "string" then return vehicle end
    return safeString(vehicle.label or vehicle.name or vehicle.displayName or vehicle.model, "None")
end

function minigames.HUD.GetCurrentVehicleIndex(pool)
    pool = pool or minigames.HUD.GetVehiclePool()
    if type(pool) ~= "table" or #pool <= 0 then return nil end

    local index = tonumber(minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or minigames.S.currentVehicleIndex or minigames.S.wargamesVehicleIndex or 1) or 1
    if index < 1 then index = 1 end
    if index > #pool then index = #pool end
    return index
end

function minigames.HUD.GetCurrentVehicleLabel()
    if minigames.WarGames and minigames.WarGames.GetCurrentVehicle then
        local ok, vehicle = direct_call(minigames.WarGames.GetCurrentVehicle)
        if ok and vehicle then
            return minigames.HUD.GetVehicleLabel(vehicle)
        end
    end

    if minigames.S and minigames.S.currentVehicleLabel then
        return safeString(minigames.S.currentVehicleLabel, "None")
    end

    local pool = minigames.HUD.GetVehiclePool()
    local index = minigames.HUD.GetCurrentVehicleIndex(pool)
    if pool and index then
        return minigames.HUD.GetVehicleLabel(pool[index])
    end

    return "None"
end

function minigames.HUD.GetNextVehicleLabel()
    local pool = minigames.HUD.GetVehiclePool()
    if type(pool) ~= "table" or #pool <= 0 then return "None" end

    local index = minigames.HUD.GetCurrentVehicleIndex(pool) or 1
    local nextIndex = index + 1
    if nextIndex > #pool then nextIndex = 1 end
    return minigames.HUD.GetVehicleLabel(pool[nextIndex])
end

------------------------------------------------------------
-- active mode helpers
------------------------------------------------------------
function minigames.HUD.IsWarGamesActive()
    return minigames.S and (
        minigames.S.wargamesSystemsActive == true
        or minigames.S.wargamesNoBountyMode == true
        or minigames.S.spawnVehicleOnPlayerRespawn == true
        or minigames.S.spawnVehiclesOnRespawn == true
        or minigames.S.respawnVehiclesOnPlayerRespawn == true
    )
end

function minigames.HUD.GetActiveMode()
    if minigames.S and minigames.S.activeMinigame and tostring(minigames.S.activeMinigame) ~= "" then
        return tostring(minigames.S.activeMinigame)
    end

    if minigames.HUD.IsWarGamesActive() then return "WarGames" end
    if minigames.S and (minigames.S.landOnItActive == true or minigames.S.landOnItRunning == true) then return "Land On It" end
    if minigames.S and (minigames.S.driftGodActive == true or minigames.S.driftGodRunning == true) then return "DriftGod" end
    if minigames.S and (minigames.S.beastActive == true or minigames.S.beastRunning == true) then return "Beast" end

    return "None"
end

------------------------------------------------------------
-- plus/minus row filter
------------------------------------------------------------
function minigames.HUD.IsPlusMinusHudRow(line)
    local trim = tostring(line or ""):gsub("^%s+", ""):gsub("%s+$", "")

    if trim == "" then return true end
    if trim == "+" or trim == "-" then return true end
    if trim == "- None  + None" then return true end
    if trim == "- None + None" then return true end
    if trim == "-    +" then return true end
    if trim == "-   +" then return true end
    if trim == "- +" then return true end

    if trim:match("^[-+%s]+$") and (trim:find("%+") or trim:find("%-")) then
        return true
    end

    if trim:match("^%-.*%+.*$") and not trim:match("^Prev:") and not trim:match("^Next:") then
        return true
    end

    if trim == "Session:" then return true end

    return false
end

------------------------------------------------------------
-- hud line builders
------------------------------------------------------------
function minigames.HUD.GetWarGamesLines()
    local lines = {}
    local vehicle = minigames.HUD.GetCurrentVehicleLabel()
    local nextVehicle = minigames.HUD.GetNextVehicleLabel()

    table.insert(lines, "Mode: WarGames")
    table.insert(lines, "Vehicle: " .. vehicle)

    if nextVehicle ~= "None" then
        table.insert(lines, "Next: " .. nextVehicle)
    end

    table.insert(lines, minigames.GetHudVehicleStatsText and minigames.GetHudVehicleStatsText() or ("Vehicles: " .. tostring(minigames.HUD.GetTrackedVehicleCount()) .. "  Cleared: " .. tostring(minigames.HUD.GetClearedVehicleCount())))
    table.insert(lines, "Players: " .. tostring(minigames.HUD.GetPlayerCount()))

    return lines
end

function minigames.HUD.GetLines()
    local mode = minigames.HUD.GetActiveMode()

    if mode == "None" and minigames.S.hudOnlyWhenMinigameActive == true then
        return nil
    end

    local lines = { "Minigames" }

    if mode == "WarGames" then
        for _, line in ipairs(minigames.HUD.GetWarGamesLines()) do table.insert(lines, line) end
    elseif mode == "Land On It" then
        table.insert(lines, "Mode: Land On It")
        table.insert(lines, "Vehicle: " .. safeString(minigames.S.landOnItVehicle or minigames.S.landOnItCurrentVehicle, "MK1 / Shamal"))
        table.insert(lines, "Players: " .. tostring(minigames.HUD.GetPlayerCount()))
    elseif mode == "DriftGod" then
        table.insert(lines, "Mode: DriftGod")
        table.insert(lines, "Score: " .. tostring(minigames.S.driftScore or 0))
        table.insert(lines, "Best: " .. tostring(minigames.S.driftBestScore or 0))
    elseif mode == "Beast" then
        table.insert(lines, "Mode: Beast")
        table.insert(lines, "Players: " .. tostring(minigames.HUD.GetPlayerCount()))
    elseif type(minigames.S.activeMinigameHudLines) == "table" then
        for _, line in ipairs(minigames.S.activeMinigameHudLines) do table.insert(lines, line) end
    else
        table.insert(lines, "Mode: " .. safeString(mode, "None"))
        table.insert(lines, "Players: " .. tostring(minigames.HUD.GetPlayerCount()))
    end

    local filtered = {}
    local maxLines = tonumber(minigames.S.hudMaxLines or 9) or 9

    for _, line in ipairs(lines) do
        if not minigames.HUD.IsPlusMinusHudRow(line) then
            table.insert(filtered, line)
            if #filtered >= maxLines then break end
        end
    end

    return filtered
end

function minigames.HUD.GetText()
    local lines = minigames.HUD.GetLines()
    if not lines or #lines <= 0 then return nil end
    return table.concat(lines, "\n")
end

function minigames.HUD.Status()
    local text = minigames.HUD.GetText() or "HUD hidden / no active minigame"
    if minigames.LogInfo then minigames.LogInfo("[Adaptive HUD] " .. text:gsub("\n", " | ")) end
    if minigames.Toast then minigames.Toast("Adaptive HUD", text, 5000) end
    return text
end

minigames.HUD.ApplyAdaptiveOverrides()

if minigames.LogInfo then
    minigames.LogInfo("[Adaptive HUD] loaded v0.171-alpha syntax hotfix")
end


