function minigames.HUD.GetTrackedVehicleCount()
    if minigames.VehicleTracking and minigames.VehicleTracking.GetActiveCount then
        return minigames.VehicleTracking.GetActiveCount()
    end
    local count = 0
    if minigames.S and type(minigames.S.trackedVehicles) == "table" then
        for _, entry in pairs(minigames.S.trackedVehicles) do
            if entry then count = count + 1 end
        end
    end
    return count
end

function minigames.HUD.GetClearedVehicleCount()
    if minigames.VehicleTracking and minigames.VehicleTracking.GetClearedCount then
        return minigames.VehicleTracking.GetClearedCount()
    end
    if minigames.S then
        return tonumber(minigames.S.vehiclesCleared or minigames.S.vehicleClearedCount or minigames.S.totalVehiclesCleared or 0) or 0
    end
    return 0
end


------------------------------------------------------------
-- v0.128 hud count bridge fix
------------------------------------------------------------
function minigames.HUD.GetTrackedVehicleCount()
    if minigames.VehicleTracking and minigames.VehicleTracking.SyncHudStats then
        local active = select(1, minigames.VehicleTracking.SyncHudStats("hud_draw"))
        return tonumber(active or 0) or 0
    end

    if minigames.S then
        return tonumber(minigames.S.hudVehiclesCount or minigames.S.activeVehicleCount or minigames.S.trackedVehicleCount or 0) or 0
    end

    return 0
end

function minigames.HUD.GetClearedVehicleCount()
    if minigames.VehicleTracking and minigames.VehicleTracking.SyncHudStats then
        local cleared = select(2, minigames.VehicleTracking.SyncHudStats("hud_draw"))
        return tonumber(cleared or 0) or 0
    end

    if minigames.S then
        return tonumber(minigames.S.hudClearedVehiclesCount or minigames.S.vehiclesCleared or minigames.S.vehicleClearedCount or minigames.S.totalVehiclesCleared or 0) or 0
    end

    return 0
end


------------------------------------------------------------
-- v0.129 direct fix: hud reads spawnedwargamesvehicles
------------------------------------------------------------
-- important:
-- the real raw spawn tracker writes to mg.s.spawnedwargamesvehicles.
-- previous hud bridges forgot that exact table name, so ids logged correctly
-- while vehicles still displayed 0.
------------------------------------------------------------

function minigames.CountWarGamesTrackedVehicleTables()
    local S = minigames.S or {}
    local WG = minigames.WarGames or {}
    local WGS = WG.S or {}

    local tables = {
        S.spawnedWarGamesVehicles,        -- real table used by registerwargamesvehicle()
        S.spawnedWarGamesVehicleRecords,
        S.trackedWarGamesVehicles,
        S.warGamesTrackedVehicles,
        S.wargamesTrackedVehicles,
        S.spawnedVehicles,
        S.respawnVehicles,
        S.respawnTrackedVehicles,
        S.playerRespawnVehicles,
        S.vehicleTrackingById,
        S.trackedVehicles,
        WG.spawnedWarGamesVehicles,
        WG.spawnedVehicles,
        WG.trackedVehicles,
        WGS.spawnedWarGamesVehicles,
        WGS.spawnedVehicles,
        WGS.trackedVehicles,
    }

    local bestActive = 0
    local bestRaw = 0
    local missing = 0
    local deleted = 0

    local function exists(entity)
        if entity == nil or entity == 0 then return false end
        if ENTITY and ENTITY.DOES_ENTITY_EXIST then
            local ok, result = direct_call(function()
                return ENTITY.DOES_ENTITY_EXIST(entity)
            end)
            return ok and result == true
        end
        return true
    end

    for _, tbl in ipairs(tables) do
        if type(tbl) == "table" then
            local active = 0
            local raw = 0
            local tblMissing = 0
            local tblDeleted = 0

            for _, entry in pairs(tbl) do
                if entry ~= nil then
                    raw = raw + 1

                    if type(entry) == "table" then
                        if entry.deleted == true or entry.cleared == true then
                            tblDeleted = tblDeleted + 1
                        else
                            local entity = entry.entity or entry.handle or entry.vehicle or entry.veh or entry.vehicleHandle
                            if entity == nil then
                                active = active + 1
                            elseif exists(entity) then
                                active = active + 1
                            else
                                tblMissing = tblMissing + 1
                            end
                        end
                    else
                        if exists(entry) then
                            active = active + 1
                        else
                            tblMissing = tblMissing + 1
                        end
                    end
                end
            end

            if raw > bestRaw then bestRaw = raw end
            if active > bestActive then bestActive = active end
            if tblMissing > missing then missing = tblMissing end
            if tblDeleted > deleted then deleted = tblDeleted end
        end
    end

    -- prefer active, but if entity checks fail/aren't available, show raw so hud doesn't lie at 0.
    local visibleActive = bestActive
    if visibleActive <= 0 and bestRaw > 0 then
        visibleActive = bestRaw - deleted
    end
    if visibleActive < 0 then visibleActive = 0 end

    local cleared = math.max(
        tonumber(S.vehiclesCleared or 0) or 0,
        tonumber(S.vehicleClearedCount or 0) or 0,
        tonumber(S.totalVehiclesCleared or 0) or 0,
        tonumber(S.deletedWarGamesVehicleCount or 0) or 0,
        tonumber(S.cleanedVehicleCount or 0) or 0,
        tonumber(S.cleanupDeletedCount or 0) or 0,
        missing,
        deleted
    )

    S.hudVehiclesCount = visibleActive
    S.hudClearedVehiclesCount = cleared
    S.vehiclesTrackedHud = visibleActive
    S.vehiclesClearedHud = cleared
    S.lastHudVehicleCounterStatus =
        "active=" .. tostring(visibleActive) ..
        " raw=" .. tostring(bestRaw) ..
        " missing=" .. tostring(missing) ..
        " deleted=" .. tostring(deleted) ..
        " cleared=" .. tostring(cleared)

    return visibleActive, cleared, bestRaw, missing, deleted
end

function minigames.GetTrackedVehicleCount()
    local active = select(1, minigames.CountWarGamesTrackedVehicleTables())
    return tonumber(active or 0) or 0
end

function minigames.GetClearedVehicleCount()
    local cleared = select(2, minigames.CountWarGamesTrackedVehicleTables())
    return tonumber(cleared or 0) or 0
end

function minigames.GetHudVehicleStatsText()
    return "Vehicles: " .. tostring(minigames.GetTrackedVehicleCount()) .. "  Cleared: " .. tostring(minigames.GetClearedVehicleCount())
end

if minigames.HUD then
    function minigames.HUD.GetTrackedVehicleCount()
        return minigames.GetTrackedVehicleCount()
    end

    function minigames.HUD.GetClearedVehicleCount()
        return minigames.GetClearedVehicleCount()
    end
end
end

