local function ascii_console_color_v101(name, fallback)
    if not eLogColor then return nil end
    return eLogColor[name] or eLogColor[fallback or "LIGHTCYAN"] or eLogColor.LIGHTCYAN
end

function minigames.AsciiBanner.PrintBlock(title, art, details)
    local titleText = tostring(title or "MINIGAMES")
    local separator = "──────────────────────────────────────────────────────────────────────────────"
    local lines = {
        separator,
        tostring(art or ""),
        separator,
        titleText,
    }

    if type(details) == "table" then
        for _, line in ipairs(details) do
            lines[#lines + 1] = tostring(line)
        end
    end

    lines[#lines + 1] = separator

    -- match the clean minigames startup style: one colored multiline call, so
    -- cherax does not repeat timestamps or empty [] prefixes on every line.
    if titleText == "WARGAMES" and Logger then
        local block = "\n" .. table.concat(lines, "\n")
        local color = ascii_console_color_v101("LIGHTRED", "RED")
        if Logger.Log and color ~= nil then
            local ok = direct_call(function() Logger.Log(color, "WARGAMES", block) end)
            if ok then return end
        end
        if Logger.LogInfo then
            local ok = direct_call(function() Logger.LogInfo("[WARGAMES] " .. block) end)
            if ok then return end
        end
    end

    if not minigames.LogInfo then return end
    for _, line in ipairs(lines) do minigames.LogInfo(line) end
end

