------------------------------------------------------------
-- v0.139 wargames banner spam guard
------------------------------------------------------------
local __mg139_old_print_wargames_details = minigames.AsciiBanner.PrintWarGamesDetails
function minigames.AsciiBanner.PrintWarGamesDetails(reason)
    reason = tostring(reason or "WarGames activation")

    -- helper calls should not print full wargames banner.
    if reason:find("EnableRespawnVehiclesForAllCurrentPlayers", 1, true) then
        minigames.S.suppressedWarGamesLogCount = (tonumber(minigames.S.suppressedWarGamesLogCount or 0) or 0) + 1
        minigames.S.lastSuppressedWarGamesLogChannel = "activation"
        minigames.S.lastSuppressedWarGamesLog = "Suppressed WARGAMES banner helper reason=" .. reason
        return
    end

    local now = minigames.Now and minigames.Now() or (os and os.clock and math.floor(os.clock() * 1000) or 0)
    local last = tonumber(minigames.S.lastWarGamesBannerMs or 0) or 0

    if last ~= 0 and now ~= 0 and now - last < 5000 then
        minigames.S.suppressedWarGamesLogCount = (tonumber(minigames.S.suppressedWarGamesLogCount or 0) or 0) + 1
        minigames.S.lastSuppressedWarGamesLogChannel = "activation"
        minigames.S.lastSuppressedWarGamesLog = "Suppressed duplicate WARGAMES banner reason=" .. reason
        return
    end

    minigames.S.lastWarGamesBannerMs = now

    if __mg139_old_print_wargames_details then
        return __mg139_old_print_wargames_details(reason)
    end
end
end

