embedded_modules['systems\\bounty.lua'] = function()
-- minigames/systems/bounty.lua
-- confirmed working method:
-- featuremgr.getfeaturebyname("set bounty on player", playerid):triggercallback()

minigames.C.BUILT_IN_BOUNTY_FEATURE_NAME = "Set Bounty On Player"
minigames.C.BUILT_IN_BOUNTY_AMOUNT_LABEL = "9k"

function minigames.IsBountyTracked(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)
    return minigames.Player.bountyApplied[playerId] == true
end

function minigames.MarkBountyTracked(playerId, method)
    playerId = minigames.ClampInt(playerId, 0, 31)
    minigames.InitPlayerState(playerId)

    minigames.Player.bountyApplied[playerId] = true
    minigames.Player.bountyAppliedAtMs[playerId] = minigames.Now()
    minigames.Player.bountyLastMethod[playerId] = tostring(method or "Built-in 9k")
end

function minigames.ClearBountyTracking(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)
    minigames.InitPlayerState(playerId)

    minigames.Player.bountyApplied[playerId] = false
    minigames.Player.bountyAppliedAtMs[playerId] = 0
    minigames.Player.bountyLastStatus[playerId] = "Tracking cleared"
    minigames.Player.bountyLastMethod[playerId] = "None"
    minigames.Player.bountyLastError[playerId] = "None"

    minigames.Toast("Bounty Tracking Cleared", minigames.GetPlayerName(playerId), 2500)
end

function minigames.ClearAllBountyTracking()
    for playerId = 0, 31 do
        minigames.InitPlayerState(playerId)
        minigames.Player.bountyApplied[playerId] = false
        minigames.Player.bountyAppliedAtMs[playerId] = 0
        minigames.Player.bountyLastStatus[playerId] = "Tracking cleared"
        minigames.Player.bountyLastMethod[playerId] = "None"
        minigames.Player.bountyLastError[playerId] = "None"
    end

    minigames.Toast("Bounty Tracking", "All bounty tracking cleared.", 3000)
end

function minigames.SetBountyStatus(playerId, status, method, err)
    playerId = minigames.ClampInt(playerId, 0, 31)
    minigames.InitPlayerState(playerId)

    minigames.Player.bountyLastStatus[playerId] = tostring(status or "None")
    minigames.Player.bountyLastMethod[playerId] = tostring(method or "None")
    minigames.Player.bountyLastError[playerId] = tostring(err or "None")

    minigames.S.lastBountyStatus = tostring(status or "None")
    minigames.S.lastBountyTarget = playerId
    minigames.S.lastBountyTargetName = minigames.GetPlayerName(playerId)
    minigames.S.lastBountyMethod = tostring(method or "None")
    minigames.S.lastBountyError = tostring(err or "None")
end

function minigames.ApplyBuiltInBounty(playerId, force)
    if minigames.RefreshConfig then minigames.RefreshConfig() end

    playerId = minigames.ClampInt(playerId, 0, 31)
    force = force == true

    if not minigames.IsPlayerActive(playerId) then
        minigames.SetBountyStatus(playerId, "Skipped: inactive player", "Built-in 9k", "inactive")
        return false, "inactive"
    end

    if minigames.S.skipSelfBounty and minigames.IsSelf(playerId) and not force then
        minigames.SetBountyStatus(playerId, "Skipped: self", "Built-in 9k", "skip_self")
        return false, "skip_self"
    end

    -- important:
    -- in v0.053, force bypasses internal tracking so auto reapply can run every 60 seconds.
    if minigames.S.useBountyTracking and minigames.IsBountyTracked(playerId) and not force then
        minigames.SetBountyStatus(playerId, "Skipped: already tracked", "Built-in 9k", "already_tracked")
        return false, "already_tracked"
    end

    local feature = nil

    local okGet, errGet = direct_call(function()
        feature = FeatureMgr.GetFeatureByName(minigames.C.BUILT_IN_BOUNTY_FEATURE_NAME, playerId)
    end)

    if not okGet or not feature then
        minigames.SetBountyStatus(playerId, "Failed: built-in bounty feature not found", "Built-in 9k", errGet or "feature=nil")
        return false, "feature_nil"
    end

    local okTrigger, errTrigger = direct_call(function()
        feature:TriggerCallback()
    end)

    if okTrigger then
        minigames.MarkBountyTracked(playerId, "Built-in 9k")
        minigames.SetBountyStatus(playerId, "Applied built-in 9k bounty to " .. minigames.GetPlayerName(playerId), "Built-in 9k", "None")
        minigames.LogInfo("Bounty applied | player=" .. tostring(playerId) .. " | " .. minigames.GetPlayerName(playerId) .. " | force=" .. tostring(force))
        return true, "applied"
    end

    minigames.SetBountyStatus(playerId, "Failed: TriggerCallback error", "Built-in 9k", errTrigger)
    return false, "trigger_failed"
end

function minigames.ApplyBountyToSelected(force)
    minigames.RefreshPlayers()
    if minigames.RefreshConfig then minigames.RefreshConfig() end

    local playerId = minigames.S.selectedPlayerId

    minigames.Queue(function()
        local ok, status = minigames.ApplyBuiltInBounty(playerId, force == true)

        if ok then
            minigames.Toast("Bounty Applied", minigames.GetPlayerName(playerId) .. " | built-in " .. minigames.C.BUILT_IN_BOUNTY_AMOUNT_LABEL, 4000)
        else
            minigames.Toast("Bounty Failed", minigames.GetPlayerName(playerId) .. " | " .. tostring(status), 6000)
        end
    end)
end

function minigames.ApplyBountyToAll(force)
    minigames.RefreshPlayers()
    if minigames.RefreshConfig then minigames.RefreshConfig() end

    force = force == true

    minigames.S.lastBountyBatchApplied = 0
    minigames.S.lastBountyBatchSkipped = 0
    minigames.S.lastBountyBatchFailed = 0

    for _, playerId in ipairs(minigames.S.activePlayers) do
        if minigames.S.skipSelfBounty and minigames.IsSelf(playerId) and not force then
            minigames.S.lastBountyBatchSkipped = minigames.S.lastBountyBatchSkipped + 1
        else
            local ok, status = minigames.ApplyBuiltInBounty(playerId, force)

            if ok then
                minigames.S.lastBountyBatchApplied = minigames.S.lastBountyBatchApplied + 1
            elseif status == "skip_self" or status == "already_tracked" or status == "inactive" then
                minigames.S.lastBountyBatchSkipped = minigames.S.lastBountyBatchSkipped + 1
            else
                minigames.S.lastBountyBatchFailed = minigames.S.lastBountyBatchFailed + 1
            end
        -- v0.061: no yielding inside cherax feature/tick fibers.
        end
    end

    minigames.S.lastBountyStatus =
        "Bounty batch complete | applied=" ..
        tostring(minigames.S.lastBountyBatchApplied) ..
        " skipped=" ..
        tostring(minigames.S.lastBountyBatchSkipped) ..
        " failed=" ..
        tostring(minigames.S.lastBountyBatchFailed)

    minigames.Toast("Apply Bounties To All", minigames.S.lastBountyStatus, 5000)
end


------------------------------------------------------------
-- v0.107 force bounty maintain interval
------------------------------------------------------------
minigames.S.autoBountyIntervalMs = 60000
minigames.S.bountyIntervalMs = 60000
minigames.S.autoBountyMaintainIntervalMs = 60000
minigames.S.bountyMaintenanceIntervalMs = 60000
minigames.LogInfo("[WarGames Bounty] Auto-maintain interval forced to 60 seconds.")


------------------------------------------------------------
-- v0.112 no automatic vehicle spawn on join
------------------------------------------------------------
minigames.S.disableAutomaticSpawnAll = true
minigames.S.spawnAllOnPlayerJoin = false
minigames.S.autoSpawnAllOnJoin = false
minigames.S.spawnVehicleForNewPlayers = false
minigames.S.autoGiveRoundVehicleToNewPlayers = false


------------------------------------------------------------
-- v0.113 auto spawn-all disabled in this module
------------------------------------------------------------
minigames.S.disableAutomaticSpawnAll = true
minigames.S.disableSpawnAllFromJoin = true
minigames.S.spawnAllOnPlayerJoin = false
minigames.S.autoSpawnAllOnJoin = false
minigames.S.spawnVehicleForNewPlayers = false
minigames.S.autoGiveRoundVehicleToNewPlayers = false
end

-- ============================================================
-- embedded module: systems\cherax_vehicle_spam_protection.lua
-- ============================================================
embedded_modules['systems\\cherax_vehicle_spam_protection.lua'] = function()
-- minigames/systems/cherax_vehicle_spam_protection.lua
-- v0.171-alpha
--
-- wargames compatibility for cherax prime vehicle-spam protections.
--
-- while wargames / wargames no-bounties / wargames bounty is active:
--   off: block vehicle spam
--   off: only rate-limit modded vehicles
--   off: block vehicle density
--
-- exact prior states are restored when wargames is no longer active,
-- during script unload, or during the next startup after an abnormal exit.

minigames.WarGames = minigames.WarGames or {}
minigames.WarGames.VehicleSpamProtection = minigames.WarGames.VehicleSpamProtection or {}

local VP = minigames.WarGames.VehicleSpamProtection

VP.Specs = {
    {
        key = "block_vehicle_spam",
        displayName = "Block Vehicle Spam",
        names = {
            "Block Vehicle Spam",
        },
    },
    {
        key = "only_rate_limit_modded",
        displayName = "Only Rate-Limit Modded Vehicles",
        names = {
            "Only Rate-Limit Modded Vehicles",
            "Only Rate Limit Modded Vehicles",
            "Only Rate-Limit Modded Vehicle",
            "Only Rate Limit Modded Vehicle",
        },
    },
    {
        key = "block_vehicle_density",
        displayName = "Block Vehicle Density",
        names = {
            "Block Vehicle Density",
        },
    },
}

VP.markerPath =
    (minigames.ROOT or ".") ..
    "\\cherax_vehicle_spam_protection_restore.txt"

function VP.Now()
    return minigames.Now and minigames.Now() or 0
end

function VP.Log(message)
    if minigames.LogInfo then
        minigames.LogInfo(
            "[WarGames Protection Guard] " ..
            tostring(message)
        )
    elseif Logger and Logger.LogInfo then
        Logger.LogInfo(
            "[WarGames Protection Guard] " ..
            tostring(message)
        )
    end
end

function VP.Error(message)
    if minigames.LogError then
        minigames.LogError(
            "[WarGames Protection Guard] " ..
            tostring(message)
        )
    elseif Logger and Logger.LogError then
        Logger.LogError(
            "[WarGames Protection Guard] " ..
            tostring(message)
        )
    end
end

function VP.ReadToggle(feature)
    if not feature then return nil end

    if minigames.WarGames.SafeFeatureIsOnV140 then
        local ok, value = direct_call(
            minigames.WarGames.SafeFeatureIsOnV140,
            feature
        )
        if ok then return value == true end
    end

    if feature.IsToggled then
        local ok, value = direct_call(function()
            return feature:IsToggled()
        end)
        if ok and value ~= nil then
            return value == true
        end
    end

    if feature.GetBoolValue then
        local ok, value = direct_call(function()
            return feature:GetBoolValue()
        end)
        if ok and value ~= nil then
            return value == true
        end
    end

    if feature.GetValue then
        local ok, value = direct_call(function()
            return feature:GetValue()
        end)
        if ok and value ~= nil then
            return value == true or value == 1
        end
    end

    return nil
end

function VP.SetToggle(feature, enabled)
    if not feature then
        return false, "feature_missing"
    end

    enabled = enabled == true
    local before = VP.ReadToggle(feature)

    if before == enabled then
        return true, "already_" .. tostring(enabled)
    end

    -- v0.157: proven cherax method used by other working scripts.
    -- featuremgr.getfeaturebyname("..."):toggle(value)
    if feature.Toggle then
        local ok, err = direct_call(function()
            feature:Toggle(enabled)
        end)

        if ok then
            local after = VP.ReadToggle(feature)

            if minigames.S.warGamesVehicleSpamProtectionVerifyAfterToggle == false
                or after == enabled then
                return true, "Toggle(value)"
            end
        else
            VP.Error(
                "Toggle(value) failed: " .. tostring(err)
            )
        end
    end

    -- compatibility fallbacks only if direct toggle(value) did not work.
    if feature.SetToggled then
        local ok = direct_call(function()
            feature:SetToggled(enabled)
        end)

        if ok and VP.ReadToggle(feature) == enabled then
            return true, "SetToggled"
        end
    end

    if feature.SetBoolValue then
        local ok = direct_call(function()
            feature:SetBoolValue(enabled)
        end)

        if ok and feature.TriggerCallback then
            direct_call(function()
                feature:TriggerCallback()
            end)
        end

        if ok and VP.ReadToggle(feature) == enabled then
            return true, "SetBoolValue"
        end
    end

    if feature.SetValue then
        local ok = direct_call(function()
            feature:SetValue(enabled and 1 or 0)
        end)

        if ok and feature.TriggerCallback then
            direct_call(function()
                feature:TriggerCallback()
            end)
        end

        if ok and VP.ReadToggle(feature) == enabled then
            return true, "SetValue"
        end
    end

    -- last fallback for toggle implementations that accept no argument.
    if feature.Toggle then
        local current = VP.ReadToggle(feature)

        if current ~= enabled then
            local ok = direct_call(function()
                feature:Toggle()
            end)

            if ok and VP.ReadToggle(feature) == enabled then
                return true, "Toggle()"
            end
        end
    end

    return VP.ReadToggle(feature) == enabled, "best_effort"
end

function VP.FindFeature(spec)
    if not FeatureMgr or not FeatureMgr.GetFeatureByName then
        return nil, "FeatureMgr unavailable"
    end

    for _, name in ipairs(spec.names or {}) do
        local feature = nil
        local ok, result = direct_call(function()
            return FeatureMgr.GetFeatureByName(name)
        end)

        if ok then
            feature = result
        end

        if feature then
            return feature, name
        end
    end

    return nil, "not_found"
end

function VP.GetFeatureToggle(hash, fallback)
    if minigames.GetFeatureBool and hash then
        local ok, value = direct_call(
            minigames.GetFeatureBool,
            hash,
            fallback == true
        )

        if ok then return value == true end
    end

    if FeatureMgr and FeatureMgr.GetFeatureByHash and hash then
        local ok, feature = direct_call(function()
            return FeatureMgr.GetFeatureByHash(hash)
        end)

        if ok and feature then
            local value = VP.ReadToggle(feature)
            if value ~= nil then return value end
        end
    end

    return fallback == true
end

function VP.ShouldDisable()
    if minigames.S.warGamesVehicleSpamProtectionGuardEnabled ~= true then
        return false, "guard_disabled"
    end

    local master = false
    local noBounties = false
    local bounty = false

    if minigames.H then
        master = VP.GetFeatureToggle(
            minigames.H.WARGAMES_ACTIVATE_SYSTEMS,
            false
        )

        noBounties = VP.GetFeatureToggle(
            minigames.H.WARGAMES_ACTIVATE_SYSTEMS_NO_BOUNTIES,
            false
        )

        bounty = VP.GetFeatureToggle(
            minigames.H.WARGAMES_AUTO_BOUNTY_TICK,
            false
        )
    end

    master =
        master or
        minigames.S.wargamesSystemsActive == true or
        minigames.S.wargamesActive == true or
        minigames.S.warGamesActive == true

    noBounties =
        noBounties or
        minigames.S.wargamesNoBountyMode == true

    bounty =
        bounty or
        minigames.S.autoBountyRunning == true or
        minigames.S.autoBountyEnabled == true

    if master then
        return true, "WarGames"
    end

    if noBounties then
        return true, "WarGames No-Bounties"
    end

    if bounty then
        return true, "WarGames Bounty"
    end

    return false, "inactive"
end

function VP.WriteMarker()
    if minigames.S.warGamesVehicleSpamProtectionCrashRecovery ~= true then
        return false
    end

    local file = io.open(VP.markerPath, "w")
    if not file then
        return false
    end

    file:write("version=v0.171-alpha\n")

    for _, spec in ipairs(VP.Specs) do
        local record =
            minigames.S.warGamesVehicleSpamProtectionStates[spec.key]

        if record then
            file:write(
                tostring(spec.key) ..
                "=" ..
                (record.wasOn == true and "1" or "0") ..
                "\n"
            )
        end
    end

    file:close()
    return true
end

function VP.DeleteMarker()
    direct_call(function()
        os.remove(VP.markerPath)
    end)
end

function VP.ReadMarker()
    local file = io.open(VP.markerPath, "r")
    if not file then return nil end

    local states = {}

    for line in file:lines() do
        local key, value =
            tostring(line):match("^([%w_]+)=([01])$")

        if key and value then
            states[key] = value == "1"
        end
    end

    file:close()
    return states
end


function VP.GetProtectionStateSummary()
    local parts = {}

    for _, spec in ipairs(VP.Specs) do
        local feature, resolved = VP.FindFeature(spec)
        local state = feature and VP.ReadToggle(feature) or nil

        parts[#parts + 1] =
            tostring(spec.displayName) ..
            "=" ..
            (state == nil and "missing" or tostring(state)) ..
            "(" .. tostring(resolved or "none") .. ")"
    end

    return table.concat(parts, " | ")
end

function VP.Disable(reason)
    if minigames.S.warGamesVehicleSpamProtectionGuardEnabled ~= true then
        return false, "guard_disabled"
    end

    minigames.S.warGamesVehicleSpamProtectionStates =
        minigames.S.warGamesVehicleSpamProtectionStates or {}

    local found = 0
    local disabled = 0
    local alreadyOff = 0
    local failed = 0

    for _, spec in ipairs(VP.Specs) do
        local feature, resolvedName = VP.FindFeature(spec)

        if feature then
            found = found + 1

            local record =
                minigames.S.warGamesVehicleSpamProtectionStates[spec.key]

            if not record then
                local wasOn = VP.ReadToggle(feature) == true

                record = {
                    key = spec.key,
                    displayName = spec.displayName,
                    resolvedName = resolvedName,
                    wasOn = wasOn,
                    changedByWarGames = false,
                }

                minigames.S.warGamesVehicleSpamProtectionStates[spec.key] =
                    record
            end

            local current = VP.ReadToggle(feature)

            if current == true then
                local ok, method = VP.SetToggle(feature, false)

                if ok then
                    disabled = disabled + 1
                    record.changedByWarGames = true
                    record.disableMethod = method
                else
                    failed = failed + 1
                    record.disableError = method
                end
            elseif current == false then
                alreadyOff = alreadyOff + 1
            else
                failed = failed + 1
                record.disableError = "state_unknown"
            end
        else
            failed = failed + 1
            VP.Error(
                "Could not find Cherax feature: " ..
                tostring(spec.displayName)
            )
        end
    end

    minigames.S.warGamesVehicleSpamProtectionActive = true
    VP.WriteMarker()

    minigames.S.warGamesVehicleSpamProtectionLastStatus =
        "OFF while active" ..
        " | found=" .. tostring(found) ..
        " | disabled=" .. tostring(disabled) ..
        " | alreadyOff=" .. tostring(alreadyOff) ..
        " | failed=" .. tostring(failed) ..
        " | reason=" .. tostring(reason or "WarGames active")

    if disabled > 0 or failed > 0 or
        minigames.S.warGamesVehicleSpamProtectionLastDisableLogMs == nil then
        minigames.S.warGamesVehicleSpamProtectionLastDisableLogMs = VP.Now()

        VP.Log(
            minigames.S.warGamesVehicleSpamProtectionLastStatus ..
            " | states=" .. VP.GetProtectionStateSummary()
        )
    end

    return failed == 0, minigames.S.warGamesVehicleSpamProtectionLastStatus
end

function VP.Restore(reason, markerStates)
    local states =
        minigames.S.warGamesVehicleSpamProtectionStates or {}

    local restored = 0
    local keptOff = 0
    local missing = 0
    local failed = 0

    for _, spec in ipairs(VP.Specs) do
        local record = states[spec.key]
        local desired = nil

        if record then
            desired = record.wasOn == true
        elseif markerStates and
            markerStates[spec.key] ~= nil then
            desired = markerStates[spec.key] == true
        end

        if desired ~= nil then
            local feature = VP.FindFeature(spec)

            if feature then
                if desired == true then
                    local ok = VP.SetToggle(feature, true)

                    if ok then
                        restored = restored + 1
                    else
                        failed = failed + 1
                    end
                else
                    -- it was already off before wargames.
                    -- preserve that exact user preference.
                    local ok = VP.SetToggle(feature, false)

                    if ok then
                        keptOff = keptOff + 1
                    else
                        failed = failed + 1
                    end
                end
            else
                missing = missing + 1
            end
        end
    end

    minigames.S.warGamesVehicleSpamProtectionActive = false
    minigames.S.warGamesVehicleSpamProtectionStates = {}
    VP.DeleteMarker()

    minigames.S.warGamesVehicleSpamProtectionLastStatus =
        "restored previous states" ..
        " | restoredOn=" .. tostring(restored) ..
        " | preservedOff=" .. tostring(keptOff) ..
        " | missing=" .. tostring(missing) ..
        " | failed=" .. tostring(failed) ..
        " | reason=" .. tostring(reason or "WarGames inactive")

    VP.Log(minigames.S.warGamesVehicleSpamProtectionLastStatus)

    return failed == 0,
        minigames.S.warGamesVehicleSpamProtectionLastStatus
end

function VP.RecoverStaleMarker()
    if minigames.S.warGamesVehicleSpamProtectionCrashRecovery ~= true then
        return false, "disabled"
    end

    local states = VP.ReadMarker()
    if not states then
        return false, "no_marker"
    end

    VP.Log(
        "Found previous-session restore marker; " ..
        "restoring Cherax protection states."
    )

    return VP.Restore(
        "previous session abnormal exit recovery",
        states
    )
end

function VP.Sync(reason)
    local shouldDisable, source = VP.ShouldDisable()

    if shouldDisable then
        return VP.Disable(
            reason or source or "WarGames active"
        )
    end

    if minigames.S.warGamesVehicleSpamProtectionActive == true and
        minigames.S.warGamesVehicleSpamProtectionRestoreOnDisable ~= false then
        return VP.Restore(
            reason or "all WarGames/bounty toggles OFF"
        )
    end

    return true, "no_change"
end

function VP.Tick()
    local now = VP.Now()
    local interval =
        tonumber(
            minigames.S.warGamesVehicleSpamProtectionSyncMs or 500
        ) or 750

    local last =
        tonumber(
            minigames.S.warGamesVehicleSpamProtectionLastSyncMs or 0
        ) or 0

    if last ~= 0 and now - last < interval then
        return
    end

    minigames.S.warGamesVehicleSpamProtectionLastSyncMs = now
    VP.Sync("periodic state sync")
end

------------------------------------------------------------
-- disable protections before activation logic can spawn vehicles.
------------------------------------------------------------

if minigames.WarGames.SystemsTick and
    minigames.WarGames.__v156SystemsTickGuard ~= true then
    minigames.WarGames.__v156SystemsTickGuard = true
    local oldSystemsTick = minigames.WarGames.SystemsTick

    function minigames.WarGames.SystemsTick(feature)
        local enabled = false

        if minigames.SafeIsToggled then
            enabled =
                minigames.SafeIsToggled(
                    feature,
                    minigames.H and minigames.H.WARGAMES_ACTIVATE_SYSTEMS,
                    false
                ) == true
        elseif feature and feature.IsToggled then
            direct_call(function()
                enabled = feature:IsToggled() == true
            end)
        end

        if enabled then
            VP.Disable("Activate WarGames Systems")
        end

        local result = oldSystemsTick(feature)

        if not enabled then
            VP.Sync("WarGames Systems OFF")
        end

        return result
    end
end

if minigames.WarGames.SystemsNoBountyTick and
    minigames.WarGames.__v156NoBountyTickGuard ~= true then
    minigames.WarGames.__v156NoBountyTickGuard = true
    local oldNoBountyTick =
        minigames.WarGames.SystemsNoBountyTick

    function minigames.WarGames.SystemsNoBountyTick(feature)
        local enabled = false

        if minigames.SafeIsToggled then
            enabled =
                minigames.SafeIsToggled(
                    feature,
                    minigames.H and
                        minigames.H.WARGAMES_ACTIVATE_SYSTEMS_NO_BOUNTIES,
                    false
                ) == true
        elseif feature and feature.IsToggled then
            direct_call(function()
                enabled = feature:IsToggled() == true
            end)
        end

        if enabled then
            VP.Disable(
                "Activate WarGames Systems - No Bounties"
            )
        end

        local result = oldNoBountyTick(feature)

        if not enabled then
            VP.Sync("WarGames No-Bounties OFF")
        end

        return result
    end
end

if minigames.WarGames.ActivateSystems and
    minigames.WarGames.__v156ActivateGuard ~= true then
    minigames.WarGames.__v156ActivateGuard = true
    local oldActivate = minigames.WarGames.ActivateSystems

    function minigames.WarGames.ActivateSystems(...)
        VP.Disable("ActivateSystems pre-spawn guard")
        return oldActivate(...)
    end
end

if minigames.WarGames.ActivateSystemsNoBounties and
    minigames.WarGames.__v156ActivateNoBountyGuard ~= true then
    minigames.WarGames.__v156ActivateNoBountyGuard = true
    local oldActivateNoBounties =
        minigames.WarGames.ActivateSystemsNoBounties

    function minigames.WarGames.ActivateSystemsNoBounties(...)
        VP.Disable(
            "ActivateSystemsNoBounties pre-spawn guard"
        )
        return oldActivateNoBounties(...)
    end
end

------------------------------------------------------------
-- periodic state sync through the existing scheduler.
------------------------------------------------------------

if minigames.Scheduler and minigames.Scheduler.Tick and
    minigames.__v156ProtectionSchedulerHook ~= true then
    minigames.__v156ProtectionSchedulerHook = true
    local oldSchedulerTick = minigames.Scheduler.Tick

    function minigames.Scheduler.Tick(...)
        local result = oldSchedulerTick(...)

        local ok, err = direct_call(VP.Tick)
        if not ok then
            VP.Error("scheduler sync failed: " .. tostring(err))
        end

        return result
    end
end


------------------------------------------------------------
-- v0.157 final late-load activation guards
------------------------------------------------------------
-- this file now loads after startup.lua and ui registration, so these are the
-- final wrappers and cannot be replaced by later build patches.

if minigames.WarGames.SystemsTick and
    minigames.WarGames.__v157FinalSystemsTickGuard ~= true then
    minigames.WarGames.__v157FinalSystemsTickGuard = true
    local oldFinalSystemsTick = minigames.WarGames.SystemsTick

    function minigames.WarGames.SystemsTick(feature)
        local enabled = false

        if feature and feature.IsToggled then
            direct_call(function()
                enabled = feature:IsToggled() == true
            end)
        end

        if enabled then
            VP.Disable("final SystemsTick pre-spawn")
        end

        local result = oldFinalSystemsTick(feature)

        if not enabled then
            VP.Sync("final SystemsTick disabled")
        end

        return result
    end
end

if minigames.WarGames.SystemsNoBountyTick and
    minigames.WarGames.__v157FinalNoBountyTickGuard ~= true then
    minigames.WarGames.__v157FinalNoBountyTickGuard = true
    local oldFinalNoBountyTick =
        minigames.WarGames.SystemsNoBountyTick

    function minigames.WarGames.SystemsNoBountyTick(feature)
        local enabled = false

        if feature and feature.IsToggled then
            direct_call(function()
                enabled = feature:IsToggled() == true
            end)
        end

        if enabled then
            VP.Disable("final No-Bounties pre-spawn")
        end

        local result = oldFinalNoBountyTick(feature)

        if not enabled then
            VP.Sync("final No-Bounties disabled")
        end

        return result
    end
end

-- final scheduler wrapper installed after startup.lua.
if minigames.Scheduler and minigames.Scheduler.Tick and
    minigames.__v157FinalProtectionSchedulerHook ~= true then
    minigames.__v157FinalProtectionSchedulerHook = true
    local oldFinalProtectionTick = minigames.Scheduler.Tick

    function minigames.Scheduler.Tick(...)
        local result = oldFinalProtectionTick(...)

        local ok, err = direct_call(VP.Tick)
        if not ok then
            VP.Error(
                "final scheduler sync failed: " ..
                tostring(err)
            )
        end

        return result
    end
end

------------------------------------------------------------
-- restore on normal script unload / normal game shutdown.
------------------------------------------------------------

if EventMgr and EventMgr.RegisterHandler and
    eLuaEvent and eLuaEvent.ON_UNLOAD and
    minigames.__v157ProtectionUnloadRegistered ~= true then
    minigames.__v157ProtectionUnloadRegistered = true

    EventMgr.RegisterHandler(
        eLuaEvent.ON_UNLOAD,
        function()
            if minigames.S.warGamesVehicleSpamProtectionRestoreOnUnload ~=
                false then
                direct_call(
                    VP.Restore,
                    "Minigames ON_UNLOAD"
                )
            end
        end
    )
end

-- recover states if a prior process ended before on_unload could execute.
direct_call(VP.RecoverStaleMarker)

-- this module loads after startup.lua and after all ui features are registered.
direct_call(function()
    VP.Sync("v0.157 late-load initial sync")
end)

VP.Log(
    "v0.157 loaded LAST | guarding Block Vehicle Spam, " ..
    "Only Rate-Limit Modded Vehicles, and Block Vehicle Density." ..
    " | current=" .. VP.GetProtectionStateSummary()
)
end

