embedded_modules['systems\\debug.lua'] = function()
-- minigames/systems/debug.lua

function minigames.PrintSystemDebug()
    minigames.RefreshPlayers()

    minigames.LogInfo("========== Minigames System Debug ==========")
    minigames.LogInfo("Version: " .. tostring(minigames.VERSION))
    minigames.LogInfo("Players: " .. tostring(minigames.S.activePlayerCount) .. " via " .. tostring(minigames.S.lastPlayerDiscoveryMethod))
    minigames.LogInfo("WarGames Active: " .. tostring(minigames.S.wargamesSystemsActive))
    minigames.LogInfo("Auto Bounty Running: " .. tostring(minigames.S.autoBountyRunning))
    minigames.LogInfo("Auto Bounty Interval: " .. tostring(minigames.S.autoBountyIntervalMs))
    minigames.LogInfo("Auto Bounty Ticks: " .. tostring(minigames.S.autoBountyTickCount))
    minigames.LogInfo("Respawn Running: " .. tostring(minigames.S.respawnWatcherRunning))
    minigames.LogInfo("Respawn Ticks: " .. tostring(minigames.S.respawnTickCount))
    minigames.LogInfo("Last Bounty: " .. tostring(minigames.S.lastBountyStatus))
    minigames.LogInfo("Last Vehicle: " .. tostring(minigames.S.lastVehicleStatus))
    minigames.LogInfo("Last Respawn: " .. tostring(minigames.S.lastRespawnStatus))
    minigames.LogInfo("Last Vehicle Cleanup: " .. tostring(minigames.S.lastVehicleCleanupStatus))
    minigames.LogInfo("Tracked WarGames Vehicles: " .. tostring(#(minigames.S.spawnedWarGamesVehicles or {})))
    minigames.LogInfo("Deleted WarGames Vehicles: " .. tostring(minigames.S.deletedWarGamesVehicleCount or 0))
    minigames.LogInfo("Last Weapon Cleanup: " .. tostring(minigames.S.lastWeaponCleanupStatus))
    minigames.LogInfo("Last Fair Vehicle Enforcement: " .. tostring(minigames.S.lastFairVehicleStatus))
    minigames.LogInfo("Fair Vehicle Mode: " .. tostring(minigames.S.fairVehicleMode))
    minigames.LogInfo("Fair Vehicle Deleted Count: " .. tostring(minigames.S.fairVehicleDeletedCount or 0))

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        local health, healthSource = minigames.GetPlayerHealth(playerId)
        local dead, deadReason = minigames.IsPlayerDead(playerId)

        minigames.LogInfo(
            "player=" .. tostring(playerId) ..
            " name=" .. minigames.GetPlayerName(playerId) ..
            " health=" .. tostring(health) ..
            " healthSource=" .. tostring(healthSource) ..
            " dead=" .. tostring(dead) ..
            " deadReason=" .. tostring(deadReason) ..
            " bountyTracked=" .. tostring(minigames.Player.bountyApplied[playerId] == true) ..
            " vehicleEnabled=" .. tostring(minigames.Player.vehicleEnabled[playerId] == true) ..
            " wasDead=" .. tostring(minigames.Player.wasDead[playerId] == true)
        )
    end

    minigames.LogInfo("===========================================")
    minigames.Toast("Debug", "Printed system debug.", 3000)
end

------------------------------------------------------------
-- v0.137 wargames debug filters
------------------------------------------------------------
minigames.Debug = minigames.Debug or {}

function minigames.Debug.EnsureWarGamesDefaultsV137()
    if minigames.S.wargamesDebugErrors == nil then minigames.S.wargamesDebugErrors = true end
    if minigames.S.wargamesDebugHeartbeat == nil then minigames.S.wargamesDebugHeartbeat = false end
    if minigames.S.wargamesDebugRounds == nil then minigames.S.wargamesDebugRounds = false end
end

function minigames.Debug.StringContainsAnyV137(text, needles)
    text = tostring(text or ""):lower()

    for _, needle in ipairs(needles or {}) do
        if text:find(tostring(needle):lower(), 1, true) then
            return true
        end
    end

    return false
end

function minigames.Debug.ClassifyWarGamesLogV137(message)
    local msg = tostring(message or "")

    -- error logs should remain visible by default.
    if minigames.Debug.StringContainsAnyV137(msg, {
        "[error]",
        "[fatal]",
        " error",
        "error:",
        "failed",
        "exception",
        "traceback",
        "scheduler error",
        "systems error",
        "spawn failed",
        "delete failed",
        "cleanup failed",
        "nil value",
        "attempt to",
        "threw an exception",
    }) then
        return "error"
    end

    -- heartbeats are currently the main spam source.
    if minigames.Debug.StringContainsAnyV137(msg, {
        "heartbeat",
        "scheduler heartbeat",
        "[wargames systems] scheduler",
        "[wargames respawn] heartbeat",
        "watcher=true",
        "spawnonrespawn=true",
        "players=",
        "localid=",
        "watched=",
        "skippedremote=",
        "remoteRespawn=true",
        "cleanup=soft cleanup only",
    }) then
        return "heartbeat"
    end

    -- round transition logs can be useful, but are noisy with auto rounds.
    if minigames.Debug.StringContainsAnyV137(msg, {
        "[wargames rounds]",
        "wargames vehicle round",
        "vehicle round changed",
        "round changed",
        "time's up",
        "new round",
        "previous vehicle",
        "auto random vehicle round",
        "random round",
        "queued active round vehicle",
    }) then
        return "round"
    end

    return "normal"
end

function minigames.Debug.ShouldPrintWarGamesLogV137(message)
    minigames.Debug.EnsureWarGamesDefaultsV137()

    local channel = minigames.Debug.ClassifyWarGamesLogV137(message)

    if channel == "error" then
        return minigames.S.wargamesDebugErrors == true, channel
    end

    if channel == "heartbeat" then
        return minigames.S.wargamesDebugHeartbeat == true, channel
    end

    if channel == "round" then
        return minigames.S.wargamesDebugRounds == true, channel
    end

    return true, channel
end

function minigames.Debug.SetWarGamesDebugV137(channel, enabled)
    channel = tostring(channel or "")
    enabled = enabled == true

    if channel == "errors" then
        minigames.S.wargamesDebugErrors = enabled
    elseif channel == "heartbeat" then
        minigames.S.wargamesDebugHeartbeat = enabled
    elseif channel == "rounds" then
        minigames.S.wargamesDebugRounds = enabled
    end

    minigames.S.lastWarGamesDebugStatus =
        "Errors Debug=" .. (minigames.S.wargamesDebugErrors and "ON" or "OFF") ..
        " | Heartbeat Debug=" .. (minigames.S.wargamesDebugHeartbeat and "ON" or "OFF") ..
        " | WarGames Rounds Debug=" .. (minigames.S.wargamesDebugRounds and "ON" or "OFF")

    if minigames.LogInfoUnfiltered then
        minigames.LogInfoUnfiltered("[WarGames Debug] " .. minigames.S.lastWarGamesDebugStatus)
    elseif minigames.LogInfo then
        minigames.LogInfo("[WarGames Debug] " .. minigames.S.lastWarGamesDebugStatus)
    end
end

function minigames.Debug.PrintWarGamesDebugStatusV137()
    minigames.Debug.EnsureWarGamesDefaultsV137()

    minigames.S.lastWarGamesDebugStatus =
        "Errors Debug=" .. (minigames.S.wargamesDebugErrors and "ON" or "OFF") ..
        " | Heartbeat Debug=" .. (minigames.S.wargamesDebugHeartbeat and "ON" or "OFF") ..
        " | WarGames Rounds Debug=" .. (minigames.S.wargamesDebugRounds and "ON" or "OFF")

    if minigames.LogInfoUnfiltered then
        minigames.LogInfoUnfiltered("[WarGames Debug Status] " .. minigames.S.lastWarGamesDebugStatus)
    elseif minigames.LogInfo then
        minigames.LogInfo("[WarGames Debug Status] " .. minigames.S.lastWarGamesDebugStatus)
    end

    if minigames.Toast then
        minigames.Toast("WarGames Debug", minigames.S.lastWarGamesDebugStatus, 5500)
    end
end

minigames.Debug.EnsureWarGamesDefaultsV137()

if minigames.LogInfo then
    minigames.LogInfo("[WarGames Debug] v0.137 filters loaded | Errors=ON | Heartbeat=OFF | Rounds=OFF")
end


------------------------------------------------------------
-- v0.137 wargames log filter wrapper fallback
------------------------------------------------------------
if minigames.LogInfo and minigames.__v137LogFilterInstalled ~= true then
    minigames.__v137LogFilterInstalled = true
    minigames.LogInfoUnfiltered = minigames.LogInfoUnfiltered or minigames.LogInfo

    local __mg137_original_log_info_fallback = minigames.LogInfo

    minigames.LogInfo = function(message)
        local msg = tostring(message or "")

        if minigames.Debug and minigames.Debug.ShouldPrintWarGamesLogV137 then
            local shouldPrint, channel = minigames.Debug.ShouldPrintWarGamesLogV137(msg)

            if shouldPrint ~= true then
                minigames.S = minigames.S or {}
                minigames.S.suppressedWarGamesLogCount = (tonumber(minigames.S.suppressedWarGamesLogCount or 0) or 0) + 1
                minigames.S.lastSuppressedWarGamesLogChannel = channel
                minigames.S.lastSuppressedWarGamesLog = msg
                return
            end
        end

        return __mg137_original_log_info_fallback(message)
    end

    minigames.LogInfoUnfiltered("[WarGames Debug] Log filter wrapper installed from debug fallback.")
end


