        " | RespawnWatcher=" .. (minigames.S.wargamesDebugRespawnWatcher and "ON" or "OFF")

    minigames.S.lastWarGamesDebugStatus = status

    if minigames.TrueRawLogInfoV140 then
        minigames.TrueRawLogInfoV140("[WarGames Debug Status] " .. status)
        minigames.TrueRawLogInfoV140("[WarGames Debug Status] Suppressed logs=" .. tostring(minigames.S.suppressedWarGamesLogCount or 0) .. " | Last channel=" .. tostring(minigames.S.lastSuppressedWarGamesLogChannel or "None"))
        minigames.TrueRawLogInfoV140("[WarGames Cherax Safety] " .. tostring(minigames.S.lastCheraxVehicleHelperSafety or "Not active yet"))
    elseif minigames.LogInfo then
        minigames.LogInfo("[WarGames Debug Status] " .. status)
    end

    if minigames.Toast then
        minigames.Toast("WarGames Debug", status, 5500)
    end
end

function minigames.Debug.PrintWarGamesDebugStatusV139() return minigames.Debug.PrintWarGamesDebugStatusV140() end
function minigames.Debug.PrintWarGamesDebugStatusV138() return minigames.Debug.PrintWarGamesDebugStatusV140() end
function minigames.Debug.PrintWarGamesDebugStatusV137() return minigames.Debug.PrintWarGamesDebugStatusV140() end

function minigames.Debug.ClassifyWarGamesLogV137(message)
    if minigames.ClassifyLogV140 then return minigames.ClassifyLogV140(message) end
    return "normal"
end
function minigames.Debug.ShouldPrintWarGamesLogV137(message)
    if minigames.ShouldPrintLogV140 then return minigames.ShouldPrintLogV140(message) end
    return true, "normal"
end


------------------------------------------------------------
-- v0.141 debug classifier hook: respawn heartbeat
------------------------------------------------------------
local __mg141_old_classify_debug = minigames.Debug and minigames.Debug.ClassifyWarGamesLogV137
if minigames.Debug then
    function minigames.Debug.ClassifyWarGamesLogV137(message)
        if minigames.IsMutedRespawnHeartbeatV141 and minigames.IsMutedRespawnHeartbeatV141(message) then
            return "heartbeat"
        end

        if __mg141_old_classify_debug then
            return __mg141_old_classify_debug(message)
        end

        return "normal"
    end
end
end

-- ============================================================
-- embedded module: systems\fair_vehicle_enforcement.lua
-- ============================================================
embedded_modules['systems\\fair_vehicle_enforcement.lua'] = function()
--[[
    minigames/systems/fair_vehicle_enforcement.lua
    build: v0.171-alpha

    purpose:
    - keeps wargames fair by policing vehicles players bring from outside the minigame.
    - deletes player-used vehicles that do not match the current active round vehicle.
    - hard-bans rc bandito and rc tank / mini tank.

    catches while players are using them:
    - personal/player-owned mk2s
    - traffic vehicles
    - menu-spawned vehicles from other scripts
    - rc bandito
    - rc tank / mini tank

    safety:
    - this scanner checks the vehicle a detected player is currently using.
    - it does not blindly delete every vehicle in the world.
]]

minigames.FairVehicles = minigames.FairVehicles or {}

minigames.FairVehicles.ModeNames = {
    [0] = "Off",
    [1] = "Banned Vehicles Only",
    [2] = "Current Round Vehicle Only"
}

minigames.FairVehicles.BannedModels = {
    "oppressor2",
    "rcbandito",
    "minitank",
    "avenger",
    "avenger2",
    "akula",
    "annihilator",
    "annihilator2",
    "cargobob",
    "cargobob2",
    "cargobob3",
    "cargobob4",
    "hunter",
    "savage",
    "seasparrow",
    "seasparrow2",
    "seasparrow3",
    "skylift",
    "supervolito",
    "supervolito2",
    "swift",
    "swift2",
    "valkyrie",
    "valkyrie2",
    "volatus",
    "havok",
    "frogger",
    "frogger2",
    "maverick",
    "polmav",
    "volatol",
    "bombushka",
    "molotok",
    "nokota",
    "pyro",
    "rogue",
    "starling",
    "strikeforce",
    "tula",
    "lazer",
    "besra",
    "cuban800",
    "dodo",
    "duster",
    "howard",
    "luxor",
    "luxor2",
    "mammatus",
    "miljet",
    "nimbus",
    "shamal",
    "stunt",
    "titan",
    "velum",
    "velum2",
    "vestra",
    "microlight",
    "mogul",
    "alphaz1",
    "seabreeze",
    "raiju"
}

function minigames.FairVehicles.Log(msg)
    minigames.LogInfo("[WarGames Fair Vehicles] " .. tostring(msg))
end

function minigames.FairVehicles.GetModeName()
    return minigames.FairVehicles.ModeNames[minigames.S.fairVehicleMode or 0] or "Unknown"
end

function minigames.ModelHash(modelName)
    if Utils and Utils.Joaat then
        local ok, hash = direct_call(function()
            return Utils.Joaat(tostring(modelName or ""))
        end)

        if ok and hash then
            return tonumber(hash) or 0
        end
    end

    return 0
end

function minigames.NormalizeHash(value)
    value = tonumber(value) or 0

    -- lua / native wrappers may return signed ints. joaat hashes are normally unsigned.
    if value < 0 then
        value = value + 4294967296
    end

    return value
end

function minigames.FairVehicles.GetVehicleModelHash(vehicleEntity)
    if not vehicleEntity or vehicleEntity == 0 then
        return 0
    end

    if ENTITY and ENTITY.GET_ENTITY_MODEL then
        local ok, hash = direct_call(function()
            return ENTITY.GET_ENTITY_MODEL(vehicleEntity)
        end)

        if ok and hash then
            return minigames.NormalizeHash(hash)
        end
    end

    return 0
end

function minigames.FairVehicles.HashMatchesModel(vehicleHash, modelName)
    vehicleHash = minigames.NormalizeHash(vehicleHash)
    local modelHash = minigames.NormalizeHash(minigames.ModelHash(modelName))

    return modelHash ~= 0 and vehicleHash == modelHash
end

function minigames.FairVehicles.GetCurrentAllowedVehicle()
    local vehicle = nil

    if minigames.WarGames and minigames.WarGames.GetSelectedVehicle then
        vehicle = minigames.WarGames.GetSelectedVehicle()
    end

    if minigames.S.currentRoundVehicleModel and minigames.S.currentRoundVehicleModel ~= "None" then
        return {
            label = minigames.S.currentRoundVehicleName or tostring(minigames.S.currentRoundVehicleModel),
            model = minigames.S.currentRoundVehicleModel
        }
    end

    return vehicle
end

function minigames.FairVehicles.IsBannedModelHash(vehicleHash)
    vehicleHash = minigames.NormalizeHash(vehicleHash)

    for _, modelName in ipairs(minigames.FairVehicles.BannedModels) do
        if minigames.FairVehicles.HashMatchesModel(vehicleHash, modelName) then
            return true, modelName
        end
    end

    return false, "None"
end



function minigames.FairVehicles.IsAlwaysAllowedAircraft(vehicleHash)
    -- user request: do not disable hydra or buzzard.
    if minigames.FairVehicles.HashMatchesModel(vehicleHash, "hydra") then
        return true, "hydra_exempt"
    end

    if minigames.FairVehicles.HashMatchesModel(vehicleHash, "buzzard") then
        return true, "buzzard_exempt"
    end

    return false, "not_exempt"
end

function minigames.FairVehicles.GetVehicleClass(vehicleEntity)
    if VEHICLE and VEHICLE.GET_VEHICLE_CLASS then
        local ok, class = direct_call(function()
            return VEHICLE.GET_VEHICLE_CLASS(vehicleEntity)
        end)

        if ok and class ~= nil then
            return tonumber(class) or -1
        end
    end

    return -1
end

function minigames.FairVehicles.IsAircraftClass(vehicleEntity)
    local class = minigames.FairVehicles.GetVehicleClass(vehicleEntity)
    -- gta v classes: 15 = helicopters, 16 = planes.
    return class == 15 or class == 16
end

function minigames.FairVehicles.GetPlayerCurrentVehicle(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)

    local ped = minigames.GetPlayerPed(playerId)

    if not ped or ped == 0 or not minigames.EntityExists(ped) then
        return 0, "ped_missing"
    end

    if PED and PED.IS_PED_IN_ANY_VEHICLE then
        local inVehicle = false

        local ok = direct_call(function()
            inVehicle = PED.IS_PED_IN_ANY_VEHICLE(ped, false)
        end)

        if ok and inVehicle ~= true then
            return 0, "not_in_vehicle"
        end
    end

    if PED and PED.GET_VEHICLE_PED_IS_IN then
        local veh = 0

        local ok = direct_call(function()
            veh = PED.GET_VEHICLE_PED_IS_IN(ped, false)
        end)

        if ok and veh and veh ~= 0 and minigames.EntityExists(veh) then
            return veh, "ok"
        end
    end

    return 0, "vehicle_missing"
end

function minigames.FairVehicles.ShouldDeleteVehicleForPlayer(playerId, vehicleEntity)
    local vehicleHash = minigames.FairVehicles.GetVehicleModelHash(vehicleEntity)

    if vehicleHash == 0 then
        return false, "model_unknown"
    end

    local allowed = minigames.FairVehicles.GetCurrentAllowedVehicle()
    local banned, bannedModel = minigames.FairVehicles.IsBannedModelHash(vehicleHash)
    local aircraftClass = minigames.FairVehicles.IsAircraftClass(vehicleEntity)
    local exemptAircraft, exemptReason = minigames.FairVehicles.IsAlwaysAllowedAircraft(vehicleHash)

    if exemptAircraft then
        return false, exemptReason
    end

    -- rc vehicles are always unfair in wargames.
    if minigames.S.deleteRcVehicles ~= false and (bannedModel == "rcbandito" or bannedModel == "minitank") then
        return true, "rc_vehicle_banned:" .. tostring(bannedModel)
    end

    -- aircraft class ban catches planes/helicopters not explicitly listed.
    -- current official round vehicles remain allowed so wargames rounds still work.
    if minigames.S.deleteAircraftGriefVehicles ~= false and aircraftClass then
        if allowed and allowed.model and minigames.FairVehicles.HashMatchesModel(vehicleHash, allowed.model) then
            return false, "aircraft_current_round_allowed"
        end

        return true, "aircraft_class_banned"
    end

    -- hard-ban list. if the banned model is also the current round model, allow it.
    if minigames.S.deleteBannedVehicles ~= false and banned then
        if allowed and allowed.model and minigames.FairVehicles.HashMatchesModel(vehicleHash, allowed.model) then
            return false, "banned_but_current_round_allowed"
        end

        return true, "banned_vehicle:" .. tostring(bannedModel)
    end

    -- strict competitive mode: only current round vehicle model is allowed.
    if (minigames.S.fairVehicleMode or 2) == minigames.C.FAIR_VEHICLE_MODE_CURRENT_ROUND_ONLY and minigames.S.deleteNonRoundVehicles ~= false then
        if not allowed or not allowed.model then
            return false, "no_allowed_round_model"
        end

        if not minigames.FairVehicles.HashMatchesModel(vehicleHash, allowed.model) then
            return true, "non_round_vehicle | allowed=" .. tostring(allowed.model) .. " hash=" .. tostring(vehicleHash)
        end
    end

    return false, "allowed"
end

function minigames.FairVehicles.DeletePlayerVehicle(playerId, vehicleEntity, reason)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if not vehicleEntity or vehicleEntity == 0 or not minigames.EntityExists(vehicleEntity) then
        return false, "vehicle_missing"
    end

    local modelHash = minigames.FairVehicles.GetVehicleModelHash(vehicleEntity)
    local ok = minigames.DeleteVehicleEntity(vehicleEntity)

    if ok then
        minigames.S.fairVehicleDeletedCount = (minigames.S.fairVehicleDeletedCount or 0) + 1
        minigames.S.fairVehicleLastDeletedModel = tostring(modelHash)
        minigames.S.fairVehicleLastDeletedPlayer = minigames.GetPlayerName(playerId)
        minigames.S.lastFairVehicleStatus =
            "Deleted unfair vehicle | player=" ..
            minigames.GetPlayerName(playerId) ..
            " | modelHash=" ..
            tostring(modelHash) ..
            " | reason=" ..
            tostring(reason)

        minigames.FairVehicles.Log(minigames.S.lastFairVehicleStatus)
        return true, "deleted"
    end

    minigames.S.lastFairVehicleStatus =
        "Failed to delete unfair vehicle | player=" ..
        minigames.GetPlayerName(playerId) ..
        " | reason=" ..
        tostring(reason)

    minigames.FairVehicles.Log(minigames.S.lastFairVehicleStatus)
    return false, "delete_failed"
end

function minigames.FairVehicles.ScanPlayer(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if not minigames.IsPlayerActive(playerId) then
        return false, "inactive"
    end

    if minigames.S.skipSelfVehicle and minigames.IsSelf(playerId) then
        return false, "skip_self"
    end

    local veh, status = minigames.FairVehicles.GetPlayerCurrentVehicle(playerId)

    if not veh or veh == 0 then
        return false, status
    end

    local shouldDelete, reason = minigames.FairVehicles.ShouldDeleteVehicleForPlayer(playerId, veh)

    if shouldDelete then
        return minigames.FairVehicles.DeletePlayerVehicle(playerId, veh, reason)
    end

    minigames.S.fairVehicleSkippedCount = (minigames.S.fairVehicleSkippedCount or 0) + 1
    return false, reason
end

function minigames.FairVehicles.ScanAll(reason)
    minigames.RefreshPlayers()

    local deleted = 0
    local skipped = 0
    local failed = 0

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        local ok, status = minigames.FairVehicles.ScanPlayer(playerId)

        if ok then
            deleted = deleted + 1
        elseif status == "delete_failed" then
            failed = failed + 1
        else
            skipped = skipped + 1
        end
        -- v0.061: no yielding inside cherax feature/tick fibers.
    end

    minigames.S.lastFairVehicleStatus =
        "Fair scan | deleted=" ..
        tostring(deleted) ..
        " skipped=" ..
        tostring(skipped) ..
        " failed=" ..
        tostring(failed) ..
        " mode=" ..
        minigames.FairVehicles.GetModeName() ..
        " reason=" ..
        tostring(reason or "Manual")

    if deleted > 0 or failed > 0 then
        minigames.FairVehicles.Log(minigames.S.lastFairVehicleStatus)
    end

    return deleted, skipped, failed
end

function minigames.FairVehicles.Tick()
    if minigames.S.fairVehicleEnforcementEnabled ~= true and minigames.S.wargamesSystemsActive ~= true then
        return
    end

    if (minigames.S.fairVehicleMode or 2) == minigames.C.FAIR_VEHICLE_MODE_OFF then
        return
    end

    local now = minigames.Now()
    local scanMs = minigames.S.fairVehicleScanMs or minigames.C.DEFAULT_FAIR_VEHICLE_SCAN_MS
    local last = minigames.S.lastFairVehicleScanMs or 0

    if last ~= 0 and now - last < scanMs then
        return
    end

    minigames.S.lastFairVehicleScanMs = now
    minigames.FairVehicles.ScanAll("Auto Fair Vehicle Enforcement")
end

function minigames.FairVehicles.PrintDebug()
    minigames.RefreshPlayers()

    local allowed = minigames.FairVehicles.GetCurrentAllowedVehicle()

    minigames.LogInfo("========== WarGames Fair Vehicle Debug ==========")
    minigames.LogInfo("Enabled: " .. tostring(minigames.S.fairVehicleEnforcementEnabled))
    minigames.LogInfo("Mode: " .. tostring(minigames.S.fairVehicleMode) .. " | " .. minigames.FairVehicles.GetModeName())
    minigames.LogInfo("Scan MS: " .. tostring(minigames.S.fairVehicleScanMs))
    minigames.LogInfo("Delete RC Vehicles: " .. tostring(minigames.S.deleteRcVehicles))
    minigames.LogInfo("Delete Banned Vehicles: " .. tostring(minigames.S.deleteBannedVehicles))
    minigames.LogInfo("Delete Non-Round Vehicles: " .. tostring(minigames.S.deleteNonRoundVehicles))
    minigames.LogInfo("Allowed Vehicle: " .. tostring(allowed and allowed.label or "None") .. " | model=" .. tostring(allowed and allowed.model or "None"))
    minigames.LogInfo("Deleted Count: " .. tostring(minigames.S.fairVehicleDeletedCount or 0))
    minigames.LogInfo("Last Status: " .. tostring(minigames.S.lastFairVehicleStatus))

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        local veh, status = minigames.FairVehicles.GetPlayerCurrentVehicle(playerId)
        local modelHash = 0
        local shouldDelete = false
        local reason = status

        if veh and veh ~= 0 then
            modelHash = minigames.FairVehicles.GetVehicleModelHash(veh)
            shouldDelete, reason = minigames.FairVehicles.ShouldDeleteVehicleForPlayer(playerId, veh)
        end

        minigames.LogInfo(
            "player=" ..
            tostring(playerId) ..
            " name=" ..
            minigames.GetPlayerName(playerId) ..
            " vehicle=" ..
            tostring(veh) ..
            " modelHash=" ..
            tostring(modelHash) ..
            " shouldDelete=" ..
            tostring(shouldDelete) ..
            " reason=" ..
            tostring(reason)
        )
    end

    minigames.LogInfo("================================================")
    minigames.Toast("Fair Vehicle Debug", "Printed fair vehicle debug.", 3000)
end


------------------------------------------------------------
-- v0.117 safety guard
------------------------------------------------------------
-- these systems are intentionally off by default because live testing showed
-- respawn vehicles worked again after disabling them.
------------------------------------------------------------
end

