embedded_modules['systems\\intro_logo.lua'] = function()
--[[
    minigames - logo intro renderer
    v0.171-alpha

    purpose:
    - uses the finished minigames logo image as the visual intro asset.
    - layout: logo image on top, "minigames" title below it, subtitle below that.
    - keeps the previous driftgod-style startup intro behavior, but upgrades the visuals.

    safety:
    - the png is loaded from minigames/assets/minigames_logo.png.
    - image drawing happens through texture + imgui on_present when available.
    - if image rendering fails or the runtime does not expose texture/imgui, the intro gracefully falls back to text + red glow rectangles instead of throwing.
]]

minigames = minigames or {}
minigames.S = minigames.S or {}
minigames.IntroLogo = minigames.IntroLogo or {}

minigames.TITLE = "MiniGames"
minigames.SUBTITLE = minigames.SUBTITLE or "Turn the lobby into your personal playground."
minigames.VERSION = "v0.183-alpha"

minigames.S.introLogoEnabled = minigames.S.introLogoEnabled ~= false
minigames.S.introLogoFile = minigames.S.introLogoFile or "Minigames_Logo.png"
minigames.S.introLogoX = minigames.S.introLogoX or 0.500
minigames.S.introLogoY = minigames.S.introLogoY or 0.345
minigames.S.introLogoWidth = minigames.S.introLogoWidth or 0.400
minigames.S.introTitleY = minigames.S.introTitleY or 0.525
minigames.S.introSubtitleY = minigames.S.introSubtitleY or 0.595
minigames.S.introFooterY = minigames.S.introFooterY or 0.680
minigames.S.introImageFallbackText = minigames.S.introImageFallbackText ~= false

-- v0.190 intro state. preserve a still-valid cached texture across script
-- reloads when cherax keeps the d3d resource alive, but always register a new
-- generation-gated on_present handler so stale handlers become inert.
local __mg_old_intro_texture_id = tonumber(minigames.IntroLogo.textureId or 0) or 0
local __mg_old_intro_srv = minigames.IntroLogo.textureSrv
local __mg_keep_intro_texture = false
if __mg_old_intro_texture_id > 0 and Texture and Texture.IsTextureValid then
    direct_call(function()
        __mg_keep_intro_texture = Texture.IsTextureValid(__mg_old_intro_texture_id) == true
    end)
end
if __mg_keep_intro_texture then
    minigames.IntroLogo.textureId = __mg_old_intro_texture_id
    minigames.IntroLogo.textureSrv = __mg_old_intro_srv
else
    minigames.IntroLogo.textureId = nil
    minigames.IntroLogo.textureSrv = nil
end
minigames.IntroLogo.pending = nil
minigames.IntroLogo.handlerRegistered = false
minigames.IntroLogo.warned = false
minigames.IntroLogo.textureLoadStarted = __mg_keep_intro_texture == true
minigames.IntroLogo.textureLoadFailed = false
minigames.IntroLogo.textureLoadRequestedMs = 0
minigames.IntroLogo.lastTexturePollMs = 0
minigames.IntroLogo.textureRetryCount = 0
minigames.IntroLogo.textureNextRetryMs = 0
minigames.IntroLogo.fileStableSize = 0
minigames.IntroLogo.fileStableSinceMs = 0
_G.MinigamesIntroPresentGenerationV190 =
    (tonumber(_G.MinigamesIntroPresentGenerationV190 or 0) or 0) + 1
minigames.IntroLogo.presentGenerationV190 = _G.MinigamesIntroPresentGenerationV190


------------------------------------------------------------
-- v0.124 tunable intro layout defaults
------------------------------------------------------------
minigames.S.introBgX = minigames.S.introBgX or 0.500
minigames.S.introBgY = minigames.S.introBgY or 0.380
minigames.S.introBgW = minigames.S.introBgW or 0.720
minigames.S.introBgH = minigames.S.introBgH or 0.520
minigames.S.introBgAlpha = minigames.S.introBgAlpha or 0.100

minigames.S.introTitleX = minigames.S.introTitleX or 0.500
minigames.S.introTitleScale = minigames.S.introTitleScale or 1.04
minigames.S.introSubtitleX = minigames.S.introSubtitleX or 0.500
minigames.S.introSubtitleScale = minigames.S.introSubtitleScale or 0.40

minigames.S.introModesText = minigames.S.introModesText or "WarGames - The Purge - Land On It - DriftGod - Beast"
minigames.S.introModesX = minigames.S.introModesX or 0.500
minigames.S.introModesY = minigames.S.introModesY or minigames.S.introFooterY or 0.680
minigames.S.introModesScale = minigames.S.introModesScale or 0.285

minigames.S.introRedLineX = minigames.S.introRedLineX or 0.500
minigames.S.introRedLineY = minigames.S.introRedLineY or ((minigames.S.introTitleY or 0.555) + 0.078)
minigames.S.introRedLineW = minigames.S.introRedLineW or 0.425
minigames.S.introRedLineH = minigames.S.introRedLineH or 0.006
minigames.S.introRedLineAlpha = minigames.S.introRedLineAlpha or 0.70

minigames.S.introDevText = minigames.S.introDevText or "Developed by Public Urinal"
minigames.S.introDevX = minigames.S.introDevX or 0.500
minigames.S.introDevY = minigames.S.introDevY or 0.670
minigames.S.introDevScale = minigames.S.introDevScale or 0.250
minigames.S.introDevAlpha = minigames.S.introDevAlpha or 0.72

function minigames.IntroLogo.GetLogoPath()
    local root = minigames.ASSETS_ROOT or ((minigames.ROOT or "") .. "\\assets")
    return root .. "\\" .. tostring(minigames.S.introLogoFile or "Minigames_Logo.png")
end

function minigames.IntroLogo.TryLoadTexture()
    if minigames.IntroLogo.textureSrv then
        return minigames.IntroLogo.textureSrv
    end

    if not Texture or not Texture.GetTexture or
        (not Texture.LoadTextureAsync and not Texture.LoadTexture) then
        if not minigames.IntroLogo.warned and minigames.LogInfo then
            minigames.IntroLogo.warned = true
            minigames.LogInfo("[Intro Logo] Texture API unavailable; using text fallback.")
        end
        return nil
    end

    local path = minigames.IntroLogo.GetLogoPath()
    local now = minigames.Now and minigames.Now() or math.floor((os.clock and os.clock() or 0) * 1000)

    -- do not ask cherax to load a png while the downloader is still replacing it.
    -- require the same non-trivial file size for at least 500 ms first.
    local fileSize = 0
    local f = io.open(path, "rb")
    if f then
        fileSize = tonumber(f:seek("end") or 0) or 0
        f:close()
    end
    if fileSize < 1000 then
        return nil
    end
    if tonumber(minigames.IntroLogo.fileStableSize or 0) ~= fileSize then
        minigames.IntroLogo.fileStableSize = fileSize
        minigames.IntroLogo.fileStableSinceMs = now
        return nil
    end
    if now - (tonumber(minigames.IntroLogo.fileStableSinceMs or now) or now) < 500 then
        return nil
    end

    if minigames.IntroLogo.textureLoadFailed == true and
        now < (tonumber(minigames.IntroLogo.textureNextRetryMs or 0) or 0) then
        return nil
    end

    if not minigames.IntroLogo.textureId then
        if minigames.IntroLogo.textureLoadStarted == true and
            now < (tonumber(minigames.IntroLogo.textureNextRetryMs or 0) or 0) then
            return nil
        end

        minigames.IntroLogo.textureLoadStarted = true
        minigames.IntroLogo.textureLoadRequestedMs = now
        minigames.IntroLogo.lastTexturePollMs = 0
        minigames.IntroLogo.textureLoadFailed = false

        local texId = nil
        local okLoad = direct_call(function()
            -- async is preferred on prime/dx12 and avoids the noisy synchronous
            -- loader path that could log a failure even when the intro later drew.
            if Texture.LoadTextureAsync then
                texId = Texture.LoadTextureAsync(path)
            elseif Texture.LoadTexture then
                texId = Texture.LoadTexture(path)
            end
        end)

        texId = tonumber(texId)
        if not okLoad or not texId or texId <= 0 then
            minigames.IntroLogo.textureRetryCount = (tonumber(minigames.IntroLogo.textureRetryCount or 0) or 0) + 1
            minigames.IntroLogo.textureLoadStarted = false
            minigames.IntroLogo.textureLoadFailed = minigames.IntroLogo.textureRetryCount >= 3
            minigames.IntroLogo.textureNextRetryMs = now + 1500
            if minigames.IntroLogo.textureLoadFailed and not minigames.IntroLogo.warned and minigames.LogInfo then
                minigames.IntroLogo.warned = true
                minigames.LogInfo("[Intro Logo] Image loader unavailable after retries; using built-in fallback.")
            end
            return nil
        end

        minigames.IntroLogo.textureId = texId
    end

    if now - (tonumber(minigames.IntroLogo.lastTexturePollMs or 0) or 0) < 100 then
        return nil
    end
    minigames.IntroLogo.lastTexturePollMs = now

    local texId = tonumber(minigames.IntroLogo.textureId or 0) or 0
    if texId <= 0 then return nil end

    if Texture.IsTextureValid then
        local okValid, valid = direct_call(Texture.IsTextureValid, texId)
        if not okValid or valid ~= true then
            if now - (tonumber(minigames.IntroLogo.textureLoadRequestedMs or now) or now) > 10000 then
                minigames.IntroLogo.textureId = nil
                minigames.IntroLogo.textureLoadStarted = false
                minigames.IntroLogo.textureRetryCount = (tonumber(minigames.IntroLogo.textureRetryCount or 0) or 0) + 1
                minigames.IntroLogo.textureNextRetryMs = now + 1500
                minigames.IntroLogo.textureLoadFailed = minigames.IntroLogo.textureRetryCount >= 3
            end
            return nil
        end
    end

    local d3dTex = nil
    local okTex = direct_call(function() d3dTex = Texture.GetTexture(texId) end)
    if not okTex or not d3dTex or not d3dTex.GetCurrent then
        return nil
    end

    local srv = nil
    local okSrv = direct_call(function() srv = d3dTex:GetCurrent() end)
    if okSrv and srv then
        minigames.IntroLogo.textureSrv = srv
        minigames.IntroLogo.textureLoadFailed = false
        minigames.IntroLogo.textureRetryCount = 0
        if minigames.LogInfo then
            minigames.LogInfo("[Intro Logo] Loaded logo image: " .. tostring(path))
        end
        return srv
    end

    return nil
end

function minigames.IntroLogo.QueueLogo(x, y, width, alpha)
    if minigames.S.introLogoEnabled == false then
        minigames.IntroLogo.pending = nil
        return
    end

    minigames.IntroLogo.pending = {
        x = x or minigames.S.introLogoX or 0.5,
        y = y or minigames.S.introLogoY or 0.305,
        width = width or minigames.S.introLogoWidth or 0.48,
        alpha = alpha or 255
    }
end

function minigames.IntroLogo.RegisterPresentHandler()
    if minigames.IntroLogo.handlerRegistered then return end
    if not EventMgr or not EventMgr.RegisterHandler or not eLuaEvent or not eLuaEvent.ON_PRESENT then
        return
    end

    local generation = tonumber(minigames.IntroLogo.presentGenerationV190 or 0) or 0
    local ok = direct_call(function()
        EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
            if tonumber(_G.MinigamesIntroPresentGenerationV190 or 0) ~= generation then return end
            local draw = minigames.IntroLogo.pending
            if not draw then return end
            if not ImGui or not ImGui.BgAddImageRotated then return end

            local srv = minigames.IntroLogo.TryLoadTexture()
            if not srv then return end

            local resX, resY = 1920, 1080
            if ImGui.GetDisplaySize then
                local okSize, sx, sy = direct_call(ImGui.GetDisplaySize)
                if okSize and sx and sy and sx > 0 and sy > 0 then
                    resX, resY = sx, sy
                end
            end

            -- official minigames logo is 3:2. keep its transparent canvas proportional.
            local logoAspect = 1536.0 / 1024.0
            local wPx = (draw.width or 0.48) * resX
            local hPx = wPx / logoAspect
            local xPx = (draw.x or 0.5) * resX
            local yPx = (draw.y or 0.305) * resY
            local alpha = math.floor(math.max(0, math.min(255, draw.alpha or 255)))

            direct_call(function()
                ImGui.BgAddImageRotated(srv, xPx, yPx, wPx, hPx, 0.0, alpha)
            end)
        end)
    end)

    if ok then
        minigames.IntroLogo.handlerRegistered = true
        if minigames.LogInfo then
            minigames.LogInfo("[Intro Logo] ON_PRESENT image renderer registered.")
        end
    end
end

minigames.IntroLogo.RegisterPresentHandler()

function minigames.IntroLogo.DrawFallbackMark(alpha)
    -- only used if image rendering is unavailable. keeps the intro nice instead of blank.
    if minigames.S.introImageFallbackText == false then return end
    if not minigames.DrawRect or not minigames.DrawText then return end

    local pulse = math.sin((minigames.Now and minigames.Now() or 0) * 0.004) * 0.5 + 0.5
    local red = math.floor(165 + 70 * pulse)

    minigames.DrawRect(0.5, 0.305, 0.42, 0.15, 25, 0, 0, math.floor(alpha * 0.20))
    minigames.DrawRect(0.5, 0.380, 0.34, 0.006, red, 20, 20, math.floor(alpha * 0.70))
    minigames.DrawText("★  🕹  ♛", 0.5, 0.280, 0.58, red, 45, 45, math.floor(alpha * 0.88), 7)
end



