-- v0.124 feature-backed intro tuning helpers
------------------------------------------------------------
function minigames.IntroLogo.ToInt1000(value, fallback)
    value = tonumber(value)
    if value == nil then value = fallback end
    value = tonumber(value) or 0
    return math.floor(value * 1000 + 0.5)
end

function minigames.IntroLogo.FromInt1000(value, fallback)
    value = tonumber(value)
    if value == nil then return fallback end
    return value / 1000.0
end

function minigames.IntroLogo.ReadIntFeature(hash, fallback)
    if not hash or not minigames.GetFeatureInt then return fallback end
    return minigames.GetFeatureInt(hash, fallback)
end

function minigames.IntroLogo.RefreshTuningFromFeatures()
    if not minigames.H or not FeatureMgr then return end

    local function f1000(hash, current)
        return minigames.IntroLogo.FromInt1000(minigames.IntroLogo.ReadIntFeature(hash, minigames.IntroLogo.ToInt1000(current, current)), current)
    end

    minigames.S.introBgX = f1000(minigames.H.INTRO_BG_X, minigames.S.introBgX or 0.500)
    minigames.S.introBgY = f1000(minigames.H.INTRO_BG_Y, minigames.S.introBgY or 0.380)
    minigames.S.introBgAlpha = f1000(minigames.H.INTRO_BG_ALPHA, minigames.S.introBgAlpha or 0.100)

    minigames.S.introLogoX = f1000(minigames.H.INTRO_IMAGE_X, minigames.S.introLogoX or 0.500)
    minigames.S.introLogoY = f1000(minigames.H.INTRO_IMAGE_Y, minigames.S.introLogoY or 0.345)
    minigames.S.introLogoWidth = f1000(minigames.H.INTRO_IMAGE_W, minigames.S.introLogoWidth or 0.400)

    minigames.S.introTitleX = f1000(minigames.H.INTRO_TITLE_X, minigames.S.introTitleX or 0.500)
    minigames.S.introTitleY = f1000(minigames.H.INTRO_TITLE_Y, minigames.S.introTitleY or 0.525)

    minigames.S.introSubtitleX = f1000(minigames.H.INTRO_SUBTITLE_X, minigames.S.introSubtitleX or 0.500)
    minigames.S.introSubtitleY = f1000(minigames.H.INTRO_SUBTITLE_Y, minigames.S.introSubtitleY or 0.595)

    minigames.S.introModesX = f1000(minigames.H.INTRO_MODES_X, minigames.S.introModesX or 0.500)
    minigames.S.introModesY = f1000(minigames.H.INTRO_MODES_Y, minigames.S.introModesY or 0.650)

    minigames.S.introRedLineX = f1000(minigames.H.INTRO_REDLINE_X, minigames.S.introRedLineX or 0.500)
    minigames.S.introRedLineY = f1000(minigames.H.INTRO_REDLINE_Y, minigames.S.introRedLineY or 0.633)
    minigames.S.introRedLineW = f1000(minigames.H.INTRO_REDLINE_W, minigames.S.introRedLineW or 0.425)

    minigames.S.introDevX = f1000(minigames.H.INTRO_DEV_X, minigames.S.introDevX or 0.500)
    minigames.S.introDevY = f1000(minigames.H.INTRO_DEV_Y, minigames.S.introDevY or 0.670)
end

function minigames.IntroLogo.StartIntro(reason)
    minigames.S.introEnabled = true
    minigames.S.introStartMs = minigames.Now and minigames.Now() or 0
    minigames.IntroLogo.pending = nil

    if minigames.LogInfo then
        minigames.LogInfo("[Intro Logo] Start intro requested | reason=" .. tostring(reason or "Manual Test"))
    end

    if minigames.Toast then
        minigames.Toast("Minigames Intro", "Intro started.", 2500)
    end
end

function minigames.DrawIntro()
    if minigames.S.introEnabled == false then
        minigames.IntroLogo.pending = nil
        return
    end

    if minigames.IntroLogo and minigames.IntroLogo.RefreshTuningFromFeatures then
        minigames.IntroLogo.RefreshTuningFromFeatures()
    end

    local now = minigames.Now and minigames.Now() or 0
    if not minigames.S.introStartMs or minigames.S.introStartMs == 0 then
        minigames.S.introStartMs = now
    end

    local duration = minigames.S.introDurationMs or 7200
    local fadeStart = minigames.S.introFadeStartMs or 2800
    local elapsed = now - minigames.S.introStartMs

    if elapsed > duration then
        minigames.IntroLogo.pending = nil
        return
    end

    local alpha = 255
    if elapsed > fadeStart then
        local fadeElapsed = elapsed - fadeStart
        local fadeDuration = duration - fadeStart
        if fadeDuration <= 0 then
            alpha = 0
        else
            alpha = math.floor(math.max(0, math.min(255, 255 * (1.0 - fadeElapsed / fadeDuration))))
        end
    end

    local pulse = math.sin(now * 0.004) * 0.5 + 0.5
    local red = math.floor(190 + 65 * pulse)

    -- tunable alpha background / panel.
    if minigames.DrawRect then
        minigames.DrawRect(
            minigames.S.introBgX or 0.5,
            minigames.S.introBgY or 0.415,
            minigames.S.introBgW or 0.72,
            minigames.S.introBgH or 0.52,
            8, 0, 0,
            math.floor(alpha * (minigames.S.introBgAlpha or 0.10))
        )

        -- tunable red separator line.
        minigames.DrawRect(
            minigames.S.introRedLineX or 0.5,
            minigames.S.introRedLineY or 0.633,
            minigames.S.introRedLineW or 0.43,
            minigames.S.introRedLineH or 0.006,
            red, 20, 20,
            math.floor(alpha * (minigames.S.introRedLineAlpha or 0.70))
        )
    end

    -- tunable image on top.
    minigames.IntroLogo.QueueLogo(minigames.S.introLogoX, minigames.S.introLogoY, minigames.S.introLogoWidth, alpha)

    -- fallback marker if the png renderer is unavailable or rejected the texture.
    if not minigames.IntroLogo.textureSrv and
        (not Texture or not ImGui or minigames.IntroLogo.textureLoadFailed == true) then
        minigames.IntroLogo.DrawFallbackMark(alpha)
    end

    -- tunable text stack.
    if minigames.DrawText then
        minigames.DrawText(
            "MiniGames",
            minigames.S.introTitleX or 0.5,
            minigames.S.introTitleY or 0.555,
            minigames.S.introTitleScale or 1.04,
            red, 30, 30, alpha, 7
        )

        minigames.DrawText(
            minigames.SUBTITLE or "Turn the lobby into your personal playground.",
            minigames.S.introSubtitleX or 0.5,
            minigames.S.introSubtitleY or 0.625,
            minigames.S.introSubtitleScale or 0.40,
            255, 245, 245, alpha, 4
        )

        minigames.DrawText(
            minigames.S.introModesText or "WarGames - The Purge - Land On It - DriftGod - Beast",
            minigames.S.introModesX or 0.5,
            minigames.S.introModesY or 0.680,
            minigames.S.introModesScale or 0.285,
            255, 125, 125, math.floor(alpha * 0.84), 4
        )

        minigames.DrawText(
            minigames.S.introDevText or "Developed by Public Urinal",
            minigames.S.introDevX or 0.5,
            minigames.S.introDevY or 0.725,
            minigames.S.introDevScale or 0.250,
            255, 210, 210, math.floor(alpha * (minigames.S.introDevAlpha or 0.72)), 4
        )
    end
end

function minigames.ResetIntro()
    if minigames.IntroLogo and minigames.IntroLogo.StartIntro then
        minigames.IntroLogo.StartIntro("ResetIntro")
    else
        minigames.S.introStartMs = minigames.Now and minigames.Now() or 0
        minigames.IntroLogo.pending = nil
    end
end

if minigames.LogInfo then
    minigames.LogInfo("[Intro Logo] v0.124 loaded | tunable image/title/subtitle/modes/dev-credit intro active.")
end


