-- ============================================================
-- embedded module: systems\peacekeeper.lua
-- ============================================================
embedded_modules['systems\\peacekeeper.lua'] = function()
--[[
    minigames/systems/peacekeeper.lua
    build: v0.171-alpha

    wargames peacekeeper / no cops system.

    goal:
    - keep wargames from being ruined by cops.
    - automatically enabled by activate wargames systems and no-bounty mode.
    - native wanted-level control is strongest for the local player.
    - for other players, this does best-effort built-in feature attempts plus local hostile/cops suppression.
]]

minigames.Peacekeeper = minigames.Peacekeeper or {}

minigames.Peacekeeper.FeatureNames = {
    "Never Wanted",
    "Never wanted",
    "No Wanted",
    "No wanted",
    "Turn Blind Eye",
    "Turn blind eye",
    "Cops Turn Blind Eye",
    "Police Ignore Player",
    "Police Ignore",
    "Remove Wanted Level",
    "Clear Wanted Level"
}

function minigames.Peacekeeper.ApplyLocalNeverWanted(reason)
    local playerId = minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or 0
    local calls = 0
    local failed = 0

    local function call(label, fn)
        local ok, err = direct_call(fn)
        calls = calls + 1
        if not ok then
            failed = failed + 1
            minigames.S.lastPeacekeeperError = tostring(label) .. ": " .. tostring(err)
        end
    end

    if PLAYER then
        if PLAYER.SET_MAX_WANTED_LEVEL then
            call("SET_MAX_WANTED_LEVEL", function()
                PLAYER.SET_MAX_WANTED_LEVEL(0)
            end)
        end

        if PLAYER.SET_WANTED_LEVEL_MULTIPLIER then
            call("SET_WANTED_LEVEL_MULTIPLIER", function()
                PLAYER.SET_WANTED_LEVEL_MULTIPLIER(0.0)
            end)
        end

        if PLAYER.SET_PLAYER_WANTED_LEVEL then
            call("SET_PLAYER_WANTED_LEVEL", function()
                PLAYER.SET_PLAYER_WANTED_LEVEL(playerId, 0, false)
            end)
        end

        if PLAYER.SET_PLAYER_WANTED_LEVEL_NO_DROP then
            call("SET_PLAYER_WANTED_LEVEL_NO_DROP", function()
                PLAYER.SET_PLAYER_WANTED_LEVEL_NO_DROP(playerId, 0, false)
            end)
        end

        if PLAYER.SET_PLAYER_WANTED_LEVEL_NOW then
            call("SET_PLAYER_WANTED_LEVEL_NOW", function()
                PLAYER.SET_PLAYER_WANTED_LEVEL_NOW(playerId, false)
            end)
        end

        if PLAYER.CLEAR_PLAYER_WANTED_LEVEL then
            call("CLEAR_PLAYER_WANTED_LEVEL", function()
                PLAYER.CLEAR_PLAYER_WANTED_LEVEL(playerId)
            end)
        end

        if PLAYER.SET_POLICE_IGNORE_PLAYER then
            call("SET_POLICE_IGNORE_PLAYER", function()
                PLAYER.SET_POLICE_IGNORE_PLAYER(playerId, true)
            end)
        end

        if PLAYER.SET_EVERYONE_IGNORE_PLAYER then
            call("SET_EVERYONE_IGNORE_PLAYER", function()
                PLAYER.SET_EVERYONE_IGNORE_PLAYER(playerId, true)
            end)
        end

        if PLAYER.SET_DISPATCH_COPS_FOR_PLAYER then
            call("SET_DISPATCH_COPS_FOR_PLAYER", function()
                PLAYER.SET_DISPATCH_COPS_FOR_PLAYER(playerId, false)
            end)
        end
    end

    minigames.S.lastPeacekeeperLocalStatus =
        "Local never wanted | calls=" ..
        tostring(calls) ..
        " failed=" ..
        tostring(failed) ..
        " reason=" ..
        tostring(reason or "Manual")

    return failed == 0, calls, failed
end

function minigames.Peacekeeper.TryBuiltInForPlayer(playerId, reason)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if not FeatureMgr or not FeatureMgr.GetFeatureByName then
        return false, "GetFeatureByName missing"
    end

    for _, name in ipairs(minigames.Peacekeeper.FeatureNames) do
        local feature = nil
        local okGet = direct_call(function()
            feature = FeatureMgr.GetFeatureByName(name, playerId)
        end)

        if okGet and feature ~= nil then
            local okSet = false
            local setErr = nil

            if feature.SetBoolValue then
                okSet, setErr = direct_call(function()
                    feature:SetBoolValue(true)
                end)
            end

            if not okSet and feature.Toggle then
                okSet, setErr = direct_call(function()
                    feature:Toggle()
                end)
            end

            if not okSet and feature.TriggerCallback then
                okSet, setErr = direct_call(function()
                    feature:TriggerCallback()
                end)
            end

            if okSet then
                minigames.S.lastPeacekeeperBuiltInMethod = tostring(name)
                minigames.S.lastPeacekeeperBuiltInTarget = playerId
                minigames.LogInfo("[Peacekeeper] Built-in applied | feature=" .. tostring(name) .. " | player=" .. tostring(playerId) .. " | reason=" .. tostring(reason or "Manual"))
                return true, name
            else
                minigames.S.lastPeacekeeperError = "Built-in found but failed | feature=" .. tostring(name) .. " | err=" .. tostring(setErr)
            end
        end
    end

    return false, "no matching built-in feature"
end

function minigames.Peacekeeper.ApplyToPlayer(playerId, reason)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if not minigames.IsPlayerActive(playerId) then
        return false, "inactive"
    end

    local applied = false
    local status = "none"

    if minigames.IsSelf and minigames.IsSelf(playerId) then
        local ok = minigames.Peacekeeper.ApplyLocalNeverWanted(reason)
        applied = ok == true
        status = minigames.S.lastPeacekeeperLocalStatus or "local"
    end

    -- best effort for every selected/remote player through cherax built-ins.
    local okBuiltIn, builtInStatus = minigames.Peacekeeper.TryBuiltInForPlayer(playerId, reason)
    if okBuiltIn then
        applied = true
        status = "built-in: " .. tostring(builtInStatus)
    end

    minigames.Player.peacekeeperApplied = minigames.Player.peacekeeperApplied or {}
    minigames.Player.peacekeeperAppliedAtMs = minigames.Player.peacekeeperAppliedAtMs or {}
    minigames.Player.peacekeeperStatus = minigames.Player.peacekeeperStatus or {}

    minigames.Player.peacekeeperApplied[playerId] = applied
    minigames.Player.peacekeeperAppliedAtMs[playerId] = minigames.Now()
    minigames.Player.peacekeeperStatus[playerId] = status

    return applied, status
end

function minigames.Peacekeeper.ApplyToAll(reason)
    minigames.RefreshPlayers()

    local applied = 0
    local failed = 0
    local skipped = 0

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        local ok, status = minigames.Peacekeeper.ApplyToPlayer(playerId, reason or "Apply All")

        if ok then
            applied = applied + 1
        elseif status == "inactive" then
            skipped = skipped + 1
        else
            failed = failed + 1
        end
    end

    minigames.S.lastPeacekeeperStatus =
        "Peacekeeper apply all | applied=" ..
        tostring(applied) ..
        " failed=" ..
        tostring(failed) ..
        " skipped=" ..
        tostring(skipped) ..
        " reason=" ..
        tostring(reason or "Manual")

    minigames.LogInfo("[Peacekeeper] " .. minigames.S.lastPeacekeeperStatus)
    return applied, failed, skipped
end

function minigames.Peacekeeper.DisableLocal(reason)
    local playerId = minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or 0

    direct_call(function()
        if PLAYER and PLAYER.SET_MAX_WANTED_LEVEL then
            PLAYER.SET_MAX_WANTED_LEVEL(5)
        end
    end)

    direct_call(function()
        if PLAYER and PLAYER.SET_WANTED_LEVEL_MULTIPLIER then
            PLAYER.SET_WANTED_LEVEL_MULTIPLIER(1.0)
        end
    end)

    direct_call(function()
        if PLAYER and PLAYER.SET_POLICE_IGNORE_PLAYER then
            PLAYER.SET_POLICE_IGNORE_PLAYER(playerId, false)
        end
    end)

    direct_call(function()
        if PLAYER and PLAYER.SET_EVERYONE_IGNORE_PLAYER then
            PLAYER.SET_EVERYONE_IGNORE_PLAYER(playerId, false)
        end
    end)

    direct_call(function()
        if PLAYER and PLAYER.SET_DISPATCH_COPS_FOR_PLAYER then
            PLAYER.SET_DISPATCH_COPS_FOR_PLAYER(playerId, true)
        end
    end)

    minigames.S.lastPeacekeeperStatus = "Peacekeeper disabled locally | reason=" .. tostring(reason or "Manual")
    minigames.LogInfo("[Peacekeeper] " .. minigames.S.lastPeacekeeperStatus)
end

function minigames.Peacekeeper.Tick()
    if minigames.S.noCopsEnabled ~= true then
        return
    end

    local now = minigames.Now()
    local scanMs = minigames.S.peacekeeperScanMs or minigames.C.DEFAULT_PEACEKEEPER_SCAN_MS or 1000
    local last = minigames.S.lastPeacekeeperTickMs or 0

    if last ~= 0 and now - last < scanMs then
        return
    end

    minigames.S.lastPeacekeeperTickMs = now
    minigames.S.peacekeeperTickCount = (minigames.S.peacekeeperTickCount or 0) + 1

    -- local needs frequent native refresh to stay truly never wanted.
    minigames.Peacekeeper.ApplyLocalNeverWanted("Peacekeeper Tick")

    -- built-in remote attempts are throttled harder to avoid menu spam.
    local remoteLast = minigames.S.lastPeacekeeperRemoteApplyMs or 0
    local remoteInterval = minigames.S.peacekeeperRemoteApplyMs or 15000

    if remoteLast == 0 or now - remoteLast >= remoteInterval then
        minigames.S.lastPeacekeeperRemoteApplyMs = now
        minigames.Peacekeeper.ApplyToAll("Peacekeeper Remote Refresh")
    end
end

function minigames.Peacekeeper.PrintDebug()
    minigames.RefreshPlayers()

    minigames.LogInfo("========== WarGames Peacekeeper Debug ==========")
    minigames.LogInfo("No Cops Enabled: " .. tostring(minigames.S.noCopsEnabled))
    minigames.LogInfo("Peacekeeper Tick Count: " .. tostring(minigames.S.peacekeeperTickCount or 0))
    minigames.LogInfo("Peacekeeper Scan MS: " .. tostring(minigames.S.peacekeeperScanMs or minigames.C.DEFAULT_PEACEKEEPER_SCAN_MS))
    minigames.LogInfo("Remote Apply MS: " .. tostring(minigames.S.peacekeeperRemoteApplyMs or 15000))
    minigames.LogInfo("Last Status: " .. tostring(minigames.S.lastPeacekeeperStatus))
    minigames.LogInfo("Last Local: " .. tostring(minigames.S.lastPeacekeeperLocalStatus))
    minigames.LogInfo("Last Built-in Method: " .. tostring(minigames.S.lastPeacekeeperBuiltInMethod))
    minigames.LogInfo("Last Error: " .. tostring(minigames.S.lastPeacekeeperError))

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        minigames.LogInfo(
            "player=" .. tostring(playerId) ..
            " name=" .. minigames.GetPlayerName(playerId) ..
            " status=" .. tostring(minigames.Player.peacekeeperStatus and minigames.Player.peacekeeperStatus[playerId] or "None")
        )
    end

    minigames.LogInfo("===============================================")
    minigames.Toast("Peacekeeper Debug", "Printed no-cops debug to log.", 3500)
end
end

-- ============================================================
-- embedded module: systems\pedwars_entity_cleanup.lua
-- ============================================================
embedded_modules['systems\\pedwars_entity_cleanup.lua'] = function()
--[[
    minigames / wargames - pedwars-style entity cleanup engine
    v0.171-alpha

    purpose:
    - replace the unstable wargames cleanup/fairness helpers with a slower,
      detector-first cleanup layer inspired by the pedwars approach.
    - do not mass delete.
    - do not run hard deletes in the same frame as respawn spawns.
    - do not interfere with respawn queue.
    - only process tracked wargames vehicles.
]]

minigames = minigames or {}
minigames.PWCleanup = minigames.PWCleanup or {}

------------------------------------------------------------
-- helpers
------------------------------------------------------------

function minigames.PWCleanup.Now()
    if minigames.Now then return minigames.Now() end
    if os and os.clock then return math.floor(os.clock() * 1000) end
    return 0
end

function minigames.PWCleanup.Log(msg)
    if minigames.LogInfo then
        minigames.LogInfo("[PedWars Cleanup] " .. tostring(msg))
    end
end

function minigames.PWCleanup.LogError(msg)
    if minigames.LogError then
        minigames.LogError("[PedWars Cleanup] " .. tostring(msg))
    elseif minigames.LogInfo then
        minigames.LogInfo("[PedWars Cleanup ERROR] " .. tostring(msg))
    end
end

function minigames.PWCleanup.DoesEntityExist(entity)
    if not entity or entity == 0 then return false end

    if ENTITY and ENTITY.DOES_ENTITY_EXIST then
        local ok, exists = direct_call(function()
            return ENTITY.DOES_ENTITY_EXIST(entity)
        end)
        return ok and exists == true
    end

    return true
end

function minigames.PWCleanup.IsVehicleDestroyed(entity)
    if not minigames.PWCleanup.DoesEntityExist(entity) then
        return true, "missing"
    end

    if ENTITY and ENTITY.IS_ENTITY_DEAD then
        local ok, dead = direct_call(function()
            return ENTITY.IS_ENTITY_DEAD(entity, false)
        end)
        if ok and dead == true then
            return true, "entity_dead"
        end
    end

    if VEHICLE and VEHICLE.IS_VEHICLE_DRIVEABLE then
        local ok, driveable = direct_call(function()
            return VEHICLE.IS_VEHICLE_DRIVEABLE(entity, false)
        end)
        if ok and driveable == false then
            return true, "not_driveable"
        end
    end

    if VEHICLE and VEHICLE.GET_VEHICLE_ENGINE_HEALTH then
        local ok, health = direct_call(function()
            return VEHICLE.GET_VEHICLE_ENGINE_HEALTH(entity)
        end)
        if ok and tonumber(health) and tonumber(health) <= -3500 then
            return true, "engine_destroyed"
        end
    end

    return false, "alive"
end

function minigames.PWCleanup.GetCoords(entity)
    if not minigames.PWCleanup.DoesEntityExist(entity) then
        return nil
    end

    if ENTITY and ENTITY.GET_ENTITY_COORDS then
        local ok, coords = direct_call(function()
            return ENTITY.GET_ENTITY_COORDS(entity, true)
        end)
        if ok and coords then
            return coords
        end
    end

    return nil
end

function minigames.PWCleanup.Distance(a, b)
    if not a or not b then return 999999.0 end
    local ax = tonumber(a.x or a[1] or 0) or 0
    local ay = tonumber(a.y or a[2] or 0) or 0
    local az = tonumber(a.z or a[3] or 0) or 0
    local bx = tonumber(b.x or b[1] or 0) or 0
    local by = tonumber(b.y or b[2] or 0) or 0
    local bz = tonumber(b.z or b[3] or 0) or 0
    local dx, dy, dz = ax - bx, ay - by, az - bz
    return math.sqrt(dx * dx + dy * dy + dz * dz)
end

function minigames.PWCleanup.GetPlayerPed(playerId)
    if minigames.GetPlayerPed then
        local ok, ped = direct_call(minigames.GetPlayerPed, playerId)
        if ok then return ped end
    end

    if PLAYER and PLAYER.GET_PLAYER_PED then
        local ok, ped = direct_call(function()
            return PLAYER.GET_PLAYER_PED(playerId)
        end)
        if ok then return ped end
    end

    return 0
end

function minigames.PWCleanup.IsPlayerUsingVehicle(playerId, entity)
    if not entity or entity == 0 then return false end

    local ped = minigames.PWCleanup.GetPlayerPed(playerId)
    if not ped or ped == 0 then return false end

    if PED and PED.IS_PED_IN_VEHICLE then
        local ok, inside = direct_call(function()
            return PED.IS_PED_IN_VEHICLE(ped, entity, false)
        end)
        if ok and inside == true then
            return true
        end
    end

    if PED and PED.GET_VEHICLE_PED_IS_IN then
        local ok, veh = direct_call(function()
            return PED.GET_VEHICLE_PED_IS_IN(ped, false)
        end)
        if ok and veh == entity then
            return true
        end
    end

    return false
end

function minigames.PWCleanup.AnyPlayerUsingVehicle(entity)
    if not entity or entity == 0 then return false, nil end

    local players = {}

    if minigames.S and type(minigames.S.activePlayers) == "table" then
        for _, id in ipairs(minigames.S.activePlayers) do table.insert(players, id) end
    elseif minigames.GetActivePlayers then
        local ok, list = direct_call(minigames.GetActivePlayers)
        if ok and type(list) == "table" then players = list end
    end

    for _, id in ipairs(players) do
        if minigames.PWCleanup.IsPlayerUsingVehicle(tonumber(id) or 0, entity) then
            return true, tonumber(id) or 0
        end
    end

    return false, nil
end

------------------------------------------------------------
-- tracking normalization
------------------------------------------------------------

function minigames.PWCleanup.EnsureTracking()
    minigames.S = minigames.S or {}
    minigames.S.trackedVehicles = minigames.S.trackedVehicles or {}
    minigames.S.pedwarsCleanupQueue = minigames.S.pedwarsCleanupQueue or {}
    minigames.S.pedwarsCleanupStats = minigames.S.pedwarsCleanupStats or {
        scanned = 0,
        queued = 0,
        deleted = 0,
        missing = 0,
        skippedUsed = 0,
        skippedYoung = 0,
        skippedLive = 0,
        failed = 0
    }
end

function minigames.PWCleanup.MarkSpawnedVehicle(entity, playerId, vehicleLabel, method)
    minigames.PWCleanup.EnsureTracking()

    if not entity or entity == 0 then
        return nil
    end

    minigames.S.nextTrackedVehicleId = (minigames.S.nextTrackedVehicleId or 0) + 1
    local id = minigames.S.nextTrackedVehicleId
    local now = minigames.PWCleanup.Now()

    local entry = {
        id = id,
        entity = entity,
        playerId = playerId,
        player = playerId,
        owner = minigames.GetPlayerName and minigames.GetPlayerName(playerId) or tostring(playerId),
        vehicle = vehicleLabel or "Unknown",
        method = method or "unknown",
        createdMs = now,
        lastSeenMs = now,
        lastUsedMs = 0,
        lastCoords = minigames.PWCleanup.GetCoords(entity),
        source = "WarGames",
        cleanupEngine = "PedWarsStyle"
    }

    minigames.S.trackedVehicles[id] = entry

    minigames.PWCleanup.Log(
        "tracked | id=" .. tostring(id) ..
        " | entity=" .. tostring(entity) ..
        " | player=" .. tostring(playerId) ..
        " | owner=" .. tostring(entry.owner) ..
        " | vehicle=" .. tostring(entry.vehicle) ..
        " | method=" .. tostring(method or "unknown")
    )

    return id
end

------------------------------------------------------------
-- detection
------------------------------------------------------------

function minigames.PWCleanup.ShouldQueueDelete(entry, now)
    if not entry then return false, "empty_entry" end

    local entity = entry.entity or entry.handle or entry.vehicleHandle
    if not entity or entity == 0 then return true, "empty_entity" end

    if not minigames.PWCleanup.DoesEntityExist(entity) then
        return true, "missing"
    end

    local destroyed, destroyedReason = minigames.PWCleanup.IsVehicleDestroyed(entity)
    if destroyed then
        return true, destroyedReason
    end

    local used, usedBy = minigames.PWCleanup.AnyPlayerUsingVehicle(entity)
    if used then
        entry.lastUsedMs = now
        return false, "used_by_" .. tostring(usedBy)
    end

    local age = now - (entry.createdMs or now)
    local unusedFor = entry.lastUsedMs and entry.lastUsedMs > 0 and (now - entry.lastUsedMs) or age

    -- keep young vehicles alive so respawn spawns are never instantly cleaned.
    local minAge = minigames.S.pedwarsCleanupMinAgeMs or 120000
    if age < minAge then
        return false, "young"
    end

    -- optional abandoned cleanup, off by default unless user enables it.
    if minigames.S.pedwarsCleanupDeleteAbandoned == true then
        local abandonedMs = minigames.S.pedwarsCleanupAbandonedMs or 180000
        if unusedFor >= abandonedMs then
            return true, "abandoned"
        end
    end

    return false, "live"
end

function minigames.PWCleanup.ScanTrackedVehicles(reason)
    minigames.PWCleanup.EnsureTracking()

    if minigames.S.pedwarsCleanupEnabled ~= true then
        return "disabled"
    end

    local now = minigames.PWCleanup.Now()
    local scanned, queued, missing, skippedUsed, skippedYoung, skippedLive = 0, 0, 0, 0, 0, 0

    for key, entry in pairs(minigames.S.trackedVehicles) do
        scanned = scanned + 1

        local shouldDelete, why = minigames.PWCleanup.ShouldQueueDelete(entry, now)

        if shouldDelete then
            if why == "missing" then missing = missing + 1 end
            minigames.PWCleanup.QueueDelete(key, entry, why, reason or "scan")
            queued = queued + 1
        else
            if tostring(why):find("used_by_") then
                skippedUsed = skippedUsed + 1
            elseif why == "young" then
                skippedYoung = skippedYoung + 1
            else
                skippedLive = skippedLive + 1
            end
        end
    end

    minigames.S.pedwarsCleanupStats.scanned = (minigames.S.pedwarsCleanupStats.scanned or 0) + scanned
    minigames.S.pedwarsCleanupStats.queued = (minigames.S.pedwarsCleanupStats.queued or 0) + queued
    minigames.S.pedwarsCleanupStats.missing = (minigames.S.pedwarsCleanupStats.missing or 0) + missing
    minigames.S.pedwarsCleanupStats.skippedUsed = (minigames.S.pedwarsCleanupStats.skippedUsed or 0) + skippedUsed
    minigames.S.pedwarsCleanupStats.skippedYoung = (minigames.S.pedwarsCleanupStats.skippedYoung or 0) + skippedYoung
    minigames.S.pedwarsCleanupStats.skippedLive = (minigames.S.pedwarsCleanupStats.skippedLive or 0) + skippedLive

    local msg =
        "scan | scanned=" .. tostring(scanned) ..
        " queued=" .. tostring(queued) ..
        " missing=" .. tostring(missing) ..
        " used=" .. tostring(skippedUsed) ..
        " young=" .. tostring(skippedYoung) ..
        " live=" .. tostring(skippedLive) ..
        " queue=" .. tostring(#minigames.S.pedwarsCleanupQueue) ..
        " reason=" .. tostring(reason or "manual")

    minigames.S.lastPedWarsCleanupStatus = msg
    minigames.PWCleanup.Log(msg)

    return msg
end

------------------------------------------------------------
-- delete queue
------------------------------------------------------------

function minigames.PWCleanup.QueueDelete(key, entry, why, reason)
    minigames.PWCleanup.EnsureTracking()

    if not entry then return false end

    if entry.pwDeleteQueued == true then
        return false
    end

    entry.pwDeleteQueued = true
    entry.pwDeleteReason = why

    table.insert(minigames.S.pedwarsCleanupQueue, {
        key = key,
        entry = entry,
        entity = entry.entity or entry.handle or entry.vehicleHandle,
        reason = why,
        sourceReason = reason,
        queuedMs = minigames.PWCleanup.Now()
    })

    return true
end

function minigames.PWCleanup.DeleteEntityPointerSafe(entity)
    if not entity or entity == 0 then return false, "empty" end

    if not minigames.PWCleanup.DoesEntityExist(entity) then
        return false, "missing"
    end

    -- avoid the risky mission-entity path by default.
    -- previous fatal logs pointed near hard delete / mission entity flows.
    if minigames.S.pedwarsCleanupUseMissionEntity == true and ENTITY and ENTITY.SET_ENTITY_AS_MISSION_ENTITY then
        direct_call(function()
            ENTITY.SET_ENTITY_AS_MISSION_ENTITY(entity, true, true)
        end)
    end

    if ENTITY and ENTITY.DELETE_ENTITY and Memory and Memory.AllocInt and Memory.WriteInt then
        local ok, err = direct_call(function()
            local ptr = Memory.AllocInt()
            Memory.WriteInt(ptr, entity)
            ENTITY.DELETE_ENTITY(ptr)
        end)

        if ok then
            return true, "delete_entity_ptr"
        end

        return false, "delete_failed:" .. tostring(err)
    end

    if entities and entities.delete_by_handle then
        local ok, err = direct_call(function()
            entities.delete_by_handle(entity)
        end)

        if ok then
            return true, "entities_delete_by_handle"
        end

        return false, "entities_delete_failed:" .. tostring(err)
    end

    return false, "no_delete_method"
end

function minigames.PWCleanup.ProcessDeleteQueue(reason)
    minigames.PWCleanup.EnsureTracking()

    if minigames.S.pedwarsCleanupEnabled ~= true then
        return "disabled"
    end

    local now = minigames.PWCleanup.Now()
    local last = minigames.S.pedwarsCleanupLastDeleteMs or 0
    local gap = minigames.S.pedwarsCleanupDeleteGapMs or 850

    if last ~= 0 and now - last < gap then
        return "cooldown"
    end

    local item = table.remove(minigames.S.pedwarsCleanupQueue, 1)
    if not item then
        return "empty"
    end

    minigames.S.pedwarsCleanupLastDeleteMs = now

    local entity = item.entity
    local ok, status = minigames.PWCleanup.DeleteEntityPointerSafe(entity)

    if ok or status == "missing" then
        minigames.S.trackedVehicles[item.key] = nil
        minigames.S.pedwarsCleanupStats.deleted = (minigames.S.pedwarsCleanupStats.deleted or 0) + (ok and 1 or 0)

        minigames.PWCleanup.Log(
            "delete processed | ok=" .. tostring(ok) ..
            " | status=" .. tostring(status) ..
            " | entity=" .. tostring(entity) ..
            " | reason=" .. tostring(item.reason) ..
            " | queue=" .. tostring(#minigames.S.pedwarsCleanupQueue)
        )
    else
        minigames.S.pedwarsCleanupStats.failed = (minigames.S.pedwarsCleanupStats.failed or 0) + 1
        if item.entry then
            item.entry.pwDeleteQueued = false
            item.entry.pwDeleteReason = nil
        end

        minigames.PWCleanup.LogError(
            "delete failed | status=" .. tostring(status) ..
            " | entity=" .. tostring(entity) ..
            " | reason=" .. tostring(item.reason)
        )
    end

    return status
end

------------------------------------------------------------
-- public replacements for old cleanup systems
------------------------------------------------------------

function minigames.PWCleanup.DeletePreviousVehicleTypeOnChange(previousVehicleLabel, reason)
    -- safe replacement:
    -- instead of deleting immediately on round change, mark matching old vehicles
    -- for queue processing. this prevents same-frame delete/spawn crashes.
    minigames.PWCleanup.EnsureTracking()

    if minigames.S.pedwarsCleanupEnabled ~= true then
        return "disabled"
    end

    local queued = 0

    for key, entry in pairs(minigames.S.trackedVehicles) do
        if entry and tostring(entry.vehicle) == tostring(previousVehicleLabel) then
            if minigames.PWCleanup.QueueDelete(key, entry, "previous_vehicle_type", reason or "round_change") then
                queued = queued + 1
            end
        end
    end

    local msg = "previous type queued | vehicle=" .. tostring(previousVehicleLabel) .. " | queued=" .. tostring(queued)
    minigames.PWCleanup.Log(msg)
    return msg
end

function minigames.PWCleanup.DeleteInactiveRoundVehicles(reason)
    -- safe replacement for "delete all inactive round vehicles".
    -- it scans and queues only destroyed/missing/abandoned vehicles.
    return minigames.PWCleanup.ScanTrackedVehicles(reason or "inactive_round_scan")
end

function minigames.PWCleanup.CleanupEmptyVehicles(reason)
    -- safe replacement for "auto delete empty spawned vehicles after 2 min".
    minigames.S.pedwarsCleanupDeleteAbandoned = true
    minigames.S.pedwarsCleanupAbandonedMs = minigames.S.pedwarsCleanupAbandonedMs or 180000
    return minigames.PWCleanup.ScanTrackedVehicles(reason or "empty_vehicle_scan")
end

function minigames.PWCleanup.DestroyedOnlyCleanup(reason)
    -- safe replacement for "destroyed-only vehicle cleanup".
    -- since shouldqueuedelete always queues missing/destroyed, just scan without
    -- enabling abandoned cleanup.
    local old = minigames.S.pedwarsCleanupDeleteAbandoned
    minigames.S.pedwarsCleanupDeleteAbandoned = false
    local result = minigames.PWCleanup.ScanTrackedVehicles(reason or "destroyed_only_scan")
    minigames.S.pedwarsCleanupDeleteAbandoned = old
    return result
end

function minigames.PWCleanup.PreventRespawnVehicleSpam(playerId, reason)
    -- safe replacement:
    -- do not block respawn. only prune stale/missing tracking records.
    return minigames.PWCleanup.ScanTrackedVehicles(reason or "respawn_spam_soft_prune")
end

function minigames.PWCleanup.Tick()
    if minigames.S.pedwarsCleanupEnabled ~= true then
        return
    end

    local now = minigames.PWCleanup.Now()

    local scanGap = minigames.S.pedwarsCleanupScanGapMs or 15000
    if (minigames.S.pedwarsCleanupLastScanMs or 0) == 0 or now - minigames.S.pedwarsCleanupLastScanMs >= scanGap then
        minigames.S.pedwarsCleanupLastScanMs = now
        minigames.PWCleanup.ScanTrackedVehicles("scheduled")
    end

    minigames.PWCleanup.ProcessDeleteQueue("scheduled")
end

function minigames.PWCleanup.Status()
    minigames.PWCleanup.EnsureTracking()

    local tracked = 0
    for _, _ in pairs(minigames.S.trackedVehicles) do tracked = tracked + 1 end

    local stats = minigames.S.pedwarsCleanupStats or {}
    local msg =
        "enabled=" .. tostring(minigames.S.pedwarsCleanupEnabled) ..
        " | tracked=" .. tostring(tracked) ..
        " | queue=" .. tostring(#minigames.S.pedwarsCleanupQueue) ..
        " | deleted=" .. tostring(stats.deleted or 0) ..
        " | failed=" .. tostring(stats.failed or 0) ..
        " | scanned=" .. tostring(stats.scanned or 0) ..
        " | last=" .. tostring(minigames.S.lastPedWarsCleanupStatus or "none")

    minigames.PWCleanup.Log("status | " .. msg)

    if minigames.Toast then
        minigames.Toast("PedWars Cleanup", msg, 6000)
    end

    return msg
end

minigames.PWCleanup.Log("loaded PedWars-style cleanup engine v0.171-alpha")


------------------------------------------------------------
-- v0.119 cleanup / fairness replacement api
------------------------------------------------------------
function minigames.PWCleanup.ReplaceCleanupFairnessSectionStatus()
    return minigames.PWCleanup.Status()
end

function minigames.PWCleanup.LegacySystemsReplacedNotice()
    local msg =
        "Legacy cleanup helpers replaced by PedWars-style cleanup | " ..
        "oldRoundCleanup=false | oldSpamPrevention=false | oldAutoSpawnAll=false"

    minigames.PWCleanup.Log(msg)
    return msg
end

------------------------------------------------------------
-- v0.127 vehicle tracking cleanup bridge
------------------------------------------------------------
local __mg127_pw_process_delete_queue = minigames.PWCleanup.ProcessDeleteQueue
function minigames.PWCleanup.ProcessDeleteQueue(reason)
    local before = nil
    if minigames.S and type(minigames.S.pedwarsCleanupQueue) == "table" and #minigames.S.pedwarsCleanupQueue > 0 then
        before = minigames.S.pedwarsCleanupQueue[1]
    end

    local status = __mg127_pw_process_delete_queue(reason)

    if before and before.entry and before.entry.id and minigames.VehicleTracking and minigames.VehicleTracking.MarkCleared then
        if status ~= "cooldown" and status ~= "empty" and status ~= "disabled" then
            minigames.VehicleTracking.MarkCleared(before.entry.id, "pedwars_cleanup_" .. tostring(status))
        end
    end
    return status
end
end

-- ============================================================
-- embedded module: systems\perks.lua
-- ============================================================
embedded_modules['systems\\perks.lua'] = function()
--[[
    minigames/systems/perks.lua
    build: v0.171-alpha

    loyalty / session-time rewards for wargames.

    current rewards:
    - 1 hour in session  = 3 minutes vehicle god mode
    - 2 hours in session = 5 minutes vehicle god mode
    - 3 hours in session = 10 minutes vehicle god mode

    when reward expires, the protected vehicle is deleted even if occupied.
]]

minigames.Perks = minigames.Perks or {}
minigames.Player.sessionJoinedAtMs = minigames.Player.sessionJoinedAtMs or {}
minigames.Player.loyaltyTierClaimed = minigames.Player.loyaltyTierClaimed or {}
minigames.Player.loyaltyGodVehicle = minigames.Player.loyaltyGodVehicle or {}
minigames.Player.loyaltyGodUntilMs = minigames.Player.loyaltyGodUntilMs or {}
minigames.Player.loyaltyPendingRewardMs = minigames.Player.loyaltyPendingRewardMs or {}

function minigames.Perks.Log(msg)
    minigames.LogInfo("[WarGames Perks] " .. tostring(msg))
end

function minigames.Perks.GetPlayerSessionMs(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)
    local now = minigames.Now()

    if not minigames.Player.sessionJoinedAtMs[playerId] or minigames.Player.sessionJoinedAtMs[playerId] == 0 then
        minigames.Player.sessionJoinedAtMs[playerId] = now
    end

    return now - minigames.Player.sessionJoinedAtMs[playerId]
end

function minigames.Perks.EnsurePlayer(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)
    minigames.InitPlayerState(playerId)

    if not minigames.Player.sessionJoinedAtMs[playerId] or minigames.Player.sessionJoinedAtMs[playerId] == 0 then
        minigames.Player.sessionJoinedAtMs[playerId] = minigames.Now()
        minigames.Player.loyaltyTierClaimed[playerId] = 0
        minigames.Player.loyaltyGodUntilMs[playerId] = 0
        minigames.Player.loyaltyGodVehicle[playerId] = 0
        minigames.Player.loyaltyPendingRewardMs[playerId] = 0
        minigames.Perks.Log("Tracking session time for " .. minigames.GetPlayerName(playerId))
    end
end

function minigames.Perks.GetRewardForElapsed(elapsedMs, claimedTier)
    claimedTier = tonumber(claimedTier) or 0

    if elapsedMs >= (minigames.S.loyaltyTier3Ms or 10800000) and claimedTier < 3 then
        return 3, minigames.S.loyaltyTier3RewardMs or 600000
    end

    if elapsedMs >= (minigames.S.loyaltyTier2Ms or 7200000) and claimedTier < 2 then
        return 2, minigames.S.loyaltyTier2RewardMs or 300000
    end

    if elapsedMs >= (minigames.S.loyaltyTier1Ms or 3600000) and claimedTier < 1 then
        return 1, minigames.S.loyaltyTier1RewardMs or 180000
    end

    return 0, 0
end

function minigames.Perks.GetCurrentVehicle(playerId)
    if minigames.FairVehicles and minigames.FairVehicles.GetPlayerCurrentVehicle then
        local veh = select(1, minigames.FairVehicles.GetPlayerCurrentVehicle(playerId))
        if veh and veh ~= 0 and minigames.EntityExists(veh) then
            return veh
        end
    end

    if minigames.GetPlayerVehicleIfAny then
        local veh = minigames.GetPlayerVehicleIfAny(playerId)
        if veh and veh ~= 0 and minigames.EntityExists(veh) then
            return veh
        end
    end

    return 0
end

function minigames.Perks.SetVehicleGodMode(vehicleEntity, enabled)
    if not vehicleEntity or vehicleEntity == 0 or not minigames.EntityExists(vehicleEntity) then
        return false
    end

    local ok = direct_call(function()
        if ENTITY and ENTITY.SET_ENTITY_AS_MISSION_ENTITY then
            ENTITY.SET_ENTITY_AS_MISSION_ENTITY(vehicleEntity, true, true)
        end

        if ENTITY and ENTITY.SET_ENTITY_INVINCIBLE then
            ENTITY.SET_ENTITY_INVINCIBLE(vehicleEntity, enabled == true)
        end

        if ENTITY and ENTITY.SET_ENTITY_PROOFS then
            ENTITY.SET_ENTITY_PROOFS(vehicleEntity, enabled == true, enabled == true, enabled == true, enabled == true, enabled == true, enabled == true, enabled == true, enabled == true)
        end

        if enabled == true and VEHICLE then
            if VEHICLE.SET_VEHICLE_FIXED then VEHICLE.SET_VEHICLE_FIXED(vehicleEntity) end
            if VEHICLE.SET_VEHICLE_ENGINE_HEALTH then VEHICLE.SET_VEHICLE_ENGINE_HEALTH(vehicleEntity, 1000.0) end
            if VEHICLE.SET_VEHICLE_BODY_HEALTH then VEHICLE.SET_VEHICLE_BODY_HEALTH(vehicleEntity, 1000.0) end
        end
    end)

    return ok == true
end

function minigames.Perks.ActivateVehicleGodMode(playerId, durationMs, tier)
    playerId = minigames.ClampInt(playerId, 0, 31)
    durationMs = tonumber(durationMs) or 180000

    local veh = minigames.Perks.GetCurrentVehicle(playerId)

    if not veh or veh == 0 then
        minigames.Player.loyaltyPendingRewardMs[playerId] = math.max(minigames.Player.loyaltyPendingRewardMs[playerId] or 0, durationMs)
        minigames.S.lastLoyaltyStatus = "Pending vehicle god mode for " .. minigames.GetPlayerName(playerId) .. " | tier=" .. tostring(tier)
        minigames.Perks.Log(minigames.S.lastLoyaltyStatus)
        return false, "pending_no_vehicle"
    end

    if minigames.Perks.SetVehicleGodMode(veh, true) then
        minigames.Player.loyaltyGodVehicle[playerId] = veh
        minigames.Player.loyaltyGodUntilMs[playerId] = minigames.Now() + durationMs
        minigames.Player.loyaltyPendingRewardMs[playerId] = 0

        minigames.S.lastLoyaltyStatus =
            "Activated vehicle god mode | player=" ..
            minigames.GetPlayerName(playerId) ..
            " | tier=" ..
            tostring(tier) ..
            " | durationMs=" ..
            tostring(durationMs)

        minigames.Toast("WarGames Loyalty Perk", minigames.GetPlayerName(playerId) .. " earned vehicle god mode for " .. tostring(math.floor(durationMs / 60000)) .. " min.", 6500)
        minigames.Perks.Log(minigames.S.lastLoyaltyStatus)
        return true, "active"
    end

    minigames.S.lastLoyaltyStatus = "Failed to apply vehicle god mode for " .. minigames.GetPlayerName(playerId)
    minigames.Perks.Log(minigames.S.lastLoyaltyStatus)
    return false, "apply_failed"
end

function minigames.Perks.ExpireVehicleGodMode(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)
    local veh = minigames.Player.loyaltyGodVehicle[playerId] or 0

    if veh ~= 0 and minigames.EntityExists(veh) then
        minigames.Perks.SetVehicleGodMode(veh, false)
        -- reward rule: when perk time ends, delete the protected vehicle even if occupied.
        minigames.DeleteVehicleEntity(veh)
    end

    minigames.Player.loyaltyGodVehicle[playerId] = 0
    minigames.Player.loyaltyGodUntilMs[playerId] = 0
    minigames.S.lastLoyaltyStatus = "Expired vehicle god mode for " .. minigames.GetPlayerName(playerId)
    minigames.Perks.Log(minigames.S.lastLoyaltyStatus)
end

function minigames.Perks.TickPlayer(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if not minigames.IsPlayerActive(playerId) then
        return
    end

    minigames.Perks.EnsurePlayer(playerId)

    local now = minigames.Now()
    local untilMs = minigames.Player.loyaltyGodUntilMs[playerId] or 0

    if untilMs > 0 then
        local veh = minigames.Player.loyaltyGodVehicle[playerId] or 0
        if veh ~= 0 and minigames.EntityExists(veh) then
            minigames.Perks.SetVehicleGodMode(veh, true)
        end

        if now >= untilMs then
            minigames.Perks.ExpireVehicleGodMode(playerId)
        end
    end

    local pending = minigames.Player.loyaltyPendingRewardMs[playerId] or 0
    if pending > 0 and untilMs <= 0 then
        minigames.Perks.ActivateVehicleGodMode(playerId, pending, "pending")
    end

    local elapsed = minigames.Perks.GetPlayerSessionMs(playerId)
    local claimed = minigames.Player.loyaltyTierClaimed[playerId] or 0
    local tier, duration = minigames.Perks.GetRewardForElapsed(elapsed, claimed)

    if tier > 0 and duration > 0 then
        minigames.Player.loyaltyTierClaimed[playerId] = tier
        minigames.Perks.ActivateVehicleGodMode(playerId, duration, tier)
    end
end

function minigames.Perks.Tick()
    if minigames.S.loyaltyPerksEnabled ~= true then
        return
    end

    local now = minigames.Now()
    local last = minigames.S.lastLoyaltyScanMs or 0
    local scanMs = minigames.S.loyaltyScanMs or 30000

    if last ~= 0 and now - last < scanMs then
        return
    end

    minigames.S.lastLoyaltyScanMs = now
    minigames.RefreshPlayers()

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        local ok, err = direct_call(function()
            minigames.Perks.TickPlayer(playerId)
        end)

        if not ok then
            minigames.Perks.Log("TickPlayer failed | player=" .. tostring(playerId) .. " | err=" .. tostring(err))
        end
    end
end

function minigames.Perks.PrintDebug()
    minigames.RefreshPlayers()
    minigames.LogInfo("========== WarGames Loyalty Perks ==========")
    minigames.LogInfo("Enabled: " .. tostring(minigames.S.loyaltyPerksEnabled))
    minigames.LogInfo("Vehicle God Mode Enabled: " .. tostring(minigames.S.loyaltyVehicleGodModeEnabled))
    minigames.LogInfo("Scan MS: " .. tostring(minigames.S.loyaltyScanMs))
    minigames.LogInfo("Last Status: " .. tostring(minigames.S.lastLoyaltyStatus))

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        minigames.Perks.EnsurePlayer(playerId)
        minigames.LogInfo(
            "player=" .. tostring(playerId) ..
            " name=" .. minigames.GetPlayerName(playerId) ..
            " sessionMs=" .. tostring(minigames.Perks.GetPlayerSessionMs(playerId)) ..
            " claimedTier=" .. tostring(minigames.Player.loyaltyTierClaimed[playerId] or 0) ..
            " godUntil=" .. tostring(minigames.Player.loyaltyGodUntilMs[playerId] or 0) ..
            " pending=" .. tostring(minigames.Player.loyaltyPendingRewardMs[playerId] or 0)
        )
    end

    minigames.LogInfo("===========================================")
    minigames.Toast("WarGames Perks", "Printed loyalty perk debug to log.", 3500)
end
end

-- ============================================================
-- embedded module: systems\players.lua
-- ============================================================
embedded_modules['systems\\players.lua'] = function()
-- minigames/systems/players.lua

function minigames.GetLocalPlayerId()
    if GTA and GTA.GetLocalPlayerId then
        local ok, playerId = direct_call(function()
            return GTA.GetLocalPlayerId()
        end)
        if ok and playerId ~= nil then return minigames.ClampInt(playerId, 0, 31) end
    end

    if PLAYER and PLAYER.PLAYER_ID then
        local ok, playerId = direct_call(function()
            return PLAYER.PLAYER_ID()
        end)
        if ok and playerId ~= nil then return minigames.ClampInt(playerId, 0, 31) end
    end

    return 0
end

function minigames.IsSelf(playerId)
    return minigames.ClampInt(playerId, 0, 31) == minigames.GetLocalPlayerId()
end

function minigames.GetPlayerName(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if Players and Players.GetName then
        local ok, name = direct_call(function()
            return Players.GetName(playerId)
        end)
        if ok and name and tostring(name) ~= "" then return tostring(name) end
    end

    if PLAYER and PLAYER.GET_PLAYER_NAME then
        local ok, name = direct_call(function()
            return PLAYER.GET_PLAYER_NAME(playerId)
        end)

        if ok and name and tostring(name) ~= "" and tostring(name) ~= "NULL" and tostring(name) ~= "**Invalid**" then
            return tostring(name)
        end
    end

    return "Player " .. tostring(playerId)
end

function minigames.PlayerObjectExists(playerId)
    if Players and Players.GetById then
        local ok, p = direct_call(function()
            return Players.GetById(playerId)
        end)

        return ok and p ~= nil
    end

    return false
end

function minigames.IsPlayerActive(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if minigames.PlayerObjectExists(playerId) then return true end

    if NETWORK and NETWORK.NETWORK_IS_PLAYER_ACTIVE then
        local ok, active = direct_call(function()
            return NETWORK.NETWORK_IS_PLAYER_ACTIVE(playerId)
        end)
        if ok and active == true then return true end
    end

    if PLAYER and PLAYER.GET_PLAYER_NAME then
        local ok, name = direct_call(function()
            return PLAYER.GET_PLAYER_NAME(playerId)
        end)

        if ok and name and tostring(name) ~= "" and tostring(name) ~= "NULL" and tostring(name) ~= "**Invalid**" then
            return true
        end
    end

    if minigames.IsSelf(playerId) then return true end

    return false
end

function minigames.GetSortMode()
    if ePlayerListSort and ePlayerListSort.PLAYER_ID then
        return ePlayerListSort.PLAYER_ID
    end
    return 0
end

function minigames.InitPlayerState(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)

    minigames.Player.bountyApplied = minigames.Player.bountyApplied or {}
    minigames.Player.bountyAppliedAtMs = minigames.Player.bountyAppliedAtMs or {}
    minigames.Player.bountyLastStatus = minigames.Player.bountyLastStatus or {}
    minigames.Player.bountyLastMethod = minigames.Player.bountyLastMethod or {}
    minigames.Player.bountyLastError = minigames.Player.bountyLastError or {}

    minigames.Player.vehicleEnabled = minigames.Player.vehicleEnabled or {}
    minigames.Player.vehicleSpawned = minigames.Player.vehicleSpawned or {}
    minigames.Player.vehicleSpawnedAtMs = minigames.Player.vehicleSpawnedAtMs or {}
    minigames.Player.vehicleLastStatus = minigames.Player.vehicleLastStatus or {}
    minigames.Player.vehicleLastMethod = minigames.Player.vehicleLastMethod or {}
    minigames.Player.vehicleLastError = minigames.Player.vehicleLastError or {}

    minigames.Player.wasDead = minigames.Player.wasDead or {}
    minigames.Player.deathDetectedMs = minigames.Player.deathDetectedMs or {}
    minigames.Player.respawnReadyMs = minigames.Player.respawnReadyMs or {}
    minigames.Player.deathReason = minigames.Player.deathReason or {}

    minigames.Player.bountyApplied[playerId] = minigames.Player.bountyApplied[playerId] or false
    minigames.Player.bountyAppliedAtMs[playerId] = minigames.Player.bountyAppliedAtMs[playerId] or 0
    minigames.Player.bountyLastStatus[playerId] = minigames.Player.bountyLastStatus[playerId] or "None"
    minigames.Player.bountyLastMethod[playerId] = minigames.Player.bountyLastMethod[playerId] or "None"
    minigames.Player.bountyLastError[playerId] = minigames.Player.bountyLastError[playerId] or "None"

    minigames.Player.vehicleEnabled[playerId] = minigames.Player.vehicleEnabled[playerId] or false
    minigames.Player.vehicleSpawned[playerId] = minigames.Player.vehicleSpawned[playerId] or false
    minigames.Player.vehicleSpawnedAtMs[playerId] = minigames.Player.vehicleSpawnedAtMs[playerId] or 0
    minigames.Player.vehicleLastStatus[playerId] = minigames.Player.vehicleLastStatus[playerId] or "None"
    minigames.Player.vehicleLastMethod[playerId] = minigames.Player.vehicleLastMethod[playerId] or "None"
    minigames.Player.vehicleLastError[playerId] = minigames.Player.vehicleLastError[playerId] or "None"

    minigames.Player.wasDead[playerId] = minigames.Player.wasDead[playerId] or false
    minigames.Player.deathDetectedMs[playerId] = minigames.Player.deathDetectedMs[playerId] or 0
    minigames.Player.respawnReadyMs[playerId] = minigames.Player.respawnReadyMs[playerId] or 0
    minigames.Player.deathReason[playerId] = minigames.Player.deathReason[playerId] or "None"
end

function minigames.RefreshPlayers()
    local previous = minigames.KnownPlayers or {}
    local found = {}
    local seen = {}
    local method = "None"

    if Players and Players.Get then
        local ok, players = direct_call(function()
            return Players.Get(minigames.GetSortMode(), "")
        end)

        if ok and type(players) == "table" then
            for _, playerId in pairs(players) do
                playerId = tonumber(playerId)
                if playerId ~= nil then
                    playerId = minigames.ClampInt(playerId, 0, 31)
                    if not seen[playerId] then
                        seen[playerId] = true
                        table.insert(found, playerId)
                    end
                end
            end
            if #found > 0 then method = "Players.Get" end
        end
    end

    if #found == 0 then
        for playerId = 0, 31 do
            if minigames.IsPlayerActive(playerId) and not seen[playerId] then
                seen[playerId] = true
                table.insert(found, playerId)
            end
        end
        if #found > 0 then method = "0-31 fallback scan" end
    end

    if #found == 0 then
        local selfId = minigames.GetLocalPlayerId()
        table.insert(found, selfId)
        seen[selfId] = true
        method = "self fallback"
    end

    table.sort(found, function(a, b) return a < b end)

    minigames.ActiveSet = {}

    for _, playerId in ipairs(found) do
        minigames.ActiveSet[playerId] = true
        minigames.InitPlayerState(playerId)

        if not previous[playerId] then
            minigames.LogInfo("Player detected/joined | id=" .. tostring(playerId) .. " name=" .. minigames.GetPlayerName(playerId))
            if minigames.WarGames and minigames.WarGames.OnPlayerJoined then
                minigames.WarGames.OnPlayerJoined(playerId)
            end
        end
    end

    for playerId, _ in pairs(previous) do
        if not minigames.ActiveSet[playerId] then
            minigames.LogInfo("Player left or no longer detected | id=" .. tostring(playerId) .. " name=" .. minigames.GetPlayerName(playerId))
        end
    end

    minigames.KnownPlayers = minigames.ActiveSet
    minigames.S.activePlayers = found
    minigames.S.activePlayerCount = #found
    minigames.S.lastPlayerRefreshMs = minigames.Now()
    minigames.S.lastPlayerDiscoveryMethod = method

    local selectedStillExists = false
    for _, playerId in ipairs(found) do
        if playerId == minigames.S.selectedPlayerId then
            selectedStillExists = true
            break
        end
    end

    if not selectedStillExists and #found > 0 then
        minigames.S.selectedPlayerId = found[1]
    end

    minigames.S.selectedPlayerName = minigames.GetPlayerName(minigames.S.selectedPlayerId)
    return found
end

function minigames.EnsurePlayersFresh()
    if minigames.Now() - (minigames.S.lastPlayerRefreshMs or 0) >= (minigames.S.rosterRefreshMs or minigames.C.DEFAULT_ROSTER_REFRESH_MS) then
        minigames.RefreshPlayers()
    end
end

function minigames.SelectPlayer(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)
    minigames.S.selectedPlayerId = playerId
    minigames.S.selectedPlayerName = minigames.GetPlayerName(playerId)

    if minigames.H.SELECTED_PLAYER_ID then
        minigames.SetFeatureInt(minigames.H.SELECTED_PLAYER_ID, playerId)
    end

    minigames.Toast("Selected Player", tostring(playerId) .. " | " .. minigames.S.selectedPlayerName, 2500)
end

function minigames.SelectNextPlayer()
    minigames.EnsurePlayersFresh()
    if #minigames.S.activePlayers == 0 then minigames.RefreshPlayers() end
    if #minigames.S.activePlayers == 0 then return end

    local idx = 1
    for i, pid in ipairs(minigames.S.activePlayers) do
        if pid == minigames.S.selectedPlayerId then idx = i break end
    end

    idx = idx + 1
    if idx > #minigames.S.activePlayers then idx = 1 end

    minigames.SelectPlayer(minigames.S.activePlayers[idx])
end

function minigames.SelectPreviousPlayer()
    minigames.EnsurePlayersFresh()
    if #minigames.S.activePlayers == 0 then minigames.RefreshPlayers() end
    if #minigames.S.activePlayers == 0 then return end

    local idx = 1
    for i, pid in ipairs(minigames.S.activePlayers) do
        if pid == minigames.S.selectedPlayerId then idx = i break end
    end

    idx = idx - 1
    if idx < 1 then idx = #minigames.S.activePlayers end

    minigames.SelectPlayer(minigames.S.activePlayers[idx])
end

function minigames.PrintPlayers()
    minigames.RefreshPlayers()

    minigames.LogInfo("========== Active Players ==========")
    minigames.LogInfo("Discovery Method: " .. tostring(minigames.S.lastPlayerDiscoveryMethod))
    minigames.LogInfo("Count: " .. tostring(minigames.S.activePlayerCount))

    for _, playerId in ipairs(minigames.S.activePlayers) do
        minigames.LogInfo(
            "player=" .. tostring(playerId) ..
            " name=" .. minigames.GetPlayerName(playerId) ..
            " self=" .. tostring(minigames.IsSelf(playerId)) ..
            " bountyTracked=" .. tostring(minigames.Player.bountyApplied[playerId] == true) ..
            " respawnVehicle=" .. tostring(minigames.Player.vehicleEnabled[playerId] == true)
        )
    end

    minigames.LogInfo("===================================")
    minigames.Toast("Players", "Printed " .. tostring(minigames.S.activePlayerCount) .. " players.", 3000)
end


-- v0.075:
-- session duration tracker for compact hud.
if not minigames.RefreshPlayers_CompactHudOriginal and minigames.RefreshPlayers then
    minigames.RefreshPlayers_CompactHudOriginal = minigames.RefreshPlayers

    function minigames.RefreshPlayers()
        minigames.RefreshPlayers_CompactHudOriginal()

        minigames.S.playerFirstSeenMs = minigames.S.playerFirstSeenMs or {}
        local now = minigames.Now()

        for _, playerId in ipairs(minigames.S.activePlayers or {}) do
            if not minigames.S.playerFirstSeenMs[playerId] or minigames.S.playerFirstSeenMs[playerId] <= 0 then
                minigames.S.playerFirstSeenMs[playerId] = now
            end
        end
    end
end


------------------------------------------------------------
-- v0.096 refreshplayers safety wrapper
------------------------------------------------------------
if not minigames.RefreshPlayers_SafePlayerTables_v096 and minigames.RefreshPlayers then
    minigames.RefreshPlayers_SafePlayerTables_v096 = minigames.RefreshPlayers

    function minigames.RefreshPlayers()
        if minigames.EnsurePlayerTables then
            minigames.EnsurePlayerTables()
        end

        local ok, err = direct_call_trace(function()
            minigames.RefreshPlayers_SafePlayerTables_v096()
        end, debug and debug.traceback or function(e) return tostring(e) end)

        if not ok then
            minigames.S.lastPlayerRefreshError = tostring(err)
            minigames.LogError("[Players] RefreshPlayers error swallowed: " .. tostring(err))
        end

        return true
    end
end


------------------------------------------------------------
-- v0.112 no automatic vehicle spawn on join
------------------------------------------------------------
minigames.S.disableAutomaticSpawnAll = true
minigames.S.spawnAllOnPlayerJoin = false
minigames.S.autoSpawnAllOnJoin = false
minigames.S.spawnVehicleForNewPlayers = false
minigames.S.autoGiveRoundVehicleToNewPlayers = false


------------------------------------------------------------
-- v0.113 auto spawn-all disabled in this module
------------------------------------------------------------
minigames.S.disableAutomaticSpawnAll = true
minigames.S.disableSpawnAllFromJoin = true
minigames.S.spawnAllOnPlayerJoin = false
minigames.S.autoSpawnAllOnJoin = false
minigames.S.spawnVehicleForNewPlayers = false
minigames.S.autoGiveRoundVehicleToNewPlayers = false
end

-- ============================================================
-- embedded module: systems\respawn.lua
-- ============================================================
embedded_modules['systems\\respawn.lua'] = function()
--[[
    minigames/systems/respawn.lua
    shared death / respawn detection.

    v0.056:
    - clears bounty tracking when a player dies.
      this prevents bounty spam while a bounty is already active,
      but allows reapply after the player dies/respawns.
]]

function minigames.GetPlayerHealth(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)

    local ped = minigames.GetPlayerPed(playerId)

    if not ped or ped == 0 then
        return -1, "No Ped"
    end

    if not minigames.EntityExists(ped) then
        return -1, "Ped Missing"
    end

    if ENTITY and ENTITY.GET_ENTITY_HEALTH then
        local ok, health = direct_call(function()
            return ENTITY.GET_ENTITY_HEALTH(ped)
        end)

        if ok and health ~= nil then
            return tonumber(health) or -1, "ENTITY.GET_ENTITY_HEALTH"
        end
    end

    if PED and PED.GET_PED_HEALTH then
        local ok, health = direct_call(function()
            return PED.GET_PED_HEALTH(ped)
        end)

        if ok and health ~= nil then
            return tonumber(health) or -1, "PED.GET_PED_HEALTH"
        end
    end

    return -1, "No Safe Health Source"
end

function minigames.IsPlayerDead(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if PLAYER and PLAYER.IS_PLAYER_DEAD then
        local ok, dead = direct_call(function()
            return PLAYER.IS_PLAYER_DEAD(playerId)
        end)

        if ok and dead == true then
            return true, "PLAYER.IS_PLAYER_DEAD"
        end
    end

    local ped = minigames.GetPlayerPed(playerId)

    if not ped or ped == 0 then
        return false, "No Ped"
    end

    if not minigames.EntityExists(ped) then
        return false, "Ped Missing"
    end

    if ENTITY and ENTITY.IS_ENTITY_DEAD then
        local ok, dead = direct_call(function()
            return ENTITY.IS_ENTITY_DEAD(ped, false)
        end)

        if ok and dead == true then
            return true, "ENTITY.IS_ENTITY_DEAD"
        end
    end

    local health, source = minigames.GetPlayerHealth(playerId)

    if health ~= -1 and health <= 0 then
        return true, source .. " <= 0"
    end

    return false, "Alive"
end

function minigames.IsPlayerAliveEnough(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if not minigames.IsPlayerActive(playerId) then
        return false
    end

    local ped = minigames.GetPlayerPed(playerId)

    if not ped or ped == 0 then
        return false
    end

    if not minigames.EntityExists(ped) then
        return false
    end

    local dead = select(1, minigames.IsPlayerDead(playerId))

    if dead then
        return false
    end

    local health = select(1, minigames.GetPlayerHealth(playerId))

    if health ~= -1 then
        return health > 0
    end

    return true
end

function minigames.ShouldWatchRespawn(playerId)
    if not minigames.IsPlayerActive(playerId) then
        return false
    end

    if minigames.S.skipSelfVehicle and minigames.IsSelf(playerId) then
        return false
    end

    if minigames.S.respawnOnlyTracked and not minigames.Player.vehicleEnabled[playerId] then
        return false
    end

    return true
end

function minigames.ResetDeathTracking()
    for playerId = 0, 31 do
        minigames.InitPlayerState(playerId)
        minigames.Player.wasDead[playerId] = false
        minigames.Player.deathDetectedMs[playerId] = 0
        minigames.Player.respawnReadyMs[playerId] = 0
        minigames.Player.deathReason[playerId] = "None"
    end

    minigames.Toast("Respawn Watcher", "Death tracking reset.", 3000)
end

function minigames.MarkBountyMissingAfterDeath(playerId, reason)
    playerId = minigames.ClampInt(playerId, 0, 31)
    minigames.InitPlayerState(playerId)

    if minigames.Player.bountyApplied[playerId] == true then
        minigames.Player.bountyApplied[playerId] = false
        minigames.Player.bountyAppliedAtMs[playerId] = 0
        minigames.Player.bountyLastStatus[playerId] = "Cleared after death so WarGames can reapply"
        minigames.Player.bountyLastError[playerId] = tostring(reason or "death")

        minigames.LogInfo(
            "Bounty tracking cleared after death | player=" ..
            tostring(playerId) ..
            " | " ..
            minigames.GetPlayerName(playerId) ..
            " | reason=" ..
            tostring(reason)
        )
    end
end


function minigames.HandleRespawnTick(playerId, vehicleResolver)
    if not minigames.ShouldWatchRespawn(playerId) then
        return
    end

    minigames.InitPlayerState(playerId)

    local now = minigames.Now()
    local ped = minigames.GetPlayerPed(playerId)
    local dead, reason = minigames.IsPlayerDead(playerId)
    local health = select(1, minigames.GetPlayerHealth(playerId))

    minigames.Player.lastPedHandle = minigames.Player.lastPedHandle or {}
    minigames.Player.lastHealth = minigames.Player.lastHealth or {}

    -- v0.094 lifecycle tables.
    minigames.Player.respawnCycleActive = minigames.Player.respawnCycleActive or {}
    minigames.Player.respawnVehicleSpawnedThisCycle = minigames.Player.respawnVehicleSpawnedThisCycle or {}
    minigames.Player.respawnVehicleSpawnedAtMs = minigames.Player.respawnVehicleSpawnedAtMs or {}
    minigames.Player.respawnSpawnLockUntilMs = minigames.Player.respawnSpawnLockUntilMs or {}
    minigames.Player.respawnDeathSerial = minigames.Player.respawnDeathSerial or {}
    minigames.Player.respawnLastSpawnDeathSerial = minigames.Player.respawnLastSpawnDeathSerial or {}

    local previousPed = minigames.Player.lastPedHandle[playerId] or 0
    local previousHealth = minigames.Player.lastHealth[playerId] or -1
    local lockUntil = minigames.Player.respawnSpawnLockUntilMs[playerId] or 0

    -- death edge:
    -- start a new cycle only once per actual death.
    -- if the same death keeps reporting as dead, do not reset the spawned flag over and over.
    if dead then
        if minigames.Player.respawnCycleActive[playerId] ~= true then
            local serial = (minigames.Player.respawnDeathSerial[playerId] or 0) + 1

            minigames.Player.respawnDeathSerial[playerId] = serial
            minigames.Player.respawnCycleActive[playerId] = true
            minigames.Player.respawnVehicleSpawnedThisCycle[playerId] = false
            minigames.Player.respawnVehicleSpawnedAtMs[playerId] = 0
            minigames.Player.respawnSpawnLockUntilMs[playerId] = 0

            minigames.Player.wasDead[playerId] = true
            minigames.Player.deathDetectedMs[playerId] = now
            minigames.Player.respawnReadyMs[playerId] = 0
            minigames.Player.deathReason[playerId] = reason

            if minigames.S.wargamesNoBountyMode ~= true and minigames.MarkBountyMissingAfterDeath then
                minigames.MarkBountyMissingAfterDeath(playerId, reason)
            end

            minigames.LogInfo(
                "[Respawn Watcher] Death cycle started | player=" ..
                tostring(playerId) ..
                " | name=" ..
                minigames.GetPlayerName(playerId) ..
                " | serial=" ..
                tostring(serial) ..
                " | reason=" ..
                tostring(reason)
            )
        end

        minigames.Player.lastPedHandle[playerId] = ped
        minigames.Player.lastHealth[playerId] = health
        return
    end

    -- already spawned for this death cycle: stay locked until the player dies again.
    if minigames.Player.respawnCycleActive[playerId] == true
        and minigames.Player.respawnVehicleSpawnedThisCycle[playerId] == true then
        minigames.Player.lastPedHandle[playerId] = ped
        minigames.Player.lastHealth[playerId] = health
        return
    end

    -- short noisy-transition lock.
    if lockUntil ~= 0 and now < lockUntil then
        minigames.Player.lastPedHandle[playerId] = ped
        minigames.Player.lastHealth[playerId] = health
        return
    end

    -- fallback for cases where cherax/gta misses the dead state but health clearly transitioned.
    if minigames.Player.respawnCycleActive[playerId] ~= true
        and previousHealth ~= -1
        and previousHealth <= 0
        and health ~= -1
        and health > 0 then

        local serial = (minigames.Player.respawnDeathSerial[playerId] or 0) + 1

        minigames.Player.respawnDeathSerial[playerId] = serial
        minigames.Player.respawnCycleActive[playerId] = true
        minigames.Player.respawnVehicleSpawnedThisCycle[playerId] = false
        minigames.Player.respawnVehicleSpawnedAtMs[playerId] = 0

        minigames.Player.wasDead[playerId] = true
        minigames.Player.deathDetectedMs[playerId] = now - (minigames.S.respawnDelayMs or 1250)
        minigames.Player.deathReason[playerId] = "health transition <=0 -> >0"
        minigames.Player.respawnReadyMs[playerId] = now

        minigames.LogInfo(
            "[Respawn Watcher] Health transition cycle started | player=" ..
            tostring(playerId) ..
            " | name=" ..
            minigames.GetPlayerName(playerId) ..
            " | serial=" ..
            tostring(serial)
        )
    end

    -- ped swap after death often means the respawn is ready.
    if previousPed ~= 0 and ped ~= 0 and previousPed ~= ped and minigames.Player.wasDead[playerId] == true then
        if minigames.Player.respawnReadyMs[playerId] == 0 then
            minigames.Player.respawnReadyMs[playerId] = now
            minigames.LogInfo("[Respawn Watcher] Respawn ped swap detected | player=" .. tostring(playerId) .. " | name=" .. minigames.GetPlayerName(playerId))
        end
    end

    if minigames.Player.wasDead[playerId] and minigames.IsPlayerAliveEnough(playerId) then
        if minigames.Player.respawnReadyMs[playerId] == 0 then
            minigames.Player.respawnReadyMs[playerId] = now
            minigames.LogInfo("[Respawn Watcher] Respawn ready | player=" .. tostring(playerId) .. " | name=" .. minigames.GetPlayerName(playerId))
        end

        if now - minigames.Player.respawnReadyMs[playerId] >= (minigames.S.respawnDelayMs or 1250) then
            local serial = minigames.Player.respawnDeathSerial[playerId] or 0

            if minigames.Player.respawnVehicleSpawnedThisCycle[playerId] == true
                or minigames.Player.respawnLastSpawnDeathSerial[playerId] == serial then
                minigames.Player.lastPedHandle[playerId] = ped
                minigames.Player.lastHealth[playerId] = health
                return
            end

            local vehicle = vehicleResolver()
            local ok, status = minigames.SpawnVehicleForPlayer(playerId, vehicle, true, "Respawn Watcher")

            minigames.Player.respawnVehicleSpawnedThisCycle[playerId] = true
            minigames.Player.respawnLastSpawnDeathSerial[playerId] = serial
            minigames.Player.respawnVehicleSpawnedAtMs[playerId] = now
            minigames.Player.respawnSpawnLockUntilMs[playerId] = now + (minigames.S.respawnSpawnCycleLockMs or 30000)

            if ok then
                minigames.S.lastRespawnStatus = "Spawned one vehicle after respawn for " .. minigames.GetPlayerName(playerId)
                minigames.LogInfo("[Respawn Watcher] SUCCESS | " .. minigames.S.lastRespawnStatus .. " | serial=" .. tostring(serial))
            else
                minigames.S.lastRespawnStatus = "Respawn spawn failed for " .. minigames.GetPlayerName(playerId) .. " | " .. tostring(status)
                minigames.LogError("[Respawn Watcher] FAILED | " .. minigames.S.lastRespawnStatus .. " | LastVehicleError=" .. tostring(minigames.S.lastVehicleError))
            end

            -- do not clear respawncycleactive here.
            -- keeping cycleactive=true + spawned=true is the one-shot lock.
            minigames.Player.wasDead[playerId] = false
            minigames.Player.deathDetectedMs[playerId] = 0
            minigames.Player.respawnReadyMs[playerId] = 0
        end
    end

    minigames.Player.lastPedHandle[playerId] = ped
    minigames.Player.lastHealth[playerId] = health
end



------------------------------------------------------------
-- v0.095 no-yield respawn spawn queue
------------------------------------------------------------
-- cherax does not allow vehicle spawning from the scheduler ontick fiber
-- because gta.spawnvehicle can internally yield.
-- the scheduler now only detects respawn and queues the real spawn job.
------------------------------------------------------------

function minigames.EnqueueRespawnVehicleSpawn(playerId, vehicle, serial, reason)
    minigames.S = minigames.S or {}
    minigames.Player = minigames.Player or {}

    minigames.S.pendingRespawnSpawnByPlayer = minigames.S.pendingRespawnSpawnByPlayer or {}
    minigames.S.respawnSpawnJobRunningByPlayer = minigames.S.respawnSpawnJobRunningByPlayer or {}

    playerId = minigames.ClampInt(playerId, 0, 31)
    serial = tonumber(serial or 0) or 0

    if minigames.S.pendingRespawnSpawnByPlayer[playerId] == serial
        or minigames.S.respawnSpawnJobRunningByPlayer[playerId] == serial then
        return false, "already_queued"
    end

    minigames.S.pendingRespawnSpawnByPlayer[playerId] = serial

    local function do_spawn()
        minigames.S.respawnSpawnJobRunningByPlayer[playerId] = serial

        local ok, err = direct_call_trace(function()
            -- tiny wait is safe in queuejob and prevents spawning on transitional frame.
            if Script and Script.Yield then
                Script.Yield(150)
            end

            if not minigames.IsPlayerActive(playerId) then
                minigames.S.lastRespawnStatus = "Queued spawn skipped: inactive player " .. tostring(playerId)
                return
            end

            local spawnVehicle = vehicle
            if not spawnVehicle and minigames.WarGames and minigames.WarGames.ResolveVehicle then
                spawnVehicle = minigames.WarGames.ResolveVehicle("Queued Respawn Spawn")
            end

            if not spawnVehicle then
                minigames.S.lastRespawnStatus = "Queued spawn failed: vehicle=nil"
                minigames.LogError("[Respawn Queue] " .. minigames.S.lastRespawnStatus)
                return
            end

            local okSpawn, status = minigames.SpawnVehicleForPlayer(playerId, spawnVehicle, true, reason or "Queued Respawn Watcher")

            if okSpawn then
                minigames.S.lastRespawnStatus = "Spawned one queued vehicle after respawn for " .. minigames.GetPlayerName(playerId)
                minigames.LogInfo("[Respawn Queue] SUCCESS | " .. minigames.S.lastRespawnStatus .. " | serial=" .. tostring(serial))
            else
                minigames.S.lastRespawnStatus = "Queued respawn spawn failed for " .. minigames.GetPlayerName(playerId) .. " | " .. tostring(status)
                minigames.LogError("[Respawn Queue] FAILED | " .. minigames.S.lastRespawnStatus .. " | LastVehicleError=" .. tostring(minigames.S.lastVehicleError))
            end
        end, debug and debug.traceback or function(e) return tostring(e) end)

        minigames.S.pendingRespawnSpawnByPlayer[playerId] = nil
        minigames.S.respawnSpawnJobRunningByPlayer[playerId] = nil

        if not ok then
            minigames.S.lastRespawnStatus = "Queued respawn spawn job error: " .. tostring(err)
            minigames.LogError("[Respawn Queue] " .. minigames.S.lastRespawnStatus)
        end
    end

    if Script and Script.QueueJob then
        Script.QueueJob(do_spawn)
        minigames.LogInfo("[Respawn Queue] queued vehicle spawn | player=" .. tostring(playerId) .. " | name=" .. minigames.GetPlayerName(playerId) .. " | serial=" .. tostring(serial))
        return true, "queued"
    end

    -- last-resort fallback. this may still fail in ontick, but keeps older builds functional.
    local ok, err = direct_call_trace(do_spawn, debug and debug.traceback or function(e) return tostring(e) end)
    if not ok then
        minigames.LogError("[Respawn Queue] fallback direct spawn failed: " .. tostring(err))
        return false, "fallback_failed"
    end

    return true, "queued_fallback"
end

function minigames.HandleRespawnTick(playerId, vehicleResolver)
    if not minigames.ShouldWatchRespawn(playerId) then
        return
    end

    minigames.InitPlayerState(playerId)

    local now = minigames.Now()
    local ped = minigames.GetPlayerPed(playerId)
    local dead, reason = minigames.IsPlayerDead(playerId)
    local health = select(1, minigames.GetPlayerHealth(playerId))

    minigames.Player.lastPedHandle = minigames.Player.lastPedHandle or {}
    minigames.Player.lastHealth = minigames.Player.lastHealth or {}
    minigames.Player.respawnCycleActive = minigames.Player.respawnCycleActive or {}
    minigames.Player.respawnVehicleSpawnedThisCycle = minigames.Player.respawnVehicleSpawnedThisCycle or {}
    minigames.Player.respawnVehicleSpawnedAtMs = minigames.Player.respawnVehicleSpawnedAtMs or {}
    minigames.Player.respawnSpawnLockUntilMs = minigames.Player.respawnSpawnLockUntilMs or {}
    minigames.Player.respawnDeathSerial = minigames.Player.respawnDeathSerial or {}
    minigames.Player.respawnLastSpawnDeathSerial = minigames.Player.respawnLastSpawnDeathSerial or {}

    local previousPed = minigames.Player.lastPedHandle[playerId] or 0
    local previousHealth = minigames.Player.lastHealth[playerId] or -1
    local lockUntil = minigames.Player.respawnSpawnLockUntilMs[playerId] or 0

    if dead then
        if minigames.Player.respawnCycleActive[playerId] ~= true then
            local serial = (minigames.Player.respawnDeathSerial[playerId] or 0) + 1
            minigames.Player.respawnDeathSerial[playerId] = serial
            minigames.Player.respawnCycleActive[playerId] = true
            minigames.Player.respawnVehicleSpawnedThisCycle[playerId] = false
            minigames.Player.respawnVehicleSpawnedAtMs[playerId] = 0
            minigames.Player.respawnSpawnLockUntilMs[playerId] = 0
            minigames.Player.wasDead[playerId] = true
            minigames.Player.deathDetectedMs[playerId] = now
            minigames.Player.respawnReadyMs[playerId] = 0
            minigames.Player.deathReason[playerId] = reason

            if minigames.S.wargamesNoBountyMode ~= true and minigames.MarkBountyMissingAfterDeath then
                minigames.MarkBountyMissingAfterDeath(playerId, reason)
            end

            minigames.LogInfo("[Respawn Watcher] Death cycle started | player=" .. tostring(playerId) .. " | name=" .. minigames.GetPlayerName(playerId) .. " | serial=" .. tostring(serial) .. " | reason=" .. tostring(reason))
        end

        minigames.Player.lastPedHandle[playerId] = ped
        minigames.Player.lastHealth[playerId] = health
        return
    end

    if minigames.Player.respawnCycleActive[playerId] == true
        and minigames.Player.respawnVehicleSpawnedThisCycle[playerId] == true then
        minigames.Player.lastPedHandle[playerId] = ped
        minigames.Player.lastHealth[playerId] = health
        return
    end

    if lockUntil ~= 0 and now < lockUntil then
        minigames.Player.lastPedHandle[playerId] = ped
        minigames.Player.lastHealth[playerId] = health
        return
    end

    if minigames.Player.respawnCycleActive[playerId] ~= true
        and previousHealth ~= -1
        and previousHealth <= 0
        and health ~= -1
        and health > 0 then

        local serial = (minigames.Player.respawnDeathSerial[playerId] or 0) + 1
        minigames.Player.respawnDeathSerial[playerId] = serial
        minigames.Player.respawnCycleActive[playerId] = true
        minigames.Player.respawnVehicleSpawnedThisCycle[playerId] = false
        minigames.Player.respawnVehicleSpawnedAtMs[playerId] = 0
        minigames.Player.wasDead[playerId] = true
        minigames.Player.deathDetectedMs[playerId] = now - (minigames.S.respawnDelayMs or 1250)
        minigames.Player.deathReason[playerId] = "health transition <=0 -> >0"
        minigames.Player.respawnReadyMs[playerId] = now

        minigames.LogInfo("[Respawn Watcher] Health transition cycle started | player=" .. tostring(playerId) .. " | name=" .. minigames.GetPlayerName(playerId) .. " | serial=" .. tostring(serial))
    end

    if previousPed ~= 0 and ped ~= 0 and previousPed ~= ped and minigames.Player.wasDead[playerId] == true then
        if minigames.Player.respawnReadyMs[playerId] == 0 then
            minigames.Player.respawnReadyMs[playerId] = now
            minigames.LogInfo("[Respawn Watcher] Respawn ped swap detected | player=" .. tostring(playerId) .. " | name=" .. minigames.GetPlayerName(playerId))
        end
    end

    if minigames.Player.wasDead[playerId] and minigames.IsPlayerAliveEnough(playerId) then
        if minigames.Player.respawnReadyMs[playerId] == 0 then
            minigames.Player.respawnReadyMs[playerId] = now
            minigames.LogInfo("[Respawn Watcher] Respawn ready | player=" .. tostring(playerId) .. " | name=" .. minigames.GetPlayerName(playerId))
        end

        if now - minigames.Player.respawnReadyMs[playerId] >= (minigames.S.respawnDelayMs or 1250) then
            local serial = minigames.Player.respawnDeathSerial[playerId] or 0

            if minigames.Player.respawnVehicleSpawnedThisCycle[playerId] == true
                or minigames.Player.respawnLastSpawnDeathSerial[playerId] == serial then
                minigames.Player.lastPedHandle[playerId] = ped
                minigames.Player.lastHealth[playerId] = health
                return
            end

            local vehicle = vehicleResolver()

            -- lock before queueing so the scheduler cannot enqueue every tick.
            minigames.Player.respawnVehicleSpawnedThisCycle[playerId] = true
            minigames.Player.respawnLastSpawnDeathSerial[playerId] = serial
            minigames.Player.respawnVehicleSpawnedAtMs[playerId] = now
            minigames.Player.respawnSpawnLockUntilMs[playerId] = now + (minigames.S.respawnSpawnCycleLockMs or 30000)
            minigames.Player.wasDead[playerId] = false
            minigames.Player.deathDetectedMs[playerId] = 0
            minigames.Player.respawnReadyMs[playerId] = 0

            local queued, qStatus = minigames.EnqueueRespawnVehicleSpawn(playerId, vehicle, serial, "Queued Respawn Watcher")
            minigames.S.lastRespawnStatus = "Queued respawn vehicle for " .. minigames.GetPlayerName(playerId) .. " | " .. tostring(qStatus)
        end
    end

    minigames.Player.lastPedHandle[playerId] = ped
    minigames.Player.lastHealth[playerId] = health
end

------------------------------------------------------------
-- v0.097 respawn lifecycle phase override
------------------------------------------------------------
-- fixes the issue where one successful respawn spawn permanently
-- locked the player out of future death cycles.
--
-- phase model:
-- nil/idle  = ready to detect a death
-- dead      = death detected, waiting for alive/respawn
-- queued    = respawn detected, spawn queued
-- spawned   = vehicle spawned/attempted, ready to detect next death
------------------------------------------------------------

function minigames.EnsureRespawnLifecycleTables()
    minigames.Player = minigames.Player or {}
    minigames.Player.lastPedHandle = minigames.Player.lastPedHandle or {}
    minigames.Player.lastHealth = minigames.Player.lastHealth or {}
    minigames.Player.respawnPhase = minigames.Player.respawnPhase or {}
    minigames.Player.respawnDeathSerial = minigames.Player.respawnDeathSerial or {}
    minigames.Player.respawnReadyMs = minigames.Player.respawnReadyMs or {}
    minigames.Player.deathDetectedMs = minigames.Player.deathDetectedMs or {}
    minigames.Player.deathReason = minigames.Player.deathReason or {}
    minigames.Player.respawnVehicleSpawnedAtMs = minigames.Player.respawnVehicleSpawnedAtMs or {}
    minigames.Player.respawnSpawnLockUntilMs = minigames.Player.respawnSpawnLockUntilMs or {}
    minigames.Player.respawnLastSpawnDeathSerial = minigames.Player.respawnLastSpawnDeathSerial or {}
    minigames.Player.wasDead = minigames.Player.wasDead or {}
end

function minigames.StartRespawnDeathCycle(playerId, reason, now)
    minigames.EnsureRespawnLifecycleTables()

    local serial = (minigames.Player.respawnDeathSerial[playerId] or 0) + 1

    minigames.Player.respawnDeathSerial[playerId] = serial
    minigames.Player.respawnPhase[playerId] = "dead"
    minigames.Player.wasDead[playerId] = true
    minigames.Player.deathDetectedMs[playerId] = now
    minigames.Player.respawnReadyMs[playerId] = 0
    minigames.Player.deathReason[playerId] = tostring(reason or "death")
    minigames.Player.respawnSpawnLockUntilMs[playerId] = 0

    -- backward-compatible fields for older debug/status ui.
    minigames.Player.respawnCycleActive = minigames.Player.respawnCycleActive or {}
    minigames.Player.respawnVehicleSpawnedThisCycle = minigames.Player.respawnVehicleSpawnedThisCycle or {}
    minigames.Player.respawnVehicleSpawnedAtMs = minigames.Player.respawnVehicleSpawnedAtMs or {}
    minigames.Player.respawnCycleActive[playerId] = true
    minigames.Player.respawnVehicleSpawnedThisCycle[playerId] = false
    minigames.Player.respawnVehicleSpawnedAtMs[playerId] = 0

    if minigames.S.wargamesNoBountyMode ~= true and minigames.MarkBountyMissingAfterDeath then
        minigames.MarkBountyMissingAfterDeath(playerId, reason)
    end

    minigames.LogInfo(
        "[Respawn Watcher] Death cycle started | player=" ..
        tostring(playerId) ..
        " | name=" ..
        minigames.GetPlayerName(playerId) ..
        " | serial=" ..
        tostring(serial) ..
        " | reason=" ..
        tostring(reason)
    )

    return serial
end

function minigames.HandleRespawnTick(playerId, vehicleResolver)
    if not minigames.ShouldWatchRespawn(playerId) then
        return
    end

    minigames.InitPlayerState(playerId)
    minigames.EnsureRespawnLifecycleTables()

    local now = minigames.Now()
    local ped = minigames.GetPlayerPed(playerId)
    local dead, reason = minigames.IsPlayerDead(playerId)
    local health = select(1, minigames.GetPlayerHealth(playerId))

    local previousPed = minigames.Player.lastPedHandle[playerId] or 0
    local previousHealth = minigames.Player.lastHealth[playerId] or -1
    local phase = minigames.Player.respawnPhase[playerId] or "idle"
    local lockUntil = minigames.Player.respawnSpawnLockUntilMs[playerId] or 0

    -- new death edge.
    -- if phase is spawned/idle/queued and the player is dead, this is a new death cycle.
    -- if phase is already dead, it is the same death and should not reset repeatedly.
    if dead then
        if phase ~= "dead" then
            minigames.StartRespawnDeathCycle(playerId, reason, now)
        end

        minigames.Player.lastPedHandle[playerId] = ped
        minigames.Player.lastHealth[playerId] = health
        return
    end

    -- if alive and waiting on a queued/spawned vehicle, do not enqueue again.
    if phase == "queued" or phase == "spawned" then
        minigames.Player.lastPedHandle[playerId] = ped
        minigames.Player.lastHealth[playerId] = health
        return
    end

    -- short transition lock. this only blocks noisy post-spawn frames,
    -- not future deaths because the dead branch above wins first.
    if lockUntil ~= 0 and now < lockUntil then
        minigames.Player.lastPedHandle[playerId] = ped
        minigames.Player.lastHealth[playerId] = health
        return
    end

    -- fallback: missed dead state, but health moved from dead to alive.
    if phase ~= "dead"
        and previousHealth ~= -1
        and previousHealth <= 0
        and health ~= -1
        and health > 0 then

        minigames.StartRespawnDeathCycle(playerId, "health transition <=0 -> >0", now - (minigames.S.respawnDelayMs or 1250))
        minigames.Player.respawnReadyMs[playerId] = now
        phase = "dead"
    end

    -- ped handle swap after death often means respawn is ready.
    if previousPed ~= 0 and ped ~= 0 and previousPed ~= ped and phase == "dead" then
        if minigames.Player.respawnReadyMs[playerId] == 0 then
            minigames.Player.respawnReadyMs[playerId] = now
            minigames.LogInfo("[Respawn Watcher] Respawn ped swap detected | player=" .. tostring(playerId) .. " | name=" .. minigames.GetPlayerName(playerId))
        end
    end

    if phase == "dead" and minigames.IsPlayerAliveEnough(playerId) then
        if minigames.Player.respawnReadyMs[playerId] == 0 then
            minigames.Player.respawnReadyMs[playerId] = now
            minigames.LogInfo("[Respawn Watcher] Respawn ready | player=" .. tostring(playerId) .. " | name=" .. minigames.GetPlayerName(playerId))
        end

        if now - minigames.Player.respawnReadyMs[playerId] >= (minigames.S.respawnDelayMs or 1250) then
            local serial = minigames.Player.respawnDeathSerial[playerId] or 0

            if minigames.Player.respawnLastSpawnDeathSerial[playerId] == serial then
                minigames.Player.respawnPhase[playerId] = "spawned"
                minigames.Player.lastPedHandle[playerId] = ped
                minigames.Player.lastHealth[playerId] = health
                return
            end

            local vehicle = nil
            if vehicleResolver then
                local okVehicle, result = direct_call(vehicleResolver)
                if okVehicle then
                    vehicle = result
                else
                    minigames.LogError("[Respawn Watcher] vehicleResolver failed: " .. tostring(result))
                end
            end

            -- lock before queueing so ontick cannot enqueue repeatedly.
            minigames.Player.respawnPhase[playerId] = "queued"
            minigames.Player.respawnLastSpawnDeathSerial[playerId] = serial
            minigames.Player.respawnVehicleSpawnedAtMs[playerId] = now
            minigames.Player.respawnSpawnLockUntilMs[playerId] = now + (minigames.S.respawnSpawnCycleLockMs or 30000)
            minigames.Player.wasDead[playerId] = false
            minigames.Player.deathDetectedMs[playerId] = 0
            minigames.Player.respawnReadyMs[playerId] = 0

            -- backward-compatible flags.
            minigames.Player.respawnCycleActive = minigames.Player.respawnCycleActive or {}
            minigames.Player.respawnVehicleSpawnedThisCycle = minigames.Player.respawnVehicleSpawnedThisCycle or {}
            minigames.Player.respawnCycleActive[playerId] = true
            minigames.Player.respawnVehicleSpawnedThisCycle[playerId] = true

            local queued, qStatus = minigames.EnqueueRespawnVehicleSpawn(playerId, vehicle, serial, "Queued Respawn Watcher")

            if queued then
                minigames.S.lastRespawnStatus = "Queued respawn vehicle for " .. minigames.GetPlayerName(playerId) .. " | " .. tostring(qStatus)
                minigames.Player.respawnPhase[playerId] = "spawned"
            else
                minigames.S.lastRespawnStatus = "Failed to queue respawn vehicle for " .. minigames.GetPlayerName(playerId) .. " | " .. tostring(qStatus)
                minigames.Player.respawnPhase[playerId] = "spawned"
                minigames.LogError("[Respawn Watcher] " .. tostring(minigames.S.lastRespawnStatus))
            end
        end
    end

    minigames.Player.lastPedHandle[playerId] = ped
    minigames.Player.lastHealth[playerId] = health
end


------------------------------------------------------------
-- v0.098 final respawn detection override
------------------------------------------------------------
-- reason:
-- some gta/cherax death methods miss later deaths after the first cycle,
-- especially when instant suicide / script-driven deaths are used. this
-- final watcher keeps the regular death branch, but also treats a ped handle
-- change while alive as a respawn signal. that gives us a reliable fallback:
-- one vehicle per detected death or one vehicle per respawn ped-swap.
------------------------------------------------------------

function minigames.EnsureRespawnLifecycleTables()
    minigames.Player = minigames.Player or {}
    minigames.Player.lastPedHandle = minigames.Player.lastPedHandle or {}
    minigames.Player.lastHealth = minigames.Player.lastHealth or {}
    minigames.Player.respawnPhase = minigames.Player.respawnPhase or {}
    minigames.Player.respawnDeathSerial = minigames.Player.respawnDeathSerial or {}
    minigames.Player.respawnReadyMs = minigames.Player.respawnReadyMs or {}
    minigames.Player.deathDetectedMs = minigames.Player.deathDetectedMs or {}
    minigames.Player.deathReason = minigames.Player.deathReason or {}
    minigames.Player.respawnVehicleSpawnedAtMs = minigames.Player.respawnVehicleSpawnedAtMs or {}
    minigames.Player.respawnSpawnLockUntilMs = minigames.Player.respawnSpawnLockUntilMs or {}
    minigames.Player.respawnLastSpawnDeathSerial = minigames.Player.respawnLastSpawnDeathSerial or {}
    minigames.Player.respawnLastPedChangeSpawnMs = minigames.Player.respawnLastPedChangeSpawnMs or {}
    minigames.Player.wasDead = minigames.Player.wasDead or {}
    minigames.Player.respawnCycleActive = minigames.Player.respawnCycleActive or {}
    minigames.Player.respawnVehicleSpawnedThisCycle = minigames.Player.respawnVehicleSpawnedThisCycle or {}
end

function minigames.StartRespawnDeathCycle(playerId, reason, now)
    minigames.EnsureRespawnLifecycleTables()
    now = now or minigames.Now()

    local serial = (minigames.Player.respawnDeathSerial[playerId] or 0) + 1

    minigames.Player.respawnDeathSerial[playerId] = serial
    minigames.Player.respawnPhase[playerId] = "dead"
    minigames.Player.wasDead[playerId] = true
    minigames.Player.deathDetectedMs[playerId] = now
    minigames.Player.respawnReadyMs[playerId] = 0
    minigames.Player.deathReason[playerId] = tostring(reason or "death")
    minigames.Player.respawnSpawnLockUntilMs[playerId] = 0
    minigames.Player.respawnCycleActive[playerId] = true
    minigames.Player.respawnVehicleSpawnedThisCycle[playerId] = false
    minigames.Player.respawnVehicleSpawnedAtMs[playerId] = 0

    if minigames.S.wargamesNoBountyMode ~= true and minigames.MarkBountyMissingAfterDeath then
        minigames.MarkBountyMissingAfterDeath(playerId, reason)
    end

    minigames.LogInfo(
        "[Respawn Watcher] Death cycle started | player=" ..
        tostring(playerId) ..
        " | name=" ..
        minigames.GetPlayerName(playerId) ..
        " | serial=" ..
        tostring(serial) ..
        " | reason=" ..
        tostring(reason)
    )

    return serial
end

function minigames.QueueRespawnSpawnOnce(playerId, vehicle, serial, reason)
    minigames.EnsureRespawnLifecycleTables()

    local now = minigames.Now()
    local lastSpawn = minigames.Player.respawnVehicleSpawnedAtMs[playerId] or 0
    local minGap = minigames.S.respawnMinimumSpawnGapMs or 7000

    if lastSpawn ~= 0 and now - lastSpawn < minGap then
        minigames.S.lastRespawnStatus = "Respawn spawn skipped by min-gap for " .. minigames.GetPlayerName(playerId)
        return false, "min_gap"
    end

    minigames.Player.respawnPhase[playerId] = "queued"
    minigames.Player.respawnLastSpawnDeathSerial[playerId] = serial
    minigames.Player.respawnVehicleSpawnedAtMs[playerId] = now
    minigames.Player.respawnSpawnLockUntilMs[playerId] = now + (minigames.S.respawnSpawnCycleLockMs or 30000)
    minigames.Player.wasDead[playerId] = false
    minigames.Player.deathDetectedMs[playerId] = 0
    minigames.Player.respawnReadyMs[playerId] = 0
    minigames.Player.respawnCycleActive[playerId] = true
    minigames.Player.respawnVehicleSpawnedThisCycle[playerId] = true

    local queued, qStatus = minigames.EnqueueRespawnVehicleSpawn(playerId, vehicle, serial, reason or "Queued Respawn Watcher")

    if queued then
        minigames.Player.respawnPhase[playerId] = "spawned"
        minigames.S.lastRespawnStatus = "Queued respawn vehicle for " .. minigames.GetPlayerName(playerId) .. " | " .. tostring(qStatus)
        return true, qStatus
    end

    minigames.Player.respawnPhase[playerId] = "spawned"
    minigames.S.lastRespawnStatus = "Failed to queue respawn vehicle for " .. minigames.GetPlayerName(playerId) .. " | " .. tostring(qStatus)
    minigames.LogError("[Respawn Watcher] " .. tostring(minigames.S.lastRespawnStatus))
    return false, qStatus
end

function minigames.HandleRespawnTick(playerId, vehicleResolver)
    if not minigames.ShouldWatchRespawn(playerId) then
        return
    end

    minigames.InitPlayerState(playerId)
    minigames.EnsureRespawnLifecycleTables()

    local now = minigames.Now()
    local ped = minigames.GetPlayerPed(playerId)
    local dead, reason = minigames.IsPlayerDead(playerId)
    local health = select(1, minigames.GetPlayerHealth(playerId))

    local previousPed = minigames.Player.lastPedHandle[playerId] or 0
    local previousHealth = minigames.Player.lastHealth[playerId] or -1
    local phase = minigames.Player.respawnPhase[playerId] or "idle"
    local lockUntil = minigames.Player.respawnSpawnLockUntilMs[playerId] or 0

    -- normal death edge. this still handles the first/cleanest path.
    if dead then
        if phase ~= "dead" then
            minigames.StartRespawnDeathCycle(playerId, reason, now)
        end

        minigames.Player.lastPedHandle[playerId] = ped
        minigames.Player.lastHealth[playerId] = health
        return
    end

    -- fallback a: missed dead state, but health moved from <=0 back to alive.
    if phase ~= "dead"
        and previousHealth ~= -1
        and previousHealth <= 0
        and health ~= -1
        and health > 0 then
        minigames.StartRespawnDeathCycle(playerId, "health transition <=0 -> >0", now - (minigames.S.respawnDelayMs or 1250))
        minigames.Player.respawnReadyMs[playerId] = now
        phase = "dead"
    end

    -- fallback b: missed death entirely, but ped handle changed and the player is alive.
    -- this is the most reliable respawn signal when instant suicide/native death polling misses.
    local pedChangedRespawn = false
    if previousPed ~= 0 and ped ~= 0 and previousPed ~= ped and minigames.IsPlayerAliveEnough(playerId) then
        local lastPedSpawn = minigames.Player.respawnLastPedChangeSpawnMs[playerId] or 0
        local pedCooldown = minigames.S.respawnPedChangeCooldownMs or 9000

        if lastPedSpawn == 0 or now - lastPedSpawn >= pedCooldown then
            pedChangedRespawn = true
            minigames.Player.respawnLastPedChangeSpawnMs[playerId] = now
            minigames.LogInfo(
                "[Respawn Watcher] Ped-change respawn fallback | player=" ..
                tostring(playerId) ..
                " | name=" ..
                minigames.GetPlayerName(playerId) ..
                " | oldPed=" ..
                tostring(previousPed) ..
                " | newPed=" ..
                tostring(ped)
            )
        end
    end

    if pedChangedRespawn and phase ~= "dead" then
        local serial = (minigames.Player.respawnDeathSerial[playerId] or 0) + 1
        minigames.Player.respawnDeathSerial[playerId] = serial

        local vehicle = nil
        if vehicleResolver then
            local okVehicle, result = direct_call(vehicleResolver)
            if okVehicle then vehicle = result else minigames.LogError("[Respawn Watcher] vehicleResolver failed: " .. tostring(result)) end
        end

        minigames.QueueRespawnSpawnOnce(playerId, vehicle, serial, "Ped Change Respawn Fallback")
        minigames.Player.lastPedHandle[playerId] = ped
        minigames.Player.lastHealth[playerId] = health
        return
    end

    -- normal respawn-ready branch after a known death cycle.
    if phase == "dead" and minigames.IsPlayerAliveEnough(playerId) then
        if minigames.Player.respawnReadyMs[playerId] == 0 then
            minigames.Player.respawnReadyMs[playerId] = now
            minigames.LogInfo("[Respawn Watcher] Respawn ready | player=" .. tostring(playerId) .. " | name=" .. minigames.GetPlayerName(playerId))
        end

        if now - minigames.Player.respawnReadyMs[playerId] >= (minigames.S.respawnDelayMs or 1250) then
            local serial = minigames.Player.respawnDeathSerial[playerId] or 0

            if minigames.Player.respawnLastSpawnDeathSerial[playerId] == serial then
                minigames.Player.respawnPhase[playerId] = "spawned"
                minigames.Player.lastPedHandle[playerId] = ped
                minigames.Player.lastHealth[playerId] = health
                return
            end

            local vehicle = nil
            if vehicleResolver then
                local okVehicle, result = direct_call(vehicleResolver)
                if okVehicle then vehicle = result else minigames.LogError("[Respawn Watcher] vehicleResolver failed: " .. tostring(result)) end
            end

            minigames.QueueRespawnSpawnOnce(playerId, vehicle, serial, "Queued Respawn Watcher")
        end
    end

    minigames.Player.lastPedHandle[playerId] = ped
    minigames.Player.lastHealth[playerId] = health
end


------------------------------------------------------------
-- v0.099 final respawn fallback override
------------------------------------------------------------
-- goal:
-- - keep normal death -> respawn -> spawn flow.
-- - add position-jump fallback for cases where cherax/gta misses later
--   death states and the ped handle does not change reliably.
-- - do not spam: every fallback/respawn spawn is cooldown gated.
------------------------------------------------------------
function minigames.GetPedCoordsSimple(ped)
    if not ped or ped == 0 then return nil end
    if not minigames.EntityExists(ped) then return nil end

    if ENTITY and ENTITY.GET_ENTITY_COORDS then
        local ok, coords = direct_call(function()
            return ENTITY.GET_ENTITY_COORDS(ped, true)
        end)
        if ok and coords then return coords end
    end

    return nil
end

function minigames.Distance2D(a, b)
    if not a or not b then return 0.0 end
    local dx = (tonumber(a.x) or 0.0) - (tonumber(b.x) or 0.0)
    local dy = (tonumber(a.y) or 0.0) - (tonumber(b.y) or 0.0)
    return math.sqrt((dx * dx) + (dy * dy))
end

function minigames.IsPlayerInAnyVehicle(playerId)
    local ped = minigames.GetPlayerPed(playerId)
    if not ped or ped == 0 or not minigames.EntityExists(ped) then return false end

    if PED and PED.IS_PED_IN_ANY_VEHICLE then
        local ok, result = direct_call(function()
            return PED.IS_PED_IN_ANY_VEHICLE(ped, false)
        end)
        if ok then return result == true end
    end

    if PED and PED.GET_VEHICLE_PED_IS_IN then
        local ok, veh = direct_call(function()
            return PED.GET_VEHICLE_PED_IS_IN(ped, false)
        end)
        if ok and veh and veh ~= 0 and minigames.EntityExists(veh) then return true end
    end

    return false
end

function minigames.EnqueueRespawnFromWatcher(playerId, vehicleResolver, serial, reason)
    local vehicle = nil
    if vehicleResolver then
        local okVehicle, result = direct_call(vehicleResolver)
        if okVehicle then
            vehicle = result
        else
            minigames.LogError("[Respawn Watcher] vehicleResolver failed: " .. tostring(result))
        end
    end

    return minigames.QueueRespawnSpawnOnce(playerId, vehicle, serial, reason)
end

function minigames.HandleRespawnTick(playerId, vehicleResolver)
    if not minigames.ShouldWatchRespawn(playerId) then
        return
    end

    minigames.InitPlayerState(playerId)
    minigames.EnsureRespawnLifecycleTables()

    minigames.Player.lastPedCoords = minigames.Player.lastPedCoords or {}
    minigames.Player.lastAliveSeenMs = minigames.Player.lastAliveSeenMs or {}
    minigames.Player.respawnFallbackSpawnMs = minigames.Player.respawnFallbackSpawnMs or {}
    minigames.Player.respawnSampleCount = minigames.Player.respawnSampleCount or {}

    local now = minigames.Now()
    local ped = minigames.GetPlayerPed(playerId)
    local coords = minigames.GetPedCoordsSimple(ped)
    local dead, reason = minigames.IsPlayerDead(playerId)
    local health = select(1, minigames.GetPlayerHealth(playerId))
    local aliveEnough = minigames.IsPlayerAliveEnough(playerId)

    local previousPed = minigames.Player.lastPedHandle[playerId] or 0
    local previousHealth = minigames.Player.lastHealth[playerId] or -1
    local previousCoords = minigames.Player.lastPedCoords[playerId]
    local phase = minigames.Player.respawnPhase[playerId] or "idle"

    minigames.Player.respawnSampleCount[playerId] = (minigames.Player.respawnSampleCount[playerId] or 0) + 1

    -- normal death edge. this is still the preferred path.
    if dead then
        if phase ~= "dead" then
            minigames.StartRespawnDeathCycle(playerId, reason, now)
        end

        minigames.Player.lastPedHandle[playerId] = ped
        minigames.Player.lastHealth[playerId] = health
        minigames.Player.lastPedCoords[playerId] = coords
        return
    end

    -- health transition fallback.
    if phase ~= "dead"
        and previousHealth ~= -1
        and previousHealth <= 0
        and health ~= -1
        and health > 0 then
        minigames.StartRespawnDeathCycle(playerId, "health transition <=0 -> >0", now - (minigames.S.respawnDelayMs or 1250))
        minigames.Player.respawnReadyMs[playerId] = now
        phase = "dead"
    end

    -- known death cycle -> alive enough -> one queued spawn.
    if phase == "dead" and aliveEnough then
        if minigames.Player.respawnReadyMs[playerId] == 0 then
            minigames.Player.respawnReadyMs[playerId] = now
            minigames.LogInfo("[Respawn Watcher] Respawn ready | player=" .. tostring(playerId) .. " | name=" .. minigames.GetPlayerName(playerId))
        end

        if now - minigames.Player.respawnReadyMs[playerId] >= (minigames.S.respawnDelayMs or 1250) then
            local serial = minigames.Player.respawnDeathSerial[playerId] or 0

            if minigames.Player.respawnLastSpawnDeathSerial[playerId] ~= serial then
                minigames.EnqueueRespawnFromWatcher(playerId, vehicleResolver, serial, "Known Death Respawn")
            end
        end

        minigames.Player.lastPedHandle[playerId] = ped
        minigames.Player.lastHealth[playerId] = health
        minigames.Player.lastPedCoords[playerId] = coords
        return
    end

    -- v0.108 disable noisy position/ped fallback:
    -- public lobbies and remote tp can create huge position jumps.
    -- those jumps were being treated as respawns and could spawn extra vehicles.
    if minigames.S.enableRespawnPositionJumpFallback ~= true and minigames.S.enableRespawnPedChangeFallback ~= true then
        if aliveEnough then
            minigames.Player.lastAliveSeenMs[playerId] = now
        end

        minigames.Player.lastPedHandle[playerId] = ped
        minigames.Player.lastHealth[playerId] = health
        minigames.Player.lastPedCoords[playerId] = coords
        return
    end

    -- fallback: ped swap while alive.
    local pedChanged = previousPed ~= 0 and ped ~= 0 and previousPed ~= ped
    local movedFar = false
    local dist = 0.0

    if previousCoords and coords then
        dist = minigames.Distance2D(previousCoords, coords)
        movedFar = dist >= (minigames.S.respawnPositionJumpDistance or 45.0)
    end

    local enoughSamples = (minigames.Player.respawnSampleCount[playerId] or 0) >= 4
    local lastFallback = minigames.Player.respawnFallbackSpawnMs[playerId] or 0
    local lastAnySpawn = minigames.Player.respawnVehicleSpawnedAtMs[playerId] or 0
    local fallbackCooldown = minigames.S.respawnFallbackCooldownMs or 15000
    local anySpawnCooldown = minigames.S.respawnMinimumSpawnGapMs or 7000
    local notInVehicle = not minigames.IsPlayerInAnyVehicle(playerId)

    if aliveEnough and enoughSamples and notInVehicle then
        local canFallback = true

        if lastFallback ~= 0 and now - lastFallback < fallbackCooldown then canFallback = false end
        if lastAnySpawn ~= 0 and now - lastAnySpawn < anySpawnCooldown then canFallback = false end

        if canFallback and ((minigames.S.enableRespawnPedChangeFallback == true and pedChanged) or (minigames.S.enableRespawnPositionJumpFallback == true and movedFar)) then
            local serial = (minigames.Player.respawnDeathSerial[playerId] or 0) + 1
            minigames.Player.respawnDeathSerial[playerId] = serial
            minigames.Player.respawnFallbackSpawnMs[playerId] = now

            local reasonText = "fallback"
            if pedChanged and movedFar then
                reasonText = "ped+position respawn fallback"
            elseif pedChanged then
                reasonText = "ped-change respawn fallback"
            elseif movedFar then
                reasonText = "position-jump respawn fallback " .. tostring(math.floor(dist)) .. "m"
            end

            minigames.LogInfo(
                "[Respawn Watcher] " .. reasonText ..
                " | player=" .. tostring(playerId) ..
                " | name=" .. minigames.GetPlayerName(playerId) ..
                " | oldPed=" .. tostring(previousPed) ..
                " | newPed=" .. tostring(ped)
            )

            minigames.EnqueueRespawnFromWatcher(playerId, vehicleResolver, serial, reasonText)
        end
    end

    if aliveEnough then
        minigames.Player.lastAliveSeenMs[playerId] = now
    end

    minigames.Player.lastPedHandle[playerId] = ped
    minigames.Player.lastHealth[playerId] = health
    minigames.Player.lastPedCoords[playerId] = coords
end


------------------------------------------------------------
-- v0.100 hard respawn fallback override
------------------------------------------------------------
-- why:
-- v0.099 successfully spawned for the first two mk2 deaths and one mk1 death,
-- but later death cycles could get stuck at:
--   death cycle started -> no respawn ready -> no queued spawn.
--
-- fix:
-- - keep normal death -> aliveenough -> spawn path.
-- - add a forced-ready path when the player is no longer dead but aliveenough
--   never becomes true.
-- - add a dead-cycle timeout so one bad cycle cannot permanently block future
--   deaths.
-- - add clearer logs so the next test shows which path fired.
------------------------------------------------------------
function minigames.HandleRespawnTick(playerId, vehicleResolver)
    if not minigames.ShouldWatchRespawn(playerId) then
        return
    end

    minigames.InitPlayerState(playerId)
    minigames.EnsureRespawnLifecycleTables()

    minigames.Player.lastPedCoords = minigames.Player.lastPedCoords or {}
    minigames.Player.lastAliveSeenMs = minigames.Player.lastAliveSeenMs or {}
    minigames.Player.respawnFallbackSpawnMs = minigames.Player.respawnFallbackSpawnMs or {}
    minigames.Player.respawnSampleCount = minigames.Player.respawnSampleCount or {}
    minigames.Player.respawnForcedReadyMs = minigames.Player.respawnForcedReadyMs or {}

    local now = minigames.Now()
    local ped = minigames.GetPlayerPed(playerId)
    local coords = minigames.GetPedCoordsSimple and minigames.GetPedCoordsSimple(ped) or nil
    local dead, reason = minigames.IsPlayerDead(playerId)
    local health = select(1, minigames.GetPlayerHealth(playerId))
    local aliveEnough = minigames.IsPlayerAliveEnough(playerId)

    local previousPed = minigames.Player.lastPedHandle[playerId] or 0
    local previousHealth = minigames.Player.lastHealth[playerId] or -1
    local previousCoords = minigames.Player.lastPedCoords[playerId]
    local phase = minigames.Player.respawnPhase[playerId] or "idle"
    local deathAt = minigames.Player.deathDetectedMs[playerId] or 0
    local serial = minigames.Player.respawnDeathSerial[playerId] or 0

    minigames.Player.respawnSampleCount[playerId] = (minigames.Player.respawnSampleCount[playerId] or 0) + 1

    -- dead edge / dead hold.
    if dead then
        if phase ~= "dead" then
            minigames.StartRespawnDeathCycle(playerId, reason, now)
        else
            -- if a cycle gets stuck while the game still says dead, do not keep it forever.
            -- this prevents one bad suicide/respawn event from blocking all future cycles.
            local maxDeadHoldMs = minigames.S.respawnDeadCycleHardResetMs or 16000
            if deathAt ~= 0 and now - deathAt >= maxDeadHoldMs then
                minigames.LogError(
                    "[Respawn Watcher] dead-cycle hard reset | player=" .. tostring(playerId) ..
                    " | name=" .. minigames.GetPlayerName(playerId) ..
                    " | serial=" .. tostring(serial) ..
                    " | heldMs=" .. tostring(now - deathAt)
                )
                minigames.Player.respawnPhase[playerId] = "idle"
                minigames.Player.wasDead[playerId] = false
                minigames.Player.deathDetectedMs[playerId] = 0
                minigames.Player.respawnReadyMs[playerId] = 0
                minigames.Player.respawnForcedReadyMs[playerId] = 0
            end
        end

        minigames.Player.lastPedHandle[playerId] = ped
        minigames.Player.lastHealth[playerId] = health
        minigames.Player.lastPedCoords[playerId] = coords
        return
    end

    -- if queued/spawned, a new death will be caught above. while alive, do nothing.
    if phase == "queued" or phase == "spawned" then
        minigames.Player.lastPedHandle[playerId] = ped
        minigames.Player.lastHealth[playerId] = health
        minigames.Player.lastPedCoords[playerId] = coords
        return
    end

    -- health transition fallback: missed the death edge, but saw dead health -> alive health.
    if phase ~= "dead"
        and previousHealth ~= -1
        and previousHealth <= 0
        and health ~= -1
        and health > 0 then
        minigames.StartRespawnDeathCycle(playerId, "health transition <=0 -> >0", now - (minigames.S.respawnDelayMs or 1250))
        minigames.Player.respawnReadyMs[playerId] = now
        phase = "dead"
        deathAt = minigames.Player.deathDetectedMs[playerId] or now
    end

    -- known death cycle. prefer aliveenough, but do not require it forever.
    if phase == "dead" then
        local elapsedSinceDeath = (deathAt ~= 0) and (now - deathAt) or 0
        local forceReadyAfterMs = minigames.S.respawnForceReadyAfterMs or 6500
        local maxWaitMs = minigames.S.respawnMaxWaitBeforeForceSpawnMs or 9500
        local readyReason = nil

        if aliveEnough then
            readyReason = "aliveEnough"
        elseif elapsedSinceDeath >= forceReadyAfterMs and ped ~= 0 then
            readyReason = "forced-ready-after-timeout"
        end

        if readyReason ~= nil and minigames.Player.respawnReadyMs[playerId] == 0 then
            minigames.Player.respawnReadyMs[playerId] = now
            minigames.Player.respawnForcedReadyMs[playerId] = now
            minigames.LogInfo(
                "[Respawn Watcher] Respawn ready | player=" .. tostring(playerId) ..
                " | name=" .. minigames.GetPlayerName(playerId) ..
                " | reason=" .. tostring(readyReason) ..
                " | elapsedMs=" .. tostring(elapsedSinceDeath) ..
                " | health=" .. tostring(health) ..
                " | ped=" .. tostring(ped)
            )
        end

        local readyAt = minigames.Player.respawnReadyMs[playerId] or 0
        local shouldSpawn = false
        local spawnReason = "Known Death Respawn"

        if readyAt ~= 0 and now - readyAt >= (minigames.S.respawnDelayMs or 1250) then
            shouldSpawn = true
            if readyReason == "forced-ready-after-timeout" then
                spawnReason = "Forced Ready Respawn"
            end
        elseif elapsedSinceDeath >= maxWaitMs and ped ~= 0 then
            -- ultimate backstop: if readyat somehow never gets set, still spawn once.
            shouldSpawn = true
            spawnReason = "Max Wait Respawn Fallback"
            if minigames.RoutineLogInfoV171 then
                minigames.RoutineLogInfoV171(
                    "[Respawn Watcher] max-wait fallback firing | player=" .. tostring(playerId) ..
                    " | name=" .. minigames.GetPlayerName(playerId) ..
                    " | serial=" .. tostring(minigames.Player.respawnDeathSerial[playerId] or 0) ..
                    " | elapsedMs=" .. tostring(elapsedSinceDeath) ..
                    " | aliveEnough=" .. tostring(aliveEnough) ..
                    " | health=" .. tostring(health)
                )
            end
        end

        if shouldSpawn then
            local activeSerial = minigames.Player.respawnDeathSerial[playerId] or 0

            if minigames.Player.respawnLastSpawnDeathSerial[playerId] ~= activeSerial then
                minigames.EnqueueRespawnFromWatcher(playerId, vehicleResolver, activeSerial, spawnReason)
            else
                minigames.Player.respawnPhase[playerId] = "spawned"
            end
        end

        minigames.Player.lastPedHandle[playerId] = ped
        minigames.Player.lastHealth[playerId] = health
        minigames.Player.lastPedCoords[playerId] = coords
        return
    end

    -- fallback: ped swap / position jump while alive.
    local pedChanged = previousPed ~= 0 and ped ~= 0 and previousPed ~= ped
    local movedFar = false
    local dist = 0.0

    if minigames.Distance2D and previousCoords and coords then
        dist = minigames.Distance2D(previousCoords, coords)
        movedFar = dist >= (minigames.S.respawnPositionJumpDistance or 45.0)
    end

    local enoughSamples = (minigames.Player.respawnSampleCount[playerId] or 0) >= 4
    local lastFallback = minigames.Player.respawnFallbackSpawnMs[playerId] or 0
    local lastAnySpawn = minigames.Player.respawnVehicleSpawnedAtMs[playerId] or 0
    local fallbackCooldown = minigames.S.respawnFallbackCooldownMs or 12000
    local anySpawnCooldown = minigames.S.respawnMinimumSpawnGapMs or 7000
    local notInVehicle = true

    if minigames.IsPlayerInAnyVehicle then
        notInVehicle = not minigames.IsPlayerInAnyVehicle(playerId)
    end

    if aliveEnough and enoughSamples and notInVehicle then
        local canFallback = true
        if lastFallback ~= 0 and now - lastFallback < fallbackCooldown then canFallback = false end
        if lastAnySpawn ~= 0 and now - lastAnySpawn < anySpawnCooldown then canFallback = false end

        if canFallback and ((minigames.S.enableRespawnPedChangeFallback == true and pedChanged) or (minigames.S.enableRespawnPositionJumpFallback == true and movedFar)) then
            local newSerial = (minigames.Player.respawnDeathSerial[playerId] or 0) + 1
            minigames.Player.respawnDeathSerial[playerId] = newSerial
            minigames.Player.respawnFallbackSpawnMs[playerId] = now

            local reasonText = "fallback"
            if pedChanged and movedFar then
                reasonText = "ped+position respawn fallback"
            elseif pedChanged then
                reasonText = "ped-change respawn fallback"
            elseif movedFar then
                reasonText = "position-jump respawn fallback " .. tostring(math.floor(dist)) .. "m"
            end

            minigames.LogInfo(
                "[Respawn Watcher] " .. reasonText ..
                " | player=" .. tostring(playerId) ..
                " | name=" .. minigames.GetPlayerName(playerId) ..
                " | oldPed=" .. tostring(previousPed) ..
                " | newPed=" .. tostring(ped)
            )

            minigames.EnqueueRespawnFromWatcher(playerId, vehicleResolver, newSerial, reasonText)
        end
    end

    if aliveEnough then
        minigames.Player.lastAliveSeenMs[playerId] = now
    end

    minigames.Player.lastPedHandle[playerId] = ped
    minigames.Player.lastHealth[playerId] = health
    minigames.Player.lastPedCoords[playerId] = coords
end


------------------------------------------------------------
-- v0.109 hard fallback guard
------------------------------------------------------------
-- if older fallback code exists above this point, settings keep it disabled:
minigames.S.enableRespawnPositionJumpFallback = minigames.S.enableRespawnPositionJumpFallback == true
minigames.S.enableRespawnPedChangeFallback = minigames.S.enableRespawnPedChangeFallback == true


------------------------------------------------------------
-- v0.116 respawn gap neutralizer
------------------------------------------------------------
minigames.S.serialRespawnPerPlayerGapMs = 0
minigames.S.respawnMinimumSpawnGapMs = 0
end

-- ============================================================
-- embedded module: systems\scheduler.lua
-- ============================================================
embedded_modules['systems\\scheduler.lua'] = function()
--[[
    minigames/systems/scheduler.lua
    build: v0.171-alpha

    lightweight scheduler for wargames.
    prevents vehicle freeze by keeping heavy logic out of feature callbacks.
]]

minigames.Scheduler = minigames.Scheduler or {
    lastTickMs = 0,
    tickMs = 250,
    times = {}
}

function minigames.Scheduler.ShouldRun(name, intervalMs)
    local now = minigames.Now()
    local last = minigames.Scheduler.times[name] or 0

    if last ~= 0 and now - last < intervalMs then
        return false
    end

    minigames.Scheduler.times[name] = now
    return true
end

function minigames.Scheduler.RunPart(label, fn)
    if type(fn) ~= "function" then
        return
    end

    local ok, err = direct_call_trace(fn, debug.traceback)

    if not ok then
        minigames.S.lastSchedulerError = tostring(label) .. ": " .. tostring(err)
        minigames.LogError("[Scheduler] " .. tostring(label) .. " failed: " .. tostring(err))
    end
end

function minigames.Scheduler.Tick()
    local now = minigames.Now()
    local last = minigames.Scheduler.lastTickMs or 0

    if last ~= 0 and now - last < (minigames.Scheduler.tickMs or 250) then
        return
    end

    minigames.Scheduler.lastTickMs = now

    if minigames.Scheduler.ShouldRun("RefreshPlayers", 1000) then
        minigames.Scheduler.RunPart("RefreshPlayers", function()
            minigames.RefreshPlayers()
        end)
    end

    if minigames.S.wargamesSystemsActive == true then
        minigames.Scheduler.RunPart("WarGamesSystems", function()
            if minigames.WarGames and minigames.WarGames.SystemsSafeTick then
                minigames.WarGames.SystemsSafeTick()
            end
        end)
    end

    if minigames.S.respawnWatcherRunning == true or minigames.S.respawnVehiclesOnPlayerRespawn == true or minigames.S.spawnVehiclesOnRespawn == true then
        minigames.Scheduler.RunPart("RespawnWatcher", function()
            if minigames.WarGames and minigames.WarGames.RespawnWatcherTick then
                minigames.WarGames.RespawnWatcherTick()
            end
        end)
    end

    if minigames.S.wargamesNoBountyMode ~= true and (minigames.S.autoBountyRunning == true or minigames.S.autoBountyEnabled == true) then
        minigames.Scheduler.RunPart("AutoBounty", function()
            if minigames.WarGames and minigames.WarGames.AutoBountyTick then
                minigames.WarGames.AutoBountyTick()
            end
        end)
    end

    if minigames.S.autoCleanupWarGamesVehicles == true then
        minigames.Scheduler.RunPart("VehicleCleanup", function()
            if minigames.VehicleCleanupTick then
                minigames.VehicleCleanupTick()
            end
        end)
    end



    if minigames.S.noCopsEnabled == true then
        minigames.Scheduler.RunPart("Peacekeeper", function()
            if minigames.Peacekeeper and minigames.Peacekeeper.Tick then
                minigames.Peacekeeper.Tick()
            end
        end)
    end

    if minigames.S.autoRemoveRestrictedWeapons == true then
        minigames.Scheduler.RunPart("WeaponCleanup", function()
            if minigames.WeaponCleanupTick then
                minigames.WeaponCleanupTick()
            end
        end)
    end



    if minigames.S.loyaltyPerksEnabled == true then
        minigames.Scheduler.RunPart("LoyaltyPerks", function()
            if minigames.Perks and minigames.Perks.Tick then
                minigames.Perks.Tick()
            end
        end)
    end

    if minigames.S.autoFairVehicleEnforcement == true or minigames.S.fairVehicleEnforcementEnabled == true then
        minigames.Scheduler.RunPart("FairVehicle", function()
            if minigames.FairVehicleTick then
                minigames.FairVehicleTick()
            end
        end)
    end
end


------------------------------------------------------------
-- v0.094 scheduler hardening override
------------------------------------------------------------
function minigames.Scheduler.SafeTrace(err)
    if debug and debug.traceback then
        return debug.traceback(err)
    end
    return tostring(err)
end

function minigames.Scheduler.RunPart(label, fn)
    if type(fn) ~= "function" then
        return true
    end

    local ok, err = direct_call_trace(fn, minigames.Scheduler.SafeTrace)

    if not ok then
        minigames.S.lastSchedulerError = tostring(label) .. ": " .. tostring(err)
        minigames.LogError("[Scheduler] " .. tostring(label) .. " failed: " .. tostring(err))
        return false
    end

    return true
end

function minigames.Scheduler.Tick()
    local okAll, errAll = direct_call_trace(function()
        local now = minigames.Now()
        local last = minigames.Scheduler.lastTickMs or 0

        if last ~= 0 and now - last < (minigames.Scheduler.tickMs or 250) then
            return
        end

        minigames.Scheduler.lastTickMs = now

        if minigames.Scheduler.ShouldRun("RefreshPlayers", 1000) then
            minigames.Scheduler.RunPart("RefreshPlayers", function()
                if minigames.RefreshPlayers then minigames.RefreshPlayers() end
            end)
        end

        if minigames.S.wargamesSystemsActive == true then
            minigames.Scheduler.RunPart("WarGamesSystems", function()
                if minigames.WarGames and minigames.WarGames.SystemsSafeTick then
                    minigames.WarGames.SystemsSafeTick()
                end
            end)
        end

        if minigames.S.respawnWatcherRunning == true
            or minigames.S.respawnVehiclesOnPlayerRespawn == true
            or minigames.S.spawnVehiclesOnRespawn == true then
            minigames.Scheduler.RunPart("RespawnWatcher", function()
                if minigames.WarGames and minigames.WarGames.RespawnWatcherTick then
                    minigames.WarGames.RespawnWatcherTick()
                end
            end)
        end

        if minigames.S.wargamesNoBountyMode ~= true
            and (minigames.S.autoBountyRunning == true or minigames.S.autoBountyEnabled == true) then
            minigames.Scheduler.RunPart("AutoBounty", function()
                if minigames.WarGames and minigames.WarGames.AutoBountyTick then
                    minigames.WarGames.AutoBountyTick()
                end
            end)
        end

        if minigames.S.autoCleanupWarGamesVehicles == true then
            minigames.Scheduler.RunPart("VehicleCleanup", function()
                if minigames.VehicleCleanupTick then
                    minigames.VehicleCleanupTick()
                end
            end)
        end

        if minigames.S.noCopsEnabled == true then
            minigames.Scheduler.RunPart("Peacekeeper", function()
                if minigames.Peacekeeper and minigames.Peacekeeper.Tick then
                    minigames.Peacekeeper.Tick()
                end
            end)
        end

        if minigames.S.autoRemoveRestrictedWeapons == true then
            minigames.Scheduler.RunPart("WeaponCleanup", function()
                if minigames.WeaponCleanupTick then
                    minigames.WeaponCleanupTick()
                end
            end)
        end

        if minigames.S.loyaltyPerksEnabled == true then
            minigames.Scheduler.RunPart("LoyaltyPerks", function()
                if minigames.Perks and minigames.Perks.Tick then
                    minigames.Perks.Tick()
                end
            end)
        end

        if minigames.S.autoFairVehicleEnforcement == true or minigames.S.fairVehicleEnforcementEnabled == true then
            minigames.Scheduler.RunPart("FairVehicle", function()
                if minigames.FairVehicleTick then
                    minigames.FairVehicleTick()
                end
            end)
        end
    end, minigames.Scheduler.SafeTrace)

    if not okAll then
        minigames.S.lastSchedulerError = "Scheduler.Tick: " .. tostring(errAll)
        minigames.LogError("[Scheduler] Tick failed but was swallowed: " .. tostring(errAll))
    end

    return true
end


------------------------------------------------------------
-- v0.095 scheduler feature safety marker
------------------------------------------------------------
minigames.Scheduler.noYieldSpawnQueueEnabled = true


------------------------------------------------------------
-- v0.096 scheduler final table-safety tick override
------------------------------------------------------------
function minigames.Scheduler.Tick()
    local okAll, errAll = direct_call_trace(function()
        if minigames.EnsurePlayerTables then
            minigames.EnsurePlayerTables()
        end

        local now = minigames.Now()
        local last = minigames.Scheduler.lastTickMs or 0

        if last ~= 0 and now - last < (minigames.Scheduler.tickMs or 250) then
            return true
        end

        minigames.Scheduler.lastTickMs = now

        if minigames.Scheduler.ShouldRun("RefreshPlayers", 1000) then
            minigames.Scheduler.RunPart("RefreshPlayers", function()
                if minigames.RefreshPlayers then minigames.RefreshPlayers() end
            end)
        end

        if minigames.S.wargamesSystemsActive == true then
            minigames.Scheduler.RunPart("WarGamesSystems", function()
                if minigames.WarGames and minigames.WarGames.SystemsSafeTick then
                    minigames.WarGames.SystemsSafeTick()
                end
            end)
        end

        if minigames.S.respawnWatcherRunning == true
            or minigames.S.respawnVehiclesOnPlayerRespawn == true
            or minigames.S.spawnVehiclesOnRespawn == true then
            minigames.Scheduler.RunPart("RespawnWatcher", function()
                if minigames.WarGames and minigames.WarGames.RespawnWatcherTick then
                    minigames.WarGames.RespawnWatcherTick()
                end
            end)
        end

        if minigames.S.wargamesNoBountyMode ~= true
            and (minigames.S.autoBountyRunning == true or minigames.S.autoBountyEnabled == true) then
            minigames.Scheduler.RunPart("AutoBounty", function()
                if minigames.WarGames and minigames.WarGames.AutoBountyTick then
                    minigames.WarGames.AutoBountyTick()
                end
            end)
        end

        if minigames.S.autoCleanupWarGamesVehicles == true then
            minigames.Scheduler.RunPart("VehicleCleanup", function()
                if minigames.VehicleCleanupTick then
                    minigames.VehicleCleanupTick()
                end
            end)
        end

        if minigames.S.noCopsEnabled == true then
            minigames.Scheduler.RunPart("Peacekeeper", function()
                if minigames.Peacekeeper and minigames.Peacekeeper.Tick then
                    minigames.Peacekeeper.Tick()
                end
            end)
        end

        if minigames.S.autoRemoveRestrictedWeapons == true then
            minigames.Scheduler.RunPart("WeaponCleanup", function()
                if minigames.WeaponCleanupTick then
                    minigames.WeaponCleanupTick()
                end
            end)
        end

        if minigames.S.loyaltyPerksEnabled == true then
            minigames.Scheduler.RunPart("LoyaltyPerks", function()
                if minigames.Perks and minigames.Perks.Tick then
                    minigames.Perks.Tick()
                end
            end)
        end

        if minigames.S.autoFairVehicleEnforcement == true or minigames.S.fairVehicleEnforcementEnabled == true then
            minigames.Scheduler.RunPart("FairVehicle", function()
                if minigames.FairVehicleTick then
                    minigames.FairVehicleTick()
                end
            end)
        end

        return true
    end, minigames.Scheduler.SafeTrace or function(e) return tostring(e) end)

    if not okAll then
        minigames.S.lastSchedulerError = "Scheduler.Tick: " .. tostring(errAll)
        minigames.LogError("[Scheduler] Tick failed but was swallowed: " .. tostring(errAll))
    end

    return true
end

------------------------------------------------------------
-- v0.097 scheduler queued ontick runner
------------------------------------------------------------
-- cherax can throw a generic feature exception if anything inside the
-- ontick fiber tries to yield or perform heavy native work. this wrapper
-- makes the feature callback only queue the real scheduler work.
------------------------------------------------------------

function minigames.Scheduler.QueueTick()
    minigames.S = minigames.S or {}

    local now = minigames.Now()
    local minQueueMs = minigames.S.schedulerQueueIntervalMs or 250

    if minigames.S.schedulerJobRunning == true then
        return true, "running"
    end

    if minigames.S.lastSchedulerQueuedMs ~= nil and minigames.S.lastSchedulerQueuedMs ~= 0 then
        if now - minigames.S.lastSchedulerQueuedMs < minQueueMs then
            return true, "cooldown"
        end
    end

    minigames.S.lastSchedulerQueuedMs = now
    minigames.S.schedulerJobRunning = true

    local function run_scheduler_job()
        local ok, err = direct_call_trace(function()
            if minigames.Scheduler and minigames.Scheduler.Tick then
                minigames.Scheduler.Tick()
            end
        end, minigames.Scheduler.SafeTrace or function(e) return tostring(e) end)

        minigames.S.schedulerJobRunning = false

        if not ok then
            minigames.S.lastSchedulerError = "Queued scheduler job: " .. tostring(err)
            minigames.LogError("[Scheduler Queue] job failed: " .. tostring(err))
        end
    end

    if Script and Script.QueueJob then
        Script.QueueJob(run_scheduler_job)
        return true, "queued"
    end

    -- fallback for older builds. keep this protected.
    run_scheduler_job()
    return true, "direct"
end


------------------------------------------------------------
-- v0.098 final scheduler safety override
------------------------------------------------------------
-- queuetick itself must never throw, because it is called from cherax ontick.
-- all real work is wrapped inside a queued job and every branch is protected.
------------------------------------------------------------
function minigames.Scheduler.QueueTick()
    local okOuter, errOuter = direct_call_trace(function()
        local now = minigames.Now()
        local minQueueMs = minigames.S.schedulerQueueIntervalMs or 350

        if minigames.S.schedulerJobPending == true then
            return true
        end

        if minigames.S.lastSchedulerQueuedMs ~= nil and minigames.S.lastSchedulerQueuedMs ~= 0 then
            if now - minigames.S.lastSchedulerQueuedMs < minQueueMs then
                return true
            end
        end

        minigames.S.lastSchedulerQueuedMs = now
        minigames.S.schedulerJobPending = true

        local function run_job()
            local okJob, errJob = direct_call_trace(function()
                if minigames.Scheduler and minigames.Scheduler.Tick then
                    minigames.Scheduler.Tick()
                end
            end, debug and debug.traceback or function(e) return tostring(e) end)

            minigames.S.schedulerJobPending = false

            if not okJob then
                minigames.S.lastSchedulerError = "Queued scheduler job: " .. tostring(errJob)
                minigames.LogError("[Scheduler Queue] job failed: " .. tostring(errJob))
            end
        end

        if Script and Script.QueueJob then
            local okQueue, errQueue = direct_call(function()
                Script.QueueJob(run_job)
            end)

            if not okQueue then
                minigames.S.schedulerJobPending = false
                minigames.S.lastSchedulerError = "Script.QueueJob failed: " .. tostring(errQueue)
                minigames.LogError("[Scheduler Queue] QueueJob failed: " .. tostring(errQueue))
            end
        else
            run_job()
        end

        return true
    end, debug and debug.traceback or function(e) return tostring(e) end)

    if not okOuter then
        minigames.S.schedulerJobPending = false
        minigames.S.lastSchedulerError = "QueueTick outer: " .. tostring(errOuter)
        minigames.LogError("[Scheduler Queue] outer failed but was swallowed: " .. tostring(errOuter))
    end

    return true
end


------------------------------------------------------------
-- v0.099 final scheduler background service
------------------------------------------------------------
-- important:
-- cherax kept throwing generic feature exceptions from the old ontick
-- scheduler feature. the real scheduler now runs inside one queued
-- background job, where yielding is allowed and heavy work is safer.
------------------------------------------------------------
function minigames.Scheduler.StartBackgroundLoop()
    minigames.S = minigames.S or {}

    if minigames.S.schedulerBackgroundRunning == true then
        return true, "already_running"
    end

    minigames.S.schedulerBackgroundEnabled = true
    minigames.S.schedulerBackgroundRunning = true
    minigames.S.schedulerJobPending = false
    minigames.S.lastSchedulerError = "None"

    local function loop()
        minigames.LogInfo("[Scheduler Service] background loop started")

        while minigames.S and minigames.S.schedulerBackgroundEnabled ~= false do
            local ok, err = direct_call_trace(function()
                if minigames.Scheduler and minigames.Scheduler.Tick then
                    minigames.Scheduler.Tick()
                end
            end, debug and debug.traceback or function(e) return tostring(e) end)

            if not ok then
                minigames.S.lastSchedulerError = "Background scheduler: " .. tostring(err)
                minigames.LogError("[Scheduler Service] tick failed but loop continues: " .. tostring(err))
            end

            if Script and Script.Yield then
                Script.Yield(minigames.S.schedulerBackgroundLoopMs or 250)
            elseif SYSTEM and SYSTEM.WAIT then
                SYSTEM.WAIT(minigames.S.schedulerBackgroundLoopMs or 250)
            else
                break
            end
        end

        minigames.S.schedulerBackgroundRunning = false
        minigames.LogInfo("[Scheduler Service] background loop stopped")
    end

    if Script and Script.QueueJob then
        local okQueue, errQueue = direct_call(function()
            Script.QueueJob(loop)
        end)

        if not okQueue then
            minigames.S.schedulerBackgroundRunning = false
            minigames.S.lastSchedulerError = "StartBackgroundLoop QueueJob failed: " .. tostring(errQueue)
            minigames.LogError("[Scheduler Service] QueueJob failed: " .. tostring(errQueue))
            return false, errQueue
        end

        return true, "queued"
    end

    minigames.S.schedulerBackgroundRunning = false
    minigames.S.lastSchedulerError = "Script.QueueJob missing; scheduler service not started"
    minigames.LogError("[Scheduler Service] Script.QueueJob missing; cannot start background scheduler")
    return false, "queuejob_missing"
end

-- v0.099: queuetick is now a harmless compatibility shim. it does not
-- perform work from a feature ontick callback anymore.
function minigames.Scheduler.QueueTick()
    if minigames.S.schedulerBackgroundRunning ~= true and minigames.Scheduler.StartBackgroundLoop then
        minigames.Scheduler.StartBackgroundLoop()
    end
    return true, "background_service"
end


