-- ============================================================
-- embedded module: systems\teleport.lua
-- ============================================================
embedded_modules['systems\\teleport.lua'] = function()
--[[
    minigames/systems/teleport.lua
    build: v0.171-alpha

    v0.061:
    - removes queued/yielding teleport loop.
    - teleport is direct + direct call protected to avoid fiber errors.
    - adds anti-spam cooldown for manual teleport buttons.
]]

function minigames.GetPlayerVehicleIfAny(playerId)
    local ped = minigames.GetPlayerPed(playerId)

    if not ped or ped == 0 or not minigames.EntityExists(ped) then
        return 0
    end

    if PED and PED.GET_VEHICLE_PED_IS_IN then
        local ok, veh = direct_call(function()
            return PED.GET_VEHICLE_PED_IS_IN(ped, false)
        end)

        if ok and veh and veh ~= 0 and minigames.EntityExists(veh) then
            return veh
        end
    end

    return 0
end

function minigames.TeleportEntity(entity, location)
    if not entity or entity == 0 or not minigames.EntityExists(entity) then
        return false, "entity_missing"
    end

    if not location then
        return false, "location_missing"
    end

    local x = tonumber(location.x or location.X)
    local y = tonumber(location.y or location.Y)
    local z = tonumber(location.z or location.Z)
    local heading = tonumber(location.heading or location.Heading or 0.0)

    if not x or not y or not z then
        return false, "bad_coords"
    end

    local ok, err = direct_call(function()
        if ENTITY and ENTITY.SET_ENTITY_AS_MISSION_ENTITY then
            ENTITY.SET_ENTITY_AS_MISSION_ENTITY(entity, true, true)
        end

        if ENTITY and ENTITY.SET_ENTITY_COORDS_NO_OFFSET then
            ENTITY.SET_ENTITY_COORDS_NO_OFFSET(entity, x, y, z, false, false, false)
        elseif ENTITY and ENTITY.SET_ENTITY_COORDS then
            ENTITY.SET_ENTITY_COORDS(entity, x, y, z, false, false, false, true)
        else
            error("missing SET_ENTITY_COORDS native")
        end

        if ENTITY and ENTITY.SET_ENTITY_HEADING then
            ENTITY.SET_ENTITY_HEADING(entity, heading)
        end
    end)

    if ok then
        return true, "teleported"
    end

    return false, tostring(err)
end

function minigames.TeleportPlayerToLocation(playerId, location, includeVehicle)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if not minigames.IsPlayerActive(playerId) then
        return false, "inactive"
    end

    local ped = minigames.GetPlayerPed(playerId)

    if not ped or ped == 0 or not minigames.EntityExists(ped) then
        return false, "ped_missing"
    end

    local entity = ped

    if includeVehicle == true then
        local veh = minigames.GetPlayerVehicleIfAny(playerId)

        if veh and veh ~= 0 then
            entity = veh
        end
    end

    local ok, status = minigames.TeleportEntity(entity, location)

    if ok then
        minigames.S.lastTeleportStatus =
            "Teleported " ..
            minigames.GetPlayerName(playerId) ..
            " to " ..
            tostring(location.label or location.id or "location")
    else
        minigames.S.lastTeleportStatus =
            "Failed teleport " ..
            minigames.GetPlayerName(playerId) ..
            " | " ..
            tostring(status)
    end

    minigames.LogInfo("[Teleport] " .. minigames.S.lastTeleportStatus)

    return ok, status
end

function minigames.TeleportAllPlayersToLocation(location, includeVehicle, reason)
    if not location then
        minigames.Toast("WarGames Teleport", "No teleport location selected.", 4000)
        return
    end

    local now = minigames.Now()
    local last = minigames.S.lastTeleportActionMs or 0
    local cooldown = minigames.S.teleportButtonCooldownMs or 1200

    if tostring(reason or ""):find("Auto") == nil and last ~= 0 and now - last < cooldown then
        minigames.LogInfo("[Teleport] skipped duplicate manual teleport due to cooldown.")
        return
    end

    minigames.S.lastTeleportActionMs = now

    local applied = 0
    local failed = 0

    local okLoop, errLoop = direct_call(function()
        minigames.RefreshPlayers()

        for _, playerId in ipairs(minigames.S.activePlayers or {}) do
            local ok = false
            local status = "unknown"

            ok, status = minigames.TeleportPlayerToLocation(playerId, location, includeVehicle == true)

            if ok then
                applied = applied + 1
            else
                failed = failed + 1
            end
        end
    end)

    if not okLoop then
        minigames.S.lastTeleportStatus = "Teleport all error: " .. tostring(errLoop)
        minigames.LogError("[Teleport] " .. minigames.S.lastTeleportStatus)
        minigames.Toast("WarGames Teleport Failed", minigames.S.lastTeleportStatus, 6000)
        return
    end

    minigames.S.lastTeleportCount = applied
    minigames.S.lastTeleportFailed = failed
    minigames.S.lastTeleportLocation = tostring(location and location.label or "Unknown")
    minigames.S.lastTeleportStatus =
        "Teleport all complete | location=" ..
        minigames.S.lastTeleportLocation ..
        " | teleported=" ..
        tostring(applied) ..
        " | failed=" ..
        tostring(failed) ..
        " | reason=" ..
        tostring(reason or "Manual")

    minigames.LogInfo("[Teleport] " .. minigames.S.lastTeleportStatus)

    if minigames.S.teleportNotificationEnabled ~= false then
        minigames.Toast("WarGames Teleport", minigames.S.lastTeleportStatus, 6000)
    end
end


function minigames.IsTeleportRoundModeEnabled()
    -- teleport mode means the lobby location is controlled by teleport logic.
    -- this covers both recommended-location and selected-location round teleports.
    return minigames.S.autoTeleportOnVehicleRoundChange == true
        or minigames.S.autoTeleportSelectedOnRoundChange == true
        or minigames.S.teleportRoundModeEnabled == true
end

function minigames.GetActiveTeleportSpawnLocation()
    if not minigames.WarGames then
        return nil
    end

    if minigames.S.autoTeleportSelectedOnRoundChange == true and minigames.WarGames.GetSelectedTeleport then
        return minigames.WarGames.GetSelectedTeleport()
    end

    if minigames.S.autoTeleportOnVehicleRoundChange == true and minigames.WarGames.GetRecommendedTeleportForVehicle then
        local vehicle = nil

        if minigames.WarGames.GetCurrentRoundVehicle then
            vehicle = minigames.WarGames.GetCurrentRoundVehicle()
        elseif minigames.WarGames.GetSelectedVehicle then
            vehicle = minigames.WarGames.GetSelectedVehicle()
        end

        return minigames.WarGames.GetRecommendedTeleportForVehicle(vehicle)
    end

    if minigames.WarGames.GetSelectedTeleport then
        return minigames.WarGames.GetSelectedTeleport()
    end

    return nil
end


------------------------------------------------------------
-- v0.103 built-in remote teleport fix
------------------------------------------------------------
-- user-tested result:
-- - land on it -> remote tp -> built-in remote tp: send all to maze bank worked instantly.
-- - direct coordinate teleport is unreliable for multiple remote players.
--
-- new default:
-- - wargames group tp uses built-in remote teleport style first.
-- - maze bank uses the exact built-in send all to maze bank trigger.
-- - other custom locations:
--     1. teleport local player to selected coordinates.
--     2. trigger built-in teleport all to me.
--     3. fallback to old direct coordinate tp only if built-in method fails.
------------------------------------------------------------

minigames.RemoteTeleport = minigames.RemoteTeleport or {}

minigames.RemoteTeleport.FeatureNames = {
    SendAllToMazeBank = {
        "Send All to Maze Bank",
        "Send All To Maze Bank",
        "Remote Teleport: Send All to Maze Bank",
        "Remote Teleport - Send All to Maze Bank"
    },

    SendAllToChilliad = {
        "Send All to Mt. Chilliad",
        "Send All To Mt. Chilliad",
        "Send All to Mount Chilliad",
        "Send All To Mount Chilliad",
        "Remote Teleport: Send All to Mt. Chilliad",
        "Remote Teleport - Send All to Mt. Chilliad"
    },

    TeleportAllToMe = {
        "Teleport All To Me",
        "Teleport All to Me",
        "Remote Teleport: Teleport All To Me",
        "Remote Teleport - Teleport All To Me"
    },

    SendAllToWaypoint = {
        "Send All To My Waypoint",
        "Send All to My Waypoint",
        "Teleport All To My Waypoint",
        "Remote Teleport: Send All To My Waypoint",
        "Remote Teleport - Send All To My Waypoint"
    }
}

function minigames.TriggerBuiltInRemoteTeleportKey(key)
    local names = minigames.RemoteTeleport.FeatureNames[key] or {}
    local lastErr = "no_names"

    for _, name in ipairs(names) do
        local okGet, feature = direct_call(function()
            return FeatureMgr.GetFeatureByName(name)
        end)

        if okGet and feature then
            local okTrigger, errTrigger = direct_call(function()
                feature:TriggerCallback()
            end)

            if okTrigger then
                minigames.S.lastRemoteTeleportFeature = tostring(name)
                minigames.S.lastRemoteTeleportStatus = "Triggered built-in remote TP: " .. tostring(name)
                minigames.LogInfo("[Remote TP] " .. minigames.S.lastRemoteTeleportStatus)
                return true, name
            end

            lastErr = tostring(errTrigger)
        else
            lastErr = "feature not found: " .. tostring(name)
        end
    end

    minigames.S.lastRemoteTeleportStatus =
        "Built-in remote TP failed | key=" ..
        tostring(key) ..
        " | lastErr=" ..
        tostring(lastErr)

    minigames.LogError("[Remote TP] " .. minigames.S.lastRemoteTeleportStatus)
    return false, lastErr
end

function minigames.IsMazeBankTeleport(location)
    local id = tostring(location and location.id or ""):lower()
    local label = tostring(location and location.label or ""):lower()
    return id:find("mazebank") ~= nil
        or id:find("maze") ~= nil
        or label:find("maze") ~= nil
end

function minigames.IsChilliadTeleport(location)
    local id = tostring(location and location.id or ""):lower()
    local label = tostring(location and location.label or ""):lower()
    return id:find("chilliad") ~= nil
        or id:find("chiliad") ~= nil
        or label:find("chilliad") ~= nil
        or label:find("chiliad") ~= nil
end

function minigames.TeleportLocalPlayerToRemoteAnchor(location, includeVehicle)
    local localId = minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or 0

    local ok, status = minigames.TeleportPlayerToLocation(localId, location, includeVehicle == true)

    if ok then
        minigames.LogInfo(
            "[Remote TP] Local anchor moved to " ..
            tostring(location and location.label or "location") ..
            " before built-in Teleport All To Me."
        )
    else
        minigames.LogError(
            "[Remote TP] Failed moving local anchor before built-in remote TP | status=" ..
            tostring(status)
        )
    end

    return ok, status
end

function minigames.RemoteTeleportAllPlayersToLocation(location, includeVehicle, reason)
    if not location then
        minigames.Toast("Remote TP", "No teleport location selected.", 4000)
        return false, "location_missing"
    end

    local now = minigames.Now()
    local last = minigames.S.lastRemoteTeleportActionMs or 0
    local cooldown = minigames.S.remoteTeleportButtonCooldownMs or 1500

    if tostring(reason or ""):find("Auto") == nil and last ~= 0 and now - last < cooldown then
        minigames.LogInfo("[Remote TP] skipped duplicate manual remote teleport due to cooldown.")
        return false, "cooldown"
    end

    minigames.S.lastRemoteTeleportActionMs = now

    local function remote_job()
        local label = tostring(location.label or location.id or "location")
        local ok = false
        local status = "not_run"

        -- best known working path.
        if minigames.IsMazeBankTeleport(location) then
            ok, status = minigames.TriggerBuiltInRemoteTeleportKey("SendAllToMazeBank")
        elseif minigames.IsChilliadTeleport(location) and minigames.S.tryDirectChilliadBuiltInTp == true then
            -- optional: tried only if user enables it later. some built-ins may not work reliably.
            ok, status = minigames.TriggerBuiltInRemoteTeleportKey("SendAllToChilliad")
        end

        -- universal built-in method:
        -- move host/local anchor to desired coordinates, then use built-in teleport all to me.
        if not ok then
            local moved = false
            local moveStatus = "not_attempted"

            moved, moveStatus = minigames.TeleportLocalPlayerToRemoteAnchor(location, includeVehicle == true)

            if moved then
                if Script and Script.Yield then
                    direct_call(function()
                        Script.Yield(minigames.S.remoteTeleportAnchorDelayMs or 450)
                    end)
                end

                ok, status = minigames.TriggerBuiltInRemoteTeleportKey("TeleportAllToMe")
            else
                status = "anchor_move_failed: " .. tostring(moveStatus)
            end
        end

        if ok then
            minigames.S.lastTeleportLocation = label
            minigames.S.lastTeleportStatus =
                "Built-in remote TP complete | location=" ..
                label ..
                " | method=" ..
                tostring(status) ..
                " | reason=" ..
                tostring(reason or "Manual")

            minigames.LogInfo("[Remote TP] " .. minigames.S.lastTeleportStatus)

            if minigames.S.teleportNotificationEnabled ~= false then
                minigames.Toast("Remote TP", minigames.S.lastTeleportStatus, 6000)
            end

            return
        end

        -- final fallback to old direct coordinate teleport.
        if minigames.S.remoteTeleportFallbackToDirect ~= false and minigames.TeleportAllPlayersToLocationDirect then
            minigames.LogError("[Remote TP] built-in method failed; falling back to direct coordinate TP | status=" .. tostring(status))
            minigames.TeleportAllPlayersToLocationDirect(location, includeVehicle, tostring(reason or "Manual") .. " | fallback_direct_after_builtin")
            return
        end

        minigames.S.lastTeleportStatus =
            "Built-in remote TP failed | location=" ..
            label ..
            " | status=" ..
            tostring(status)

        minigames.LogError("[Remote TP] " .. minigames.S.lastTeleportStatus)
        minigames.Toast("Remote TP Failed", minigames.S.lastTeleportStatus, 6000)
    end

    if Script and Script.QueueJob then
        Script.QueueJob(remote_job)
        minigames.S.lastTeleportStatus =
            "Built-in remote TP queued | location=" ..
            tostring(location.label or location.id or "location") ..
            " | reason=" ..
            tostring(reason or "Manual")
        minigames.LogInfo("[Remote TP] " .. minigames.S.lastTeleportStatus)
        return true, "queued"
    end

    remote_job()
    return true, "ran_direct"
end

-- preserve old direct-coordinate method, then override the public group teleport function.
minigames.TeleportAllPlayersToLocationDirect = minigames.TeleportAllPlayersToLocationDirect or minigames.TeleportAllPlayersToLocation

function minigames.TeleportAllPlayersToLocation(location, includeVehicle, reason)
    if minigames.S.useBuiltInRemoteTeleportForGroups ~= false then
        return minigames.RemoteTeleportAllPlayersToLocation(location, includeVehicle, reason)
    end

    return minigames.TeleportAllPlayersToLocationDirect(location, includeVehicle, reason)
end

function minigames.SearchRemoteTeleportFeatures()
    if not FeatureMgr or not FeatureMgr.SearchFeatures then
        minigames.Toast("Remote TP Search", "FeatureMgr.SearchFeatures unavailable.", 4000)
        return
    end

    local ok, results = direct_call(function()
        return FeatureMgr.SearchFeatures("Teleport")
    end)

    minigames.LogInfo("========== Global Remote Teleport Feature Search ==========")
    minigames.LogInfo("Search ok=" .. tostring(ok))

    if ok and type(results) == "table" then
        for i, feature in ipairs(results) do
            local name = "unknown"
            local hash = "unknown"
            local desc = ""

            direct_call(function() name = feature:GetName() end)
            direct_call(function() hash = feature:GetHash() end)
            direct_call(function() desc = feature:GetDescription() end)

            minigames.LogInfo("Result " .. tostring(i) .. " | hash=" .. tostring(hash) .. " | name=" .. tostring(name) .. " | desc=" .. tostring(desc))
        end
    end

    minigames.LogInfo("==========================================================")
    minigames.Toast("Remote TP Search", "Printed teleport feature search to log.", 4000)
end

------------------------------------------------------------
-- v0.155 per-player built-in remote teleport
------------------------------------------------------------
-- known-working cherax feature pattern:
--   featuremgr.getfeaturebyname("teleport to me", playerid):triggercallback()
--   featuremgr.getfeaturebyname("send to my waypoint", playerid):triggercallback()
--
-- unlike direct entity-coordinate teleport or "teleport all" group features,
-- these per-player actions do not depend on the player being near the host.
------------------------------------------------------------

minigames.PerPlayerRemoteTeleport = minigames.PerPlayerRemoteTeleport or {}

minigames.PerPlayerRemoteTeleport.FeatureNames = {
    TeleportToMe = {
        "Teleport To Me",
        "Teleport to Me",
    },

    SendToMyWaypoint = {
        "Send To My Waypoint",
        "Send to My Waypoint",
    },
}

function minigames.PerPlayerRemoteTeleport.Now()
    return minigames.Now and minigames.Now() or 0
end

function minigames.PerPlayerRemoteTeleport.GetLocalPlayerId()
    if minigames.GetLocalPlayerId then
        local ok, playerId = direct_call(minigames.GetLocalPlayerId)
        if ok and tonumber(playerId) then
            return minigames.ClampInt(playerId, 0, 31)
        end
    end

    if PLAYER and PLAYER.PLAYER_ID then
        local ok, playerId = direct_call(function()
            return PLAYER.PLAYER_ID()
        end)
        if ok and tonumber(playerId) then
            return minigames.ClampInt(playerId, 0, 31)
        end
    end

    return 0
end

function minigames.PerPlayerRemoteTeleport.GetPlayerName(playerId)
    if minigames.GetPlayerName then
        local ok, name = direct_call(minigames.GetPlayerName, playerId)
        if ok and name then return tostring(name) end
    end

    return "Player " .. tostring(playerId)
end

function minigames.PerPlayerRemoteTeleport.GetEntityCoords(entity)
    if not entity or entity == 0 then return nil end

    if ENTITY and ENTITY.GET_ENTITY_COORDS then
        local ok, coords = direct_call(function()
            return ENTITY.GET_ENTITY_COORDS(entity, true)
        end)

        if ok and coords then
            local x = tonumber(coords.x or coords.X or coords[1])
            local y = tonumber(coords.y or coords.Y or coords[2])
            local z = tonumber(coords.z or coords.Z or coords[3])

            if x and y and z then
                return {
                    x = x,
                    y = y,
                    z = z,
                }
            end
        end
    end

    return nil
end

function minigames.PerPlayerRemoteTeleport.GetEntityHeading(entity)
    if not entity or entity == 0 then return 0.0 end

    if ENTITY and ENTITY.GET_ENTITY_HEADING then
        local ok, heading = direct_call(function()
            return ENTITY.GET_ENTITY_HEADING(entity)
        end)
        if ok and tonumber(heading) then
            return tonumber(heading)
        end
    end

    return 0.0
end

function minigames.PerPlayerRemoteTeleport.GetLocalAnchorEntity(includeVehicle)
    local localId = minigames.PerPlayerRemoteTeleport.GetLocalPlayerId()
    local ped = minigames.GetPlayerPed and minigames.GetPlayerPed(localId) or 0

    if includeVehicle == true and minigames.GetPlayerVehicleIfAny then
        local vehicle = minigames.GetPlayerVehicleIfAny(localId)
        if vehicle and vehicle ~= 0 then
            return vehicle, localId
        end
    end

    return ped, localId
end

function minigames.PerPlayerRemoteTeleport.FreezeEntity(entity, enabled)
    if not entity or entity == 0 then return end

    if ENTITY and ENTITY.FREEZE_ENTITY_POSITION then
        direct_call(function()
            ENTITY.FREEZE_ENTITY_POSITION(entity, enabled == true)
        end)
    end
end

function minigames.PerPlayerRemoteTeleport.SaveAnchor(includeVehicle)
    local entity, localId =
        minigames.PerPlayerRemoteTeleport.GetLocalAnchorEntity(includeVehicle)

    if not entity or entity == 0 then
        return nil, "local_anchor_missing"
    end

    local coords = minigames.PerPlayerRemoteTeleport.GetEntityCoords(entity)
    if not coords then
        return nil, "local_anchor_coords_missing"
    end

    return {
        entity = entity,
        localId = localId,
        x = coords.x,
        y = coords.y,
        z = coords.z,
        heading = minigames.PerPlayerRemoteTeleport.GetEntityHeading(entity),
        includeVehicle = includeVehicle == true,
    }, "saved"
end

function minigames.PerPlayerRemoteTeleport.MoveAnchor(anchor, location)
    if not anchor or not location then
        return false, "bad_anchor_or_location"
    end

    if minigames.S.perPlayerRemoteTeleportFreezeAnchor ~= false then
        minigames.PerPlayerRemoteTeleport.FreezeEntity(anchor.entity, true)
    end

    local ok, status = minigames.TeleportEntity(anchor.entity, location)

    if not ok then
        minigames.PerPlayerRemoteTeleport.FreezeEntity(anchor.entity, false)
        return false, status
    end

    return true, "anchor_moved"
end

function minigames.PerPlayerRemoteTeleport.RestoreAnchor(anchor)
    if not anchor or not anchor.entity or anchor.entity == 0 then
        return false, "anchor_missing"
    end

    local original = {
        x = anchor.x,
        y = anchor.y,
        z = anchor.z,
        heading = anchor.heading,
        label = "Original Host Position",
    }

    local ok, status = minigames.TeleportEntity(anchor.entity, original)
    minigames.PerPlayerRemoteTeleport.FreezeEntity(anchor.entity, false)

    return ok, status
end

function minigames.PerPlayerRemoteTeleport.CleanHistory()
    minigames.S.perPlayerRemoteTeleportHistory =
        minigames.S.perPlayerRemoteTeleportHistory or {}

    local now = minigames.PerPlayerRemoteTeleport.Now()
    local keepMs =
        tonumber(minigames.S.perPlayerRemoteTeleportRecentMs or 60000) or 60000

    for key, entry in pairs(minigames.S.perPlayerRemoteTeleportHistory) do
        local timestamp = 0

        if type(entry) == "table" then
            timestamp = tonumber(entry.timeMs or 0) or 0
        else
            timestamp = tonumber(entry or 0) or 0
        end

        if timestamp == 0 or now - timestamp > keepMs * 3 then
            minigames.S.perPlayerRemoteTeleportHistory[key] = nil
        end
    end
end

function minigames.PerPlayerRemoteTeleport.WasRecentlyTeleported(playerId)
    minigames.PerPlayerRemoteTeleport.CleanHistory()

    local entry =
        minigames.S.perPlayerRemoteTeleportHistory and
        minigames.S.perPlayerRemoteTeleportHistory[tostring(playerId)]

    if not entry then
        return false, 0
    end

    local currentName =
        minigames.PerPlayerRemoteTeleport.GetPlayerName(playerId)
    local timestamp = 0
    local storedName = nil

    if type(entry) == "table" then
        timestamp = tonumber(entry.timeMs or 0) or 0
        storedName = tostring(entry.playerName or "")
    else
        timestamp = tonumber(entry or 0) or 0
    end

    -- player ids may be reused. a different name gets a fresh teleport.
    if storedName and storedName ~= "" and storedName ~= currentName then
        minigames.S.perPlayerRemoteTeleportHistory[tostring(playerId)] = nil
        return false, 0
    end

    local now = minigames.PerPlayerRemoteTeleport.Now()
    local cooldown =
        tonumber(minigames.S.perPlayerRemoteTeleportRecentMs or 60000) or 60000
    local remaining = cooldown - (now - timestamp)

    return remaining > 0, math.max(0, remaining)
end

function minigames.PerPlayerRemoteTeleport.MarkTeleported(playerId, action)
    minigames.S.perPlayerRemoteTeleportHistory =
        minigames.S.perPlayerRemoteTeleportHistory or {}

    minigames.S.perPlayerRemoteTeleportHistory[tostring(playerId)] = {
        timeMs = minigames.PerPlayerRemoteTeleport.Now(),
        playerName = minigames.PerPlayerRemoteTeleport.GetPlayerName(playerId),
        action = tostring(action or "remote_teleport"),
    }
end

function minigames.PerPlayerRemoteTeleport.TriggerPlayerFeature(
    playerId,
    actionKey
)
    playerId = minigames.ClampInt(playerId, 0, 31)

    local names =
        minigames.PerPlayerRemoteTeleport.FeatureNames[actionKey] or {}
    local lastError = "feature_names_missing"

    for _, featureName in ipairs(names) do
        local feature = nil
        local okGet, getResult = direct_call(function()
            return FeatureMgr.GetFeatureByName(featureName, playerId)
        end)

        if okGet then
            feature = getResult
        else
            lastError = tostring(getResult)
        end

        if feature then
            local okTrigger, triggerError = direct_call(function()
                feature:TriggerCallback()
            end)

            if okTrigger then
                minigames.PerPlayerRemoteTeleport.MarkTeleported(
                    playerId,
                    actionKey
                )

                return true, featureName
            end

            lastError = tostring(triggerError)
        else
            lastError = "feature_not_found:" .. tostring(featureName)
        end
    end

    return false, lastError
end

function minigames.PerPlayerRemoteTeleport.GetEligiblePlayers()
    minigames.RefreshPlayers()

    local players = {}
    local localId = minigames.PerPlayerRemoteTeleport.GetLocalPlayerId()

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        playerId = minigames.ClampInt(playerId, 0, 31)

        if not (
            minigames.S.perPlayerRemoteTeleportSkipSelf ~= false and
            playerId == localId
        ) then
            players[#players + 1] = playerId
        end
    end

    table.sort(players)
    return players
end

function minigames.PerPlayerRemoteTeleport.RunSequential(
    actionKey,
    reason,
    options
)
    options = options or {}

    if minigames.S.perPlayerRemoteTeleportEnabled ~= true then
        return false, "disabled"
    end

    local function job()
        local players =
            minigames.PerPlayerRemoteTeleport.GetEligiblePlayers()

        local attempted = 0
        local triggered = 0
        local skippedRecent = 0
        local failed = 0
        local skippedNames = {}
        local failedNames = {}

        for _, playerId in ipairs(players) do
            local recent, remaining =
                minigames.PerPlayerRemoteTeleport.WasRecentlyTeleported(playerId)

            if recent then
                skippedRecent = skippedRecent + 1
                skippedNames[#skippedNames + 1] =
                    minigames.PerPlayerRemoteTeleport.GetPlayerName(playerId) ..
                    "(" .. tostring(math.ceil(remaining / 1000)) .. "s)"
            else
                attempted = attempted + 1

                local ok, status =
                    minigames.PerPlayerRemoteTeleport.TriggerPlayerFeature(
                        playerId,
                        actionKey
                    )

                if ok then
                    triggered = triggered + 1

                    if minigames.LogInfo then
                        minigames.LogInfo(
                            "[Per-Player Remote TP] triggered | player=" ..
                            minigames.PerPlayerRemoteTeleport.GetPlayerName(playerId) ..
                            " [" .. tostring(playerId) .. "]" ..
                            " | action=" .. tostring(actionKey) ..
                            " | feature=" .. tostring(status)
                        )
                    end
                else
                    failed = failed + 1
                    failedNames[#failedNames + 1] =
                        minigames.PerPlayerRemoteTeleport.GetPlayerName(playerId) ..
                        "(" .. tostring(status) .. ")"

                    if minigames.LogError then
                        minigames.LogError(
                            "[Per-Player Remote TP] failed | player=" ..
                            minigames.PerPlayerRemoteTeleport.GetPlayerName(playerId) ..
                            " [" .. tostring(playerId) .. "]" ..
                            " | action=" .. tostring(actionKey) ..
                            " | status=" .. tostring(status)
                        )
                    end
                end

                local delay =
                    tonumber(
                        minigames.S.perPlayerRemoteTeleportDelayMs or 225
                    ) or 225

                if Script and Script.Yield then
                    Script.Yield(delay)
                end
            end
        end

        if options.anchor and
            minigames.S.perPlayerRemoteTeleportRestoreAnchor ~= false then
            local restoreDelay =
                tonumber(
                    minigames.S.perPlayerRemoteTeleportRestoreDelayMs or 650
                ) or 650

            if Script and Script.Yield then
                Script.Yield(restoreDelay)
            end

            minigames.PerPlayerRemoteTeleport.RestoreAnchor(options.anchor)
        end

        minigames.S.lastTeleportCount = triggered
        minigames.S.lastTeleportFailed = failed
        minigames.S.lastTeleportLocation =
            tostring(options.locationLabel or actionKey)
        minigames.S.perPlayerRemoteTeleportLastStatus =
            "complete | action=" .. tostring(actionKey) ..
            " | players=" .. tostring(#players) ..
            " | attempted=" .. tostring(attempted) ..
            " | triggered=" .. tostring(triggered) ..
            " | skippedRecent=" .. tostring(skippedRecent) ..
            " | failed=" .. tostring(failed) ..
            " | reason=" .. tostring(reason or "Manual")

        minigames.S.lastTeleportStatus =
            "Per-player remote TP " ..
            minigames.S.perPlayerRemoteTeleportLastStatus

        if minigames.LogInfo then
            minigames.LogInfo(
                "[Per-Player Remote TP] " ..
                minigames.S.perPlayerRemoteTeleportLastStatus
            )

            if #skippedNames > 0 then
                minigames.LogInfo(
                    "[Per-Player Remote TP] skipped recent: " ..
                    table.concat(skippedNames, ", ")
                )
            end

            if #failedNames > 0 then
                minigames.LogInfo(
                    "[Per-Player Remote TP] failures: " ..
                    table.concat(failedNames, ", ")
                )
            end
        end

        if minigames.Toast then
            minigames.Toast(
                "WarGames Remote TP",
                "Triggered " .. tostring(triggered) ..
                " | Recent " .. tostring(skippedRecent) ..
                " | Failed " .. tostring(failed),
                6000
            )
        end
    end

    if Script and Script.QueueJob then
        Script.QueueJob(job)

        minigames.S.lastTeleportStatus =
            "Per-player remote TP queued | action=" ..
            tostring(actionKey) ..
            " | reason=" .. tostring(reason or "Manual")

        return true, "queued"
    end

    job()
    return true, "ran_direct"
end

function minigames.PerPlayerRemoteTeleport.TeleportEveryoneToWaypoint(reason)
    return minigames.PerPlayerRemoteTeleport.RunSequential(
        "SendToMyWaypoint",
        reason or "Everyone To My Waypoint",
        {
            locationLabel = "My Waypoint",
        }
    )
end

function minigames.PerPlayerRemoteTeleport.TeleportEveryoneToLocation(
    location,
    includeVehicle,
    reason
)
    if not location then
        if minigames.Toast then
            minigames.Toast(
                "WarGames Remote TP",
                "No teleport location selected.",
                4000
            )
        end
        return false, "location_missing"
    end

    local anchor, saveStatus =
        minigames.PerPlayerRemoteTeleport.SaveAnchor(includeVehicle == true)

    if not anchor then
        return false, saveStatus
    end

    local moved, moveStatus =
        minigames.PerPlayerRemoteTeleport.MoveAnchor(anchor, location)

    if not moved then
        return false, moveStatus
    end

    local delay =
        tonumber(
            minigames.S.perPlayerRemoteTeleportAnchorDelayMs or 450
        ) or 450

    local function queue_after_anchor()
        if Script and Script.Yield then
            Script.Yield(delay)
        end

        minigames.PerPlayerRemoteTeleport.RunSequential(
            "TeleportToMe",
            reason or "Everyone To Location",
            {
                anchor = anchor,
                locationLabel =
                    tostring(location.label or location.id or "Location"),
            }
        )
    end

    if Script and Script.QueueJob then
        Script.QueueJob(queue_after_anchor)
        return true, "anchor_moved_and_queued"
    end

    queue_after_anchor()
    return true, "anchor_moved_and_ran"
end

-- final public group teleport:
-- every custom/recommended location uses the per-player built-in teleport to me.
function minigames.TeleportAllPlayersToLocation(
    location,
    includeVehicle,
    reason
)
    if minigames.S.perPlayerRemoteTeleportEnabled == true then
        return minigames.PerPlayerRemoteTeleport.TeleportEveryoneToLocation(
            location,
            includeVehicle,
            reason
        )
    end

    if minigames.S.useBuiltInRemoteTeleportForGroups ~= false then
        return minigames.RemoteTeleportAllPlayersToLocation(
            location,
            includeVehicle,
            reason
        )
    end

    return minigames.TeleportAllPlayersToLocationDirect(
        location,
        includeVehicle,
        reason
    )
end

function minigames.TeleportEveryoneToMyWaypointV155(reason)
    -- v0.194: manual group waypoint teleport mirrors the exact cherax action
    -- that works from player > general > remote teleport > send to my waypoint.
    -- an explicit button press must not be blocked by the old 60-second
    -- per-player history cooldown.
    local function job()
        local players = minigames.PerPlayerRemoteTeleport.GetEligiblePlayers()
        local attempted, triggered, failed = 0, 0, 0
        local failedNames = {}

        for _, playerId in ipairs(players) do
            attempted = attempted + 1
            local ok, status = minigames.PerPlayerRemoteTeleport.TriggerPlayerFeature(
                playerId,
                "SendToMyWaypoint"
            )
            if ok then
                triggered = triggered + 1
            else
                failed = failed + 1
                failedNames[#failedNames + 1] =
                    minigames.PerPlayerRemoteTeleport.GetPlayerName(playerId) ..
                    "(" .. tostring(status) .. ")"
            end
            if Script and Script.Yield then Script.Yield(225) end
        end

        minigames.S.lastTeleportStatus =
            "Waypoint TP | moved=" .. tostring(triggered) ..
            " / " .. tostring(attempted) ..
            " | failed=" .. tostring(failed)

        if minigames.Toast then
            if triggered > 0 then
                minigames.Toast(
                    "WarGames TP",
                    "Sent " .. tostring(triggered) ..
                    " player" .. (triggered == 1 and "" or "s") ..
                    " to your waypoint.",
                    4000
                )
            elseif attempted == 0 then
                minigames.Toast("WarGames TP", "No remote players detected.", 3500)
            else
                minigames.Toast("WarGames TP", "Send To My Waypoint was unavailable for the detected players.", 4500)
            end
        end

        if failed > 0 and minigames.LogError then
            minigames.LogError(
                "[Per-Player Remote TP] waypoint group failures | " ..
                table.concat(failedNames, ", ")
            )
        end
    end

    if Script and Script.QueueJob then
        Script.QueueJob(job)
        minigames.S.lastTeleportStatus = tostring(reason or "Everyone To My Waypoint") .. " queued"
        return true, "queued"
    end

    job()
    return true, "ran_direct"
end

end

-- ============================================================
-- embedded module: systems\ui_lab.lua
-- ============================================================
embedded_modules['systems\\ui_lab.lua'] = function()
--[[
    minigames/systems/ui_lab.lua
    build: v0.171-alpha

    purpose:
    - test multiple cherax/imgui menu creation methods.
    - helps identify which methods are actually clickable in this build.

    tests:
    1. clickgui.renderfeature + featuremgr button
    2. imgui.button
    3. imgui.smallbutton + sameline
    4. imgui.selectable rows
    5. imgui.invisiblebutton fallback
]]

minigames.UILab = minigames.UILab or {}
minigames.UILab.H = minigames.UILab.H or {}
minigames.UILab.S = minigames.UILab.S or {
    lastClicked = "None",
    lastError = "None",
    totalClicks = 0,
    methodClicks = {},
    supported = {},
    notes = {}
}

function minigames.UILab.Hash(name)
    return minigames.Hash("UILab_" .. tostring(name))
end

minigames.UILab.H.FEATURE_BUTTON_A = minigames.UILab.Hash("FeatureButtonA")
minigames.UILab.H.FEATURE_BUTTON_B = minigames.UILab.Hash("FeatureButtonB")
minigames.UILab.H.FEATURE_TOGGLE = minigames.UILab.Hash("FeatureToggle")
minigames.UILab.H.PRINT_RESULTS = minigames.UILab.Hash("PrintResults")
minigames.UILab.H.RESET_RESULTS = minigames.UILab.Hash("ResetResults")

function minigames.UILab.MarkClick(method, detail)
    method = tostring(method or "Unknown")
    detail = tostring(detail or "")

    minigames.UILab.S.totalClicks = (minigames.UILab.S.totalClicks or 0) + 1
    minigames.UILab.S.methodClicks[method] = (minigames.UILab.S.methodClicks[method] or 0) + 1
    minigames.UILab.S.lastClicked = method .. (detail ~= "" and (" | " .. detail) or "")

    minigames.LogInfo("[UI Lab] CLICKED | method=" .. method .. " | detail=" .. detail .. " | total=" .. tostring(minigames.UILab.S.totalClicks))
    minigames.Toast("UI Lab", "Clicked: " .. method, 2500)
end

function minigames.UILab.MarkError(method, err)
    method = tostring(method or "Unknown")
    err = tostring(err or "Unknown error")
    minigames.UILab.S.lastError = method .. " | " .. err
    minigames.LogError("[UI Lab] ERROR | method=" .. method .. " | " .. err)
end

function minigames.UILab.TryCall(method, fn)
    local ok, result = direct_call(fn)

    if ok then
        minigames.UILab.S.supported[method] = true
        return result
    end

    minigames.UILab.S.supported[method] = false
    minigames.UILab.MarkError(method, result)
    return nil
end

function minigames.UILab.SafeText(text)
    if ImGui and ImGui.Text then
        direct_call(function() ImGui.Text(tostring(text)) end)
    end
end

function minigames.UILab.SafeSeparator()
    if ImGui and ImGui.Separator then
        direct_call(function() ImGui.Separator() end)
    end
end

function minigames.UILab.SafeSameLine()
    if ImGui and ImGui.SameLine then
        direct_call(function() ImGui.SameLine() end)
    end
end

function minigames.UILab.PrintResults()
    minigames.LogInfo("========== UI Lab Results ==========")
    minigames.LogInfo("Total Clicks: " .. tostring(minigames.UILab.S.totalClicks or 0))
    minigames.LogInfo("Last Clicked: " .. tostring(minigames.UILab.S.lastClicked or "None"))
    minigames.LogInfo("Last Error: " .. tostring(minigames.UILab.S.lastError or "None"))

    for method, count in pairs(minigames.UILab.S.methodClicks or {}) do
        minigames.LogInfo("Method: " .. tostring(method) .. " | clicks=" .. tostring(count))
    end

    for method, supported in pairs(minigames.UILab.S.supported or {}) do
        minigames.LogInfo("Supported: " .. tostring(method) .. " = " .. tostring(supported))
    end

    minigames.LogInfo("====================================")
    minigames.Toast("UI Lab", "Printed UI Lab results to log.", 3000)
end

function minigames.UILab.ResetResults()
    minigames.UILab.S.lastClicked = "None"
    minigames.UILab.S.lastError = "None"
    minigames.UILab.S.totalClicks = 0
    minigames.UILab.S.methodClicks = {}
    minigames.UILab.S.supported = {}
    minigames.Toast("UI Lab", "Results reset.", 2500)
end

FeatureMgr.AddFeature(
    minigames.UILab.H.FEATURE_BUTTON_A,
    "UI Test 1A - Feature Button",
    eFeatureType.Button,
    "Test ClickGUI.RenderFeature + FeatureMgr.AddFeature button.",
    function()
        minigames.UILab.MarkClick("FeatureMgr Button", "1A")
    end
)

FeatureMgr.AddFeature(
    minigames.UILab.H.FEATURE_BUTTON_B,
    "UI Test 1B - Feature Button",
    eFeatureType.Button,
    "Second FeatureMgr button test.",
    function()
        minigames.UILab.MarkClick("FeatureMgr Button", "1B")
    end
)

FeatureMgr.AddFeature(
    minigames.UILab.H.FEATURE_TOGGLE,
    "UI Test 1C - Feature Toggle",
    eFeatureType.Toggle,
    "Test FeatureMgr toggle click callback.",
    function(f)
        minigames.UILab.MarkClick("FeatureMgr Toggle", "state=" .. tostring(f:IsToggled()))
    end
)
:SetDefaultValue(false)
:Reset()

FeatureMgr.AddFeature(
    minigames.UILab.H.PRINT_RESULTS,
    "UI Lab - Print Results",
    eFeatureType.Button,
    "Prints UI test results to log.",
    function()
        minigames.UILab.PrintResults()
    end
)

FeatureMgr.AddFeature(
    minigames.UILab.H.RESET_RESULTS,
    "UI Lab - Reset Results",
    eFeatureType.Button,
    "Clears UI test counters.",
    function()
        minigames.UILab.ResetResults()
    end
)

function minigames.UILab.RenderMethod1_FeatureMgr()
    if ClickGUI.BeginCustomChildWindow("Test 1 - ClickGUI.RenderFeature") then
        minigames.UILab.SafeText("Known Cherax method. If this works, FeatureMgr buttons are reliable.")
        ClickGUI.RenderFeature(minigames.UILab.H.FEATURE_BUTTON_A)
        ClickGUI.RenderFeature(minigames.UILab.H.FEATURE_BUTTON_B)
        ClickGUI.RenderFeature(minigames.UILab.H.FEATURE_TOGGLE)
        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.UILab.RenderMethod2_ImGuiButton()
    if ClickGUI.BeginCustomChildWindow("Test 2 - ImGui.Button") then
        minigames.UILab.SafeText("Immediate-mode ImGui.Button inside CustomChildWindow.")

        if ImGui and ImGui.Button then
            local clicked = minigames.UILab.TryCall("ImGui.Button", function()
                return ImGui.Button("ImGui.Button Click Me##UILabButtonA")
            end)

            if clicked then
                minigames.UILab.MarkClick("ImGui.Button", "A")
            end

            local clicked2 = minigames.UILab.TryCall("ImGui.Button", function()
                return ImGui.Button("ImGui.Button Second##UILabButtonB")
            end)

            if clicked2 then
                minigames.UILab.MarkClick("ImGui.Button", "B")
            end
        else
            minigames.UILab.SafeText("ImGui.Button unavailable.")
        end

        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.UILab.RenderMethod3_SmallButtons()
    if ClickGUI.BeginCustomChildWindow("Test 3 - ImGui.SmallButton / SameLine") then
        minigames.UILab.SafeText("Compact inline button method.")

        if ImGui and ImGui.SmallButton then
            local minus = minigames.UILab.TryCall("ImGui.SmallButton", function()
                return ImGui.SmallButton("-##UILabSmallMinus")
            end)
            if minus then minigames.UILab.MarkClick("ImGui.SmallButton", "minus") end

            minigames.UILab.SafeSameLine()

            local plus = minigames.UILab.TryCall("ImGui.SmallButton", function()
                return ImGui.SmallButton("+##UILabSmallPlus")
            end)
            if plus then minigames.UILab.MarkClick("ImGui.SmallButton", "plus") end

            minigames.UILab.SafeSameLine()

            local next = minigames.UILab.TryCall("ImGui.SmallButton", function()
                return ImGui.SmallButton("Next##UILabSmallNext")
            end)
            if next then minigames.UILab.MarkClick("ImGui.SmallButton", "next") end
        else
            minigames.UILab.SafeText("ImGui.SmallButton unavailable.")
        end

        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.UILab.RenderMethod4_Selectable()
    if ClickGUI.BeginCustomChildWindow("Test 4 - ImGui.Selectable Rows") then
        minigames.UILab.SafeText("Selectable row method. Good for compact player lists.")

        if ImGui and ImGui.Selectable then
            local rows = { "Spawn Vehicle To All", "Force Bounty All", "Cleanup Vehicles", "Next Vehicle Round" }

            for i, label in ipairs(rows) do
                local clicked = minigames.UILab.TryCall("ImGui.Selectable", function()
                    return ImGui.Selectable(label .. "##UILabSelectable" .. tostring(i))
                end)

                if clicked then
                    minigames.UILab.MarkClick("ImGui.Selectable", label)
                end
            end
        else
            minigames.UILab.SafeText("ImGui.Selectable unavailable.")
        end

        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.UILab.RenderMethod5_InvisibleButton()
    if ClickGUI.BeginCustomChildWindow("Test 5 - InvisibleButton / Text Row") then
        minigames.UILab.SafeText("Attempts invisible click-zone method. May fail if this binding needs vector args.")

        if ImGui and ImGui.InvisibleButton then
            minigames.UILab.SafeText("[ Click Zone A ]")
            local clicked = minigames.UILab.TryCall("ImGui.InvisibleButton", function()
                return ImGui.InvisibleButton("UILabInvisibleA", 120, 22)
            end)
            if clicked then minigames.UILab.MarkClick("ImGui.InvisibleButton", "A") end

            minigames.UILab.SafeText("[ Click Zone B ]")
            local clicked2 = minigames.UILab.TryCall("ImGui.InvisibleButton", function()
                return ImGui.InvisibleButton("UILabInvisibleB", 120, 22)
            end)
            if clicked2 then minigames.UILab.MarkClick("ImGui.InvisibleButton", "B") end
        else
            minigames.UILab.SafeText("ImGui.InvisibleButton unavailable.")
        end

        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.UILab.RenderStatus()
    if ClickGUI.BeginCustomChildWindow("UI Lab Status / Results") then
        minigames.UILab.SafeText("Click each test. If it works, toast/log says CLICKED.")
        minigames.UILab.SafeText("Total Clicks: " .. tostring(minigames.UILab.S.totalClicks or 0))
        minigames.UILab.SafeText("Last Clicked: " .. tostring(minigames.UILab.S.lastClicked or "None"))
        minigames.UILab.SafeText("Last Error: " .. tostring(minigames.UILab.S.lastError or "None"))
        ClickGUI.RenderFeature(minigames.UILab.H.PRINT_RESULTS)
        ClickGUI.RenderFeature(minigames.UILab.H.RESET_RESULTS)
        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.UILab.Render()
    if ImGui and ImGui.BeginTabBar and ImGui.BeginTabItem then
        if ImGui.BeginTabBar("Minigames_UILab_Tabs_v079") then
            if ImGui.BeginTabItem("Status") then minigames.UILab.RenderStatus() ImGui.EndTabItem() end
            if ImGui.BeginTabItem("1 FeatureMgr") then minigames.UILab.RenderMethod1_FeatureMgr() ImGui.EndTabItem() end
            if ImGui.BeginTabItem("2 Button") then minigames.UILab.RenderMethod2_ImGuiButton() ImGui.EndTabItem() end
            if ImGui.BeginTabItem("3 Small") then minigames.UILab.RenderMethod3_SmallButtons() ImGui.EndTabItem() end
            if ImGui.BeginTabItem("4 Selectable") then minigames.UILab.RenderMethod4_Selectable() ImGui.EndTabItem() end
            if ImGui.BeginTabItem("5 Invisible") then minigames.UILab.RenderMethod5_InvisibleButton() ImGui.EndTabItem() end
            ImGui.EndTabBar()
        end
    else
        minigames.UILab.RenderStatus()
        minigames.UILab.RenderMethod1_FeatureMgr()
        minigames.UILab.RenderMethod2_ImGuiButton()
        minigames.UILab.RenderMethod3_SmallButtons()
        minigames.UILab.RenderMethod4_Selectable()
        minigames.UILab.RenderMethod5_InvisibleButton()
    end
end

minigames.LogInfo("[UI Lab] Loaded five UI click test methods.")
end

