-- ============================================================
embedded_modules['systems\\upgrades.lua'] = function()
-- minigames/systems/upgrades.lua

function minigames.ApplyRawVehicleUpgrades(vehicleEntity)
    if not vehicleEntity or vehicleEntity == 0 then return false end
    if not VEHICLE then return false end

    direct_call(function()
        if VEHICLE.SET_VEHICLE_MOD_KIT then
            VEHICLE.SET_VEHICLE_MOD_KIT(vehicleEntity, 0)
        end
    end)

    if minigames.S.rawVehicleMatteBlack ~= false then
        direct_call(function()
            if VEHICLE.SET_VEHICLE_COLOURS then VEHICLE.SET_VEHICLE_COLOURS(vehicleEntity, 12, 12) end
            if VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicleEntity, 0, 0, 0) end
            if VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR then VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicleEntity, 0, 0, 0) end
            if VEHICLE.SET_VEHICLE_WINDOW_TINT then VEHICLE.SET_VEHICLE_WINDOW_TINT(vehicleEntity, 1) end
            if VEHICLE.SET_VEHICLE_DIRT_LEVEL then VEHICLE.SET_VEHICLE_DIRT_LEVEL(vehicleEntity, 0.0) end
        end)
    end

    if minigames.S.rawVehicleBlackWheels ~= false then
        direct_call(function()
            if VEHICLE.SET_VEHICLE_EXTRA_COLOURS then VEHICLE.SET_VEHICLE_EXTRA_COLOURS(vehicleEntity, 0, 0) end
            if VEHICLE.SET_VEHICLE_WHEEL_TYPE then VEHICLE.SET_VEHICLE_WHEEL_TYPE(vehicleEntity, 7) end
            if VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR then VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR(vehicleEntity, 0, 0, 0) end
        end)
    end

    if minigames.S.maxUpgradeRawVehicles ~= false then
        for modType = 0, 49 do
            direct_call(function()
                if VEHICLE.GET_NUM_VEHICLE_MODS and VEHICLE.SET_VEHICLE_MOD then
                    local count = VEHICLE.GET_NUM_VEHICLE_MODS(vehicleEntity, modType)
                    if count and count > 0 then
                        VEHICLE.SET_VEHICLE_MOD(vehicleEntity, modType, count - 1, false)
                    end
                end
            end)
        end

        direct_call(function()
            if VEHICLE.TOGGLE_VEHICLE_MOD then
                VEHICLE.TOGGLE_VEHICLE_MOD(vehicleEntity, 18, true)
                VEHICLE.TOGGLE_VEHICLE_MOD(vehicleEntity, 20, true)
                VEHICLE.TOGGLE_VEHICLE_MOD(vehicleEntity, 22, true)
            end
        end)

        for _, slot in ipairs({ 11, 12, 13, 15, 16 }) do
            direct_call(function()
                if VEHICLE.GET_NUM_VEHICLE_MODS and VEHICLE.SET_VEHICLE_MOD then
                    local count = VEHICLE.GET_NUM_VEHICLE_MODS(vehicleEntity, slot)
                    if count and count > 0 then
                        VEHICLE.SET_VEHICLE_MOD(vehicleEntity, slot, count - 1, false)
                    end
                end
            end)
        end
    end

    return true
end


-- v0.069 override: max upgrades only. color is handled by vehicle_spawn.lua random hex color.
function minigames.ApplyRawVehicleUpgrades(vehicleEntity)
    if not vehicleEntity or vehicleEntity == 0 then return false end
    if not VEHICLE then return false end

    direct_call(function()
        if VEHICLE.SET_VEHICLE_MOD_KIT then VEHICLE.SET_VEHICLE_MOD_KIT(vehicleEntity, 0) end
        if VEHICLE.SET_VEHICLE_DIRT_LEVEL then VEHICLE.SET_VEHICLE_DIRT_LEVEL(vehicleEntity, 0.0) end
        if VEHICLE.SET_VEHICLE_WINDOW_TINT then VEHICLE.SET_VEHICLE_WINDOW_TINT(vehicleEntity, 1) end
    end)

    if minigames.S.maxUpgradeRawVehicles ~= false then
        for modType = 0, 49 do
            direct_call(function()
                if VEHICLE.GET_NUM_VEHICLE_MODS and VEHICLE.SET_VEHICLE_MOD then
                    local count = VEHICLE.GET_NUM_VEHICLE_MODS(vehicleEntity, modType)
                    if count and count > 0 then
                        VEHICLE.SET_VEHICLE_MOD(vehicleEntity, modType, count - 1, false)
                    end
                end
            end)
        end

        direct_call(function()
            if VEHICLE.TOGGLE_VEHICLE_MOD then
                VEHICLE.TOGGLE_VEHICLE_MOD(vehicleEntity, 18, true)
                VEHICLE.TOGGLE_VEHICLE_MOD(vehicleEntity, 20, true)
                VEHICLE.TOGGLE_VEHICLE_MOD(vehicleEntity, 22, true)
            end
        end)
    end

    return true
end


------------------------------------------------------------
-- experimental vehicle weapon disable helpers
------------------------------------------------------------
-- v0.071:
-- used by land on it for oppressor mk1 rounds.
-- this is best-effort because weapon/vehicle mod behavior can vary by build.
------------------------------------------------------------

function minigames.DisableVehicleWeaponsExperimental(vehicleEntity, ped)
    if not vehicleEntity or vehicleEntity == 0 then
        return false, "vehicle_missing"
    end

    local changed = 0

    local ok = direct_call(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then
            VEHICLE.SET_VEHICLE_MOD_KIT(vehicleEntity, 0)
        end

        -- common vehicle weapon mod slot attempts.
        -- these are intentionally best-effort; unsupported slots are ignored.
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD then
            for _, modSlot in ipairs({ 10, 14, 15, 16, 40, 41, 42, 43, 44, 45, 46, 47, 48 }) do
                direct_call(function()
                    VEHICLE.SET_VEHICLE_MOD(vehicleEntity, modSlot, -1, false)
                    changed = changed + 1
                end)
            end
        end

        -- toggle weapon-like extras off where possible.
        if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA then
            for extraId = 1, 14 do
                direct_call(function()
                    VEHICLE.SET_VEHICLE_EXTRA(vehicleEntity, extraId, true)
                    changed = changed + 1
                end)
            end
        end

        -- native disable attempts for common vehicle weapons.
        if VEHICLE and VEHICLE.DISABLE_VEHICLE_WEAPON then
            local weaponHashes = {
                0xB5D6687F, -- generic vehicle weapon attempt
                0x6D6FAE43, -- generic missile attempt
                0x7F7497E5, -- generic mg attempt
            }

            for _, weaponHash in ipairs(weaponHashes) do
                direct_call(function()
                    VEHICLE.DISABLE_VEHICLE_WEAPON(true, weaponHash, vehicleEntity, ped or 0)
                    changed = changed + 1
                end)
            end
        end
    end)

    if ok then
        return true, "changed=" .. tostring(changed)
    end

    return false, "native_failed"
end
end

-- ============================================================
-- embedded module: systems\vehicle_rounds.lua
-- ============================================================
embedded_modules['systems\\vehicle_rounds.lua'] = function()
--[[
    minigames/systems/vehicle_rounds.lua
    build: v0.171-alpha

    stable wargames vehicle round controller.

    v0.060:
    - keeps one active vehicle for full round window.
    - adds clear notification only when the round timer expires and vehicle changes:
        previous: xxxx
        new: xxxx
    - optional auto teleport on round change exists, but is off by default.
]]

minigames.VehicleRounds = minigames.VehicleRounds or {}

function minigames.GetRoundVehicleIndex()
    local poolSize = 1

    if minigames.WarGames and minigames.WarGames.VehiclePool then
        poolSize = #minigames.WarGames.VehiclePool
    end

    local index = minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or 1
    return minigames.ClampInt(index, 1, poolSize)
end

function minigames.GetRoundVehicle()
    if not minigames.WarGames or not minigames.WarGames.VehiclePool or #minigames.WarGames.VehiclePool == 0 then
        return nil
    end

    return minigames.WarGames.VehiclePool[minigames.GetRoundVehicleIndex()]
end

function minigames.GetVehicleLabelByIndex(index)
    if minigames.WarGames and minigames.WarGames.VehiclePool and minigames.WarGames.VehiclePool[index] then
        return minigames.WarGames.VehiclePool[index].label
    end

    return "None"
end

function minigames.NotifyVehicleRoundChange(previousLabel, newLabel, reason)
    local title = "WarGames Vehicle Round"
    local message =
        "Time's up!\nPrevious: " ..
        tostring(previousLabel) ..
        "\nNew: " ..
        tostring(newLabel)

    if tostring(reason or "") ~= "" then
        message = message .. "\nReason: " .. tostring(reason)
    end

    minigames.Toast(title, message, 7000)
    minigames.LogInfo("[WarGames Rounds] " .. message:gsub("\n", " | "))
end

function minigames.SetRoundVehicleIndex(index, reason, notify)
    if not minigames.WarGames or not minigames.WarGames.VehiclePool then
        return
    end

    local poolSize = #minigames.WarGames.VehiclePool
    index = minigames.ClampInt(index, 1, poolSize)

    local previous = minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or index
    previous = minigames.ClampInt(previous, 1, poolSize)

    if previous == index and minigames.S.roundStartedAtMs ~= 0 then
        return
    end

    minigames.S.previousRoundVehicleIndex = previous
    minigames.S.roundVehicleIndex = index
    minigames.S.selectedVehicleIndex = index
    minigames.S.roundStartedAtMs = minigames.Now()
    minigames.S.lastVehicleRoundTickMs = minigames.Now()

    local previousLabel = minigames.GetVehicleLabelByIndex(previous)
    local newLabel = minigames.GetVehicleLabelByIndex(index)

    if minigames.S.deletePreviousVehicleTypeOnChange ~= false and previous ~= index then
        if minigames.DeleteTrackedVehiclesByRoundIndex then
            minigames.DeleteTrackedVehiclesByRoundIndex(previous, true, "Round changed from " .. previousLabel .. " to " .. newLabel)
        elseif minigames.DeleteTrackedVehiclesByModel then
            local prevVehicle = minigames.WarGames.VehiclePool[previous]
            if prevVehicle then
                minigames.DeleteTrackedVehiclesByModel(prevVehicle.model, true, "Round changed")
            end
        end
    end

    if minigames.S.deleteAllInactiveRoundVehicles == true then
        if minigames.DeleteInactiveRoundVehicles then
            minigames.DeleteInactiveRoundVehicles(index, true, "New active round vehicle")
        end
    end

    minigames.S.lastVehicleRoundStatus =
        "Vehicle round changed | Previous: " ..
        tostring(previousLabel) ..
        " | New: " ..
        tostring(newLabel) ..
        " | reason=" ..
        tostring(reason or "Unknown")

    minigames.LogInfo("[WarGames Rounds] " .. minigames.S.lastVehicleRoundStatus)

    if notify ~= false and minigames.S.roundChangeNotifyEnabled ~= false then
        minigames.NotifyVehicleRoundChange(previousLabel, newLabel, reason)
    end

    if minigames.S.autoSpawnNewRoundVehicleToAll == true and minigames.WarGames and minigames.WarGames.SpawnVehicleOnAll then
        local okSpawn, errSpawn = direct_call(function()
            minigames.WarGames.SpawnVehicleOnAll(true)
        end)

        if not okSpawn then
            minigames.LogError("[WarGames Rounds] Auto spawn on round change failed: " .. tostring(errSpawn))
        end
    end

    -- future feature:
    -- off by default and not enabled by activate wargames systems.
    if minigames.S.autoTeleportSelectedOnRoundChange == true and minigames.WarGames and minigames.WarGames.TeleportAllToSelected then
        local okTeleportSelected, errTeleportSelected = direct_call(function()
            minigames.WarGames.TeleportAllToSelected("Auto selected-location round change")
        end)

        if not okTeleportSelected then
            minigames.LogError("[WarGames Rounds] Auto selected teleport on round change failed: " .. tostring(errTeleportSelected))
        end
    elseif minigames.S.autoTeleportOnVehicleRoundChange == true and minigames.WarGames and minigames.WarGames.TeleportAllToRecommendedForCurrentRound then
        local okTeleport, errTeleport = direct_call(function()
            minigames.WarGames.TeleportAllToRecommendedForCurrentRound("Auto recommended round change")
        end)

        if not okTeleport then
            minigames.LogError("[WarGames Rounds] Auto recommended teleport on round change failed: " .. tostring(errTeleport))
        end
    end
end

function minigames.RollRandomRoundVehicleIndex()
    if not minigames.WarGames or not minigames.WarGames.VehiclePool then
        return 1
    end

    local poolSize = #minigames.WarGames.VehiclePool
    if poolSize <= 1 then
        return 1
    end

    local current = minigames.GetRoundVehicleIndex()
    local nextIndex = current

    for _ = 1, 8 do
        nextIndex = math.random(1, poolSize)
        if nextIndex ~= current then
            return nextIndex
        end
    end

    if nextIndex == current then
        nextIndex = current + 1
        if nextIndex > poolSize then
            nextIndex = 1
        end
    end

    return nextIndex
end

function minigames.RandomVehicleRoundNow(reason)
    local index = minigames.RollRandomRoundVehicleIndex()
    minigames.SetRoundVehicleIndex(index, reason or "Manual Random Round", true)
end

function minigames.NextVehicleRoundNow(reason)
    if not minigames.WarGames or not minigames.WarGames.VehiclePool then
        return
    end

    local index = minigames.GetRoundVehicleIndex() + 1
    if index > #minigames.WarGames.VehiclePool then
        index = 1
    end

    minigames.SetRoundVehicleIndex(index, reason or "Manual Next Round", true)
end

function minigames.EnsureVehicleRoundStarted()
    if not minigames.S.roundVehicleIndex or minigames.S.roundVehicleIndex <= 0 then
        minigames.S.roundVehicleIndex = minigames.S.selectedVehicleIndex or 1
    end

    if not minigames.S.roundStartedAtMs or minigames.S.roundStartedAtMs == 0 then
        minigames.S.roundStartedAtMs = minigames.Now()
        minigames.S.lastVehicleRoundTickMs = minigames.Now()
        minigames.S.lastVehicleRoundStatus =
            "Vehicle round initialized | Active: " ..
            tostring(minigames.GetVehicleLabelByIndex(minigames.GetRoundVehicleIndex()))

        minigames.LogInfo("[WarGames Rounds] " .. minigames.S.lastVehicleRoundStatus)
    end
end

function minigames.VehicleRoundTick()
    if minigames.S.wargamesSystemsActive ~= true and minigames.S.autoRandomVehicleRounds ~= true then
        return
    end

    if minigames.S.autoRandomVehicleRounds ~= true then
        return
    end

    minigames.EnsureVehicleRoundStarted()

    local now = minigames.Now()
    local roundTime = minigames.S.vehicleRoundTimeMs or 180000
    local started = minigames.S.roundStartedAtMs or now

    if now - started < roundTime then
        return
    end

    minigames.RandomVehicleRoundNow("Round timer expired")
end

function minigames.DeleteTrackedVehiclesByRoundIndex(roundIndex, force, reason)
    minigames.S.spawnedWarGamesVehicles = minigames.S.spawnedWarGamesVehicles or {}

    local kept = {}
    local deleted = 0

    for _, record in ipairs(minigames.S.spawnedWarGamesVehicles) do
        if record.roundIndex == roundIndex then
            if minigames.DeleteVehicleEntity(record.entity) then
                deleted = deleted + 1
                minigames.S.vehicleCleanupDeletedTotal = (minigames.S.vehicleCleanupDeletedTotal or 0) + 1
            else
                table.insert(kept, record)
            end
        else
            table.insert(kept, record)
        end
    end

    minigames.S.spawnedWarGamesVehicles = kept
    minigames.S.deletedWarGamesVehicleCount = (minigames.S.deletedWarGamesVehicleCount or 0) + deleted
    minigames.S.lastVehicleRoundCleanupStatus =
        "Deleted tracked vehicles by round index " ..
        tostring(roundIndex) ..
        " | deleted=" ..
        tostring(deleted) ..
        " | reason=" ..
        tostring(reason or "None")

    minigames.LogInfo("[WarGames Rounds] " .. minigames.S.lastVehicleRoundCleanupStatus)

    return deleted
end

function minigames.DeleteTrackedVehiclesByModel(model, force, reason)
    model = tostring(model or "")
    minigames.S.spawnedWarGamesVehicles = minigames.S.spawnedWarGamesVehicles or {}

    local kept = {}
    local deleted = 0

    for _, record in ipairs(minigames.S.spawnedWarGamesVehicles) do
        if tostring(record.model or "") == model then
            if minigames.DeleteVehicleEntity(record.entity) then
                deleted = deleted + 1
            else
                table.insert(kept, record)
            end
        else
            table.insert(kept, record)
        end
    end

    minigames.S.spawnedWarGamesVehicles = kept
    minigames.S.deletedWarGamesVehicleCount = (minigames.S.deletedWarGamesVehicleCount or 0) + deleted
    minigames.S.lastVehicleRoundCleanupStatus =
        "Deleted tracked vehicles by model " ..
        tostring(model) ..
        " | deleted=" ..
        tostring(deleted) ..
        " | reason=" ..
        tostring(reason or "None")

    minigames.LogInfo("[WarGames Rounds] " .. minigames.S.lastVehicleRoundCleanupStatus)

    return deleted
end

function minigames.DeleteInactiveRoundVehicles(activeRoundIndex, force, reason)
    activeRoundIndex = activeRoundIndex or minigames.GetRoundVehicleIndex()
    minigames.S.spawnedWarGamesVehicles = minigames.S.spawnedWarGamesVehicles or {}

    local kept = {}
    local deleted = 0

    for _, record in ipairs(minigames.S.spawnedWarGamesVehicles) do
        if record.roundIndex ~= activeRoundIndex then
            if minigames.DeleteVehicleEntity(record.entity) then
                deleted = deleted + 1
            else
                table.insert(kept, record)
            end
        else
            table.insert(kept, record)
        end
    end

    minigames.S.spawnedWarGamesVehicles = kept
    minigames.S.deletedWarGamesVehicleCount = (minigames.S.deletedWarGamesVehicleCount or 0) + deleted
    minigames.S.lastVehicleRoundCleanupStatus =
        "Deleted inactive round vehicles | activeRound=" ..
        tostring(activeRoundIndex) ..
        " | deleted=" ..
        tostring(deleted) ..
        " | reason=" ..
        tostring(reason or "None")

    if deleted > 0 then
        minigames.LogInfo("[WarGames Rounds] " .. minigames.S.lastVehicleRoundCleanupStatus)
    end

    return deleted
end


------------------------------------------------------------
-- v0.096 safe / queued vehicle round controls
------------------------------------------------------------
function minigames.SetRoundVehicleIndexSafe(index, reason, notify)
    local ok, err = direct_call_trace(function()
        minigames.SetRoundVehicleIndex(index, reason, notify)
    end, debug and debug.traceback or function(e) return tostring(e) end)

    if not ok then
        minigames.S.lastVehicleRoundStatus = "Safe round change failed: " .. tostring(err)
        minigames.LogError("[WarGames Rounds] " .. minigames.S.lastVehicleRoundStatus)
        return false, err
    end

    return true, "ok"
end

function minigames.QueueRoundVehicleIndex(index, reason, notify)
    minigames.S.pendingRoundVehicleIndex = index
    minigames.S.pendingRoundVehicleReason = tostring(reason or "Queued Round Change")
    minigames.S.pendingRoundVehicleNotify = notify ~= false

    if minigames.Queue then
        minigames.Queue(function()
            local pendingIndex = minigames.S.pendingRoundVehicleIndex
            local pendingReason = minigames.S.pendingRoundVehicleReason
            local pendingNotify = minigames.S.pendingRoundVehicleNotify

            minigames.S.pendingRoundVehicleIndex = nil
            minigames.S.pendingRoundVehicleReason = nil
            minigames.S.pendingRoundVehicleNotify = nil

            minigames.SetRoundVehicleIndexSafe(pendingIndex, pendingReason, pendingNotify)
        end)
    else
        minigames.SetRoundVehicleIndexSafe(index, reason, notify)
    end

    return true
end

function minigames.NextVehicleRoundNow(reason)
    if not minigames.WarGames or not minigames.WarGames.VehiclePool then
        return false, "no_vehicle_pool"
    end

    local index = minigames.GetRoundVehicleIndex() + 1
    if index > #minigames.WarGames.VehiclePool then
        index = 1
    end

    return minigames.QueueRoundVehicleIndex(index, reason or "Manual Next Round", true)
end

function minigames.PreviousVehicleRoundNow(reason)
    if not minigames.WarGames or not minigames.WarGames.VehiclePool then
        return false, "no_vehicle_pool"
    end

    local index = minigames.GetRoundVehicleIndex() - 1
    if index < 1 then
        index = #minigames.WarGames.VehiclePool
    end

    return minigames.QueueRoundVehicleIndex(index, reason or "Manual Previous Round", true)
end

function minigames.RandomVehicleRoundNow(reason)
    local index = minigames.RollRandomRoundVehicleIndex()
    return minigames.QueueRoundVehicleIndex(index, reason or "Manual Random Round", true)
end


------------------------------------------------------------
-- v0.098 final round button / crash safety override
------------------------------------------------------------
-- direct round-change cleanup caused instability while the cherax menu was open.
-- round changes now update the active vehicle only; cleanup is deferred to the
-- 3-minute cleanup pass. manual previous/next is also debounced.
------------------------------------------------------------
function minigames.SetRoundVehicleIndex(index, reason, notify)
    if not minigames.WarGames or not minigames.WarGames.VehiclePool then
        return false
    end

    local poolSize = #minigames.WarGames.VehiclePool
    if poolSize <= 0 then return false end

    index = minigames.ClampInt(index, 1, poolSize)

    local previous = minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or index
    previous = minigames.ClampInt(previous, 1, poolSize)

    local previousLabel = minigames.GetVehicleLabelByIndex(previous)
    local newLabel = minigames.GetVehicleLabelByIndex(index)

    minigames.S.previousRoundVehicleIndex = previous
    minigames.S.roundVehicleIndex = index
    minigames.S.selectedVehicleIndex = index
    minigames.S.roundStartedAtMs = minigames.Now()
    minigames.S.lastVehicleRoundTickMs = minigames.Now()

    -- do not delete old round vehicles here. defer to cleanup tick.
    minigames.S.lastVehicleRoundStatus =
        "Vehicle round changed | Previous: " ..
        tostring(previousLabel) ..
        " | New: " ..
        tostring(newLabel) ..
        " | reason=" ..
        tostring(reason or "Unknown") ..
        " | cleanup=deferred"

    minigames.LogInfo("[WarGames Rounds] " .. minigames.S.lastVehicleRoundStatus)

    if notify ~= false and minigames.S.roundChangeNotifyEnabled ~= false then
        minigames.NotifyVehicleRoundChange(previousLabel, newLabel, reason)
    end

    return true
end

function minigames.SetRoundVehicleIndexSafe(index, reason, notify)
    local ok, err = direct_call_trace(function()
        minigames.SetRoundVehicleIndex(index, reason, notify)
    end, debug and debug.traceback or function(e) return tostring(e) end)

    if not ok then
        minigames.S.lastVehicleRoundStatus = "Safe round change failed: " .. tostring(err)
        minigames.LogError("[WarGames Rounds] " .. minigames.S.lastVehicleRoundStatus)
        return false, err
    end

    return true, "ok"
end

function minigames.QueueRoundVehicleIndex(index, reason, notify)
    local now = minigames.Now()
    local debounce = minigames.S.roundButtonDebounceMs or 850

    if minigames.S.lastManualRoundButtonMs and now - minigames.S.lastManualRoundButtonMs < debounce then
        minigames.S.lastVehicleRoundStatus = "Round button ignored by debounce."
        return false, "debounce"
    end

    minigames.S.lastManualRoundButtonMs = now
    minigames.S.pendingRoundVehicleIndex = index
    minigames.S.pendingRoundVehicleReason = tostring(reason or "Queued Round Change")
    minigames.S.pendingRoundVehicleNotify = notify ~= false

    local function run_round_job()
        local pendingIndex = minigames.S.pendingRoundVehicleIndex
        local pendingReason = minigames.S.pendingRoundVehicleReason
        local pendingNotify = minigames.S.pendingRoundVehicleNotify

        minigames.S.pendingRoundVehicleIndex = nil
        minigames.S.pendingRoundVehicleReason = nil
        minigames.S.pendingRoundVehicleNotify = nil

        minigames.SetRoundVehicleIndexSafe(pendingIndex, pendingReason, pendingNotify)
    end

    if minigames.Queue then
        minigames.Queue(run_round_job)
    elseif Script and Script.QueueJob then
        direct_call(function() Script.QueueJob(run_round_job) end)
    else
        minigames.SetRoundVehicleIndexSafe(index, reason, notify)
    end

    return true, "queued"
end

function minigames.NextVehicleRoundNow(reason)
    local index = minigames.GetRoundVehicleIndex() + 1
    if index > #minigames.WarGames.VehiclePool then index = 1 end
    return minigames.QueueRoundVehicleIndex(index, reason or "Manual Next Round", true)
end

function minigames.PreviousVehicleRoundNow(reason)
    local index = minigames.GetRoundVehicleIndex() - 1
    if index < 1 then index = #minigames.WarGames.VehiclePool end
    return minigames.QueueRoundVehicleIndex(index, reason or "Manual Previous Round", true)
end


