    { name = "Red", id = 27, r = 200, g = 20, b = 20 },
    { name = "Torino Red", id = 28, r = 255, g = 30, b = 30 },
    { name = "Orange", id = 38, r = 255, g = 120, b = 20 },
    { name = "Yellow", id = 88, r = 255, g = 220, b = 30 },
    { name = "Race Yellow", id = 89, r = 255, g = 235, b = 30 },
    { name = "Lime", id = 55, r = 140, g = 255, b = 20 },
    { name = "Green", id = 53, r = 20, g = 180, b = 60 },
    { name = "Blue", id = 64, r = 30, g = 80, b = 255 },
    { name = "Ultra Blue", id = 70, r = 30, g = 140, b = 255 },
    { name = "Purple", id = 71, r = 130, g = 50, b = 255 },
    { name = "Hot Pink", id = 135, r = 255, g = 50, b = 180 },
