}

function minigames.GetPlayerPed(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if PLAYER and PLAYER.GET_PLAYER_PED_SCRIPT_INDEX then
        local ok, ped = direct_call(function()
            return PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(playerId)
        end)

        if ok and ped and ped ~= 0 then
            return ped
        end
    end

    if minigames.IsSelf(playerId) and PLAYER and PLAYER.PLAYER_PED_ID then
        local ok, ped = direct_call(function()
            return PLAYER.PLAYER_PED_ID()
        end)

        if ok and ped and ped ~= 0 then
            return ped
        end
    end

    return 0
end

function minigames.EntityExists(entity)
    if not entity or entity == 0 then
        return false
    end

    if ENTITY and ENTITY.DOES_ENTITY_EXIST then
        local ok, exists = direct_call(function()
            return ENTITY.DOES_ENTITY_EXIST(entity)
        end)

        return ok and exists == true
    end

    return false
end

function minigames.GetTargetCoords(playerId)
    if not minigames.HasEntityNatives() then
        return nil, 0.0, "natives_missing"
    end

    local ped = minigames.GetPlayerPed(playerId)

    if not ped or ped == 0 then
        return nil, 0.0, "ped_nil"
    end

    if not minigames.EntityExists(ped) then
        return nil, 0.0, "ped_missing"
    end

    local coords = nil
    local heading = 0.0

    local okCoords = direct_call(function()
        coords = ENTITY.GET_ENTITY_COORDS(ped, true)
    end)

    local okHeading = direct_call(function()
        heading = ENTITY.GET_ENTITY_HEADING(ped)
    end)

    if not okCoords or not coords then
        return nil, 0.0, "coords_failed"
    end

    if not okHeading or heading == nil then
        heading = 0.0
    end

    return coords, tonumber(heading) or 0.0, "ok"
end

function minigames.GetSpawnCoordsInFront(playerId)
    local coords, heading, status = minigames.GetTargetCoords(playerId)

    if not coords then
        return nil, 0.0, status
    end

    local radians = minigames.DegToRad(heading)
    local distance = tonumber(minigames.S.spawnDistance) or minigames.C.DEFAULT_SPAWN_DISTANCE
    local forwardX = -math.sin(radians)
    local forwardY = math.cos(radians)

    return {
        x = coords.x + forwardX * distance,
        y = coords.y + forwardY * distance,
        z = coords.z + (minigames.S.spawnZOffset or minigames.C.DEFAULT_SPAWN_Z_OFFSET)
    }, heading, "ok"
end

function minigames.MarkVehicleSpawned(playerId, method, vehicle)
    playerId = minigames.ClampInt(playerId, 0, 31)
    minigames.InitPlayerState(playerId)

    minigames.Player.vehicleSpawned[playerId] = true
    minigames.Player.vehicleSpawnedAtMs[playerId] = minigames.Now()
    minigames.Player.vehicleLastMethod[playerId] = tostring(method or "Unknown")

    if vehicle then
        minigames.Player.vehicleLastStatus[playerId] = "Spawned " .. tostring(vehicle.label)
    end
end

function minigames.SetVehicleStatus(playerId, status, method, err, vehicle)
    playerId = minigames.ClampInt(playerId, 0, 31)
    minigames.InitPlayerState(playerId)

    minigames.Player.vehicleLastStatus[playerId] = tostring(status or "None")
    minigames.Player.vehicleLastMethod[playerId] = tostring(method or "None")
    minigames.Player.vehicleLastError[playerId] = tostring(err or "None")

    minigames.S.lastVehicleStatus = tostring(status or "None")
    minigames.S.lastVehicleTarget = playerId
    minigames.S.lastVehicleTargetName = minigames.GetPlayerName(playerId)
    minigames.S.lastVehicleMethod = tostring(method or "None")
    minigames.S.lastVehicleError = tostring(err or "None")

    if vehicle then
        minigames.S.lastVehicleName = tostring(vehicle.label)
        minigames.S.lastVehicleModel = tostring(vehicle.model)
        minigames.S.lastVehicleSavedIndex = tonumber(vehicle.savedIndex) or -1
    end
end

function minigames.ApplyWarGamesPlate(vehicleEntity)
    if not vehicleEntity or vehicleEntity == 0 then
        return false
    end

    local plate = tostring(minigames.C.WARGAMES_PLATE_TEXT or "WARGAMES")

    local ok = direct_call(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT then
            VEHICLE.SET_VEHICLE_NUMBER_PLATE_TEXT(vehicleEntity, plate)
        end
    end)

    return ok
end

function minigames.RemoveWarGamesLivery(vehicleEntity)
    if not vehicleEntity or vehicleEntity == 0 then
        return false
    end

    if minigames.S.removeVehicleLiveries == false then
        return false
    end

    local ok = direct_call(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_LIVERY then
            VEHICLE.SET_VEHICLE_LIVERY(vehicleEntity, -1)
        end

        if VEHICLE and VEHICLE.SET_VEHICLE_MOD then
            VEHICLE.SET_VEHICLE_MOD(vehicleEntity, 48, -1, false)
        end
    end)

    return ok
end

function minigames.GetRandomWarGamesColor()
    local pool = minigames.VehicleColorPool or {}

    if #pool <= 0 then
        return { name = "Black", id = 0, r = 5, g = 5, b = 5 }
    end

    return pool[math.random(1, #pool)]
end

function minigames.ApplyRandomWarGamesColor(vehicleEntity)
    if not vehicleEntity or vehicleEntity == 0 then
        return nil
    end

    if minigames.S.randomizeVehicleColors == false then
        return nil
    end

    local color = minigames.GetRandomWarGamesColor()

    direct_call(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_COLOURS then
            VEHICLE.SET_VEHICLE_COLOURS(vehicleEntity, color.id, color.id)
        end
    end)

    direct_call(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA_COLOURS then
            VEHICLE.SET_VEHICLE_EXTRA_COLOURS(vehicleEntity, color.id, color.id)
        end
    end)

    direct_call(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then
            VEHICLE.SET_VEHICLE_MOD_KIT(vehicleEntity, 0)
        end

        if VEHICLE and VEHICLE.TOGGLE_VEHICLE_MOD then
            VEHICLE.TOGGLE_VEHICLE_MOD(vehicleEntity, 20, true)
        end

        if minigames.S.randomizeWheelSmoke ~= false and VEHICLE and VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR then
            VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR(vehicleEntity, color.r, color.g, color.b)
        end
    end)

    return color
end

function minigames.IsVigilanteEntityV164(vehicleEntity)
    if not vehicleEntity or vehicleEntity == 0 then
        return false
    end

    local modelHash = nil
    local vigilanteHash = nil

    if ENTITY and ENTITY.GET_ENTITY_MODEL then
        direct_call(function()
            modelHash = ENTITY.GET_ENTITY_MODEL(vehicleEntity)
        end)
    end

    if Utils and Utils.Joaat then
        direct_call(function()
            vigilanteHash = Utils.Joaat("vigilante")
        end)
    end

    modelHash = tonumber(modelHash)
    vigilanteHash = tonumber(vigilanteHash)

    if not modelHash or not vigilanteHash then
        return false
    end

    local function unsigned32(value)
        value = math.floor(tonumber(value) or 0)
        if value < 0 then value = value + 4294967296 end
        return value
    end

    return unsigned32(modelHash) == unsigned32(vigilanteHash)
end

function minigames.ApplyVigilanteSafeStyleV164(vehicleEntity)
    if not vehicleEntity or vehicleEntity == 0 then
        return false
    end

    if minigames.S.forceWarGamesPlate ~= false and minigames.ApplyWarGamesPlate then
        direct_call(minigames.ApplyWarGamesPlate, vehicleEntity)
    end

    if minigames.RemoveWarGamesLivery then
        direct_call(minigames.RemoveWarGamesLivery, vehicleEntity)
    end

    minigames.S.lastVigilanteSafeStyleStatusV164 =
        "minimal safe style | entity=" .. tostring(vehicleEntity) ..
        " | wheels=untouched | upgrades=skipped" ..
        " | colors=skipped | smoke=skipped"

    return true
end

function minigames.ApplyWarGamesVehicleStyle(vehicleEntity)
    if not vehicleEntity or vehicleEntity == 0 then
        return
    end

    if minigames.IsVigilanteEntityV164 and
        minigames.IsVigilanteEntityV164(vehicleEntity) == true then
        minigames.ApplyVigilanteSafeStyleV164(vehicleEntity)
        return
    end

    direct_call(function()
        if minigames.ApplyRawVehicleUpgrades then
            minigames.ApplyRawVehicleUpgrades(vehicleEntity)
        end
    end)

    if minigames.S.forceWarGamesPlate ~= false then
        minigames.ApplyWarGamesPlate(vehicleEntity)
    end

    minigames.RemoveWarGamesLivery(vehicleEntity)
    local color = minigames.ApplyRandomWarGamesColor(vehicleEntity)

    if minigames.S.forceWarGamesPlate ~= false then
        minigames.ApplyWarGamesPlate(vehicleEntity)
    end

    if color then
        minigames.S.lastVehicleColorName = color.name
        minigames.S.lastVehicleColorId = color.id
    end
end

function minigames.RegisterWarGamesVehicle(vehicleEntity, playerId, vehicleData, method)
    if not vehicleEntity or vehicleEntity == 0 then
        return
    end

    minigames.S.spawnedWarGamesVehicles = minigames.S.spawnedWarGamesVehicles or {}

    table.insert(minigames.S.spawnedWarGamesVehicles, {
        entity = vehicleEntity,
        playerId = minigames.ClampInt(playerId or -1, -1, 31),
        label = vehicleData and vehicleData.label or "Unknown",
        model = vehicleData and vehicleData.model or "Unknown",
        shortName = vehicleData and vehicleData.shortName or "Unknown",
        savedIndex = vehicleData and vehicleData.savedIndex or -1,
        roundIndex = minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or 1,
        method = tostring(method or "Unknown"),
        spawnedAtMs = minigames.Now(),
        lastSeenMs = minigames.Now()
    })

    minigames.S.spawnedWarGamesVehicleCount = (minigames.S.spawnedWarGamesVehicleCount or 0) + 1

    minigames.LogInfo(
        "Registered WarGames vehicle for cleanup | entity=" ..
        tostring(vehicleEntity) ..
        " | player=" ..
        tostring(playerId) ..
        " | vehicle=" ..
        tostring(vehicleData and vehicleData.label or "Unknown")
    )
end

function minigames.IsVehicleUsed(vehicleEntity)
    if not vehicleEntity or vehicleEntity == 0 then
        return false
    end

    if not minigames.EntityExists(vehicleEntity) then
        return false
    end

    if VEHICLE and VEHICLE.GET_PED_IN_VEHICLE_SEAT then
        for seat = -1, 15 do
            local ped = 0

            local ok = direct_call(function()
                ped = VEHICLE.GET_PED_IN_VEHICLE_SEAT(vehicleEntity, seat, false)
            end)

            if ok and ped and ped ~= 0 and minigames.EntityExists(ped) then
                return true
            end
        end
    end

    return false
end

function minigames.DeleteVehicleEntity(vehicleEntity)
    if not vehicleEntity or vehicleEntity == 0 then
        return false
    end

    if not minigames.EntityExists(vehicleEntity) then
        return true
    end

    local ok, err = direct_call(function()
        if ENTITY and ENTITY.SET_ENTITY_AS_MISSION_ENTITY then
            ENTITY.SET_ENTITY_AS_MISSION_ENTITY(vehicleEntity, true, true)
        end

        if VEHICLE and VEHICLE.SET_VEHICLE_ENGINE_ON then
            VEHICLE.SET_VEHICLE_ENGINE_ON(vehicleEntity, false, true, true)
        end

        if ENTITY and ENTITY.DELETE_ENTITY then
            ENTITY.DELETE_ENTITY(vehicleEntity)
        elseif VEHICLE and VEHICLE.DELETE_VEHICLE then
            VEHICLE.DELETE_VEHICLE(vehicleEntity)
        end
    end)

    if not ok then
        minigames.LogError("DeleteVehicleEntity failed | entity=" .. tostring(vehicleEntity) .. " | err=" .. tostring(err))
        return false
    end

    -- some deletes do not happen instantly. if it still exists, we still count the call as attempted false.
    if minigames.EntityExists(vehicleEntity) then
        return false
    end

    return true
end

function minigames.CleanupWarGamesVehicles(force)
    minigames.S.spawnedWarGamesVehicles = minigames.S.spawnedWarGamesVehicles or {}

    local now = minigames.Now()
    local cleanupMs = minigames.S.vehicleCleanupMs or minigames.C.DEFAULT_VEHICLE_CLEANUP_MS or 120000
    local kept = {}
    local deleted = 0
    local attempted = 0
    local keptUsed = 0
    local keptYoung = 0
    local missing = 0
    local failed = 0

    for _, record in ipairs(minigames.S.spawnedWarGamesVehicles) do
        local entity = record.entity

        if not entity or entity == 0 or not minigames.EntityExists(entity) then
            missing = missing + 1
        else
            local age = now - (record.spawnedAtMs or now)
            local used = minigames.IsVehicleUsed(entity)

            if force == true then
                attempted = attempted + 1

                if minigames.DeleteVehicleEntity(entity) then
                    deleted = deleted + 1
                minigames.S.vehicleCleanupDeletedTotal = (minigames.S.vehicleCleanupDeletedTotal or 0) + 1
                else
                    failed = failed + 1
                    table.insert(kept, record)
                end
            elseif used then
                record.lastSeenMs = now
                table.insert(kept, record)
                keptUsed = keptUsed + 1
            elseif age >= cleanupMs then
                attempted = attempted + 1

                if minigames.DeleteVehicleEntity(entity) then
                    deleted = deleted + 1
                else
                    failed = failed + 1
                    table.insert(kept, record)
                end
            else
                table.insert(kept, record)
                keptYoung = keptYoung + 1
            end
        end
    end

    minigames.S.spawnedWarGamesVehicles = kept
    minigames.S.deletedWarGamesVehicleCount = (minigames.S.deletedWarGamesVehicleCount or 0) + deleted

    minigames.S.lastVehicleCleanupStatus =
        "cleanup deleted=" ..
        tostring(deleted) ..
        " attempted=" ..
        tostring(attempted) ..
        " failed=" ..
        tostring(failed) ..
        " keptUsed=" ..
        tostring(keptUsed) ..
        " keptYoung=" ..
        tostring(keptYoung) ..
        " missing=" ..
        tostring(missing) ..
        " tracking=" ..
        tostring(#kept)

    minigames.LogCleanupStatus("[WarGames Cleanup] " .. minigames.S.lastVehicleCleanupStatus, deleted, failed, attempted, "wargames_cleanup")

    return deleted, attempted, failed
end

function minigames.VehicleCleanupTick()
    if minigames.S.autoCleanupWarGamesVehicles ~= true and minigames.S.wargamesSystemsActive ~= true then
        return
    end

    local now = minigames.Now()
    local scanMs = minigames.S.vehicleCleanupScanMs or minigames.C.DEFAULT_VEHICLE_CLEANUP_SCAN_MS or 5000
    local last = minigames.S.lastVehicleCleanupScanMs or 0

    if last ~= 0 and now - last < scanMs then
        return
    end

    minigames.S.lastVehicleCleanupScanMs = now

    local ok, err = direct_call(function()
        minigames.CleanupWarGamesVehicles(false)
    end)

    if not ok then
        minigames.S.lastVehicleCleanupStatus = "cleanup tick error: " .. tostring(err)
        minigames.LogError("[WarGames Cleanup] " .. minigames.S.lastVehicleCleanupStatus)
    end
end

function minigames.SetSavedVehicleListIndex(savedIndex)
    for _, listHash in ipairs({ minigames.C.VEHICLE_LIST_HASH_PRIMARY, minigames.C.VEHICLE_LIST_HASH_FALLBACK }) do
        local ok = direct_call(function()
            FeatureMgr.SetFeatureListIndex(listHash, savedIndex)
        end)

        minigames.LogInfo("SetFeatureListIndex hash=" .. tostring(listHash) .. " index=" .. tostring(savedIndex) .. " ok=" .. tostring(ok))

        if ok then
            minigames.S.lastWorkingVehicleListHash = tostring(listHash)
            return true
        end
    end

    minigames.S.lastWorkingVehicleListHash = "None"
    return false
end

function minigames.GetLoadVehicleFeature()
    minigames.S.lastLoadVehicleFeatureName = "None"

    if not FeatureMgr.GetFeatureByName then
        return nil
    end

    for _, name in ipairs({ "Load Vehicle", "Load vehicle", "Load Saved Vehicle", "Load CHRX Vehicle", "Load Current Vehicle", "Load" }) do
        local ok, feature = direct_call(function()
            return FeatureMgr.GetFeatureByName(name)
        end)

        if ok and feature then
            minigames.S.lastLoadVehicleFeatureName = name
            return feature
        end
    end

    return nil
end

function minigames.SpawnSavedJsonVehicle(vehicle, playerId, reason, force)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if not minigames.IsSelf(playerId) and not force then
        minigames.SetVehicleStatus(playerId, "Saved JSON skipped: only reliable for self/local", "Saved JSON", "not_self", vehicle)
        return false, "not_self"
    end

    if not minigames.SetSavedVehicleListIndex(vehicle.savedIndex or 1) then
        minigames.SetVehicleStatus(playerId, "Saved JSON failed: could not set list index", "Saved JSON", "set_index_failed", vehicle)
        return false, "set_index_failed"
    end

    local loadFeature = minigames.GetLoadVehicleFeature()

    if not loadFeature then
        minigames.SetVehicleStatus(playerId, "Saved JSON failed: Load Vehicle feature missing", "Saved JSON", "feature_nil", vehicle)
        return false, "feature_nil"
    end

    local okTrigger, errTrigger = direct_call(function()
        loadFeature:TriggerCallback()
    end)

    if okTrigger then
        minigames.MarkVehicleSpawned(playerId, "Saved JSON", vehicle)
        minigames.SetVehicleStatus(playerId, "Loaded saved JSON vehicle: " .. vehicle.label, "Saved JSON", "None", vehicle)
        return true, "spawned"
    end

    minigames.SetVehicleStatus(playerId, "Saved JSON failed: TriggerCallback error", "Saved JSON", errTrigger, vehicle)
    return false, "trigger_failed"
end



function minigames.GetTeleportAreaSpawnCoords(playerId)
    if minigames.S.teleportAwareVehicleRespawn == false then
        return nil, 0.0, "teleport_aware_disabled"
    end

    if not minigames.IsTeleportRoundModeEnabled or not minigames.IsTeleportRoundModeEnabled() then
        return nil, 0.0, "teleport_mode_off"
    end

    if minigames.S.spawnAtSelectedTeleportWhenTeleportEnabled == false then
        return nil, 0.0, "teleport_spawn_disabled"
    end

    if not minigames.GetActiveTeleportSpawnLocation then
        return nil, 0.0, "teleport_helper_missing"
    end

    local location = minigames.GetActiveTeleportSpawnLocation()

    if not location then
        return nil, 0.0, "location_missing"
    end

    local baseX = tonumber(location.x or location.X)
    local baseY = tonumber(location.y or location.Y)
    local baseZ = tonumber(location.z or location.Z)
    local heading = tonumber(location.heading or location.Heading or 0.0)

    if not baseX or not baseY or not baseZ then
        return nil, 0.0, "bad_location_coords"
    end

    -- spread players around the chosen tp so vehicles do not stack.
    local spacing = tonumber(minigames.S.teleportSpawnSpacing) or 8.0
    local gridWidth = tonumber(minigames.S.teleportSpawnGridWidth) or 4

    if gridWidth < 1 then
        gridWidth = 4
    end

    local index = minigames.ClampInt(playerId or 0, 0, 31)
    local col = index % gridWidth
    local row = math.floor(index / gridWidth)

    local centeredCol = col - ((gridWidth - 1) / 2.0)
    local offsetX = centeredCol * spacing
    local offsetY = row * spacing

    minigames.S.lastTeleportSpawnStatus =
        "teleport-area spawn | location=" ..
        tostring(location.label or location.id or "Unknown") ..
        " | player=" ..
        tostring(playerId) ..
        " | offset=" ..
        tostring(offsetX) ..
        "," ..
        tostring(offsetY)

    return {
        x = baseX + offsetX,
        y = baseY + offsetY,
        z = baseZ + (minigames.S.spawnZOffset or minigames.C.DEFAULT_SPAWN_Z_OFFSET or 1.0)
    }, heading, "teleport_area"
end

function minigames.SpawnRawModelVehicle(vehicle, playerId, reason, force)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if not GTA or not GTA.SpawnVehicle then
        minigames.SetVehicleStatus(playerId, "RAW spawn failed: GTA.SpawnVehicle missing", "RAW Model", "GTA.SpawnVehicle=nil", vehicle)
        return false, "missing_spawnvehicle"
    end

    local spawnCoords, heading, coordStatus = nil, 0.0, "none"

    -- v0.066:
    -- teleport mode controls where the fight happens.
    -- vehicle round controls what spawns.
    -- if teleport mode is off, always spawn in front of the player like before.
    spawnCoords, heading, coordStatus = minigames.GetTeleportAreaSpawnCoords(playerId)

    if not spawnCoords then
        spawnCoords, heading, coordStatus = minigames.GetSpawnCoordsInFront(playerId)
    end

    if not spawnCoords then
        minigames.SetVehicleStatus(playerId, "RAW spawn failed: target coords unavailable", "RAW Model", coordStatus, vehicle)
        return false, coordStatus
    end

    local veh = nil

    local okSpawn, errSpawn = direct_call(function()
        veh = GTA.SpawnVehicle(vehicle.model, spawnCoords.x, spawnCoords.y, spawnCoords.z, heading, true, true)
    end)

    if not okSpawn or not veh or veh == 0 then
        minigames.SetVehicleStatus(playerId, "RAW spawn failed: vehicle handle nil", "RAW Model", errSpawn or "veh=nil", vehicle)
        return false, "spawn_failed"
    end

    minigames.S.lastVehicleEntity = veh

    direct_call(function()
        if ENTITY and ENTITY.SET_ENTITY_AS_MISSION_ENTITY then
            ENTITY.SET_ENTITY_AS_MISSION_ENTITY(veh, true, true)
        end
    end)

    direct_call(function()
        if ENTITY and ENTITY.SET_ENTITY_HEADING then
            ENTITY.SET_ENTITY_HEADING(veh, heading)
        end
    end)

    direct_call(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_ENGINE_ON then
            VEHICLE.SET_VEHICLE_ENGINE_ON(veh, true, true, false)
        end
    end)

    direct_call(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_ON_GROUND_PROPERLY then
            VEHICLE.SET_VEHICLE_ON_GROUND_PROPERLY(veh, 5.0)
        end
    end)

    minigames.ApplyWarGamesVehicleStyle(veh)
    minigames.RegisterWarGamesVehicle(veh, playerId, vehicle, "RAW Model")

    minigames.MarkVehicleSpawned(playerId, "RAW Model", vehicle)
    minigames.SetVehicleStatus(playerId, "Spawned RAW " .. vehicle.label .. " in front of " .. minigames.GetPlayerName(playerId), "RAW Model", "None", vehicle)

    minigames.LogInfo(
        "RAW vehicle spawned | player=" ..
        tostring(playerId) ..
        " | name=" ..
        minigames.GetPlayerName(playerId) ..
        " | vehicle=" ..
        vehicle.label ..
        " | model=" ..
        vehicle.model ..
        " | spawnStatus=" .. tostring(coordStatus) .. " | plate=WARGAMES | color=" ..
        tostring(minigames.S.lastVehicleColorName or "Unknown")
    )

    return true, "spawned"
end

function minigames.SpawnVehicleForPlayer(playerId, vehicle, force, reason)
    if minigames.RefreshConfig then
        minigames.RefreshConfig()
    end

    playerId = minigames.ClampInt(playerId, 0, 31)
    force = force == true

    if not minigames.IsPlayerActive(playerId) then
        minigames.SetVehicleStatus(playerId, "Skipped: inactive player", "Vehicle", "inactive", vehicle)
        return false, "inactive"
    end

    if minigames.S.skipSelfVehicle and minigames.IsSelf(playerId) and not force then
        minigames.SetVehicleStatus(playerId, "Skipped: self", "Vehicle", "skip_self", vehicle)
        return false, "skip_self"
    end

    if minigames.S.useVehicleTracking and not force then
        local lastSpawn = minigames.Player.vehicleSpawnedAtMs[playerId] or 0

        if lastSpawn > 0 and minigames.Now() - lastSpawn < minigames.S.spawnCooldownMs then
            minigames.SetVehicleStatus(playerId, "Skipped: spawn cooldown", "Vehicle", "cooldown", vehicle)
            return false, "cooldown"
        end
    end

    if minigames.S.preventRespawnVehicleSpam ~= false and force ~= true then
        local existing = minigames.GetTrackedVehicleForPlayer and minigames.GetTrackedVehicleForPlayer(playerId) or nil

        if existing and existing.entity and minigames.EntityExists(existing.entity) and not minigames.IsVehicleDestroyed(existing.entity) then
            minigames.SetVehicleStatus(playerId, "Skipped: existing live WarGames vehicle still active", "Vehicle Anti-Spam", "live_vehicle_exists", vehicle)
            return false, "live_vehicle_exists"
        end
    end

    if minigames.S.vehicleSpawnEngine == minigames.C.VEHICLE_SPAWN_ENGINE_SAVED_JSON then
        return minigames.SpawnSavedJsonVehicle(vehicle, playerId, reason, force)
    elseif minigames.S.vehicleSpawnEngine == minigames.C.VEHICLE_SPAWN_ENGINE_RAW_MODEL then
        return minigames.SpawnRawModelVehicle(vehicle, playerId, reason, force)
    end

    if minigames.IsSelf(playerId) then
        local okSaved, savedStatus = minigames.SpawnSavedJsonVehicle(vehicle, playerId, reason, true)

        if okSaved then
            return true, savedStatus
        end

        minigames.LogInfo("Hybrid fallback to RAW after saved JSON status=" .. tostring(savedStatus))
        return minigames.SpawnRawModelVehicle(vehicle, playerId, reason, true)
    end

    return minigames.SpawnRawModelVehicle(vehicle, playerId, reason, force)
end


------------------------------------------------------------
-- v0.069 fairness / color / tracking overrides
------------------------------------------------------------

function minigames.GetRandomWarGamesColor()
    local r = minigames.RandomInt and minigames.RandomInt(0, 255) or math.random(0, 255)
    local g = minigames.RandomInt and minigames.RandomInt(0, 255) or math.random(0, 255)
    local b = minigames.RandomInt and minigames.RandomInt(0, 255) or math.random(0, 255)

    return {
        name = string.format("#%02X%02X%02X", r, g, b),
        id = 12,
        r = r,
        g = g,
        b = b
    }
end

function minigames.ApplyRandomWarGamesColor(vehicleEntity)
    if not vehicleEntity or vehicleEntity == 0 then
        return nil
    end

    if minigames.S.randomizeVehicleColors == false then
        return nil
    end

    local color = minigames.GetRandomWarGamesColor()

    direct_call(function()
        if VEHICLE and VEHICLE.SET_VEHICLE_COLOURS then
            VEHICLE.SET_VEHICLE_COLOURS(vehicleEntity, 12, 12)
        end

        if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR then
            VEHICLE.SET_VEHICLE_CUSTOM_PRIMARY_COLOUR(vehicleEntity, color.r, color.g, color.b)
        end

        if VEHICLE and VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR then
            VEHICLE.SET_VEHICLE_CUSTOM_SECONDARY_COLOUR(vehicleEntity, color.r, color.g, color.b)
        end

        if VEHICLE and VEHICLE.SET_VEHICLE_EXTRA_COLOURS then
            VEHICLE.SET_VEHICLE_EXTRA_COLOURS(vehicleEntity, 0, 0)
        end

        if VEHICLE and VEHICLE.SET_VEHICLE_MOD_KIT then
            VEHICLE.SET_VEHICLE_MOD_KIT(vehicleEntity, 0)
        end

        if VEHICLE and VEHICLE.TOGGLE_VEHICLE_MOD then
            VEHICLE.TOGGLE_VEHICLE_MOD(vehicleEntity, 20, true)
        end

        if minigames.S.randomizeWheelSmoke ~= false and VEHICLE and VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR then
            VEHICLE.SET_VEHICLE_TYRE_SMOKE_COLOR(vehicleEntity, color.r, color.g, color.b)
        end
    end)

    return color
end

function minigames.IsVehicleDestroyed(vehicleEntity)
    if not vehicleEntity or vehicleEntity == 0 then
        return true
    end

    if not minigames.EntityExists(vehicleEntity) then
        return true
    end

    if ENTITY and ENTITY.IS_ENTITY_DEAD then
        local ok, dead = direct_call(function()
            return ENTITY.IS_ENTITY_DEAD(vehicleEntity, false)
        end)

        if ok and dead == true then
            return true
        end
    end

    if VEHICLE and VEHICLE.IS_VEHICLE_DRIVEABLE then
        local ok, driveable = direct_call(function()
            return VEHICLE.IS_VEHICLE_DRIVEABLE(vehicleEntity, false)
        end)

        if ok and driveable == false then
            return true
        end
    end

    return false
end

function minigames.GetTrackedVehicleForPlayer(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)
    minigames.S.spawnedWarGamesVehicles = minigames.S.spawnedWarGamesVehicles or {}

    local newest = nil

    for _, record in ipairs(minigames.S.spawnedWarGamesVehicles) do
        if record.playerId == playerId and record.entity and record.entity ~= 0 and minigames.EntityExists(record.entity) then
            if not newest or (record.spawnedAtMs or 0) > (newest.spawnedAtMs or 0) then
                newest = record
            end
        end
    end

    return newest
end

function minigames.CleanupWarGamesVehicles(force)
    minigames.S.spawnedWarGamesVehicles = minigames.S.spawnedWarGamesVehicles or {}

    local kept = {}
    local deleted = 0
    local attempted = 0
    local keptLive = 0
    local missing = 0
    local failed = 0
    local destroyed = 0

    for _, record in ipairs(minigames.S.spawnedWarGamesVehicles) do
        local entity = record.entity

        if not entity or entity == 0 or not minigames.EntityExists(entity) then
            missing = missing + 1
        else
            local isDestroyed = minigames.IsVehicleDestroyed(entity)

            if force == true or isDestroyed == true then
                attempted = attempted + 1
                if isDestroyed then destroyed = destroyed + 1 end

                if minigames.DeleteVehicleEntity(entity) then
                    deleted = deleted + 1
                else
                    failed = failed + 1
                    table.insert(kept, record)
                end
            else
                record.lastSeenMs = minigames.Now()
                table.insert(kept, record)
                keptLive = keptLive + 1
            end
        end
    end

    minigames.S.spawnedWarGamesVehicles = kept
    minigames.S.deletedWarGamesVehicleCount = (minigames.S.deletedWarGamesVehicleCount or 0) + deleted

    minigames.S.lastVehicleCleanupStatus =
        "destroyed-only cleanup deleted=" ..
        tostring(deleted) ..
        " attempted=" ..
        tostring(attempted) ..
        " destroyed=" ..
        tostring(destroyed) ..
        " failed=" ..
        tostring(failed) ..
        " keptLive=" ..
        tostring(keptLive) ..
        " missing=" ..
        tostring(missing) ..
        " tracking=" ..
        tostring(#kept)

    minigames.LogCleanupStatus("[WarGames Cleanup] " .. minigames.S.lastVehicleCleanupStatus, deleted, failed, attempted, "wargames_cleanup")
    return deleted, attempted, failed
end

function minigames.RegisterWarGamesVehicle(vehicleEntity, playerId, vehicleData, method)
    if not vehicleEntity or vehicleEntity == 0 then
        return
    end

    minigames.S.spawnedWarGamesVehicles = minigames.S.spawnedWarGamesVehicles or {}
    playerId = minigames.ClampInt(playerId or -1, -1, 31)

    -- keep one active live tracked vehicle per player to reduce spam.
    local kept = {}
    for _, record in ipairs(minigames.S.spawnedWarGamesVehicles) do
        if record.playerId == playerId and record.entity and record.entity ~= 0 and minigames.EntityExists(record.entity) then
            if minigames.IsVehicleDestroyed(record.entity) then
                minigames.DeleteVehicleEntity(record.entity)
            else
                -- old live vehicle for same player stays tracked, but only if it is different and recent.
                table.insert(kept, record)
            end
        else
            table.insert(kept, record)
        end
    end
    minigames.S.spawnedWarGamesVehicles = kept

    table.insert(minigames.S.spawnedWarGamesVehicles, {
        entity = vehicleEntity,
        playerId = playerId,
        label = vehicleData and vehicleData.label or "Unknown",
        model = vehicleData and vehicleData.model or "Unknown",
        shortName = vehicleData and vehicleData.shortName or "Unknown",
        savedIndex = vehicleData and vehicleData.savedIndex or -1,
        roundIndex = minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or 1,
        method = tostring(method or "Unknown"),
        spawnedAtMs = minigames.Now(),
        lastSeenMs = minigames.Now()
    })

    minigames.S.spawnedWarGamesVehicleCount = (minigames.S.spawnedWarGamesVehicleCount or 0) + 1
    minigames.Player.activeWarGamesVehicle = minigames.Player.activeWarGamesVehicle or {}
    minigames.Player.activeWarGamesVehicle[playerId] = vehicleEntity

    minigames.LogInfo("Registered WarGames vehicle | entity=" .. tostring(vehicleEntity) .. " | player=" .. tostring(playerId) .. " | vehicle=" .. tostring(vehicleData and vehicleData.label or "Unknown"))
end


------------------------------------------------------------
-- v0.094 wargames vehicle tracking + cleanup override
------------------------------------------------------------
function minigames.GetNextWarGamesVehicleId()
    minigames.S.nextWarGamesVehicleId = (minigames.S.nextWarGamesVehicleId or 0) + 1
    return minigames.S.nextWarGamesVehicleId
end

function minigames.RegisterWarGamesVehicle(vehicleEntity, playerId, vehicleData, method)
    if not vehicleEntity or vehicleEntity == 0 then
        return
    end

    minigames.S.spawnedWarGamesVehicles = minigames.S.spawnedWarGamesVehicles or {}
    minigames.Player = minigames.Player or {}
    minigames.Player.activeWarGamesVehicle = minigames.Player.activeWarGamesVehicle or {}

    playerId = minigames.ClampInt(playerId or -1, -1, 31)

    local record = {
        id = minigames.GetNextWarGamesVehicleId(),
        entity = vehicleEntity,
        playerId = playerId,
        ownerName = (playerId >= 0 and minigames.GetPlayerName and minigames.GetPlayerName(playerId)) or "Unknown",
        label = vehicleData and vehicleData.label or "Unknown",
        model = vehicleData and vehicleData.model or "Unknown",
        shortName = vehicleData and vehicleData.shortName or "Unknown",
        savedIndex = vehicleData and vehicleData.savedIndex or -1,
        roundIndex = minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or 1,
        method = tostring(method or "Unknown"),
        spawnedAtMs = minigames.Now(),
        lastSeenMs = minigames.Now(),
        firstUsedAtMs = 0,
        lastUsedAtMs = 0,
        everUsed = false,
        deleted = false
    }

    table.insert(minigames.S.spawnedWarGamesVehicles, record)

    minigames.S.spawnedWarGamesVehicleCount = (minigames.S.spawnedWarGamesVehicleCount or 0) + 1
    minigames.Player.activeWarGamesVehicle[playerId] = vehicleEntity

    minigames.LogInfo(
        "[WarGames Vehicle Tracking] id=" ..
        tostring(record.id) ..
        " | entity=" ..
        tostring(vehicleEntity) ..
        " | player=" ..
        tostring(playerId) ..
        " | owner=" ..
        tostring(record.ownerName) ..
        " | vehicle=" ..
        tostring(record.label) ..
        " | method=" ..
        tostring(record.method)
    )
end

function minigames.MarkTrackedVehicleUsage(record, used, now)
    if not record then return end
    now = now or minigames.Now()

    if used == true then
        record.everUsed = true
        record.lastUsedAtMs = now
        if not record.firstUsedAtMs or record.firstUsedAtMs == 0 then
            record.firstUsedAtMs = now
        end
    end

    record.lastSeenMs = now
end

function minigames.CleanupWarGamesVehicles(force)
    minigames.S.spawnedWarGamesVehicles = minigames.S.spawnedWarGamesVehicles or {}

    local now = minigames.Now()
    local idleMs = minigames.S.vehicleIdleCleanupMs or 60000

    local kept = {}
    local deleted = 0
    local attempted = 0
    local failed = 0
    local missing = 0
    local destroyed = 0
    local unusedExpired = 0
    local keptUsed = 0
    local keptYoung = 0
    local keptLiveUnused = 0

    for _, record in ipairs(minigames.S.spawnedWarGamesVehicles) do
        local entity = record.entity

        if not entity or entity == 0 or not minigames.EntityExists(entity) then
            missing = missing + 1
        else
            local age = now - (record.spawnedAtMs or now)
            local usedNow = minigames.IsVehicleUsed and minigames.IsVehicleUsed(entity) or false
            local isDestroyed = minigames.IsVehicleDestroyed and minigames.IsVehicleDestroyed(entity) or false

            minigames.MarkTrackedVehicleUsage(record, usedNow, now)

            local shouldDelete = false
            local deleteReason = "none"

            if force == true then
                shouldDelete = true
                deleteReason = "force"
            elseif isDestroyed == true then
                shouldDelete = true
                deleteReason = "destroyed"
                destroyed = destroyed + 1
            elseif record.everUsed ~= true and age >= idleMs then
                shouldDelete = true
                deleteReason = "unused_expired"
                unusedExpired = unusedExpired + 1
            end

            if shouldDelete then
                attempted = attempted + 1

                if minigames.DeleteVehicleEntity(entity) then
                    deleted = deleted + 1
                    record.deleted = true
                    minigames.S.vehicleCleanupDeletedTotal = (minigames.S.vehicleCleanupDeletedTotal or 0) + 1
                    minigames.LogInfo(
                        "[WarGames Cleanup] deleted tracked vehicle id=" ..
                        tostring(record.id or "?") ..
                        " | entity=" ..
                        tostring(entity) ..
                        " | reason=" ..
                        tostring(deleteReason) ..
                        " | vehicle=" ..
                        tostring(record.label)
                    )
                else
                    failed = failed + 1
                    table.insert(kept, record)
                end
            else
                if usedNow then
                    keptUsed = keptUsed + 1
                elseif age < idleMs then
                    keptYoung = keptYoung + 1
                else
                    keptLiveUnused = keptLiveUnused + 1
                end

                table.insert(kept, record)
            end
        end
    end

    minigames.S.spawnedWarGamesVehicles = kept
    minigames.S.deletedWarGamesVehicleCount = (minigames.S.deletedWarGamesVehicleCount or 0) + deleted

    minigames.S.lastVehicleCleanupStatus =
        "cleanup deleted=" ..
        tostring(deleted) ..
        " attempted=" ..
        tostring(attempted) ..
        " failed=" ..
        tostring(failed) ..
        " destroyed=" ..
        tostring(destroyed) ..
        " unusedExpired=" ..
        tostring(unusedExpired) ..
        " keptUsed=" ..
        tostring(keptUsed) ..
        " keptYoung=" ..
        tostring(keptYoung) ..
        " keptLiveUnused=" ..
        tostring(keptLiveUnused) ..
        " missing=" ..
        tostring(missing) ..
        " tracking=" ..
        tostring(#kept)

    -- quiet success logs; only log when it actually matters.
    if deleted > 0 or failed > 0 or force == true then
        minigames.LogInfo("[WarGames Cleanup] " .. minigames.S.lastVehicleCleanupStatus)
    end

    return deleted, attempted, failed
end

function minigames.VehicleCleanupTick()
    if minigames.S.autoCleanupWarGamesVehicles ~= true and minigames.S.wargamesSystemsActive ~= true then
        return
    end

    local now = minigames.Now()
    local scanMs = minigames.S.vehicleCleanupScanMs or 180000
    local last = minigames.S.lastVehicleCleanupScanMs or 0

    if last ~= 0 and now - last < scanMs then
        return
    end

    minigames.S.lastVehicleCleanupScanMs = now

    local ok, err = direct_call_trace(function()
        minigames.CleanupWarGamesVehicles(false)
    end, debug and debug.traceback or function(e) return tostring(e) end)

    if not ok then
        minigames.S.lastVehicleCleanupStatus = "cleanup tick error: " .. tostring(err)
        minigames.LogError("[WarGames Cleanup] " .. minigames.S.lastVehicleCleanupStatus)
    end
end

function minigames.GetTrackedVehicleForPlayer(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)
    minigames.S.spawnedWarGamesVehicles = minigames.S.spawnedWarGamesVehicles or {}

    local newest = nil

    for _, record in ipairs(minigames.S.spawnedWarGamesVehicles) do
        if record.playerId == playerId and record.entity and record.entity ~= 0 and minigames.EntityExists(record.entity) then
            local destroyed = minigames.IsVehicleDestroyed and minigames.IsVehicleDestroyed(record.entity) or false
            if destroyed ~= true then
                if not newest or (record.spawnedAtMs or 0) > (newest.spawnedAtMs or 0) then
                    newest = record
                end
            end
        end
    end

    return newest
end


------------------------------------------------------------
-- v0.108 spawn rate tracking wrapper
------------------------------------------------------------
local __mg108_spawn_vehicle_for_player = minigames.SpawnVehicleForPlayer
function minigames.SpawnVehicleForPlayer(playerId, vehicle, force, reason)
    playerId = minigames.ClampInt(playerId or 0, 0, 31)

    minigames.Player = minigames.Player or {}
    minigames.Player.lastVehicleSpawnMs = minigames.Player.lastVehicleSpawnMs or {}

    local now = minigames.Now()
    local last = minigames.Player.lastVehicleSpawnMs[playerId] or 0
    local minGap = minigames.S.respawnMinimumSpawnGapMs or 9000

    local reasonText = tostring(reason or "")
    local isRespawn = reasonText:lower():find("respawn") ~= nil

    if isRespawn and last ~= 0 and now - last < minGap then
        minigames.LogInfo(
            "[Vehicle Spawn] blocked by v0.108 per-player cooldown | player=" ..
            tostring(playerId) ..
            " | waitMs=" ..
            tostring(minGap - (now - last)) ..
            " | reason=" ..
            reasonText
        )
        return false, "cooldown"
    end

    local ok, status = __mg108_spawn_vehicle_for_player(playerId, vehicle, force, reason)

    if ok == true then
        minigames.Player.lastVehicleSpawnMs[playerId] = minigames.Now()
    end

    return ok, status
end


------------------------------------------------------------
-- v0.109 local/remote respawn spawn cooldown override
------------------------------------------------------------
-- v0.108 blocked hydra once by only 291ms. that killed fast testing.
-- new rule:
-- - local/self respawn cooldown: 1000ms
-- - remote-player respawn cooldown: 15000ms
-- - non-respawn/manual force spawns are not affected by this respawn cooldown.
------------------------------------------------------------

local __mg109_spawn_vehicle_for_player = minigames.SpawnVehicleForPlayer
function minigames.SpawnVehicleForPlayer(playerId, vehicle, force, reason)
    playerId = minigames.ClampInt(playerId or 0, 0, 31)

    minigames.Player = minigames.Player or {}
    minigames.Player.lastVehicleSpawnMs = minigames.Player.lastVehicleSpawnMs or {}

    local now = minigames.Now()
    local localId = minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or 0
    local isLocal = playerId == localId
    local reasonText = tostring(reason or "")
    local lowerReason = reasonText:lower()
    local isRespawn = lowerReason:find("respawn") ~= nil or lowerReason:find("death") ~= nil

    if isRespawn then
        local last = minigames.Player.lastVehicleSpawnMs[playerId] or 0
        local gap = isLocal and (minigames.S.localRespawnMinimumSpawnGapMs or 1000) or (minigames.S.remoteRespawnMinimumSpawnGapMs or 15000)

        if last ~= 0 and now - last < gap then
            minigames.LogInfo(
                "[Vehicle Spawn] respawn cooldown blocked | player=" ..
                tostring(playerId) ..
                " | local=" ..
                tostring(isLocal) ..
                " | waitMs=" ..
                tostring(gap - (now - last)) ..
                " | reason=" ..
                reasonText
            )
            return false, "cooldown"
        end
    end

    local ok, status = __mg109_spawn_vehicle_for_player(playerId, vehicle, force, reason)

    if ok == true then
        minigames.Player.lastVehicleSpawnMs[playerId] = minigames.Now()
    end

    return ok, status
end


------------------------------------------------------------
-- v0.110 local respawn cooldown final override
------------------------------------------------------------
-- local fast-suicide testing should never be blocked by the old 9000ms v0.108 wrapper.
-- keep only a tiny 500ms safety guard for duplicate same-frame triggers.
------------------------------------------------------------

local __mg110_spawn_vehicle_for_player = minigames.SpawnVehicleForPlayer
function minigames.SpawnVehicleForPlayer(playerId, vehicle, force, reason)
    playerId = minigames.ClampInt(playerId or 0, 0, 31)

    minigames.Player = minigames.Player or {}
    minigames.Player.lastVehicleSpawnMs = minigames.Player.lastVehicleSpawnMs or {}

    local now = minigames.Now()
    local localId = 0
    if minigames.GetLocalPlayerId then
        local okLocal, result = direct_call(minigames.GetLocalPlayerId)
        if okLocal and tonumber(result) ~= nil then
            localId = minigames.ClampInt(result, 0, 31)
        end
    end

    local isLocal = playerId == localId or playerId == 0
    local reasonText = tostring(reason or "")
    local lowerReason = reasonText:lower()
    local isRespawn = lowerReason:find("respawn") ~= nil or lowerReason:find("death") ~= nil

    if isRespawn then
        local last = minigames.Player.lastVehicleSpawnMs[playerId] or 0
        local gap = isLocal and 500 or (minigames.S.remoteRespawnMinimumSpawnGapMs or 15000)

        if last ~= 0 and now - last < gap then
            minigames.LogInfo(
                "[Vehicle Spawn] v0.110 respawn cooldown blocked | player=" ..
                tostring(playerId) ..
                " | local=" ..
                tostring(isLocal) ..
                " | waitMs=" ..
                tostring(gap - (now - last)) ..
                " | reason=" ..
                reasonText
            )
            return false, "cooldown"
        end
    end

    local ok, status = __mg110_spawn_vehicle_for_player(playerId, vehicle, force, reason)

    if ok == true then
        minigames.Player.lastVehicleSpawnMs[playerId] = minigames.Now()
    end

    return ok, status
end


------------------------------------------------------------
-- v0.111 one active respawn vehicle per player
------------------------------------------------------------
-- the log showed respawn working through many vehicles, then a fatal after many
-- sequential respawn vehicles stayed tracked/alive. to reduce entity pressure,
-- each player gets only one active respawn vehicle at a time.
------------------------------------------------------------

function minigames.DeleteEntitySafe(entity, reason)
    if entity == nil or entity == 0 then
        return false, "empty"
    end

    local okExists = true
    if ENTITY and ENTITY.DOES_ENTITY_EXIST then
        local ok, exists = direct_call(function()
            return ENTITY.DOES_ENTITY_EXIST(entity)
        end)
        okExists = ok and exists == true
    end

    if not okExists then
        return false, "missing"
    end

    -- try all safe ownership/delete paths available in cherax/gta.
    local attempts = {
        function()
            if NETWORK and NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY then
                NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(entity)
            end
        end,
        function()
            if ENTITY and ENTITY.SET_ENTITY_AS_MISSION_ENTITY then
                ENTITY.SET_ENTITY_AS_MISSION_ENTITY(entity, true, true)
            end
        end,
        function()
            if ENTITY and ENTITY.DELETE_ENTITY then
                local e = entity
                ENTITY.DELETE_ENTITY(e)
            end
        end,
        function()
            if entities and entities.delete_by_handle then
                entities.delete_by_handle(entity)
            end
        end,
        function()
            if Entity and Entity.Delete then
                Entity.Delete(entity)
            end
        end
    }

    for _, fn in ipairs(attempts) do
        direct_call(fn)
    end

    minigames.LogInfo("[Vehicle Cleanup] DeleteEntitySafe | entity=" .. tostring(entity) .. " | reason=" .. tostring(reason or "unknown"))
    return true, "attempted"
end

function minigames.DeletePreviousRespawnVehicleForPlayer(playerId, reason)
    if minigames.S.deletePreviousRespawnVehicleForPlayer ~= true then
        return false, "disabled"
    end

    playerId = minigames.ClampInt(playerId or 0, 0, 31)

    minigames.Player = minigames.Player or {}
    minigames.Player.activeRespawnVehicle = minigames.Player.activeRespawnVehicle or {}

    local old = minigames.Player.activeRespawnVehicle[playerId]
    if not old or not old.entity then
        return false, "none"
    end

    local ok, status = minigames.DeleteEntitySafe(old.entity, reason or "delete previous respawn vehicle")
    minigames.Player.activeRespawnVehicle[playerId] = nil

    return ok, status
end

function minigames.PruneRespawnVehicleTracking(reason)
    minigames.Player = minigames.Player or {}
    minigames.Player.activeRespawnVehicle = minigames.Player.activeRespawnVehicle or {}

    local count = 0
    for playerId, entry in pairs(minigames.Player.activeRespawnVehicle) do
        count = count + 1
    end

    local maxRespawn = minigames.S.maxTrackedRespawnVehicles or 6
    if count <= maxRespawn then
        return 0
    end

    local removed = 0
    for playerId, entry in pairs(minigames.Player.activeRespawnVehicle) do
        if removed >= (count - maxRespawn) then
            break
        end

        if tonumber(playerId) ~= 0 and entry and entry.entity then
            minigames.DeleteEntitySafe(entry.entity, reason or "respawn tracking prune")
            minigames.Player.activeRespawnVehicle[playerId] = nil
            removed = removed + 1
        end
    end

    if removed > 0 then
        minigames.LogInfo("[Vehicle Cleanup] Pruned respawn vehicles | removed=" .. tostring(removed) .. " | reason=" .. tostring(reason or "prune"))
    end

    return removed
end

local __mg111_spawn_vehicle_for_player = minigames.SpawnVehicleForPlayer
function minigames.SpawnVehicleForPlayer(playerId, vehicle, force, reason)
    playerId = minigames.ClampInt(playerId or 0, 0, 31)

    local reasonText = tostring(reason or "")
    local lowerReason = reasonText:lower()
    local isRespawn = lowerReason:find("respawn") ~= nil or lowerReason:find("death") ~= nil

    if isRespawn then
        minigames.DeletePreviousRespawnVehicleForPlayer(playerId, "before new respawn vehicle")
    end

    local ok, status = __mg111_spawn_vehicle_for_player(playerId, vehicle, force, reason)

    if ok == true and isRespawn then
        minigames.Player = minigames.Player or {}
        minigames.Player.activeRespawnVehicle = minigames.Player.activeRespawnVehicle or {}
        minigames.Player.lastVehicleSpawnMs = minigames.Player.lastVehicleSpawnMs or {}

        -- best effort: the lower spawn function should have tracked last spawned entity.
        -- use newest tracked vehicle for this player if available.
        local newest = nil
        if minigames.S and minigames.S.trackedVehicles then
            for _, entry in pairs(minigames.S.trackedVehicles) do
                if entry and minigames.ClampInt(entry.playerId or entry.player or -1, -1, 31) == playerId then
                    if newest == nil or (entry.id or 0) > (newest.id or 0) then
                        newest = entry
                    end
                end
            end
        end

        if newest and newest.entity then
            minigames.Player.activeRespawnVehicle[playerId] = {
                entity = newest.entity,
                id = newest.id,
                vehicle = newest.vehicle or (vehicle and vehicle.label),
                createdMs = minigames.Now()
            }
        end

        minigames.PruneRespawnVehicleTracking("after respawn spawn")
    end

    return ok, status
end


------------------------------------------------------------
-- v0.112 aggressive local respawn cleanup
------------------------------------------------------------
-- v0.111 still allowed tracked vehicle count to climb. for local respawn tests,
-- clear every tracked local wargames vehicle before spawning the next respawn car.
------------------------------------------------------------

function minigames.DeleteTrackedVehiclesForPlayer(playerId, reason)
    playerId = minigames.ClampInt(playerId or 0, 0, 31)

    local deleted = 0
    local kept = 0

    if not minigames.S or type(minigames.S.trackedVehicles) ~= "table" then
        return 0, "no_tracking"
    end

    for key, entry in pairs(minigames.S.trackedVehicles) do
        if entry then
            local entryPlayer = entry.playerId or entry.player or entry.ownerId or -999
            entryPlayer = minigames.ClampInt(entryPlayer, -1, 31)

            if entryPlayer == playerId then
                local entity = entry.entity or entry.handle or entry.vehicle
                if entity and entity ~= 0 then
                    minigames.DeleteEntitySafe(entity, reason or "delete tracked vehicles for player")
                    deleted = deleted + 1
                end
                minigames.S.trackedVehicles[key] = nil
            else
                kept = kept + 1
            end
        end
    end

    minigames.LogInfo(
        "[Vehicle Cleanup] DeleteTrackedVehiclesForPlayer | player=" ..
        tostring(playerId) ..
        " | deleted=" ..
        tostring(deleted) ..
        " | kept=" ..
        tostring(kept) ..
        " | reason=" ..
        tostring(reason or "unknown")
    )

    return deleted, "ok"
end

function minigames.PruneAllTrackedWarGamesVehicles(reason)
    if not minigames.S or type(minigames.S.trackedVehicles) ~= "table" then
        return 0
    end

    local entries = {}
    for key, entry in pairs(minigames.S.trackedVehicles) do
        if entry then
            table.insert(entries, { key = key, entry = entry, id = tonumber(entry.id or key) or 0 })
        end
    end

    table.sort(entries, function(a, b) return a.id < b.id end)

    local maxCount = minigames.S.maxTrackedWarGamesVehicles or 6
    local removeCount = #entries - maxCount
    local removed = 0

    if removeCount <= 0 then
        return 0
    end

    for i = 1, removeCount do
        local item = entries[i]
        if item and item.entry then
            local entity = item.entry.entity or item.entry.handle or item.entry.vehicle
            if entity and entity ~= 0 then
                minigames.DeleteEntitySafe(entity, reason or "tracked vehicle prune")
            end
            minigames.S.trackedVehicles[item.key] = nil
            removed = removed + 1
        end
    end

    minigames.LogInfo("[Vehicle Cleanup] PruneAllTrackedWarGamesVehicles | removed=" .. tostring(removed) .. " | max=" .. tostring(maxCount))
    return removed
end

local __mg112_spawn_vehicle_for_player = minigames.SpawnVehicleForPlayer
function minigames.SpawnVehicleForPlayer(playerId, vehicle, force, reason)
    playerId = minigames.ClampInt(playerId or 0, 0, 31)

    local reasonText = tostring(reason or "")
    local lowerReason = reasonText:lower()
    local isRespawn = lowerReason:find("respawn") ~= nil or lowerReason:find("death") ~= nil

    local localId = 0
    if minigames.GetLocalPlayerId then
        local okLocal, result = direct_call(minigames.GetLocalPlayerId)
        if okLocal and tonumber(result) ~= nil then
            localId = minigames.ClampInt(result, 0, 31)
        end
    end

    local isLocal = playerId == 0 or playerId == localId

    if isRespawn and isLocal and minigames.S.deleteAllLocalTrackedVehiclesBeforeRespawn == true then
        minigames.DeleteTrackedVehiclesForPlayer(playerId, "before local respawn spawn")
        minigames.DeleteTrackedVehiclesForPlayer(0, "before local respawn spawn local zero")
    end

    local ok, status = __mg112_spawn_vehicle_for_player(playerId, vehicle, force, reason)

    if ok == true then
        minigames.PruneAllTrackedWarGamesVehicles("after spawn cap")
    end

    return ok, status
end


