-- v0.117 safety guard
------------------------------------------------------------
-- these systems are intentionally off by default because live testing showed
-- respawn vehicles worked again after disabling them.
------------------------------------------------------------


------------------------------------------------------------
-- v0.118 pedwars-style cleanup tracking hook
------------------------------------------------------------
-- tracks wargames vehicles into the pedwars-style cleanup engine without changing
-- respawn spawn behavior.
------------------------------------------------------------

local __mg118_spawn_vehicle_for_player = minigames.SpawnVehicleForPlayer
function minigames.SpawnVehicleForPlayer(playerId, vehicle, force, reason)
    local ok, status = __mg118_spawn_vehicle_for_player(playerId, vehicle, force, reason)

    -- the original spawn function already logs and tracks into mg.s.trackedvehicles.
    -- this hook only normalizes newest tracked entry for pedwars-style cleanup.
    if ok == true and minigames.PWCleanup and minigames.S and type(minigames.S.trackedVehicles) == "table" then
        local newest = nil
        local p = minigames.ClampInt(playerId or -1, -1, 31)

        for _, entry in pairs(minigames.S.trackedVehicles) do
            if entry then
                local entryPlayer = minigames.ClampInt(entry.playerId or entry.player or -1, -1, 31)
                if entryPlayer == p then
                    if newest == nil or (tonumber(entry.id or 0) or 0) > (tonumber(newest.id or 0) or 0) then
                        newest = entry
                    end
                end
            end
        end

        if newest then
            newest.cleanupEngine = "PedWarsStyle"
            newest.lastSeenMs = minigames.PWCleanup.Now()
            newest.source = "WarGames"
            newest.method = newest.method or tostring(reason or "SpawnVehicleForPlayer")
        end
    end

    return ok, status
end

------------------------------------------------------------
-- v0.127 respawn vehicle id tracking hook
------------------------------------------------------------
local __mg127_spawn_vehicle_for_player = minigames.SpawnVehicleForPlayer
function minigames.SpawnVehicleForPlayer(playerId, vehicle, force, reason)
    local ok, status = __mg127_spawn_vehicle_for_player(playerId, vehicle, force, reason)

    local reasonText = tostring(reason or "")
    local lowerReason = reasonText:lower()
    local isRespawnSpawn = lowerReason:find("respawn") ~= nil or lowerReason:find("death") ~= nil or lowerReason:find("queued") ~= nil

    if ok == true and isRespawnSpawn and minigames.VehicleTracking and minigames.VehicleTracking.TrackVehicle then
        local label = "Unknown"
        if type(vehicle) == "table" then
            label = tostring(vehicle.label or vehicle.name or vehicle.model or "Unknown")
        elseif vehicle ~= nil then
            label = tostring(vehicle)
        end

        local newest = minigames.VehicleTracking.FindNewestRawTrackedForPlayer and minigames.VehicleTracking.FindNewestRawTrackedForPlayer(playerId) or nil
        if newest and newest.entity then
            minigames.VehicleTracking.TrackVehicle(newest.entity, playerId, label, reasonText, newest.method or "Respawn Spawn")
        elseif type(status) == "number" then
            minigames.VehicleTracking.TrackVehicle(status, playerId, label, reasonText, "Respawn Spawn Status Handle")
        else
            minigames.LogInfo("[WarGames Vehicle Tracking] respawn spawn succeeded but no entity handle was discovered | player=" .. tostring(playerId) .. " | vehicle=" .. tostring(label) .. " | reason=" .. reasonText)
        end

        minigames.VehicleTracking.Reconcile("after_respawn_spawn")
    end

    return ok, status
end


------------------------------------------------------------
-- v0.128 spawn tracker hud sync
------------------------------------------------------------
-- keep hud stats refreshed even when the older raw spawn tracker logs the vehicle first.
local __mg128_old_spawn_vehicle_for_player = minigames.SpawnVehicleForPlayer
function minigames.SpawnVehicleForPlayer(playerId, vehicle, force, reason)
    local ok, status = __mg128_old_spawn_vehicle_for_player(playerId, vehicle, force, reason)

    if ok == true and minigames.VehicleTracking and minigames.VehicleTracking.SyncHudStats then
        minigames.VehicleTracking.SyncHudStats("spawn_vehicle_for_player")
    end

    return ok, status
end
end

-- ============================================================
-- embedded module: systems\vehicle_spawn_prime.lua
-- ============================================================
embedded_modules['systems\\vehicle_spawn_prime.lua'] = function()
-- minigames/systems/vehicle_spawn_prime.lua
-- v0.171-alpha
--
-- prime-safe wargames vehicle spawning:
-- use cherax gta.spawnvehicleforplayer first, because it performs the
-- player-relative spawn ceremony internally. do not reposition/ground the
-- returned vehicle afterward. retain the stable raw path as fallback only.

minigames.PrimeVehicleSpawn = minigames.PrimeVehicleSpawn or {}

function minigames.PrimeVehicleSpawn.GetCheraxRuntime()
    local edition, version, build = "Unknown", "Unknown", "Unknown"

    direct_call(function()
        if Cherax and Cherax.GetEdition then
            edition = tostring(Cherax.GetEdition() or "Unknown")
        end
    end)

    direct_call(function()
        if Cherax and Cherax.GetVersion then
            version = tostring(Cherax.GetVersion() or "Unknown")
        end
    end)

    direct_call(function()
        if Cherax and Cherax.GetBuild then
            build = tostring(Cherax.GetBuild() or "Unknown")
        end
    end)

    return edition, version, build
end

function minigames.PrimeVehicleSpawn.ToUnsigned32(value)
    value = tonumber(value)
    if not value then return nil end

    value = math.floor(value)
    if value < 0 then
        value = value + 4294967296
    end

    return value
end

function minigames.PrimeVehicleSpawn.ToSigned32(value)
    value = minigames.PrimeVehicleSpawn.ToUnsigned32(value)
    if not value then return nil end

    if value > 2147483647 then
        return value - 4294967296
    end

    return value
end

function minigames.PrimeVehicleSpawn.GetModelHash(model)
    if type(model) == "number" then
        return model
    end

    if type(model) == "string" and Utils and Utils.Joaat then
        local ok, hash = direct_call(Utils.Joaat, model)
        if ok and hash ~= nil then
            return tonumber(hash)
        end
    end

    return tonumber(model)
end

function minigames.PrimeVehicleSpawn.RequestModel(modelHash)
    modelHash = tonumber(modelHash)
    if not modelHash then return false end

    if STREAMING and STREAMING.REQUEST_MODEL then
        direct_call(function()
            STREAMING.REQUEST_MODEL(modelHash)
        end)
    end

    return true
end

function minigames.PrimeVehicleSpawn.IsValidHandle(vehicleEntity)
    if not vehicleEntity or tonumber(vehicleEntity or 0) == 0 then
        return false
    end

    if minigames.EntityExists then
        local ok, exists = direct_call(minigames.EntityExists, vehicleEntity)
        if ok then
            return exists == true
        end
    end

    return true
end

function minigames.PrimeVehicleSpawn.BuildCandidates(vehicle)
    local candidates = {}
    local seen = {}

    local function add(value, label)
        if value == nil then return end

        local key = type(value) .. ":" .. tostring(value)
        if seen[key] then return end
        seen[key] = true

        candidates[#candidates + 1] = {
            value = value,
            label = tostring(label or type(value))
        }
    end

    local model = vehicle and vehicle.model or nil
    local hash = minigames.PrimeVehicleSpawn.GetModelHash(model)
    local unsignedHash = minigames.PrimeVehicleSpawn.ToUnsigned32(hash)
    local signedHash = minigames.PrimeVehicleSpawn.ToSigned32(hash)

    if minigames.S.primeSafeTryModelString ~= false and type(model) == "string" and model ~= "" then
        add(model, "model_string")
    end

    if minigames.S.primeSafeTryUnsignedHash ~= false and unsignedHash ~= nil then
        add(unsignedHash, "unsigned_hash")
    end

    if minigames.S.primeSafeTrySignedHash ~= false and signedHash ~= nil then
        add(signedHash, "signed_hash")
    end

    return candidates, hash
end

function minigames.PrimeVehicleSpawn.TrySpawnForPlayer(vehicle, playerId)
    if not GTA or not GTA.SpawnVehicleForPlayer then
        return 0, "SpawnVehicleForPlayer_missing", {}
    end

    playerId = minigames.ClampInt(playerId, 0, 31)

    local candidates, hash = minigames.PrimeVehicleSpawn.BuildCandidates(vehicle)
    minigames.PrimeVehicleSpawn.RequestModel(hash)

    local forwardOffset = tonumber(minigames.S.primeSafeSpawnForwardOffset or minigames.S.spawnDistance or 5.0) or 5.0
    if forwardOffset < 2.0 then forwardOffset = 2.0 end
    if forwardOffset > 20.0 then forwardOffset = 20.0 end

    local attempts = {}

    for _, candidate in ipairs(candidates) do
        local vehicleEntity = 0
        local ok, result = direct_call(function()
            return GTA.SpawnVehicleForPlayer(candidate.value, playerId, forwardOffset)
        end)

        if ok and result then
            vehicleEntity = tonumber(result or 0) or 0
        end

        attempts[#attempts + 1] =
            candidate.label ..
            ":ok=" .. tostring(ok) ..
            ":handle=" .. tostring(vehicleEntity)

        if ok and minigames.PrimeVehicleSpawn.IsValidHandle(vehicleEntity) then
            return vehicleEntity, candidate.label, attempts
        end
    end

    return 0, "all_candidates_failed", attempts
end


------------------------------------------------------------
-- v0.154 prime local clone refresh
------------------------------------------------------------
-- the network entity is correct for remote clients. this refreshes only the
-- spawning prime client's local representation after a remote player enters.
-- it never changes entity coordinates.

minigames.PrimeVehicleSpawn.HASH = minigames.PrimeVehicleSpawn.HASH or {
    NETWORK_GET_NETWORK_ID_FROM_ENTITY = 0xA11700682F3AD45C,
    NETWORK_GET_ENTITY_FROM_NETWORK_ID = 0xCE4E5D9B0A4FF560,
    NETWORK_GET_ENTITY_IS_NETWORKED = 0xC7827959479DCC78,
    NETWORK_GET_ENTITY_IS_LOCAL = 0x0991549DE4D64762,
    NETWORK_IS_NETWORK_ID_REMOTELY_CONTROLLED = 0x7242F8B741CE1086,
    SET_NETWORK_ID_CAN_MIGRATE = 0x299EEB23175895FC,
    SET_NETWORK_ID_CAN_BE_REASSIGNED = 0x9D724B400A7E8FFC,
    NETWORK_CONCEAL_ENTITY = 0x1632BE0AC1E62876,
    NETWORK_FADE_OUT_ENTITY = 0xDE564951F95E09ED,
    NETWORK_FADE_IN_ENTITY = 0x1F4ED342ACEFE62D,
    SET_PLAYER_INVISIBLE_LOCALLY = 0x12B37D54667DB0B8,
    SET_PLAYER_VISIBLE_LOCALLY = 0xFAA10F1FAFB11AF2,
}

function minigames.PrimeVehicleSpawn.InvokeVoidV154(hash, ...)
    if Natives and Natives.InvokeVoid then
        return Natives.InvokeVoid(hash, ...)
    end

    if minigames.Inv and minigames.Inv.Void then
        return minigames.Inv.Void(hash, ...)
    end
end

function minigames.PrimeVehicleSpawn.InvokeIntV154(hash, ...)
    if Natives and Natives.InvokeInt then
        return Natives.InvokeInt(hash, ...)
    end

    if minigames.Inv and minigames.Inv.Int then
        return minigames.Inv.Int(hash, ...)
    end

    return 0
end

function minigames.PrimeVehicleSpawn.InvokeBoolV154(hash, ...)
    if Natives and Natives.InvokeBool then
        return Natives.InvokeBool(hash, ...)
    end

    if minigames.Inv and minigames.Inv.Bool then
        return minigames.Inv.Bool(hash, ...)
    end

    return false
end

function minigames.PrimeVehicleSpawn.GetEntityCoordsV154(entity)
    if not entity or entity == 0 then return nil end

    if ENTITY and ENTITY.GET_ENTITY_COORDS then
        local ok, coords = direct_call(function()
            return ENTITY.GET_ENTITY_COORDS(entity, true)
        end)

        if ok and coords then
            local x = tonumber(coords.x or coords.X or coords[1])
            local y = tonumber(coords.y or coords.Y or coords[2])
            local z = tonumber(coords.z or coords.Z or coords[3])

            if x and y and z then
                return { x = x, y = y, z = z }
            end
        end
    end

    return nil
end

function minigames.PrimeVehicleSpawn.GetNetworkIdV154(entity)
    if not entity or entity == 0 then return 0 end

    local netId = 0

    if NETWORK and NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY then
        direct_call(function()
            netId = NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY(entity)
        end)
    end

    if not netId or netId == 0 then
        direct_call(function()
            netId = minigames.PrimeVehicleSpawn.InvokeIntV154(
                minigames.PrimeVehicleSpawn.HASH.NETWORK_GET_NETWORK_ID_FROM_ENTITY,
                entity
            )
        end)
    end

    return tonumber(netId or 0) or 0
end

function minigames.PrimeVehicleSpawn.GetEntityFromNetworkIdV154(netId, fallbackEntity)
    netId = tonumber(netId or 0) or 0

    if netId ~= 0 then
        local entity = 0

        if NETWORK and NETWORK.NETWORK_GET_ENTITY_FROM_NETWORK_ID then
            direct_call(function()
                entity = NETWORK.NETWORK_GET_ENTITY_FROM_NETWORK_ID(netId)
            end)
        end

        if not entity or entity == 0 then
            direct_call(function()
                entity = minigames.PrimeVehicleSpawn.InvokeIntV154(
                    minigames.PrimeVehicleSpawn.HASH.NETWORK_GET_ENTITY_FROM_NETWORK_ID,
                    netId
                )
            end)
        end

        if entity and entity ~= 0 then
            return entity
        end
    end

    return fallbackEntity or 0
end

function minigames.PrimeVehicleSpawn.IsPlayerInsideVehicleV154(playerId, vehicleEntity)
    if not vehicleEntity or vehicleEntity == 0 then return false end

    local ped = 0

    if minigames.GetPlayerPed then
        direct_call(function()
            ped = minigames.GetPlayerPed(playerId)
        end)
    end

    if not ped or ped == 0 then return false end

    if PED and PED.IS_PED_IN_VEHICLE then
        local ok, result = direct_call(function()
            return PED.IS_PED_IN_VEHICLE(ped, vehicleEntity, false)
        end)

        if ok then return result == true end
    end

    if PED and PED.GET_VEHICLE_PED_IS_IN then
        local ok, current = direct_call(function()
            return PED.GET_VEHICLE_PED_IS_IN(ped, false)
        end)

        if ok then return current == vehicleEntity end
    end

    return false
end

function minigames.PrimeVehicleSpawn.ReleaseMissionHoldV154(vehicleEntity)
    minigames.S.lastPrimeMissionReleaseStatusV164 =
        "unsafe mission release skipped | entity=" ..
        tostring(vehicleEntity)

    return false, "disabled_v0_164"
end

function minigames.PrimeVehicleSpawn.AllowMigrationOnceV154(vehicleEntity, netId)
    if minigames.S.primeAllowOwnershipMigrationOnce ~= true then
        return
    end

    netId = tonumber(netId or 0) or 0
    if netId == 0 then return end

    if NETWORK and NETWORK.SET_NETWORK_ID_CAN_MIGRATE then
        direct_call(function()
            NETWORK.SET_NETWORK_ID_CAN_MIGRATE(netId, true)
        end)
    else
        direct_call(
            minigames.PrimeVehicleSpawn.InvokeVoidV154,
            minigames.PrimeVehicleSpawn.HASH.SET_NETWORK_ID_CAN_MIGRATE,
            netId,
            true
        )
    end

    if NETWORK and NETWORK.SET_NETWORK_ID_CAN_BE_REASSIGNED then
        direct_call(function()
            NETWORK.SET_NETWORK_ID_CAN_BE_REASSIGNED(netId, true)
        end)
    else
        direct_call(
            minigames.PrimeVehicleSpawn.InvokeVoidV154,
            minigames.PrimeVehicleSpawn.HASH.SET_NETWORK_ID_CAN_BE_REASSIGNED,
            netId,
            true
        )
    end
end

function minigames.PrimeVehicleSpawn.GetNetworkStateV154(vehicleEntity, netId)
    local networked, isLocal, remotelyControlled = false, false, false

    if vehicleEntity and vehicleEntity ~= 0 then
        if NETWORK and NETWORK.NETWORK_GET_ENTITY_IS_NETWORKED then
            direct_call(function()
                networked = NETWORK.NETWORK_GET_ENTITY_IS_NETWORKED(vehicleEntity) == true
            end)
        else
            direct_call(function()
                networked = minigames.PrimeVehicleSpawn.InvokeBoolV154(
                    minigames.PrimeVehicleSpawn.HASH.NETWORK_GET_ENTITY_IS_NETWORKED,
                    vehicleEntity
                ) == true
            end)
        end

        if NETWORK and NETWORK.NETWORK_GET_ENTITY_IS_LOCAL then
            direct_call(function()
                isLocal = NETWORK.NETWORK_GET_ENTITY_IS_LOCAL(vehicleEntity) == true
            end)
        else
            direct_call(function()
                isLocal = minigames.PrimeVehicleSpawn.InvokeBoolV154(
                    minigames.PrimeVehicleSpawn.HASH.NETWORK_GET_ENTITY_IS_LOCAL,
                    vehicleEntity
                ) == true
            end)
        end
    end

    if netId and netId ~= 0 then
        if NETWORK and NETWORK.NETWORK_IS_NETWORK_ID_REMOTELY_CONTROLLED then
            direct_call(function()
                remotelyControlled =
                    NETWORK.NETWORK_IS_NETWORK_ID_REMOTELY_CONTROLLED(netId) == true
            end)
        else
            direct_call(function()
                remotelyControlled = minigames.PrimeVehicleSpawn.InvokeBoolV154(
                    minigames.PrimeVehicleSpawn.HASH.NETWORK_IS_NETWORK_ID_REMOTELY_CONTROLLED,
                    netId
                ) == true
            end)
        end
    end

    return networked, isLocal, remotelyControlled
end

function minigames.PrimeVehicleSpawn.LocalCloneRefreshV154(vehicleEntity, playerId, netId, reason)
    vehicleEntity = minigames.PrimeVehicleSpawn.GetEntityFromNetworkIdV154(netId, vehicleEntity)

    if not minigames.PrimeVehicleSpawn.IsValidHandle(vehicleEntity) then
        return false, "vehicle_missing"
    end

    local before = minigames.PrimeVehicleSpawn.GetEntityCoordsV154(vehicleEntity)
    local networked, isLocal, remotelyControlled =
        minigames.PrimeVehicleSpawn.GetNetworkStateV154(vehicleEntity, netId)

    -- release our local script hold again before refreshing the clone.
    minigames.PrimeVehicleSpawn.ReleaseMissionHoldV154(vehicleEntity)
    minigames.PrimeVehicleSpawn.AllowMigrationOnceV154(vehicleEntity, netId)

    -- explicitly local player/vehicle visibility toggle.
    if minigames.S.primeCloneRefreshUsePlayerLocalVisibility ~= false then
        for _ = 1, 2 do
            if NETWORK and NETWORK.SET_PLAYER_INVISIBLE_LOCALLY then
                direct_call(function()
                    NETWORK.SET_PLAYER_INVISIBLE_LOCALLY(playerId, true)
                end)
            else
                direct_call(
                    minigames.PrimeVehicleSpawn.InvokeVoidV154,
                    minigames.PrimeVehicleSpawn.HASH.SET_PLAYER_INVISIBLE_LOCALLY,
                    playerId,
                    true
                )
            end

            if Script and Script.Yield then Script.Yield(0) end
        end
    end

    -- conceal/unconceal the vehicle on this client to force its clone to refresh.
    if minigames.S.primeCloneRefreshUseConceal ~= false then
        if NETWORK and NETWORK.NETWORK_CONCEAL_ENTITY then
            direct_call(function()
                NETWORK.NETWORK_CONCEAL_ENTITY(vehicleEntity, true)
            end)
        else
            direct_call(
                minigames.PrimeVehicleSpawn.InvokeVoidV154,
                minigames.PrimeVehicleSpawn.HASH.NETWORK_CONCEAL_ENTITY,
                vehicleEntity,
                true
            )
        end

        if Script and Script.Yield then Script.Yield(80) end

        if NETWORK and NETWORK.NETWORK_CONCEAL_ENTITY then
            direct_call(function()
                NETWORK.NETWORK_CONCEAL_ENTITY(vehicleEntity, false)
            end)
        else
            direct_call(
                minigames.PrimeVehicleSpawn.InvokeVoidV154,
                minigames.PrimeVehicleSpawn.HASH.NETWORK_CONCEAL_ENTITY,
                vehicleEntity,
                false
            )
        end
    end

    -- a brief local network fade rebuilds the rendered clone without moving it.
    if minigames.S.primeCloneRefreshUseFade ~= false then
        if NETWORK and NETWORK.NETWORK_FADE_OUT_ENTITY then
            direct_call(function()
                NETWORK.NETWORK_FADE_OUT_ENTITY(vehicleEntity, false, false)
            end)
        else
            direct_call(
                minigames.PrimeVehicleSpawn.InvokeVoidV154,
                minigames.PrimeVehicleSpawn.HASH.NETWORK_FADE_OUT_ENTITY,
                vehicleEntity,
                false,
                false
            )
        end

        if Script and Script.Yield then Script.Yield(90) end

        if NETWORK and NETWORK.NETWORK_FADE_IN_ENTITY then
            direct_call(function()
                NETWORK.NETWORK_FADE_IN_ENTITY(vehicleEntity, false, 0)
            end)
        else
            direct_call(
                minigames.PrimeVehicleSpawn.InvokeVoidV154,
                minigames.PrimeVehicleSpawn.HASH.NETWORK_FADE_IN_ENTITY,
                vehicleEntity,
                false,
                0
            )
        end
    end

    if minigames.S.primeCloneRefreshUsePlayerLocalVisibility ~= false then
        for _ = 1, 4 do
            if NETWORK and NETWORK.SET_PLAYER_VISIBLE_LOCALLY then
                direct_call(function()
                    NETWORK.SET_PLAYER_VISIBLE_LOCALLY(playerId, true)
                end)
            else
                direct_call(
                    minigames.PrimeVehicleSpawn.InvokeVoidV154,
                    minigames.PrimeVehicleSpawn.HASH.SET_PLAYER_VISIBLE_LOCALLY,
                    playerId,
                    true
                )
            end

            if Script and Script.Yield then Script.Yield(0) end
        end
    end

    vehicleEntity = minigames.PrimeVehicleSpawn.GetEntityFromNetworkIdV154(netId, vehicleEntity)
    local after = minigames.PrimeVehicleSpawn.GetEntityCoordsV154(vehicleEntity)

    minigames.S.primeLocalCloneRefreshLastStatus =
        "refreshed | player=" .. tostring(playerId) ..
        " | entity=" .. tostring(vehicleEntity) ..
        " | netId=" .. tostring(netId) ..
        " | networked=" .. tostring(networked) ..
        " | local=" .. tostring(isLocal) ..
        " | remoteControlled=" .. tostring(remotelyControlled) ..
        " | beforeZ=" .. tostring(before and before.z or "nil") ..
        " | afterZ=" .. tostring(after and after.z or "nil") ..
        " | reason=" .. tostring(reason or "entry")

    if minigames.LogInfo then
        minigames.LogInfo(
            "[Prime Local Clone] " ..
            minigames.S.primeLocalCloneRefreshLastStatus
        )
    end

    return true, vehicleEntity
end

function minigames.PrimeVehicleSpawn.QueueLocalCloneRefreshV154(
    vehicleEntity,
    playerId,
    initialCoords,
    reason
)
    if minigames.S.primeLocalCloneRefreshEnabled ~= true then
        return false, "disabled"
    end

    if minigames.IsSelf and minigames.IsSelf(playerId) then
        return false, "local_player_skipped"
    end

    if not Script or not Script.QueueJob then
        return false, "queue_job_missing"
    end

    local netId = minigames.PrimeVehicleSpawn.GetNetworkIdV154(vehicleEntity)
    local originalEntity = vehicleEntity
    local initialZ = initialCoords and tonumber(initialCoords.z) or nil

    Script.QueueJob(function()
        local waitMs = tonumber(minigames.S.primeCloneRefreshEntryWaitMs or 12000) or 12000
        local elapsed = 0
        local currentEntity = originalEntity
        local entered = false

        while elapsed < waitMs do
            currentEntity =
                minigames.PrimeVehicleSpawn.GetEntityFromNetworkIdV154(netId, currentEntity)

            if minigames.PrimeVehicleSpawn.IsPlayerInsideVehicleV154(playerId, currentEntity) then
                entered = true
                break
            end

            if Script and Script.Yield then Script.Yield(250) end
            elapsed = elapsed + 250
        end

        if not entered then
            minigames.S.primeLocalCloneRefreshLastStatus =
                "entry wait expired | player=" .. tostring(playerId) ..
                " | entity=" .. tostring(currentEntity) ..
                " | netId=" .. tostring(netId)
            return
        end

        local delay = tonumber(minigames.S.primeCloneRefreshDelayMs or 350) or 350
        if Script and Script.Yield then Script.Yield(delay) end

        local ok, refreshedEntity =
            minigames.PrimeVehicleSpawn.LocalCloneRefreshV154(
                currentEntity,
                playerId,
                netId,
                reason or "remote_entry"
            )

        if not ok then return end

        local secondCheck =
            tonumber(minigames.S.primeCloneRefreshSecondCheckMs or 1200) or 1200
        if Script and Script.Yield then Script.Yield(secondCheck) end

        refreshedEntity =
            minigames.PrimeVehicleSpawn.GetEntityFromNetworkIdV154(netId, refreshedEntity)

        local coords =
            minigames.PrimeVehicleSpawn.GetEntityCoordsV154(refreshedEntity)
        local tolerance =
            tonumber(minigames.S.primeCloneRefreshDropTolerance or 6.0) or 6.0
        local emergencyZ =
            tonumber(minigames.S.primeCloneRefreshEmergencyZ or -20.0) or -20.0

        local needsSecondRefresh = false

        if coords then
            if coords.z < emergencyZ then
                needsSecondRefresh = true
            elseif initialZ and coords.z < (initialZ - tolerance) then
                needsSecondRefresh = true
            end
        end

        if needsSecondRefresh then
            minigames.PrimeVehicleSpawn.LocalCloneRefreshV154(
                refreshedEntity,
                playerId,
                netId,
                "second_check_local_drop"
            )
        end
    end)

    return true, "queued"
end


function minigames.PrimeVehicleSpawn.Finalize(vehicleEntity, vehicle, playerId, method, reason)
    if not minigames.PrimeVehicleSpawn.IsValidHandle(vehicleEntity) then
        return false, "invalid_handle"
    end

    -- capture the locally correct spawn position before remote entry.
    local initialCoords =
        minigames.PrimeVehicleSpawn.GetEntityCoordsV154(vehicleEntity)
    local netId =
        minigames.PrimeVehicleSpawn.GetNetworkIdV154(vehicleEntity)

    -- style while this client initially owns/controls the new entity.
    if minigames.ApplyWarGamesVehicleStyle then
        direct_call(minigames.ApplyWarGamesVehicleStyle, vehicleEntity)
    end

    if minigames.RegisterWarGamesVehicle then
        direct_call(
            minigames.RegisterWarGamesVehicle,
            vehicleEntity,
            playerId,
            vehicle,
            "Prime Safe " .. tostring(method)
        )
    end

    if minigames.MarkVehicleSpawned then
        minigames.MarkVehicleSpawned(playerId, "Prime Safe " .. tostring(method), vehicle)
    end

    if minigames.SetVehicleStatus then
        minigames.SetVehicleStatus(
            playerId,
            "Spawned " .. tostring(vehicle and vehicle.label or "vehicle") ..
                " using Cherax player-relative spawn",
            "Prime Safe " .. tostring(method),
            "None",
            vehicle
        )
    end

    minigames.S.lastVehicleEntity = vehicleEntity

    -- critical prime change:
    -- release the spawning script's mission hold, then permit normal remote ownership.
    minigames.PrimeVehicleSpawn.AllowMigrationOnceV154(vehicleEntity, netId)
    minigames.PrimeVehicleSpawn.ReleaseMissionHoldV154(vehicleEntity)

    -- v0.164: old local-clone refresh path stays disabled.
    minigames.S.primeLocalCloneRefreshEnabled = false
    minigames.S.primeLocalCloneRefreshLastStatus =
        "disabled by v0.164 safe spawn"

    minigames.S.primeSafeVehicleSpawnLastStatus =
        "spawned | player=" .. tostring(playerId) ..
        " | vehicle=" .. tostring(vehicle and vehicle.label or vehicle and vehicle.model or "Unknown") ..
        " | method=" .. tostring(method) ..
        " | handle=" .. tostring(vehicleEntity) ..
        " | netId=" .. tostring(netId) ..
        " | missionHoldReleased=false" ..
        " | localCloneRefreshQueued=true" ..
        " | reason=" .. tostring(reason or "WarGames")

    if minigames.LogInfo then
        minigames.LogInfo(
            "[Prime Vehicle Spawn] " ..
            minigames.S.primeSafeVehicleSpawnLastStatus
        )
    end

    return true, "spawned_prime_safe_clone_refresh"
end

-- preserve the known standard/premium raw path as fallback.
minigames.PrimeVehicleSpawn.RawFallback = minigames.PrimeVehicleSpawn.RawFallback or minigames.SpawnRawModelVehicle

function minigames.SpawnRawModelVehicle(vehicle, playerId, reason, force)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if minigames.S.primeSafePlayerVehicleSpawn ~= false then
        local vehicleEntity, method, attempts =
            minigames.PrimeVehicleSpawn.TrySpawnForPlayer(vehicle, playerId)

        minigames.S.primeSafeVehicleSpawnLastAttempts = table.concat(attempts or {}, " | ")

        if vehicleEntity and vehicleEntity ~= 0 then
            return minigames.PrimeVehicleSpawn.Finalize(
                vehicleEntity,
                vehicle,
                playerId,
                method,
                reason
            )
        end

        minigames.S.primeSafeVehicleSpawnLastStatus =
            "player-relative spawn failed | player=" .. tostring(playerId) ..
            " | vehicle=" .. tostring(vehicle and vehicle.label or vehicle and vehicle.model or "Unknown") ..
            " | attempts=" .. tostring(minigames.S.primeSafeVehicleSpawnLastAttempts)

        if minigames.LogInfo then
            minigames.LogInfo("[Prime Vehicle Spawn] " .. minigames.S.primeSafeVehicleSpawnLastStatus)
        end
    end

    if minigames.S.primeSafeRawFallbackEnabled ~= false
        and type(minigames.PrimeVehicleSpawn.RawFallback) == "function" then
        return minigames.PrimeVehicleSpawn.RawFallback(vehicle, playerId, reason, force)
    end

    if minigames.SetVehicleStatus then
        minigames.SetVehicleStatus(
            playerId,
            "Vehicle spawn failed: player-relative path failed and RAW fallback disabled",
            "Prime Safe",
            minigames.S.primeSafeVehicleSpawnLastAttempts or "no_attempts",
            vehicle
        )
    end

    return false, "prime_safe_spawn_failed"
end

do
    local edition, version, build = minigames.PrimeVehicleSpawn.GetCheraxRuntime()
    minigames.S.primeSafeVehicleSpawnRuntime =
        "edition=" .. tostring(edition) ..
        " | version=" .. tostring(version) ..
        " | build=" .. tostring(build)

    if minigames.LogInfo then
        minigames.LogInfo(
            "[Prime Vehicle Spawn] v0.153 compatibility module loaded | " ..
            minigames.S.primeSafeVehicleSpawnRuntime
        )
    end
end
end

-- ============================================================
-- embedded module: systems\vehicle_tracking.lua
-- ============================================================
embedded_modules['systems\\vehicle_tracking.lua'] = function()

-- minigames - respawn vehicle id tracking v0.171-alpha
minigames = minigames or {}
minigames.S = minigames.S or {}
minigames.VehicleTracking = minigames.VehicleTracking or {}

function minigames.VehicleTracking.Now()
    if minigames.Now then return minigames.Now() end
    if os and os.clock then return math.floor(os.clock() * 1000) end
    return 0
end

function minigames.VehicleTracking.Log(msg)
    if minigames.LogInfo then minigames.LogInfo("[WarGames Vehicle Tracking] " .. tostring(msg)) end
end

function minigames.VehicleTracking.Ensure()
    minigames.S.trackedVehicles = minigames.S.trackedVehicles or {}
    minigames.S.vehicleTrackingByEntity = minigames.S.vehicleTrackingByEntity or {}
    minigames.S.vehicleTrackingById = minigames.S.vehicleTrackingById or {}
    minigames.S.nextTrackedVehicleId = tonumber(minigames.S.nextTrackedVehicleId or 0) or 0
    minigames.S.vehiclesCleared = tonumber(minigames.S.vehiclesCleared or 0) or 0
    minigames.S.vehicleClearedCount = tonumber(minigames.S.vehicleClearedCount or 0) or 0
    minigames.S.totalVehiclesCleared = tonumber(minigames.S.totalVehiclesCleared or 0) or 0
end

function minigames.VehicleTracking.DoesEntityExist(entity)
    if entity == nil or entity == 0 then return false end
    if ENTITY and ENTITY.DOES_ENTITY_EXIST then
        local ok, exists = direct_call(function() return ENTITY.DOES_ENTITY_EXIST(entity) end)
        return ok and exists == true
    end
    return true
end

function minigames.VehicleTracking.FindNewestRawTrackedForPlayer(playerId)
    minigames.VehicleTracking.Ensure()
    local newest, newestId = nil, -1
    local p = tonumber(playerId) or -999

    for key, entry in pairs(minigames.S.trackedVehicles) do
        if entry then
            local entryPlayer = tonumber(entry.playerId or entry.player or entry.ownerId or -999) or -999
            local id = tonumber(entry.id or key or 0) or 0
            if entryPlayer == p and id > newestId then
                newest = entry
                newestId = id
            end
        end
    end
    return newest
end

function minigames.VehicleTracking.TrackVehicle(entity, playerId, vehicleLabel, reason, method)
    minigames.VehicleTracking.Ensure()
    entity = tonumber(entity) or entity
    if entity == nil or entity == 0 then return nil, "empty_entity" end

    local existingId = minigames.S.vehicleTrackingByEntity[tostring(entity)]
    if existingId and minigames.S.vehicleTrackingById[existingId] then
        local e = minigames.S.vehicleTrackingById[existingId]
        e.lastSeenMs = minigames.VehicleTracking.Now()
        e.reason = reason or e.reason
        return existingId, "already_tracked"
    end

    minigames.S.nextTrackedVehicleId = (tonumber(minigames.S.nextTrackedVehicleId or 0) or 0) + 1
    local id = minigames.S.nextTrackedVehicleId
    local ownerName = tostring(playerId or "unknown")
    if minigames.GetPlayerName then
        local ok, name = direct_call(minigames.GetPlayerName, playerId)
        if ok and name and tostring(name) ~= "" then ownerName = tostring(name) end
    end

    local entry = {
        id = id,
        entity = entity,
        playerId = playerId,
        player = playerId,
        owner = ownerName,
        vehicle = vehicleLabel or "Unknown",
        reason = reason or "unknown",
        method = method or "respawn_spawn",
        createdMs = minigames.VehicleTracking.Now(),
        lastSeenMs = minigames.VehicleTracking.Now(),
        cleared = false,
        source = "WarGamesRespawn",
        cleanupEngine = "VehicleTracking_v0.127"
    }

    minigames.S.vehicleTrackingById[id] = entry
    minigames.S.vehicleTrackingByEntity[tostring(entity)] = id
    minigames.S.trackedVehicles[id] = entry

    minigames.VehicleTracking.Log("id=" .. tostring(id) ..
        " | entity=" .. tostring(entity) ..
        " | player=" .. tostring(playerId) ..
        " | owner=" .. tostring(ownerName) ..
        " | vehicle=" .. tostring(vehicleLabel or "Unknown") ..
        " | reason=" .. tostring(reason or "unknown"))

    return id, "tracked"
end

function minigames.VehicleTracking.MarkCleared(idOrEntity, reason)
    minigames.VehicleTracking.Ensure()
    local id = tonumber(idOrEntity)
    if not id and idOrEntity ~= nil then id = minigames.S.vehicleTrackingByEntity[tostring(idOrEntity)] end
    if not id then return false, "not_found" end

    local entry = minigames.S.vehicleTrackingById[id] or minigames.S.trackedVehicles[id]
    if not entry then return false, "missing_entry" end
    if entry.cleared == true then return false, "already_cleared" end

    entry.cleared = true
    entry.clearedMs = minigames.VehicleTracking.Now()
    entry.clearReason = reason or "cleared"

    minigames.S.vehiclesCleared = (tonumber(minigames.S.vehiclesCleared or 0) or 0) + 1
    minigames.S.vehicleClearedCount = minigames.S.vehiclesCleared
    minigames.S.totalVehiclesCleared = minigames.S.vehiclesCleared

    if entry.entity then minigames.S.vehicleTrackingByEntity[tostring(entry.entity)] = nil end
    minigames.S.vehicleTrackingById[id] = nil
    minigames.S.trackedVehicles[id] = nil

    minigames.VehicleTracking.Log("cleared id=" .. tostring(id) ..
        " | entity=" .. tostring(entry.entity) ..
        " | vehicle=" .. tostring(entry.vehicle) ..
        " | reason=" .. tostring(reason or "cleared") ..
        " | clearedTotal=" .. tostring(minigames.S.vehiclesCleared))

    return true, "cleared"
end

function minigames.VehicleTracking.Reconcile(reason)
    minigames.VehicleTracking.Ensure()
    local ids = {}
    for id, _ in pairs(minigames.S.vehicleTrackingById) do table.insert(ids, id) end

    for _, id in ipairs(ids) do
        local entry = minigames.S.vehicleTrackingById[id]
        if entry and entry.entity then
            if minigames.VehicleTracking.DoesEntityExist(entry.entity) then
                entry.lastSeenMs = minigames.VehicleTracking.Now()
            else
                minigames.VehicleTracking.MarkCleared(id, reason or "missing_reconcile")
            end
        else
            minigames.VehicleTracking.MarkCleared(id, reason or "bad_entry_reconcile")
        end
    end

    local active = 0
    for _, entry in pairs(minigames.S.vehicleTrackingById) do
        if entry then active = active + 1 end
    end
    minigames.S.activeVehicleCount = active
    minigames.S.trackedVehicleCount = active
    return active, tonumber(minigames.S.vehiclesCleared or 0) or 0
end

function minigames.VehicleTracking.GetActiveCount()
    local active = select(1, minigames.VehicleTracking.Reconcile("hud_count"))
    return active or 0
end

function minigames.VehicleTracking.GetClearedCount()
    minigames.VehicleTracking.Ensure()
    return tonumber(minigames.S.vehiclesCleared or minigames.S.vehicleClearedCount or minigames.S.totalVehiclesCleared or 0) or 0
end

function minigames.VehicleTracking.Status()
    local active, cleared = minigames.VehicleTracking.Reconcile("status")
    local msg = "Vehicles=" .. tostring(active) .. " | Cleared=" .. tostring(cleared)
    minigames.VehicleTracking.Log("status | " .. msg)
    if minigames.Toast then minigames.Toast("Vehicle Tracking", msg, 5000) end
    return msg
end

minigames.VehicleTracking.Log("loaded v0.171-alpha")


------------------------------------------------------------
-- v0.128 hud tracking bridge fix
------------------------------------------------------------
-- the spawn system already logs:
-- [wargames vehicle tracking] id=x | entity=y ...
--
-- v0.127 added a second tracker, but the hud could still miss the real spawn table.
-- v0.128 counts from every known wargames/spawn tracking bucket and exposes one
-- stable hud-facing count.
------------------------------------------------------------

function minigames.VehicleTracking.TableCount(tbl)
    if type(tbl) ~= "table" then return 0 end
    local c = 0
    for _, v in pairs(tbl) do
        if v ~= nil then c = c + 1 end
    end
    return c
end

function minigames.VehicleTracking.ExistsSoft(entity)
    if entity == nil or entity == 0 then return false end
    if ENTITY and ENTITY.DOES_ENTITY_EXIST then
        local ok, exists = direct_call(function()
            return ENTITY.DOES_ENTITY_EXIST(entity)
        end)
        return ok and exists == true
    end
    -- if entity isn't available, keep it counted instead of forcing hud to 0.
    return true
end

function minigames.VehicleTracking.IsTrackedEntryAlive(entry)
    if type(entry) ~= "table" then
        return false
    end

    local entity = entry.entity or entry.handle or entry.vehicle or entry.veh or entry.vehicleHandle
    if entity == nil then
        -- some older tracking tables may not expose the entity handle.
        -- keep these counted because the spawn system already accepted them.
        return true
    end

    return minigames.VehicleTracking.ExistsSoft(entity)
end

function minigames.VehicleTracking.GetCandidateTables()
    local S = minigames.S or {}
    local WG = minigames.WarGames or {}

    return {
        S.vehicleTrackingById,
        S.spawnedWarGamesVehicles,
        S.spawnedWarGamesVehicleRecords,
        S.trackedVehicles,
        S.wargamesTrackedVehicles,
        S.warGamesTrackedVehicles,
        S.spawnedVehicles,
        S.wargamesSpawnedVehicles,
        S.warGamesSpawnedVehicles,
        S.respawnVehicles,
        S.respawnTrackedVehicles,
        S.playerRespawnVehicles,
        S.playerRespawnVehicleEntities,
        WG.trackedVehicles,
        WG.spawnedVehicles,
        WG.respawnVehicles,
        WG.vehicleTrackingById,
        WG.TrackedVehicles,
        WG.SpawnedVehicles,
    }
end

function minigames.VehicleTracking.GetBestRawTrackedCount()
    local best = 0
    local liveBest = 0
    local missing = 0

    for _, tbl in ipairs(minigames.VehicleTracking.GetCandidateTables()) do
        if type(tbl) == "table" then
            local raw = 0
            local live = 0

            for _, entry in pairs(tbl) do
                if entry ~= nil then
                    raw = raw + 1
                    if type(entry) == "table" then
                        if minigames.VehicleTracking.IsTrackedEntryAlive(entry) then
                            live = live + 1
                        else
                            missing = missing + 1
                        end
                    else
                        -- numeric/entity-only lists count as live if entity exists or cannot be checked.
                        if minigames.VehicleTracking.ExistsSoft(entry) then
                            live = live + 1
                        else
                            missing = missing + 1
                        end
                    end
                end
            end

            if raw > best then best = raw end
            if live > liveBest then liveBest = live end
        end
    end

    -- prefer live count, but never allow hud to fall back to 0 while raw tracking exists.
    local active = liveBest
    if active <= 0 and best > 0 then active = best end

    minigames.S.activeVehicleCount = active
    minigames.S.trackedVehicleCount = active
    minigames.S.lastVehicleTrackingRawBest = best
    minigames.S.lastVehicleTrackingLiveBest = liveBest
    minigames.S.lastVehicleTrackingMissing = missing

    return active, best, liveBest, missing
end

function minigames.VehicleTracking.GetActiveCount()
    local active = select(1, minigames.VehicleTracking.GetBestRawTrackedCount())
    return tonumber(active or 0) or 0
end

function minigames.VehicleTracking.GetClearedCount()
    minigames.VehicleTracking.Ensure()

    -- if the old soft cleanup reports missing vehicles but did not call markcleared,
    -- surface that as cleared/missing visibility for the hud.
    local explicit = tonumber(minigames.S.vehiclesCleared or minigames.S.vehicleClearedCount or minigames.S.totalVehiclesCleared or 0) or 0
    local missing = tonumber(minigames.S.lastVehicleTrackingMissing or 0) or 0
    local cleanupDeleted = tonumber(minigames.S.cleanupDeletedCount or minigames.S.pedwarsCleanupDeleted or 0) or 0

    return math.max(explicit, cleanupDeleted, missing)
end

function minigames.VehicleTracking.SyncHudStats(reason)
    local active, raw, live, missing = minigames.VehicleTracking.GetBestRawTrackedCount()
    local cleared = minigames.VehicleTracking.GetClearedCount()

    minigames.S.hudVehiclesCount = active
    minigames.S.hudClearedVehiclesCount = cleared
    minigames.S.vehiclesTrackedHud = active
    minigames.S.vehiclesClearedHud = cleared
    minigames.S.lastVehicleTrackingStatus =
        "active=" .. tostring(active) ..
        " raw=" .. tostring(raw) ..
        " live=" .. tostring(live) ..
        " missing=" .. tostring(missing) ..
        " cleared=" .. tostring(cleared) ..
        " reason=" .. tostring(reason or "sync")

    return active, cleared
end

local __mg128_old_track_vehicle = minigames.VehicleTracking.TrackVehicle
function minigames.VehicleTracking.TrackVehicle(entity, playerId, vehicleLabel, reason, method)
    local id, status = __mg128_old_track_vehicle(entity, playerId, vehicleLabel, reason, method)
    minigames.VehicleTracking.SyncHudStats("track_vehicle")
    return id, status
end

local __mg128_old_mark_cleared = minigames.VehicleTracking.MarkCleared
function minigames.VehicleTracking.MarkCleared(idOrEntity, reason)
    local ok, status = __mg128_old_mark_cleared(idOrEntity, reason)
    minigames.VehicleTracking.SyncHudStats("mark_cleared")
    return ok, status
end

function minigames.VehicleTracking.Status()
    local active, cleared = minigames.VehicleTracking.SyncHudStats("status")
    local msg = "Vehicles=" .. tostring(active) .. " | Cleared=" .. tostring(cleared)
    minigames.VehicleTracking.Log("status | " .. msg .. " | " .. tostring(minigames.S.lastVehicleTrackingStatus or ""))
    if minigames.Toast then minigames.Toast("Vehicle Tracking", msg, 5000) end
    return msg
end

