------------------------------------------------------------
local __mg129_old_sync_hud_stats = minigames.VehicleTracking.SyncHudStats
function minigames.VehicleTracking.SyncHudStats(reason)
    if minigames.CountWarGamesTrackedVehicleTables then
        local active, cleared = minigames.CountWarGamesTrackedVehicleTables()
        minigames.S.hudVehiclesCount = active
        minigames.S.hudClearedVehiclesCount = cleared
        return active, cleared
    end

    if __mg129_old_sync_hud_stats then
        return __mg129_old_sync_hud_stats(reason)
    end

    return 0, 0
end

minigames.VehicleTracking.Log("v0.129 spawnedWarGamesVehicles HUD table hotfix active")


------------------------------------------------------------
-- v0.130 tracked wargames vehicle clear system
------------------------------------------------------------
-- clears only vehicles the wargames tracker knows about, especially
-- mg.s.spawnedwargamesvehicles, which is the table that powers the hud count.
------------------------------------------------------------

function minigames.VehicleTracking.GetTrackedWarGamesVehicleRecords()
    local S = minigames.S or {}
    local WG = minigames.WarGames or {}
    local WGS = WG.S or {}

    return {
        S.spawnedWarGamesVehicles,
        S.spawnedWarGamesVehicleRecords,
        S.trackedWarGamesVehicles,
        S.warGamesTrackedVehicles,
        S.wargamesTrackedVehicles,
        S.vehicleTrackingById,
        S.trackedVehicles,
        WG.spawnedWarGamesVehicles,
        WG.spawnedVehicles,
        WG.trackedVehicles,
        WGS.spawnedWarGamesVehicles,
        WGS.spawnedVehicles,
        WGS.trackedVehicles,
    }
end

function minigames.VehicleTracking.GetEntityFromRecord(record)
    if type(record) == "number" then
        return record
    end

    if type(record) == "table" then
        return record.entity or record.handle or record.vehicle or record.veh or record.vehicleHandle
    end

    return nil
end

function minigames.VehicleTracking.SetRecordCleared(record, reason)
    if type(record) == "table" then
        record.deleted = true
        record.cleared = true
        record.clearReason = tostring(reason or "v0.130_clear")
        record.clearedMs = minigames.VehicleTracking.Now and minigames.VehicleTracking.Now() or 0
    end
end

function minigames.VehicleTracking.SafeDeleteEntity(entity)
    if entity == nil or entity == 0 then
        return false, "empty_entity"
    end

    local exists = true
    if ENTITY and ENTITY.DOES_ENTITY_EXIST then
        local okExists, result = direct_call(function()
            return ENTITY.DOES_ENTITY_EXIST(entity)
        end)
        exists = okExists and result == true
    end

    if not exists then
        return true, "already_missing"
    end

    -- prefer pointer-style delete_entity where available.
    if ENTITY and ENTITY.DELETE_ENTITY and Memory and Memory.AllocInt and Memory.WriteInt then
        local ok, err = direct_call(function()
            local ptr = Memory.AllocInt()
            Memory.WriteInt(ptr, entity)
            ENTITY.DELETE_ENTITY(ptr)
        end)
        if ok then
            return true, "delete_entity_ptr"
        end
        return false, "delete_entity_ptr_failed:" .. tostring(err)
    end

    -- fallbacks for alternate lua apis.
    if entities and entities.delete_by_handle then
        local ok, err = direct_call(function()
            entities.delete_by_handle(entity)
        end)
        if ok then
            return true, "entities_delete_by_handle"
        end
        return false, "entities_delete_failed:" .. tostring(err)
    end

    if ENTITY and ENTITY.SET_ENTITY_AS_NO_LONGER_NEEDED then
        local ok, err = direct_call(function()
            ENTITY.SET_ENTITY_AS_NO_LONGER_NEEDED(entity)
        end)
        if ok then
            return true, "set_no_longer_needed"
        end
        return false, "no_longer_needed_failed:" .. tostring(err)
    end

    return false, "no_delete_method"
end

function minigames.VehicleTracking.ClearTrackedWarGamesVehicles(reason, onlyMissing)
    minigames.VehicleTracking.Ensure()

    local attempted = 0
    local deleted = 0
    local failed = 0
    local alreadyMissing = 0
    local marked = 0
    local seenEntities = {}

    for _, tbl in ipairs(minigames.VehicleTracking.GetTrackedWarGamesVehicleRecords()) do
        if type(tbl) == "table" then
            for _, record in pairs(tbl) do
                local entity = minigames.VehicleTracking.GetEntityFromRecord(record)

                if entity ~= nil and entity ~= 0 and not seenEntities[tostring(entity)] then
                    seenEntities[tostring(entity)] = true
                    attempted = attempted + 1

                    local shouldDelete = true
                    if onlyMissing == true and ENTITY and ENTITY.DOES_ENTITY_EXIST then
                        local okExists, exists = direct_call(function()
                            return ENTITY.DOES_ENTITY_EXIST(entity)
                        end)
                        shouldDelete = not (okExists and exists == true)
                    end

                    if shouldDelete then
                        local ok, status = minigames.VehicleTracking.SafeDeleteEntity(entity)
                        if ok then
                            if status == "already_missing" then
                                alreadyMissing = alreadyMissing + 1
                            else
                                deleted = deleted + 1
                            end

                            minigames.VehicleTracking.SetRecordCleared(record, reason or status)
                            marked = marked + 1
                        else
                            failed = failed + 1
                            if minigames.LogInfo then
                                minigames.LogInfo("[WarGames Vehicle Clear] failed entity=" .. tostring(entity) .. " | status=" .. tostring(status))
                            end
                        end
                    end
                elseif type(record) == "table" and record.deleted ~= true and record.cleared ~= true then
                    -- no entity handle, but still mark as cleared if it is a stale record.
                    if onlyMissing ~= true then
                        minigames.VehicleTracking.SetRecordCleared(record, reason or "no_entity_record")
                        marked = marked + 1
                    end
                end
            end
        end
    end

    local totalCleared = deleted + alreadyMissing + marked
    if totalCleared > 0 then
        minigames.S.vehiclesCleared = (tonumber(minigames.S.vehiclesCleared or 0) or 0) + totalCleared
        minigames.S.vehicleClearedCount = minigames.S.vehiclesCleared
        minigames.S.totalVehiclesCleared = minigames.S.vehiclesCleared
    end

    if minigames.CountWarGamesTrackedVehicleTables then
        minigames.CountWarGamesTrackedVehicleTables()
    end

    local msg =
        "attempted=" .. tostring(attempted) ..
        " deleted=" .. tostring(deleted) ..
        " alreadyMissing=" .. tostring(alreadyMissing) ..
        " marked=" .. tostring(marked) ..
        " failed=" .. tostring(failed) ..
        " clearedTotal=" .. tostring(minigames.S.vehiclesCleared or 0)

    if minigames.LogInfo then
        minigames.LogInfo("[WarGames Vehicle Clear] " .. msg .. " | reason=" .. tostring(reason or "manual"))
    end

    if minigames.Toast then
        minigames.Toast("WarGames Vehicle Clear", msg, 6000)
    end

    return msg
end

function minigames.VehicleTracking.ClearMissingTrackedWarGamesVehicles(reason)
    return minigames.VehicleTracking.ClearTrackedWarGamesVehicles(reason or "missing_only", true)
end

function minigames.VehicleTracking.ClearAllTrackedWarGamesVehicles(reason)
    return minigames.VehicleTracking.ClearTrackedWarGamesVehicles(reason or "manual_clear_all", false)
end

minigames.VehicleTracking.Log("v0.130 tracked clear system active")


------------------------------------------------------------
-- v0.134 tracked vehicle cleanup engine
------------------------------------------------------------
-- deletes only tracked wargames vehicles.
-- rule:
--   if destroyed -> delete / mark cleared.
--   if nobody is inside -> delete / mark cleared.
--   if a player is inside -> keep.
------------------------------------------------------------

function minigames.VehicleTracking.GetCleanupNow()
    if minigames.Now then return minigames.Now() end
    if os and os.clock then return math.floor(os.clock() * 1000) end
    return 0
end

function minigames.VehicleTracking.GetAllTrackedVehicleRecordsV134()
    local S = minigames.S or {}
    local WG = minigames.WarGames or {}
    local WGS = WG.S or {}

    return {
        S.spawnedWarGamesVehicles,
        S.spawnedWarGamesVehicleRecords,
        S.trackedWarGamesVehicles,
        S.warGamesTrackedVehicles,
        S.wargamesTrackedVehicles,
        S.vehicleTrackingById,
        S.trackedVehicles,
        WG.spawnedWarGamesVehicles,
        WG.spawnedVehicles,
        WG.trackedVehicles,
        WGS.spawnedWarGamesVehicles,
        WGS.spawnedVehicles,
        WGS.trackedVehicles,
    }
end

function minigames.VehicleTracking.GetRecordEntityV134(record)
    if type(record) == "number" then
        return record
    end

    if type(record) == "table" then
        return record.entity or record.handle or record.vehicle or record.veh or record.vehicleHandle
    end

    return nil
end

function minigames.VehicleTracking.EntityExistsV134(entity)
    if entity == nil or entity == 0 then return false end

    if ENTITY and ENTITY.DOES_ENTITY_EXIST then
        local ok, exists = direct_call(function()
            return ENTITY.DOES_ENTITY_EXIST(entity)
        end)
        return ok and exists == true
    end

    return true
end

function minigames.VehicleTracking.IsVehicleDestroyedV134(entity)
    if not minigames.VehicleTracking.EntityExistsV134(entity) then
        return true, "missing"
    end

    if ENTITY and ENTITY.IS_ENTITY_DEAD then
        local ok, dead = direct_call(function()
            return ENTITY.IS_ENTITY_DEAD(entity, false)
        end)
        if ok and dead == true then
            return true, "entity_dead"
        end
    end

    if VEHICLE and VEHICLE.IS_VEHICLE_DRIVEABLE then
        local ok, driveable = direct_call(function()
            return VEHICLE.IS_VEHICLE_DRIVEABLE(entity, false)
        end)
        if ok and driveable == false then
            return true, "not_driveable"
        end
    end

    if VEHICLE and VEHICLE.GET_VEHICLE_ENGINE_HEALTH then
        local ok, health = direct_call(function()
            return VEHICLE.GET_VEHICLE_ENGINE_HEALTH(entity)
        end)
        if ok and tonumber(health) and tonumber(health) <= -3500 then
            return true, "engine_destroyed"
        end
    end

    return false, "alive"
end

function minigames.VehicleTracking.GetActivePlayersV134()
    if minigames.S and type(minigames.S.activePlayers) == "table" and #minigames.S.activePlayers > 0 then
        return minigames.S.activePlayers
    end

    if minigames.GetActivePlayers then
        local ok, list = direct_call(minigames.GetActivePlayers)
        if ok and type(list) == "table" then
            return list
        end
    end

    local fallback = {}
    for i = 0, 31 do
        if PLAYER and PLAYER.GET_PLAYER_NAME then
            local ok, name = direct_call(function()
                return PLAYER.GET_PLAYER_NAME(i)
            end)
            if ok and name and tostring(name) ~= "**Invalid**" and tostring(name) ~= "" then
                table.insert(fallback, i)
            end
        end
    end

    return fallback
end

function minigames.VehicleTracking.GetPlayerPedV134(playerId)
    if minigames.GetPlayerPed then
        local ok, ped = direct_call(minigames.GetPlayerPed, playerId)
        if ok then return ped end
    end

    if PLAYER and PLAYER.GET_PLAYER_PED then
        local ok, ped = direct_call(function()
            return PLAYER.GET_PLAYER_PED(playerId)
        end)
        if ok then return ped end
    end

    return 0
end

function minigames.VehicleTracking.IsAnyPlayerInsideVehicleV134(entity)
    if entity == nil or entity == 0 then
        return false, nil
    end

    for _, playerId in ipairs(minigames.VehicleTracking.GetActivePlayersV134()) do
        local ped = minigames.VehicleTracking.GetPlayerPedV134(playerId)

        if ped and ped ~= 0 then
            if PED and PED.IS_PED_IN_VEHICLE then
                local ok, inside = direct_call(function()
                    return PED.IS_PED_IN_VEHICLE(ped, entity, false)
                end)
                if ok and inside == true then
                    return true, playerId
                end
            end

            if PED and PED.GET_VEHICLE_PED_IS_IN then
                local ok, veh = direct_call(function()
                    return PED.GET_VEHICLE_PED_IS_IN(ped, false)
                end)
                if ok and veh == entity then
                    return true, playerId
                end
            end
        end
    end

    return false, nil
end

function minigames.VehicleTracking.SafeDeleteTrackedEntityV134(entity)
    if entity == nil or entity == 0 then
        return false, "empty_entity"
    end

    if not minigames.VehicleTracking.EntityExistsV134(entity) then
        return true, "already_missing"
    end

    -- pointer delete first. this is the most common safe native pattern in cherax lua.
    if ENTITY and ENTITY.DELETE_ENTITY and Memory and Memory.AllocInt and Memory.WriteInt then
        local ok, err = direct_call(function()
            local ptr = Memory.AllocInt()
            Memory.WriteInt(ptr, entity)
            ENTITY.DELETE_ENTITY(ptr)
        end)

        if ok then
            return true, "delete_entity_ptr"
        end

        return false, "delete_entity_ptr_failed:" .. tostring(err)
    end

    if entities and entities.delete_by_handle then
        local ok, err = direct_call(function()
            entities.delete_by_handle(entity)
        end)

        if ok then
            return true, "entities_delete_by_handle"
        end

        return false, "entities_delete_failed:" .. tostring(err)
    end

    if ENTITY and ENTITY.SET_ENTITY_AS_NO_LONGER_NEEDED then
        local ok, err = direct_call(function()
            ENTITY.SET_ENTITY_AS_NO_LONGER_NEEDED(entity)
        end)

        if ok then
            return true, "set_no_longer_needed"
        end

        return false, "set_no_longer_needed_failed:" .. tostring(err)
    end

    return false, "no_delete_method"
end

function minigames.VehicleTracking.MarkRecordClearedV134(record, reason)
    if type(record) == "table" then
        record.deleted = true
        record.cleared = true
        record.clearReason = tostring(reason or "tracked_cleanup")
        record.clearedMs = minigames.VehicleTracking.GetCleanupNow()
    end
end

function minigames.VehicleTracking.CleanupTrackedVehiclesV134(reason, manual)
    minigames.VehicleTracking.Ensure()

    local attempted = 0
    local deleted = 0
    local alreadyMissing = 0
    local keptOccupied = 0
    local destroyed = 0
    local empty = 0
    local failed = 0
    local marked = 0
    local seen = {}

    for _, tbl in ipairs(minigames.VehicleTracking.GetAllTrackedVehicleRecordsV134()) do
        if type(tbl) == "table" then
            for _, record in pairs(tbl) do
                local entity = minigames.VehicleTracking.GetRecordEntityV134(record)

                if entity ~= nil and entity ~= 0 and not seen[tostring(entity)] then
                    seen[tostring(entity)] = true
                    attempted = attempted + 1

                    local isDestroyed, destroyedReason = minigames.VehicleTracking.IsVehicleDestroyedV134(entity)
                    local occupied, occupiedBy = minigames.VehicleTracking.IsAnyPlayerInsideVehicleV134(entity)

                    local shouldDelete = false
                    local deleteReason = "unknown"

                    if isDestroyed == true then
                        shouldDelete = true
                        deleteReason = destroyedReason or "destroyed"
                        destroyed = destroyed + 1
                    elseif occupied == false then
                        shouldDelete = true
                        deleteReason = "empty_unoccupied"
                        empty = empty + 1
                    else
                        keptOccupied = keptOccupied + 1
                    end

                    if shouldDelete == true then
                        local ok, status = minigames.VehicleTracking.SafeDeleteTrackedEntityV134(entity)

                        if ok == true then
                            if status == "already_missing" then
                                alreadyMissing = alreadyMissing + 1
                            else
                                deleted = deleted + 1
                            end

                            minigames.VehicleTracking.MarkRecordClearedV134(record, deleteReason .. ":" .. tostring(status))
                            marked = marked + 1
                        else
                            failed = failed + 1
                            if minigames.LogInfo then
                                minigames.LogInfo("[Tracked Vehicle Cleanup] failed entity=" .. tostring(entity) .. " | status=" .. tostring(status))
                            end
                        end
                    end
                elseif type(record) == "table" and record.deleted ~= true and record.cleared ~= true then
                    -- stale record with no handle. mark it so hud does not keep showing it.
                    minigames.VehicleTracking.MarkRecordClearedV134(record, "stale_no_entity")
                    marked = marked + 1
                end
            end
        end
    end

    local clearIncrement = deleted + alreadyMissing + marked
    if clearIncrement > 0 then
        minigames.S.vehiclesCleared = (tonumber(minigames.S.vehiclesCleared or 0) or 0) + clearIncrement
        minigames.S.vehicleClearedCount = minigames.S.vehiclesCleared
        minigames.S.totalVehiclesCleared = minigames.S.vehiclesCleared
    end

    if minigames.CountWarGamesTrackedVehicleTables then
        minigames.CountWarGamesTrackedVehicleTables()
    end

    local active = minigames.GetTrackedVehicleCount and minigames.GetTrackedVehicleCount() or 0
    local cleared = minigames.GetClearedVehicleCount and minigames.GetClearedVehicleCount() or (minigames.S.vehiclesCleared or 0)

    local msg =
        "attempted=" .. tostring(attempted) ..
        " deleted=" .. tostring(deleted) ..
        " alreadyMissing=" .. tostring(alreadyMissing) ..
        " destroyed=" .. tostring(destroyed) ..
        " empty=" .. tostring(empty) ..
        " keptOccupied=" .. tostring(keptOccupied) ..
        " failed=" .. tostring(failed) ..
        " active=" .. tostring(active) ..
        " cleared=" .. tostring(cleared)

    minigames.S.lastTrackedVehicleCleanupStatus = msg

    if minigames.RoutineLogInfoV171 then
        minigames.RoutineLogInfoV171(
            "[Tracked Vehicle Cleanup] " .. msg ..
            " | reason=" .. tostring(reason or "manual")
        )
    end

    if manual == true then
        if minigames.RoutineToastV171 then
            minigames.RoutineToastV171(
                "Tracked Vehicle Cleanup",
                msg,
                6500
            )
        elseif minigames.Toast then
            minigames.Toast("Tracked Vehicle Cleanup", msg, 6500)
        end
    end

    return msg
end

function minigames.VehicleTracking.CleanupTrackedVehiclesNowV134()
    return minigames.VehicleTracking.CleanupTrackedVehiclesV134("manual_button", true)
end

function minigames.VehicleTracking.ToggleAutoTrackedCleanupV134(enabled)
    minigames.S.autoTrackedVehicleCleanup = enabled == true
    minigames.S.trackedVehicleCleanupEnabled = enabled == true
    minigames.S.lastTrackedVehicleCleanupStatus = "Auto tracked cleanup " .. (enabled and "ON" or "OFF")

    if minigames.LogInfo then
        minigames.LogInfo("[Tracked Vehicle Cleanup] " .. minigames.S.lastTrackedVehicleCleanupStatus)
    end
end

function minigames.VehicleTracking.TickTrackedCleanupV134()
    if minigames.S.autoTrackedVehicleCleanup ~= true then
        return
    end

    local now = minigames.VehicleTracking.GetCleanupNow()
    local interval = tonumber(minigames.S.trackedVehicleCleanupIntervalMs or 180000) or 180000
    local last = tonumber(minigames.S.lastTrackedVehicleCleanupMs or 0) or 0

    if last ~= 0 and now - last < interval then
        return
    end

    minigames.S.lastTrackedVehicleCleanupMs = now
    minigames.VehicleTracking.CleanupTrackedVehiclesV134("auto_tick", false)
end

minigames.VehicleTracking.Log("v0.134 tracked cleanup engine active")


------------------------------------------------------------
-- v0.135 auto cleanup interval hardening
------------------------------------------------------------
-- auto cleanup runs every 3 minutes by default.
-- manual cleanup button still runs immediately.
function minigames.VehicleTracking.GetTrackedCleanupIntervalV135()
    local interval = tonumber(minigames.S.trackedVehicleCleanupIntervalMs or 180000) or 180000

    -- keep auto cleanup from running too aggressively.
    if interval < 180000 then
        interval = 180000
    end

    return interval
end

local __mg135_old_tick_tracked_cleanup = minigames.VehicleTracking.TickTrackedCleanupV134
function minigames.VehicleTracking.TickTrackedCleanupV134()
    if minigames.S.autoTrackedVehicleCleanup ~= true then
        return
    end

    local now = minigames.VehicleTracking.GetCleanupNow and minigames.VehicleTracking.GetCleanupNow() or (minigames.Now and minigames.Now() or 0)
    local interval = minigames.VehicleTracking.GetTrackedCleanupIntervalV135()
    local last = tonumber(minigames.S.lastTrackedVehicleCleanupMs or 0) or 0

    if last ~= 0 and now - last < interval then
        return
    end

    minigames.S.lastTrackedVehicleCleanupMs = now
    minigames.VehicleTracking.CleanupTrackedVehiclesV134("auto_3_minute_tick", false)
end

minigames.VehicleTracking.Log("v0.135 auto cleanup interval set to 180000ms / 3 minutes")


------------------------------------------------------------
-- v0.136 short cleanup notifications
------------------------------------------------------------
function minigames.VehicleTracking.NotifyCleanupV136(deleted, alreadyMissing, destroyed, empty, keptOccupied, cleared, reason)
    if minigames.S.notifyTrackedVehicleCleanup == false then
        return
    end

    local removed = (tonumber(deleted or 0) or 0) + (tonumber(alreadyMissing or 0) or 0)
    local markedCleared = tonumber(cleared or 0) or 0

    if minigames.S.notifyTrackedVehicleCleanupOnlyWhenDeleted ~= false and removed <= 0 and markedCleared <= 0 then
        return
    end

    local msg =
        "Removed " .. tostring(removed) ..
        " | Empty " .. tostring(empty or 0) ..
        " | Destroyed " .. tostring(destroyed or 0) ..
        " | Kept " .. tostring(keptOccupied or 0)

    if minigames.RoutineToastV171 then
        minigames.RoutineToastV171(
            "Tracked Cleanup",
            msg,
            4500
        )
    elseif minigames.Toast then
        minigames.Toast("Tracked Cleanup", msg, 4500)
    end

    if minigames.RoutineLogInfoV171 then
        minigames.RoutineLogInfoV171(
            "[Tracked Vehicle Cleanup Notify] " .. msg ..
            " | reason=" .. tostring(reason or "cleanup")
        )
    end
end

local __mg136_old_cleanup_tracked_vehicles = minigames.VehicleTracking.CleanupTrackedVehiclesV134
if __mg136_old_cleanup_tracked_vehicles then
    function minigames.VehicleTracking.CleanupTrackedVehiclesV134(reason, manual)
        local beforeCleared = tonumber(minigames.S.vehiclesCleared or minigames.S.vehicleClearedCount or minigames.S.totalVehiclesCleared or 0) or 0
        local result = __mg136_old_cleanup_tracked_vehicles(reason, manual)
        local afterCleared = tonumber(minigames.S.vehiclesCleared or minigames.S.vehicleClearedCount or minigames.S.totalVehiclesCleared or 0) or 0
        local delta = afterCleared - beforeCleared

        -- parse the cleanup result text for a nicer notification.
        local deleted = tonumber(tostring(result or ""):match("deleted=(%d+)") or 0) or 0
        local alreadyMissing = tonumber(tostring(result or ""):match("alreadyMissing=(%d+)") or 0) or 0
        local destroyed = tonumber(tostring(result or ""):match("destroyed=(%d+)") or 0) or 0
        local empty = tonumber(tostring(result or ""):match("empty=(%d+)") or 0) or 0
        local keptOccupied = tonumber(tostring(result or ""):match("keptOccupied=(%d+)") or 0) or 0

        if delta > 0 or deleted > 0 or alreadyMissing > 0 then
            minigames.VehicleTracking.NotifyCleanupV136(deleted, alreadyMissing, destroyed, empty, keptOccupied, delta, reason)
        end

        return result
    end
end
end

