-- embedded module: systems\wargames_force_bounty_60s.lua
-- ============================================================
embedded_modules['systems\\wargames_force_bounty_60s.lua'] = function()
-- minigames/systems/wargames_force_bounty_60s.lua
-- v0.171-alpha
--
-- uses the exact working manual action:
--     mg.wargames.applybountytoall(true)
--
-- it runs immediately when enabled, then once every 60 seconds.

minigames.WarGames = minigames.WarGames or {}
minigames.WarGames.Bounty = minigames.WarGames.Bounty or {}

minigames.WarGames.Bounty.IntervalMs = 60000
minigames.S.autoBountyIntervalMs = 60000
minigames.S.bountyIntervalMs = 60000
minigames.S.autoBountyMaintainIntervalMs = 60000
minigames.S.bountyMaintenanceIntervalMs = 60000
minigames.S.forceAutoBountyReapply = true
minigames.S.autoBountyOnlyUntracked = false

function minigames.WarGames.IsForceBountyMaintainEnabledV159()
    if minigames.S.wargamesNoBountyMode == true then
        return false
    end

    return
        minigames.S.autoForceBountyMaintainEnabledV159 == true or
        minigames.S.autoBountyRunning == true or
        minigames.S.autoBountyEnabled == true
end

function minigames.WarGames.RunForceBountyMaintainNowV159(reason)
    reason = tostring(reason or "Auto Force Maintain 60s")

    if minigames.S.wargamesNoBountyMode == true then
        return false, "no_bounty_mode"
    end

    local now = minigames.Now and minigames.Now() or 0
    local lastStart =
        tonumber(minigames.S.lastForceBountyMaintainStartMsV159 or 0) or 0

    -- prevent duplicate jobs if multiple final scheduler wrappers call the tick
    -- in the same frame.
    if minigames.S.forceBountyMaintainJobActiveV159 == true and
        now - lastStart < 15000 then
        return false, "job_already_active"
    end

    minigames.S.forceBountyMaintainJobActiveV159 = true
    minigames.S.lastForceBountyMaintainStartMsV159 = now
    minigames.S.lastAutoBountyTickMs = now
    minigames.S.autoBountyTickCount =
        (minigames.S.autoBountyTickCount or 0) + 1

    if minigames.WarGames.BountyLog then
        minigames.WarGames.BountyLog(
            "Force-maintain tick #" ..
            tostring(minigames.S.autoBountyTickCount) ..
            " | method=ApplyBountyToAll(true)" ..
            " | interval=60s" ..
            " | reason=" .. reason
        )
    end

    local ok, err = direct_call(function()
        -- this is the exact same function used by:
        -- test: force bounties to all
        minigames.WarGames.ApplyBountyToAll(true)
    end)

    minigames.S.forceBountyMaintainJobActiveV159 = false

    if not ok then
        minigames.S.lastBountyStatus =
            "Auto Force Bounty failed: " .. tostring(err)

        if minigames.LogError then
            minigames.LogError(
                "[WarGames Bounty] " ..
                minigames.S.lastBountyStatus
            )
        end

        return false, tostring(err)
    end

    minigames.S.lastBountyStatus =
        "Auto Force Bounties To All queued" ..
        " | tick=" .. tostring(minigames.S.autoBountyTickCount) ..
        " | interval=60s"

    return true, "force_all_queued"
end

-- final override of every older 180-second autobountytick implementation.
function minigames.WarGames.AutoBountyTick()
    if not minigames.WarGames.IsForceBountyMaintainEnabledV159() then
        return false, "disabled"
    end

    local now = minigames.Now and minigames.Now() or 0
    local lastTick =
        tonumber(minigames.S.lastAutoBountyTickMs or 0) or 0

    if lastTick ~= 0 and now - lastTick < 60000 then
        return false, "waiting"
    end

    return minigames.WarGames.RunForceBountyMaintainNowV159(
        "60-second scheduler"
    )
end

-- install the final scheduler wrapper after startup and protection guard.
if minigames.Scheduler and minigames.Scheduler.Tick and
    minigames.__v159ForceBountySchedulerHook ~= true then
    minigames.__v159ForceBountySchedulerHook = true
    local oldSchedulerTickV159 = minigames.Scheduler.Tick

    function minigames.Scheduler.Tick(...)
        local result = oldSchedulerTickV159(...)

        if minigames.WarGames.IsForceBountyMaintainEnabledV159() then
            local ok, err =
                direct_call(minigames.WarGames.AutoBountyTick)

            if not ok and minigames.LogError then
                minigames.LogError(
                    "[WarGames Bounty] Final 60s scheduler error: " ..
                    tostring(err)
                )
            end
        end

        return result
    end
end

if minigames.LogInfo then
    minigames.LogInfo(
        "[WarGames Bounty] v0.159 loaded LAST" ..
        " | method=Force Bounties To All" ..
        " | interval=60000ms"
    )
end
end

