-- ============================================================
embedded_modules['systems\\weapons.lua'] = function()
--[[
    minigames/systems/weapons.lua
    shared weapon control for wargames.

    v0.056:
    - manual remove all weapons from all detected players.
    - auto remove restricted weapons from all detected players.
    - restricted list targets rpg, homing launcher, snipers, minigun-style weapons, launchers, etc.
]]

minigames.RestrictedWeapons = {
    "WEAPON_RPG",
    "WEAPON_HOMINGLAUNCHER",
    "WEAPON_GRENADELAUNCHER",
    "WEAPON_COMPACTLAUNCHER",
    "WEAPON_FIREWORK",
    "WEAPON_RAILGUN",
    "WEAPON_RAILGUNXM3",
    "WEAPON_EMPLAUNCHER",

    "WEAPON_SNIPERRIFLE",
    "WEAPON_HEAVYSNIPER",
    "WEAPON_HEAVYSNIPER_MK2",
    "WEAPON_MARKSMANRIFLE",
    "WEAPON_MARKSMANRIFLE_MK2",
    "WEAPON_PRECISIONRIFLE",

    "WEAPON_MINIGUN",
    "WEAPON_RAYMINIGUN",
    "WEAPON_COMBATMG",
    "WEAPON_COMBATMG_MK2",
    "WEAPON_GUSENBERG",

    "WEAPON_GRENADE",
    "WEAPON_STICKYBOMB",
    "WEAPON_PIPEBOMB",
    "WEAPON_PROXMINE"
}

function minigames.GetWeaponHash(name)
    if Utils and Utils.Joaat then
        local ok, hash = direct_call(function()
            return Utils.Joaat(name)
        end)

        if ok and hash then
            return hash
        end
    end

    return 0
end

function minigames.RemoveRestrictedWeaponsFromPlayer(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)

    local ped = minigames.GetPlayerPed(playerId)

    if not ped or ped == 0 or not minigames.EntityExists(ped) then
        return 0, "ped_missing"
    end

    if not WEAPON or not WEAPON.REMOVE_WEAPON_FROM_PED then
        return 0, "weapon_native_missing"
    end

    local removed = 0

    for _, weaponName in ipairs(minigames.RestrictedWeapons or {}) do
        local weaponHash = minigames.GetWeaponHash(weaponName)

        if weaponHash ~= 0 then
            local ok = direct_call(function()
                WEAPON.REMOVE_WEAPON_FROM_PED(ped, weaponHash)
            end)

            if ok then
                removed = removed + 1
            end
        end
    end

    return removed, "ok"
end

function minigames.RemoveAllWeaponsFromPlayer(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)

    local ped = minigames.GetPlayerPed(playerId)

    if not ped or ped == 0 or not minigames.EntityExists(ped) then
        return false, "ped_missing"
    end

    if not WEAPON or not WEAPON.REMOVE_ALL_PED_WEAPONS then
        return false, "weapon_native_missing"
    end

    local ok, err = direct_call(function()
        WEAPON.REMOVE_ALL_PED_WEAPONS(ped, true)
    end)

    if ok then
        return true, "ok"
    end

    return false, tostring(err)
end

function minigames.RemoveRestrictedWeaponsFromAllPlayers(reason)
    minigames.RefreshPlayers()

    local players = 0
    local removeCalls = 0
    local failed = 0

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        local removed, status = minigames.RemoveRestrictedWeaponsFromPlayer(playerId)

        if status == "ok" then
            players = players + 1
            removeCalls = removeCalls + removed
        else
            failed = failed + 1
        end
        -- v0.061: no yielding inside cherax feature/tick fibers.
    end

    minigames.S.lastWeaponCleanupRemoved = removeCalls
    minigames.S.lastWeaponCleanupStatus =
        "Restricted cleanup | players=" ..
        tostring(players) ..
        " removeCalls=" ..
        tostring(removeCalls) ..
        " failed=" ..
        tostring(failed) ..
        " reason=" ..
        tostring(reason or "Manual")

    minigames.LogInfo("[WarGames Weapons] " .. minigames.S.lastWeaponCleanupStatus)

    return players, removeCalls, failed
end

function minigames.RemoveAllWeaponsFromAllPlayers(reason)
    minigames.RefreshPlayers()

    local removedPlayers = 0
    local failed = 0

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        local ok, status = minigames.RemoveAllWeaponsFromPlayer(playerId)

        if ok then
            removedPlayers = removedPlayers + 1
        else
            failed = failed + 1
            minigames.LogInfo("[WarGames Weapons] Remove all failed | player=" .. tostring(playerId) .. " | " .. minigames.GetPlayerName(playerId) .. " | " .. tostring(status))
        end
        -- v0.061: no yielding inside cherax feature/tick fibers.
    end

    minigames.S.lastWeaponCleanupStatus =
        "Remove all weapons | players=" ..
        tostring(removedPlayers) ..
        " failed=" ..
        tostring(failed) ..
        " reason=" ..
        tostring(reason or "Manual")

    minigames.Toast("WarGames Weapons", minigames.S.lastWeaponCleanupStatus, 5000)
    minigames.LogInfo("[WarGames Weapons] " .. minigames.S.lastWeaponCleanupStatus)

    return removedPlayers, failed
end

function minigames.WeaponCleanupTick()
    -- v0.064 weapon gate
    if minigames.S.autoRemoveRestrictedWeapons ~= true then
        return
    end
    -- v0.062 weapon auto cleanup gate
    if minigames.S.autoRemoveRestrictedWeapons ~= true then
        return
    end

    if minigames.S.autoRemoveRestrictedWeapons ~= true and minigames.S.wargamesSystemsActive ~= true then
        return
    end

    local now = minigames.Now()
    local scanMs = minigames.S.weaponCleanupScanMs or 300000
    local last = minigames.S.lastWeaponCleanupScanMs or 0

    if last ~= 0 and now - last < scanMs then
        return
    end

    minigames.S.lastWeaponCleanupScanMs = now

    minigames.RemoveRestrictedWeaponsFromAllPlayers("Auto Restricted Weapon Cleanup")
end


------------------------------------------------------------
-- v0.117 safety guard
------------------------------------------------------------
-- these systems are intentionally off by default because live testing showed
-- respawn vehicles worked again after disabling them.
------------------------------------------------------------
end

