function minigames.RefreshConfig()
    minigames.S.selectedPlayerId = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.SELECTED_PLAYER_ID, minigames.S.selectedPlayerId or 0), 0, 31)
    minigames.S.selectedPlayerName = minigames.GetPlayerName(minigames.S.selectedPlayerId)

    minigames.S.rosterRefreshMs = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.ROSTER_REFRESH_MS, minigames.S.rosterRefreshMs or minigames.C.DEFAULT_ROSTER_REFRESH_MS), 1000, 30000)
    minigames.S.autoTrackNewPlayers = minigames.GetFeatureBool(minigames.H.AUTO_TRACK_NEW_PLAYERS, minigames.S.autoTrackNewPlayers == true)
    minigames.S.autoBountyNewPlayers = minigames.GetFeatureBool(minigames.H.AUTO_BOUNTY_NEW_PLAYERS, minigames.S.autoBountyNewPlayers == true)

    minigames.S.vehicleSpawnEngine = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.VEHICLE_SPAWN_ENGINE, minigames.S.vehicleSpawnEngine or minigames.C.VEHICLE_SPAWN_ENGINE_RAW_MODEL), 0, 2)
    minigames.S.vehicleMode = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.VEHICLE_MODE, minigames.S.vehicleMode or minigames.C.VEHICLE_MODE_SELECTED), 0, 3)
    minigames.S.spawnDistance = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.SPAWN_DISTANCE, minigames.S.spawnDistance or minigames.C.DEFAULT_SPAWN_DISTANCE), 1, 50)
    minigames.S.spawnZOffset = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.SPAWN_Z_OFFSET, minigames.S.spawnZOffset or minigames.C.DEFAULT_SPAWN_Z_OFFSET), -5, 20)
    minigames.S.spawnCooldownMs = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.SPAWN_COOLDOWN_MS, minigames.S.spawnCooldownMs or minigames.C.DEFAULT_SPAWN_COOLDOWN_MS), 0, 120000)
    minigames.S.skipSelfVehicle = minigames.GetFeatureBool(minigames.H.SKIP_SELF_VEHICLE, minigames.S.skipSelfVehicle == true)
    minigames.S.useVehicleTracking = minigames.GetFeatureBool(minigames.H.USE_VEHICLE_TRACKING, minigames.S.useVehicleTracking ~= false)
    minigames.S.maxUpgradeRawVehicles = minigames.GetFeatureBool(minigames.H.MAX_UPGRADE_RAW_VEHICLES, minigames.S.maxUpgradeRawVehicles ~= false)
    minigames.S.rawVehicleMatteBlack = minigames.GetFeatureBool(minigames.H.RAW_VEHICLE_MATTE_BLACK, minigames.S.rawVehicleMatteBlack ~= false)
    minigames.S.rawVehicleBlackWheels = minigames.GetFeatureBool(minigames.H.RAW_VEHICLE_BLACK_WHEELS, minigames.S.rawVehicleBlackWheels ~= false)

    minigames.S.skipSelfBounty = minigames.GetFeatureBool(minigames.H.SKIP_SELF_BOUNTY, minigames.S.skipSelfBounty == true)
    minigames.S.useBountyTracking = minigames.GetFeatureBool(minigames.H.USE_BOUNTY_TRACKING, minigames.S.useBountyTracking ~= false)
    minigames.S.autoBountyIntervalMs = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.AUTO_BOUNTY_INTERVAL_MS, minigames.S.autoBountyIntervalMs or minigames.C.DEFAULT_AUTO_BOUNTY_INTERVAL_MS), 5000, 300000)
    minigames.S.autoBountyOnlyUntracked = minigames.GetFeatureBool(minigames.H.AUTO_BOUNTY_ONLY_UNTRACKED, minigames.S.autoBountyOnlyUntracked ~= false)
    minigames.S.forceAutoBountyReapply = minigames.GetFeatureBool(minigames.H.FORCE_AUTO_BOUNTY_REAPPLY, minigames.S.forceAutoBountyReapply ~= false)

    minigames.S.respawnScanMs = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.RESPAWN_SCAN_MS, minigames.S.respawnScanMs or minigames.C.DEFAULT_RESPAWN_SCAN_MS), 100, 10000)
    minigames.S.respawnDelayMs = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.RESPAWN_DELAY_MS, minigames.S.respawnDelayMs or minigames.C.DEFAULT_RESPAWN_DELAY_MS), 0, 30000)
    minigames.S.respawnOnlyTracked = minigames.GetFeatureBool(minigames.H.RESPAWN_ONLY_TRACKED, minigames.S.respawnOnlyTracked ~= false)

    if minigames.H.WARGAMES_SELECTED_VEHICLE_INDEX and minigames.WarGames and minigames.WarGames.State then
        minigames.WarGames.State.selectedVehicleIndex = minigames.ClampInt(
            minigames.GetFeatureInt(minigames.H.WARGAMES_SELECTED_VEHICLE_INDEX, minigames.WarGames.State.selectedVehicleIndex or 1),
            1,
            #minigames.WarGames.VehiclePool
        )
    end
end

function minigames.DrawIntro()
    if not minigames.S.introEnabled or not minigames.S.nativeOK then return end

    local now = minigames.Now()
    if minigames.S.introStartMs == 0 then minigames.S.introStartMs = now end

    local elapsed = now - minigames.S.introStartMs
    if elapsed > minigames.S.introDurationMs then return end

    local alpha = 255
    if elapsed > minigames.S.introFadeStartMs then
        local fadeElapsed = elapsed - minigames.S.introFadeStartMs
        local fadeDuration = minigames.S.introDurationMs - minigames.S.introFadeStartMs
        alpha = math.floor(math.max(0, math.min(255, 255 * (1.0 - fadeElapsed / fadeDuration))))
    end

    local pulse = math.sin(now * 0.004) * 0.5 + 0.5
    local red = math.floor(190 + 65 * pulse)

    minigames.DrawRect(0.5, 0.415, 0.62, 0.205, 20, 0, 0, math.floor(alpha * 0.28))
    minigames.DrawRect(0.5, 0.505, 0.48, 0.006, red, 20, 20, math.floor(alpha * 0.80))
    -- v0.123 replaced by systems/intro_logo.lua
    minigames.DrawText(minigames.SUBTITLE, 0.5, 0.455, 0.46, 255, 245, 245, alpha, 4)
    minigames.DrawText("Bounties • Vehicles • Respawn Chaos", 0.5, 0.535, 0.30, 255, 120, 120, math.floor(alpha * 0.85), 4)
end

minigames.AddToggleOnTick(minigames.H.HUD_RENDERER, "Minigames HUD Renderer", "Internal startup intro renderer.", function(f)
    if f:IsToggled() then minigames.DrawIntro() end
end, true)

FeatureMgr.AddFeature(minigames.H.INTRO_TOGGLE, "Show Startup Intro", eFeatureType.Toggle, "Shows the MiniGames logo startup intro.", function(f)
    minigames.S.introEnabled = f:IsToggled()
    if minigames.S.introEnabled then minigames.S.introStartMs = minigames.Now() end
end):SetDefaultValue(true):Reset()

