local function MG124IntroIntDefault(value)
    return math.floor((tonumber(value) or 0) * 1000 + 0.5)
end

local function MG124AddIntroInput(hash, label, desc, defaultNorm, minNorm, maxNorm, stepNorm, fastStepNorm)
    FeatureMgr.AddFeature(hash, label, eFeatureType.InputInt, desc)
    :SetDefaultValue(MG124IntroIntDefault(defaultNorm))
    :SetLimitValues(MG124IntroIntDefault(minNorm), MG124IntroIntDefault(maxNorm))
    :SetStepSize(MG124IntroIntDefault(stepNorm))
    :SetFastStepSize(MG124IntroIntDefault(fastStepNorm))
    :Reset()
end

FeatureMgr.AddFeature(minigames.H.INTRO_START_TEST, "Start Intro", eFeatureType.Button, "Restarts the Minigames startup intro so you can test layout tuning.", function()
    minigames.S.introEnabled = true
    if minigames.IntroLogo and minigames.IntroLogo.StartIntro then
        minigames.IntroLogo.StartIntro("Settings > Test > Start Intro")
    elseif minigames.ResetIntro then
        minigames.ResetIntro()
    else
        minigames.S.introStartMs = minigames.Now and minigames.Now() or 0
    end
end)

