function minigames.RenderMainPage()
    if ClickGUI.BeginCustomChildWindow("LOBBYGAMES Status") then
        ClickGUI.RenderFeature(minigames.H.REFRESH_PLAYERS)
        ClickGUI.RenderFeature(minigames.H.PRINT_PLAYERS)
        ClickGUI.RenderFeature(minigames.H.PRINT_SYSTEM_DEBUG)
        ClickGUI.RenderFeature(minigames.H.CREDITS)

        if ImGui then
            ImGui.Text(minigames.TITLE .. " " .. minigames.VERSION)
            ImGui.Text(minigames.SUBTITLE)
            ImGui.Text("Players: " .. tostring(minigames.S.activePlayerCount))
            ImGui.Text("Discovery: " .. tostring(minigames.S.lastPlayerDiscoveryMethod))
            ImGui.Text("Selected Player: [" .. tostring(minigames.S.selectedPlayerId) .. "] " .. minigames.GetPlayerName(minigames.S.selectedPlayerId))
            ImGui.Text("WarGames Active: " .. tostring(minigames.S.wargamesSystemsActive))
            if minigames.LandOnIt and minigames.LandOnIt.S then ImGui.Text("Land On It Active: " .. tostring(minigames.LandOnIt.S.active)) end
            ImGui.Text("Auto Bounty Ticks: " .. tostring(minigames.S.autoBountyTickCount))
            ImGui.Text("Respawn Ticks: " .. tostring(minigames.S.respawnTickCount))
        end

        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.RenderPlayersPage()
    if ClickGUI.BeginCustomChildWindow("Player Selection") then
        ClickGUI.RenderFeature(minigames.H.SELECTED_PLAYER_ID)
        ClickGUI.RenderFeature(minigames.H.SELECT_PREVIOUS_PLAYER)
        ClickGUI.RenderFeature(minigames.H.SELECT_NEXT_PLAYER)
        ClickGUI.RenderFeature(minigames.H.REFRESH_PLAYERS)
        ClickGUI.RenderFeature(minigames.H.ROSTER_REFRESH_MS)
        ClickGUI.RenderFeature(minigames.H.AUTO_TRACK_NEW_PLAYERS)
        ClickGUI.RenderFeature(minigames.H.AUTO_BOUNTY_NEW_PLAYERS)
        ClickGUI.EndCustomChildWindow()
    end

    if ClickGUI.BeginCustomChildWindow("Detected Players") then
        minigames.EnsurePlayersFresh()

        if ImGui then
            for _, playerId in ipairs(minigames.S.activePlayers or {}) do
                ImGui.Text("[" .. tostring(playerId) .. "] " .. minigames.GetPlayerName(playerId) .. " | bounty=" .. tostring(minigames.Player.bountyApplied[playerId] == true) .. " | respawnVeh=" .. tostring(minigames.Player.vehicleEnabled[playerId] == true))
                if ImGui.Button("Select##select_" .. tostring(playerId)) then minigames.SelectPlayer(playerId) end
            end
        end

        ClickGUI.EndCustomChildWindow()
    end
end

