------------------------------------------------------------
-- ui tests inside hud settings
------------------------------------------------------------
-- v0.080:
-- these tests render directly inside the visible hud/settings area.
------------------------------------------------------------

minigames.UILab = minigames.UILab or {
    clickedFeature = 0,
    clickedToggle = 0,
    clickedImguiButton = 0,
    clickedSmallButton = 0,
    clickedSelectable = 0,
    clickedInvisible = 0,
    lastClicked = "None"
}

function minigames.UILabClick(method)
    minigames.UILab = minigames.UILab or {}
    minigames.UILab.lastClicked = tostring(method or "Unknown")

    if method == "Feature Button" then
        minigames.UILab.clickedFeature = (minigames.UILab.clickedFeature or 0) + 1
    elseif method == "Feature Toggle" then
        minigames.UILab.clickedToggle = (minigames.UILab.clickedToggle or 0) + 1
    elseif method == "ImGui.Button" then
        minigames.UILab.clickedImguiButton = (minigames.UILab.clickedImguiButton or 0) + 1
    elseif method == "ImGui.SmallButton" then
        minigames.UILab.clickedSmallButton = (minigames.UILab.clickedSmallButton or 0) + 1
    elseif method == "ImGui.Selectable" then
        minigames.UILab.clickedSelectable = (minigames.UILab.clickedSelectable or 0) + 1
    elseif method == "ImGui.InvisibleButton" then
        minigames.UILab.clickedInvisible = (minigames.UILab.clickedInvisible or 0) + 1
    end

    minigames.Toast("UI Test", "Clicked: " .. tostring(method), 2500)
    minigames.LogInfo("[UI Lab HUD Settings] CLICKED | method=" .. tostring(method))
end

function minigames.PrintUILabResults()
    minigames.LogInfo("========== UI Lab HUD Settings Results ==========")
    minigames.LogInfo("Feature Button: " .. tostring(minigames.UILab.clickedFeature or 0))
    minigames.LogInfo("Feature Toggle: " .. tostring(minigames.UILab.clickedToggle or 0))
    minigames.LogInfo("ImGui.Button: " .. tostring(minigames.UILab.clickedImguiButton or 0))
    minigames.LogInfo("ImGui.SmallButton: " .. tostring(minigames.UILab.clickedSmallButton or 0))
    minigames.LogInfo("ImGui.Selectable: " .. tostring(minigames.UILab.clickedSelectable or 0))
    minigames.LogInfo("ImGui.InvisibleButton: " .. tostring(minigames.UILab.clickedInvisible or 0))
    minigames.LogInfo("Last Clicked: " .. tostring(minigames.UILab.lastClicked or "None"))
    minigames.LogInfo("================================================")
    minigames.Toast("UI Lab", "Printed HUD settings UI test results.", 3500)
end


