function minigames.RenderHudSettingsUiTests()
    if ClickGUI.BeginCustomChildWindow("HUD / Menu UI Tests") then
        if ImGui then
            ImGui.Text("These tests are inside the same area as HUD settings.")
            ImGui.Text("Click each test. A toast/log means that method works.")
            ImGui.Text("Last Clicked: " .. tostring(minigames.UILab and minigames.UILab.lastClicked or "None"))
        end

        -- method 1: featuremgr + clickgui.renderfeature
        ClickGUI.RenderFeature(minigames.H.UI_TESTS_HUD_FEATURE_BUTTON)
        ClickGUI.RenderFeature(minigames.H.UI_TESTS_HUD_FEATURE_TOGGLE)

        -- method 2: imgui.button
        if ImGui and ImGui.Button then
            if ImGui.Button("UI Test: ImGui.Button") then
                minigames.UILabClick("ImGui.Button")
            end
        end

        -- method 3: imgui.smallbutton
        if ImGui and ImGui.SmallButton then
            if ImGui.SmallButton("UI Test Small -") then
                minigames.UILabClick("ImGui.SmallButton")
            end

            if ImGui.SameLine then
                ImGui.SameLine()
            end

            if ImGui.SmallButton("UI Test Small +") then
                minigames.UILabClick("ImGui.SmallButton")
            end
        end

        -- method 4: imgui.selectable
        if ImGui and ImGui.Selectable then
            if ImGui.Selectable("UI Test: Selectable Row") then
                minigames.UILabClick("ImGui.Selectable")
            end
        end

        -- method 5: imgui.invisiblebutton
        if ImGui and ImGui.InvisibleButton then
            if ImGui.InvisibleButton("UI Test Invisible Button Zone", 180, 24) then
                minigames.UILabClick("ImGui.InvisibleButton")
            end

            if ImGui and ImGui.Text then
                ImGui.Text("Invisible button zone is above this line.")
            end
        end

        ClickGUI.RenderFeature(minigames.H.UI_TESTS_HUD_RESULTS)

        if ImGui then
            ImGui.Text("Counts:")
            ImGui.Text("Feature: " .. tostring(minigames.UILab.clickedFeature or 0) ..
                " | Toggle: " .. tostring(minigames.UILab.clickedToggle or 0))
            ImGui.Text("Button: " .. tostring(minigames.UILab.clickedImguiButton or 0) ..
                " | Small: " .. tostring(minigames.UILab.clickedSmallButton or 0))
            ImGui.Text("Selectable: " .. tostring(minigames.UILab.clickedSelectable or 0) ..
                " | Invisible: " .. tostring(minigames.UILab.clickedInvisible or 0))
        end

        ClickGUI.EndCustomChildWindow()
    end
end



