            end

            if ImGui.BeginTabItem("Test") then
                minigames.RenderIntroTestSettingsTab()
                ImGui.EndTabItem()
            end

            ImGui.EndTabBar()
        end
    else
        -- fallback if tab bars fail in this cherax build.
        minigames.RenderCoreSettingsTab()
        minigames.RenderHudTuningSettingsTab()
        minigames.RenderHudSettingsUiTests()
        minigames.RenderCleanupLogSettingsTab()
        minigames.RenderSettingsPage()
        minigames.RenderIntroTestSettingsTab()
    end
end


