    if ImGui and ImGui.BeginTabBar and ImGui.BeginTabItem then
        if ImGui.BeginTabBar("Minigames_Root_v081") then
            if ImGui.BeginTabItem("Main") then minigames.RenderMainPage() ImGui.EndTabItem() end
            if ImGui.BeginTabItem("Players") then minigames.RenderPlayersPage() ImGui.EndTabItem() end
            if minigames.UILab and minigames.UILab.Render and ImGui.BeginTabItem("UI Tests") then minigames.UILab.Render() ImGui.EndTabItem() end
            if ImGui.BeginTabItem("WarGames") then minigames.WarGames.RenderUI() ImGui.EndTabItem() end
            if minigames.LandOnIt and minigames.LandOnIt.Render and ImGui.BeginTabItem("Land On It") then minigames.LandOnIt.Render() ImGui.EndTabItem() end
            if ImGui.BeginTabItem("DriftGod") then minigames.DriftGod.RenderUI() ImGui.EndTabItem() end
            if ImGui.BeginTabItem("Beast") then minigames.Beast.RenderUI() ImGui.EndTabItem() end
            if ImGui.BeginTabItem("Settings") then minigames.RenderSettingsTabs() ImGui.EndTabItem() end
            ImGui.EndTabBar()
        end
    else
        minigames.RenderMainPage()
        minigames.RenderPlayersPage()
        if minigames.UILab and minigames.UILab.Render then minigames.UILab.Render() end
        minigames.WarGames.RenderUI()
        if minigames.LandOnIt and minigames.LandOnIt.Render then minigames.LandOnIt.Render() end
        minigames.DriftGod.RenderUI()
        minigames.Beast.RenderUI()
        minigames.RenderSettingsPage()
    end
end

