-- ============================================================
-- embedded module: wargames\bounty.lua
-- ============================================================
embedded_modules['WarGames\\bounty.lua'] = function()
--[[
    minigames/wargames/bounty.lua
    build: v0.171-alpha

    v0.056 behavior:
    - manual force bounty still bypasses tracking.
    - auto bounty maintenance force-refreshes every 60 seconds.
    - auto bounty skips players already tracked as having a bounty.
    - bounty tracking clears when a player dies in systems/respawn.lua.
    - new players receive a bounty immediately unless already tracked.
]]

minigames.WarGames = minigames.WarGames or {}
minigames.WarGames.Bounty = minigames.WarGames.Bounty or {}

minigames.WarGames.Bounty.IntervalMs = 60000
minigames.WarGames.Bounty.FeatureName = "Set Bounty On Player"
minigames.WarGames.Bounty.AmountLabel = "9k"

function minigames.WarGames.BountyLog(msg)
    if minigames.RoutineLogInfoV171 then
        minigames.RoutineLogInfoV171(
            "[WarGames Bounty] " .. tostring(msg)
        )
    end
end

function minigames.WarGames.ForceBountyOnPlayer(playerId, reason)
    playerId = minigames.ClampInt(playerId, 0, 31)
    reason = tostring(reason or "WarGames Force Bounty")

    minigames.InitPlayerState(playerId)

    if not minigames.IsPlayerActive(playerId) then
        minigames.SetBountyStatus(playerId, "Skipped force bounty: inactive player", "WarGames Force Built-In 9k", "inactive")
        return false, "inactive"
    end

    local feature = nil

    local okGet, errGet = direct_call(function()
        feature = FeatureMgr.GetFeatureByName(minigames.WarGames.Bounty.FeatureName, playerId)
    end)

    if not okGet or not feature then
        minigames.SetBountyStatus(playerId, "Failed force bounty: built-in feature not found", "WarGames Force Built-In 9k", errGet or "feature=nil")
        return false, "feature_nil"
    end

    local okTrigger, errTrigger = direct_call(function()
        feature:TriggerCallback()
    end)

    if okTrigger then
        minigames.MarkBountyTracked(playerId, "WarGames Force Built-In 9k")
        minigames.SetBountyStatus(playerId, "Applied built-in " .. minigames.WarGames.Bounty.AmountLabel .. " bounty to " .. minigames.GetPlayerName(playerId), "WarGames Force Built-In 9k", "None")

        minigames.WarGames.BountyLog(
            "Bounty applied | player=" ..
            tostring(playerId) ..
            " | name=" ..
            minigames.GetPlayerName(playerId) ..
            " | reason=" ..
            reason
        )

        return true, "applied"
    end

    minigames.SetBountyStatus(playerId, "Failed force bounty: TriggerCallback error", "WarGames Force Built-In 9k", errTrigger)
    return false, "trigger_failed"
end

function minigames.WarGames.ApplyBountyToSelected(force)
    minigames.RefreshPlayers()

    if minigames.RefreshConfig then
        minigames.RefreshConfig()
    end

    local playerId = minigames.S.selectedPlayerId or minigames.GetLocalPlayerId()

    minigames.Queue(function()
        local ok, status

        if force == true then
            ok, status = minigames.WarGames.ForceBountyOnPlayer(playerId, "Selected Player Force")
        else
            ok, status = minigames.ApplyBuiltInBounty(playerId, false)
        end

        if ok then
            minigames.Toast("Bounty Applied", minigames.GetPlayerName(playerId) .. " | built-in " .. minigames.WarGames.Bounty.AmountLabel, 4000)
        else
            minigames.Toast("Bounty Failed", minigames.GetPlayerName(playerId) .. " | " .. tostring(status), 6000)
        end
    end)
end

function minigames.WarGames.ApplyBountyToAll(force)
    minigames.RefreshPlayers()

    if minigames.RefreshConfig then
        minigames.RefreshConfig()
    end

    force = force == true

    minigames.S.lastBountyBatchApplied = 0
    minigames.S.lastBountyBatchSkipped = 0
    minigames.S.lastBountyBatchFailed = 0

    minigames.Queue(function()
        for _, playerId in ipairs(minigames.S.activePlayers or {}) do
            if minigames.S.skipSelfBounty and minigames.IsSelf(playerId) and not force then
                minigames.S.lastBountyBatchSkipped = minigames.S.lastBountyBatchSkipped + 1
            elseif minigames.IsBountyTracked(playerId) and not force then
                minigames.S.lastBountyBatchSkipped = minigames.S.lastBountyBatchSkipped + 1
                minigames.SetBountyStatus(playerId, "Skipped: already tracked as having bounty", "WarGames Batch", "already_tracked")
            else
                local ok, status

                if force then
                    ok, status = minigames.WarGames.ForceBountyOnPlayer(playerId, "Force All Manual")
                else
                    ok, status = minigames.ApplyBuiltInBounty(playerId, false)
                end

                if ok then
                    minigames.S.lastBountyBatchApplied = minigames.S.lastBountyBatchApplied + 1
                elseif status == "skip_self" or status == "already_tracked" or status == "inactive" then
                    minigames.S.lastBountyBatchSkipped = minigames.S.lastBountyBatchSkipped + 1
                else
                    minigames.S.lastBountyBatchFailed = minigames.S.lastBountyBatchFailed + 1
                end
        -- v0.061: no yielding inside cherax feature/tick fibers.
            end
        end

        minigames.S.lastBountyStatus =
            "Bounty batch complete | applied=" ..
            tostring(minigames.S.lastBountyBatchApplied) ..
            " skipped=" ..
            tostring(minigames.S.lastBountyBatchSkipped) ..
            " failed=" ..
            tostring(minigames.S.lastBountyBatchFailed)

        if minigames.RoutineToastV171 then
            minigames.RoutineToastV171(
                "Bounty Batch",
                minigames.S.lastBountyStatus,
                5000
            )
        else
            minigames.Toast("Bounty Batch", minigames.S.lastBountyStatus, 5000)
        end
        minigames.WarGames.BountyLog(minigames.S.lastBountyStatus)
    end)
end

function minigames.WarGames.AutoBountyTick()
    if minigames.RefreshConfig then
        minigames.RefreshConfig()
    end

    if minigames.S.wargamesNoBountyMode == true then
        return
    end

    if minigames.S.wargamesSystemsActive ~= true and minigames.S.autoBountyRunning ~= true and minigames.S.autoBountyEnabled ~= true then
        return
    end

    minigames.S.autoBountyRunning = true
    minigames.S.autoBountyIntervalMs = 60000

    local now = minigames.Now()
    local lastTick = minigames.S.lastAutoBountyTickMs or 0

    if lastTick ~= 0 and now - lastTick < 60000 then
        return
    end

    minigames.S.lastAutoBountyTickMs = now
    minigames.S.autoBountyTickCount = (minigames.S.autoBountyTickCount or 0) + 1

    minigames.RefreshPlayers()

    minigames.S.lastBountyBatchApplied = 0
    minigames.S.lastBountyBatchSkipped = 0
    minigames.S.lastBountyBatchFailed = 0

    minigames.WarGames.BountyLog(
        "Serialized bounty refresh tick #" ..
        tostring(minigames.S.autoBountyTickCount) ..
        " | players=" ..
        tostring(minigames.S.activePlayerCount or 0)
    )

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        if minigames.S.skipSelfBounty and minigames.IsSelf(playerId) then
            minigames.S.lastBountyBatchSkipped = minigames.S.lastBountyBatchSkipped + 1
        else
            local ok, status = minigames.WarGames.ForceBountyOnPlayer(playerId, "Auto Force Maintain 60s")

            if ok then
                minigames.S.lastBountyBatchApplied = minigames.S.lastBountyBatchApplied + 1
            elseif status == "inactive" then
                minigames.S.lastBountyBatchSkipped = minigames.S.lastBountyBatchSkipped + 1
            else
                minigames.S.lastBountyBatchFailed = minigames.S.lastBountyBatchFailed + 1
            end
        end
    end

    minigames.S.lastBountyStatus =
        "Auto force bounty refresh | applied=" ..
        tostring(minigames.S.lastBountyBatchApplied) ..
        " skipped=" ..
        tostring(minigames.S.lastBountyBatchSkipped) ..
        " failed=" ..
        tostring(minigames.S.lastBountyBatchFailed)

    minigames.WarGames.BountyLog(minigames.S.lastBountyStatus)
end

function minigames.WarGames.RunAutoBountyLoop(feature)
    if minigames.S.autoBountyLoopThreadRunning then
        minigames.Toast("Auto Bounty", "Loop already running.", 3000)
        return
    end

    minigames.S.autoBountyLoopThreadRunning = true
    minigames.S.autoBountyRunning = true
    minigames.S.autoBountyIntervalMs = 60000
    minigames.S.lastAutoBountyTickMs = 0

    minigames.Toast("Auto Bounty", "Started. Force-refreshing bounties every 60 seconds.", 4500)

    while feature:IsToggled() do
        minigames.WarGames.AutoBountyTick()
        -- v0.061: no yielding inside cherax feature/tick fibers.
    end

    minigames.S.autoBountyRunning = false
    minigames.S.autoBountyLoopThreadRunning = false

    minigames.Toast("Auto Bounty", "Stopped.", 3000)
end

function minigames.WarGames.OnPlayerJoined(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)
    minigames.InitPlayerState(playerId)

    if minigames.S.autoTrackNewPlayers == true or minigames.S.wargamesSystemsActive == true then
        minigames.Player.vehicleEnabled[playerId] = true

        minigames.WarGames.BountyLog(
            "New player auto-enrolled for respawn vehicles | player=" ..
            tostring(playerId) ..
            " | " ..
            minigames.GetPlayerName(playerId)
        )
    end

    if minigames.S.autoBountyNewPlayers == true or minigames.S.wargamesSystemsActive == true then
        minigames.Queue(function()
            if not minigames.IsBountyTracked(playerId) then
                minigames.WarGames.ForceBountyOnPlayer(playerId, "New Player Joined")
            end
        end)
    end
end

function minigames.WarGames.PrintBountyDebug()
    minigames.RefreshPlayers()

    minigames.LogInfo("========== WarGames Bounty Debug ==========")
    minigames.LogInfo("Feature Name: " .. tostring(minigames.WarGames.Bounty.FeatureName))
    minigames.LogInfo("Expected Amount: " .. tostring(minigames.WarGames.Bounty.AmountLabel))
    minigames.LogInfo("WarGames Systems Active: " .. tostring(minigames.S.wargamesSystemsActive))
    minigames.LogInfo("Auto Bounty Running: " .. tostring(minigames.S.autoBountyRunning))
    minigames.LogInfo("Interval MS: 60000")
    minigames.LogInfo("Auto Tick Count: " .. tostring(minigames.S.autoBountyTickCount or 0))
    minigames.LogInfo("Last Status: " .. tostring(minigames.S.lastBountyStatus))
    minigames.LogInfo("Active Players: " .. tostring(minigames.S.activePlayerCount or 0))

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        minigames.LogInfo(
            "player=" ..
            tostring(playerId) ..
            " name=" ..
            minigames.GetPlayerName(playerId) ..
            " tracked=" ..
            tostring(minigames.Player.bountyApplied[playerId] == true) ..
            " lastStatus=" ..
            tostring(minigames.Player.bountyLastStatus[playerId] or "None") ..
            " lastError=" ..
            tostring(minigames.Player.bountyLastError[playerId] or "None")
        )
    end

    minigames.LogInfo("==========================================")
    minigames.Toast("Bounty Debug", "Printed WarGames bounty debug.", 3000)
end


------------------------------------------------------------
-- v0.095 no-bounties player join override
------------------------------------------------------------
function minigames.WarGames.OnPlayerJoined(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if minigames.S.autoTrackNewPlayers == true or minigames.S.wargamesSystemsActive == true then
        minigames.Player.respawnEnabled[playerId] = true
        minigames.WarGames.BountyLog(
            "New player auto-enrolled for respawn vehicles | player=" ..
            tostring(playerId) ..
            " | " ..
            minigames.GetPlayerName(playerId)
        )
    end

    if minigames.S.wargamesNoBountyMode == true then
        minigames.WarGames.BountyLog("No-Bounties mode active; skipped join bounty | player=" .. tostring(playerId) .. " | " .. minigames.GetPlayerName(playerId))
        return
    end

    if minigames.S.autoBountyNewPlayers == true or minigames.S.wargamesSystemsActive == true then
        if not minigames.IsBountyTracked(playerId) then
            minigames.WarGames.ForceBountyOnPlayer(playerId, "New Player Joined")
        end
    end
end


------------------------------------------------------------
-- v0.096 safe player join / respawn enrollment override
------------------------------------------------------------
function minigames.WarGames.OnPlayerJoined(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if minigames.EnsurePlayerTables then
        minigames.EnsurePlayerTables()
    else
        minigames.Player = minigames.Player or {}
        minigames.Player.respawnEnabled = minigames.Player.respawnEnabled or {}
    end

    local shouldEnrollRespawn =
        minigames.S.autoTrackNewPlayers == true
        or minigames.S.wargamesSystemsActive == true
        or minigames.S.spawnVehiclesOnRespawn == true
        or minigames.S.respawnVehiclesOnPlayerRespawn == true
        or minigames.S.respawnWatcherRunning == true

    if shouldEnrollRespawn then
        minigames.Player.respawnEnabled[playerId] = true
        minigames.WarGames.BountyLog(
            "New player auto-enrolled for respawn vehicles | player=" ..
            tostring(playerId) ..
            " | " ..
            minigames.GetPlayerName(playerId)
        )
    end

    if minigames.S.wargamesNoBountyMode == true then
        minigames.WarGames.BountyLog("No-Bounties mode active; skipped join bounty | player=" .. tostring(playerId) .. " | " .. minigames.GetPlayerName(playerId))
        return true
    end

    if not minigames.IsWarGamesBountyAllowed or not minigames.IsWarGamesBountyAllowed() then
        minigames.WarGames.BountyLog("Bounty systems not active; skipped join bounty | player=" .. tostring(playerId) .. " | " .. minigames.GetPlayerName(playerId))
        return true
    end

    if minigames.IsBountyTracked and minigames.IsBountyTracked(playerId) then
        minigames.WarGames.BountyLog("Join bounty skipped; already tracked | player=" .. tostring(playerId) .. " | " .. minigames.GetPlayerName(playerId))
        return true
    end

    if minigames.Queue then
        minigames.Queue(function()
            if minigames.S.wargamesNoBountyMode == true then return end
            minigames.ApplyBuiltInBounty(playerId, false, "New Player Joined")
        end)
    else
        minigames.ApplyBuiltInBounty(playerId, false, "New Player Joined")
    end

    return true
end


------------------------------------------------------------
-- v0.107 force bounty maintain interval
------------------------------------------------------------
minigames.S.autoBountyIntervalMs = 60000
minigames.S.bountyIntervalMs = 60000
minigames.S.autoBountyMaintainIntervalMs = 60000
minigames.S.bountyMaintenanceIntervalMs = 60000
minigames.LogInfo("[WarGames Bounty] Auto-maintain interval forced to 60 seconds.")


