    "WEAPON_SPECIALCARBINE_MK2", "WEAPON_BULLPUPRIFLE", "WEAPON_BULLPUPRIFLE_MK2",
    "WEAPON_COMPACTRIFLE", "WEAPON_MILITARYRIFLE", "WEAPON_TACTICALRIFLE",
