    -- melee
    "WEAPON_KNIFE", "WEAPON_NIGHTSTICK", "WEAPON_HAMMER", "WEAPON_BAT",
    "WEAPON_CROWBAR", "WEAPON_GOLFCLUB", "WEAPON_BOTTLE", "WEAPON_DAGGER",
    "WEAPON_HATCHET", "WEAPON_MACHETE", "WEAPON_SWITCHBLADE", "WEAPON_BATTLEAXE",
    "WEAPON_POOLCUE", "WEAPON_WRENCH", "WEAPON_FLASHLIGHT"
}

function minigames.WarGames.Infantry.WeaponHash(name)
    if minigames.GetWeaponHash then return minigames.GetWeaponHash(name) end
    if Utils and Utils.Joaat then
        local ok, hash = direct_call(Utils.Joaat, name)
        if ok and hash then return hash end
    end
    return 0
end

function minigames.WarGames.Infantry.GetPlayerPed(playerId)
    if minigames.GetPlayerPed then return minigames.GetPlayerPed(playerId) end
    return 0
end

function minigames.WarGames.Infantry.SnapshotPlayerWeapons(playerId)
    if minigames.S.infantrySaveAndRestoreWeapons ~= true then return false, "restore_disabled" end
    minigames.S.infantrySavedWeapons = minigames.S.infantrySavedWeapons or {}

    playerId = minigames.ClampInt(playerId, 0, 31)
    if minigames.S.infantrySavedWeapons[playerId] then
        return true, "already_saved"
    end

    local ped = minigames.WarGames.Infantry.GetPlayerPed(playerId)
    if not ped or ped == 0 or (minigames.EntityExists and not minigames.EntityExists(ped)) then
        return false, "ped_missing"
    end

    local saved = {}

    if WEAPON and WEAPON.HAS_PED_GOT_WEAPON then
        for _, weaponName in ipairs(minigames.WarGames.Infantry.WeaponCatalog) do
            local hash = minigames.WarGames.Infantry.WeaponHash(weaponName)
            if hash ~= 0 then
                local has = false
                direct_call(function()
                    has = WEAPON.HAS_PED_GOT_WEAPON(ped, hash, false) == true
                end)

                if has then
                    local ammo = 0
                    if WEAPON.GET_AMMO_IN_PED_WEAPON then
                        direct_call(function()
                            ammo = WEAPON.GET_AMMO_IN_PED_WEAPON(ped, hash)
                        end)
                    end

                    saved[#saved + 1] = {
                        name = weaponName,
                        hash = hash,
                        ammo = tonumber(ammo or 0) or 0
                    }
                end
            end
        end
    end

    minigames.S.infantrySavedWeapons[playerId] = saved
    return true, "saved_" .. tostring(#saved)
end

function minigames.WarGames.Infantry.RestorePlayerWeapons(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)
    local ped = minigames.WarGames.Infantry.GetPlayerPed(playerId)
    if not ped or ped == 0 or (minigames.EntityExists and not minigames.EntityExists(ped)) then
        return false, "ped_missing"
    end

    local saved = minigames.S.infantrySavedWeapons and minigames.S.infantrySavedWeapons[playerId] or nil
    if not saved then return false, "not_saved" end

    if WEAPON and WEAPON.REMOVE_ALL_PED_WEAPONS then
        direct_call(function() WEAPON.REMOVE_ALL_PED_WEAPONS(ped, true) end)
    end

    local restored = 0
    if WEAPON and WEAPON.GIVE_WEAPON_TO_PED then
        for _, item in ipairs(saved) do
            local hash = tonumber(item.hash or 0) or 0
            local ammo = tonumber(item.ammo or 0) or 0
            if hash ~= 0 then
                local ok = direct_call(function()
                    WEAPON.GIVE_WEAPON_TO_PED(ped, hash, ammo, false, false)
                end)
                if ok then restored = restored + 1 end
            end
        end
    end

    return true, "restored_" .. tostring(restored)
end

function minigames.WarGames.Infantry.GetMode()
    return minigames.ClampInt(minigames.S.infantryLoadoutMode or 1, 1, 4)
end

function minigames.WarGames.Infantry.GetLoadoutWeapons()
    local mode = minigames.WarGames.Infantry.GetMode()

    if mode == 1 then
        return { { name = "WEAPON_HEAVYSNIPER", ammo = minigames.S.infantryAmmoSniper or 120 } }, "Sniper"
    elseif mode == 2 then
        return { { name = "WEAPON_RPG", ammo = minigames.S.infantryAmmoRpg or 20 } }, "RPG"
    elseif mode == 3 then
        if math.random(1, 2) == 1 then
            return { { name = "WEAPON_HEAVYSNIPER", ammo = minigames.S.infantryAmmoSniper or 120 } }, "Random Sniper"
        end
        return { { name = "WEAPON_RPG", ammo = minigames.S.infantryAmmoRpg or 20 } }, "Random RPG"
    end

    return {
        { name = "WEAPON_HEAVYSNIPER", ammo = minigames.S.infantryAmmoSniper or 120 },
        { name = "WEAPON_RPG", ammo = minigames.S.infantryAmmoRpg or 20 },
        { name = "WEAPON_PISTOL", ammo = minigames.S.infantryAmmoPistol or 120 },
    }, "Sniper + RPG"
end

function minigames.WarGames.Infantry.ApplyLoadoutToPlayer(playerId, reason)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if not minigames.IsPlayerActive(playerId) then
        return false, "inactive"
    end

    local ped = minigames.WarGames.Infantry.GetPlayerPed(playerId)
    if not ped or ped == 0 or (minigames.EntityExists and not minigames.EntityExists(ped)) then
        return false, "ped_missing"
    end

    minigames.WarGames.Infantry.SnapshotPlayerWeapons(playerId)

    if WEAPON and WEAPON.REMOVE_ALL_PED_WEAPONS then
        direct_call(function()
            WEAPON.REMOVE_ALL_PED_WEAPONS(ped, true)
        end)
    end

    local weapons, label = minigames.WarGames.Infantry.GetLoadoutWeapons()
    local given = 0

    if WEAPON and WEAPON.GIVE_WEAPON_TO_PED then
        for _, item in ipairs(weapons) do
            local hash = minigames.WarGames.Infantry.WeaponHash(item.name)
            if hash ~= 0 then
                local ok = direct_call(function()
                    WEAPON.GIVE_WEAPON_TO_PED(ped, hash, tonumber(item.ammo or 20) or 20, false, true)
                end)
                if ok then given = given + 1 end
            end
        end
    end

    return given > 0, label .. "_given_" .. tostring(given) .. "_" .. tostring(reason or "infantry")
end

function minigames.WarGames.Infantry.GetPlayerVehicle(playerId)
    if minigames.GetPlayerVehicleIfAny then
        return minigames.GetPlayerVehicleIfAny(playerId)
    end

    local ped = minigames.WarGames.Infantry.GetPlayerPed(playerId)
    if not ped or ped == 0 then return 0 end

    if PED and PED.GET_VEHICLE_PED_IS_IN then
        local ok, veh = direct_call(function()
            return PED.GET_VEHICLE_PED_IS_IN(ped, false)
        end)
        if ok and veh then return veh end
    end

    return 0
end

function minigames.WarGames.Infantry.RemovePlayerVehicle(playerId, reason)
    playerId = minigames.ClampInt(playerId, 0, 31)

    local ped = minigames.WarGames.Infantry.GetPlayerPed(playerId)
    local veh = minigames.WarGames.Infantry.GetPlayerVehicle(playerId)

    if not veh or veh == 0 or (minigames.EntityExists and not minigames.EntityExists(veh)) then
        return false, "not_in_vehicle"
    end

    if minigames.S.infantryKickPlayersOutOfVehicles ~= false and TASK and TASK.TASK_LEAVE_VEHICLE and ped and ped ~= 0 then
        direct_call(function()
            TASK.TASK_LEAVE_VEHICLE(ped, veh, 4160)
        end)
    end

    if minigames.S.infantryDeleteVehiclesHard == true then
        -- off by default for v0.141 stability. only used if user turns it on later.
        if minigames.DeleteVehicleEntity then
            local ok, status = minigames.DeleteVehicleEntity(veh, reason or "Infantry WarGames")
            return ok == true, tostring(status or "delete_attempt")
        end
    end

    return true, "vehicle_exit_requested"
end

function minigames.WarGames.Infantry.DisableVehicleSystems(reason)
    if minigames.S.infantryBlockVehicleSpawns ~= true then return end

    minigames.S.autoRandomVehicleRounds = false
    minigames.S.autoVehicleRounds = false
    minigames.S.randomVehicleRoundsEnabled = false
    minigames.S.autoRandomRoundsEnabled = false

    minigames.S.spawnVehicleOnPlayerRespawn = false
    minigames.S.spawnVehiclesOnRespawn = false
    minigames.S.respawnVehiclesOnPlayerRespawn = false

    if minigames.Player and minigames.Player.vehicleEnabled then
        for playerId = 0, 31 do
            minigames.Player.vehicleEnabled[playerId] = false
        end
    end
end

function minigames.WarGames.Infantry.ApplyToAll(reason)
    minigames.RefreshPlayers()
    minigames.WarGames.Infantry.DisableVehicleSystems(reason or "Infantry apply")

    local applied, vehicleActions, failed = 0, 0, 0

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        local okLoadout = false
        local ok, status = direct_call(function()
            return minigames.WarGames.Infantry.ApplyLoadoutToPlayer(playerId, reason or "ApplyToAll")
        end)

        if ok then
            okLoadout = status == true
        end

        if okLoadout then applied = applied + 1 else failed = failed + 1 end

        if minigames.S.infantryKickPlayersOutOfVehicles ~= false then
            local okVehicle = false
            direct_call(function()
                okVehicle = minigames.WarGames.Infantry.RemovePlayerVehicle(playerId, reason or "Infantry vehicle block")
            end)
            if okVehicle then vehicleActions = vehicleActions + 1 end
        end
    end

    local _, label = minigames.WarGames.Infantry.GetLoadoutWeapons()

    minigames.S.infantryLastStatus =
        "Infantry apply | loadout=" .. tostring(label) ..
        " | applied=" .. tostring(applied) ..
        " | vehicleActions=" .. tostring(vehicleActions) ..
        " | failed=" .. tostring(failed) ..
        " | reason=" .. tostring(reason or "Manual")

    minigames.LogInfo("[Infantry] " .. minigames.S.infantryLastStatus)
    return applied, failed, vehicleActions
end

function minigames.WarGames.Infantry.RestoreAll(reason)
    minigames.RefreshPlayers()

    local restored, failed = 0, 0

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        local ok, status = minigames.WarGames.Infantry.RestorePlayerWeapons(playerId)
        if ok then restored = restored + 1 else failed = failed + 1 end
    end

    minigames.S.infantryLastStatus =
        "Restore weapons | restored=" .. tostring(restored) ..
        " | failed=" .. tostring(failed) ..
        " | reason=" .. tostring(reason or "Manual")

    minigames.LogInfo("[Infantry] " .. minigames.S.infantryLastStatus)
    minigames.Toast("Infantry WarGames", minigames.S.infantryLastStatus, 4500)

    return restored, failed
end

function minigames.WarGames.Infantry.SetEnabled(enabled, reason)
    enabled = enabled == true
    minigames.S.infantryWarGamesEnabled = enabled

    if enabled then
        minigames.S.infantryStartedMs = minigames.Now()
        minigames.S.infantrySavedWeapons = {}
        minigames.WarGames.Infantry.ApplyToAll(reason or "Enabled")
        minigames.Toast("Infantry WarGames", "Enabled: vehicles blocked, loadout applied.", 4500)
    else
        minigames.WarGames.Infantry.DisableVehicleSystems(reason or "Disabled")
        if minigames.S.infantryRestoreWeaponsOnDisable ~= false then
            minigames.WarGames.Infantry.RestoreAll(reason or "Disabled")
        end
        minigames.S.infantrySavedWeapons = {}
        minigames.Toast("Infantry WarGames", "Disabled.", 3000)
    end
end

function minigames.WarGames.Infantry.Tick()
    if minigames.S.infantryWarGamesEnabled ~= true then return end
    if minigames.S.infantryAutoEnforce ~= true then return end

    local now = minigames.Now()
    local last = minigames.S.lastInfantryEnforceMs or 0
    local interval = tonumber(minigames.S.infantryEnforceIntervalMs or 7000) or 7000

    if last ~= 0 and now - last < interval then
        return
    end

    minigames.S.lastInfantryEnforceMs = now
    minigames.WarGames.Infantry.ApplyToAll("Auto enforce")
end

function minigames.WarGames.Infantry.PrintStatus()
    local mode = minigames.WarGames.Infantry.GetMode()
    local label = minigames.WarGames.Infantry.LoadoutNames[mode] or tostring(mode)
    local status =
        "Enabled=" .. tostring(minigames.S.infantryWarGamesEnabled == true) ..
        " | Loadout=" .. tostring(label) ..
        " | Restore=" .. tostring(minigames.S.infantryRestoreWeaponsOnDisable ~= false) ..
        " | BlockVehicles=" .. tostring(minigames.S.infantryBlockVehicleSpawns == true) ..
        " | KickVehicles=" .. tostring(minigames.S.infantryKickPlayersOutOfVehicles ~= false) ..
        " | HardDeleteVehicles=" .. tostring(minigames.S.infantryDeleteVehiclesHard == true) ..
        " | Last=" .. tostring(minigames.S.infantryLastStatus or "None")

    minigames.LogInfo("[Infantry] " .. status)
    minigames.Toast("Infantry Status", status, 5500)
end

