                " | reason=" .. tostring(reason or "unknown")
            return false, "infantry_vehicle_spawns_blocked"
        end

        return __mg150_old_spawn_vehicle_for_player(playerId, vehicle, force, reason)
    end
end

local __mg150_old_wargames_spawn_all = minigames.WarGames.SpawnVehicleOnAll
if __mg150_old_wargames_spawn_all then
