            minigames.S.infantryLastVehicleBlockStatus = "Blocked Spawn All while Infantry WarGames is active."
            minigames.Toast("Infantry WarGames", "Vehicle spawning is blocked while Infantry mode is active.", 3500)
            return 0, 0, 0
        end

        return __mg150_old_wargames_spawn_all(force, reason)
    end
end

------------------------------------------------------------
-- simple group teleport helpers for main tab.
------------------------------------------------------------

function minigames.WarGames.GetEntityCoordsV150(entity)
    if not entity or entity == 0 then return nil end
    if ENTITY and ENTITY.GET_ENTITY_COORDS then
        local ok, coords = direct_call(function()
            return ENTITY.GET_ENTITY_COORDS(entity, true)
        end)
        if ok and coords then
            local x = tonumber(coords.x or coords.X or coords[1])
            local y = tonumber(coords.y or coords.Y or coords[2])
            local z = tonumber(coords.z or coords.Z or coords[3])
            if x and y and z then return x, y, z end
        end
    end
    return nil
end

function minigames.WarGames.GetLocalPlayerLocationV150(zOffset, label)
    local playerId = minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or 0
    local ped = minigames.GetPlayerPed and minigames.GetPlayerPed(playerId) or 0
    local entity = ped

    if minigames.GetPlayerVehicleIfAny then
        local veh = minigames.GetPlayerVehicleIfAny(playerId)
        if veh and veh ~= 0 then entity = veh end
    end

    local x, y, z = minigames.WarGames.GetEntityCoordsV150(entity)
    if not x then return nil, "coords_missing" end

    return {
        id = "local_above_me",
        label = label or "Above Me",
        x = x,
        y = y,
        z = z + (tonumber(zOffset or 0.0) or 0.0),
        heading = 0.0
    }, "ok"
end

function minigames.WarGames.GetWaypointLocationV150()
    if not HUD then return nil, "hud_missing" end

    local active = true
    if HUD.IS_WAYPOINT_ACTIVE then
        local ok, result = direct_call(function() return HUD.IS_WAYPOINT_ACTIVE() end)
        if ok then active = result == true end
    end

    if active ~= true then
        return nil, "waypoint_not_active"
    end

    local sprite = 8
    if HUD.GET_WAYPOINT_BLIP_ENUM_ID then
        direct_call(function() sprite = HUD.GET_WAYPOINT_BLIP_ENUM_ID() end)
    end

    local blip = 0
    if HUD.GET_FIRST_BLIP_INFO_ID then
        local ok, result = direct_call(function()
            return HUD.GET_FIRST_BLIP_INFO_ID(sprite)
        end)
        if ok and result then blip = result end
    end

    if not blip or blip == 0 then
        return nil, "waypoint_blip_missing"
    end

    if not HUD.GET_BLIP_INFO_ID_COORD then
        return nil, "coord_native_missing"
    end

    local ok, coords = direct_call(function()
        return HUD.GET_BLIP_INFO_ID_COORD(blip)
    end)

    if not ok or not coords then
        return nil, "coord_read_failed"
    end

    local x = tonumber(coords.x or coords.X or coords[1])
    local y = tonumber(coords.y or coords.Y or coords[2])
    local z = tonumber(coords.z or coords.Z or coords[3]) or 0.0

    if not x or not y then
        return nil, "bad_waypoint_coords"
    end

    if z < 5.0 then z = 80.0 end

    return {
        id = "my_waypoint",
        label = "My Waypoint",
        x = x,
        y = y,
        z = z + 2.0,
        heading = 0.0
    }, "ok"
end

function minigames.WarGames.TeleportEveryoneAboveMeV150()
    local now = minigames.Now()
    if minigames.S.lastTpAllSimpleMs and minigames.S.lastTpAllSimpleMs ~= 0 and now - minigames.S.lastTpAllSimpleMs < (minigames.S.tpButtonCooldownMs or 2500) then
        minigames.Toast("WarGames TP", "Teleport cooldown.", 2500)
        return false, "cooldown"
    end
    minigames.S.lastTpAllSimpleMs = now

    local location, status = minigames.WarGames.GetLocalPlayerLocationV150(minigames.S.tpAboveHeadZOffset or 10.0, "Above My Head")
    if not location then
        minigames.Toast("WarGames TP", "Could not read your current location: " .. tostring(status), 4000)
        return false, status
    end

    minigames.S.lastSimpleTeleportStatus = "TP Everyone Above Me queued"
    minigames.LogInfo("[WarGames TP] TP Everyone Above Me | x=" .. tostring(location.x) .. " y=" .. tostring(location.y) .. " z=" .. tostring(location.z))

    -- uses existing v0.103 remote tp bridge by default.
    return minigames.TeleportAllPlayersToLocation(location, minigames.S.tpEveryoneIncludeVehicles ~= false, "Main Button: TP Everyone Above Me")
end

function minigames.WarGames.TeleportEveryoneToWaypointV150()
    local now = minigames.Now()

    if minigames.S.lastTpWaypointSimpleMs and
        minigames.S.lastTpWaypointSimpleMs ~= 0 and
        now - minigames.S.lastTpWaypointSimpleMs <
            (minigames.S.tpButtonCooldownMs or 2500) then
        minigames.Toast("WarGames TP", "Teleport cooldown.", 2500)
        return false, "cooldown"
    end

    minigames.S.lastTpWaypointSimpleMs = now
    minigames.S.lastSimpleTeleportStatus =
        "Per-player TP Everyone To My Waypoint queued"

    if minigames.TeleportEveryoneToMyWaypointV155 then
        return minigames.TeleportEveryoneToMyWaypointV155(
            "Main Button: TP Everyone To My Waypoint"
        )
    end

    return false, "per_player_waypoint_bridge_missing"
end

