------------------------------------------------------------

if minigames.Scheduler and minigames.Scheduler.Tick and minigames.WarGames.__v150InfantrySchedulerHook ~= true then
    minigames.WarGames.__v150InfantrySchedulerHook = true
    local __mg150_old_scheduler_tick = minigames.Scheduler.Tick

    function minigames.Scheduler.Tick(...)
