------------------------------------------------------------
-- v0.136 wargames activation automation
------------------------------------------------------------
-- when wargames systems / wargames systems - bounty / no-bounties are enabled,
-- automatically enable:
--   1) auto random vehicle rounds
--   2) auto delete empty / destroyed tracked vehicles
------------------------------------------------------------

minigames.WarGames = minigames.WarGames or {}

function minigames.WarGames.SetFeatureToggleV136(hash, enabled)
    if not FeatureMgr or not FeatureMgr.GetFeatureByHash or not hash then
        return false, "feature_mgr_unavailable"
    end

    local ok, feature = direct_call(function()
        return FeatureMgr.GetFeatureByHash(hash)
    end)

    if not ok or not feature then
        return false, "feature_not_found"
    end

    -- different cherax builds expose toggles differently, so try common methods.
    local current = nil
    if feature.IsToggled then
        direct_call(function() current = feature:IsToggled() == true end)
    elseif feature.GetBoolValue then
        direct_call(function() current = feature:GetBoolValue() == true end)
    end

    if current == enabled then
        return true, "already_" .. tostring(enabled)
    end

    if feature.SetToggled then
        local okSet = direct_call(function() feature:SetToggled(enabled == true) end)
        if okSet then return true, "SetToggled" end
    end

    if feature.SetBoolValue then
        local okSet = direct_call(function() feature:SetBoolValue(enabled == true) end)
        if okSet then return true, "SetBoolValue" end
    end

    if feature.Toggle then
        local okToggle = direct_call(function() feature:Toggle() end)
        if okToggle then return true, "Toggle" end
    end

    return false, "no_supported_toggle_method"
end

function minigames.WarGames.ApplyActivationAutomationV136(reason)
    reason = tostring(reason or "WarGames activation")

    -- 1) auto random vehicle rounds
    minigames.S.autoRandomVehicleRounds = true
    minigames.S.autoVehicleRounds = true
    minigames.S.randomVehicleRoundsEnabled = true
    minigames.S.autoRandomRoundsEnabled = true

    local roundStatus = "state_only"
    if minigames.H and minigames.H.WARGAMES_AUTO_RANDOM_VEHICLE_ROUNDS then
        local ok, status = minigames.WarGames.SetFeatureToggleV136(minigames.H.WARGAMES_AUTO_RANDOM_VEHICLE_ROUNDS, true)
        roundStatus = tostring(status or ok)
    end

    -- 2) auto delete empty / destroyed tracked vehicles
    minigames.S.autoTrackedVehicleCleanup = true
    minigames.S.trackedVehicleCleanupEnabled = true
    minigames.S.trackedVehicleCleanupIntervalMs = 180000

    local cleanupStatus = "state_only"
    if minigames.VehicleTracking and minigames.VehicleTracking.ToggleAutoTrackedCleanupV134 then
        local ok, err = direct_call(function()
            minigames.VehicleTracking.ToggleAutoTrackedCleanupV134(true)
        end)
        cleanupStatus = ok and "ToggleAutoTrackedCleanupV134" or ("cleanup_toggle_failed:" .. tostring(err))
    elseif minigames.H and minigames.H.WARGAMES_AUTO_TRACKED_VEHICLE_CLEANUP then
        local ok, status = minigames.WarGames.SetFeatureToggleV136(minigames.H.WARGAMES_AUTO_TRACKED_VEHICLE_CLEANUP, true)
        cleanupStatus = tostring(status or ok)
    end

    minigames.S.lastWarGamesAutomationStatus =
        "Auto Random Rounds ON (" .. tostring(roundStatus) .. ") | " ..
        "Tracked Cleanup ON (" .. tostring(cleanupStatus) .. ") | " ..
        "reason=" .. reason

    if minigames.LogInfo then
        minigames.LogInfo("[WarGames Automation] " .. minigames.S.lastWarGamesAutomationStatus)
    end

    if minigames.Toast then
        minigames.Toast("WarGames Automation", "Random rounds + tracked cleanup enabled.", 4500)
    end
end

function minigames.WarGames.MaybeApplyActivationAutomationV136(reason)
    if minigames.S.autoEnableRandomVehicleRoundsOnWarGames ~= false or minigames.S.autoEnableTrackedCleanupOnWarGames ~= false then
        minigames.WarGames.ApplyActivationAutomationV136(reason)
    end
end


------------------------------------------------------------
-- v0.136 wargames activation automation wrappers
------------------------------------------------------------
local __mg136_old_activate_wargames_systems = minigames.WarGames.ActivateSystems
if __mg136_old_activate_wargames_systems then
    function minigames.WarGames.ActivateSystems(...)
        local result = __mg136_old_activate_wargames_systems(...)
        if minigames.WarGames.MaybeApplyActivationAutomationV136 then
            minigames.WarGames.MaybeApplyActivationAutomationV136("Activate WarGames Systems")
        end
        return result
    end
end

local __mg136_old_activate_wargames_no_bounties = minigames.WarGames.ActivateSystemsNoBounties
if __mg136_old_activate_wargames_no_bounties then
    function minigames.WarGames.ActivateSystemsNoBounties(...)
        local result = __mg136_old_activate_wargames_no_bounties(...)
        if minigames.WarGames.MaybeApplyActivationAutomationV136 then
            minigames.WarGames.MaybeApplyActivationAutomationV136("Activate WarGames Systems - No Bounties")
        end
        return result
    end
end

local __mg136_old_enable_respawn_vehicle = minigames.WarGames.EnableSpawnVehicleOnPlayerRespawn
if __mg136_old_enable_respawn_vehicle then
    function minigames.WarGames.EnableSpawnVehicleOnPlayerRespawn(reason)
        local result = __mg136_old_enable_respawn_vehicle(reason)
        local reasonText = tostring(reason or "")
        if reasonText:find("Activate WarGames") or reasonText:find("WarGames Systems") or reasonText:find("Bounty") then
            if minigames.WarGames.MaybeApplyActivationAutomationV136 then
                minigames.WarGames.MaybeApplyActivationAutomationV136(reasonText)
            end
        end
        return result
    end
end
end

-- ============================================================
-- embedded module: wargames\respawn.lua
-- ============================================================
embedded_modules['WarGames\\respawn.lua'] = function()
--[[
    minigames/wargames/respawn.lua
    build: v0.171-alpha

    v0.056:
    - activate wargames systems now enables:
        * respawn vehicle spawning
        * auto bounty maintenance every 180 seconds
        * unused vehicle cleanup after 2 minutes
        * restricted weapon cleanup
        * new-player enrollment
]]

minigames.WarGames = minigames.WarGames or {}
minigames.WarGames.Respawn = minigames.WarGames.Respawn or {}

minigames.WarGames.Respawn.DefaultScanMs = 500
minigames.WarGames.Respawn.DefaultDelayMs = 1250

function minigames.WarGames.RespawnLog(msg)
    minigames.LogInfo("[WarGames Respawn] " .. tostring(msg))
end

function minigames.WarGames.EnableRespawnVehiclesForAllCurrentPlayers()
    minigames.RefreshPlayers()

    local count = 0
    local skipped = 0

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        minigames.InitPlayerState(playerId)

        if minigames.S.skipSelfVehicle and minigames.IsSelf(playerId) then
            skipped = skipped + 1
        else
            minigames.Player.vehicleEnabled[playerId] = true
            count = count + 1
        end
    end

    minigames.S.lastRespawnStatus =
        "Enabled respawn vehicles for " ..
        tostring(count) ..
        " players | skipped=" ..
        tostring(skipped)

    minigames.Toast("WarGames Respawn", minigames.S.lastRespawnStatus, 4000)
    minigames.WarGames.RespawnLog(minigames.S.lastRespawnStatus)
end

function minigames.WarGames.EnableVehicleTracking(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)
    minigames.InitPlayerState(playerId)

    minigames.Player.vehicleEnabled[playerId] = true

    minigames.Toast("Respawn Vehicle Enabled", minigames.GetPlayerName(playerId), 3000)
end

function minigames.WarGames.DisableVehicleTracking(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)
    minigames.InitPlayerState(playerId)

    minigames.Player.vehicleEnabled[playerId] = false

    minigames.Toast("Respawn Vehicle Disabled", minigames.GetPlayerName(playerId), 3000)
end

function minigames.WarGames.ToggleVehicleTracking(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)
    minigames.InitPlayerState(playerId)

    minigames.Player.vehicleEnabled[playerId] = not (minigames.Player.vehicleEnabled[playerId] == true)

    minigames.Toast(
        "Respawn Vehicle Tracking",
        minigames.GetPlayerName(playerId) .. " = " .. tostring(minigames.Player.vehicleEnabled[playerId]),
        3500
    )
end

function minigames.WarGames.ClearVehicleTracking(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)
    minigames.InitPlayerState(playerId)

    minigames.Player.vehicleEnabled[playerId] = false
    minigames.Player.vehicleSpawned[playerId] = false
    minigames.Player.vehicleSpawnedAtMs[playerId] = 0
    minigames.Player.vehicleLastStatus[playerId] = "Tracking cleared"
    minigames.Player.vehicleLastMethod[playerId] = "None"
    minigames.Player.vehicleLastError[playerId] = "None"

    minigames.Player.wasDead[playerId] = false
    minigames.Player.deathDetectedMs[playerId] = 0
    minigames.Player.respawnReadyMs[playerId] = 0
    minigames.Player.deathReason[playerId] = "None"

    minigames.Toast("Vehicle Tracking Cleared", minigames.GetPlayerName(playerId), 2500)
end

function minigames.WarGames.ClearAllVehicleTracking()
    for playerId = 0, 31 do
        minigames.InitPlayerState(playerId)

        minigames.Player.vehicleEnabled[playerId] = false
        minigames.Player.vehicleSpawned[playerId] = false
        minigames.Player.vehicleSpawnedAtMs[playerId] = 0
        minigames.Player.vehicleLastStatus[playerId] = "Tracking cleared"
        minigames.Player.vehicleLastMethod[playerId] = "None"
        minigames.Player.vehicleLastError[playerId] = "None"

        minigames.Player.wasDead[playerId] = false
        minigames.Player.deathDetectedMs[playerId] = 0
        minigames.Player.respawnReadyMs[playerId] = 0
        minigames.Player.deathReason[playerId] = "None"
    end

    minigames.S.lastRespawnStatus = "All vehicle tracking cleared."
    minigames.Toast("Vehicle Tracking", "All vehicle tracking cleared.", 3000)
end

function minigames.WarGames.ActivateSystems()
    minigames.S.wargamesSystemsActive = true

    minigames.S.autoTrackNewPlayers = true
    minigames.S.autoBountyNewPlayers = true

    minigames.S.respawnWatcherRunning = true
    minigames.S.autoBountyRunning = true

    -- v0.056:
    -- maintain bounty state, but do not reapply to players already tracked.
    minigames.S.forceAutoBountyReapply = false
    minigames.S.autoBountyIntervalMs = 180000

    -- teleports are manual by default. do not auto-enable with wargames systems.
    minigames.S.autoTeleportOnVehicleRoundChange = false

    -- v0.059 stable vehicle rounds.
    minigames.S.vehicleRoundTimeMs = 180000
    minigames.S.roundChangeNotifyEnabled = true
    minigames.S.suppressRoundToggleSpamToast = true
    minigames.S.forceWarGamesPlate = true
    minigames.S.removeVehicleLiveries = true
    minigames.S.randomizeVehicleColors = true
    minigames.S.randomizeWheelSmoke = true
    minigames.S.lastAutoBountyTickMs = 0
    minigames.S.autoBountyTickCount = 0

    minigames.S.respawnScanMs = minigames.S.respawnScanMs or minigames.WarGames.Respawn.DefaultScanMs
    minigames.S.respawnDelayMs = minigames.S.respawnDelayMs or minigames.WarGames.Respawn.DefaultDelayMs
    minigames.S.lastRespawnScanMs = 0
    minigames.S.respawnTickCount = 0

    -- vehicle cleanup.
    minigames.S.autoCleanupWarGamesVehicles = true
    minigames.S.noCopsEnabled = true
    minigames.S.peacekeeperAutoEnabledByWarGames = true
    minigames.S.vehicleCleanupMs = 120000
    minigames.S.vehicleCleanupScanMs = 5000
    minigames.S.lastVehicleCleanupScanMs = 0

    -- restricted weapon cleanup.
    minigames.S.autoRemoveRestrictedWeapons = true
    minigames.S.weaponCleanupScanMs = 300000
    minigames.S.lastWeaponCleanupScanMs = 0

    -- fair vehicle enforcement.
    -- strict default: only current round vehicle is allowed; rc bandito / rc tank are always removed.
    minigames.S.fairVehicleEnforcementEnabled = true
    minigames.S.fairVehicleMode = minigames.C.FAIR_VEHICLE_MODE_CURRENT_ROUND_ONLY
    minigames.S.fairVehicleScanMs = 1000
    minigames.S.lastFairVehicleScanMs = 0
    minigames.S.deleteBannedVehicles = true
    minigames.S.deleteNonRoundVehicles = true
    minigames.S.deleteRcVehicles = true

    -- vehicle round controller.
    -- default off so you can manually test first. turn on auto random vehicle rounds when ready.
    minigames.S.autoVehicleRounds = minigames.S.autoVehicleRounds == true
    minigames.S.vehicleRoundMs = minigames.S.vehicleRoundMs or 180000
    minigames.S.autoSpawnRoundVehicleToAll = minigames.S.autoSpawnRoundVehicleToAll ~= false
    minigames.S.deletePreviousVehicleOnChange = true
    minigames.S.deleteInactiveRoundVehicles = true
    minigames.S.currentRoundVehicleModel = minigames.WarGames.GetSelectedVehicle().model
    minigames.S.currentRoundVehicleName = minigames.WarGames.GetSelectedVehicle().label

    -- keep visible ui values synchronized where available.
    if minigames.H.AUTO_TRACK_NEW_PLAYERS then minigames.SetFeatureBool(minigames.H.AUTO_TRACK_NEW_PLAYERS, true) end
    if minigames.H.AUTO_BOUNTY_NEW_PLAYERS then minigames.SetFeatureBool(minigames.H.AUTO_BOUNTY_NEW_PLAYERS, true) end
    if minigames.H.AUTO_BOUNTY_INTERVAL_MS then minigames.SetFeatureInt(minigames.H.AUTO_BOUNTY_INTERVAL_MS, 20000) end

    if minigames.H.WARGAMES_RESPAWN_TICK then minigames.SetFeatureBool(minigames.H.WARGAMES_RESPAWN_TICK, true) end
    if minigames.H.WARGAMES_AUTO_BOUNTY_TICK then minigames.SetFeatureBool(minigames.H.WARGAMES_AUTO_BOUNTY_TICK, true) end
    if minigames.H.WARGAMES_AUTO_CLEANUP_VEHICLES then minigames.SetFeatureBool(minigames.H.WARGAMES_AUTO_CLEANUP_VEHICLES, true) end
    if minigames.H.WARGAMES_AUTO_REMOVE_RESTRICTED_WEAPONS then minigames.SetFeatureBool(minigames.H.WARGAMES_AUTO_REMOVE_RESTRICTED_WEAPONS, true) end
    if minigames.H.WARGAMES_FAIR_VEHICLE_ENFORCEMENT then minigames.SetFeatureBool(minigames.H.WARGAMES_FAIR_VEHICLE_ENFORCEMENT, true) end
    if minigames.H.WARGAMES_FAIR_VEHICLE_MODE then minigames.SetFeatureInt(minigames.H.WARGAMES_FAIR_VEHICLE_MODE, minigames.C.FAIR_VEHICLE_MODE_CURRENT_ROUND_ONLY) end
    if minigames.H.WARGAMES_DELETE_PREVIOUS_ON_CHANGE then minigames.SetFeatureBool(minigames.H.WARGAMES_DELETE_PREVIOUS_ON_CHANGE, true) end
    if minigames.H.WARGAMES_DELETE_INACTIVE_ROUND_VEHICLES then minigames.SetFeatureBool(minigames.H.WARGAMES_DELETE_INACTIVE_ROUND_VEHICLES, true) end

    minigames.WarGames.EnableRespawnVehiclesForAllCurrentPlayers()

    if minigames.ResetDeathTracking then
        minigames.ResetDeathTracking()
    end

    -- do one immediate pass.
    minigames.Queue(function()
        if minigames.WarGames.AutoBountyTick then minigames.WarGames.AutoBountyTick() end
        if minigames.VehicleCleanupTick then minigames.VehicleCleanupTick() end
        if minigames.FairVehicles and minigames.FairVehicles.ScanAll then minigames.FairVehicles.ScanAll("WarGames Activation") end
    end)

    minigames.S.lastRespawnStatus =
        "WarGames active | respawn vehicles ON | force bounty 20s ON | cleanup ON | restricted weapons cleanup ON"

    minigames.Toast(
        "WarGames Activated",
        "Respawn vehicles, bounty maintenance, cleanup, WARGAMES plates, and weapon cleanup are active.",
        6500
    )

    minigames.WarGames.RespawnLog(minigames.S.lastRespawnStatus)
end

function minigames.WarGames.DeactivateSystems()
    minigames.S.wargamesSystemsActive = false
    minigames.S.respawnWatcherRunning = false
    minigames.S.autoBountyRunning = false
    minigames.S.autoRemoveRestrictedWeapons = false
    minigames.S.fairVehicleEnforcementEnabled = false

    minigames.S.lastRespawnStatus = "WarGames systems deactivated."

    minigames.Toast("WarGames Deactivated", "Respawn watcher, auto bounty, and weapon cleanup stopped.", 4000)
end

function minigames.WarGames.ScanPlayerForRespawnVehicle(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)
    minigames.InitPlayerState(playerId)

    if not minigames.IsPlayerActive(playerId) then return end
    if minigames.S.skipSelfVehicle and minigames.IsSelf(playerId) then return end
    if minigames.S.respawnOnlyTracked ~= false and minigames.Player.vehicleEnabled[playerId] ~= true then return end

    if not minigames.HandleRespawnTick then
        minigames.WarGames.RespawnLog("HandleRespawnTick is missing from systems/respawn.lua")
        return
    end

    minigames.HandleRespawnTick(playerId, function()
        return minigames.WarGames.ResolveVehicle("Respawn Watcher")
    end)
end

function minigames.WarGames.RespawnWatcherTick()
    -- v0.067: scheduler-driven watcher. no bounty/weapon/fair cleanup runs here.
    local nowGate = minigames.Now()
    local lastGate = minigames.S.lastRespawnWatcherTickMs or 0
    local intervalGate = minigames.S.respawnWatcherIntervalMs or 500

    if lastGate ~= 0 and nowGate - lastGate < intervalGate then
        return
    end

    minigames.S.lastRespawnWatcherTickMs = nowGate

    if minigames.S.wargamesSystemsActive ~= true
        and minigames.S.respawnWatcherRunning ~= true
        and minigames.S.spawnVehiclesOnRespawn ~= true
        and minigames.S.respawnVehiclesOnPlayerRespawn ~= true then
        return
    end

    if minigames.RefreshConfig then
        minigames.RefreshConfig()
    end

    local now = minigames.Now()
    local scanMs = minigames.S.respawnScanMs or minigames.WarGames.Respawn.DefaultScanMs
    local lastScan = minigames.S.lastRespawnScanMs or 0

    if lastScan ~= 0 and now - lastScan < scanMs then
        return
    end

    minigames.S.lastRespawnScanMs = now
    minigames.S.respawnTickCount = (minigames.S.respawnTickCount or 0) + 1

    minigames.RefreshPlayers()

    -- new players should automatically join the respawn vehicle system while it is enabled.
    if minigames.S.autoTrackNewPlayers ~= false then
        for _, playerId in ipairs(minigames.S.activePlayers or {}) do
            minigames.InitPlayerState(playerId)
            if minigames.S.skipSelfVehicle and minigames.IsSelf(playerId) then
                -- skip self only if user wants that
            else
                minigames.Player.vehicleEnabled[playerId] = true
            end
        end
    end

    if minigames.VehicleRoundTick then
        local okRound, errRound = direct_call(function()
            minigames.VehicleRoundTick()
        end)
        if not okRound then
            minigames.LogError("[WarGames Respawn] VehicleRoundTick failed: " .. tostring(errRound))
        end
    end

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        local okScan, errScan = direct_call(function()
            minigames.WarGames.ScanPlayerForRespawnVehicle(playerId)
        end)
        if not okScan then
            minigames.LogError("[WarGames Respawn] scan failed | player=" .. tostring(playerId) .. " | err=" .. tostring(errScan))
        end
    end

    if (minigames.S.respawnTickCount or 0) % 20 == 0 then
        minigames.WarGames.RespawnLog(
            "heartbeat | tick=" ..
            tostring(minigames.S.respawnTickCount) ..
            " | players=" ..
            tostring(minigames.S.activePlayerCount or 0) ..
            " | watcher=" ..
            tostring(minigames.S.respawnWatcherRunning) ..
            " | spawnOnRespawn=" ..
            tostring(minigames.S.spawnVehiclesOnRespawn) ..
            " | noBounties=" ..
            tostring(minigames.S.wargamesNoBountyMode) ..
            " | last=" ..
            tostring(minigames.S.lastRespawnStatus)
        )
    end
end

function minigames.WarGames.RunRespawnWatcher(feature)
    if minigames.S.respawnWatcherLoopThreadRunning then
        minigames.Toast("Respawn Watcher", "Loop already running.", 3000)
        return
    end

    minigames.S.respawnWatcherLoopThreadRunning = true
    minigames.S.respawnWatcherRunning = true
    minigames.S.lastRespawnScanMs = 0
    minigames.S.respawnTickCount = 0

    minigames.Toast("WarGames Respawn Watcher", "Started.", 4000)

    while feature:IsToggled() do
        minigames.WarGames.RespawnWatcherTick()
        -- v0.061: no yielding inside cherax tick fibers.
    end

    minigames.S.respawnWatcherRunning = false
    minigames.S.respawnWatcherLoopThreadRunning = false

    minigames.Toast("WarGames Respawn Watcher", "Stopped.", 3000)
end


function minigames.WarGames.ConfigureSystems(includeBounties)
    includeBounties = includeBounties == true

    minigames.S.wargamesSystemsActive = true
    minigames.S.wargamesNoBountyMode = not includeBounties

    minigames.S.autoTrackNewPlayers = true
    minigames.S.autoBountyNewPlayers = includeBounties

    if minigames.H.AUTO_BOUNTY_NEW_PLAYERS and minigames.SetFeatureBool then
        minigames.SetFeatureBool(
            minigames.H.AUTO_BOUNTY_NEW_PLAYERS,
            includeBounties
        )
    end

    minigames.S.respawnWatcherRunning = true
    minigames.S.spawnVehiclesOnRespawn = true
    minigames.S.respawnVehiclesOnPlayerRespawn = true

    minigames.S.autoBountyRunning = includeBounties
    minigames.S.autoBountyEnabled = includeBounties
    minigames.S.forceAutoBountyReapply = false
    minigames.S.autoBountyIntervalMs = 180000

    minigames.S.respawnScanMs = minigames.S.respawnScanMs or minigames.WarGames.Respawn.DefaultScanMs
    minigames.S.respawnDelayMs = minigames.S.respawnDelayMs or minigames.WarGames.Respawn.DefaultDelayMs
    minigames.S.lastRespawnScanMs = 0
    minigames.S.respawnTickCount = 0

    minigames.S.vehicleRoundTimeMs = minigames.S.vehicleRoundTimeMs or 180000
    minigames.S.roundChangeNotifyEnabled = true
    minigames.S.suppressRoundToggleSpamToast = true
    minigames.S.forceWarGamesPlate = true
    minigames.S.removeVehicleLiveries = true
    minigames.S.randomizeVehicleColors = true
    minigames.S.randomizeWheelSmoke = true

    minigames.S.autoCleanupWarGamesVehicles = true
    minigames.S.vehicleCleanupMs = minigames.S.vehicleCleanupMs or 120000
    minigames.S.vehicleCleanupScanMs = minigames.S.vehicleCleanupScanMs or 5000

    -- keep the movement-sensitive systems manual by default.
    if minigames.S.wargamesSoftSystemsMode ~= false then
        minigames.S.autoRemoveRestrictedWeapons = false
        minigames.S.autoFairVehicleEnforcement = false
        minigames.S.fairVehicleEnforcementEnabled = false
    end

    minigames.WarGames.EnableRespawnVehiclesForAllCurrentPlayers()

    if minigames.ResetDeathTracking then
        minigames.ResetDeathTracking()
    end

    if minigames.EnsureVehicleRoundStarted then
        direct_call(function()
            minigames.EnsureVehicleRoundStarted()
        end)
    end

    minigames.S.wargamesSystemsWasActive = true
    minigames.S.lastRespawnStatus = includeBounties and
        "WarGames active | respawn vehicles ON | bounties ON | cleanup ON" or
        "WarGames active | respawn vehicles ON | bounties OFF | cleanup ON"

    minigames.Toast(
        includeBounties and "WarGames Activated" or "WarGames No-Bounties Activated",
        minigames.S.lastRespawnStatus,
        6500
    )

    minigames.WarGames.RespawnLog(minigames.S.lastRespawnStatus)
end

function minigames.WarGames.ActivateSystemsNoBounties()
    minigames.WarGames.ConfigureSystems(false)
end

function minigames.WarGames.SystemsSafeTick()
    -- v0.064:
    -- scheduled version. this is not called directly by the toggle callback.
    if minigames.S.wargamesSystemsActive ~= true then
        return
    end

    if minigames.S.wargamesSystemsWasActive ~= true then
        minigames.WarGames.ConfigureSystems(minigames.S.wargamesNoBountyMode ~= true)
    end

    local function runPart(label, fn)
        local ok, err = direct_call_trace(fn, debug.traceback)
        if not ok then
            minigames.S.lastWarGamesSystemsError = tostring(label) .. ": " .. tostring(err)
            minigames.LogError("[WarGames Systems] " .. tostring(label) .. " failed: " .. tostring(err))
        end
    end

    runPart("VehicleRoundTick", function()
        if minigames.VehicleRoundTick then
            minigames.VehicleRoundTick()
        end
    end)

    if minigames.S.wargamesNoBountyMode ~= true then
        runPart("AutoBountyTick", function()
            if minigames.WarGames.AutoBountyTick then
                minigames.WarGames.AutoBountyTick()
            end
        end)
    end

    runPart("VehicleCleanupTick", function()
        if minigames.VehicleCleanupTick then
            minigames.VehicleCleanupTick()
        end
    end)

    local now = minigames.Now()
    local lastHeartbeat = minigames.S.lastWarGamesSystemHeartbeatMs or 0

    if lastHeartbeat == 0 or now - lastHeartbeat >= 10000 then
        minigames.S.lastWarGamesSystemHeartbeatMs = now

        minigames.LogInfo(
            "[WarGames Systems] scheduler heartbeat | players=" ..
            tostring(#(minigames.S.activePlayers or {})) ..
            " | autoBounty=" ..
            tostring(minigames.S.autoBountyEnabled) ..
            " | cleanup=" ..
            tostring(minigames.S.lastVehicleCleanupStatus) ..
            " | autoTeleportRecommended=" ..
            tostring(minigames.S.autoTeleportOnVehicleRoundChange) ..
            " | autoTeleportSelected=" ..
            tostring(minigames.S.autoTeleportSelectedOnRoundChange) ..
            " | weaponsAuto=" ..
            tostring(minigames.S.autoRemoveRestrictedWeapons) ..
            " | fairAuto=" ..
            tostring(minigames.S.autoFairVehicleEnforcement or minigames.S.fairVehicleEnforcementEnabled) ..
            " | noCops=" ..
            tostring(minigames.S.noCopsEnabled)
        )
    end
end

function minigames.WarGames.SystemsTick(feature)
    -- v0.067: lightweight toggle callback. scheduler does the real work.
    local enabled = minigames.SafeIsToggled(feature, minigames.H and minigames.H.WARGAMES_ACTIVATE_SYSTEMS, false)

    minigames.S.wargamesSystemsActive = enabled

    if not enabled then
        minigames.S.wargamesSystemsWasActive = false
        minigames.S.spawnVehiclesOnRespawn = false
        minigames.S.respawnVehiclesOnPlayerRespawn = false
        minigames.S.respawnWatcherRunning = false
        minigames.S.autoBountyRunning = false
        minigames.S.autoBountyEnabled = false
        minigames.S.wargamesNoBountyMode = false
        minigames.S.noCopsEnabled = false
        minigames.S.peacekeeperAutoEnabledByWarGames = false
        if minigames.Peacekeeper and minigames.Peacekeeper.DisableLocal then
            minigames.Peacekeeper.DisableLocal("WarGames Systems OFF")
        end
        minigames.LogInfo("[WarGames Systems] disabled")
        return true
    end

    minigames.S.wargamesNoBountyMode = false
    minigames.S.autoBountyRunning = true
    minigames.S.autoBountyEnabled = true
    minigames.S.noCopsEnabled = true
    minigames.S.peacekeeperAutoEnabledByWarGames = true
    minigames.S.respawnWatcherRunning = true
    minigames.S.spawnVehiclesOnRespawn = true
    minigames.S.respawnVehiclesOnPlayerRespawn = true
    minigames.S.wargamesSystemsWasActive = false

    minigames.LogInfo("[WarGames Systems] enabled WITH bounties; scheduler will configure systems.")
    return true
end

function minigames.WarGames.SystemsNoBountyTick(feature)
    -- v0.067: same as activate wargames systems, but leaves bounty systems off.
    local enabled = minigames.SafeIsToggled(feature, minigames.H and minigames.H.WARGAMES_ACTIVATE_SYSTEMS_NO_BOUNTIES, false)

    minigames.S.wargamesSystemsActive = enabled

    if not enabled then
        minigames.S.wargamesSystemsWasActive = false
        minigames.S.spawnVehiclesOnRespawn = false
        minigames.S.respawnVehiclesOnPlayerRespawn = false
        minigames.S.respawnWatcherRunning = false
        minigames.S.autoBountyRunning = false
        minigames.S.autoBountyEnabled = false
        minigames.S.wargamesNoBountyMode = false
        minigames.S.noCopsEnabled = false
        minigames.S.peacekeeperAutoEnabledByWarGames = false
        if minigames.Peacekeeper and minigames.Peacekeeper.DisableLocal then
            minigames.Peacekeeper.DisableLocal("WarGames No-Bounties OFF")
        end
        minigames.LogInfo("[WarGames Systems - No Bounties] disabled")
        return true
    end

    minigames.S.wargamesNoBountyMode = true
    minigames.S.autoBountyRunning = false
    minigames.S.autoBountyEnabled = false
    minigames.S.autoBountyNewPlayers = false
    minigames.S.noCopsEnabled = true
    minigames.S.peacekeeperAutoEnabledByWarGames = true
    minigames.S.respawnWatcherRunning = true
    minigames.S.spawnVehiclesOnRespawn = true
    minigames.S.respawnVehiclesOnPlayerRespawn = true
    minigames.S.wargamesSystemsWasActive = false

    minigames.LogInfo("[WarGames Systems - No Bounties] enabled; scheduler will configure systems without bounties.")
    return true
end

function minigames.WarGames.PrintRespawnDebug()
    minigames.RefreshPlayers()
    minigames.LogInfo("========== WarGames Respawn Debug ==========")
    minigames.LogInfo("WarGames Systems Active: " .. tostring(minigames.S.wargamesSystemsActive))
    minigames.LogInfo("No-Bounty Mode: " .. tostring(minigames.S.wargamesNoBountyMode))
    minigames.LogInfo("No Cops Enabled: " .. tostring(minigames.S.noCopsEnabled))
    minigames.LogInfo("Respawn Watcher Running: " .. tostring(minigames.S.respawnWatcherRunning))
    minigames.LogInfo("Spawn Vehicles On Respawn: " .. tostring(minigames.S.spawnVehiclesOnRespawn))
    minigames.LogInfo("Respawn Vehicles On Player Respawn: " .. tostring(minigames.S.respawnVehiclesOnPlayerRespawn))
    minigames.LogInfo("Respawn Tick Count: " .. tostring(minigames.S.respawnTickCount or 0))
    minigames.LogInfo("Last Respawn Status: " .. tostring(minigames.S.lastRespawnStatus))
    minigames.LogInfo("Last Vehicle Status: " .. tostring(minigames.S.lastVehicleStatus))
    minigames.LogInfo("Active Players: " .. tostring(minigames.S.activePlayerCount or 0))
    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        minigames.InitPlayerState(playerId)
        local dead, reason = false, "unknown"
        if minigames.IsPlayerDead then dead, reason = minigames.IsPlayerDead(playerId) end
        minigames.LogInfo("player=" .. tostring(playerId) .. " name=" .. minigames.GetPlayerName(playerId) .. " enabled=" .. tostring(minigames.Player.vehicleEnabled[playerId]) .. " wasDead=" .. tostring(minigames.Player.wasDead[playerId]) .. " dead=" .. tostring(dead) .. " reason=" .. tostring(reason))
    end
    minigames.LogInfo("===========================================")
    minigames.Toast("Respawn Debug", "Printed WarGames respawn debug.", 3000)
end


