-- v0.094 wargames active/hud + no-bounty safety overrides
------------------------------------------------------------
function minigames.WarGames.MarkActiveState(active, noBounty)
    minigames.S = minigames.S or {}
    minigames.S.wargamesSystemsActive = active == true
    minigames.S.wargamesActive = active == true
    minigames.S.warGamesActive = active == true
    minigames.S.wargamesNoBountyMode = noBounty == true

    if active == true then
        if noBounty == true then
            minigames.S.currentMinigame = "WarGames - No Bounties"
        else
            minigames.S.currentMinigame = "WarGames"
        end
    elseif minigames.S.currentMinigame == "WarGames" or minigames.S.currentMinigame == "WarGames - No Bounties" then
        minigames.S.currentMinigame = "None"
    end
end

local __mg_original_ActivateSystems_v094 = minigames.WarGames.ActivateSystems
function minigames.WarGames.ActivateSystems()
    minigames.WarGames.MarkActiveState(true, false)

    if __mg_original_ActivateSystems_v094 then
        local ok, err = direct_call_trace(function()
            __mg_original_ActivateSystems_v094()
        end, debug and debug.traceback or function(e) return tostring(e) end)

        if not ok then
            minigames.LogError("[WarGames Systems] ActivateSystems inner error swallowed: " .. tostring(err))
        end
    end

    -- v0.094 defaults.
    minigames.S.respawnWatcherRunning = true
    minigames.S.spawnVehiclesOnRespawn = true
    minigames.S.respawnVehiclesOnPlayerRespawn = true
    minigames.S.autoCleanupWarGamesVehicles = true
    minigames.S.vehicleCleanupScanMs = 180000
    minigames.S.vehicleIdleCleanupMs = 60000
    minigames.S.vehicleCleanupDestroyedOnly = false
    minigames.S.preventRespawnVehicleSpam = true
    minigames.S.respawnSpawnCycleLockMs = 30000
    minigames.S.noCopsEnabled = true

    return true
end

local __mg_original_DeactivateSystems_v094 = minigames.WarGames.DeactivateSystems
function minigames.WarGames.DeactivateSystems()
    if __mg_original_DeactivateSystems_v094 then
        local ok, err = direct_call_trace(function()
            __mg_original_DeactivateSystems_v094()
        end, debug and debug.traceback or function(e) return tostring(e) end)

        if not ok then
            minigames.LogError("[WarGames Systems] DeactivateSystems inner error swallowed: " .. tostring(err))
        end
    end

    minigames.WarGames.MarkActiveState(false, false)
    return true
end

function minigames.WarGames.SystemsNoBountyTick(feature)
    local enabled = minigames.SafeIsToggled and minigames.SafeIsToggled(feature, minigames.H and minigames.H.WARGAMES_ACTIVATE_SYSTEMS_NO_BOUNTIES, false)
        or (feature and feature.IsToggled and feature:IsToggled() == true)

    if not enabled then
        minigames.S.wargamesSystemsWasActive = false
        minigames.S.spawnVehiclesOnRespawn = false
        minigames.S.respawnVehiclesOnPlayerRespawn = false
        minigames.S.respawnWatcherRunning = false
        minigames.S.autoBountyRunning = false
        minigames.S.autoBountyEnabled = false
        minigames.S.autoBountyNewPlayers = false
        minigames.S.noCopsEnabled = false
        minigames.S.peacekeeperAutoEnabledByWarGames = false
        minigames.WarGames.MarkActiveState(false, false)

        if minigames.Peacekeeper and minigames.Peacekeeper.DisableLocal then
            direct_call(function()
                minigames.Peacekeeper.DisableLocal("WarGames No-Bounties OFF")
            end)
        end

        minigames.LogInfo("[WarGames Systems - No Bounties] disabled")
        return true
    end

    minigames.WarGames.MarkActiveState(true, true)

    minigames.S.autoBountyRunning = false
    minigames.S.autoBountyEnabled = false
    minigames.S.autoBountyNewPlayers = false

    minigames.S.noCopsEnabled = true
    minigames.S.peacekeeperAutoEnabledByWarGames = true
    minigames.S.respawnWatcherRunning = true
    minigames.S.spawnVehiclesOnRespawn = true
    minigames.S.respawnVehiclesOnPlayerRespawn = true

    minigames.S.autoTrackNewPlayers = true
    minigames.S.autoCleanupWarGamesVehicles = true
    minigames.S.vehicleCleanupScanMs = 180000
    minigames.S.vehicleIdleCleanupMs = 60000
    minigames.S.preventRespawnVehicleSpam = true
    minigames.S.respawnSpawnCycleLockMs = 30000

    if minigames.WarGames.EnableRespawnVehiclesForAllCurrentPlayers then
        direct_call(minigames.WarGames.EnableRespawnVehiclesForAllCurrentPlayers)
    end

    minigames.LogInfo("[WarGames Systems - No Bounties] enabled; HUD active; respawn vehicles ON; bounty systems OFF.")
    return true
end


------------------------------------------------------------
-- v0.106 compatibility: known-good respawn + new main toggle
------------------------------------------------------------
-- this file intentionally restores the v0.100 hard-fallback respawn method,
-- because that was the version confirmed to spawn mk2, mk1, khanjali, hydra,
-- savage, deluxo, toreador, scramjet, veto, tampa, dune, br8, dump, raiju,
-- buzzard, etc. across repeated deaths.
--
-- newer toggle names are preserved:
-- - spawn vehicle on player respawn
-- - activate wargames systems
-- - activate wargames systems - no bounties
------------------------------------------------------------

function minigames.WarGames.SetSpawnVehicleOnPlayerRespawn(enabled, reason)
    minigames.S.spawnVehicleOnPlayerRespawn = enabled == true

    -- these are the flags used by the known-good v0.100 watcher.
    minigames.S.spawnVehiclesOnRespawn = minigames.S.spawnVehicleOnPlayerRespawn
    minigames.S.respawnVehiclesOnPlayerRespawn = minigames.S.spawnVehicleOnPlayerRespawn
    minigames.S.respawnWatcherRunning = minigames.S.spawnVehicleOnPlayerRespawn

    minigames.Player = minigames.Player or {}
    minigames.Player.respawnEnabled = minigames.Player.respawnEnabled or {}

    local players = minigames.GetActivePlayers and minigames.GetActivePlayers() or {}
    for _, playerId in ipairs(players) do
        minigames.Player.respawnEnabled[minigames.ClampInt(playerId, 0, 31)] = minigames.S.spawnVehicleOnPlayerRespawn
    end

    minigames.S.lastRespawnStatus =
        "Spawn Vehicle On Player Respawn " ..
