------------------------------------------------------------
-- v0.109 local-only respawn watcher override
------------------------------------------------------------
-- the log showed the normal local respawn method worked through hydra.
-- the fatal repeated shortly after a remote player's savage respawn spawn.
-- therefore:
-- - local/self player respawn vehicles stay on.
-- - remote-player respawn vehicles are off by default.
-- - remote-player support can be re-enabled with a toggle later for controlled tests.
------------------------------------------------------------

local __mg109_original_respawn_watcher_tick = minigames.WarGames.RespawnWatcherTick
function minigames.WarGames.RespawnWatcherTick()
    if minigames.S.respawnWatcherRunning ~= true
        and minigames.S.spawnVehiclesOnRespawn ~= true
        and minigames.S.respawnVehiclesOnPlayerRespawn ~= true
        and minigames.S.spawnVehicleOnPlayerRespawn ~= true then
        return
    end

    if minigames.RefreshPlayers then
        direct_call(minigames.RefreshPlayers)
    end

    minigames.Player = minigames.Player or {}
    minigames.Player.respawnEnabled = minigames.Player.respawnEnabled or {}

    local localId = minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or 0
    local players = minigames.GetActivePlayers and minigames.GetActivePlayers() or {}
    local watched = 0
    local skippedRemote = 0

    for _, playerId in ipairs(players) do
        playerId = minigames.ClampInt(playerId, 0, 31)

        local isLocal = playerId == localId
        local allowRemote = minigames.S.spawnRespawnVehiclesForRemotePlayers == true

        if isLocal or allowRemote then
            minigames.Player.respawnEnabled[playerId] = true
            minigames.HandleRespawnTick(playerId, minigames.ResolveWarGamesRespawnVehicle or minigames.RespawnVehicleResolverSafe)
            watched = watched + 1
        else
            -- keep remote players enrolled for future toggles, but don't spawn vehicles on their respawns.
            minigames.Player.respawnEnabled[playerId] = false
            skippedRemote = skippedRemote + 1
        end
    end

    minigames.S.respawnHeartbeatTick = (minigames.S.respawnHeartbeatTick or 0) + 1

    if minigames.S.respawnHeartbeatTick % 20 == 0 then
        minigames.LogInfo(
            "[WarGames Respawn] heartbeat | players=" ..
            tostring(#players) ..
            " | watched=" ..
            tostring(watched) ..
            " | skippedRemote=" ..
            tostring(skippedRemote) ..
            " | remoteRespawn=" ..
            tostring(minigames.S.spawnRespawnVehiclesForRemotePlayers) ..
            " | watcher=" ..
            tostring(minigames.S.respawnWatcherRunning) ..
            " | spawnOnRespawn=" ..
            tostring(minigames.S.spawnVehiclesOnRespawn) ..
            " | noBounties=" ..
            tostring(minigames.S.wargamesNoBountyMode) ..
            " | last=" ..
            tostring(minigames.S.lastRespawnStatus)
        )
    end
end

function minigames.WarGames.SetRemoteRespawnVehicleSpawns(enabled, reason)
    minigames.S.spawnRespawnVehiclesForRemotePlayers = enabled == true

    minigames.S.lastRespawnStatus =
        "Remote respawn vehicle spawns " ..
        (minigames.S.spawnRespawnVehiclesForRemotePlayers and "ON" or "OFF") ..
        " | reason=" ..
        tostring(reason or "Manual")

    minigames.LogInfo("[WarGames Respawn] " .. minigames.S.lastRespawnStatus)
    minigames.Toast("WarGames Respawn", minigames.S.lastRespawnStatus, 5000)

    return minigames.S.spawnRespawnVehiclesForRemotePlayers
end


------------------------------------------------------------
-- v0.110 respawn watcher player source fix
------------------------------------------------------------
-- v0.109 log bug:
--   wargames systems heartbeat: players=16+
--   respawn watcher heartbeat: players=0 / watched=0
--
-- cause:
--   respawn watcher used a player source that returned empty.
--
-- fix:
--   use the same state list the systems heartbeat relies on, then fallback:
--   1) mg.s.activeplayers
--   2) mg.getactiveplayers()
--   3) player.is_player_active scan 0-31
--   4) always include local player 0
------------------------------------------------------------

function minigames.WarGames.GetRespawnWatchPlayers()
    local seen = {}
    local players = {}

    local function addPlayer(id)
        id = tonumber(id)
        if id == nil then return end
        id = minigames.ClampInt(id, 0, 31)

        if not seen[id] then
            seen[id] = true
            table.insert(players, id)
        end
    end

    -- prefer the shared player cache used by the rest of wargames.
    if minigames.S and type(minigames.S.activePlayers) == "table" then
        for _, id in ipairs(minigames.S.activePlayers) do
            addPlayer(id)
        end
    end

    -- then try helper function, if it exists and returns something useful.
    if minigames.GetActivePlayers then
        local ok, list = direct_call(minigames.GetActivePlayers)
        if ok and type(list) == "table" then
            for _, id in ipairs(list) do
                addPlayer(id)
            end
        end
    end

    -- then scan directly from gta native if possible.
    if PLAYER and PLAYER.IS_PLAYER_ACTIVE then
        for id = 0, 31 do
            local ok, active = direct_call(function()
                return PLAYER.IS_PLAYER_ACTIVE(id)
            end)

            if ok and active == true then
                addPlayer(id)
            end
        end
    end

    -- always include local player. for our current cherax tests, local id is 0.
    local localId = 0
    if minigames.GetLocalPlayerId then
        local okLocal, result = direct_call(minigames.GetLocalPlayerId)
        if okLocal and tonumber(result) ~= nil then
            localId = minigames.ClampInt(result, 0, 31)
        end
    end

    addPlayer(localId)
    addPlayer(0)

    return players, localId
end

function minigames.ShouldWatchRespawn(playerId)
    playerId = minigames.ClampInt(playerId or 0, 0, 31)

    local localId = 0
    if minigames.GetLocalPlayerId then
        local okLocal, result = direct_call(minigames.GetLocalPlayerId)
        if okLocal and tonumber(result) ~= nil then
            localId = minigames.ClampInt(result, 0, 31)
        end
    end

    local isLocal = playerId == localId or playerId == 0

    -- local/self respawn should always be watched while spawn vehicle on player respawn is on.
    if isLocal and (
        minigames.S.spawnVehicleOnPlayerRespawn == true
        or minigames.S.spawnVehiclesOnRespawn == true
        or minigames.S.respawnVehiclesOnPlayerRespawn == true
        or minigames.S.respawnWatcherRunning == true
    ) then
        return true
    end

    -- remote respawn vehicles are disabled by default for stability.
    if minigames.S.spawnRespawnVehiclesForRemotePlayers ~= true then
        return false
    end

    -- if remote is manually enabled, require wargames respawn to be active.
    return minigames.S.spawnVehicleOnPlayerRespawn == true
        or minigames.S.spawnVehiclesOnRespawn == true
        or minigames.S.respawnVehiclesOnPlayerRespawn == true
        or minigames.S.respawnWatcherRunning == true
end

function minigames.WarGames.RespawnWatcherTick()
    if minigames.S.respawnWatcherRunning ~= true
        and minigames.S.spawnVehiclesOnRespawn ~= true
        and minigames.S.respawnVehiclesOnPlayerRespawn ~= true
        and minigames.S.spawnVehicleOnPlayerRespawn ~= true then
        return
    end

    if minigames.RefreshPlayers then
        direct_call(minigames.RefreshPlayers)
    end

    minigames.Player = minigames.Player or {}
    minigames.Player.respawnEnabled = minigames.Player.respawnEnabled or {}

    local players, localId = minigames.WarGames.GetRespawnWatchPlayers()
    local watched = 0
    local skippedRemote = 0

    for _, playerId in ipairs(players) do
        playerId = minigames.ClampInt(playerId, 0, 31)

        local isLocal = playerId == localId or playerId == 0
        local allowRemote = minigames.S.spawnRespawnVehiclesForRemotePlayers == true

        if isLocal or allowRemote then
            minigames.Player.respawnEnabled[playerId] = true
            local okTick, errTick = direct_call_trace(function()
                minigames.HandleRespawnTick(playerId, minigames.ResolveWarGamesRespawnVehicle or minigames.RespawnVehicleResolverSafe)
            end, debug and debug.traceback or function(e) return tostring(e) end)

            if not okTick then
                minigames.LogError("[WarGames Respawn] watcher tick failed for player=" .. tostring(playerId) .. " | err=" .. tostring(errTick))
            end

            watched = watched + 1
        else
            minigames.Player.respawnEnabled[playerId] = false
            skippedRemote = skippedRemote + 1
        end
    end

    minigames.S.respawnHeartbeatTick = (minigames.S.respawnHeartbeatTick or 0) + 1

    if minigames.S.respawnHeartbeatTick % 20 == 0 then
        minigames.LogInfo(
            "[WarGames Respawn] heartbeat | players=" ..
            tostring(#players) ..
            " | localId=" ..
            tostring(localId) ..
            " | watched=" ..
            tostring(watched) ..
            " | skippedRemote=" ..
            tostring(skippedRemote) ..
            " | remoteRespawn=" ..
            tostring(minigames.S.spawnRespawnVehiclesForRemotePlayers) ..
            " | watcher=" ..
            tostring(minigames.S.respawnWatcherRunning) ..
            " | spawnOnRespawn=" ..
            tostring(minigames.S.spawnVehiclesOnRespawn) ..
            " | noBounties=" ..
            tostring(minigames.S.wargamesNoBountyMode) ..
            " | last=" ..
            tostring(minigames.S.lastRespawnStatus)
        )
    end
end

function minigames.WarGames.SetSpawnVehicleOnPlayerRespawn(enabled, reason)
    minigames.S.spawnVehicleOnPlayerRespawn = enabled == true
    minigames.S.spawnVehiclesOnRespawn = enabled == true
    minigames.S.respawnVehiclesOnPlayerRespawn = enabled == true
    minigames.S.respawnWatcherRunning = enabled == true

    minigames.Player = minigames.Player or {}
    minigames.Player.respawnEnabled = minigames.Player.respawnEnabled or {}

    local players = {}
    if minigames.WarGames.GetRespawnWatchPlayers then
        players = select(1, minigames.WarGames.GetRespawnWatchPlayers()) or {}
    end

    for _, playerId in ipairs(players) do
        playerId = minigames.ClampInt(playerId, 0, 31)
        minigames.Player.respawnEnabled[playerId] = minigames.ShouldWatchRespawn(playerId)
    end

    minigames.S.lastRespawnStatus =
        "Spawn Vehicle On Player Respawn " ..
        (enabled and "ON" or "OFF") ..
        " | v0.114 remote-respawn-watcher | reason=" ..
        tostring(reason or "Manual")

    minigames.LogInfo("[WarGames Respawn] " .. minigames.S.lastRespawnStatus)
    return enabled == true
end

function minigames.WarGames.SetRemoteRespawnVehicleSpawns(enabled, reason)
    minigames.S.spawnRespawnVehiclesForRemotePlayers = enabled == true

    minigames.S.lastRespawnStatus =
        "Remote respawn vehicle spawns " ..
        (minigames.S.spawnRespawnVehiclesForRemotePlayers and "ON" or "OFF") ..
        " | reason=" ..
        tostring(reason or "Manual")

    minigames.LogInfo("[WarGames Respawn] " .. minigames.S.lastRespawnStatus)
    minigames.Toast("WarGames Respawn", minigames.S.lastRespawnStatus, 5000)

    return minigames.S.spawnRespawnVehiclesForRemotePlayers
end


------------------------------------------------------------
-- v0.111 respawn watchdog re-arm
------------------------------------------------------------
-- if a fatal/internal error knocks out the watcher path but the scheduler is still
-- alive, this re-arms the key flags and local player enrollment.
------------------------------------------------------------

function minigames.WarGames.RespawnWatchdogTick()
    if minigames.S.respawnWatchdogEnabled ~= true then
        return
    end

    local active = minigames.S.spawnVehicleOnPlayerRespawn == true
        or minigames.S.spawnVehiclesOnRespawn == true
        or minigames.S.respawnVehiclesOnPlayerRespawn == true
        or minigames.S.respawnWatcherRunning == true
        or minigames.S.wargamesSystemsActive == true
        or minigames.S.wargamesNoBountyMode == true

    if not active then
        return
    end

    local now = minigames.Now()
    local last = minigames.S.lastRespawnWatcherTickMs or 0
    local staleMs = minigames.S.respawnWatchdogStaleMs or 15000

    if last == 0 or now - last > staleMs then
        minigames.S.spawnVehicleOnPlayerRespawn = true
        minigames.S.spawnVehiclesOnRespawn = true
        minigames.S.respawnVehiclesOnPlayerRespawn = true
        minigames.S.respawnWatcherRunning = true

        minigames.Player = minigames.Player or {}
        minigames.Player.respawnEnabled = minigames.Player.respawnEnabled or {}
        minigames.Player.respawnEnabled[0] = true

        minigames.S.lastRespawnStatus = "Watchdog re-armed respawn watcher"

        local lastLog = minigames.S.lastRespawnWatchdogLogMs or 0
        if now - lastLog > (minigames.S.respawnWatchdogLogMs or 10000) then
            minigames.S.lastRespawnWatchdogLogMs = now
            minigames.LogInfo("[WarGames Respawn Watchdog] Re-armed watcher | lastTickMs=" .. tostring(last) .. " | now=" .. tostring(now))
        end
    end
end

local __mg111_respawn_watcher_tick = minigames.WarGames.RespawnWatcherTick
function minigames.WarGames.RespawnWatcherTick()
    minigames.S.lastRespawnWatcherTickMs = minigames.Now()

    local ok, err = direct_call_trace(function()
        __mg111_respawn_watcher_tick()
    end, debug and debug.traceback or function(e) return tostring(e) end)

    if not ok then
        minigames.LogError("[WarGames Respawn] watcher error swallowed by v0.111 | err=" .. tostring(err))
        minigames.WarGames.RespawnWatchdogTick()
    end
end


------------------------------------------------------------
-- v0.112 local respawn recovery watchdog
------------------------------------------------------------
-- if a fatal/repeated exception interrupts normal heartbeat, this only re-arms
-- local player 0. it does not mass-enroll remote players.
------------------------------------------------------------

function minigames.WarGames.LocalRespawnRecoveryTick()
    if minigames.S.respawnWatchdogEnabled ~= true then
        return
    end

    local active = minigames.S.spawnVehicleOnPlayerRespawn == true
        or minigames.S.spawnVehiclesOnRespawn == true
        or minigames.S.respawnVehiclesOnPlayerRespawn == true
        or minigames.S.respawnWatcherRunning == true
        or minigames.S.wargamesSystemsActive == true
        or minigames.S.wargamesNoBountyMode == true

    if not active then
        return
    end

    minigames.S.spawnVehicleOnPlayerRespawn = true
    minigames.S.spawnVehiclesOnRespawn = true
    minigames.S.respawnVehiclesOnPlayerRespawn = true
    minigames.S.respawnWatcherRunning = true
    minigames.S.spawnRespawnVehiclesForRemotePlayers = false

    minigames.Player = minigames.Player or {}
    minigames.Player.respawnEnabled = minigames.Player.respawnEnabled or {}
    minigames.Player.respawnEnabled[0] = true

    local now = minigames.Now()
    local last = minigames.S.lastRespawnWatcherTickMs or 0
    local staleMs = minigames.S.respawnWatchdogStaleMs or 12000

    if last == 0 or now - last > staleMs then
        minigames.S.lastRespawnStatus = "v0.112 local recovery re-armed watcher"
        minigames.LogInfo("[WarGames Respawn Recovery] Re-armed local watcher | lastTickMs=" .. tostring(last) .. " | now=" .. tostring(now))

        if minigames.WarGames and minigames.WarGames.RespawnWatcherTick then
            direct_call(minigames.WarGames.RespawnWatcherTick)
        end
    end
end

local __mg112_set_spawn_respawn = minigames.WarGames.SetSpawnVehicleOnPlayerRespawn
function minigames.WarGames.SetSpawnVehicleOnPlayerRespawn(enabled, reason)
    local result = true
    if __mg112_set_spawn_respawn then
        local ok, err = direct_call_trace(function()
            result = __mg112_set_spawn_respawn(enabled, reason)
        end, debug and debug.traceback or function(e) return tostring(e) end)
        if not ok then
            minigames.LogError("[WarGames Respawn] v0.112 set toggle swallowed: " .. tostring(err))
        end
    end

    minigames.S.spawnRespawnVehiclesForRemotePlayers = false
    minigames.Player = minigames.Player or {}
    minigames.Player.respawnEnabled = minigames.Player.respawnEnabled or {}
    minigames.Player.respawnEnabled[0] = enabled == true

    return result
end


------------------------------------------------------------
-- v0.114 final override: remote player respawn vehicles on
------------------------------------------------------------
-- v0.113 fixed mass-spawn spam but intentionally watched local only.
-- the log pattern for that build was:
--   players=11+ | watched=1 | skippedremote=10+ | remoterespawn=false
-- this override restores the intended wargames behavior:
--   spawn vehicle on player respawn watches all active players.
-- it still blocks automatic spawn all; it only spawns one vehicle after a watched death cycle.
------------------------------------------------------------

minigames.VERSION = "v0.183-alpha"
minigames.S.spawnRespawnVehiclesForRemotePlayers = true
minigames.S.remoteRespawnVehiclesEnabled = true
minigames.S.remoteRespawnMinimumSpawnGapMs = 8000
minigames.S.respawnMinimumSpawnGapMs = 3000
minigames.S.localRespawnMinimumSpawnGapMs = 0

function minigames.ShouldWatchRespawn(playerId)
    playerId = minigames.ClampInt(playerId or 0, 0, 31)

    local active = minigames.S.spawnVehicleOnPlayerRespawn == true
        or minigames.S.spawnVehiclesOnRespawn == true
        or minigames.S.respawnVehiclesOnPlayerRespawn == true
        or minigames.S.respawnWatcherRunning == true
        or minigames.S.wargamesSystemsActive == true
        or minigames.S.wargamesNoBountyMode == true

    if not active then
        return false
    end

    -- local player is always watched.
    local localId = 0
    if minigames.GetLocalPlayerId then
        local okLocal, result = direct_call(minigames.GetLocalPlayerId)
        if okLocal and tonumber(result) ~= nil then
            localId = minigames.ClampInt(result, 0, 31)
        end
    end

    if playerId == localId or playerId == 0 then
        return true
    end

    -- v0.114: remote players are watched by default for actual respawn cycles.
    return minigames.S.spawnRespawnVehiclesForRemotePlayers == true
end

local __mg114_previous_set_respawn = minigames.WarGames.SetSpawnVehicleOnPlayerRespawn
function minigames.WarGames.SetSpawnVehicleOnPlayerRespawn(enabled, reason)
    minigames.S.spawnVehicleOnPlayerRespawn = enabled == true
    minigames.S.spawnVehiclesOnRespawn = enabled == true
    minigames.S.respawnVehiclesOnPlayerRespawn = enabled == true
    minigames.S.respawnWatcherRunning = enabled == true
    minigames.S.spawnRespawnVehiclesForRemotePlayers = enabled == true
    minigames.S.remoteRespawnVehiclesEnabled = enabled == true

    local result = enabled == true
    if __mg114_previous_set_respawn then
        local ok, err = direct_call_trace(function()
            result = __mg114_previous_set_respawn(enabled, reason)
        end, debug and debug.traceback or function(e) return tostring(e) end)
        if not ok then
            minigames.LogError("[WarGames Respawn] v0.114 set toggle swallowed older error: " .. tostring(err))
        end
    end

    -- older v0.112/v0.113 wrappers may set this back to false. force it back on.
    minigames.S.spawnRespawnVehiclesForRemotePlayers = enabled == true
    minigames.S.remoteRespawnVehiclesEnabled = enabled == true

    minigames.Player = minigames.Player or {}
    minigames.Player.respawnEnabled = minigames.Player.respawnEnabled or {}

    local players = {}
    if minigames.WarGames.GetRespawnWatchPlayers then
        players = select(1, minigames.WarGames.GetRespawnWatchPlayers()) or {}
    elseif minigames.GetActivePlayers then
        players = minigames.GetActivePlayers() or {}
    end

    local watched = 0
    for _, playerId in ipairs(players) do
        playerId = minigames.ClampInt(playerId, 0, 31)
        minigames.Player.respawnEnabled[playerId] = enabled == true
        if enabled == true then watched = watched + 1 end
    end

    minigames.S.lastRespawnStatus =
        "Spawn Vehicle On Player Respawn " ..
        (enabled and "ON" or "OFF") ..
        " | v0.114 remote players watched | watched=" ..
        tostring(watched) ..
        " | reason=" ..
        tostring(reason or "Manual")

    minigames.LogInfo("[WarGames Respawn] " .. minigames.S.lastRespawnStatus)
    return result
end

local __mg114_previous_enable_all = minigames.WarGames.EnableRespawnVehiclesForAllCurrentPlayers
function minigames.WarGames.EnableRespawnVehiclesForAllCurrentPlayers()
    minigames.S.spawnRespawnVehiclesForRemotePlayers = true
    minigames.S.remoteRespawnVehiclesEnabled = true

    if minigames.WarGames.SetSpawnVehicleOnPlayerRespawn then
        minigames.WarGames.SetSpawnVehicleOnPlayerRespawn(true, "EnableRespawnVehiclesForAllCurrentPlayers")
    end

    if __mg114_previous_enable_all then
        local ok, err = direct_call_trace(function()
            __mg114_previous_enable_all()
        end, debug and debug.traceback or function(e) return tostring(e) end)
        if not ok then
            minigames.LogError("[WarGames Respawn] v0.114 enable-all swallowed older error: " .. tostring(err))
        end
    end

    -- older enable-all may also reset remotes false. force it after.
    minigames.S.spawnRespawnVehiclesForRemotePlayers = true
    minigames.S.remoteRespawnVehiclesEnabled = true

    local players = {}
    if minigames.WarGames.GetRespawnWatchPlayers then
        players = select(1, minigames.WarGames.GetRespawnWatchPlayers()) or {}
    elseif minigames.GetActivePlayers then
        players = minigames.GetActivePlayers() or {}
    end

    minigames.Player = minigames.Player or {}
    minigames.Player.respawnEnabled = minigames.Player.respawnEnabled or {}

    local count = 0
    for _, playerId in ipairs(players) do
        playerId = minigames.ClampInt(playerId, 0, 31)
        minigames.Player.respawnEnabled[playerId] = true
        count = count + 1
    end

    minigames.S.lastRespawnStatus =
        "Enabled respawn vehicles for " ..
        tostring(count) ..
        " players | v0.114 remote players ON"

    minigames.LogInfo("[WarGames Respawn] " .. minigames.S.lastRespawnStatus)
    return true
end

function minigames.WarGames.SetRemoteRespawnVehicleSpawns(enabled, reason)
    minigames.S.spawnRespawnVehiclesForRemotePlayers = enabled == true
    minigames.S.remoteRespawnVehiclesEnabled = enabled == true

    minigames.S.lastRespawnStatus =
        "Remote respawn vehicle spawns " ..
        (minigames.S.spawnRespawnVehiclesForRemotePlayers and "ON" or "OFF") ..
        " | v0.114 | reason=" ..
        tostring(reason or "Manual")

    minigames.LogInfo("[WarGames Respawn] " .. minigames.S.lastRespawnStatus)
    minigames.Toast("WarGames Respawn", minigames.S.lastRespawnStatus, 5000)
    return minigames.S.spawnRespawnVehiclesForRemotePlayers
end

function minigames.WarGames.RespawnWatcherTick()
    if minigames.S.respawnWatcherRunning ~= true
        and minigames.S.spawnVehiclesOnRespawn ~= true
        and minigames.S.respawnVehiclesOnPlayerRespawn ~= true
        and minigames.S.spawnVehicleOnPlayerRespawn ~= true
        and minigames.S.wargamesSystemsActive ~= true
        and minigames.S.wargamesNoBountyMode ~= true then
        return
    end

    minigames.S.lastRespawnWatcherTickMs = minigames.Now()

    if minigames.RefreshPlayers then
        direct_call(minigames.RefreshPlayers)
    end

    minigames.Player = minigames.Player or {}
    minigames.Player.respawnEnabled = minigames.Player.respawnEnabled or {}

    -- force remote on every watcher tick so older recovery code cannot silently disable it.
    minigames.S.spawnRespawnVehiclesForRemotePlayers = true
    minigames.S.remoteRespawnVehiclesEnabled = true

    local players, localId = {}, 0
    if minigames.WarGames.GetRespawnWatchPlayers then
        players, localId = minigames.WarGames.GetRespawnWatchPlayers()
    elseif minigames.GetActivePlayers then
        players = minigames.GetActivePlayers() or {}
        localId = minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or 0
    end

    local watched = 0
    local errors = 0

    for _, playerId in ipairs(players) do
        playerId = minigames.ClampInt(playerId, 0, 31)
        minigames.Player.respawnEnabled[playerId] = true

        local okTick, errTick = direct_call_trace(function()
            minigames.HandleRespawnTick(playerId, minigames.ResolveWarGamesRespawnVehicle or minigames.RespawnVehicleResolverSafe)
        end, debug and debug.traceback or function(e) return tostring(e) end)

        if okTick then
            watched = watched + 1
        else
            errors = errors + 1
            minigames.LogError("[WarGames Respawn] v0.114 watcher tick failed for player=" .. tostring(playerId) .. " | err=" .. tostring(errTick))
        end
    end

    minigames.S.respawnHeartbeatTick = (minigames.S.respawnHeartbeatTick or 0) + 1

    if minigames.S.respawnHeartbeatTick % 20 == 0 then
        minigames.LogInfo(
            "[WarGames Respawn] heartbeat | players=" ..
            tostring(#players) ..
            " | localId=" ..
            tostring(localId) ..
            " | watched=" ..
            tostring(watched) ..
            " | skippedRemote=0" ..
            " | remoteRespawn=" ..
            tostring(minigames.S.spawnRespawnVehiclesForRemotePlayers) ..
            " | watcher=" ..
            tostring(minigames.S.respawnWatcherRunning) ..
            " | spawnOnRespawn=" ..
            tostring(minigames.S.spawnVehiclesOnRespawn) ..
            " | errors=" ..
            tostring(errors) ..
            " | last=" ..
            tostring(minigames.S.lastRespawnStatus)
        )
    end
end

function minigames.WarGames.LocalRespawnRecoveryTick()
    -- v0.114: keep the recovery behavior but do not turn remotes off.
    if minigames.S.respawnWatchdogEnabled ~= true then
        return
    end

    local active = minigames.S.spawnVehicleOnPlayerRespawn == true
        or minigames.S.spawnVehiclesOnRespawn == true
        or minigames.S.respawnVehiclesOnPlayerRespawn == true
        or minigames.S.respawnWatcherRunning == true
        or minigames.S.wargamesSystemsActive == true
        or minigames.S.wargamesNoBountyMode == true

    if not active then
        return
    end

    minigames.S.spawnVehicleOnPlayerRespawn = true
    minigames.S.spawnVehiclesOnRespawn = true
    minigames.S.respawnVehiclesOnPlayerRespawn = true
    minigames.S.respawnWatcherRunning = true
    minigames.S.spawnRespawnVehiclesForRemotePlayers = true
    minigames.S.remoteRespawnVehiclesEnabled = true

    local now = minigames.Now()
    local last = minigames.S.lastRespawnWatcherTickMs or 0
    local staleMs = minigames.S.respawnWatchdogStaleMs or 12000

    if last == 0 or now - last > staleMs then
        minigames.S.lastRespawnStatus = "v0.114 all-player recovery re-armed watcher"
        minigames.LogInfo("[WarGames Respawn Recovery] Re-armed all-player watcher | lastTickMs=" .. tostring(last) .. " | now=" .. tostring(now))

        if minigames.WarGames and minigames.WarGames.RespawnWatcherTick then
            direct_call(minigames.WarGames.RespawnWatcherTick)
        end
    end
end

minigames.LogInfo("Loaded " .. script_version)
minigames.LogInfo("Respawn watcher: REMOTE PLAYER RESPAWNS ON by default.")
minigames.LogInfo("Expected heartbeat: watched should equal players, skippedRemote=0, remoteRespawn=true.")
minigames.LogInfo("Automatic Spawn All remains blocked; respawn watcher only queues one vehicle per death cycle.")


