-- v0.119 respawn activation toggle wiring
------------------------------------------------------------
-- spawn vehicle on player respawn is off by default.
-- these activation paths explicitly turn it on.
------------------------------------------------------------

function minigames.WarGames.EnableSpawnVehicleOnPlayerRespawn(reason)
    minigames.S.spawnVehicleOnPlayerRespawn = true
    minigames.S.spawnVehiclesOnRespawn = true
    minigames.S.respawnVehiclesOnPlayerRespawn = true
    minigames.S.respawnWatcherRunning = true
    minigames.S.spawnRespawnVehiclesForRemotePlayers = true

    minigames.Player = minigames.Player or {}
    minigames.Player.respawnEnabled = minigames.Player.respawnEnabled or {}

    local players = {}
    if minigames.WarGames and minigames.WarGames.GetRespawnWatchPlayers then
        players = select(1, minigames.WarGames.GetRespawnWatchPlayers()) or {}
    elseif minigames.GetActivePlayers then
        local ok, list = direct_call(minigames.GetActivePlayers)
        if ok and type(list) == "table" then players = list end
    end

    for _, playerId in ipairs(players) do
        playerId = minigames.ClampInt(playerId, 0, 31)
        minigames.Player.respawnEnabled[playerId] = true
    end

    minigames.S.lastRespawnStatus =
        "Spawn Vehicle On Player Respawn ON | reason=" ..
        tostring(reason or "WarGames Activation")

    minigames.LogInfo("[WarGames Respawn] " .. minigames.S.lastRespawnStatus)

    return true
end

function minigames.WarGames.SetSpawnVehicleOnPlayerRespawn(enabled, reason)
    if enabled == true then
        return minigames.WarGames.EnableSpawnVehicleOnPlayerRespawn(reason or "Main Toggle")
    end

    minigames.S.spawnVehicleOnPlayerRespawn = false
    minigames.S.spawnVehiclesOnRespawn = false
    minigames.S.respawnVehiclesOnPlayerRespawn = false
    minigames.S.respawnWatcherRunning = false

    minigames.S.lastRespawnStatus =
        "Spawn Vehicle On Player Respawn OFF | reason=" ..
        tostring(reason or "Main Toggle")

    minigames.LogInfo("[WarGames Respawn] " .. minigames.S.lastRespawnStatus)
    return false
end

