        end, debug and debug.traceback or function(e) return tostring(e) end)

        if not ok then
            minigames.LogError("[WarGames No-Bounties] inner tick error swallowed by v0.119: " .. tostring(err))
        end
    end

    local enabled = false
    if feature and feature.IsToggled then
        local okToggle, toggleValue = direct_call(function()
            return feature:IsToggled()
        end)
        enabled = okToggle and toggleValue == true
    else
        enabled = minigames.S.wargamesNoBountyMode == true or minigames.S.wargamesSystemsActive == true
    end

    if enabled then
        minigames.WarGames.EnableSpawnVehicleOnPlayerRespawn("Activate WarGames Systems - No Bounties")
        minigames.S.autoBountyRunning = false
        minigames.S.autoBountyEnabled = false
        minigames.S.autoBountyNewPlayers = false
    end

    return result
end

