------------------------------------------------------------
-- v0.136 wargames activation automation
------------------------------------------------------------
-- when wargames systems / wargames systems - bounty / no-bounties are enabled,
-- automatically enable:
--   1) auto random vehicle rounds
--   2) auto delete empty / destroyed tracked vehicles
------------------------------------------------------------

minigames.WarGames = minigames.WarGames or {}

function minigames.WarGames.SetFeatureToggleV136(hash, enabled)
    if not FeatureMgr or not FeatureMgr.GetFeatureByHash or not hash then
        return false, "feature_mgr_unavailable"
    end

    local ok, feature = direct_call(function()
        return FeatureMgr.GetFeatureByHash(hash)
    end)

    if not ok or not feature then
        return false, "feature_not_found"
    end

    -- different cherax builds expose toggles differently, so try common methods.
    local current = nil
    if feature.IsToggled then
        direct_call(function() current = feature:IsToggled() == true end)
    elseif feature.GetBoolValue then
        direct_call(function() current = feature:GetBoolValue() == true end)
    end

    if current == enabled then
        return true, "already_" .. tostring(enabled)
    end

    if feature.SetToggled then
        local okSet = direct_call(function() feature:SetToggled(enabled == true) end)
        if okSet then return true, "SetToggled" end
    end

    if feature.SetBoolValue then
        local okSet = direct_call(function() feature:SetBoolValue(enabled == true) end)
        if okSet then return true, "SetBoolValue" end
    end

    if feature.Toggle then
        local okToggle = direct_call(function() feature:Toggle() end)
        if okToggle then return true, "Toggle" end
    end

    return false, "no_supported_toggle_method"
end

function minigames.WarGames.ApplyActivationAutomationV136(reason)
    reason = tostring(reason or "WarGames activation")

    -- 1) auto random vehicle rounds
    minigames.S.autoRandomVehicleRounds = true
    minigames.S.autoVehicleRounds = true
    minigames.S.randomVehicleRoundsEnabled = true
    minigames.S.autoRandomRoundsEnabled = true

    local roundStatus = "state_only"
    if minigames.H and minigames.H.WARGAMES_AUTO_RANDOM_VEHICLE_ROUNDS then
        local ok, status = minigames.WarGames.SetFeatureToggleV136(minigames.H.WARGAMES_AUTO_RANDOM_VEHICLE_ROUNDS, true)
        roundStatus = tostring(status or ok)
    end

    -- 2) auto delete empty / destroyed tracked vehicles
    minigames.S.autoTrackedVehicleCleanup = true
    minigames.S.trackedVehicleCleanupEnabled = true
    minigames.S.trackedVehicleCleanupIntervalMs = 180000

    local cleanupStatus = "state_only"
    if minigames.VehicleTracking and minigames.VehicleTracking.ToggleAutoTrackedCleanupV134 then
        local ok, err = direct_call(function()
            minigames.VehicleTracking.ToggleAutoTrackedCleanupV134(true)
        end)
        cleanupStatus = ok and "ToggleAutoTrackedCleanupV134" or ("cleanup_toggle_failed:" .. tostring(err))
    elseif minigames.H and minigames.H.WARGAMES_AUTO_TRACKED_VEHICLE_CLEANUP then
        local ok, status = minigames.WarGames.SetFeatureToggleV136(minigames.H.WARGAMES_AUTO_TRACKED_VEHICLE_CLEANUP, true)
        cleanupStatus = tostring(status or ok)
    end

    minigames.S.lastWarGamesAutomationStatus =
        "Auto Random Rounds ON (" .. tostring(roundStatus) .. ") | " ..
        "Tracked Cleanup ON (" .. tostring(cleanupStatus) .. ") | " ..
        "reason=" .. reason

    if minigames.LogInfo then
        minigames.LogInfo("[WarGames Automation] " .. minigames.S.lastWarGamesAutomationStatus)
    end

    if minigames.Toast then
        minigames.Toast("WarGames Automation", "Random rounds + tracked cleanup enabled.", 4500)
    end
end

function minigames.WarGames.MaybeApplyActivationAutomationV136(reason)
    if minigames.S.autoEnableRandomVehicleRoundsOnWarGames ~= false or minigames.S.autoEnableTrackedCleanupOnWarGames ~= false then
        minigames.WarGames.ApplyActivationAutomationV136(reason)
    end
end


