        local result = __mg140_old_activate_systems(...)
        if minigames.WarGames and minigames.WarGames.DisableCheraxVehicleHelpersV140 then
            minigames.WarGames.DisableCheraxVehicleHelpersV140("Activate WarGames Systems")
        end
        return result
    end
end

