embedded_modules['WarGames\\teleports.lua'] = function()
--[[
    minigames/wargames/teleports.lua
    build: v0.171-alpha

    purpose:
    - wargames teleport locations from .tp files.
    - manual teleport all players to chosen location.
    - vehicle-aware location suggestions for future round automation.

    teleporting is not automatically enabled by activate wargames systems.
]]

minigames.WarGames = minigames.WarGames or {}
minigames.WarGames.Teleports = minigames.WarGames.Teleports or {}

minigames.WarGames.Teleports.Locations = {
    { id = "Docks", label = "Docks", file = "WarGames-Docks.tp", x = 917.07000732, y = -3081.17431641, z = 18.11876678, heading = 352.87442017 },
    { id = "FortZancudoAirstrip", label = "Fort Zancudo Airstrip", file = "WarGames-FortZancudoAirstrip.tp", x = -2014.90356445, y = 2947.03320312, z = 38.25864792, heading = 323.25228882 },
    { id = "GriffithObservatory", label = "Griffith Observatory", file = "WarGames-GriffithObservatory.tp", x = -439.09985352, y = 1074.59765625, z = 355.09365845, heading = 168.90843201 },
    { id = "HumaneLabs", label = "Humane Labs", file = "WarGames-HumaneLabs.tp", x = 3573.62255859, y = 3662.06542969, z = 37.41388321, heading = 76.21700287 },
    { id = "LSIA", label = "LSIA", file = "WarGames-LSIA.tp", x = -1336.19494629, y = -3044.08862305, z = 17.94380569, heading = 146.49903870 },
    { id = "MazeBank", label = "Maze Bank", file = "WarGames-MazeBank.tp", x = -75.24710846, y = -820.61663818, z = 329.71957397, heading = 3.32945704 },
    { id = "MountChilliad", label = "Mount Chiliad", file = "WarGames-MountChilliad.tp", x = 501.97296143, y = 5603.98242188, z = 799.54925537, heading = 1.64618218 },
    { id = "PaletoBayTip", label = "Paleto Bay Tip", file = "WarGames-PaletoBayTip.tp", x = 55.21707535, y = 7246.29443359, z = 2.21558046, heading = 11.07840443 },
    { id = "Pier", label = "Pier", file = "WarGames-Pier.tp", x = -1736.20019531, y = -1113.55529785, z = 15.56037045, heading = 133.38810730 },
    { id = "SandyShoresAirport", label = "Sandy Shores Airport", file = "WarGames-SandyShoresAirport.tp", x = 1700.88024902, y = 3291.83471680, z = 56.98052979, heading = 124.39339447 },
    { id = "SouthCentral", label = "South Central", file = "WarGames-SouthCentral.tp", x = 148.07058716, y = -1388.61413574, z = 29.30508804, heading = 66.03376770 }
}

minigames.WarGames.Teleports.VehicleLocationPools = {
    -- aircraft / air vehicles
    Hydra = { "LSIA", "FortZancudoAirstrip", "SandyShoresAirport" },
    Savage = { "LSIA", "FortZancudoAirstrip", "SandyShoresAirport", "HumaneLabs" },

    -- mk2 can work basically anywhere, but rooftops / open high areas are fun.
    OppressorMK2 = { "MazeBank", "GriffithObservatory", "MountChilliad", "LSIA", "Docks", "PaletoBayTip" },

    -- heavy / chaos vehicles
    Khanjali = { "FortZancudoAirstrip", "Docks", "HumaneLabs", "SandyShoresAirport", "SouthCentral" },
    DumpTruck = { "Docks", "SandyShoresAirport", "HumaneLabs", "SouthCentral" },
    Tampa = { "SouthCentral", "Docks", "HumaneLabs", "Pier" },

    -- stunt / car combat
    Scramjet = { "LSIA", "Docks", "Pier", "MazeBank", "GriffithObservatory" },
    Vigilante = { "LSIA", "FortZancudoAirstrip", "SandyShoresAirport", "Docks", "SouthCentral" },
    Deluxo = { "MazeBank", "GriffithObservatory", "LSIA", "Docks", "Pier" },
    Toreador = { "Docks", "Pier", "PaletoBayTip", "LSIA" },
    BR8 = { "LSIA", "SandyShoresAirport", "FortZancudoAirstrip" },
    VetoClassic = { "Pier", "SouthCentral", "Docks", "MazeBank" },

    -- off-road / map exploration
    DuneBuggy = { "MountChilliad", "PaletoBayTip", "SandyShoresAirport", "HumaneLabs" }
}

function minigames.WarGames.GetTeleportById(id)
    id = tostring(id or "")

    for _, location in ipairs(minigames.WarGames.Teleports.Locations or {}) do
        if tostring(location.id) == id then
            return location
        end
    end

    return nil
end

function minigames.WarGames.GetTeleportByIndex(index)
    local locations = minigames.WarGames.Teleports.Locations or {}
    if #locations <= 0 then
        return nil
    end

    index = minigames.ClampInt(index or 1, 1, #locations)
    return locations[index]
end

function minigames.WarGames.GetSelectedTeleport()
    return minigames.WarGames.GetTeleportByIndex(minigames.S.selectedTeleportIndex or 1)
end

function minigames.WarGames.SelectTeleport(index)
    local locations = minigames.WarGames.Teleports.Locations or {}
    if #locations <= 0 then
        return
    end

    minigames.S.selectedTeleportIndex = minigames.ClampInt(index, 1, #locations)
    local location = minigames.WarGames.GetSelectedTeleport()

    minigames.Toast("WarGames Teleport Selected", tostring(location.label), 3500)
    minigames.LogInfo("[WarGames Teleport] Selected: " .. tostring(location.label))
end

function minigames.WarGames.GetRecommendedTeleportForVehicle(vehicle)
    if not vehicle then
        return minigames.WarGames.GetSelectedTeleport()
    end

    local key = tostring(vehicle.shortName or vehicle.id or vehicle.label or "")
    key = key:gsub("%s+", "")

    local pool = minigames.WarGames.Teleports.VehicleLocationPools[key]

    if not pool or #pool <= 0 then
        return minigames.WarGames.GetSelectedTeleport()
    end

    local locationId = pool[math.random(1, #pool)]
    return minigames.WarGames.GetTeleportById(locationId) or minigames.WarGames.GetSelectedTeleport()
end

function minigames.WarGames.TeleportAllToSelected(reason)
    local location = minigames.WarGames.GetSelectedTeleport()

    if not location then
        minigames.Toast("WarGames Teleport", "No teleport location selected.", 4000)
        return
    end

    minigames.TeleportAllPlayersToLocation(
        location,
        minigames.S.teleportAllPlayersIntoVehicle == true,
        tostring(reason or "Manual selected teleport")
    )
end

function minigames.WarGames.TeleportAllToRecommendedForCurrentRound(reason)
    local vehicle = nil

    if minigames.WarGames.GetCurrentRoundVehicle then
        vehicle = minigames.WarGames.GetCurrentRoundVehicle()
    elseif minigames.WarGames.GetSelectedVehicle then
        vehicle = minigames.WarGames.GetSelectedVehicle()
    end

    local location = minigames.WarGames.GetRecommendedTeleportForVehicle(vehicle)

    if not location then
        minigames.Toast("WarGames Teleport", "No recommended teleport location found.", 4000)
        return
    end

    minigames.TeleportAllPlayersToLocation(
        location,
        minigames.S.teleportAllPlayersIntoVehicle == true,
        tostring(reason or "Recommended round teleport") ..
            " | vehicle=" ..
            tostring(vehicle and vehicle.label or "Unknown")
    )
end

function minigames.WarGames.PrintTeleportDebug()
    minigames.LogInfo("========== WarGames Teleports ==========")
    minigames.LogInfo("Selected index: " .. tostring(minigames.S.selectedTeleportIndex or 1))
    minigames.LogInfo("Auto teleport on round change: " .. tostring(minigames.S.autoTeleportOnVehicleRoundChange))
    minigames.LogInfo("Teleport into vehicle: " .. tostring(minigames.S.teleportAllPlayersIntoVehicle))
    minigames.LogInfo("Teleport stagger ms: " .. tostring(minigames.S.teleportStaggerMs))
    minigames.LogInfo("Last teleport: " .. tostring(minigames.S.lastTeleportStatus))

    for i, location in ipairs(minigames.WarGames.Teleports.Locations or {}) do
        local marker = " "
        if i == (minigames.S.selectedTeleportIndex or 1) then
            marker = "*"
        end

        minigames.LogInfo(
            marker ..
            tostring(i) ..
            " | " ..
            tostring(location.label) ..
            " | " ..
            tostring(location.x) ..
            ", " ..
            tostring(location.y) ..
            ", " ..
            tostring(location.z) ..
            " | heading=" ..
            tostring(location.heading)
        )
    end

    minigames.LogInfo("=======================================")
    minigames.Toast("WarGames Teleports", "Printed teleport debug to log.", 3500)
end


function minigames.WarGames.EnableTeleportRoundMode(enabled)
    minigames.S.teleportRoundModeEnabled = enabled == true

    minigames.Toast(
        "WarGames Teleport Mode",
        minigames.S.teleportRoundModeEnabled and
            "ON - respawn vehicles will use selected/active TP area." or
            "OFF - respawn vehicles spawn in front of players.",
        4500
    )

    minigames.LogInfo("[WarGames Teleport] teleportRoundModeEnabled=" .. tostring(minigames.S.teleportRoundModeEnabled))
end


------------------------------------------------------------
-- v0.103 built-in remote tp default note
------------------------------------------------------------
-- mg.teleportallplayerstolocation is overridden in systems/teleport.lua.
-- wargames manual/recommended teleport buttons keep calling:
--   mg.teleportallplayerstolocation(location, includevehicle, reason)
-- but now that public function uses built-in remote tp first by default.
------------------------------------------------------------
end

