-- v0.074:
-- dedicated lightweight ontick renderer for the small minigames status hud.
local minigamesHudRendererFeature = FeatureMgr.AddFeature(
    minigames.H.MG_STATUS_HUD_RENDERER,
    "Internal Minigames HUD Renderer",
    eFeatureType.Toggle,
    "Internal lightweight renderer for the on-screen Minigames status box.",
    function(f)
        if f:IsToggled() and minigames.DrawMinigamesHud then
            -- v0.085:
            -- internal hud renderer must never call imgui-based hud modes.
            -- the red in-game hud is native draw only; menu controls are separate.
            if minigames.S then
                minigames.S.actualHudMode = 1
            end

            local ok, err = direct_call(function()
                minigames.DrawMinigamesHud()
            end)

            if not ok then
                if minigames.S then
                    minigames.S.actualHudMode = 1
                    minigames.S.compactHudEnabled = false
                end

                if minigames.LogError then
                    minigames.LogError("[Safe HUD] Disabled compact HUD after renderer error: " .. tostring(err))
                end
            end
        end

        return true
    end
)

if minigamesHudRendererFeature and minigamesHudRendererFeature.RegisterCallbackTrigger and eCallbackTrigger and eCallbackTrigger.OnTick then
    minigamesHudRendererFeature:RegisterCallbackTrigger(eCallbackTrigger.OnTick)
end

if minigamesHudRendererFeature and minigamesHudRendererFeature.SetDefaultValue then
    minigamesHudRendererFeature:SetDefaultValue(true):Reset()
end


