FeatureMgr.AddFeature(minigames.H.WARGAMES_PREVIOUS_VEHICLE, "Previous WarGames Vehicle", eFeatureType.Button, "Select previous WarGames vehicle.", function()
    local ok, err = direct_call_trace(function()
        if minigames.WarGames and minigames.WarGames.PreviousVehicle then
            minigames.WarGames.PreviousVehicle()
        end
    end, debug and debug.traceback or function(e) return tostring(e) end)

    if not ok then
        minigames.S.lastVehicleRoundStatus = "Previous vehicle button error swallowed: " .. tostring(err)
        minigames.LogError("[WarGames Vehicles] " .. minigames.S.lastVehicleRoundStatus)
    end
end)
FeatureMgr.AddFeature(minigames.H.WARGAMES_NEXT_VEHICLE, "Next WarGames Vehicle", eFeatureType.Button, "Select next WarGames vehicle.", function()
    local ok, err = direct_call_trace(function()
        if minigames.WarGames and minigames.WarGames.NextVehicle then
            minigames.WarGames.NextVehicle()
        end
    end, debug and debug.traceback or function(e) return tostring(e) end)

    if not ok then
        minigames.S.lastVehicleRoundStatus = "Next vehicle button error swallowed: " .. tostring(err)
        minigames.LogError("[WarGames Vehicles] " .. minigames.S.lastVehicleRoundStatus)
    end
end)

for i, vehicle in ipairs(minigames.WarGames.VehiclePool) do
    -- lock loop values into locals before creating callbacks.
    local vehicleIndex = i
    local vehicleLabel =
        tostring(vehicle.label or ("Vehicle " .. tostring(i)))
    local vehicleModel =
        tostring(vehicle.model or "unknown")
    local isVigilante =
        vehicleModel:lower() == "vigilante" or
        vehicleLabel:lower() == "vigilante"

    minigames.H.WARGAMES_VEHICLE_BUTTONS[vehicleIndex] =
        minigames.Hash(
            "WarGames_VehicleButton_Exact_" ..
            tostring(vehicleIndex) ..
            "_" .. vehicleLabel
        )

    local description =
        "Selects exactly " .. vehicleLabel ..
        " as the active round vehicle. Model: " ..
        vehicleModel

    if isVigilante then
        description =
            "Selects Vigilante and immediately force-spawns it " ..
            "for every active player."
    end

    FeatureMgr.AddFeature(
        minigames.H.WARGAMES_VEHICLE_BUTTONS[vehicleIndex],
        "Use " .. vehicleLabel,
        eFeatureType.Button,
        description,
        function()
            if isVigilante and
                minigames.WarGames and
                minigames.WarGames.SpawnVigilanteToAllV160 then
                local okSpawn, spawnStatus =
                    minigames.WarGames.SpawnVigilanteToAllV160(
                        "Use Vigilante Button"
                    )

                minigames.LogInfo(
                    "[WarGames Vehicles] Vigilante button pressed" ..
                    " | queued=" .. tostring(okSpawn) ..
                    " | status=" .. tostring(spawnStatus)
                )

                return
            end

            local okSelect, errSelect = direct_call_trace(function()
                if minigames.WarGames and
                    minigames.WarGames.SelectVehicleExact then
                    minigames.WarGames.SelectVehicleExact(
                        vehicleIndex,
                        vehicleLabel
                    )
                elseif minigames.WarGames and
                    minigames.WarGames.SelectVehicle then
                    minigames.WarGames.SelectVehicle(vehicleIndex)
                end
            end, debug and debug.traceback or
                function(e) return tostring(e) end)

            if not okSelect then
                minigames.S.lastVehicleRoundStatus =
                    "Exact vehicle button error swallowed | index=" ..
                    tostring(vehicleIndex) ..
                    " | label=" ..
                    tostring(vehicleLabel) ..
                    " | error=" ..
                    tostring(errSelect)

                minigames.LogError(
                    "[WarGames Vehicles] " ..
                    minigames.S.lastVehicleRoundStatus
                )
            else
                minigames.LogInfo(
                    "[WarGames Vehicles] Exact button pressed | index=" ..
                    tostring(vehicleIndex) ..
                    " | label=" ..
                    tostring(vehicleLabel) ..
                    " | model=" ..
                    tostring(vehicleModel)
                )
            end
        end
    )
end


