-- v0.067:
-- this is the only lightweight system ontick. it runs timed scheduler checks.
-- heavy wargames work is gated inside systems/scheduler.lua.
local schedulerFeature = FeatureMgr.AddFeature(
    minigames.H.MG_INTERNAL_SCHEDULER,
    "Internal Minigames Scheduler Status",
    eFeatureType.Toggle,
    "Status toggle only. v0.099 runs the real scheduler in a background queued job instead of an OnTick feature callback.",
    function(f)
        local toggled = false
        direct_call(function()
            toggled = f:IsToggled() == true
        end)

        minigames.S.schedulerMenuToggle = toggled
        minigames.S.schedulerBackgroundEnabled = toggled

        if toggled and minigames.Scheduler and minigames.Scheduler.StartBackgroundLoop then
            minigames.Scheduler.StartBackgroundLoop()
        end

        return true
    end
)

if schedulerFeature and schedulerFeature.SetDefaultValue then
    schedulerFeature:SetDefaultValue(true):Reset()
end

