minigames.AddToggleOnTick(
    minigames.H.WARGAMES_AUTO_BOUNTY_TICK,
    "Auto Maintain Bounties Every 60 Seconds",
    "Uses the exact working Force Bounties To All action immediately, then every 60 seconds.",
    function(f)
        local toggled = f:IsToggled()
        local wasToggled =
            minigames.S.autoForceBountyToggleWasOnV159 == true

        minigames.S.autoBountyRunning = toggled
        minigames.S.autoBountyEnabled = toggled
        minigames.S.autoForceBountyMaintainEnabledV159 = toggled
        minigames.S.autoBountyNewPlayers = toggled

        if minigames.H.AUTO_BOUNTY_NEW_PLAYERS and minigames.SetFeatureBool then
            minigames.SetFeatureBool(
                minigames.H.AUTO_BOUNTY_NEW_PLAYERS,
                toggled
            )
        end

        if toggled then
            minigames.S.wargamesNoBountyMode = false

            if not wasToggled then
                minigames.S.lastAutoBountyTickMs = 0

                if minigames.WarGames and
                    minigames.WarGames.RunForceBountyMaintainNowV159 then
                    minigames.WarGames.RunForceBountyMaintainNowV159(
                        "Auto Maintain toggle enabled"
                    )
                end
            end
        end

        minigames.S.autoForceBountyToggleWasOnV159 = toggled

        minigames.LogInfo(
            "[WarGames Bounty] Auto Maintain toggle=" ..
            tostring(toggled) ..
            " | method=Force Bounties To All" ..
            " | interval=60s"
        )

        return true
    end,
    false
)

