FeatureMgr.AddFeature(
    minigames.H.WARGAMES_PRINT_RESPAWN_STATUS,
    "Print Respawn Status",
    eFeatureType.Button,
    "Prints current respawn watcher status to the Cherax log.",
    function()
        local players = minigames.GetActivePlayers and minigames.GetActivePlayers() or {}
        if minigames.PrintRespawnStatusV110 then minigames.PrintRespawnStatusV110() end
        minigames.LogInfo(
            "[Respawn Status] version=v0.171-alpha | players=" ..
            tostring(#players) ..
            " | watcher=" ..
            tostring(minigames.S.respawnWatcherRunning) ..
            " | spawnOnRespawn=" ..
            tostring(minigames.S.spawnVehiclesOnRespawn) ..
            " | mainToggle=" ..
            tostring(minigames.S.spawnVehicleOnPlayerRespawn) ..
            " | bountyInterval=" ..
            tostring(minigames.S.autoBountyIntervalMs) ..
            " | posFallback=" .. tostring(minigames.S.enableRespawnPositionJumpFallback) ..
            " | pedFallback=" .. tostring(minigames.S.enableRespawnPedChangeFallback) ..
            " | remoteRespawn=" .. tostring(minigames.S.spawnRespawnVehiclesForRemotePlayers)
        )

        if minigames.Player and minigames.Player.respawnDeathSerial then
            for _, playerId in ipairs(players) do
                playerId = minigames.ClampInt(playerId, 0, 31)
                minigames.LogInfo(
                    "[Respawn Status] player=" ..
                    tostring(playerId) ..
                    " name=" ..
                    tostring(minigames.GetPlayerName(playerId)) ..
                    " enabled=" ..
                    tostring(minigames.Player.respawnEnabled and minigames.Player.respawnEnabled[playerId]) ..
                    " serial=" ..
                    tostring(minigames.Player.respawnDeathSerial[playerId]) ..
                    " phase=" ..
                    tostring(minigames.Player.respawnPhase and minigames.Player.respawnPhase[playerId])
                )
            end
        end

        minigames.Toast("Respawn Status", "Printed respawn watcher status to log.", 4000)
    end
)


