minigames.AddToggle(
    minigames.H.WARGAMES_NO_COPS_TOGGLE,
    "No Cops / Turn Blind Eye",
    "Keeps cops from ruining WarGames. Automatically enabled by WarGames Systems. Strongest for local player; best-effort for others.",
    function(f)
        minigames.S.noCopsEnabled = f:IsToggled()

        if f:IsToggled() then
            if minigames.Peacekeeper and minigames.Peacekeeper.ApplyToAll then
                minigames.Peacekeeper.ApplyToAll("Manual Toggle ON")
            end
            minigames.Toast("WarGames Peacekeeper", "No Cops / Turn Blind Eye ON.", 4500)
        else
            if minigames.Peacekeeper and minigames.Peacekeeper.DisableLocal then
                minigames.Peacekeeper.DisableLocal("Manual Toggle OFF")
            end
            minigames.Toast("WarGames Peacekeeper", "No Cops / Turn Blind Eye OFF locally.", 4500)
        end
    end,
    false
)

