function minigames.WarGames.RefreshWarGamesUiSettings()
    if minigames.GetFeatureInt then
        minigames.S.vehicleCleanupMs = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.WARGAMES_VEHICLE_CLEANUP_MS, minigames.S.vehicleCleanupMs or 120000), 30000, 600000)
        minigames.S.vehicleCleanupScanMs = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.WARGAMES_VEHICLE_CLEANUP_SCAN_MS, minigames.S.vehicleCleanupScanMs or 5000), 1000, 60000)
        minigames.S.weaponCleanupScanMs = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.WARGAMES_WEAPON_CLEANUP_SCAN_MS, minigames.S.weaponCleanupScanMs or 300000), 60000, 900000)
        minigames.S.peacekeeperScanMs = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.WARGAMES_PEACEKEEPER_SCAN_MS, minigames.S.peacekeeperScanMs or 1000), 250, 10000)
        minigames.S.peacekeeperRemoteApplyMs = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.WARGAMES_PEACEKEEPER_REMOTE_MS, minigames.S.peacekeeperRemoteApplyMs or 15000), 5000, 120000)
        minigames.S.vehicleRoundTimeMs = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.WARGAMES_VEHICLE_ROUND_TIME_MS, minigames.S.vehicleRoundTimeMs or 180000), 30000, 900000)
        minigames.S.selectedTeleportIndex = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.WARGAMES_SELECTED_TELEPORT_INDEX, minigames.S.selectedTeleportIndex or 1), 1, #(minigames.WarGames.Teleports and minigames.WarGames.Teleports.Locations or { 1 }))
        minigames.S.teleportStaggerMs = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.WARGAMES_TELEPORT_STAGGER_MS, minigames.S.teleportStaggerMs or 350), 0, 5000)
    end
end


