-- wargames subtab ui
------------------------------------------------------------
-- v0.070:
-- wargames grew into a full lobby framework, so the old single
-- vertical page has been split into subtabs to stop endless scrolling.
------------------------------------------------------------

function minigames.WarGames.RenderMainTab(activeRound, previousLabel)
    if ClickGUI.BeginCustomChildWindow("WarGames Activation") then
        ClickGUI.RenderFeature(minigames.H.MG_RESET_INTRO)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_ACTIVATE_SYSTEMS)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_ACTIVATE_SYSTEMS_NO_BOUNTIES)
                    ClickGUI.RenderFeature(minigames.H.WARGAMES_SPAWN_VEHICLE_ON_PLAYER_RESPAWN)
                    ClickGUI.RenderFeature(minigames.H.WARGAMES_PRINT_RESPAWN_STATUS)
                    ClickGUI.RenderFeature(minigames.H.WARGAMES_POSITION_FALLBACK)
                    ClickGUI.RenderFeature(minigames.H.WARGAMES_PED_FALLBACK)
                    ClickGUI.RenderFeature(minigames.H.WARGAMES_REMOTE_RESPAWN_SPAWNS)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_RESPAWN_TICK)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_AUTO_RANDOM_VEHICLE_ROUNDS)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_SOFT_SYSTEMS_MODE)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_NO_COPS_TOGGLE)

        if ImGui then
            ImGui.Text("Recommended: turn ON Activate WarGames Systems.")
            ImGui.Text("Movement-safe mode keeps weapon/fair cleanup manual.")
            ImGui.Text("No-Bounty Mode: " .. tostring(minigames.S.wargamesNoBountyMode == true))
            ImGui.Text("Active Round Vehicle: " .. tostring(activeRound and activeRound.label or "None"))
            ImGui.Text("Previous Vehicle: " .. tostring(previousLabel))
            ImGui.Text("Round Time: " .. tostring(minigames.S.vehicleRoundTimeMs or 180000) .. "ms")
            ImGui.Text("Last round: " .. tostring(minigames.S.lastVehicleRoundStatus))
            ImGui.Text("Scheduler Error: " .. tostring(minigames.S.lastSchedulerError or "None"))
            ImGui.Text("Systems Error: " .. tostring(minigames.S.lastWarGamesSystemsError or "None"))
        end

        ClickGUI.EndCustomChildWindow()
    end

    if ClickGUI.BeginCustomChildWindow("WarGames Quick Test Buttons") then
        ClickGUI.RenderFeature(minigames.H.WARGAMES_SPAWN_ALL)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_FORCE_SPAWN_ALL)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_ENABLE_RESPAWN_ALL)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_RANDOM_ROUND_NOW)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_NEXT_ROUND_NOW)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_APPLY_NO_COPS_NOW)
        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.WarGames.RenderVehiclesTab(activeRound, previousLabel)
    if ImGui and ImGui.BeginTabBar and ImGui.BeginTabItem then
        if ImGui.BeginTabBar("WarGamesVehicleNestedTabs_v070") then
            if ImGui.BeginTabItem("Round") then
                minigames.WarGames.RenderVehicleRoundPanel(activeRound, previousLabel)
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Spawn") then
                minigames.WarGames.RenderVehicleSpawnPanel(activeRound)
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Buttons") then
                minigames.WarGames.RenderVehicleButtonsPanel()
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Styling") then
                minigames.WarGames.RenderVehicleStylingPanel()
                ImGui.EndTabItem()
            end
            ImGui.EndTabBar()
        end
    else
        minigames.WarGames.RenderVehicleRoundPanel(activeRound, previousLabel)
        minigames.WarGames.RenderVehicleSpawnPanel(activeRound)
        minigames.WarGames.RenderVehicleButtonsPanel()
        minigames.WarGames.RenderVehicleStylingPanel()
    end
end

function minigames.WarGames.RenderVehicleRoundPanel(activeRound, previousLabel)
    if ClickGUI.BeginCustomChildWindow("Vehicle Rounds") then
        ClickGUI.RenderFeature(minigames.H.WARGAMES_AUTO_RANDOM_VEHICLE_ROUNDS)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_VEHICLE_ROUND_TIME_MS)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_RANDOM_ROUND_NOW)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_NEXT_ROUND_NOW)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_DELETE_PREVIOUS_ON_CHANGE)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_DELETE_ALL_INACTIVE_ON_CHANGE)
                    -- v0.119 replaced by pedwars-style cleanup: clickgui.renderfeature(mg.h.wargames_auto_spawn_new_round_to_all)
                    -- v0.119 replaced by pedwars-style cleanup: clickgui.renderfeature(mg.h.wargames_delete_inactive_round_vehicles)

        if ImGui then
            ImGui.Text("Active Round: " .. tostring(activeRound and activeRound.label or "None"))
            ImGui.Text("Previous Vehicle: " .. tostring(previousLabel))
            ImGui.Text("Notification only fires on actual vehicle change.")
            ImGui.Text("Last cleanup: " .. tostring(minigames.S.lastVehicleRoundCleanupStatus))
        end

        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.WarGames.RenderVehicleSpawnPanel(activeRound)
    if ClickGUI.BeginCustomChildWindow("Vehicle Spawn / Player Controls") then
        -- v1.0.2: vehicle controls now follow the shared vehiclepool order.
        -- vigilante is no longer specially pinned ahead of khanjali.
        ClickGUI.RenderFeature(minigames.H.WARGAMES_SELECTED_VEHICLE_INDEX)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_PREVIOUS_VEHICLE)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_NEXT_VEHICLE)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_ROLL_RANDOM_ROUND_VEHICLE)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_PRINT_VEHICLES)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_SPAWN_SELECTED)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_FORCE_SPAWN_SELECTED)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_SPAWN_ALL)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_FORCE_SPAWN_ALL)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_ENABLE_RESPAWN_ALL)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_CLEAR_SELECTED_VEHICLE_TRACKING)

        if ImGui then
            ImGui.Text("Selected: " .. tostring(minigames.WarGames.GetSelectedVehicle().label))
            ImGui.Text("Active Round: " .. tostring(activeRound and activeRound.label or "None"))
            ImGui.Text("Spawn engine: " .. tostring(minigames.SpawnEngineNames[minigames.S.vehicleSpawnEngine]))
        end

        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.WarGames.RenderVehicleButtonsPanel()
    if ClickGUI.BeginCustomChildWindow("Vehicle Buttons") then
        -- v1.0.2: render exactly in vehiclepool order.
        for i, _ in ipairs(minigames.WarGames.VehiclePool or {}) do
            if minigames.H.WARGAMES_VEHICLE_BUTTONS[i] then
                ClickGUI.RenderFeature(
                    minigames.H.WARGAMES_VEHICLE_BUTTONS[i]
                )
            end
        end

        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.WarGames.RenderVehicleStylingPanel()
    if ClickGUI.BeginCustomChildWindow("Vehicle Styling") then
        ClickGUI.RenderFeature(minigames.H.WARGAMES_FORCE_PLATE)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_REMOVE_LIVERIES)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_RANDOMIZE_COLORS)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_RANDOMIZE_WHEEL_SMOKE)
        if ImGui then
            ImGui.Text("Plate: WARGAMES")
            ImGui.Text("Last Color: " .. tostring(minigames.S.lastVehicleColorName or "None"))
            ImGui.Text("Liveries: disabled/removed where native supports it.")
        end
        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.WarGames.RenderBountiesTab()
    if ClickGUI.BeginCustomChildWindow("WarGames Bounties") then
        ClickGUI.RenderFeature(minigames.H.WARGAMES_AUTO_BOUNTY_TICK)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_APPLY_BOUNTY_SELECTED)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_FORCE_BOUNTY_SELECTED)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_APPLY_BOUNTY_ALL)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_FORCE_BOUNTY_ALL)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_PRINT_BOUNTY_DEBUG)
        if ImGui then
            ImGui.Text("No-Bounty Mode: " .. tostring(minigames.S.wargamesNoBountyMode == true))
            ImGui.Text("Auto bounty ticks: " .. tostring(minigames.S.autoBountyTickCount or 0))
            ImGui.Text("Last bounty: " .. tostring(minigames.S.lastBountyStatus or "None"))
        end
        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.WarGames.RenderTeleportsTab()
    if ClickGUI.BeginCustomChildWindow("Teleport Controls") then
        ClickGUI.RenderFeature(minigames.H.WARGAMES_SELECTED_TELEPORT_INDEX)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_TELEPORT_ALL_SELECTED)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_TELEPORT_ALL_RECOMMENDED)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_USE_BUILTIN_REMOTE_TP)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_REMOTE_TP_FALLBACK_DIRECT)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_TEST_REMOTE_MAZE)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_SEARCH_REMOTE_TP)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_TELEPORT_INTO_VEHICLE)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_AUTO_TELEPORT_ON_ROUND_CHANGE)
        if minigames.H.WARGAMES_AUTO_TELEPORT_SELECTED_ROUND then ClickGUI.RenderFeature(minigames.H.WARGAMES_AUTO_TELEPORT_SELECTED_ROUND) end
        ClickGUI.RenderFeature(minigames.H.WARGAMES_TELEPORT_ROUND_MODE)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_TELEPORT_AWARE_RESPAWN)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_SPAWN_AT_TP_AREA)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_TELEPORT_STAGGER_MS)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_PRINT_TELEPORT_DEBUG)

        if ImGui then
            local selectedTp = minigames.WarGames.GetSelectedTeleport and minigames.WarGames.GetSelectedTeleport() or nil
            ImGui.Text("Selected TP: " .. tostring(selectedTp and selectedTp.label or "None"))
            ImGui.Text("Last TP: " .. tostring(minigames.S.lastTeleportStatus))
            ImGui.Text("Teleport Spawn: " .. tostring(minigames.S.lastTeleportSpawnStatus or "None"))
            ImGui.Text("Rule: TP ON = spawn at TP area. TP OFF = spawn in front of players.")
        end

        ClickGUI.EndCustomChildWindow()
    end

    if ClickGUI.BeginCustomChildWindow("Teleport Location Buttons") then
        if minigames.WarGames.Teleports and minigames.WarGames.Teleports.Locations then
            for i, _ in ipairs(minigames.WarGames.Teleports.Locations) do
                ClickGUI.RenderFeature(minigames.H.WARGAMES_TELEPORT_BUTTONS[i])
            end
        end
        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.WarGames.RenderCleanupFairnessTab()
    if ClickGUI.BeginCustomChildWindow("Cleanup / Anti-Spam") then
        ClickGUI.RenderFeature(minigames.H.WARGAMES_AUTO_CLEANUP_VEHICLES)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_CLEANUP_UNUSED_NOW)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_FORCE_DELETE_SPAWNED_VEHICLES)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_VEHICLE_CLEANUP_MS)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_VEHICLE_CLEANUP_SCAN_MS)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_DESTROYED_ONLY_CLEANUP)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_PREVENT_VEHICLE_SPAM)
        if ImGui then
            ImGui.Text("Tracked vehicles: " .. tostring(#(minigames.S.spawnedWarGamesVehicles or {})))
            ImGui.Text("Deleted vehicles: " .. tostring(minigames.S.deletedWarGamesVehicleCount or 0))
            ImGui.Text("Vehicle cleanup: " .. tostring(minigames.S.lastVehicleCleanupStatus))
            ImGui.Text("Destroyed-only cleanup: " .. tostring(minigames.S.destroyedOnlyVehicleCleanup))
            ImGui.Text("Anti-spam vehicles: " .. tostring(minigames.S.preventRespawnVehicleSpam))
        end
        ClickGUI.EndCustomChildWindow()
    end

    if ClickGUI.BeginCustomChildWindow("Weapons / Fairness / No Cops") then
        ClickGUI.RenderFeature(minigames.H.WARGAMES_AUTO_REMOVE_RESTRICTED_WEAPONS)

                    ClickGUI.RenderFeature(minigames.H.WARGAMES_PEDWARS_CLEANUP_ENABLE)
                    ClickGUI.RenderFeature(minigames.H.WARGAMES_PEDWARS_CLEANUP_ABANDONED)
                    ClickGUI.RenderFeature(minigames.H.WARGAMES_PEDWARS_CLEANUP_SCAN)
                    ClickGUI.RenderFeature(minigames.H.WARGAMES_PEDWARS_CLEANUP_PROCESS)
                    ClickGUI.RenderFeature(minigames.H.WARGAMES_PEDWARS_CLEANUP_STATUS)

        ClickGUI.RenderFeature(minigames.H.WARGAMES_REMOVE_RESTRICTED_WEAPONS_NOW)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_REMOVE_ALL_WEAPONS_NOW)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_WEAPON_CLEANUP_SCAN_MS)
                    -- v0.119 replaced by pedwars-style cleanup: clickgui.renderfeature(mg.h.wargames_auto_fair_enforcement)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_DELETE_AIRCRAFT_GRIEF)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_NO_COPS_TOGGLE)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_APPLY_NO_COPS_NOW)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_DISABLE_NO_COPS_LOCAL)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_PEACEKEEPER_SCAN_MS)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_PEACEKEEPER_REMOTE_MS)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_PRINT_PEACEKEEPER_DEBUG)
        if ImGui then
            ImGui.Text("Weapon cleanup: " .. tostring(minigames.S.lastWeaponCleanupStatus))
            ImGui.Text("Fair scan: " .. tostring(minigames.S.lastFairVehicleStatus))
            ImGui.Text("Peacekeeper: " .. tostring(minigames.S.lastPeacekeeperStatus))
        end
        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.WarGames.RenderPerksTab()
    if ClickGUI.BeginCustomChildWindow("Loyalty Perks") then
        ClickGUI.RenderFeature(minigames.H.WARGAMES_LOYALTY_PERKS)
