            ImGui.Text("1 hour = 3 min vehicle god mode")
            ImGui.Text("2 hours = 5 min vehicle god mode")
            ImGui.Text("3 hours = 10 min vehicle god mode")
            ImGui.Text("Loyalty: " .. tostring(minigames.S.lastLoyaltyStatus or "None"))
        end
        ClickGUI.EndCustomChildWindow()
