end

function minigames.WarGames.RenderDebugTab()
    if ClickGUI.BeginCustomChildWindow("Debug / Tracking") then
        ClickGUI.RenderFeature(minigames.H.WARGAMES_ENABLE_RESPAWN_ALL)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_CLEAR_ALL_VEHICLE_TRACKING)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_PRINT_DEBUG)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_PRINT_RESPAWN_DEBUG)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_PRINT_BOUNTY_DEBUG)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_PRINT_TELEPORT_DEBUG)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_PRINT_PEACEKEEPER_DEBUG)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_PRINT_LOYALTY_DEBUG)

        if ImGui then
            ImGui.Text("Tracked players:")
            for _, playerId in ipairs(minigames.S.activePlayers or {}) do
                ImGui.Text(
                    "[" .. tostring(playerId) .. "] " .. minigames.GetPlayerName(playerId) ..
                    " | vehicle=" .. tostring(minigames.Player.vehicleEnabled[playerId] == true) ..
                    " | wasDead=" .. tostring(minigames.Player.wasDead[playerId] == true) ..
                    " | bountyTracked=" .. tostring(minigames.Player.bountyApplied[playerId] == true)
                )
            end
        end

        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.WarGames.RenderCreditsTab()
    if ClickGUI.BeginCustomChildWindow("Credits / References") then
        if ImGui then
            ImGui.Text("MINIGAMES / WARGAMES")
            ImGui.Text("Turn the lobby into your personal playground.")
            ImGui.Text("")
            ImGui.Text("Developer: " .. tostring(minigames.AUTHOR or "Animus"))
            ImGui.Text("Build help: " .. tostring(minigames.HELP or "ChatGPT"))
            ImGui.Text("")
            ImGui.Text("External references and Lua files studied with love:")
            for i, credit in ipairs(minigames.Credits or {}) do
                ImGui.Text(tostring(i) .. ". " .. tostring(credit.title) .. " - " .. tostring(credit.name))
                ImGui.Text("   " .. tostring(credit.note))
            end
            ImGui.Text("")
            ImGui.Text("Special love to Kektram / Kek's Menu Lua files. This project would not have been possible without studying those helper patterns.")
            ImGui.Text("Respect to Cherax for the Lua API and runtime this is built on.")
        end
        ClickGUI.RenderFeature(minigames.H.CREDITS)
        ClickGUI.EndCustomChildWindow()
    end
end

function minigames.WarGames.RenderUI()
    minigames.WarGames.RefreshWarGamesUiSettings()

    local activeRound = minigames.WarGames.GetCurrentRoundVehicle and minigames.WarGames.GetCurrentRoundVehicle() or minigames.WarGames.GetSelectedVehicle()
    local previousLabel = minigames.GetVehicleLabelByIndex and minigames.GetVehicleLabelByIndex(minigames.S.previousRoundVehicleIndex or minigames.S.roundVehicleIndex or 1) or "None"

    if ImGui and ImGui.BeginTabBar and ImGui.BeginTabItem then
        if ImGui.BeginTabBar("WarGames_Subtabs_v070") then
            if ImGui.BeginTabItem("Main") then
                minigames.WarGames.RenderMainTab(activeRound, previousLabel)
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Vehicles") then
                minigames.WarGames.RenderVehiclesTab(activeRound, previousLabel)
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Bounties") then
                minigames.WarGames.RenderBountiesTab()
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Teleports") then
                minigames.WarGames.RenderTeleportsTab()
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Cleanup / Fairness") then
                minigames.WarGames.RenderCleanupFairnessTab()
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Perks") then
                minigames.WarGames.RenderPerksTab()
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Debug") then
                minigames.WarGames.RenderDebugTab()
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Credits") then
                minigames.WarGames.RenderCreditsTab()
                ImGui.EndTabItem()
            end
            ImGui.EndTabBar()
        end
    else
        -- fallback for cherax builds without imgui tab-bar bindings.
        minigames.WarGames.RenderMainTab(activeRound, previousLabel)
        minigames.WarGames.RenderVehiclesTab(activeRound, previousLabel)
        minigames.WarGames.RenderBountiesTab()
        minigames.WarGames.RenderTeleportsTab()
        minigames.WarGames.RenderCleanupFairnessTab()
        minigames.WarGames.RenderPerksTab()
        minigames.WarGames.RenderDebugTab()
        minigames.WarGames.RenderCreditsTab()
    end
end


minigames.AddToggle(
    minigames.H.WARGAMES_SPAWN_VEHICLE_ON_PLAYER_RESPAWN,
    "Spawn Vehicle On Player Respawn",
    "Automatically spawns the selected WarGames vehicle for a player after they die and respawn. Uses the same proven method as Force WarGames Vehicle Spawn For All.",
    function(f)
        minigames.WarGames.SetSpawnVehicleOnPlayerRespawn(f:IsToggled(), "Main Toggle")
    end,
    true
)


------------------------------------------------------------
-- v0.110 print respawn status override
------------------------------------------------------------
if FeatureMgr and minigames.H and minigames.H.WARGAMES_PRINT_RESPAWN_STATUS then
    -- some builds already created this feature above. if duplicate creation is blocked by cherax,
    -- the existing status button still works; this function is mainly here for the newer log format.
    minigames.PrintRespawnStatusV110 = function()
        local players, localId = {}, 0
        if minigames.WarGames and minigames.WarGames.GetRespawnWatchPlayers then
            players, localId = minigames.WarGames.GetRespawnWatchPlayers()
        end

        minigames.LogInfo(
            "[Respawn Status v0.110] players=" ..
            tostring(#players) ..
            " | localId=" ..
            tostring(localId) ..
            " | watcher=" ..
            tostring(minigames.S.respawnWatcherRunning) ..
            " | spawnOnRespawn=" ..
            tostring(minigames.S.spawnVehiclesOnRespawn) ..
            " | mainToggle=" ..
            tostring(minigames.S.spawnVehicleOnPlayerRespawn) ..
            " | remoteRespawn=" ..
            tostring(minigames.S.spawnRespawnVehiclesForRemotePlayers) ..
            " | bountyInterval=" ..
            tostring(minigames.S.autoBountyIntervalMs)
        )
    end
end


------------------------------------------------------------
-- v0.111 respawn stability status helper
------------------------------------------------------------
minigames.PrintRespawnStabilityV111 = function()
    local activeRespawn = 0
    if minigames.Player and minigames.Player.activeRespawnVehicle then
        for _, _ in pairs(minigames.Player.activeRespawnVehicle) do
            activeRespawn = activeRespawn + 1
        end
    end

    minigames.LogInfo(
        "[Respawn Stability v0.111] activeRespawnVehicles=" ..
        tostring(activeRespawn) ..
        " | watchdog=" ..
        tostring(minigames.S.respawnWatchdogEnabled) ..
        " | deletePrevious=" ..
        tostring(minigames.S.deletePreviousRespawnVehicleForPlayer) ..
        " | lastWatcherTickMs=" ..
        tostring(minigames.S.lastRespawnWatcherTickMs)
    )
end


------------------------------------------------------------
-- v0.117 safe defaults status helper
------------------------------------------------------------
minigames.PrintSafeRespawnDefaultsV117 = function()
    minigames.LogInfo(
        "[v0.117 Safe Defaults] " ..
        "remoteRespawn=" .. tostring(minigames.S.spawnRespawnVehiclesForRemotePlayers) ..
        " | autoSpawnAll=" .. tostring(minigames.S.autoSpawnNewRoundVehicleToAll or minigames.S.autoSpawnRoundVehicleToAll or minigames.S.autoSpawnAllOnRoundChange) ..
        " | deletePrevType=" .. tostring(minigames.S.deletePreviousVehicleTypeOnChange or minigames.S.deletePreviousRoundVehicleOnChange) ..
        " | inactiveCleanup=" .. tostring(minigames.S.deleteAllInactiveRoundVehicles) ..
        " | emptyCleanup=" .. tostring(minigames.S.autoDeleteEmptySpawnedVehicles or minigames.S.autoCleanupEmptySpawnedVehicles) ..
        " | destroyedOnly=" .. tostring(minigames.S.destroyedOnlyVehicleCleanup or minigames.S.cleanupDestroyedOnlyVehicles) ..
        " | spamPrevention=" .. tostring(minigames.S.preventRespawnVehicleSpam) ..
        " | restrictedWeapons=" .. tostring(minigames.S.autoRemoveRestrictedWeapons or minigames.S.autoRestrictedWeaponCleanup) ..
        " | fairEnforcement=" .. tostring(minigames.S.autoFairVehicleEnforcement or minigames.S.fairVehicleEnforcementEnabled)
    )
end


------------------------------------------------------------
-- v0.118 pedwars-style cleanup ui
------------------------------------------------------------
minigames.AddToggle(
    minigames.H.WARGAMES_PEDWARS_CLEANUP_ENABLE,
    "PedWars-Style Cleanup Engine",
    "Replacement cleanup engine. Scans tracked WarGames vehicles, queues safe deletes slowly, and avoids same-frame spawn/delete interference.",
    function(f)
        minigames.S.pedwarsCleanupEnabled = f:IsToggled()
        if minigames.PWCleanup and minigames.PWCleanup.Status then
            minigames.PWCleanup.Status()
        end
    end,
    false
)

minigames.AddToggle(
