------------------------------------------------------------
-- v0.133 wargames ui cleanup / removed options
------------------------------------------------------------
-- goal:
-- hide unused/risky ui options without ripping out backend functions that other
-- systems may still call internally.
--
-- removed from visible ui:
-- round:
--   delete previous vehicle type on change
--   delete all inactive round vehicles
--
-- vehicles / spawn:
--   print wargames vehicles
--   spawn wargames vehicle on selected player
--   test: spawn wargames vehicles to all
--   enable respawn vehicles for all current players
--
-- cleanup / fairness:
--   old cleanup / anti-spam block
--   pedwars cleanup tester buttons
--   apply no cops to all now
--   disable no cops locally
--   peacekeeper advanced scan/debug controls
--
-- kept in cleanup / fairness:
--   auto remove restricted weapons
--   remove restricted weapons from all players
--   remove all weapons from all players
--   delete grief aircraft / rc vehicles
--   no cops / turn blind eye
------------------------------------------------------------

minigames.S.removedWarGamesUiOptionsV133 = true

function minigames.WarGames.ApplyV133SafetyDefaults()
    -- legacy round cleanup: removed from ui and forced off.
    minigames.S.deletePreviousVehicleTypeOnChange = false
    minigames.S.deletePreviousRoundVehicleOnChange = false
    minigames.S.deletePreviousRoundVehiclesOnChange = false
    minigames.S.deleteAllInactiveRoundVehicles = false
    minigames.S.deleteAllInactiveOnChange = false

    -- legacy cleanup/anti-spam: removed from ui and forced off.
    minigames.S.autoCleanupVehicles = false
    minigames.S.autoDeleteEmptySpawnedVehicles = false
    minigames.S.autoCleanupEmptySpawnedVehicles = false
    minigames.S.destroyedOnlyVehicleCleanup = false
    minigames.S.preventRespawnVehicleSpam = false
    minigames.S.autoFairVehicleEnforcement = false
    minigames.S.fairVehicleEnforcementEnabled = false
    minigames.S.pedwarsCleanupEnabled = false
    minigames.S.pedwarsCleanupDeleteAbandoned = false

    -- auto-spawn-all helpers stay off.
    minigames.S.autoSpawnNewRoundVehicleToAll = false
    minigames.S.autoSpawnRoundVehicleToAll = false
    minigames.S.autoSpawnAllOnRoundChange = false
end

minigames.WarGames.ApplyV133SafetyDefaults()

-- combined no cops behavior:
-- this one visible toggle replaces:
--   no cops / turn blind eye
--   apply no cops to all now
--   disable no cops locally
--
-- on  = apply best-effort no-cops to all
-- off = disable local no-cops
function minigames.WarGames.SetNoCopsCombinedV133(enabled, reason)
    minigames.S.noCopsEnabled = enabled == true

    if enabled == true then
        if minigames.Peacekeeper and minigames.Peacekeeper.ApplyToAll then
            local ok, applied, failed, skipped = direct_call(function()
                return minigames.Peacekeeper.ApplyToAll(reason or "Combined No Cops Toggle ON")
            end)

            if ok then
                minigames.S.lastPeacekeeperStatus =
                    "Combined No Cops ON | applied=" ..
                    tostring(applied) ..
                    " failed=" ..
                    tostring(failed) ..
                    " skipped=" ..
                    tostring(skipped)
            else
                minigames.S.lastPeacekeeperStatus = "Combined No Cops ON failed: " .. tostring(applied)
            end
        else
            minigames.S.lastPeacekeeperStatus = "Combined No Cops ON | Peacekeeper.ApplyToAll unavailable"
        end

        if minigames.Toast then
            minigames.Toast("WarGames Peacekeeper", "No Cops / Turn Blind Eye ON for all where supported.", 4500)
        end
    else
        if minigames.Peacekeeper and minigames.Peacekeeper.DisableLocal then
            direct_call(function()
                minigames.Peacekeeper.DisableLocal(reason or "Combined No Cops Toggle OFF")
            end)
        end

        minigames.S.lastPeacekeeperStatus = "Combined No Cops OFF locally."

        if minigames.Toast then
            minigames.Toast("WarGames Peacekeeper", "No Cops / Turn Blind Eye OFF locally.", 4500)
        end
    end
end

-- override the visible feature callback by adding a safe wrapper if the feature exists.
function minigames.WarGames.RefreshNoCopsCombinedV133()
    if FeatureMgr and FeatureMgr.GetFeatureByHash and minigames.H and minigames.H.WARGAMES_NO_COPS_TOGGLE then
        local ok, feature = direct_call(function()
            return FeatureMgr.GetFeatureByHash(minigames.H.WARGAMES_NO_COPS_TOGGLE)
        end)

        -- cherax lua builds vary; not all expose mutable callback replacement.
        -- the original callback already does the desired combined behavior:
        -- on applytoall, off disablelocal.
        -- this function is here for explicit state sync/logging.
        if ok and feature and feature.IsToggled then
            local toggled = false
            direct_call(function() toggled = feature:IsToggled() == true end)
            minigames.S.noCopsEnabled = toggled
        end
    end
end

