function minigames.WarGames.RenderInfantryTab()
    if minigames.GetFeatureInt then
        minigames.S.infantryLoadoutMode = minigames.ClampInt(minigames.GetFeatureInt(minigames.H.WARGAMES_INFANTRY_LOADOUT, minigames.S.infantryLoadoutMode or 1), 1, 4)
    end

    if ClickGUI.BeginCustomChildWindow("Infantry WarGames") then
        ClickGUI.RenderFeature(minigames.H.WARGAMES_INFANTRY_ENABLE)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_INFANTRY_LOADOUT)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_INFANTRY_AUTO_ENFORCE)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_INFANTRY_APPLY_NOW)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_INFANTRY_RESTORE_NOW)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_INFANTRY_STATUS)

        if ImGui then
            local mode = minigames.S.infantryLoadoutMode or 1
            local modeName = minigames.WarGames.Infantry and minigames.WarGames.Infantry.LoadoutNames and minigames.WarGames.Infantry.LoadoutNames[mode] or tostring(mode)
            ImGui.Text("Loadout: " .. tostring(modeName))
            ImGui.Text("Last: " .. tostring(minigames.S.infantryLastStatus or "None"))
            ImGui.Text("Saved weapon snapshots: " .. tostring(minigames.S.infantrySavedWeapons and "active" or "none"))
        end

        ClickGUI.EndCustomChildWindow()
    end

    if ClickGUI.BeginCustomChildWindow("Infantry Vehicles") then
        ClickGUI.RenderFeature(minigames.H.WARGAMES_INFANTRY_BLOCK_VEHICLES)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_INFANTRY_KICK_VEHICLES)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_INFANTRY_HARD_DELETE_VEHICLES)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_INFANTRY_REMOVE_VEHICLES_NOW)
        ClickGUI.RenderFeature(minigames.H.WARGAMES_INFANTRY_RESTORE_ON_DISABLE)

        if ImGui then
            ImGui.Text("Hard Delete is OFF by default for the v0.141 stable base.")
            ImGui.Text("Vehicle spawns blocked: " .. tostring(minigames.S.infantryBlockVehicleSpawns == true))
            ImGui.Text("Last vehicle block: " .. tostring(minigames.S.infantryLastVehicleBlockStatus or "None"))
        end

        ClickGUI.EndCustomChildWindow()
    end
end

