-- rebuild wargames tabs with the new infantry tab.
function minigames.WarGames.RenderUI()
    minigames.WarGames.RefreshWarGamesUiSettings()

    local activeRound = minigames.WarGames.GetCurrentRoundVehicle and minigames.WarGames.GetCurrentRoundVehicle() or minigames.WarGames.GetSelectedVehicle()
    local previousLabel = minigames.GetVehicleLabelByIndex and minigames.GetVehicleLabelByIndex(minigames.S.previousRoundVehicleIndex or minigames.S.roundVehicleIndex or 1) or "None"

    if ImGui and ImGui.BeginTabBar and ImGui.BeginTabItem then
        if ImGui.BeginTabBar("WarGames_Subtabs_v150") then
            if ImGui.BeginTabItem("Main") then
                minigames.WarGames.RenderMainTab(activeRound, previousLabel)
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Vehicles") then
                minigames.WarGames.RenderVehiclesTab(activeRound, previousLabel)
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Bounties") then
                minigames.WarGames.RenderBountiesTab()
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Teleports") then
                minigames.WarGames.RenderTeleportsTab()
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Infantry") then
                minigames.WarGames.RenderInfantryTab()
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Cleanup / Fairness") then
                minigames.WarGames.RenderCleanupFairnessTab()
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Perks") then
                minigames.WarGames.RenderPerksTab()
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Debug") then
                minigames.WarGames.RenderDebugTab()
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Credits") then
                minigames.WarGames.RenderCreditsTab()
                ImGui.EndTabItem()
            end
            ImGui.EndTabBar()
        end
    else
        minigames.WarGames.RenderMainTab(activeRound, previousLabel)
        minigames.WarGames.RenderVehiclesTab(activeRound, previousLabel)
        minigames.WarGames.RenderBountiesTab()
        minigames.WarGames.RenderTeleportsTab()
        minigames.WarGames.RenderInfantryTab()
        minigames.WarGames.RenderCleanupFairnessTab()
        minigames.WarGames.RenderPerksTab()
        minigames.WarGames.RenderDebugTab()
        minigames.WarGames.RenderCreditsTab()
    end
end
