-- ============================================================
-- embedded module: wargames\vehicles.lua
-- ============================================================
embedded_modules['WarGames\\vehicles.lua'] = function()
--[[
    minigames/wargames/vehicles.lua
    build: v0.171-alpha

    v0.059:
    - respawn vehicle uses the active round vehicle for the entire round.
    - auto random vehicle rounds does not randomize on every death.
    - manual vehicle selection updates the active round vehicle and deletes old round vehicles.
]]

local A = minigames.Assets.Vehicles

minigames.WarGames.VehiclePool = {
    A.Khanjali,
    A.OppressorMK1,
    A.OppressorMK2,
    A.Vigilante,
    A.Hydra,
    A.Savage,
    A.Deluxo,
    A.Toreador,
    A.Scramjet,
    A.VetoClassic,
    A.Tampa3,
    A.DuneBuggy,
    A.BR8,
    A.DumpTruck,
    A.Raiju,
    A.Buzzard,
    A.Thruster,
    A.Ultralight,
    A.Marshall
}

function minigames.WarGames.EnsureVehicleSelection()
    if #minigames.WarGames.VehiclePool <= 0 then
        return
    end

    minigames.S.selectedVehicleIndex = minigames.ClampInt(minigames.S.selectedVehicleIndex or 1, 1, #minigames.WarGames.VehiclePool)
    minigames.S.roundVehicleIndex = minigames.ClampInt(minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex, 1, #minigames.WarGames.VehiclePool)

    if not minigames.S.currentRoundVehicle then
        minigames.S.currentRoundVehicle = minigames.WarGames.VehiclePool[minigames.S.roundVehicleIndex]
    end
end

function minigames.WarGames.GetSelectedVehicle()
    minigames.WarGames.EnsureVehicleSelection()
    return minigames.WarGames.VehiclePool[minigames.S.selectedVehicleIndex] or minigames.WarGames.VehiclePool[1]
end

function minigames.WarGames.GetCurrentRoundVehicle()
    minigames.WarGames.EnsureVehicleSelection()

    if minigames.GetRoundVehicle then
        local roundVehicle = minigames.GetRoundVehicle()
        if roundVehicle then
            return roundVehicle
        end
    end

    return minigames.WarGames.VehiclePool[minigames.S.roundVehicleIndex] or minigames.WarGames.GetSelectedVehicle()
end

function minigames.WarGames.SelectVehicle(index)
    minigames.WarGames.EnsureVehicleSelection()

    index = minigames.ClampInt(index, 1, #minigames.WarGames.VehiclePool)

    if minigames.SetRoundVehicleIndex then
        minigames.SetRoundVehicleIndex(index, "Manual Vehicle Selection", true)
    else
        minigames.S.selectedVehicleIndex = index
        minigames.S.roundVehicleIndex = index
    end

    local vehicle = minigames.WarGames.VehiclePool[index]

    minigames.Toast("WarGames Vehicle Selected", tostring(vehicle.label), 3500)
    minigames.LogInfo("[WarGames Vehicles] Selected active round vehicle: " .. tostring(vehicle.label))
end

function minigames.WarGames.NextVehicle()
    minigames.WarGames.EnsureVehicleSelection()

    local index = (minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or 1) + 1
    if index > #minigames.WarGames.VehiclePool then
        index = 1
    end

    minigames.WarGames.SelectVehicle(index)
end

function minigames.WarGames.PreviousVehicle()
    minigames.WarGames.EnsureVehicleSelection()

    local index = (minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or 1) - 1
    if index < 1 then
        index = #minigames.WarGames.VehiclePool
    end

    minigames.WarGames.SelectVehicle(index)
end

function minigames.WarGames.RollRandomRoundVehicle()
    if minigames.RandomVehicleRoundNow then
        minigames.RandomVehicleRoundNow("Manual Roll Random Round Vehicle")
        return
    end

    local index = math.random(1, #minigames.WarGames.VehiclePool)
    minigames.WarGames.SelectVehicle(index)
end

function minigames.WarGames.ResolveVehicle(reason)
    minigames.WarGames.EnsureVehicleSelection()

    -- v0.059:
    -- auto random vehicle rounds is stable.
    -- the active round vehicle is used for every respawn until the round timer expires.
    if minigames.S.autoRandomVehicleRounds == true then
        if minigames.EnsureVehicleRoundStarted then
            minigames.EnsureVehicleRoundStarted()
        end

        return minigames.WarGames.GetCurrentRoundVehicle()
    end

    -- existing manual behavior: selected vehicle is active.
    return minigames.WarGames.GetCurrentRoundVehicle()
end

function minigames.WarGames.SpawnVehicleOnSelected(force)
    minigames.RefreshPlayers()
    minigames.WarGames.EnsureVehicleSelection()

    local playerId = minigames.S.selectedPlayerId or minigames.GetLocalPlayerId()
    local vehicle = minigames.WarGames.ResolveVehicle("Selected Spawn")

    local ok, err = direct_call(function()
        minigames.SpawnVehicleForPlayer(playerId, vehicle, force == true, "WarGames Selected Spawn")
    end)

    if not ok then
        minigames.LogError("[WarGames Vehicles] Spawn selected failed: " .. tostring(err))
    end
end

function minigames.WarGames.SpawnVehicleOnAll(force)
    minigames.RefreshPlayers()
    minigames.WarGames.EnsureVehicleSelection()

    local vehicle = minigames.WarGames.ResolveVehicle("Spawn All")
    local applied = 0
    local skipped = 0
    local failed = 0

    local okLoop, errLoop = direct_call(function()
        for _, playerId in ipairs(minigames.S.activePlayers or {}) do
            local ok, status = minigames.SpawnVehicleForPlayer(playerId, vehicle, force == true, "WarGames Spawn All")

            if ok then
                applied = applied + 1
            elseif status == "skip_self" or status == "inactive" or status == "cooldown" then
                skipped = skipped + 1
            else
                failed = failed + 1
            end
        end
    end)

    if not okLoop then
        failed = failed + 1
        minigames.LogError("[WarGames Vehicles] Spawn all failed: " .. tostring(errLoop))
    end

    minigames.S.lastVehicleStatus =
        "Spawn all complete | vehicle=" ..
        tostring(vehicle.label) ..
        " | spawned=" ..
        tostring(applied) ..
        " skipped=" ..
        tostring(skipped) ..
        " failed=" ..
        tostring(failed)

    minigames.Toast("WarGames Vehicles", minigames.S.lastVehicleStatus, 5000)
    minigames.LogInfo("[WarGames Vehicles] " .. minigames.S.lastVehicleStatus)
end

function minigames.WarGames.PrintVehicleList()
    minigames.WarGames.EnsureVehicleSelection()

    minigames.LogInfo("========== WarGames Vehicles ==========")

    for i, vehicle in ipairs(minigames.WarGames.VehiclePool) do
        local marker = " "
        if i == minigames.S.roundVehicleIndex then
            marker = "*"
        end

        minigames.LogInfo(
            marker ..
            " " ..
            tostring(i) ..
            " | " ..
            tostring(vehicle.label) ..
            " | model=" ..
            tostring(vehicle.model) ..
            " | savedIndex=" ..
            tostring(vehicle.savedIndex)
        )
    end

    minigames.LogInfo("======================================")
    minigames.Toast("WarGames Vehicles", "Printed vehicle pool to log.", 3000)
end


