-- v0.095 previous/next no-throw final override
------------------------------------------------------------
function minigames.WarGames.SafeSelectVehicle(index, reason)
    local ok, err = direct_call_trace(function()
        minigames.WarGames.EnsureVehicleSelection()

        local poolSize = #minigames.WarGames.VehiclePool
        if poolSize <= 0 then
            minigames.S.lastVehicleRoundStatus = "No vehicles in pool."
            return
        end

        index = minigames.ClampInt(index, 1, poolSize)

        -- avoid older selectvehicle callback paths that may throw from round cleanup/autospawn.
        if minigames.SetRoundVehicleIndex then
            minigames.SetRoundVehicleIndex(index, reason or "Manual Vehicle Selection", true)
        else
            minigames.S.selectedVehicleIndex = index
            minigames.S.roundVehicleIndex = index
            minigames.S.currentRoundVehicle = minigames.WarGames.VehiclePool[index]
        end

        local vehicle = minigames.WarGames.VehiclePool[index]
        local label = vehicle and vehicle.label or ("Index " .. tostring(index))
        minigames.Toast("WarGames Vehicle Selected", tostring(label), 2500)
        minigames.LogInfo("[WarGames Vehicles] Selected active round vehicle safely: " .. tostring(label) .. " | reason=" .. tostring(reason))
    end, debug and debug.traceback or function(e) return tostring(e) end)

    if not ok then
        minigames.S.lastVehicleRoundStatus = "Safe vehicle selection failed: " .. tostring(err)
        minigames.LogError("[WarGames Vehicles] " .. minigames.S.lastVehicleRoundStatus)
        return false
    end

    return true
end

function minigames.WarGames.NextVehicle()
    local ok, err = direct_call_trace(function()
        minigames.WarGames.EnsureVehicleSelection()
        local index = (minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or 1) + 1
        if index > #minigames.WarGames.VehiclePool then index = 1 end
        minigames.WarGames.SafeSelectVehicle(index, "Manual Next Vehicle")
    end, debug and debug.traceback or function(e) return tostring(e) end)

    if not ok then
        minigames.S.lastVehicleRoundStatus = "NextVehicle failed but was swallowed: " .. tostring(err)
        minigames.LogError("[WarGames Vehicles] " .. minigames.S.lastVehicleRoundStatus)
        return false
    end

    return true
end

function minigames.WarGames.PreviousVehicle()
    local ok, err = direct_call_trace(function()
        minigames.WarGames.EnsureVehicleSelection()
        local index = (minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or 1) - 1
