        minigames.Toast("WarGames Vehicle Selected", tostring(vehicle.label), 2500)
        minigames.LogInfo("[WarGames Vehicles] Queued active round vehicle: " .. tostring(vehicle.label))
    elseif ok == false then
        minigames.LogInfo("[WarGames Vehicles] Vehicle selection ignored/status=" .. tostring(status))
    end

    return ok, status
end

