------------------------------------------------------------
-- v0.101 exact vehicle button selection fix
------------------------------------------------------------
-- purpose:
-- - vehicle buttons should select the exact vehicle attached to that button.
-- - fixes lua loop callback capture issues where "use scramjet" could select
--   a different vehicle such as marshall.
-- - keeps the active round vehicle synchronized immediately.
------------------------------------------------------------

function minigames.WarGames.SelectVehicleExact(index, labelHint)
    minigames.WarGames.EnsureVehicleSelection()

    local poolSize = #minigames.WarGames.VehiclePool
    if poolSize <= 0 then
        minigames.S.lastVehicleRoundStatus = "No WarGames vehicles available."
        minigames.LogError("[WarGames Vehicles] " .. minigames.S.lastVehicleRoundStatus)
        return false, "empty_pool"
    end

    index = minigames.ClampInt(index, 1, poolSize)

    local vehicle = minigames.WarGames.VehiclePool[index]
    if not vehicle then
        minigames.S.lastVehicleRoundStatus = "Invalid exact vehicle index: " .. tostring(index)
        minigames.LogError("[WarGames Vehicles] " .. minigames.S.lastVehicleRoundStatus)
        return false, "missing_vehicle"
    end

    -- immediate local state sync. this makes respawn spawns use the selected
    -- vehicle right away instead of waiting for a queued round update.
    minigames.S.selectedVehicleIndex = index
    minigames.S.roundVehicleIndex = index
    minigames.S.currentRoundVehicle = vehicle
    minigames.S.currentVehicleLabel = vehicle.label
    minigames.S.lastExactVehicleButtonIndex = index
    minigames.S.lastExactVehicleButtonLabel = vehicle.label

    -- keep the existing round system informed, but do it after local state sync.
    local ok, status = true, "ok"

    if minigames.QueueRoundVehicleIndex then
        ok, status = minigames.QueueRoundVehicleIndex(index, "Exact Vehicle Button: " .. tostring(vehicle.label), true)
    elseif minigames.SetRoundVehicleIndexSafe then
        ok, status = minigames.SetRoundVehicleIndexSafe(index, "Exact Vehicle Button: " .. tostring(vehicle.label), true)
    elseif minigames.SetRoundVehicleIndex then
        local roundOk, roundErr = direct_call_trace(function()
            minigames.SetRoundVehicleIndex(index, "Exact Vehicle Button: " .. tostring(vehicle.label), true)
        end, debug and debug.traceback or function(e) return tostring(e) end)

        if not roundOk then
            ok = false
            status = tostring(roundErr)
        end
    end

    minigames.Toast("WarGames Vehicle Selected", tostring(vehicle.label), 2500)

    minigames.LogInfo(
        "[WarGames Vehicles] Exact button selected | index=" ..
        tostring(index) ..
        " | label=" ..
        tostring(vehicle.label) ..
        " | model=" ..
        tostring(vehicle.model) ..
        " | status=" ..
        tostring(status) ..
        " | hint=" ..
        tostring(labelHint or "none")
    )

    return ok ~= false, status
end

-- final selection override routes normal selectvehicle through the exact helper.
function minigames.WarGames.SelectVehicle(index)
    return minigames.WarGames.SelectVehicleExact(index, "SelectVehicle")
end

function minigames.WarGames.NextVehicle()
    minigames.WarGames.EnsureVehicleSelection()

    local index = (minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or 1) + 1
    if index > #minigames.WarGames.VehiclePool then
        index = 1
    end

    return minigames.WarGames.SelectVehicleExact(index, "NextVehicle")
end

function minigames.WarGames.PreviousVehicle()
    minigames.WarGames.EnsureVehicleSelection()

    local index = (minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or 1) - 1
    if index < 1 then
        index = #minigames.WarGames.VehiclePool
    end

    return minigames.WarGames.SelectVehicleExact(index, "PreviousVehicle")
end


------------------------------------------------------------
-- v0.108 stable spawn-all override
------------------------------------------------------------
-- fatal log happened after public lobby vehicle spawning was working.
-- main risk: large batches spawning in one frame / repeated spawn-all clicks.
-- this override keeps spawnvehicleforplayer, but adds:
-- - 30s cooldown
-- - delayed per-player spawning
-- - recent vehicle skip unless force=true
------------------------------------------------------------

function minigames.WarGames.SpawnVehicleOnAll(force)
    minigames.RefreshPlayers()
    minigames.WarGames.EnsureVehicleSelection()

    local now = minigames.Now()
    local cooldown = minigames.S.spawnAllCooldownMs or 30000
    local last = minigames.S.lastSpawnAllMs or 0

    if last ~= 0 and now - last < cooldown then
        local waitLeft = math.ceil((cooldown - (now - last)) / 1000)
        minigames.S.lastVehicleStatus = "Spawn all blocked by stability cooldown | wait=" .. tostring(waitLeft) .. "s"
        minigames.LogInfo("[WarGames Vehicles] " .. minigames.S.lastVehicleStatus)
        minigames.Toast("WarGames Vehicles", minigames.S.lastVehicleStatus, 4000)
        return false, "cooldown"
    end

    minigames.S.lastSpawnAllMs = now

    local vehicle = minigames.WarGames.ResolveVehicle("Spawn All Stable")
    local players = {}
    local maxPlayers = minigames.S.maxSpawnAllPlayersPerBatch or 16

    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        if #players < maxPlayers then
            table.insert(players, minigames.ClampInt(playerId, 0, 31))
        end
    end

    local forceSpawn = force == true
    local delayMs = minigames.S.spawnAllPerPlayerDelayMs or 250

    minigames.S.lastVehicleStatus =
        "Spawn all queued | vehicle=" ..
        tostring(vehicle and vehicle.label or "Unknown") ..
        " | players=" ..
        tostring(#players) ..
        " | delayMs=" ..
        tostring(delayMs)

    minigames.LogInfo("[WarGames Vehicles] " .. minigames.S.lastVehicleStatus)
    minigames.Toast("WarGames Vehicles", minigames.S.lastVehicleStatus, 4000)

    local function spawn_job()
        local applied = 0
        local skipped = 0
        local failed = 0

        for _, playerId in ipairs(players) do
            local shouldSkipRecent = false

            if not forceSpawn and minigames.Player and minigames.Player.lastVehicleSpawnMs then
                local lastSpawn = minigames.Player.lastVehicleSpawnMs[playerId] or 0
                local recentMs = minigames.S.skipSpawnAllIfRecentVehicleMs or 45000
                if lastSpawn ~= 0 and minigames.Now() - lastSpawn < recentMs then
                    shouldSkipRecent = true
                end
            end

            if shouldSkipRecent then
                skipped = skipped + 1
            else
                local ok, status = direct_call_trace(function()
                    return minigames.SpawnVehicleForPlayer(playerId, vehicle, forceSpawn, "WarGames Stable Spawn All")
                end, debug and debug.traceback or function(e) return tostring(e) end)

                if ok and status == true then
                    applied = applied + 1
                elseif ok and (status == "skip_self" or status == "inactive" or status == "cooldown") then
                    skipped = skipped + 1
                else
                    failed = failed + 1
                    if not ok then
                        minigames.LogError("[WarGames Vehicles] Stable spawn all player failed | player=" .. tostring(playerId) .. " | err=" .. tostring(status))
                    end
                end
            end

            if Script and Script.Yield and delayMs > 0 then
                direct_call(function()
                    Script.Yield(delayMs)
                end)
            end
        end

        minigames.S.lastVehicleStatus =
            "Stable spawn all complete | vehicle=" ..
            tostring(vehicle and vehicle.label or "Unknown") ..
            " | spawned=" ..
            tostring(applied) ..
            " skipped=" ..
            tostring(skipped) ..
            " failed=" ..
            tostring(failed)

        minigames.LogInfo("[WarGames Vehicles] " .. minigames.S.lastVehicleStatus)
        minigames.Toast("WarGames Vehicles", minigames.S.lastVehicleStatus, 5000)
    end

    if Script and Script.QueueJob then
        Script.QueueJob(spawn_job)
    else
        spawn_job()
    end

    return true, "queued"
end


------------------------------------------------------------
-- v0.111 spawn-all extra safety
------------------------------------------------------------
minigames.S.spawnAllCooldownMs = math.max(minigames.S.spawnAllCooldownMs or 30000, 60000)
minigames.S.spawnAllPerPlayerDelayMs = math.max(minigames.S.spawnAllPerPlayerDelayMs or 250, 350)
minigames.S.maxSpawnAllPlayersPerBatch = math.min(minigames.S.maxSpawnAllPlayersPerBatch or 16, 12)


------------------------------------------------------------
-- v0.112 spawn-all gate / no automatic mass spawn
------------------------------------------------------------
-- the log showed spawn all being queued later in the session and tracking
-- growing to 28. while testing respawn, automatic mass-spawn is too risky.
------------------------------------------------------------

local __mg112_spawn_vehicle_on_all = minigames.WarGames.SpawnVehicleOnAll
function minigames.WarGames.SpawnVehicleOnAll(force, reason)
    local reasonText = tostring(reason or "")

    if minigames.S.disableAutomaticSpawnAll == true and force ~= true then
        minigames.S.lastVehicleStatus = "Spawn All blocked by v0.112 stability gate | reason=" .. reasonText
        minigames.LogInfo("[WarGames Vehicles] " .. minigames.S.lastVehicleStatus)
        return false, "blocked_stability_gate"
    end

    return __mg112_spawn_vehicle_on_all(force, reason)
end

function minigames.WarGames.ForceSpawnVehicleOnAllManual()
    return minigames.WarGames.SpawnVehicleOnAll(true, "Manual Force Spawn All")
end


------------------------------------------------------------
-- v0.113 direct spawn-all gate
------------------------------------------------------------
local __mg113_direct_spawn_vehicle_on_all = minigames.WarGames.SpawnVehicleOnAll
function minigames.WarGames.SpawnVehicleOnAll(force, reason)
    local reasonText = tostring(reason or "")
    local allowedManual = force == true and reasonText:lower():find("manual") ~= nil

    if not allowedManual then
        minigames.S.lastVehicleStatus = "AUTO Spawn All BLOCKED by v0.113 direct gate | reason=" .. reasonText
        minigames.LogInfo("[WarGames Vehicles] " .. minigames.S.lastVehicleStatus)
        return false, "blocked_v113_direct_gate"
    end

    return __mg113_direct_spawn_vehicle_on_all(true, "Manual Force Spawn All")
end

function minigames.WarGames.ForceSpawnVehicleOnAllManual()
    return minigames.WarGames.SpawnVehicleOnAll(true, "Manual Force Spawn All")
end


