-- v0.117 safety guard
------------------------------------------------------------
-- these systems are intentionally off by default because live testing showed
-- respawn vehicles worked again after disabling them.
------------------------------------------------------------

------------------------------------------------------------
-- v0.159 vigilante visibility helper
------------------------------------------------------------
function minigames.WarGames.GetVigilanteIndexV159()
    for index, vehicle in ipairs(minigames.WarGames.VehiclePool or {}) do
        local model = tostring(vehicle and vehicle.model or ""):lower()
        local label = tostring(vehicle and vehicle.label or ""):lower()

        if model == "vigilante" or label == "vigilante" then
            return index
        end
    end

    -- runtime fallback in case an older assets file was left installed.
    local asset =
        minigames.Assets and
        minigames.Assets.Vehicles and
        minigames.Assets.Vehicles.Vigilante

    if not asset then
        minigames.Assets = minigames.Assets or {}
        minigames.Assets.Vehicles = minigames.Assets.Vehicles or {}

        asset = {
            label = "Vigilante",
            model = "vigilante",
            json = "zzzMinigame-Vigilante.json",
            category = "Weaponized Rocket Car"
        }

        minigames.Assets.Vehicles.Vigilante = asset
    end

    minigames.WarGames.VehiclePool = minigames.WarGames.VehiclePool or {}
    table.insert(minigames.WarGames.VehiclePool, asset)

    return #minigames.WarGames.VehiclePool
end

minigames.S.vigilanteVehicleIndex =
    minigames.WarGames.GetVigilanteIndexV159()

if minigames.LogInfo then
    minigames.LogInfo(
        "[WarGames Vehicles] Vigilante registered" ..
        " | index=" .. tostring(minigames.S.vigilanteVehicleIndex) ..
        " | poolSize=" .. tostring(#(minigames.WarGames.VehiclePool or {}))
    )
end


------------------------------------------------------------
-- v0.160 vigilante direct spawn button
------------------------------------------------------------
function minigames.WarGames.GetVigilanteVehicleV160()
    local index =
        minigames.WarGames.GetVigilanteIndexV159 and
        minigames.WarGames.GetVigilanteIndexV159() or nil

    if index and minigames.WarGames.VehiclePool then
        return minigames.WarGames.VehiclePool[index], index
    end

    for i, vehicle in ipairs(minigames.WarGames.VehiclePool or {}) do
        if tostring(vehicle and vehicle.model or ""):lower() ==
            "vigilante" then
            return vehicle, i
        end
    end

    return nil, nil
end

function minigames.WarGames.RequestVigilanteModelV160()
    local hash = nil

    if Utils and Utils.Joaat then
        local ok, value = direct_call(Utils.Joaat, "vigilante")
        if ok then hash = value end
    end

    hash = tonumber(hash)
    if not hash then
        return false, "hash_missing"
    end

    if STREAMING and STREAMING.REQUEST_MODEL then
        direct_call(function()
            STREAMING.REQUEST_MODEL(hash)
        end)
    end

    if STREAMING and STREAMING.HAS_MODEL_LOADED then
        for _ = 1, 40 do
            local loaded = false

            direct_call(function()
                loaded = STREAMING.HAS_MODEL_LOADED(hash) == true
            end)

            if loaded then
                return true, hash
            end

            if Script and Script.Yield then
                Script.Yield(50)
            end

            if STREAMING and STREAMING.REQUEST_MODEL then
                direct_call(function()
                    STREAMING.REQUEST_MODEL(hash)
                end)
            end
        end
    end

    -- gta/cherax spawn functions may still load the model internally.
    return true, hash
end

function minigames.WarGames.SpawnVigilanteToAllV160(reason)
    reason = tostring(reason or "Use Vigilante Button")

    local now = minigames.Now and minigames.Now() or 0
    local last =
        tonumber(minigames.S.lastVigilanteDirectSpawnMsV160 or 0) or 0

    if last ~= 0 and now - last < 1800 then
        if minigames.Toast then
            minigames.Toast(
                "Vigilante",
                "Spawn button cooldown.",
                2500
            )
        end
        return false, "cooldown"
    end

    minigames.S.lastVigilanteDirectSpawnMsV160 = now

    local vehicle, vehicleIndex =
        minigames.WarGames.GetVigilanteVehicleV160()

    if not vehicle or not vehicleIndex then
        minigames.S.lastVigilanteSpawnStatusV160 =
            "Vigilante missing from vehicle pool"

        if minigames.LogError then
            minigames.LogError(
                "[WarGames Vigilante] " ..
                minigames.S.lastVigilanteSpawnStatusV160
            )
        end

        if minigames.Toast then
            minigames.Toast(
                "Vigilante Spawn Failed",
                minigames.S.lastVigilanteSpawnStatusV160,
                4500
            )
        end

        return false, "vehicle_missing"
    end

    -- select it immediately as the active round vehicle.
    if minigames.WarGames.SelectVehicleExact then
        minigames.WarGames.SelectVehicleExact(
            vehicleIndex,
            "Vigilante Direct Spawn"
        )
    else
        minigames.WarGames.SelectVehicle(vehicleIndex)
    end

    local function run_spawn_job()
        minigames.WarGames.RequestVigilanteModelV160()
        minigames.RefreshPlayers()

        local players = {}
        local seen = {}

        for _, playerId in ipairs(minigames.S.activePlayers or {}) do
            playerId = minigames.ClampInt(playerId, 0, 31)

            if not seen[playerId] then
                seen[playerId] = true
                players[#players + 1] = playerId
            end
        end

        -- always include the local player when active-player refresh returns
        -- an empty or remote-only list.
        local localId =
            minigames.GetLocalPlayerId and
            minigames.GetLocalPlayerId() or 0
        localId = minigames.ClampInt(localId, 0, 31)

        if not seen[localId] then
            seen[localId] = true
            players[#players + 1] = localId
        end

        table.sort(players)

        local applied = 0
        local failed = 0
        local failureDetails = {}

        for _, playerId in ipairs(players) do
            local ok, status = false, "spawn_not_called"

            local callOk, resultA, resultB = direct_call(function()
                return minigames.SpawnVehicleForPlayer(
                    playerId,
                    vehicle,
                    true,
                    reason
                )
            end)

            if callOk then
                ok = resultA == true
                status = tostring(resultB or resultA)
            else
                status = tostring(resultA)
            end

            -- explicit raw fallback if the normal hybrid/player path failed.
            if not ok and minigames.SpawnRawModelVehicle then
                local rawCallOk, rawA, rawB = direct_call(function()
                    return minigames.SpawnRawModelVehicle(
                        vehicle,
                        playerId,
                        reason .. " RAW fallback",
                        true
                    )
                end)

                if rawCallOk then
                    ok = rawA == true
                    status = tostring(rawB or rawA)
                else
                    status =
                        status ..
                        " | raw_error=" ..
                        tostring(rawA)
                end
            end

            if ok then
                applied = applied + 1
            else
                failed = failed + 1
                failureDetails[#failureDetails + 1] =
                    tostring(
                        minigames.GetPlayerName and
                        minigames.GetPlayerName(playerId) or
                        ("Player " .. tostring(playerId))
                    ) ..
                    "=" .. tostring(status)
            end

            if Script and Script.Yield then
                Script.Yield(120)
            end
        end

        minigames.S.lastVigilanteSpawnStatusV160 =
            "Vigilante force spawn complete" ..
            " | players=" .. tostring(#players) ..
            " | applied=" .. tostring(applied) ..
            " | failed=" .. tostring(failed) ..
            " | reason=" .. reason

        if minigames.LogInfo then
            minigames.LogInfo(
                "[WarGames Vigilante] " ..
                minigames.S.lastVigilanteSpawnStatusV160
            )

            if #failureDetails > 0 then
                minigames.LogInfo(
                    "[WarGames Vigilante] failures: " ..
                    table.concat(failureDetails, ", ")
                )
            end
        end

        if minigames.Toast then
            minigames.Toast(
                "Vigilante Spawn",
                "Spawned=" .. tostring(applied) ..
                " | Failed=" .. tostring(failed),
                5000
            )
        end
    end

    if Script and Script.QueueJob then
        Script.QueueJob(run_spawn_job)

        minigames.S.lastVigilanteSpawnStatusV160 =
            "Vigilante force spawn queued"

        return true, "queued"
    end

    run_spawn_job()
    return true, "ran_direct"
end
end



