local function safe(fn, ...)
    if type(fn) ~= "function" then return false, nil end
    return direct_call(fn, ...)
end

local function now_ms()
    if minigames and minigames.Now then
        local ok, value = direct_call(minigames.Now)
        if ok and tonumber(value) then return tonumber(value) end
    end
    return math.floor((os.clock and os.clock() or 0) * 1000)
end

local function clamp(value, low, high)
    value = tonumber(value or low) or low
    if value < low then return low end
    if value > high then return high end
    return value
end

local function tone(name)
    return COLORS[tostring(name or "white")] or COLORS.white
end

function UI.Text(value, colorName, wrapped, alpha)
    if not ImGui then return end

    local c = tone(colorName)
    local a = clamp(alpha == nil and c[4] or alpha, 0.0, 1.0)
    value = tostring(value or "")

    if wrapped == true and ImGui.TextWrapped then
        local pushed = false
        if ImGui.PushStyleColor and ImGuiCol and ImGuiCol.Text then
            local ok = direct_call(
                ImGui.PushStyleColor,
                ImGuiCol.Text,
                c[1], c[2], c[3], a
            )
            pushed = ok == true
        end

        direct_call(ImGui.TextWrapped, value)

        if pushed and ImGui.PopStyleColor then
            direct_call(ImGui.PopStyleColor, 1)
        end
        return
    end

    if ImGui.TextColored then
        direct_call(
            ImGui.TextColored,
            c[1], c[2], c[3], a,
            value
        )
    elseif ImGui.Text then
        direct_call(ImGui.Text, value)
    end
end

function UI.Separator()
    if ImGui and ImGui.Separator then direct_call(ImGui.Separator) end
end

function UI.Spacing(count)
    count = math.max(1, math.floor(tonumber(count or 1) or 1))
    for _ = 1, count do
        if ImGui and ImGui.Spacing then direct_call(ImGui.Spacing) end
    end
end

function UI.SameLine()
