end

function UI.SectionTitle(title, subtitle, colorName)
    UI.Text(string.upper(tostring(title or "SECTION")), colorName or "purple")
    if subtitle and subtitle ~= "" then
        UI.Text(subtitle, "dim", true)
    end
    UI.Separator()
end

function UI.Child(name, title, subtitle, callback, titleColor)
    local usedChild = false
    local open = true

    if ClickGUI and ClickGUI.BeginCustomChildWindow then
        local ok, result = direct_call(
            ClickGUI.BeginCustomChildWindow,
            tostring(name or title or "Section")
        )
        if ok then
            usedChild = true
            open = result ~= false
        end
    end

    if open then
        if title and title ~= "" then
            UI.SectionTitle(title, subtitle, titleColor or "purple")
        elseif subtitle and subtitle ~= "" then
            UI.Text(subtitle, "dim", true)
        end

        if type(callback) == "function" then
            local ok, err = direct_call(callback)
            if not ok then
                UI.Text("Section error: " .. tostring(err), "red", true)
                if minigames and minigames.LogError then
                    minigames.LogError("[UI v0.168] " .. tostring(name) .. ": " .. tostring(err))
                end
            end
        end
    end

    if usedChild and open and ClickGUI.EndCustomChildWindow then
        direct_call(ClickGUI.EndCustomChildWindow)
    end

    return open
end

function UI.RenderFeature(hash)
    if not hash or not ClickGUI or not ClickGUI.RenderFeature then
        return false
    end

    local ok = direct_call(ClickGUI.RenderFeature, hash)
    return ok == true
end

function UI.PushButtonTone(name)
    if not (
        ImGui and ImGui.PushStyleColor and
        ImGuiCol and
        ImGuiCol.Button and
        ImGuiCol.ButtonHovered and
        ImGuiCol.ButtonActive
    ) then
        return 0
    end

    local colors = BUTTON_TONES[name] or BUTTON_TONES.purple
    local count = 0

    local function push(which, c)
        local ok = direct_call(
            ImGui.PushStyleColor,
            which,
            c[1], c[2], c[3], c[4]
        )
        if ok then count = count + 1 end
    end

    push(ImGuiCol.Button, colors[1])
    push(ImGuiCol.ButtonHovered, colors[2])
    push(ImGuiCol.ButtonActive, colors[3])

    return count
end

function UI.PopButtonTone(count)
    count = tonumber(count or 0) or 0
    if count > 0 and ImGui and ImGui.PopStyleColor then
        direct_call(ImGui.PopStyleColor, count)
    end
end

function UI.Button(label, colorName, callback, width, height)
    if not ImGui or not ImGui.Button then return false end

    local pushed = UI.PushButtonTone(colorName)
    local clicked = false
    local ok, result

    if width or height then
        ok, result = direct_call(
            ImGui.Button,
            tostring(label or "Button"),
            tonumber(width or 0) or 0,
            tonumber(height or 0) or 0
        )
    else
        ok, result = direct_call(
            ImGui.Button,
            tostring(label or "Button")
        )
    end

    clicked = ok and result == true
    UI.PopButtonTone(pushed)

    if clicked and type(callback) == "function" then
        local cbOk, cbErr = direct_call(callback)
        if not cbOk then
            UI.Text("Action failed: " .. tostring(cbErr), "red", true)
            if minigames and minigames.LogError then
                minigames.LogError("[UI v0.168 Button] " .. tostring(cbErr))
            end
        end
    end

    return clicked
end

function UI.Combo(label, index, items, rows)
    index = math.floor(tonumber(index or 0) or 0)
    if type(items) ~= "table" or #items == 0 then
        return 0, false
    end

    if index < 0 then index = 0 end
    if index > #items - 1 then index = #items - 1 end

    if ImGui and ImGui.Combo then
        local ok, newIndex, changed = direct_call(
            ImGui.Combo,
            tostring(label),
            index,
            items,
            #items,
            tonumber(rows or math.min(#items, 8)) or 8
        )

        if ok and type(newIndex) == "number" then
            newIndex = math.floor(newIndex)
            if newIndex < 0 then newIndex = 0 end
            if newIndex > #items - 1 then newIndex = #items - 1 end
            return newIndex, changed == true or newIndex ~= index
        end
    end

    if ImGui and ImGui.BeginCombo and ImGui.Selectable and ImGui.EndCombo then
        local opened = false
        direct_call(function()
            opened = ImGui.BeginCombo(
                tostring(label),
                tostring(items[index + 1] or items[1])
            )
        end)

        if opened then
            local selectedIndex = index
            for i, item in ipairs(items) do
                local clicked = false
                direct_call(function()
                    clicked = ImGui.Selectable(
                        tostring(item),
                        (i - 1) == index
                    )
                end)
                if clicked then selectedIndex = i - 1 end
            end
            direct_call(ImGui.EndCombo)
            return selectedIndex, selectedIndex ~= index
        end
    end

    local changed = false
    if UI.Button("<##" .. tostring(label), "gray") then
        index = index - 1
        if index < 0 then index = #items - 1 end
        changed = true
    end
    UI.SameLine()
    UI.Text(items[index + 1], "purple")
    UI.SameLine()
    if UI.Button(">##" .. tostring(label), "gray") then
        index = index + 1
        if index > #items - 1 then index = 0 end
        changed = true
    end

    return index, changed
end

function UI.StatusRow(label, value, valueTone, help)
    UI.Text(tostring(label or "") .. ":", "cyan")
    UI.SameLine()
    UI.Text(tostring(value or "-"), valueTone or "white", true)
    if help and help ~= "" and ImGui and ImGui.IsItemHovered and ImGui.SetTooltip then
        local hovered = false
        direct_call(function() hovered = ImGui.IsItemHovered() == true end)
        if hovered then direct_call(ImGui.SetTooltip, tostring(help)) end
    end
end

function UI.TwoColumns(id, leftCallback, rightCallback)
    if (
        ImGui and ImGui.BeginTable and
        ImGui.TableNextRow and
        ImGui.TableSetColumnIndex and
        ImGui.EndTable
    ) then
        local opened = false
        direct_call(function()
            opened = ImGui.BeginTable(tostring(id), 2, 0)
        end)

        if opened then
            direct_call(ImGui.TableNextRow)
            direct_call(ImGui.TableSetColumnIndex, 0)
            if type(leftCallback) == "function" then direct_call(leftCallback) end
            direct_call(ImGui.TableSetColumnIndex, 1)
            if type(rightCallback) == "function" then direct_call(rightCallback) end
            direct_call(ImGui.EndTable)
            return true
        end
    end

    if type(leftCallback) == "function" then direct_call(leftCallback) end
    if type(rightCallback) == "function" then direct_call(rightCallback) end
    return false
end

function UI.MarkRoute(route)
    route = tostring(route or "")
    if UI.lastRoute ~= route then
        UI.lastRoute = route
        UI.transitionStartedAt = now_ms()
    end
end

function UI.EaseOutCubic(t)
    t = clamp(t, 0.0, 1.0)
    local inv = 1.0 - t
    return 1.0 - (inv * inv * inv)
end

function UI.RenderTransition(route, title, subtitle, colorName)
    UI.MarkRoute(route)

    local elapsed = now_ms() - (tonumber(UI.transitionStartedAt or 0) or 0)
    local progress = clamp(elapsed / UI.transitionDurationMs, 0.0, 1.0)
    local eased = UI.EaseOutCubic(progress)
    local alpha = 0.35 + (0.65 * eased)

    UI.Text(title, colorName or "purple", false, alpha)
    if subtitle and subtitle ~= "" then
        UI.Text(subtitle, "dim", true, alpha)
    end

    if ImGui and ImGui.ProgressBar and progress < 1.0 then
        direct_call(
            ImGui.ProgressBar,
            eased,
            0,
            3,
            ""
        )
    else
        UI.Separator()
    end

    local remaining = 1.0 - eased
    if remaining > 0.55 then
        UI.Spacing(2)
    elseif remaining > 0.10 then
        UI.Spacing(1)
    end
end

function UI.PushTabStyle()
    if not (
        ImGui and ImGui.PushStyleColor and ImGuiCol
    ) then
        return 0
    end

    local entries = {
        {"Tab", {0.14, 0.12, 0.19, 1.00}},
        {"TabHovered", {0.38, 0.22, 0.58, 1.00}},
        {"TabActive", {0.56, 0.30, 0.82, 1.00}},
        {"TabUnfocused", {0.10, 0.10, 0.14, 1.00}},
        {"TabUnfocusedActive", {0.28, 0.18, 0.40, 1.00}},
    }

    local pushed = 0

    for _, entry in ipairs(entries) do
        local enum = ImGuiCol[entry[1]]
        if enum then
            local c = entry[2]
            local ok = direct_call(
                ImGui.PushStyleColor,
                enum,
                c[1], c[2], c[3], c[4]
            )
            if ok then pushed = pushed + 1 end
        end
    end

    return pushed
end

function UI.PopTabStyle(count)
    count = tonumber(count or 0) or 0
    if count > 0 and ImGui and ImGui.PopStyleColor then
        direct_call(ImGui.PopStyleColor, count)
    end
end

local function current_vehicle_label()
    local vehicle = nil
    if minigames.WarGames and minigames.WarGames.GetSelectedVehicle then
        direct_call(function() vehicle = minigames.WarGames.GetSelectedVehicle() end)
    end
    if type(vehicle) == "table" then
        return tostring(vehicle.label or vehicle.model or "Unknown")
    end
    return "Not selected"
end

local function active_player_count()
    if minigames.S and tonumber(minigames.S.activePlayerCount) then
        return tonumber(minigames.S.activePlayerCount) or 0
    end
    return #(minigames.S and minigames.S.activePlayers or {})
end

