                    )
                    UI.StatusRow(
                        "Protection Guard",
                        minigames.S.warGamesVehicleSpamProtectionLastStatus or "Ready",
                        "cyan"
                    )
                    UI.StatusRow("Last Status", minigames.S.lastVehicleRoundStatus or minigames.S.lastBountyStatus or "Ready", "white")
