                "purple"
            )
        end,
        function()
            UI.Child(
                "Minigames_HomeQuick",
                "Quick Actions",
                "Distinct colors separate spawning, rounds, bounty, cleanup, and presentation.",
                function()
                    UI.Button("Next Vehicle Round", "cyan", quick_next_round, -1, 32)

                    UI.Button("Spawn Players Above Me", "blue", quick_spawn_players_above_me)
