function UI.RenderWarGames()
    minigames.S.uiWarGamesPageV169 = math.floor(tonumber(minigames.S.uiWarGamesPageV169 or 0) or 0)

    local index, changed = UI.Combo(
        "WarGames Section##Minigames",
        minigames.S.uiWarGamesPageV169,
        WARGAMES_PAGES,
        8
    )
    minigames.S.uiWarGamesPageV169 = index

    UI.RenderTransition(
        "WarGames:" .. tostring(index),
        "WARGAMES  -  " .. tostring(WARGAMES_PAGES[index + 1]),
        "One focused section at a time replaces the older crowded row of repetitive subtabs.",
        "red"
    )

    if changed then
        minigames.S.uiLastWarGamesSectionV169 = WARGAMES_PAGES[index + 1]
    end

    local activeRound = nil
    local previousLabel = "None"

    if minigames.WarGames and minigames.WarGames.RefreshWarGamesUiSettings then
        direct_call(minigames.WarGames.RefreshWarGamesUiSettings)
    end

    if minigames.WarGames and minigames.WarGames.GetCurrentRoundVehicle then
        direct_call(function()
            activeRound = minigames.WarGames.GetCurrentRoundVehicle()
        end)
    end

    if not activeRound and minigames.WarGames and minigames.WarGames.GetSelectedVehicle then
        direct_call(function()
            activeRound = minigames.WarGames.GetSelectedVehicle()
        end)
    end

    if minigames.GetVehicleLabelByIndex then
        direct_call(function()
            previousLabel = minigames.GetVehicleLabelByIndex(
                minigames.S.previousRoundVehicleIndex or
                minigames.S.roundVehicleIndex or 1
            )
        end)
    end

    UI.Child(
        "Minigames_WarGamesSummary",
        "Live WarGames Status",
        "The selector above changes only the visible page; active systems continue running.",
        function()
            UI.StatusRow("Selected Vehicle", current_vehicle_label(), "gold")
            UI.StatusRow("Previous Round", previousLabel, "dim")
            UI.StatusRow("Tracked Vehicles", #(minigames.S.spawnedWarGamesVehicles or {}), "cyan")
            UI.StatusRow("Players", active_player_count(), "green")
            UI.StatusRow("Respawn Watcher", minigames.S.respawnWatcherRunning == true and "ON" or "OFF", minigames.S.respawnWatcherRunning == true and "green" or "dim")
            UI.StatusRow("Last Bounty", minigames.S.lastBountyStatus or "None", "white")
        end,
        "red"
    )

    if index == 0 and minigames.WarGames.RenderMainTab then
        minigames.WarGames.RenderMainTab(activeRound, previousLabel)
    elseif index == 1 and minigames.WarGames.RenderVehiclesTab then
        minigames.WarGames.RenderVehiclesTab(activeRound, previousLabel)
    elseif index == 2 and minigames.WarGames.RenderBountiesTab then
        minigames.WarGames.RenderBountiesTab()
    elseif index == 3 and minigames.WarGames.RenderTeleportsTab then
        minigames.WarGames.RenderTeleportsTab()
    elseif index == 4 and minigames.WarGames.RenderInfantryTab then
        minigames.WarGames.RenderInfantryTab()
    elseif index == 5 and minigames.WarGames.RenderCleanupFairnessTab then
        minigames.WarGames.RenderCleanupFairnessTab()
    elseif index == 6 and minigames.WarGames.RenderPerksTab then
        minigames.WarGames.RenderPerksTab()
    elseif index == 7 and minigames.WarGames.RenderDebugTab then
        minigames.WarGames.RenderDebugTab()
    end
end

