end

local function queue_job(fn)
    if type(fn) ~= "function" then return false end

    if minigames.Queue then
        minigames.Queue(fn)
        return true
    end

    if Script and Script.QueueJob then
        Script.QueueJob(fn)
        return true
    end

    fn()
    return true
end

local function yield_ms(milliseconds)
    milliseconds = tonumber(milliseconds or 0) or 0

    if Script and Script.Yield then
        direct_call(Script.Yield, milliseconds)
    elseif SYSTEM and SYSTEM.WAIT then
        direct_call(SYSTEM.WAIT, milliseconds)
    end
end

local function file_exists(path)
    path = tostring(path or "")
    if path == "" then return false end

    if FileMgr and FileMgr.DoesFileExist then
        local ok, result =
            direct_call(FileMgr.DoesFileExist, path)

        if ok then return result == true end
    end

    local file = io.open(path, "rb")

    if file then
        file:close()
        return true
    end

    return false
end

local function ensure_dir(path)
    path = tostring(path or "")
    if path == "" then return false end

    if FileMgr and FileMgr.CreateDir then
        FileMgr.CreateDir(path)
        return true
    end

    return false
end

local function u32_be(data, offset)
    if type(data) ~= "string" then return nil end

    offset = tonumber(offset or 1) or 1

    local a, b, c, d = data:byte(
        offset,
        offset + 3
    )

    if not a or not b or not c or not d then
        return nil
    end

    return
        a * 16777216 +
        b * 65536 +
        c * 256 +
        d
end

local function validate_png_file(path)
    path = tostring(path or "")
    local file = io.open(path, "rb")

    if not file then
        return false, "missing"
    end

    local header = file:read(32) or ""
    local size = file:seek("end") or 0
    file:close()

    if header:byte(1) ~= 137 or
        header:sub(2, 4) ~= "PNG" or
        header:sub(5, 8) ~= "\r\n\26\n" then
        return false, "invalid PNG signature"
    end

    if header:sub(13, 16) ~= "IHDR" then
        return false, "missing PNG IHDR"
    end

    local width = u32_be(header, 17)
    local height = u32_be(header, 21)

    if width ~= UI.publicUrinalLogoExpectedWidth or
        height ~= UI.publicUrinalLogoExpectedHeight then
        return false,
            "unexpected dimensions " ..
            tostring(width) .. "x" .. tostring(height)
    end

    if tonumber(size or 0) < 1000 then
        return false, "file too small"
    end

    return true,
        tostring(width) .. "x" .. tostring(height) ..
        " | bytes=" .. tostring(size)
end

local function validate_png_body(body)
    if type(body) ~= "string" or #body < 1000 then
        return false, "empty or too small"
    end

    if body:byte(1) ~= 137 or
        body:sub(2, 4) ~= "PNG" or
        body:sub(5, 8) ~= "\r\n\26\n" then
        return false, "invalid PNG signature"
    end

    if body:sub(13, 16) ~= "IHDR" then
        return false, "missing PNG IHDR"
    end

    local width = u32_be(body, 17)
    local height = u32_be(body, 21)

    if width ~= UI.publicUrinalLogoExpectedWidth or
        height ~= UI.publicUrinalLogoExpectedHeight then
        return false,
            "unexpected dimensions " ..
            tostring(width) .. "x" .. tostring(height)
    end

    return true,
        tostring(width) .. "x" .. tostring(height) ..
        " | bytes=" .. tostring(#body)
end

local function public_logo_path()
    local root = tostring(
        minigames.ASSETS_ROOT or
        (
            tostring(minigames.ROOT or ".") ..
            "\\assets"
        )
    )

    ensure_dir(root)

    return root .. "\\" .. UI.publicUrinalLogoFile
end

local function curl_setopt(
    curl,
    enumName,
    numericValue,
    value
)
    if not curl or not curl.Setopt then return end

    local option = numericValue

    direct_call(function()
        if eCurlOption and eCurlOption[enumName] then
            option = eCurlOption[enumName]
        end
    end)

    direct_call(function()
        curl:Setopt(option, value)
    end)
end

local function curl_finished(curl)
    if not curl or not curl.GetFinished then
        return false
    end

    local ok, result = direct_call(function()
        return curl:GetFinished()
    end)

    return ok and result == true
end

local function download_public_logo_now(force)
    local state = UI.publicUrinalLogo
    local path = public_logo_path()

    state.path = path

    if force ~= true then
        local valid, status = validate_png_file(path)

        if valid then
            state.state = "ready"
            state.error = ""
            minigames.S.publicUrinalLogoStatusV169 =
                "Cached | " .. tostring(status)
            minigames.S.publicUrinalLogoPathV169 = path
            return true, status
        end
    end

    if not Curl or not Curl.Easy then
        state.state = "failed"
        state.error = "Cherax Curl is unavailable"
        minigames.S.publicUrinalLogoStatusV169 = state.error
        return false, state.error
    end

    state.state = "downloading"
    state.error = ""
    minigames.S.publicUrinalLogoStatusV169 = "Downloading..."

    local curl = Curl.Easy()

    curl_setopt(
        curl,
        "CURLOPT_URL",
        10002,
        UI.publicUrinalLogoUrl
    )

    curl_setopt(
        curl,
        "CURLOPT_USERAGENT",
        10018,
        "Mozilla/5.0 Minigames-Cherax"
    )

    local performOk, performError = direct_call(function()
        curl:Perform()
    end)

    if not performOk then
        state.state = "failed"
        state.error =
            "Curl perform failed: " ..
            tostring(performError)

        minigames.S.publicUrinalLogoStatusV169 = state.error
        return false, state.error
    end

    local ticks = 0

    while not curl_finished(curl) and ticks < 300 do
        yield_ms(50)
        ticks = ticks + 1
    end

    if not curl_finished(curl) then
        state.state = "failed"
        state.error = "Download timed out"
        minigames.S.publicUrinalLogoStatusV169 = state.error
        return false, state.error
    end

    local responseOk, code, body = direct_call(function()
        return curl:GetResponse()
    end)

    if not responseOk then
        state.state = "failed"
        state.error =
            "GetResponse failed: " ..
            tostring(code)

        minigames.S.publicUrinalLogoStatusV169 = state.error
        return false, state.error
    end

    local transferSuccess =
        code == true or
        code == 0

    direct_call(function()
        if eCurlCode and
            code == eCurlCode.CURLE_OK then
            transferSuccess = true
        end
    end)

    if not transferSuccess then
        state.state = "failed"
        state.error =
            "Download failed | code=" ..
            tostring(code)

        minigames.S.publicUrinalLogoStatusV169 = state.error
        return false, state.error
    end

    local validBody, bodyStatus =
        validate_png_body(body)

    if not validBody then
        state.state = "failed"
        state.error =
            "PNG validation failed: " ..
            tostring(bodyStatus)

        minigames.S.publicUrinalLogoStatusV169 = state.error
        return false, state.error
    end

    local temporaryPath = path .. ".download"
    direct_call(os.remove, temporaryPath)

    local file = io.open(temporaryPath, "wb")

    if not file then
        state.state = "failed"
        state.error = "Could not create temporary asset"
        minigames.S.publicUrinalLogoStatusV169 = state.error
        return false, state.error
    end

    file:write(body)
    file:close()

    local temporaryValid, temporaryStatus =
        validate_png_file(temporaryPath)

    if not temporaryValid then
        direct_call(os.remove, temporaryPath)

        state.state = "failed"
        state.error =
            "Temporary asset invalid: " ..
            tostring(temporaryStatus)

        minigames.S.publicUrinalLogoStatusV169 = state.error
        return false, state.error
    end

    direct_call(os.remove, path)

    local renamed = false

    direct_call(function()
        renamed =
            os.rename(temporaryPath, path) == true
    end)

    if not renamed then
        local finalFile = io.open(path, "wb")

        if not finalFile then
            direct_call(os.remove, temporaryPath)

            state.state = "failed"
            state.error = "Could not create final asset"
            minigames.S.publicUrinalLogoStatusV169 = state.error
            return false, state.error
        end

        finalFile:write(body)
        finalFile:close()
        direct_call(os.remove, temporaryPath)
    end

    local finalValid, finalStatus =
        validate_png_file(path)

    if not finalValid then
        state.state = "failed"
        state.error =
            "Final asset invalid: " ..
            tostring(finalStatus)

        minigames.S.publicUrinalLogoStatusV169 = state.error
        return false, state.error
    end

    state.state = "ready"
    state.error = ""
    state.textureId = nil
    state.srv = nil
    state.path = path

    minigames.S.publicUrinalLogoStatusV169 =
        "Downloaded | " .. tostring(finalStatus)

    minigames.S.publicUrinalLogoPathV169 = path

    return true, finalStatus
end

function minigames.DownloadPublicUrinalLogoV169(force)
    local state = UI.publicUrinalLogo

    if state.queued == true then
        return false, "already queued"
    end

    state.queued = true
    state.state = "queued"

    queue_job(function()
        yield_ms(50)

        local ok, status =
            download_public_logo_now(force == true)

        state.queued = false

        if ok then
            toast("Public_Urinal logo ready.", 2500)
        elseif force == true then
            toast(
                "Public_Urinal logo download failed: " ..
                tostring(status),
                4500
            )
        end
    end)

    return true, "queued"
end

local function load_public_logo_texture()
    local state = UI.publicUrinalLogo
    local path = state.path

    if path == nil or path == "" then
        path = public_logo_path()
        state.path = path
    end

    if state.srv then return state.srv end

    local valid = validate_png_file(path)

    if valid ~= true then
        if state.queued ~= true then
            minigames.DownloadPublicUrinalLogoV169(false)
        end

        return nil
    end

    if not Texture or
        not Texture.LoadTexture or
        not Texture.GetTexture then
        state.error = "Texture API unavailable"
        return nil
    end

    local textureId = nil

    direct_call(function()
        textureId = Texture.LoadTexture(path)
    end)

    if not textureId or tonumber(textureId) == 0 then
        state.error = "Texture load failed"
        return nil
    end

    if Texture.IsTextureValid then
        local validTexture = false

        direct_call(function()
            validTexture =
                Texture.IsTextureValid(textureId) == true
        end)

        if not validTexture then
            state.error = "Texture validation failed"
            return nil
        end
    end

    local texture = nil
    local srv = nil

    direct_call(function()
        texture = Texture.GetTexture(textureId)
        srv = texture and texture:GetCurrent() or nil
    end)

    if not srv then
        state.error = "Texture handle failed"
        return nil
    end

    state.textureId = textureId
    state.srv = srv
    state.error = ""

    return srv
end

function UI.DrawPublicUrinalLogo(size)
    size = tonumber(size or 156) or 156
    local srv = load_public_logo_texture()

    if not srv then
        UI.Text("Public_Urinal.png", "gold")

        if UI.publicUrinalLogo.state == "downloading" or
            UI.publicUrinalLogo.state == "queued" then
            UI.Text("Downloading creator logo...", "dim", true)
        else
            UI.Text(
                UI.publicUrinalLogo.error ~= "" and
                    UI.publicUrinalLogo.error or
                    "Creator logo will download automatically.",
                "dim",
                true
            )
        end

        return false
    end

    if not ImGui or
        not ImGui.GetCursorScreenPos or
        not ImGui.Button then
        return false
    end

    local x, y = 0, 0

    direct_call(function()
        x, y = ImGui.GetCursorScreenPos()
    end)

    x = tonumber(x or 0) or 0
    y = tonumber(y or 0) or 0

    -- reserve layout space without painting a button/background behind the
    -- transparent creator png. this lets the porcelain logo float cleanly.
    if ImGui.Dummy then
        direct_call(ImGui.Dummy, size, size)
    elseif ImGui.InvisibleButton then
        direct_call(ImGui.InvisibleButton, "##MinigamesPublicUrinalLogo", size, size)
    else
        direct_call(ImGui.Button, "##MinigamesPublicUrinalLogo", size, size)
    end

    if ImGui.AddImageRounded then
        direct_call(
            ImGui.AddImageRounded,
            srv,
            x,
            y,
            x + size,
            y + size,
            0.0,
            0.0,
            1.0,
            1.0,
            0xFFFFFFFF,
            12.0
        )

        return true
    end

    if ImGui.AddImage then
        direct_call(
            ImGui.AddImage,
            srv,
            x,
            y,
            x + size,
            y + size
        )

        return true
    end

    return false
end

-- ------------------------------------------------------------------
-- friendly child labels.
-- the old build passed internal minigames_* identifiers into cherax.
-- v0.169 always uses the human-facing section title instead.
-- ------------------------------------------------------------------
function UI.Child(name, title, subtitle, callback, titleColor)
    local usedChild = false
    local open = true
    local visibleTitle =
        tostring(title or name or "Section")

    if ClickGUI and ClickGUI.BeginCustomChildWindow then
        local ok, result = direct_call(
            ClickGUI.BeginCustomChildWindow,
            visibleTitle
        )

        if ok then
            usedChild = true
            open = result ~= false
        end
    end

    if open then
        if title and title ~= "" then
            UI.SectionTitle(
                title,
                subtitle,
                titleColor or "purple"
            )
        elseif subtitle and subtitle ~= "" then
            UI.Text(subtitle, "dim", true)
        end

        if type(callback) == "function" then
            local ok, err = direct_call(callback)

            if not ok then
                UI.Text(
                    "Section error: " .. tostring(err),
                    "red",
                    true
                )

                if minigames.LogError then
                    minigames.LogError(
                        "[UI v0.169] " ..
                        tostring(visibleTitle) ..
                        ": " .. tostring(err)
                    )
                end
            end
        end
    end

    if usedChild and open and
        ClickGUI.EndCustomChildWindow then
        direct_call(ClickGUI.EndCustomChildWindow)
    end

    return open
end

local function get_feature(hash)
    if not hash or not FeatureMgr or
        not FeatureMgr.GetFeature then
        return nil
    end

    local feature = nil

    direct_call(function()
        feature = FeatureMgr.GetFeature(hash)
    end)

    return feature
end

local function get_feature_toggle(hash)
    if minigames.GetFeatureBool then
        return minigames.GetFeatureBool(hash, false) == true
    end

    local feature = get_feature(hash)

    if feature and feature.IsToggled then
        local ok, value = direct_call(function()
            return feature:IsToggled()
        end)

        return ok and value == true
    end

    return false
end

local function set_feature_toggle(hash, enabled)
    local feature = get_feature(hash)

    if not feature then return false end

    if feature.Toggle then
        local ok = direct_call(function()
            feature:Toggle(enabled == true)
        end)

        if ok then return true end
    end

    if feature.SetBoolValue then
        local ok = direct_call(function()
            feature:SetBoolValue(enabled == true)
        end)

        if ok then return true end
    end

    if feature.SetValue then
        local ok = direct_call(function()
            feature:SetValue(enabled == true)
        end)

        if ok then return true end
    end

    return false
end

local function reset_feature(hash)
    local feature = get_feature(hash)

    if feature and feature.Reset then
        return direct_call(function()
            feature:Reset()
        end)
    end

    return false
end

local function current_wargames_mode()
    local full = get_feature_toggle(
        minigames.H.WARGAMES_ACTIVATE_SYSTEMS
    )

    local noBounties = get_feature_toggle(
        minigames.H.WARGAMES_ACTIVATE_SYSTEMS_NO_BOUNTIES
    )

    local bounty = get_feature_toggle(
        minigames.H.WARGAMES_AUTO_BOUNTY_TICK
    )

    if full then
        return "WarGames + Bounties", "green", bounty
    end

    if noBounties then
        return "WarGames  -  No Bounties", "cyan", false
    end

    if bounty then
        return "Bounty Maintenance Only", "gold", true
    end

    return "OFF", "red", false
end

function minigames.PerformWarGamesModeChangeV169(mode)
    mode = tostring(mode or "off")
    minigames.S.pendingWarGamesModeV169 = ""
    minigames.S.warGamesModeJobQueuedV169 = false

    if mode == "bounties" then
        set_feature_toggle(
            minigames.H.WARGAMES_ACTIVATE_SYSTEMS_NO_BOUNTIES,
            false
        )

        set_feature_toggle(
            minigames.H.WARGAMES_ACTIVATE_SYSTEMS,
            true
        )

        set_feature_toggle(
            minigames.H.WARGAMES_AUTO_BOUNTY_TICK,
            true
        )

        set_feature_toggle(
            minigames.H.AUTO_BOUNTY_NEW_PLAYERS,
            true
        )

        minigames.S.autoBountyNewPlayers = true
        minigames.S.wargamesNoBountyMode = false

        if minigames.WarGames.AfterActivationButtonV136 then
            direct_call(
                minigames.WarGames.AfterActivationButtonV136,
                "UI v0.169 WarGames + Bounties"
            )
        end

        toast(
            "WarGames started with bounty maintenance.",
            3500
        )

        return true
    end

    if mode == "no_bounties" then
        set_feature_toggle(
            minigames.H.WARGAMES_AUTO_BOUNTY_TICK,
            false
        )

        set_feature_toggle(
            minigames.H.WARGAMES_ACTIVATE_SYSTEMS,
            false
        )

        set_feature_toggle(
            minigames.H.WARGAMES_ACTIVATE_SYSTEMS_NO_BOUNTIES,
            true
        )

        set_feature_toggle(
            minigames.H.AUTO_BOUNTY_NEW_PLAYERS,
            false
        )

        minigames.S.wargamesNoBountyMode = true
        minigames.S.autoBountyRunning = false
        minigames.S.autoBountyEnabled = false
        minigames.S.autoBountyNewPlayers = false

        if minigames.WarGames.AfterActivationButtonV136 then
            direct_call(
                minigames.WarGames.AfterActivationButtonV136,
                "UI v0.169 WarGames No Bounties"
            )
        end

        toast(
            "WarGames started without bounties.",
            3500
        )

        return true
    end

    set_feature_toggle(
        minigames.H.WARGAMES_AUTO_BOUNTY_TICK,
        false
    )

    set_feature_toggle(
        minigames.H.WARGAMES_ACTIVATE_SYSTEMS,
        false
    )

    set_feature_toggle(
        minigames.H.WARGAMES_ACTIVATE_SYSTEMS_NO_BOUNTIES,
        false
    )

    set_feature_toggle(
        minigames.H.WARGAMES_RESPAWN_TICK,
        false
    )

    set_feature_toggle(
        minigames.H.AUTO_BOUNTY_NEW_PLAYERS,
        false
    )

    minigames.S.autoBountyNewPlayers = false

    if minigames.WarGames.DeactivateSystems then
        direct_call(minigames.WarGames.DeactivateSystems)
    end

    minigames.S.wargamesNoBountyMode = false
    minigames.S.autoBountyRunning = false
    minigames.S.autoBountyEnabled = false
    minigames.S.respawnWatcherRunning = false

    if minigames.WarGames.VehicleSpamProtection and
        minigames.WarGames.VehicleSpamProtection.Sync then
        direct_call(
            minigames.WarGames.VehicleSpamProtection.Sync,
            "UI v0.169 WarGames stopped"
        )
    end

    toast("WarGames systems stopped.", 3000)
    return true
end

function minigames.RequestWarGamesModeV169(mode)
    mode = tostring(mode or "off")
    minigames.S.pendingWarGamesModeV169 = mode

    if minigames.S.warGamesModeJobQueuedV169 == true then
        return true
    end

    minigames.S.warGamesModeJobQueuedV169 = true

    queue_job(function()
        yield_ms(50)

        local requested =
            tostring(
                minigames.S.pendingWarGamesModeV169 or "off"
            )

        minigames.PerformWarGamesModeChangeV169(requested)
    end)

    return true
end

function UI.RenderWarGamesLaunchPanel()
    local mode, modeTone, bountyActive =
        current_wargames_mode()

    UI.StatusRow("Current Mode", mode, modeTone)
    UI.StatusRow(
