function minigames.RequestSettingsResetV169()
    minigames.S.showSettingsResetPopupV169 = true
    return true
end

function minigames.PerformDeferredSettingsResetV169()
    if minigames.S.pendingSettingsResetV169 ~= true then
        minigames.S.settingsResetJobQueuedV169 = false
        return false
    end

    minigames.S.pendingSettingsResetV169 = false

    local ok, err = direct_call(function()
        minigames.PerformWarGamesModeChangeV169("off")

        if minigames.ResetSharedSettings then
            minigames.ResetSharedSettings()
        end

        if minigames.ResetSystemSettings then
            minigames.ResetSystemSettings()
        end

        if minigames.WarGames and minigames.WarGames.ResetState then
            minigames.WarGames.ResetState()
        end

        for _, key in ipairs(RESET_FEATURE_KEYS) do
            local hash = minigames.H[key]

            if hash then
                reset_feature(hash)
            end
        end

        set_feature_toggle(
            minigames.H.WARGAMES_ACTIVATE_SYSTEMS,
            false
        )

        set_feature_toggle(
            minigames.H.WARGAMES_ACTIVATE_SYSTEMS_NO_BOUNTIES,
            false
        )

        set_feature_toggle(
            minigames.H.WARGAMES_AUTO_BOUNTY_TICK,
            false
        )

        set_feature_toggle(
            minigames.H.WARGAMES_RESPAWN_TICK,
            false
        )

        if minigames.ResetMinigamesHudPosition then
            minigames.ResetMinigamesHudPosition()
        end

        if minigames.ResetCompactHudPosition then
            minigames.ResetCompactHudPosition()
        end

        minigames.S.uiConfigPageV169 = 0
        minigames.S.uiGuideTopicV169 = 0
        minigames.S.uiGuideHowToV169 = 0
        minigames.S.uiWarGamesPageV169 = 0
        minigames.S.uiGamesPageV169 = 0
        minigames.S.currentMinigame = "None"

        UI.lastRoute = ""
        UI.transitionStartedAt = 0

        if minigames.WarGames.VehicleSpamProtection and
            minigames.WarGames.VehicleSpamProtection.Sync then
            minigames.WarGames.VehicleSpamProtection.Sync(
                "settings reset complete"
            )
        end
    end)

    minigames.S.settingsResetJobQueuedV169 = false

    if ok then
        toast(
            "Settings reset complete. Assets and saved vehicle files were preserved.",
            4500
        )

        if minigames.LogInfo then
            minigames.LogInfo(
                "[UI v0.169] Deferred settings reset complete."
            )
        end

        return true
    end

    if minigames.LogError then
        minigames.LogError(
            "[UI v0.169] Deferred settings reset failed: " ..
            tostring(err)
        )
    end

    toast(
        "Settings reset failed. Check the Cherax log.",
        4500
    )

    return false
end

function minigames.QueueSettingsResetV169()
    minigames.S.pendingSettingsResetV169 = true

    if minigames.S.settingsResetJobQueuedV169 == true then
        return true
    end

    minigames.S.settingsResetJobQueuedV169 = true

    queue_job(function()
        yield_ms(75)
        minigames.PerformDeferredSettingsResetV169()
    end)

    return true
end

function UI.RenderSettingsResetPopupV169()
    if not ImGui or
        not ImGui.OpenPopup or
        not ImGui.BeginPopupModal or
        not ImGui.EndPopup then
        return
    end

    local popupName =
        "Reset Minigames Settings" ..
        "##MinigamesSettingsResetPopup"

    if minigames.S.showSettingsResetPopupV169 == true then
        direct_call(ImGui.OpenPopup, popupName)
    end

    local flags = nil

    if ImGuiWindowFlags and
        ImGuiWindowFlags.AlwaysAutoResize then
        flags = ImGuiWindowFlags.AlwaysAutoResize
    end

    local visible = false

    direct_call(function()
        visible =
            ImGui.BeginPopupModal(
                popupName,
                true,
                flags
            ) == true
    end)

    if not visible then return end

    UI.Text("RESET SETTINGS?", "purple")
    UI.Text(
        "This resets Minigames configuration and safely stops active WarGames systems.",
        "gold",
        true
    )

    UI.Separator()

    UI.Text("WILL RESET", "red")
    UI.Text(
        "HUD placement, UI page choices, vehicle defaults, bounty defaults, respawn defaults, round settings, diagnostics choices, and active WarGames toggles.",
        "white",
        true
    )

    UI.Spacing(1)
    UI.Text("WILL NOT RESET", "green")
    UI.Text(
        "Downloaded GitHub assets, Public_Urinal.png, saved vehicle JSON files, external Cherax themes, or the Minigames.lua release file.",
        "white",
        true
    )

    UI.Separator()

    UI.Button(
        "NO, GO BACK",
        "green",
        function()
            minigames.S.showSettingsResetPopupV169 = false

            if ImGui.CloseCurrentPopup then
                direct_call(ImGui.CloseCurrentPopup)
            end
        end
    )

    UI.SameLine()

    UI.Button(
        "YES, RESET SETTINGS",
        "red",
        function()
            minigames.S.showSettingsResetPopupV169 = false
            minigames.QueueSettingsResetV169()

            if ImGui.CloseCurrentPopup then
                direct_call(ImGui.CloseCurrentPopup)
            end
        end
    )

    direct_call(ImGui.EndPopup)
end

