local function render_colored_lines(lines, tone)
    for index, line in ipairs(lines or {}) do
        UI.Text(
            tostring(index) .. ".",
            tone or "purple"
        )

        UI.SameLine()
        UI.Text(line, "white", true)
        UI.Spacing(1)
    end
end

function UI.RenderGuide()
    UI.RenderTransition(
        "GuideProduct",
        "GUIDE",
        "DriftGod-style focused help with live mode status, color-coded topics, and step-by-step procedures.",
        "blue"
    )

    UI.TwoColumns(
        "MinigamesGuideTopColumns",
        function()
            UI.Child(
                "Quick Start",
                "Quick Start",
                "Three actions cover the normal event lifecycle.",
                function()
                    UI.Text(
                        "GREEN",
                        "green"
                    )
                    UI.SameLine()
                    UI.Text(
                        "Start WarGames with bounties.",
                        "white",
                        true
                    )

                    UI.Text(
                        "BLUE",
                        "cyan"
                    )
                    UI.SameLine()
                    UI.Text(
                        "Start WarGames without bounties.",
                        "white",
                        true
                    )

                    UI.Text(
                        "RED",
                        "red"
                    )
                    UI.SameLine()
                    UI.Text(
                        "Stop all WarGames systems and restore protections.",
                        "white",
                        true
                    )
                end,
                "purple"
            )
        end,
        function()
            UI.Child(
                "Live Mode",
                "Live Mode",
                "Current systems state while reading the guide.",
                function()
                    local mode, modeTone, bounty =
                        current_wargames_mode()

                    UI.StatusRow(
                        "Mode",
                        mode,
                        modeTone
                    )

                    UI.StatusRow(
                        "Bounty Maintain",
                        bounty and "60s FORCE" or "OFF",
                        bounty and "gold" or "dim"
                    )

                    UI.StatusRow(
                        "Respawn",
                        minigames.S.respawnWatcherRunning == true and
                            "ACTIVE" or "OFF",
                        minigames.S.respawnWatcherRunning == true and
                            "green" or "dim"
                    )

                    UI.StatusRow(
                        "Players",
                        minigames.S.activePlayerCount or
                            #(minigames.S.activePlayers or {}),
                        "cyan"
                    )
                end,
                "cyan"
            )
        end
    )

    local topicNames = {}

    for i, item in ipairs(GUIDE_TOPICS_V169) do
        topicNames[i] = item.name
    end

    UI.Child(
        "Guide Topics",
        "Guide Topics",
        "Choose one system; unrelated information stays hidden.",
        function()
            local index = UI.Combo(
                "Topic##MinigamesGuideTopic",
                minigames.S.uiGuideTopicV169,
                topicNames,
                10
            )

            minigames.S.uiGuideTopicV169 = index

            local selected =
                GUIDE_TOPICS_V169[index + 1] or
                GUIDE_TOPICS_V169[1]

            UI.Separator()
            UI.Text(
                selected.name,
                selected.tone or "purple"
            )

            render_colored_lines(
                selected.lines,
                selected.tone
            )
        end,
        "blue"
    )

    local procedureNames = {}

    for i, item in ipairs(GUIDE_HOWTO_V169) do
        procedureNames[i] = item.name
    end

    UI.Child(
        "How To",
        "How To",
        "Step-by-step procedures for the most common Minigames workflows.",
        function()
            local index = UI.Combo(
                "Procedure##MinigamesGuideProcedure",
                minigames.S.uiGuideHowToV169,
                procedureNames,
                8
            )

            minigames.S.uiGuideHowToV169 = index

            local selected =
                GUIDE_HOWTO_V169[index + 1] or
                GUIDE_HOWTO_V169[1]

            UI.Separator()
            UI.Text(
                selected.name,
                selected.tone or "gold"
            )

            render_colored_lines(
                selected.steps,
                selected.tone
            )
        end,
        "gold"
    )
end

