local function render_more_scripts()
    UI.Text("LIKE MINIGAMES?", "purple")

    UI.Text(
        "Join the community Discord for other Public_Urinal projects, updates, support, testing, and showcases.",
        "white",
        true
    )

    UI.Button(
        "OPEN DISCORD & COPY INVITE",
        "blue",
        open_and_copy_discord,
        -1,
        36
    )

    UI.Separator()
    UI.Text(
        "OTHER PUBLIC_URINAL PROJECTS",
        "cyan"
    )

    if ImGui and
        ImGui.BeginTable and
        ImGui.TableNextRow and
        ImGui.TableSetColumnIndex and
        ImGui.EndTable then
        local opened = false
        local flags = 0

        if ImGuiTableFlags and
            ImGuiTableFlags.SizingStretchSame then
            flags =
                ImGuiTableFlags.SizingStretchSame
        end

        direct_call(function()
            opened =
                ImGui.BeginTable(
                    "MinigamesCommunityScripts",
                    2,
                    flags
                ) == true
        end)

        if opened then
            for index, item in ipairs(
                MORE_SCRIPTS_V169
            ) do
                local column = (index - 1) % 2

                if column == 0 then
                    direct_call(ImGui.TableNextRow)
                end

                direct_call(
                    ImGui.TableSetColumnIndex,
                    column
                )

                UI.Text(
                    "• " .. item.name,
                    item.tone
                )

                UI.Text(
                    item.detail,
                    "dim",
                    true
                )

                UI.Spacing(1)
            end

            direct_call(ImGui.EndTable)
        end
    else
        for _, item in ipairs(MORE_SCRIPTS_V169) do
            UI.Text(
                "• " .. item.name,
                item.tone
            )

            UI.Text(
                item.detail,
                "dim",
                true
            )

            UI.Spacing(1)
        end
    end

    UI.Text(
        "All projects shown above are available through the community Discord.",
        "dim",
        true
    )
end

