local DISCORD_LINK = "https://discord.gg/PjZUBMtD3"

local function get_feature_toggle(hash)
    if minigames.GetFeatureBool then
        return minigames.GetFeatureBool(hash, false) == true
    end

    if not hash or
        not FeatureMgr or
        not FeatureMgr.GetFeature then
        return false
    end

    local feature = nil

    direct_call(function()
        feature = FeatureMgr.GetFeature(hash)
    end)

    if feature and feature.IsToggled then
        local ok, result = direct_call(function()
            return feature:IsToggled()
        end)

        return ok and result == true
    end

    return false
end

local function current_mode()
    local full = get_feature_toggle(
        minigames.H.WARGAMES_ACTIVATE_SYSTEMS
    )

    local noBounties = get_feature_toggle(
        minigames.H.WARGAMES_ACTIVATE_SYSTEMS_NO_BOUNTIES
    )

    local bounty = get_feature_toggle(
        minigames.H.WARGAMES_AUTO_BOUNTY_TICK
    )

    if full then
        return "WARGAMES + BOUNTIES", "green", bounty
    end

    if noBounties then
        return "WARGAMES  -  NO BOUNTIES", "cyan", false
    end

    if bounty then
        return "BOUNTY MAINTENANCE ONLY", "gold", true
    end

    return "OFF", "red", false
end

local function copy_text(value)
    value = tostring(value or "")

    if Utils and Utils.SetClipBoardText then
        local ok = direct_call(
            Utils.SetClipBoardText,
            value,
            ""
        )

        if ok then return true end
    end

    if Utils and Utils.SetClipboardText then
        local ok = direct_call(
            Utils.SetClipboardText,
            value
        )

        if ok then return true end
    end

    if ImGui and ImGui.SetClipboardText then
        local ok = direct_call(
            ImGui.SetClipboardText,
            value
        )

        if ok then return true end
    end

    return false
end

local function open_url(value)
    value = tostring(value or "")

    if Utils and Utils.OpenURL then
        local ok, result = direct_call(
            Utils.OpenURL,
            value
        )

        if ok and result ~= false then
            return true
        end
    end

    if Utils and Utils.OpenUrl then
        local ok, result = direct_call(
            Utils.OpenUrl,
            value
        )

        if ok and result ~= false then
            return true
        end
    end

    if GUI and GUI.OpenURL then
        local ok, result = direct_call(
            GUI.OpenURL,
            value
        )

        if ok and result ~= false then
            return true
        end
    end

    return false
end

local function toast(message, milliseconds)
    if minigames.Toast then
        direct_call(
            minigames.Toast,
            "Minigames",
            tostring(message or ""),
            tonumber(milliseconds or 3000) or 3000
        )

        return
    end

    if GUI and GUI.AddToast then
        direct_call(
            GUI.AddToast,
            "Minigames",
            tostring(message or ""),
            tonumber(milliseconds or 3000) or 3000,
            eToastPos and
                (eToastPos.TOP_RIGHT or eToastPos.TopRight) or
                2
        )
    end
end

local function open_discord()
    local copied = copy_text(DISCORD_LINK)
    local opened = open_url(DISCORD_LINK)

    if copied and opened then
        toast("Discord opened and invite copied.", 3200)
    elseif copied then
        toast("Discord invite copied.", 2800)
    elseif opened then
        toast("Discord opened.", 2800)
    else
        toast(
            "Could not open or copy the Discord invite.",
            4200
        )
    end
end

local STEP_TONES = {
    "purple",
    "cyan",
    "gold",
    "green",
    "orange",
    "blue",
}

local function render_colored_steps(lines, primaryTone)
    for index, line in ipairs(lines or {}) do
        local tone =
            STEP_TONES[
                ((index - 1) % #STEP_TONES) + 1
            ]

        if primaryTone and index == 1 then
            tone = primaryTone
        end

        UI.Text(
            tostring(index) .. ".",
            tone
        )

        UI.SameLine()
        UI.Text(
            tostring(line),
            tone,
            true
        )

        UI.Spacing(1)
    end
end

