local function queue_job(callback)
    if Script and Script.QueueJob then
        Script.QueueJob(callback)
        return true
    end

    local ok = direct_call(callback)
    return ok == true
end

local function toast(message, duration)
    if minigames.Toast then
        direct_call(minigames.Toast, tostring(message or ""), duration or 3000)
        return
    end

    if GUI and GUI.AddToast then
        direct_call(
            GUI.AddToast,
            "Minigames",
            tostring(message or ""),
            duration or 3000,
            eToastPos and eToastPos.TOP_RIGHT or 0
        )
    end
end

local function copy_text(value)
    value = tostring(value or "")

    if Utils and Utils.SetClipBoardText then
        local ok = direct_call(Utils.SetClipBoardText, value, "")
        if ok then return true end
    end

    if ImGui and ImGui.SetClipboardText then
        local ok = direct_call(ImGui.SetClipboardText, value)
        if ok then return true end
    end

    return false
end

local function open_url(value)
    value = tostring(value or "")

    if Utils and Utils.OpenURL then
        local ok, result = direct_call(Utils.OpenURL, value)
        if ok and result ~= false then return true end
    end

    if Utils and Utils.OpenUrl then
        local ok, result = direct_call(Utils.OpenUrl, value)
        if ok and result ~= false then return true end
    end

    if GUI and GUI.OpenURL then
        local ok, result = direct_call(GUI.OpenURL, value)
        if ok and result ~= false then return true end
    end

    return false
end

local function open_discord()
    local copied = copy_text(DISCORD_LINK)
    local opened = open_url(DISCORD_LINK)

    if copied and opened then
        toast("Discord opened and invite copied.", 3500)
    elseif copied then
        toast("Discord invite copied.", 3000)
    elseif opened then
        toast("Discord opened.", 3000)
    else
        toast("Could not open or copy the Discord invite.", 4000)
    end
end

local function get_feature_toggle(hash)
    if minigames.GetFeatureBool then
        local ok, value = direct_call(minigames.GetFeatureBool, hash, false)
        if ok then return value == true end
    end

    if not hash or not FeatureMgr or not FeatureMgr.GetFeature then
        return false
    end

    local feature = nil
    direct_call(function()
        feature = FeatureMgr.GetFeature(hash)
    end)

    if feature and feature.IsToggled then
        local ok, value = direct_call(function()
            return feature:IsToggled()
        end)
        return ok and value == true
    end

    return false
end

local function current_mode()
    local full = get_feature_toggle(minigames.H.WARGAMES_ACTIVATE_SYSTEMS)
    local noBounties = get_feature_toggle(minigames.H.WARGAMES_ACTIVATE_SYSTEMS_NO_BOUNTIES)
    local bounty = get_feature_toggle(minigames.H.WARGAMES_AUTO_BOUNTY_TICK)

    if full then
        return "WarGames + Bounties", "green", bounty
    end

    if noBounties then
        return "WarGames: No Bounties", "cyan", false
    end

    if bounty then
        return "Bounty Maintenance Only", "gold", true
    end

    return "OFF", "red", false
end

local function page_header(title, subtitle, tone)
    UI.Text(tostring(title or "MINIGAMES"), tone or "purple")
    if subtitle and subtitle ~= "" then
        UI.Text(subtitle, "dim", true)
    end
    UI.Spacing(1)
end

local function minimal_child(name, title, subtitle, callback, tone)
    local usedChild = false
    local open = true
    local visibleTitle = tostring(name or title or "Section")

    if ClickGUI and ClickGUI.BeginCustomChildWindow then
        local ok, result = direct_call(ClickGUI.BeginCustomChildWindow, visibleTitle)
        if ok then
            usedChild = true
            open = result ~= false
        end
    end

    if open then
        if title and title ~= "" then
            UI.Text(title, tone or "purple")
        end

        if subtitle and subtitle ~= "" then
            UI.Text(subtitle, "dim", true)
        end

        if (title and title ~= "") or (subtitle and subtitle ~= "") then
            UI.Spacing(1)
        end

        if type(callback) == "function" then
            local ok, err = direct_call(callback)
            if not ok then
                UI.Text("Section error: " .. tostring(err), "red", true)
                if minigames.LogError then
                    minigames.LogError("[UI v0.172] " .. visibleTitle .. ": " .. tostring(err))
                end
            end
        end
    end

    if usedChild and open and ClickGUI.EndCustomChildWindow then
        direct_call(ClickGUI.EndCustomChildWindow)
    end

    return open
end

local function render_feature_list(keys)
    for _, key in ipairs(keys or {}) do
        local hash = minigames.H[key]
        if hash and UI.RenderFeature then
            UI.RenderFeature(hash)
        elseif hash and ClickGUI and ClickGUI.RenderFeature then
            direct_call(ClickGUI.RenderFeature, hash)
        end
    end
end

local function render_numbered_lines(lines, tone)
    for index, line in ipairs(lines or {}) do
        UI.Text(tostring(index) .. ".", tone or "purple")
        UI.SameLine()
        UI.Text(tostring(line), "white", true)
        if index < #(lines or {}) then
            UI.Spacing(1)
        end
    end
end

