function UI.RenderSettingsResetPopupV169()
    if not ImGui or not ImGui.OpenPopup or not ImGui.BeginPopupModal or not ImGui.EndPopup then
        return
    end

    local popupName = "Reset Minigames Settings##MinigamesSettingsResetPopup"

    if minigames.S.showSettingsResetPopupV169 == true then
        direct_call(ImGui.OpenPopup, popupName)
    end

    local flags = nil
    if ImGuiWindowFlags and ImGuiWindowFlags.AlwaysAutoResize then
        flags = ImGuiWindowFlags.AlwaysAutoResize
    end

    local visible = false
    direct_call(function()
        visible = ImGui.BeginPopupModal(popupName, true, flags) == true
    end)

    if not visible then return end

    UI.Text("Reset Settings?", "purple")
    UI.Text(
        "This safely stops WarGames and restores Minigames configuration defaults.",
        "white",
        true
    )

    UI.Spacing(2)
    UI.Text("Will Reset", "red")
    UI.Text(
        "HUD placement, UI page choices, vehicle defaults, bounty defaults, respawn defaults, round settings, diagnostic choices, and active WarGames toggles.",
        "white",
        true
    )

    UI.Spacing(1)
    UI.Text("Will Not Reset", "green")
    UI.Text(
        "Downloaded assets, saved vehicle JSON files, external Cherax themes, or the Minigames.lua release file.",
        "white",
        true
    )

    UI.Spacing(2)
    UI.Button(
        "NO, GO BACK",
        "green",
        function()
            minigames.S.showSettingsResetPopupV169 = false
            if ImGui.CloseCurrentPopup then
                direct_call(ImGui.CloseCurrentPopup)
            end
        end
    )

    UI.SameLine()
    UI.Button(
        "YES, RESET SETTINGS",
        "red",
        function()
            minigames.S.showSettingsResetPopupV169 = false
            minigames.QueueSettingsResetV169()
            if ImGui.CloseCurrentPopup then
                direct_call(ImGui.CloseCurrentPopup)
            end
        end
    )

    direct_call(ImGui.EndPopup)
end

