-- ============================================================
-- embedded module: systems\bounty_auto_enroll_v173.lua
-- ============================================================
embedded_modules['systems\\bounty_auto_enroll_v173.lua'] = function()
-- minigames/systems/bounty_auto_enroll_v173.lua
-- v0.173-alpha
--
-- new players are automatically enrolled whenever bounty maintenance is active.
-- player slots are reused by gta, so stale tracking is cleared on a real join.
-- a short retry window allows cherax time to register per-player features.

minigames.WarGames = minigames.WarGames or {}
minigames.Player = minigames.Player or {}

minigames.S.autoBountyJoinRetryMsV173 = 1250
minigames.S.autoBountyJoinMaxAttemptsV173 = 6
minigames.S.autoBountyJoinSerialV173 = minigames.S.autoBountyJoinSerialV173 or 0
minigames.Player.autoBountyJoinSerialV173 = minigames.Player.autoBountyJoinSerialV173 or {}

function minigames.WarGames.IsJoinBountyActiveV173()
    if minigames.S.wargamesNoBountyMode == true or
        minigames.S.wargamesNoBountiesActive == true or
        minigames.S.noBountyMode == true then
        return false
    end

    if minigames.WarGames.IsForceBountyMaintainEnabledV159 then
        local ok, enabled = direct_call(
            minigames.WarGames.IsForceBountyMaintainEnabledV159
        )

        if ok and enabled == true then
            return true
        end
    end

    if minigames.S.autoForceBountyMaintainEnabledV159 == true or
        minigames.S.autoBountyRunning == true or
        minigames.S.autoBountyEnabled == true then
        return true
    end

    if minigames.S.wargamesSystemsActive == true then
        return true
    end

    return false
end

function minigames.WarGames.SyncJoinBountySettingV173()
    local enabled = minigames.WarGames.IsJoinBountyActiveV173()
    minigames.S.autoBountyNewPlayers = enabled

    if minigames.H and minigames.H.AUTO_BOUNTY_NEW_PLAYERS and minigames.SetFeatureBool then
        local current = enabled

        if minigames.GetFeatureBool then
            current = minigames.GetFeatureBool(
                minigames.H.AUTO_BOUNTY_NEW_PLAYERS,
                enabled
            )
        end

        if current ~= enabled then
            direct_call(
                minigames.SetFeatureBool,
                minigames.H.AUTO_BOUNTY_NEW_PLAYERS,
                enabled
            )
        end
    end

    return enabled
end

function minigames.WarGames.ClearJoinBountySlotV173(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if minigames.InitPlayerState then
        minigames.InitPlayerState(playerId)
    end

    minigames.Player.bountyApplied = minigames.Player.bountyApplied or {}
    minigames.Player.bountyAppliedAtMs = minigames.Player.bountyAppliedAtMs or {}
    minigames.Player.bountyTracked = minigames.Player.bountyTracked or {}
    minigames.Player.bountyTrackedAtMs = minigames.Player.bountyTrackedAtMs or {}
    minigames.Player.bountyLastStatus = minigames.Player.bountyLastStatus or {}
    minigames.Player.bountyLastMethod = minigames.Player.bountyLastMethod or {}
    minigames.Player.bountyLastError = minigames.Player.bountyLastError or {}

    minigames.Player.bountyApplied[playerId] = false
    minigames.Player.bountyAppliedAtMs[playerId] = 0
    minigames.Player.bountyTracked[playerId] = false
    minigames.Player.bountyTrackedAtMs[playerId] = 0
    minigames.Player.bountyLastStatus[playerId] = "New player awaiting bounty enrollment"
    minigames.Player.bountyLastMethod[playerId] = "Join Auto-Enroll"
    minigames.Player.bountyLastError[playerId] = "None"
end

function minigames.WarGames.QueueJoinBountyV173(playerId, serial)
    playerId = minigames.ClampInt(playerId, 0, 31)
    serial = tonumber(serial) or 0

    local function worker()
        local attempts = minigames.S.autoBountyJoinMaxAttemptsV173 or 6
        local retryMs = minigames.S.autoBountyJoinRetryMsV173 or 1250

        for attempt = 1, attempts do
            if minigames.Player.autoBountyJoinSerialV173[playerId] ~= serial then
                return false, "superseded"
            end

            if not minigames.WarGames.IsJoinBountyActiveV173() then
                return false, "bounty_disabled"
            end

            if not minigames.IsPlayerActive(playerId) then
                return false, "player_inactive"
            end

            if minigames.IsBountyTracked and minigames.IsBountyTracked(playerId) then
                minigames.S.lastBountyStatus =
                    "New player auto-enrolled | player=" ..
                    tostring(playerId) ..
                    " | name=" ..
                    minigames.GetPlayerName(playerId)

                if minigames.WarGames.BountyLog then
                    minigames.WarGames.BountyLog(minigames.S.lastBountyStatus)
                end

                return true, "already_applied"
            end

            local ok, status = false, "bounty_function_missing"

            if minigames.WarGames.ForceBountyOnPlayer then
                ok, status = minigames.WarGames.ForceBountyOnPlayer(
                    playerId,
                    "New Player Auto-Enroll v0.173"
                )
            elseif minigames.ApplyBuiltInBounty then
                ok, status = minigames.ApplyBuiltInBounty(playerId, true)
            end

            if ok then
                minigames.S.lastBountyStatus =
                    "New player auto-enrolled | player=" ..
                    tostring(playerId) ..
                    " | name=" ..
                    minigames.GetPlayerName(playerId) ..
                    " | attempt=" ..
                    tostring(attempt)

                if minigames.WarGames.BountyLog then
                    minigames.WarGames.BountyLog(minigames.S.lastBountyStatus)
                end

                return true, "applied"
            end

            minigames.S.lastBountyStatus =
                "New player bounty retry | player=" ..
                tostring(playerId) ..
                " | attempt=" ..
                tostring(attempt) ..
                " | status=" ..
                tostring(status)

            if attempt < attempts and Script and Script.Yield then
                Script.Yield(retryMs)
            end
        end

        minigames.S.lastBountyStatus =
            "New player bounty enrollment failed | player=" ..
            tostring(playerId) ..
            " | name=" ..
            minigames.GetPlayerName(playerId)

        if minigames.LogError then
            minigames.LogError(
                "[WarGames Bounty] " ..
                minigames.S.lastBountyStatus
            )
        end

        return false, "retry_exhausted"
    end

    if minigames.Queue then
        minigames.Queue(worker)
        return true, "queued"
    end

    if Script and Script.QueueJob then
        Script.QueueJob(worker)
        return true, "queued"
    end

    return worker()
end

local previousOnPlayerJoinedV173 = minigames.WarGames.OnPlayerJoined

function minigames.WarGames.OnPlayerJoined(playerId)
    playerId = minigames.ClampInt(playerId, 0, 31)

    if minigames.EnsurePlayerTables then
        minigames.EnsurePlayerTables()
    elseif minigames.InitPlayerState then
        minigames.InitPlayerState(playerId)
    end

    -- gta can assign a new person to a slot that was previously marked as
    -- bounty-applied. clear that stale state before older join logic runs.
    minigames.WarGames.ClearJoinBountySlotV173(playerId)

    local bountyActive =
        minigames.WarGames.SyncJoinBountySettingV173()

    if previousOnPlayerJoinedV173 then
        local ok, err = direct_call(
            previousOnPlayerJoinedV173,
            playerId
        )

        if not ok and minigames.LogError then
            minigames.LogError(
                "[WarGames Join] Previous join handler error: " ..
                tostring(err)
            )
        end
    end

    if not bountyActive then
        return true
    end

    minigames.S.autoBountyJoinSerialV173 =
        (minigames.S.autoBountyJoinSerialV173 or 0) + 1

    local serial = minigames.S.autoBountyJoinSerialV173
    minigames.Player.autoBountyJoinSerialV173[playerId] = serial

    return minigames.WarGames.QueueJoinBountyV173(
        playerId,
        serial
    )
end

-- keep the visible setting synchronized with the active bounty mode.
if minigames.Scheduler and minigames.Scheduler.Tick and
    minigames.__v173JoinBountySchedulerHook ~= true then
    minigames.__v173JoinBountySchedulerHook = true
    local oldSchedulerTickV173 = minigames.Scheduler.Tick

    function minigames.Scheduler.Tick(...)
        local result = oldSchedulerTickV173(...)
        local now = minigames.Now and minigames.Now() or 0
        local lastSync =
            tonumber(minigames.S.lastJoinBountySyncMsV173 or 0) or 0

        if lastSync == 0 or now - lastSync >= 1000 then
            minigames.S.lastJoinBountySyncMsV173 = now
            minigames.WarGames.SyncJoinBountySettingV173()
        end

        return result
    end
end

minigames.VERSION = "v0.183-alpha"
minigames.BUILD_DATE = "2026-07-29"
minigames.S.singleFileEmbeddedModuleCountV173 = 55

if minigames.LogInfo then
    minigames.LogInfo(
        "Bounty auto-enroll v0.173 active: new players are enrolled whenever bounty maintenance is enabled."
    )
end
end


-- ============================================================
-- remote asset: minigames_logo.png
--
-- github repository path:
--   minigames/assets/minigames_logo.png
--
-- the lua remains one executable file. the png is downloaded once,
-- validated, cached under cherax\lua\minigames\assets, and reused.
-- ============================================================
local MINIGAMES_INTRO_LOGO_REMOTE_ENABLED = true
local MINIGAMES_INTRO_LOGO_REMOTE_URL =
    "https://raw.githubusercontent.com/" ..
    "xReVoLTiThemeDev/GTAV-Cherax/refs/heads/main/" ..
    "Minigames/assets/Minigames_Logo.png"

local MINIGAMES_INTRO_LOGO_FILE =
    "Minigames_Logo.png"

local MINIGAMES_INTRO_LOGO_EXPECTED_SIZE = 2124090
local MINIGAMES_INTRO_LOGO_EXPECTED_WIDTH = 1536
local MINIGAMES_INTRO_LOGO_EXPECTED_HEIGHT = 1024
local MINIGAMES_INTRO_LOGO_SHA256 =
    "6d1e5c1c91141a7c8950c57a9d8db453" ..
    "954700b70fd7ffbaa9b03fd346bbc320"

local MINIGAMES_INTRO_LOGO_TIMEOUT_TICKS = 300
local MINIGAMES_INTRO_LOGO_TIMEOUT_YIELD_MS = 50

local MINIGAMES_VERBOSE_BOOT_LOGS_V205 = false

local function __mg_loader_log(message)
    if MINIGAMES_VERBOSE_BOOT_LOGS_V205 ~= true then
        return
    end
    if Logger and Logger.LogInfo then
        Logger.LogInfo(
            "[Minigames Single File] " ..
            tostring(message)
        )
    end
end

local function __mg_loader_error(message)
    if Logger and Logger.LogError then
        Logger.LogError(
            "[Minigames Single File] " ..
            tostring(message)
        )
    elseif Logger and Logger.LogInfo then
        Logger.LogInfo(
            "[Minigames Single File ERROR] " ..
            tostring(message)
        )
    end
end

local function __mg_loader_wait(milliseconds)
    milliseconds = tonumber(milliseconds or 0) or 0

    if Script and Script.Yield then
        Script.Yield(milliseconds)
        return
    end

    if SYSTEM and SYSTEM.WAIT then
        SYSTEM.WAIT(milliseconds)
    end
end

local function __mg_normalize_module_path(relativePath)
    local path = tostring(relativePath or "")
    path = path:gsub("/", "\\")
    path = path:gsub("\\+", "\\")
    path = path:gsub("^\\+", "")
    return path
end

local function __mg_ensure_dir(path)
    path = tostring(path or "")
    if path == "" then return false end

    if FileMgr and FileMgr.CreateDir then
        FileMgr.CreateDir(path)
        return true
    end

    return false
end

local function __mg_u32_be(data, offset)
    if type(data) ~= "string" then return nil end
    offset = tonumber(offset or 1) or 1

    local a, b, c, d = data:byte(
        offset,
        offset + 3
    )

    if not a or not b or not c or not d then
        return nil
    end

    return
        a * 16777216 +
        b * 65536 +
        c * 256 +
        d
end

local function __mg_validate_png_bytes(body)
    if type(body) ~= "string" or #body < 1000 then
        return false, "file too small"
    end

    if body:byte(1) ~= 137 or
        body:sub(2, 4) ~= "PNG" or
        body:sub(5, 8) ~= "\r\n\26\n" then
        return false, "invalid PNG signature"
    end

    if body:sub(13, 16) ~= "IHDR" then
        return false, "missing PNG IHDR"
    end

    local width = __mg_u32_be(body, 17)
    local height = __mg_u32_be(body, 21)

    if width ~= MINIGAMES_INTRO_LOGO_EXPECTED_WIDTH or
        height ~= MINIGAMES_INTRO_LOGO_EXPECTED_HEIGHT then
        return false,
            "unexpected dimensions " ..
            tostring(width) .. "x" .. tostring(height)
    end

    return true,
        "valid PNG " ..
        tostring(width) .. "x" .. tostring(height) ..
        " | bytes=" .. tostring(#body)
end

local function __mg_validate_png_file(path)
    path = tostring(path or "")
    if path == "" then return false, "empty path" end

    local file = io.open(path, "rb")
    if not file then
        return false, "missing"
    end

    local header = file:read(32) or ""
    local size = file:seek("end") or 0
    file:close()

    if tonumber(size or 0) < 1000 then
        return false, "file too small"
    end

    if header:byte(1) ~= 137 or
        header:sub(2, 4) ~= "PNG" or
        header:sub(5, 8) ~= "\r\n\26\n" then
        return false, "invalid PNG signature"
    end

    if header:sub(13, 16) ~= "IHDR" then
        return false, "missing PNG IHDR"
    end

    local width = __mg_u32_be(header, 17)
    local height = __mg_u32_be(header, 21)

    if width ~= MINIGAMES_INTRO_LOGO_EXPECTED_WIDTH or
        height ~= MINIGAMES_INTRO_LOGO_EXPECTED_HEIGHT then
        return false,
            "unexpected dimensions " ..
            tostring(width) .. "x" .. tostring(height)
    end

    return true,
        "valid cached PNG " ..
        tostring(width) .. "x" .. tostring(height) ..
        " | bytes=" .. tostring(size)
end

local function __mg_copy_file(sourcePath, targetPath)
    local source = io.open(sourcePath, "rb")
    if not source then
        return false, "source open failed"
    end

    local body = source:read("*a")
    source:close()

    local valid, validation =
        __mg_validate_png_bytes(body)

    if not valid then
        return false,
            "source validation failed: " ..
            tostring(validation)
    end

    local target = io.open(targetPath, "wb")
    if not target then
        return false, "target open failed"
    end

    target:write(body)
    target:close()

    local targetValid, targetStatus =
        __mg_validate_png_file(targetPath)

    if not targetValid then
        direct_call(function() os.remove(targetPath) end)

        return false,
            "copied-file validation failed: " ..
            tostring(targetStatus)
    end

    return true, targetStatus
end

local function __mg_curl_set_opt(
    curl,
    enumName,
    numericValue,
    value
)
    if not curl or not curl.Setopt then return end

    local option = numericValue

    direct_call(function()
        if eCurlOption and eCurlOption[enumName] then
            option = eCurlOption[enumName]
        end
    end)

    direct_call(function()
        curl:Setopt(option, value)
    end)
end

local function __mg_curl_finished(curl)
    if not curl or not curl.GetFinished then
        return false
    end

    local ok, finished = direct_call(function()
        return curl:GetFinished()
    end)

    return ok and finished == true
end

local function __mg_download_intro_logo(
    assetRoot,
    force
)
    assetRoot = tostring(assetRoot or "")

    local targetPath =
        assetRoot .. "\\" ..
        MINIGAMES_INTRO_LOGO_FILE

    if force ~= true then
        local existing, existingStatus =
            __mg_validate_png_file(targetPath)

        if existing then
            return true,
                "existing | " .. tostring(existingStatus),
                targetPath
        end
    end

    if MINIGAMES_INTRO_LOGO_REMOTE_ENABLED ~= true then
        return false, "remote download disabled", targetPath
    end

    if not Curl or not Curl.Easy then
        return false, "Curl unavailable", targetPath
    end

    __mg_ensure_dir(assetRoot)

    local curl = Curl.Easy()

    __mg_curl_set_opt(
        curl,
        "CURLOPT_URL",
        10002,
        MINIGAMES_INTRO_LOGO_REMOTE_URL
    )

    __mg_curl_set_opt(
        curl,
        "CURLOPT_USERAGENT",
        10018,
        "Mozilla/5.0 Minigames-Cherax"
    )

    local performOk, performError = direct_call(function()
        curl:Perform()
    end)

    if not performOk then
        return false,
            "Curl perform failed: " ..
            tostring(performError),
            targetPath
    end

    local ticks = 0

    while not __mg_curl_finished(curl) and
        ticks < MINIGAMES_INTRO_LOGO_TIMEOUT_TICKS do
        __mg_loader_wait(
            MINIGAMES_INTRO_LOGO_TIMEOUT_YIELD_MS
        )

        ticks = ticks + 1
    end

    if not __mg_curl_finished(curl) then
        return false,
            "download timeout after " ..
            tostring(
                MINIGAMES_INTRO_LOGO_TIMEOUT_TICKS *
                MINIGAMES_INTRO_LOGO_TIMEOUT_YIELD_MS
            ) ..
            "ms",
            targetPath
    end

    local responseOk, code, body = direct_call(function()
        return curl:GetResponse()
    end)

    if not responseOk then
        return false,
            "GetResponse failed: " .. tostring(code),
            targetPath
    end

    local transferSuccess =
        code == true or
        code == 0

    direct_call(function()
        if eCurlCode and
            code == eCurlCode.CURLE_OK then
            transferSuccess = true
        end
    end)

    if not transferSuccess then
        return false,
            "download failed | code=" ..
            tostring(code) ..
            " | bytes=" ..
            tostring(
                type(body) == "string" and
                #body or 0
            ),
            targetPath
    end

    local validBody, bodyStatus =
        __mg_validate_png_bytes(body)

    if not validBody then
        return false,
            "download validation failed: " ..
            tostring(bodyStatus),
            targetPath
    end

    local temporaryPath = targetPath .. ".download"

    direct_call(function()
        os.remove(temporaryPath)
    end)

    local temporary = io.open(temporaryPath, "wb")
    if not temporary then
        return false,
            "temporary file open failed",
            targetPath
    end

    temporary:write(body)
    temporary:close()

    local tempValid, tempStatus =
        __mg_validate_png_file(temporaryPath)

    if not tempValid then
        direct_call(function()
            os.remove(temporaryPath)
        end)

        return false,
            "temporary validation failed: " ..
            tostring(tempStatus),
            targetPath
    end

    direct_call(function()
        os.remove(targetPath)
    end)

    local renamed = false

    direct_call(function()
        renamed =
            os.rename(
                temporaryPath,
                targetPath
            ) == true
    end)

    if not renamed then
        local final = io.open(targetPath, "wb")

        if not final then
            direct_call(function()
                os.remove(temporaryPath)
            end)

            return false,
                "final file open failed",
                targetPath
        end

        final:write(body)
        final:close()

        direct_call(function()
            os.remove(temporaryPath)
        end)
    end

    local finalValid, finalStatus =
        __mg_validate_png_file(targetPath)

    if not finalValid then
        return false,
            "final validation failed: " ..
            tostring(finalStatus),
            targetPath
    end

    return true,
        "downloaded | " .. tostring(finalStatus),
        targetPath
end

local function __mg_ensure_intro_logo_asset(
    assetRoot,
    luaRoot,
    force
)
    assetRoot = tostring(assetRoot or "")
    luaRoot = tostring(luaRoot or "")

    local targetPath =
        assetRoot .. "\\" ..
        MINIGAMES_INTRO_LOGO_FILE

    if force ~= true then
        local valid, status =
            __mg_validate_png_file(targetPath)

        if valid then
            return true,
                "existing | " .. tostring(status),
                targetPath
        end

        -- migrate the original asset from the old folder build when present.
        local legacyPath =
            luaRoot ..
            "\\Minigames_Backup\\assets\\" ..
            MINIGAMES_INTRO_LOGO_FILE

        local legacyValid =
            __mg_validate_png_file(legacyPath)

        if legacyValid then
            __mg_ensure_dir(assetRoot)

            local copied, copyStatus =
                __mg_copy_file(
                    legacyPath,
                    targetPath
                )

            if copied then
                return true,
                    "migrated from Minigames_Backup | " ..
                    tostring(copyStatus),
                    targetPath
            end
        end
    end

    return __mg_download_intro_logo(
        assetRoot,
        force == true
    )
end


