embedded_modules['systems\\purge_ui_v175.lua'] = function()
-- minigames/systems/purge_ui_v175.lua
-- v0.175-alpha
-- the purge presentation layer is loaded through the normal single-file boot.
-- it adds a visible tab inside minigames plus a native fade intro and hud.

minigames.S = minigames.S or {}
minigames.H = minigames.H or {}
minigames.PurgeUI = minigames.PurgeUI or {}
minigames.UIX = minigames.UIX or {}

local P = minigames.PurgeUI
local UI = minigames.UIX

local function now_ms()
    if minigames.Now then
        local ok, value = direct_call(minigames.Now)
        if ok and value then return value end
    end
    if Time and Time.GetEpocheMs then
        local ok, value = direct_call(Time.GetEpocheMs)
        if ok and value then return value end
    end
    return math.floor((os.clock() or 0) * 1000)
end

local function clamp(value, minimum, maximum)
    value = tonumber(value or 0) or 0
    if value < minimum then return minimum end
    if value > maximum then return maximum end
    return value
end

local function ease_out_quad(value)
    value = clamp(value, 0.0, 1.0)
    return 1.0 - ((1.0 - value) * (1.0 - value))
end

local function format_clock(milliseconds)
    local total = math.max(0, math.floor((tonumber(milliseconds or 0) or 0) / 1000))
    local hours = math.floor(total / 3600)
    local minutes = math.floor((total % 3600) / 60)
    local seconds = total % 60
    if hours > 0 then
        return string.format('%02d:%02d:%02d', hours, minutes, seconds)
    end
    return string.format('%02d:%02d', minutes, seconds)
end

local function draw_rect(left, top, width, height, r, g, b, a)
    if minigames.DrawRect then
        minigames.DrawRect(left + width / 2.0, top + height / 2.0, width, height, r, g, b, a)
    end
end

local function draw_left(text, x, y, scale, r, g, b, a, font)
    if minigames.DrawTextLeft then
        minigames.DrawTextLeft(text, x, y, scale, r, g, b, a, font)
    elseif minigames.DrawText then
        minigames.DrawText(text, x, y, scale, r, g, b, a, font)
    end
end

local function draw_center(text, x, y, scale, r, g, b, a, font)
    if minigames.DrawText then
        minigames.DrawText(text, x, y, scale, r, g, b, a, font)
    end
end

local function timer_color(milliseconds, maximum)
    maximum = math.max(1, tonumber(maximum or 1) or 1)
    local ratio = clamp((tonumber(milliseconds or 0) or 0) / maximum, 0.0, 1.0)
    if ratio > 0.60 then return 110, 235, 145 end
    if ratio > 0.30 then return 255, 220, 95 end
    if ratio > 0.15 then return 255, 150, 70 end
    return 255, 75, 75
end

local function begin_child(name)
    if ClickGUI and ClickGUI.BeginCustomChildWindow then
        local ok, opened = direct_call(ClickGUI.BeginCustomChildWindow, name)
        if ok then return opened == true end
    end
    return true
end

local function end_child()
    if ClickGUI and ClickGUI.EndCustomChildWindow then
        direct_call(ClickGUI.EndCustomChildWindow)
    end
end

