minigames.S.purgeIntroEnabled = minigames.S.purgeIntroEnabled == true
minigames.S.purgeIntroStartMs = tonumber(minigames.S.purgeIntroStartMs or 0) or 0
minigames.S.purgeIntroFadeInMs = tonumber(minigames.S.purgeIntroFadeInMs or 900) or 900
minigames.S.purgeIntroHoldMs = tonumber(minigames.S.purgeIntroHoldMs or 2400) or 2400
minigames.S.purgeIntroFadeOutMs = tonumber(minigames.S.purgeIntroFadeOutMs or 1800) or 1800
minigames.S.purgeHudEnabled = minigames.S.purgeHudEnabled == true
minigames.S.purgeHudPreviewEnabled = minigames.S.purgeHudPreviewEnabled ~= false
minigames.S.purgeHudX = tonumber(minigames.S.purgeHudX or 0.774) or 0.774
minigames.S.purgeHudY = tonumber(minigames.S.purgeHudY or 0.205) or 0.205
minigames.S.purgeHudW = tonumber(minigames.S.purgeHudW or 0.220) or 0.220
minigames.S.purgeHudAlpha = tonumber(minigames.S.purgeHudAlpha or 168) or 168
minigames.S.purgeHudAccentAlpha = tonumber(minigames.S.purgeHudAccentAlpha or 215) or 215
minigames.S.purgeHudPulse = minigames.S.purgeHudPulse ~= false
minigames.S.purgeDemoPhase = minigames.S.purgeDemoPhase or 'HUNT ACTIVE'
minigames.S.purgeDemoTargetName = minigames.S.purgeDemoTargetName or 'Target Player'
minigames.S.purgeDemoProgressDone = tonumber(minigames.S.purgeDemoProgressDone or 4) or 4
minigames.S.purgeDemoProgressTotal = tonumber(minigames.S.purgeDemoProgressTotal or 13) or 13
minigames.S.purgeDemoTargetTimeMs = tonumber(minigames.S.purgeDemoTargetTimeMs or 161000) or 161000
minigames.S.purgeDemoTargetTimeMaxMs = tonumber(minigames.S.purgeDemoTargetTimeMaxMs or 300000) or 300000
minigames.S.purgeDemoGlobalTimeMs = tonumber(minigames.S.purgeDemoGlobalTimeMs or 2194000) or 2194000
minigames.S.purgeDemoGlobalTimeMaxMs = tonumber(minigames.S.purgeDemoGlobalTimeMaxMs or 2700000) or 2700000
minigames.S.purgeDemoExcludedCount = tonumber(minigames.S.purgeDemoExcludedCount or 2) or 2
minigames.S.purgeDemoAliveTargets = tonumber(minigames.S.purgeDemoAliveTargets or 9) or 9
minigames.S.purgeDemoStatus = minigames.S.purgeDemoStatus or 'Eliminate the current target yourself. Do not die.'
minigames.S.purgeIntroTitle = minigames.S.purgeIntroTitle or 'THE PURGE'
minigames.S.purgeIntroSubtitle = minigames.S.purgeIntroSubtitle or 'Single target bounty hunt'
minigames.S.purgeIntroLine2 = minigames.S.purgeIntroLine2 or 'Track down one marked player before time expires'
minigames.S.purgeIntroLine3 = minigames.S.purgeIntroLine3 or 'One life. One run. Purge Hour awaits.'

function P.ResetPreview()
    minigames.S.purgeDemoPhase = 'HUNT ACTIVE'
    minigames.S.purgeDemoTargetName = 'Target Player'
    minigames.S.purgeDemoProgressDone = 4
    minigames.S.purgeDemoProgressTotal = 13
    minigames.S.purgeDemoTargetTimeMs = 161000
    minigames.S.purgeDemoTargetTimeMaxMs = 300000
    minigames.S.purgeDemoGlobalTimeMs = 2194000
    minigames.S.purgeDemoGlobalTimeMaxMs = 2700000
    minigames.S.purgeDemoExcludedCount = 2
    minigames.S.purgeDemoAliveTargets = 9
    minigames.S.purgeDemoStatus = 'Eliminate the current target yourself. Do not die.'
end

function P.StartIntro(reason)
    minigames.S.purgeIntroEnabled = true
    minigames.S.purgeIntroStartMs = now_ms()
    minigames.S.purgeIntroReason = tostring(reason or 'Manual preview')
end

function P.StartPreview()
    P.ResetPreview()
    minigames.S.purgeHudPreviewEnabled = true
    minigames.S.purgeHudEnabled = true
    P.StartIntro('Purge preview')
    if minigames.Toast then minigames.Toast('The Purge', 'Intro and HUD preview started.', 2500) end
end

function P.StopPreview()
    minigames.S.purgeIntroEnabled = false
    minigames.S.purgeHudEnabled = false
    if minigames.Toast then minigames.Toast('The Purge', 'Preview stopped.', 2000) end
end

function P.CyclePhase()
    local phases = {'PREPARING', 'HUNT ACTIVE', 'TARGET LOST', 'PURGE HOUR', 'COMPLETE', 'FAILED'}
    local current = tostring(minigames.S.purgeDemoPhase or phases[1])
    local index = 1
    for i, phase in ipairs(phases) do
        if phase == current then index = i break end
    end
    index = index + 1
    if index > #phases then index = 1 end
    minigames.S.purgeDemoPhase = phases[index]

    local messages = {
        PREPARING = 'Locking eligible players and preparing target order.',
        ['HUNT ACTIVE'] = 'Eliminate the current target yourself. Do not die.',
        ['TARGET LOST'] = 'Another player claimed the target. Waiting to reapply the bounty.',
        ['PURGE HOUR'] = 'Victory reward active. Eligible bounties continuously cycle.',
        COMPLETE = 'Every required target was eliminated without dying.',
        FAILED = 'The run ended before the roster was completed.'
    }
    minigames.S.purgeDemoStatus = messages[minigames.S.purgeDemoPhase] or 'Preview active.'
end

function P.AdvancePreview()
    local done = tonumber(minigames.S.purgeDemoProgressDone or 0) or 0
    local total = math.max(1, tonumber(minigames.S.purgeDemoProgressTotal or 1) or 1)
    if done < total then
        done = done + 1
        minigames.S.purgeDemoProgressDone = done
        minigames.S.purgeDemoTargetName = 'Target Player ' .. tostring(done + 1)
        if done >= total then
            minigames.S.purgeDemoPhase = 'COMPLETE'
            minigames.S.purgeDemoStatus = 'Every required target was eliminated without dying.'
        end
    end
end

function P.TickDownPreview()
    minigames.S.purgeDemoTargetTimeMs = math.max(0, (tonumber(minigames.S.purgeDemoTargetTimeMs or 0) or 0) - 15000)
    minigames.S.purgeDemoGlobalTimeMs = math.max(0, (tonumber(minigames.S.purgeDemoGlobalTimeMs or 0) or 0) - 30000)
end

function P.GetState()
    if minigames.S.purgeActive == true or minigames.S.purgeHudLive == true then
        return {
            active = true,
            liveMode = true,
            phase = tostring(minigames.S.purgePhase or 'HUNT ACTIVE'),
            targetName = tostring(minigames.S.purgeTargetName or 'Unknown'),
            progressDone = tonumber(minigames.S.purgeProgressDone or 0) or 0,
            progressTotal = tonumber(minigames.S.purgeProgressTotal or 0) or 0,
            targetTimeMs = tonumber(minigames.S.purgeTargetTimeMs or 0) or 0,
            targetTimeMaxMs = tonumber(minigames.S.purgeTargetTimeMaxMs or minigames.S.purgeTargetTimeMs or 1) or 1,
            globalTimeMs = tonumber(minigames.S.purgeGlobalTimeMs or 0) or 0,
            globalTimeMaxMs = tonumber(minigames.S.purgeGlobalTimeMaxMs or minigames.S.purgeGlobalTimeMs or 1) or 1,
            excludedCount = tonumber(minigames.S.purgeExcludedCount or 0) or 0,
            aliveTargets = tonumber(minigames.S.purgeAliveTargets or 0) or 0,
            mode = tostring(minigames.S.purgeModeLabel or 'SOLO'),
            status = tostring(minigames.S.purgeStatusText or 'Purge active.')
        }
    end

    return {
        active = minigames.S.purgeHudPreviewEnabled == true,
        liveMode = false,
        phase = tostring(minigames.S.purgeDemoPhase or 'HUNT ACTIVE'),
        targetName = tostring(minigames.S.purgeDemoTargetName or 'Target Player'),
        progressDone = tonumber(minigames.S.purgeDemoProgressDone or 0) or 0,
        progressTotal = tonumber(minigames.S.purgeDemoProgressTotal or 0) or 0,
        targetTimeMs = tonumber(minigames.S.purgeDemoTargetTimeMs or 0) or 0,
        targetTimeMaxMs = tonumber(minigames.S.purgeDemoTargetTimeMaxMs or 1) or 1,
        globalTimeMs = tonumber(minigames.S.purgeDemoGlobalTimeMs or 0) or 0,
        globalTimeMaxMs = tonumber(minigames.S.purgeDemoGlobalTimeMaxMs or 1) or 1,
        excludedCount = tonumber(minigames.S.purgeDemoExcludedCount or 0) or 0,
        aliveTargets = tonumber(minigames.S.purgeDemoAliveTargets or 0) or 0,
        mode = 'PREVIEW',
        status = tostring(minigames.S.purgeDemoStatus or 'Preview active.')
    }
end

function P.DrawIntro()
    if minigames.S.purgeUiThemeEnabled == false or minigames.S.purgeIntroEnabled ~= true then return end

    local fadeIn = math.max(1, tonumber(minigames.S.purgeIntroFadeInMs or 900) or 900)
    local hold = math.max(0, tonumber(minigames.S.purgeIntroHoldMs or 2400) or 2400)
    local fadeOut = math.max(1, tonumber(minigames.S.purgeIntroFadeOutMs or 1800) or 1800)
    local elapsed = now_ms() - (tonumber(minigames.S.purgeIntroStartMs or 0) or 0)
    local total = fadeIn + hold + fadeOut

    if elapsed >= total then
        minigames.S.purgeIntroEnabled = false
        return
    end

    local factor = 1.0
    if elapsed < fadeIn then
        factor = ease_out_quad(elapsed / fadeIn)
    elseif elapsed > fadeIn + hold then
        factor = 1.0 - ease_out_quad((elapsed - fadeIn - hold) / fadeOut)
    end
    factor = clamp(factor, 0.0, 1.0)

    local alpha = math.floor(255 * factor)
    local pulse = minigames.S.purgeHudPulse ~= false and (math.sin(now_ms() * 0.0045) * 0.5 + 0.5) or 0.3
    local red = math.floor(190 + 45 * pulse)

    draw_rect(0.285, 0.300, 0.430, 0.205, 0, 0, 0, math.floor(145 * factor))
    draw_rect(0.320, 0.326, 0.360, 0.0045, red, 42, 42, math.floor(205 * factor))
    draw_rect(0.345, 0.470, 0.310, 0.0035, red, 42, 42, math.floor(165 * factor))
    draw_center(tostring(minigames.S.purgeIntroTitle or 'THE PURGE'), 0.500, 0.352, 1.02, red, 38, 38, alpha, 7)
    draw_center(tostring(minigames.S.purgeIntroSubtitle or 'Single target bounty hunt'), 0.500, 0.410, 0.355, 255, 255, 255, math.floor(alpha * 0.95), 4)
    draw_center(tostring(minigames.S.purgeIntroLine2 or 'Track down one marked player before time expires'), 0.500, 0.448, 0.295, 255, 215, 215, math.floor(alpha * 0.88), 4)
    draw_center(tostring(minigames.S.purgeIntroLine3 or 'One life. One run. Purge Hour awaits.'), 0.500, 0.488, 0.255, 255, 132, 132, math.floor(alpha * 0.82), 4)
end

function P.DrawHud()
    if minigames.S.purgeUiThemeEnabled == false or minigames.S.purgeHudEnabled ~= true then return end
    if minigames.S.purgeIntroEnabled == true then return end

    local state = P.GetState()
    if not state or state.active ~= true then return end

    local left = tonumber(minigames.S.purgeHudX or 0.774) or 0.774
    local top = tonumber(minigames.S.purgeHudY or 0.205) or 0.205
    local width = tonumber(minigames.S.purgeHudW or 0.220) or 0.220
    local alpha = clamp(minigames.S.purgeHudAlpha or 168, 40, 255)
    local accentAlpha = clamp(minigames.S.purgeHudAccentAlpha or 215, 60, 255)
    local pulse = minigames.S.purgeHudPulse ~= false and (math.sin(now_ms() * 0.0045) * 0.5 + 0.5) or 0.3
    local red = math.floor(176 + 48 * pulse)

    draw_rect(left, top, width, 0.258, 7, 7, 9, alpha)
    draw_rect(left, top, width, 0.028, red, 34, 34, accentAlpha)
    draw_rect(left + 0.010, top + 0.044, width - 0.020, 0.0035, 80, 18, 18, 190)

    draw_left('THE PURGE', left + 0.010, top + 0.006, 0.258, 255, 255, 255, 240, 7)
    local liveLabel = state.liveMode and ('LIVE  ' .. tostring(state.mode or 'SOLO')) or 'PREVIEW'
    draw_left(liveLabel, left + width - 0.105, top + 0.006, 0.185, 255, 215, 215, 220, 4)
    draw_left('State', left + 0.010, top + 0.038, 0.205, 255, 170, 170, 220, 4)
    draw_left(state.phase, left + 0.085, top + 0.038, 0.215, 255, 255, 255, 235, 4)
    draw_left('Target', left + 0.010, top + 0.065, 0.205, 255, 170, 170, 220, 4)
    draw_left(state.targetName, left + 0.085, top + 0.065, 0.215, 255, 255, 255, 235, 4)

    local tr, tg, tb = timer_color(state.targetTimeMs, state.targetTimeMaxMs)
    local gr, gg, gb = timer_color(state.globalTimeMs, state.globalTimeMaxMs)
    draw_left('Target Time', left + 0.010, top + 0.097, 0.205, 255, 170, 170, 220, 4)
    draw_left(format_clock(state.targetTimeMs), left + 0.128, top + 0.097, 0.235, tr, tg, tb, 238, 7)
    draw_left('Purge Time', left + 0.010, top + 0.124, 0.205, 255, 170, 170, 220, 4)
    draw_left(format_clock(state.globalTimeMs), left + 0.128, top + 0.124, 0.235, gr, gg, gb, 238, 7)
    draw_left('Progress', left + 0.010, top + 0.156, 0.205, 255, 170, 170, 220, 4)
    draw_left(string.format('%d / %d', state.progressDone, state.progressTotal), left + 0.085, top + 0.156, 0.215, 255, 255, 255, 235, 4)
    draw_left('Eligible', left + 0.010, top + 0.183, 0.205, 255, 170, 170, 220, 4)
    draw_left(tostring(state.aliveTargets), left + 0.085, top + 0.183, 0.215, 255, 255, 255, 235, 4)
    draw_left('Excluded', left + 0.118, top + 0.183, 0.205, 255, 170, 170, 220, 4)
    draw_left(tostring(state.excludedCount), left + 0.190, top + 0.183, 0.215, 255, 255, 255, 235, 4)
    draw_rect(left + 0.010, top + 0.214, width - 0.020, 0.0035, red, 32, 32, 175)
    draw_left(state.status, left + 0.010, top + 0.222, 0.185, 245, 245, 245, 220, 4)
end

function P.RenderOverlay()
    local okIntro, introError = direct_call(P.DrawIntro)
    if not okIntro and minigames.LogError then minigames.LogError('[Purge UI] Intro draw failed: ' .. tostring(introError)) end
    local okHud, hudError = direct_call(P.DrawHud)
    if not okHud and minigames.LogError then minigames.LogError('[Purge UI] HUD draw failed: ' .. tostring(hudError)) end
end

function P.RenderUI()
    if not ImGui then return end

    if begin_child('The Purge Overview') then
        ImGui.Text('THE PURGE')
        ImGui.Text('A timed sequential bounty hunt with one life and one assigned target at a time.')
        ImGui.Text('This build includes the complete intro and HUD presentation prototype.')
        ImGui.Text('The target selection and kill-validation engine will connect to the prepared live-state bridge.')
        end_child()
    end

    if begin_child('Purge Presentation Preview') then
        if ImGui.Button('PREVIEW INTRO + HUD') then P.StartPreview() end
        if ImGui.SameLine then ImGui.SameLine() end
        if ImGui.Button('REPLAY INTRO') then P.StartIntro('Replay button') end
        if ImGui.SameLine then ImGui.SameLine() end
        if ImGui.Button('STOP PREVIEW') then P.StopPreview() end

        if ImGui.Button('CYCLE PHASE') then P.CyclePhase() end
        if ImGui.SameLine then ImGui.SameLine() end
        if ImGui.Button('ADVANCE TARGET') then P.AdvancePreview() end
        if ImGui.SameLine then ImGui.SameLine() end
        if ImGui.Button('TICK TIMERS DOWN') then P.TickDownPreview() end
        if ImGui.SameLine then ImGui.SameLine() end
        if ImGui.Button('RESET PREVIEW') then P.ResetPreview() end
        end_child()
    end

    if begin_child('Purge Live Status') then
        local state = P.GetState()
        ImGui.Text('Phase: ' .. tostring(state.phase))
        ImGui.Text('Target: ' .. tostring(state.targetName))
        ImGui.Text('Progress: ' .. tostring(state.progressDone) .. ' / ' .. tostring(state.progressTotal))
        ImGui.Text('Target Time: ' .. format_clock(state.targetTimeMs))
        ImGui.Text('Purge Time: ' .. format_clock(state.globalTimeMs))
        ImGui.Text('Eligible: ' .. tostring(state.aliveTargets) .. '    Excluded: ' .. tostring(state.excludedCount))
        ImGui.Text('Status: ' .. tostring(state.status))
        end_child()
    end
end

minigames.H.PURGE_UI_RENDERER_V175 = minigames.Hash and minigames.Hash('Purge_UI_Renderer_V175') or Utils.Joaat('Purge_UI_Renderer_V175')
local renderer = FeatureMgr.AddFeature(
    minigames.H.PURGE_UI_RENDERER_V175,
    'Internal Purge UI Renderer',
    eFeatureType.Toggle,
    'Internal lightweight renderer for The Purge intro and HUD.',
    function(feature)
        if feature:IsToggled() then P.RenderOverlay() end
        return true
    end
)
if renderer and renderer.RegisterCallbackTrigger and eCallbackTrigger and eCallbackTrigger.OnTick then
    renderer:RegisterCallbackTrigger(eCallbackTrigger.OnTick)
end
if renderer and renderer.SetDefaultValue then
    renderer:SetDefaultValue(true):Reset()
end
if renderer then
    local enabled = false
    direct_call(function() enabled = renderer:IsToggled() == true end)
    if not enabled then
        direct_call(function() renderer:Toggle(true) end)
        direct_call(function()
            if renderer:IsToggled() ~= true then renderer:Toggle() end
        end)
    end
end

-- replace the final root renderer so the purge is inside the minigames tab bar.
function minigames.RenderRoot()
    if minigames.RefreshConfig then direct_call(minigames.RefreshConfig) end

    local pushed = UI.PushTabStyle and UI.PushTabStyle() or 0
    if ImGui and ImGui.BeginTabBar and ImGui.BeginTabItem then
        local opened = false
        direct_call(function() opened = ImGui.BeginTabBar('MinigamesTabs_v175') end)
        if opened then
            if ImGui.BeginTabItem('Home') then UI.RenderHome() ImGui.EndTabItem() end
            if ImGui.BeginTabItem('The Purge') then P.RenderUI() ImGui.EndTabItem() end
            if ImGui.BeginTabItem('Games') then UI.RenderGames() ImGui.EndTabItem() end
            if ImGui.BeginTabItem('Players') then UI.RenderPlayers() ImGui.EndTabItem() end
            if ImGui.BeginTabItem('Config') then UI.RenderConfig() ImGui.EndTabItem() end
            if ImGui.BeginTabItem('Guide') then UI.RenderGuide() ImGui.EndTabItem() end
            if ImGui.BeginTabItem('Credits') then UI.RenderCredits() ImGui.EndTabItem() end
            ImGui.EndTabBar()
        else
            UI.RenderHome()
        end
    else
        P.RenderUI()
    end

    if UI.PopTabStyle then UI.PopTabStyle(pushed) end
    if UI.RenderSettingsResetPopupV169 then UI.RenderSettingsResetPopupV169() end
end

minigames.VERSION = script_version
minigames.BUILD_DATE = script_release_date
minigames.S.purgeUiThemeBuild = script_version
minigames.S.purgeUiIntegratedTabV175 = true
minigames.S.singleFileEmbeddedModuleCountV169 = 57
minigames.S.singleFileEmbeddedModuleCountV170 = 57
minigames.S.singleFileEmbeddedModuleCountV172 = 57
minigames.S.singleFileEmbeddedModuleCountV175 = 57

if minigames.LogInfo then
    minigames.LogInfo('[Purge UI] Loaded inside Minigames | tab=The Purge | renderer=ready | compatibility=Prime and non-Prime')
end
end

