    hintFlashOn = false,
    hintNextFlashAtMs = 0,
    hintNextAtMs = 0,
    hintEndsAtMs = 0,
    hintStatus = 'Idle',
    teamChatStatus = 'Idle'
}

local N = {
    GET_PED_SOURCE_OF_DEATH = 0x93C8B64DEB84728C,
    NETWORK_GET_PLAYER_INDEX_FROM_PED = 0x6C0E2E0125610278,
    IS_ENTITY_A_VEHICLE = 0x6AC7003FA6E5575E,
