    NETWORK_IS_SESSION_ACTIVE = 0xD83C2B94E7508980,
    GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH = 0x2C83A9DA6BFFC4F9,
