    -- purge target-only esp rendering
    GET_ENTITY_COORDS = 0x3FEF770D40960D5A,
    GET_ENTITY_HEALTH = 0xEEF059FAD016D209,
    GET_ENTITY_MAX_HEALTH = 0x15D757606D170C3C,
    GET_PED_BONE_COORDS = 0x17C07FC640E86B4E,
    GET_SCREEN_COORD_FROM_WORLD_COORD = 0x34E82F05DF2974F5,

    -- native atmosphere fallback. cherax feature state is still the authoritative
    -- value for startup backup/restore; these force the visible gta world state.
    SET_WEATHER_TYPE_NOW_PERSIST = 0xED712CA327900C8A,
    SET_OVERRIDE_WEATHER = 0xA43D5C6FE51ADBEF,
    CLEAR_WEATHER_TYPE_PERSIST = 0xCCC39339BEF76CF5,
    CLEAR_OVERRIDE_WEATHER = 0x338D2E3477711050,
    PRELOAD_CLOUD_HAT = 0x11B56FBBF7224868,
    LOAD_CLOUD_HAT = 0xFC4842A34657BFCB,
    UNLOAD_CLOUD_HAT = 0xA74802FB8D0B7814
}

local function now_ms()
    if minigames.Now then
        local ok, value = direct_call(minigames.Now)
        if ok and value then return tonumber(value) or 0 end
    end
    if Time and Time.GetEpocheMs then
        local ok, value = direct_call(Time.GetEpocheMs)
        if ok and value then return tonumber(value) or 0 end
    end
    return math.floor((os.clock() or 0) * 1000)
end

local function clamp_int(value, minimum, maximum)
    value = math.floor(tonumber(value or minimum) or minimum)
    if value < minimum then return minimum end
    if value > maximum then return maximum end
    return value
end

local function safe_yield(milliseconds)
    if Script and Script.Yield then
        direct_call(Script.Yield, milliseconds or 0)
    elseif SYSTEM and SYSTEM.WAIT then
        direct_call(SYSTEM.WAIT, milliseconds or 0)
    end
end

local function log_info(message)
    if minigames.LogInfo then minigames.LogInfo('[The Purge] ' .. tostring(message)) end
end

local function log_error(message)
    if minigames.LogError then minigames.LogError('[The Purge] ' .. tostring(message)) end
end

local function toast(message, duration)
    if minigames.Toast then minigames.Toast('The Purge', tostring(message), duration or 3500) end
end

local function begin_child(name)
    if ClickGUI and ClickGUI.BeginCustomChildWindow then
        local ok, opened = direct_call(ClickGUI.BeginCustomChildWindow, name)
        if ok then return opened == true end
    end
    return true
end

local function end_child()
    if ClickGUI and ClickGUI.EndCustomChildWindow then direct_call(ClickGUI.EndCustomChildWindow) end
end

local function text_wrapped(text)
    if ImGui and ImGui.TextWrapped then
        direct_call(ImGui.TextWrapped, tostring(text))
    elseif ImGui and ImGui.Text then
        direct_call(ImGui.Text, tostring(text))
    end
end

local function same_line()
    if ImGui and ImGui.SameLine then direct_call(ImGui.SameLine) end
end

local function slider_int(label, value, minimum, maximum)
    value = clamp_int(value, minimum, maximum)
    if not ImGui or not ImGui.SliderInt then return value, false end
    local ok, newValue, changed = direct_call(ImGui.SliderInt, label, value, minimum, maximum)
    if ok and type(newValue) == 'number' then
        newValue = clamp_int(newValue, minimum, maximum)
        return newValue, changed == true or newValue ~= value
    end
    return value, false
end

local function checkbox(label, value)
    if not ImGui or not ImGui.Checkbox then return value == true, false end
    local ok, newValue, changed = direct_call(ImGui.Checkbox, label, value == true)
    if ok and type(newValue) == 'boolean' then
        return newValue, changed == true or newValue ~= (value == true)
    end
    return value == true, false
end

local function format_clock(milliseconds)
    local total = math.max(0, math.floor((tonumber(milliseconds or 0) or 0) / 1000))
    local hours = math.floor(total / 3600)
    local minutes = math.floor((total % 3600) / 60)
    local seconds = total % 60
    if hours > 0 then return string.format('%02d:%02d:%02d', hours, minutes, seconds) end
    return string.format('%02d:%02d', minutes, seconds)
end

local function stats_dir()
    return tostring(minigames.ROOT or ((os.getenv('USERPROFILE') or '.') .. '\\Documents\\Cherax\\Lua\\Minigames')) .. '\\Purge'
end

local function stats_path()
    return stats_dir() .. '\\progress.ini'
end

function G.SaveProgress()
    if FileMgr and FileMgr.CreateDir then direct_call(FileMgr.CreateDir, stats_dir()) end
    local content = table.concat({
        'Unlocked=' .. tostring(G.stats.unlocked == true),
        'Attempts=' .. tostring(clamp_int(G.stats.attempts, 0, 999999)),
        'Wins=' .. tostring(clamp_int(G.stats.wins, 0, 999999)),
        'BestMs=' .. tostring(math.max(0, math.floor(tonumber(G.stats.bestMs or 0) or 0))),
        'LastResult=' .. tostring(G.stats.lastResult or 'None'):gsub('[\r\n=]', ' '),
        'WholeLobby=true',
        'SingleTargetMinutes=60',
        'MinutesPerTarget=' .. tostring(clamp_int(G.config.minutesPerTarget, 1, 5)),
        'TargetMinutes=' .. tostring(clamp_int(G.config.targetMinutes, 2, 10)),
        'PurgeHourMinutes=' .. tostring(clamp_int(G.config.purgeHourMinutes, 15, 60)),
        'UnavailableRotateSeconds=' .. tostring(clamp_int(G.config.unavailableRotateSeconds, 5, 30)),
        'RespawnGraceSeconds=' .. tostring(clamp_int(G.config.respawnGraceSeconds, 3, 10)),
        'TargetTimeoutPenaltySeconds=' .. tostring(clamp_int(G.config.targetTimeoutPenaltySeconds, 0, 120)),
        'PreparationSeconds=' .. tostring(clamp_int(G.config.preparationSeconds, 5, 30)),
        'AutoStartPurgeHour=' .. tostring(G.config.autoStartPurgeHour ~= false),
        'TeamMode=' .. tostring(G.config.teamMode == true),
        'HardcoreMode=' .. tostring(G.config.hardcoreMode == true),
        'ApplyAtmospherePreset=' .. tostring(G.config.applyAtmospherePreset ~= false),
        'DisablePlayerESP=' .. tostring(G.config.disablePlayerESP ~= false),
        'HardcoreHint=' .. tostring(G.config.hardcoreHint ~= false),
        'HintIntervalSeconds=300',
        'HintDurationSeconds=15',
        'TeamChatAnnouncements=' .. tostring(G.config.teamChatAnnouncements ~= false),
        'CityLimitRadius=5000'
    }, '\n')

    if FileMgr and FileMgr.WriteFileContent then
        local ok = direct_call(FileMgr.WriteFileContent, stats_path(), content, false)
        if not ok then direct_call(FileMgr.WriteFileContent, stats_path(), content) end
    end
end

function G.LoadProgress()
    if not FileMgr or not FileMgr.DoesFileExist or not FileMgr.ReadFileContent then return end
    local exists = false
    direct_call(function() exists = FileMgr.DoesFileExist(stats_path()) == true end)
    if not exists then return end

    local raw = nil
    direct_call(function() raw = FileMgr.ReadFileContent(stats_path()) end)
    if type(raw) ~= 'string' then return end

    local values = {}
    for line in raw:gmatch('[^\r\n]+') do
        local key, value = line:match('^([^=]+)=(.*)$')
        if key then values[key] = value end
    end

    G.stats.unlocked = values.Unlocked == 'true'
    G.stats.attempts = tonumber(values.Attempts) or G.stats.attempts or 0
    G.stats.wins = tonumber(values.Wins) or G.stats.wins or 0
    G.stats.bestMs = tonumber(values.BestMs) or G.stats.bestMs or 0
    G.stats.lastResult = values.LastResult or G.stats.lastResult or 'None'
    G.config.wholeLobby = true -- v0.198: phase 2 is always the city sweep
    G.config.singleTargetMinutes = 60
    G.config.minutesPerTarget = clamp_int(values.MinutesPerTarget or G.config.minutesPerTarget, 1, 5)
    G.config.targetMinutes = clamp_int(values.TargetMinutes or G.config.targetMinutes, 5, 10)
    G.config.purgeHourMinutes = clamp_int(values.PurgeHourMinutes or G.config.purgeHourMinutes, 15, 60)
    G.config.unavailableRotateSeconds = clamp_int(values.UnavailableRotateSeconds or G.config.unavailableRotateSeconds, 5, 30)
    G.config.respawnGraceSeconds = clamp_int(values.RespawnGraceSeconds or G.config.respawnGraceSeconds, 3, 10)
    G.config.targetTimeoutPenaltySeconds = clamp_int(values.TargetTimeoutPenaltySeconds or G.config.targetTimeoutPenaltySeconds, 0, 120)
    G.config.preparationSeconds = clamp_int(values.PreparationSeconds or G.config.preparationSeconds, 5, 30)
    if values.AutoStartPurgeHour ~= nil then G.config.autoStartPurgeHour = values.AutoStartPurgeHour == 'true' end
    if values.TeamMode ~= nil then G.config.teamMode = values.TeamMode == 'true' end
    -- v0.187 migration: hardcore is no longer user-selectable for the base purge hunt.
    G.config.hardcoreMode = true
    if values.ApplyAtmospherePreset ~= nil then G.config.applyAtmospherePreset = values.ApplyAtmospherePreset == 'true' end
    if values.DisablePlayerESP ~= nil then G.config.disablePlayerESP = values.DisablePlayerESP == 'true' end
    if values.HardcoreHint ~= nil then G.config.hardcoreHint = values.HardcoreHint == 'true' end
    -- v0.185 migration: target hints are fixed at every 5 minutes for 15 seconds.
    G.config.hintIntervalSeconds = 300
    G.config.hintDurationSeconds = 15
    if values.TeamChatAnnouncements ~= nil then G.config.teamChatAnnouncements = values.TeamChatAnnouncements == 'true' end
    G.config.cityLimitRadius = 5000
end

local function get_player_object(playerId)
    if Players and Players.GetById then
        local ok, object = direct_call(Players.GetById, playerId)
        if ok then return object end
    end
    return nil
end

local function get_cped(playerId)
    if Players and Players.GetCPed then
        local ok, ped = direct_call(Players.GetCPed, playerId)
        if ok and ped then return ped end
    end

    local object = get_player_object(playerId)
    if object then
        local ok, ped = direct_call(function()
            if object.PlayerInfo then return object.PlayerInfo.PlayerPed end
            return nil
        end)
        if ok and ped then return ped end
    end

    return nil
end

local function get_identity(playerId)
    playerId = clamp_int(playerId, 0, 31)
    local name = minigames.GetPlayerName and minigames.GetPlayerName(playerId) or ('Player ' .. tostring(playerId))
    local cxnId = nil
    local object = get_player_object(playerId)
    if object then direct_call(function() cxnId = tonumber(object.CxnId) end) end
    local token = cxnId and ('cxn:' .. tostring(cxnId)) or ('name:' .. tostring(name))
    return tostring(playerId) .. '|' .. token, tostring(name), cxnId
end

local function identity_matches(record)
    if not record or not minigames.IsPlayerActive or not minigames.IsPlayerActive(record.id) then return false end
    local identity = get_identity(record.id)
    return identity == record.identity
end

local function is_invincible(playerId)
    local cped = get_cped(playerId)
    if cped and cped.IsInvincible then
        local ok, value = direct_call(function() return cped:IsInvincible() end)
        if ok and value == true then return true end
    end
    return false
end

local function player_tags(playerId)
    if Players and Players.GetTags then
        local ok, tags = direct_call(Players.GetTags, playerId)
        if ok and tags then return tostring(tags) end
    end
    return ''
end

local function is_interior(playerId)
    if player_tags(playerId):find('%[I%]') then return true end
    local ped = minigames.GetPlayerPed and minigames.GetPlayerPed(playerId) or 0
    if not ped or ped == 0 then return false end
    local ok, interior = direct_call(Natives.InvokeInt, N.GET_INTERIOR_FROM_ENTITY, ped)
    return ok and tonumber(interior or 0) ~= 0
end

local function is_passive(playerId)
    local state = G.sync[playerId]
    return state and state.passive == true or false
end

-- v0.195 purge city boundary. the hunt is intentionally los santos-only.
-- the radial limit catches far-away targets while the simple north/south/east/west
-- caps prevent sandy shores / blaine county targets from slipping into the pool.
local PURGE_CITY = {
    centerX = 0.0,
    centerY = -1000.0,
    radius = 5000.0,
    minX = -3200.0,
    maxX = 3200.0,
    minY = -4000.0,
    maxY = 1800.0
}

local function purge_player_xyz(playerId)
    local ped = minigames.GetPlayerPed and minigames.GetPlayerPed(playerId) or 0
    if not ped or ped == 0 then return nil end

    local function normalize(a, b, c)
        if type(a) == 'number' and type(b) == 'number' and type(c) == 'number' then
            return tonumber(a), tonumber(b), tonumber(c)
        end
        if a ~= nil then
            local x, y, z = nil, nil, nil
            direct_call(function() x = a.x or a.X end)
            direct_call(function() y = a.y or a.Y end)
            direct_call(function() z = a.z or a.Z end)
            if x ~= nil and y ~= nil and z ~= nil then return tonumber(x), tonumber(y), tonumber(z) end
        end
        return nil
    end

    if Natives and Natives.InvokeV3 then
        local ok, a, b, c = direct_call(function() return Natives.InvokeV3(N.GET_ENTITY_COORDS, ped, true) end)
        if ok then
            local x, y, z = normalize(a, b, c)
            if x ~= nil then return { x=x, y=y, z=z } end
        end
    end

    if ENTITY and ENTITY.GET_ENTITY_COORDS then
        local ok, a, b, c = direct_call(function() return ENTITY.GET_ENTITY_COORDS(ped, true) end)
        if ok then
            local x, y, z = normalize(a, b, c)
            if x ~= nil then return { x=x, y=y, z=z } end
        end
    end
    return nil
end

function G.IsWithinCityLimits(playerId)
    local pos = purge_player_xyz(playerId)
    if not pos then return nil, 'Position unavailable' end
    local radius = tonumber(G.config.cityLimitRadius or 5000) or 5000
    local dx = pos.x - PURGE_CITY.centerX
    local dy = pos.y - PURGE_CITY.centerY
    local distance = math.sqrt(dx * dx + dy * dy)
    local inside = distance <= radius
        and pos.x >= PURGE_CITY.minX and pos.x <= PURGE_CITY.maxX
        and pos.y >= PURGE_CITY.minY and pos.y <= PURGE_CITY.maxY
    return inside, inside and ('Inside Los Santos | ' .. tostring(math.floor(distance)) .. 'm') or ('Outside Los Santos | ' .. tostring(math.floor(distance)) .. 'm')
end

local function get_player_team(playerId)
    playerId = clamp_int(playerId, 0, 31)
    local nativeTeam = nil
    if Natives and Natives.InvokeInt then
        local ok, value = direct_call(Natives.InvokeInt, N.GET_PLAYER_TEAM, playerId)
        if ok and type(value) == 'number' then nativeTeam = math.floor(value) end
    end

    local state = G.sync[playerId]
    local syncedTeam = state and tonumber(state.playerTeam) or nil
    if syncedTeam ~= nil then syncedTeam = math.floor(syncedTeam) end

    -- get_player_team normally returns -1 outside a team. prefer a valid native
    -- value, but retain the synced cplayergamestatedatanode value as fallback.
    if nativeTeam ~= nil and nativeTeam >= 0 then return nativeTeam end
    if syncedTeam ~= nil then return syncedTeam end
    return nativeTeam or -1
end

function G.GetLocalTeamInfo(useRunMode)
    local enabled = false
    if useRunMode == true then
        enabled = G.run and G.run.teamMode == true or false
    else
        enabled = G.config.teamMode == true
    end
    local localId = minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or 0
    local localTeam = get_player_team(localId)
    local members = {}

    if enabled and localTeam >= 0 then
        for _, playerId in ipairs(minigames.S.activePlayers or {}) do
            if minigames.IsPlayerActive and minigames.IsPlayerActive(playerId) and get_player_team(playerId) == localTeam then
                members[#members + 1] = playerId
            end
        end
    end

    return {
        enabled = enabled,
        localId = localId,
        team = localTeam,
        members = members,
        available = enabled and localTeam >= 0 and #members > 0
    }
end

function G.IsPurgeTeamMember(playerId, useRunMode)
    local info = G.GetLocalTeamInfo(useRunMode == true)
    if not info.enabled or info.team < 0 then return false end
    return get_player_team(playerId) == info.team
end

local function is_sub_session(playerId)
    local state = G.sync[playerId]
    if not state then return false end
    if state.inCutscene == true then return true end

    -- compare the remote player's tutorial/sub-session identity against the
    -- local player instead of rejecting every non-zero tutorial value. some
    -- normal freemode sessions expose non-zero values, which caused v0.176 to
    -- incorrectly report that the local player was outside main freemode.
    local localId = minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or 0
    if playerId == localId then return false end
    local localState = G.sync[localId]

    local remoteIndex = tonumber(state.tutorialIndex or 0) or 0
    local remoteInstance = tonumber(state.tutorialInstanceId or 0) or 0
    local localIndex = localState and (tonumber(localState.tutorialIndex or 0) or 0) or 0
    local localInstance = localState and (tonumber(localState.tutorialInstanceId or 0) or 0) or 0

    if remoteInstance ~= localInstance and (remoteInstance > 0 or localInstance > 0) then return true end
    if remoteIndex ~= localIndex and (remoteIndex > 0 or localIndex > 0) then return true end

    local remoteState = tonumber(state.playerState or 0) or 0
    local ownState = localState and (tonumber(localState.playerState or 0) or 0) or 0
    if remoteState == 6 and ownState ~= 6 then return true end
    return false
end

local function check_main_freemode()
    local sessionKnown, sessionActive = false, true
    local gameKnown, gameActive = false, true
    local threadKnown, threadCount = false, 1

    if Natives and Natives.InvokeBool then
        local ok, value = direct_call(Natives.InvokeBool, N.NETWORK_IS_SESSION_ACTIVE)
        if ok then sessionKnown, sessionActive = true, value == true end
        ok, value = direct_call(Natives.InvokeBool, N.NETWORK_IS_GAME_IN_PROGRESS)
        if ok then gameKnown, gameActive = true, value == true end
    end

    if Natives and Natives.InvokeInt and Utils and Utils.Joaat then
        local ok, value = direct_call(Natives.InvokeInt, N.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH, Utils.Joaat('freemode'))
        if ok and type(value) == 'number' then threadKnown, threadCount = true, value end
    end

    if sessionKnown and not sessionActive then return false, 'GTA Online session is not active yet.' end
    if gameKnown and not gameActive then return false, 'GTA Online is still transitioning.' end

    -- a zero freemode-thread count can be reported briefly on some cherax/gta
    -- branches even after the public session is usable. treat it as diagnostic
    -- only once the network session and game are both active, preventing the
    -- false rejection reported in v0.176.
    if threadKnown and threadCount <= 0 then
        G.run.lastFreemodeThreadDiagnostic = 'freemode thread count reported 0 while network session was active'
    end
    return true, 'Main freemode ready'
end

function G.GetEligibility(playerId, requireAlive, excludePurgeTeam)
    playerId = clamp_int(playerId, 0, 31)
    if minigames.IsSelf and minigames.IsSelf(playerId) then return false, 'Self' end
    if not minigames.IsPlayerActive or not minigames.IsPlayerActive(playerId) then return false, 'Left session' end

    if excludePurgeTeam == true and G.IsPurgeTeamMember(playerId, G.run and G.run.active == true) then
        return false, 'Purge team member'
    end

    local ped = minigames.GetPlayerPed and minigames.GetPlayerPed(playerId) or 0
    if not ped or ped == 0 then return false, 'No player ped' end
    if minigames.EntityExists and not minigames.EntityExists(ped) then return false, 'Player ped missing' end

    if requireAlive ~= false and minigames.IsPlayerDead then
        local dead = select(1, minigames.IsPlayerDead(playerId))
        if dead then return false, 'Respawning' end
    end

    if is_interior(playerId) then return false, 'Inside an interior' end
    if is_passive(playerId) then return false, 'Passive mode' end
    local inCity = G.IsWithinCityLimits(playerId)
    if inCity == false then return false, 'Outside Los Santos city limits' end
    if is_sub_session(playerId) then return false, 'Sub-session or activity' end
    if is_invincible(playerId) then return false, 'God mode or invincible' end

    return true, 'Eligible'
end

function G.CheckLocalReady()
    local localId = minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or 0
    local freemodeReady, freemodeReason = check_main_freemode()
    if not freemodeReady then return false, freemodeReason end
    if minigames.IsPlayerDead and select(1, minigames.IsPlayerDead(localId)) then return false, 'Respawn before starting The Purge.' end
    if is_interior(localId) then return false, 'Leave the interior before starting The Purge.' end
    if is_passive(localId) then return false, 'Disable passive mode before starting The Purge.' end
    if is_invincible(localId) then return false, 'Disable god mode before starting The Purge.' end
    if minigames.S.wargamesSystemsActive == true or minigames.S.wargamesActive == true or minigames.S.warGamesActive == true then
        return false, 'Disable WarGames before starting The Purge.'
    end
    if minigames.S.autoBountyRunning == true or minigames.S.autoBountyEnabled == true then
        return false, 'Disable the separate bounty maintenance mode before starting The Purge.'
    end
    return true, 'Ready'
end

local function make_record(playerId)
    local identity, name, cxnId = get_identity(playerId)
    return { id = playerId, identity = identity, name = name, cxnId = cxnId, wasDead = false, needsBounty = false, openingBountyApplied = false }
end

local function shuffle(list)
    for i = #list, 2, -1 do
        local j = math.random(1, i)
        list[i], list[j] = list[j], list[i]
    end
end

function G.GetSessionEligibilitySummary()
    local now = now_ms()
    if G.eligibilitySummaryCache and now - (G.eligibilitySummaryCacheAtMs or 0) < 1000 then
        return G.eligibilitySummaryCache
    end

    local summary = { eligible = 0, excluded = 0, reasons = {} }
    local players = minigames.S.activePlayers or {}
    for _, playerId in ipairs(players) do
        if not (minigames.IsSelf and minigames.IsSelf(playerId)) then
            local ok, reason = G.GetEligibility(playerId, true, G.config.teamMode == true)
            if ok then
                summary.eligible = summary.eligible + 1
            else
                summary.excluded = summary.excluded + 1
                summary.reasons[reason] = (summary.reasons[reason] or 0) + 1
            end
        end
    end
    G.eligibilitySummaryCache = summary
    G.eligibilitySummaryCacheAtMs = now
    return summary
end

function G.BuildRoster()
    if minigames.RefreshPlayers then direct_call(minigames.RefreshPlayers) end
    local roster, excluded = {}, {}
    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        if not (minigames.IsSelf and minigames.IsSelf(playerId)) then
            local ok, reason = G.GetEligibility(playerId, true, G.config.teamMode == true)
            if ok then
                roster[#roster + 1] = make_record(playerId)
            else
                excluded[#excluded + 1] = { id = playerId, name = minigames.GetPlayerName(playerId), reason = reason }
            end
        end
    end
    shuffle(roster)
    return roster, excluded
end

local function select_purge_scope(fullRoster)
    fullRoster = fullRoster or {}
    if G.config.wholeLobby == true then
        return fullRoster, {}
    end

    -- single target is the default. only the chosen player is active and bounty
    -- marked. other eligible players remain unmarked standbys so a passive/left
    -- target can be forgotten without forcing the whole run to fail.
    local selected, standby = {}, {}
    if #fullRoster > 0 then
        selected[1] = table.remove(fullRoster, 1)
        for _, record in ipairs(fullRoster) do standby[#standby + 1] = record end
    end
    return selected, standby
end

local function refill_single_target_from_standby(reason)
    local run = G.run
    if run.wholeLobby == true or (tonumber(run.done or 0) or 0) > 0 then return false end
    local standby = run.singleTargetStandby or {}
    while #standby > 0 do
        local record = table.remove(standby, 1)
        if record and identity_matches(record) then
            local eligible, why = G.GetEligibility(record.id, true, run.teamMode == true)
            if eligible then
                run.queue[#run.queue + 1] = record
                run.roster = run.queue
                run.total = 1
                run.initialTotal = 1
                run.currentEligible = 1
                run.targetName = 'Selecting replacement target'
                log_info('Single-target replacement selected | name=' .. tostring(record.name) .. ' | reason=' .. tostring(reason))
                return true
            else
                log_info('Single-target standby skipped | name=' .. tostring(record.name) .. ' | reason=' .. tostring(why))
            end
        end
    end
    return false
end

local function set_intro(title, subtitle, line2, line3, reason)
    minigames.S.purgeIntroTitle = title or 'THE PURGE'
    minigames.S.purgeIntroSubtitle = subtitle or 'Two-stage Los Santos hunt'
    minigames.S.purgeIntroLine2 = line2 or 'Stage 1: one target. Stage 2: clear the city roster.'
    minigames.S.purgeIntroLine3 = line3 or 'One active target. One bounty at a time.'
    if P and P.StartIntro then P.StartIntro(reason or title or 'The Purge') end
end

local function reset_intro_copy()
    minigames.S.purgeIntroTitle = 'THE PURGE'
    minigames.S.purgeIntroSubtitle = 'Two-stage Los Santos hunt'
    minigames.S.purgeIntroLine2 = 'Stage 1: one target. Stage 2: clear the city roster.'
    minigames.S.purgeIntroLine3 = 'One active target. One bounty at a time.'
end

local function clear_damage_history(playerId)
    local ped = minigames.GetPlayerPed and minigames.GetPlayerPed(playerId) or 0
    if ped and ped ~= 0 then direct_call(Natives.InvokeVoid, N.CLEAR_ENTITY_LAST_DAMAGE_ENTITY, ped) end
end

local function player_vehicle(playerId)
    local ped = minigames.GetPlayerPed and minigames.GetPlayerPed(playerId) or 0
    if not ped or ped == 0 then return 0 end
    local ok, vehicle = direct_call(Natives.InvokeInt, N.GET_VEHICLE_PED_IS_IN, ped, false)
    if ok then return tonumber(vehicle) or 0 end
    return 0
end

local function purge_killers()
    local localId = minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or 0
    local killers = { localId }
    local seen = { [localId] = true }

    if G.run and G.run.teamMode == true then
        local info = G.GetLocalTeamInfo(true)
        if info.available then
            for _, playerId in ipairs(info.members or {}) do
                if not seen[playerId] and minigames.IsPlayerActive and minigames.IsPlayerActive(playerId) then
                    seen[playerId] = true
                    killers[#killers + 1] = playerId
                end
            end
        end
    end

    return killers
end

local function is_allowed_killer(playerId)
    for _, allowedId in ipairs(purge_killers()) do
        if allowedId == playerId then return true end
    end
    return false
end

local function player_from_ped(ped)
    if not ped or ped == 0 then return -1 end
    local playerId = -1
    direct_call(function() playerId = Natives.InvokeInt(N.NETWORK_GET_PLAYER_INDEX_FROM_PED, ped) or -1 end)
    return tonumber(playerId) or -1
end

function G.WasKilledByPurgeSide(playerId)
    local targetPed = minigames.GetPlayerPed and minigames.GetPlayerPed(playerId) or 0
    if targetPed == 0 then return false, 'ped_missing', -1 end

    local source = 0
    direct_call(function() source = Natives.InvokeInt(N.GET_PED_SOURCE_OF_DEATH, targetPed) or 0 end)

    if source ~= 0 then
        for _, killerId in ipairs(purge_killers()) do
            local killerPed = minigames.GetPlayerPed and minigames.GetPlayerPed(killerId) or 0
            if killerPed ~= 0 and source == killerPed then
                return true, killerId == (minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or 0) and 'source_local_ped' or 'source_team_ped', killerId
            end
            local vehicle = player_vehicle(killerId)
            if vehicle ~= 0 and source == vehicle then
                return true, killerId == (minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or 0) and 'source_local_vehicle' or 'source_team_vehicle', killerId
            end
        end

        local okVehicle, sourceIsVehicle = direct_call(Natives.InvokeBool, N.IS_ENTITY_A_VEHICLE, source)
        if okVehicle and sourceIsVehicle == true then
            local driver = 0
            direct_call(function() driver = Natives.InvokeInt(N.GET_PED_IN_VEHICLE_SEAT, source, -1, false) or 0 end)
            local driverId = player_from_ped(driver)
            if is_allowed_killer(driverId) then return true, 'source_vehicle_driver', driverId end
        end

        local sourcePlayer = player_from_ped(source)
        if is_allowed_killer(sourcePlayer) then return true, 'source_network_player', sourcePlayer end
    end

    -- damage-history fallback supports delayed explosions and some vehicle kills
    -- that gta does not expose through get_ped_source_of_death. as with the
    -- original local-only implementation, the current target must still die in
    -- the frame where this check runs.
    for _, killerId in ipairs(purge_killers()) do
        local killerPed = minigames.GetPlayerPed and minigames.GetPlayerPed(killerId) or 0
        if killerPed ~= 0 then
            local damagedByPed = false
            direct_call(function()
                damagedByPed = Natives.InvokeBool(N.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY, targetPed, killerPed, true) == true
            end)
            if damagedByPed then return true, 'last_damage_team_ped', killerId end
        end

        local vehicle = player_vehicle(killerId)
        if vehicle ~= 0 then
            local damagedByVehicle = false
            direct_call(function()
                damagedByVehicle = Natives.InvokeBool(N.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY, targetPed, vehicle, true) == true
            end)
            if damagedByVehicle then return true, 'last_damage_team_vehicle', killerId end
        end
    end

    return false, 'not_purge_side', -1
end

-- compatibility name retained for older purge ui/testing hooks.
function G.WasKilledByLocal(playerId)
    return G.WasKilledByPurgeSide(playerId)
end

local function apply_bounty(playerId, reason)
    if not minigames.ApplyBuiltInBounty then return false, 'bounty_function_missing' end
    local ok, result, status = direct_call(minigames.ApplyBuiltInBounty, playerId, true)
    if not ok then
        log_error('Bounty call failed | player=' .. tostring(playerId) .. ' | reason=' .. tostring(reason) .. ' | err=' .. tostring(result))
        return false, tostring(result)
    end
    if result == true then
        log_info('Bounty applied | player=' .. tostring(playerId) .. ' | name=' .. tostring(minigames.GetPlayerName(playerId)) .. ' | reason=' .. tostring(reason))
        return true, tostring(status or 'ok')
    end
    return false, tostring(status or result or 'failed')
end

local function apply_bounty_with_retries(playerId, serial, reason, attempts)
    attempts = clamp_int(attempts or 3, 1, 6)
    for attempt = 1, attempts do
        if G.run.serial ~= serial then return false, 'cancelled' end
        if not minigames.IsPlayerActive or not minigames.IsPlayerActive(playerId) then return false, 'inactive' end
        local ok, status = apply_bounty(playerId, reason)
        if ok then return true, status end
        if attempt < attempts then safe_yield(450) end
    end
    return false, 'retry_exhausted'
end

local function queue_job(worker)
    if Script and Script.QueueJob then
        local ok, err = direct_call(Script.QueueJob, worker)
        if ok then return true end
        log_error('QueueJob failed: ' .. tostring(err))
    end
    local ok, err = direct_call(worker)
    if not ok then log_error('Direct worker failed: ' .. tostring(err)) end
    return ok
end

-- cherax purge presentation preset
-- the preset is applied outside clickgui render callbacks and restores only the
-- values minigames changed. team/friend esp options are never modified.
local PURGE_FEATURE_SPECS = {
    -- exact built-in cherax hashes are used first so prime and non-prime resolve
    -- the world controls instead of another feature with a similar translated name.
    hour = { hash = 1755348425, names = { 'Hour' }, kind = 'int', min = 0, max = 23, scope = 'global' },
    minute = { hash = 2419387588, names = { 'Minute' }, kind = 'int', min = 0, max = 59, scope = 'global' },
    second = { hash = 772832074, names = { 'Second' }, kind = 'int', min = 0, max = 59, scope = 'global' },
    timeScale = { hash = 2383216635, names = { 'Time Scale' }, kind = 'float', scope = 'global' },
    freezeTime = { hash = 2660507417, names = { 'Freeze Time' }, kind = 'toggle', scope = 'global' },
    smoothWeather = { hash = 163139833, names = { 'Smooth Weather Transition' }, kind = 'toggle', scope = 'global' },
    weather = { hash = 4095455439, names = { 'Weather' }, kind = 'list', option = 'Halloween Rain', scope = 'global' },
    clouds = { hash = 2858217378, names = { 'Clouds' }, kind = 'list', option = 'Stormy 01', scope = 'global' },
    thunder = { hash = 1617820265, names = { 'Thunder Lightning' }, kind = 'toggle', scope = 'global' },
    fog = { hash = 2453007500, names = { 'Fog' }, kind = 'float', scope = 'global' },
    disableLights = { hash = 818586389, names = { 'Disable Lights' }, kind = 'toggle', scope = 'global' },
    -- misc > rendering. name lookup is intentionally used here because this built-in
    -- feature does not have a confirmed stable hash across all cherax editions.
    damageEffect = { names = { 'Enable Damage Effect', 'Enable Damage effect' }, kind = 'toggle', scope = 'global' },

    -- exact cherax hashes avoid matching unrelated features with common names.
    disableMinimap = { hash = 3154323183, names = { 'Disable Minimap' }, kind = 'toggle', scope = 'global' },
    enableESP = { hash = 1523980401, names = { 'Enable ESP' }, kind = 'toggle', scope = 'global' },
    espOnDead = { hash = 4019378386, names = { 'ESP On Dead', 'Enable ESP on Dead', 'Enable ESP On Dead' }, kind = 'toggle', scope = 'global' },
    espDistance = { hash = 1126125627, names = { 'Distance' }, kind = 'numeric', scope = 'global' },
    boxOutline = { hash = 18080799, names = { 'Box Outline' }, kind = 'list', option = { 'None', 'Off' }, scope = 'global' },
    drawBox = { hash = 4166015101, names = { 'Draw Box' }, kind = 'list', option = { '2D', '2D Box', 'Box 2D' }, scope = 'global' },
    drawBones = { hash = 2647447137, names = { 'Draw Bones' }, kind = 'list', option = { 'Full', 'Full Body' }, scope = 'global' },
    healthBar = { hash = 4147317593, names = { 'Health Bar' }, kind = 'list', option = { 'Health Based', 'Health-Based' }, scope = 'global' },

    -- cherax may expose this as an indexed player feature using the same translated name.
    playerEnableESP = { hash = 1523980401, names = { 'Enable ESP' }, kind = 'toggle', scope = 'player' }
}

local function feature_name(feature)
    if not feature then return '' end
    local name = ''
    direct_call(function()
        if feature.GetName then name = feature:GetName(false) else name = feature.Name or '' end
    end)
    return tostring(name or '')
end

local function feature_list(feature)
    local list = nil
    if feature and feature.GetList then direct_call(function() list = feature:GetList() end) end
    return type(list) == 'table' and list or nil
end

local function normalize_option(value)
    return tostring(value or ''):lower():gsub('[^%w]+', '')
end

local function list_option_index(feature, wanted)
    local list = feature_list(feature)
    if not list then return nil end
    local wantedList = type(wanted) == 'table' and wanted or { wanted }

    for _, candidate in ipairs(wantedList) do
        local normalized = normalize_option(candidate)
        for index, value in ipairs(list) do
            if normalize_option(value) == normalized then return index - 1 end
        end
    end

    -- translation wording can differ slightly between prime and non-prime.
    for _, candidate in ipairs(wantedList) do
        local normalized = normalize_option(candidate)
        for index, value in ipairs(list) do
            local current = normalize_option(value)
            if normalized ~= '' and (current:find(normalized, 1, true) or normalized:find(current, 1, true)) then
                return index - 1
            end
        end
    end
    return nil
end

local function feature_is_player(feature)
    if not feature then return false end
    local value = false
    direct_call(function() if feature.IsPlayerFeature then value = feature:IsPlayerFeature() == true end end)
    return value
end

local function feature_player_index(feature)
    if not feature then return -1 end
    local value = -1
    direct_call(function()
        if feature.GetPlayerIndex then value = tonumber(feature:GetPlayerIndex()) or -1
        elseif feature.GetArrayIndex then value = tonumber(feature:GetArrayIndex()) or -1 end
    end)
    return math.floor(value)
end

local function feature_is_toggle_safe(feature)
    if not feature then return false end

    -- cherax feature userdata exposes many methods on every feature type. calling
    -- istoggled/toggle on a numeric slider can throw outside lua's direct call boundary,
    -- especially on prime. istogglefeature is the authoritative type gate.
    if feature.IsToggleFeature then
        local ok, value = direct_call(function() return feature:IsToggleFeature() end)
        if ok then return value == true end
        return false
    end

    -- conservative compatibility fallback for older apis without istogglefeature.
    -- reject anything that advertises a numeric/list/string value interface.
    if feature.GetIntValue or feature.GetFloatValue or feature.GetListIndex or feature.GetStringValue then
        return false
    end
    return feature.GetBoolValue ~= nil or feature.IsToggled ~= nil
end

local function feature_matches(feature, spec)
    if not feature or not spec then return false end
    if spec.kind == 'list' then return list_option_index(feature, spec.option) ~= nil end
    if spec.kind == 'toggle' then return feature_is_toggle_safe(feature) end
    if spec.kind == 'int' then
        if not feature.GetIntValue and not feature.SetIntValue then return false end
        local minimum, maximum = nil, nil
        direct_call(function() if feature.GetIntMinValue then minimum = feature:GetIntMinValue() end end)
        direct_call(function() if feature.GetIntMaxValue then maximum = feature:GetIntMaxValue() end end)
        if minimum ~= nil and maximum ~= nil and spec.min ~= nil and spec.max ~= nil then
            return tonumber(minimum) <= spec.min and tonumber(maximum) >= spec.max
        end
        return true
    end
    if spec.kind == 'float' then return feature.GetFloatValue ~= nil or feature.SetFloatValue ~= nil end
    if spec.kind == 'numeric' then return feature.GetIntValue ~= nil or feature.GetFloatValue ~= nil end
    return true
end

local function feature_scope_matches(feature, scope, playerId)
    if scope == 'global' then return not feature_is_player(feature) end
    if scope == 'player' then
        return feature_is_player(feature) and feature_player_index(feature) == clamp_int(playerId or -1, -1, 31)
    end
    return true
end

local function find_cherax_feature(spec, playerId)
    if not FeatureMgr or not spec then return nil end

    -- prefer the built-in hash. indexed lookup is required for player features.
    if spec.hash and FeatureMgr.GetFeature then
        local feature = nil
        direct_call(function()
            if spec.scope == 'player' then feature = FeatureMgr.GetFeature(spec.hash, playerId)
            else feature = FeatureMgr.GetFeature(spec.hash) end
        end)
        if feature and feature_scope_matches(feature, spec.scope, playerId) and feature_matches(feature, spec) then return feature end
    end

    if FeatureMgr.GetFeatureByName then
        for _, wanted in ipairs(spec.names or {}) do
            local feature = nil
            direct_call(function()
                if spec.scope == 'player' then feature = FeatureMgr.GetFeatureByName(wanted, playerId)
                else feature = FeatureMgr.GetFeatureByName(wanted) end
            end)
            if feature and feature_scope_matches(feature, spec.scope, playerId) and feature_matches(feature, spec) then return feature end
        end
    end

    -- indexed player features must resolve through the native hash/name apis.
    -- avoid scanning the complete cherax feature tree once per player slot,
    -- which previously delayed the tab and consumed the startup intro.
    if spec.scope == 'player' then return nil end

    -- final exact-name scan for compatibility with branches where hash/index
    -- lookup is not exposed to lua.
    if FeatureMgr.GetAllFeatures then
        local all = nil
        direct_call(function() all = FeatureMgr.GetAllFeatures() end)
        if type(all) == 'table' then
            for _, feature in pairs(all) do
                if feature_scope_matches(feature, spec.scope, playerId) then
                    local name = feature_name(feature)
                    for _, wanted in ipairs(spec.names or {}) do
                        if name == wanted and feature_matches(feature, spec) then return feature end
                    end
                end
            end
        end
    end
    return nil
end

local function find_player_esp_feature(playerId)
    return find_cherax_feature(PURGE_FEATURE_SPECS.playerEnableESP, playerId)
end

-- direct indexed featuremgr access is more reliable for built-in player esp than
-- requiring cherax to return an indexed feature object. this is the primary v0.195 path.
local read_feature_state
local write_feature_state

local function read_indexed_player_esp(playerId)
    playerId = clamp_int(playerId, 0, 31)
    local hash = PURGE_FEATURE_SPECS.playerEnableESP.hash
    if FeatureMgr and FeatureMgr.IsFeatureToggled and hash then
        local ok, value = direct_call(FeatureMgr.IsFeatureToggled, hash, playerId)
        if ok and type(value) == 'boolean' then return value end
    end
    local feature = find_player_esp_feature(playerId)
    if feature then return read_feature_state and read_feature_state(feature, 'toggle') or nil end
    return nil
end

local function write_indexed_player_esp(playerId, desired)
    playerId = clamp_int(playerId, 0, 31)
    desired = desired == true
    local hash = PURGE_FEATURE_SPECS.playerEnableESP.hash
    local current = nil
    if FeatureMgr and FeatureMgr.IsFeatureToggled and hash then
        local ok, value = direct_call(FeatureMgr.IsFeatureToggled, hash, playerId)
        if ok and type(value) == 'boolean' then current = value end
    end
    if current == desired then return true end

    if FeatureMgr and FeatureMgr.ToggleFeature and hash and current ~= nil then
        local ok = direct_call(FeatureMgr.ToggleFeature, hash, playerId)
        if ok and FeatureMgr.IsFeatureToggled then
            local okRead, value = direct_call(FeatureMgr.IsFeatureToggled, hash, playerId)
            if okRead and value == desired then return true end
        end
    end

    local feature = find_player_esp_feature(playerId)
    if feature then
        return write_feature_state and write_feature_state(feature, 'toggle', desired) or false
    end
    return false
end

local function capture_purge_player_esp_backup()
    if G.playerESPBackupCaptured == true then return end
    G.playerESPBackup = {}
    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        if not (minigames.IsSelf and minigames.IsSelf(playerId)) then
            local value = read_indexed_player_esp(playerId)
            if value ~= nil then
                local identity = select(1, get_identity(playerId))
                G.playerESPBackup[#G.playerESPBackup + 1] = { id=playerId, identity=identity, value=value }
            end
        end
    end
    G.playerESPBackupCaptured = true
end

local function suppress_all_indexed_player_esp()
    local changed, checked, failed, unavailable = 0, 0, 0, 0
    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        if not (minigames.IsSelf and minigames.IsSelf(playerId)) then
            local before = read_indexed_player_esp(playerId)
            if before == nil then
                unavailable = unavailable + 1
            else
                checked = checked + 1
                local ok = write_indexed_player_esp(playerId, false)
                local after = read_indexed_player_esp(playerId)
                if ok and after == false then
                    if before == true then changed = changed + 1 end
                else
                    failed = failed + 1
                end
            end
        end
    end
    local safeForGlobalFlash = checked > 0 and failed == 0 and unavailable == 0
    return changed, safeForGlobalFlash, checked, failed, unavailable
end

local function restore_purge_player_esp_backup()
    local restored, failed = 0, 0
    for _, entry in ipairs(G.playerESPBackup or {}) do
        local currentIdentity = select(1, get_identity(entry.id))
        if currentIdentity == entry.identity then
            if write_indexed_player_esp(entry.id, entry.value == true) then restored = restored + 1 else failed = failed + 1 end
        end
    end
    G.playerESPBackup = {}
    G.playerESPBackupCaptured = false
    return restored, failed
end

read_feature_state = function(feature, kind)
    if not feature then return nil end
    local value = nil
    if kind == 'toggle' then
        if not feature_is_toggle_safe(feature) then return nil end
        direct_call(function()
            if feature.IsToggled then value = feature:IsToggled()
            elseif feature.GetBoolValue then value = feature:GetBoolValue() end
        end)
    elseif kind == 'list' then
        direct_call(function() if feature.GetListIndex then value = feature:GetListIndex() end end)
    elseif kind == 'int' then
        direct_call(function() if feature.GetIntValue then value = feature:GetIntValue() end end)
    elseif kind == 'float' then
        direct_call(function() if feature.GetFloatValue then value = feature:GetFloatValue() end end)
    elseif kind == 'numeric' then
        direct_call(function()
            if feature.GetIntValue then value = { mode = 'int', value = feature:GetIntValue() }
            elseif feature.GetFloatValue then value = { mode = 'float', value = feature:GetFloatValue() } end
        end)
    end
    return value
end

local function trigger_feature_callback(feature)
    if feature and feature.TriggerCallback then
        direct_call(function() feature:TriggerCallback() end)
    end
end

write_feature_state = function(feature, kind, value)
    if not feature or value == nil then return false end
    local ok = false

    if kind == 'toggle' then
        if not feature_is_toggle_safe(feature) then return false end
        local desired = value == true
        local current = read_feature_state(feature, 'toggle')
        if current == desired then return true end

        -- prefer toggle because cherax built-ins commonly attach their real work
        -- to the toggle callback. both explicit-bool and parameterless branches
        -- are supported across prime and non-prime.
        if feature.Toggle then
            direct_call(function() feature:Toggle(desired) end)
            ok = read_feature_state(feature, 'toggle') == desired
            if not ok then
                direct_call(function() feature:Toggle() end)
                ok = read_feature_state(feature, 'toggle') == desired
            end
        end

        if not ok and feature.SetBoolValue then
            direct_call(function() feature:SetBoolValue(desired) end)
            trigger_feature_callback(feature)
            ok = read_feature_state(feature, 'toggle') == desired
        end

        if not ok and feature.SetValue then
            direct_call(function() feature:SetValue(desired) end)
            trigger_feature_callback(feature)
            ok = read_feature_state(feature, 'toggle') == desired
        end

    elseif kind == 'list' then
        if feature.SetListIndex then
            ok = direct_call(function() feature:SetListIndex(math.floor(tonumber(value) or 0)) end)
        end
        if ok then trigger_feature_callback(feature) end

    elseif kind == 'int' then
        if feature.SetIntValue then
            ok = direct_call(function() feature:SetIntValue(math.floor(tonumber(value) or 0)) end)
        end
        if not ok and feature.SetValue then
            ok = direct_call(function() feature:SetValue(math.floor(tonumber(value) or 0)) end)
        end
        if ok then trigger_feature_callback(feature) end

    elseif kind == 'float' then
        if feature.SetFloatValue then
            ok = direct_call(function() feature:SetFloatValue(tonumber(value) or 0.0) end)
        end
        if not ok and feature.SetValue then
            ok = direct_call(function() feature:SetValue(tonumber(value) or 0.0) end)
        end
        if ok then trigger_feature_callback(feature) end

    elseif kind == 'numeric' then
        local mode = type(value) == 'table' and value.mode or nil
        local actual = type(value) == 'table' and value.value or value
        if mode == 'int' or (mode == nil and feature.SetIntValue) then
            if feature.SetIntValue then
                ok = direct_call(function() feature:SetIntValue(math.floor(tonumber(actual) or 0)) end)
            end
        end
        if not ok and feature.SetFloatValue then
            ok = direct_call(function() feature:SetFloatValue(tonumber(actual) or 0.0) end)
        end
        if not ok and feature.SetValue then
            ok = direct_call(function() feature:SetValue(tonumber(actual) or 0.0) end)
        end
        if ok then trigger_feature_callback(feature) end
    end

    return ok
end

local function numeric_max_state(feature)
    if not feature then return nil end
    local maximum = nil
    if feature.GetIntMaxValue then
        direct_call(function() maximum = feature:GetIntMaxValue() end)
        if maximum ~= nil then return { mode = 'int', value = maximum } end
    end
    if feature.GetFloatMaxValue then
        direct_call(function() maximum = feature:GetFloatMaxValue() end)
        if maximum ~= nil then return { mode = 'float', value = maximum } end
    end
    if feature.GetIntLimitValues then
        local minimum = nil
        direct_call(function() minimum, maximum = feature:GetIntLimitValues() end)
        if maximum ~= nil then return { mode = 'int', value = maximum } end
    end
    return nil
end

local function numeric_value_state(feature, value)
    value = tonumber(value) or 0
    if feature and feature.GetIntValue then return { mode = 'int', value = math.floor(value) } end
    return { mode = 'float', value = value }
end

local STARTUP_BACKUP_GLOBAL_KEYS = {
    'hour', 'minute', 'second', 'timeScale', 'freezeTime',
    'smoothWeather', 'weather', 'clouds', 'thunder', 'fog', 'disableLights', 'damageEffect',
    'disableMinimap', 'enableESP', 'espOnDead', 'espDistance',
    'boxOutline', 'drawBox', 'drawBones', 'healthBar'
}

local function startup_backup_id(key, playerId)
    if playerId ~= nil then return tostring(key) .. ':' .. tostring(clamp_int(playerId, 0, 31)) end
    return tostring(key)
end

local function clone_feature_value(value)
    if type(value) ~= 'table' then return value end
    local copy = {}
    for key, item in pairs(value) do copy[key] = item end
    return copy
end

local function capture_startup_entry(key, playerId)
    local backup = G.startupBackup
    local id = startup_backup_id(key, playerId)
    if backup.byId[id] then return true, 'already captured' end

    local spec = PURGE_FEATURE_SPECS[key]
    if not spec then return false, 'unknown feature spec' end
    local feature = find_cherax_feature(spec, playerId)
    if not feature then return false, 'missing' end
    local value = read_feature_state(feature, spec.kind)
    if value == nil then return false, 'unreadable' end

    local entry = {
        id = id,
        key = key,
        playerId = playerId,
        feature = feature,
        kind = spec.kind,
        value = clone_feature_value(value)
    }
    backup.entries[#backup.entries + 1] = entry
    backup.byId[id] = entry
    return true, 'captured'
end

local function refresh_startup_backup_status(reason)
    local backup = G.startupBackup
    local expected = #STARTUP_BACKUP_GLOBAL_KEYS
    local captured = #(backup.entries or {})
    local missing = math.max(0, expected - captured)
    backup.ready = captured > 0
    backup.capturedAtMs = backup.capturedAtMs ~= 0 and backup.capturedAtMs or now_ms()
    backup.status = (backup.ready and 'Ready' or 'Unavailable') .. ': ' .. tostring(captured) .. ' settings saved at Minigames load'
    if missing > 0 then backup.status = backup.status .. ', ' .. tostring(missing) .. ' unavailable' end
    if reason and reason ~= '' then backup.status = backup.status .. ' (' .. tostring(reason) .. ')' end
end

function G.CaptureStartupBackupPass(reason)
    local backup = G.startupBackup
    if G.presetActive == true then
        backup.status = 'Startup backup capture blocked while Purge effects are active'
        return false
    end
    backup.inProgress = true
    backup.passes = (tonumber(backup.passes or 0) or 0) + 1

    local missing = {}
    for _, key in ipairs(STARTUP_BACKUP_GLOBAL_KEYS) do
        local ok, why = capture_startup_entry(key, nil)
        if not ok then missing[#missing + 1] = key .. ':' .. tostring(why) end
    end
    -- v0.183 no longer scans indexed per-player esp features. the hint renderer
    -- is target-specific by construction and only needs the backed-up global esp state.

    backup.missing = missing
    backup.inProgress = false
    refresh_startup_backup_status(reason or ('pass ' .. tostring(backup.passes)))
    return backup.ready == true
end

function G.QueueStartupBackup(reason)
    if G.startupBackup.inProgress == true then return false end
    return queue_job(function()
        -- let the minigames tab, overlay renderer, and startup intro register
        -- before scanning cherax's full feature tree. the scan still happens
        -- immediately after boot and before the purge can modify anything.
        safe_yield(250)
        G.startupBackup.inProgress = true
        for attempt = 1, 6 do
            G.startupBackup.inProgress = false
            G.CaptureStartupBackupPass((reason or 'script load') .. ' pass ' .. tostring(attempt))
            if #(G.startupBackup.missing or {}) == 0 then break end
            safe_yield(500)
        end
        G.startupBackup.inProgress = false
        refresh_startup_backup_status(reason or 'script load')
        log_info('Startup settings backup complete | captured=' .. tostring(#(G.startupBackup.entries or {})) .. ' | unavailable=' .. tostring(#(G.startupBackup.missing or {})) .. ' | passes=' .. tostring(G.startupBackup.passes or 0))
    end)
end

function G.EnsureStartupBackupReady(reason)
    if G.startupBackup.ready == true then return true end
    G.CaptureStartupBackupPass(reason or 'on-demand safety pass')
    return G.startupBackup.ready == true
end

local function get_startup_backup_entry(key, playerId)
    return G.startupBackup.byId[startup_backup_id(key, playerId)]
end

local function mark_startup_backup_touched(key, playerId)
    local id = startup_backup_id(key, playerId)
    if G.startupBackup.byId[id] then G.startupBackup.touched[id] = true return true end
    return false
end

local function resolve_backup_feature(entry)
    if not entry then return nil end
    local spec = PURGE_FEATURE_SPECS[entry.key]
    local fresh = spec and find_cherax_feature(spec, entry.playerId) or nil
    return fresh or entry.feature
end

function G.RestoreStartupBackup(reason)
    local backup = G.startupBackup
    if not backup or backup.ready ~= true then return false, 0, 0 end
    local restored, failed = 0, 0
    local touchedBeforeRestore = {}
    for id, value in pairs(backup.touched or {}) do
        touchedBeforeRestore[id] = value == true
    end

    for index = #(backup.entries or {}), 1, -1 do
        local entry = backup.entries[index]
        if touchedBeforeRestore[entry.id] == true then
            local feature = resolve_backup_feature(entry)
            if write_feature_state(feature, entry.kind, clone_feature_value(entry.value)) then
                restored = restored + 1
            else
                failed = failed + 1
            end
        end
    end
    -- reapply the saved clock in a deterministic order. hour, minute, second,
    -- and time scale are restored first; freeze time is restored last so an
    -- originally running clock resumes from the exact saved time instead of
    -- advancing while the other fields are still being returned.
    local orderedClockKeys = { 'hour', 'minute', 'second', 'timeScale', 'freezeTime' }
    for _, key in ipairs(orderedClockKeys) do
        local entry = backup.byId[startup_backup_id(key, nil)]
        if entry and touchedBeforeRestore[entry.id] == true then
            local feature = resolve_backup_feature(entry)
            if write_feature_state(feature, entry.kind, clone_feature_value(entry.value)) then
                -- this verification pass is intentionally not counted twice.
            else
                failed = failed + 1
            end
        end
    end

    backup.touched = {}
    backup.lastRestoreAtMs = now_ms()
    backup.lastRestoreReason = tostring(reason or 'restore')
    backup.status = 'Ready: startup settings retained; last restore returned ' .. tostring(restored) .. ' settings'
    if failed > 0 then backup.status = backup.status .. ', ' .. tostring(failed) .. ' failed' end
    return failed == 0, restored, failed
end

local function restore_startup_key(key, playerId)
    local entry = get_startup_backup_entry(key, playerId)
    if not entry then return false, 'not backed up' end
    local feature = resolve_backup_feature(entry)
    if not feature then return false, 'missing' end
    local ok = write_feature_state(feature, entry.kind, clone_feature_value(entry.value))
    return ok, ok and 'restored' or 'write failed'
end

local function snapshot_and_set(key, desired)
    local spec = PURGE_FEATURE_SPECS[key]
    local backupEntry = get_startup_backup_entry(key, nil)
    if not backupEntry then
        G.presetMissing = G.presetMissing or {}
        G.presetMissing[#G.presetMissing + 1] = key .. ' (no startup backup)'
        return false, 'not backed up'
    end

    local feature = find_cherax_feature(spec) or backupEntry.feature
    if not feature then
        G.presetMissing = G.presetMissing or {}
        G.presetMissing[#G.presetMissing + 1] = key
        return false, 'missing'
    end

    if spec.kind == 'list' and (type(desired) == 'string' or type(desired) == 'table') then
        desired = list_option_index(feature, desired)
        if desired == nil then return false, 'option missing' end
    elseif spec.kind == 'numeric' and desired == 'MAX' then
        desired = numeric_max_state(feature)
        if desired == nil then return false, 'max unavailable' end
    elseif spec.kind == 'numeric' and type(desired) == 'number' then
        desired = numeric_value_state(feature, desired)
    end

    local ok = write_feature_state(feature, spec.kind, desired)
    if ok then mark_startup_backup_touched(key, nil) end
    return ok, 'set'
end

-- -------------------------------------------------------------------------
-- v0.183 custom target-only hint renderer
-- -------------------------------------------------------------------------
-- cherax prime/non-prime builds do not consistently expose indexed player esp
-- feature objects to lua. rather than ever enabling all-player esp, the purge
-- draws its own lightweight overlay for exactly one player: the assigned target.
local HINT_BONES = {
    pelvis = 0x2E28,
    neck = 0x9995,
    head = 0x796E,
    lUpperArm = 0xB1C5,
    lForearm = 0xEEEB,
    lHand = 0x49D9,
    rUpperArm = 0x9D4D,
    rForearm = 0x6E5C,
    rHand = 0xDEAD,
    lKnee = 0xB3FE,
    lFoot = 0x3779,
    rKnee = 0x3FCF,
    rFoot = 0xCC4D
}

local HINT_BONE_LINES = {
    {'head', 'neck'},
    {'neck', 'pelvis'},
    {'neck', 'lUpperArm'}, {'lUpperArm', 'lForearm'}, {'lForearm', 'lHand'},
    {'neck', 'rUpperArm'}, {'rUpperArm', 'rForearm'}, {'rForearm', 'rHand'},
    {'pelvis', 'lKnee'}, {'lKnee', 'lFoot'},
    {'pelvis', 'rKnee'}, {'rKnee', 'rFoot'}
}

local function raw_v3(hash, ...)
    local a, b, c = Natives.InvokeV3(hash, ...)
    if type(a) == 'number' then return a, b, c end
    if a ~= nil then
        local x, y, z = nil, nil, nil
        direct_call(function() x = a.x or a.X end)
        direct_call(function() y = a.y or a.Y end)
        direct_call(function() z = a.z or a.Z end)
        if x ~= nil and y ~= nil and z ~= nil then return x, y, z end
    end
    return nil, nil, nil
end

local function hint_bone_coord(ped, boneId)
    local ok, x, y, z = direct_call(raw_v3, N.GET_PED_BONE_COORDS, ped, boneId, 0.0, 0.0, 0.0)
    if not ok then return nil end
    if x == nil or y == nil or z == nil then return nil end
    return {x=x, y=y, z=z}
end

local function hint_entity_coord(entity)
    local ok, x, y, z = direct_call(raw_v3, N.GET_ENTITY_COORDS, entity, true)
    if not ok or x == nil then return nil end
    return {x=x, y=y, z=z}
end

function G.DrawTargetHintOverlay()
    if G.hintActive ~= true or G.hintUseCustomESP ~= true or G.run.hintFlashOn ~= true then return end
    local run = G.run
    local target = run and run.target or nil
    if not target or not identity_matches(target) then return end
    if not ImGui or not ImGui.AddLine or not ImGui.AddText or not ImGui.AddRectFilled then return end
    if not Memory or not Memory.Alloc or not Memory.ReadFloat or not Memory.Free then return end

    local ped = minigames.GetPlayerPed and minigames.GetPlayerPed(target.id) or 0
    if not ped or ped == 0 then return end

    local sxPtr, syPtr = nil, nil
    local okAlloc = direct_call(function()
        sxPtr = Memory.Alloc(4)
        syPtr = Memory.Alloc(4)
    end)
    if not okAlloc or not sxPtr or not syPtr then
        if sxPtr then direct_call(Memory.Free, sxPtr) end
        if syPtr then direct_call(Memory.Free, syPtr) end
        return
    end

    local function world_to_screen(pos)
        if not pos then return false, 0, 0 end
        local shown = false
        direct_call(function()
            shown = Natives.InvokeBool(N.GET_SCREEN_COORD_FROM_WORLD_COORD,
                pos.x + 0.0, pos.y + 0.0, pos.z + 0.0, sxPtr, syPtr) == true
        end)
        if not shown then return false, 0, 0 end
        local sx, sy = 0.0, 0.0
        local okRead = direct_call(function()
            sx = Memory.ReadFloat(sxPtr)
            sy = Memory.ReadFloat(syPtr)
        end)
        if not okRead then return false, 0, 0 end
        local dw, dh = 0, 0
        direct_call(function() dw, dh = ImGui.GetDisplaySize() end)
        if not dw or not dh or dw <= 0 or dh <= 0 then return false, 0, 0 end
        return true, sx * dw, sy * dh
    end

    local success, err = direct_call(function()
        local coords = {}
        for name, boneId in pairs(HINT_BONES) do coords[name] = hint_bone_coord(ped, boneId) end

        -- draw bones = full plus a target-only 2d box to mirror the cherax purge esp profile.
        for _, segment in ipairs(HINT_BONE_LINES) do
            local a, b = coords[segment[1]], coords[segment[2]]
            local aOk, ax, ay = world_to_screen(a)
            local bOk, bx, by = world_to_screen(b)
            if aOk and bOk then
                ImGui.AddLine(ax, ay, bx, by, 255, 62, 62, 235, 2.0)
            end
        end

        local head = coords.head or hint_entity_coord(ped)
        local shown, hx, hy = world_to_screen(head)
        if shown then
            -- 2d box fallback. cherax indexed esp uses its native draw box = 2d;
            -- this path only runs when indexed player esp is unavailable.
            local pelvisShown, px, py = world_to_screen(coords.pelvis or hint_entity_coord(ped))
            if pelvisShown then
                local bodyH = math.max(44.0, math.abs(py - hy) * 2.15)
                local bodyW = bodyH * 0.42
                local left, right = hx - bodyW * 0.5, hx + bodyW * 0.5
                local top, bottom = hy - 12.0, hy - 12.0 + bodyH
                ImGui.AddLine(left, top, right, top, 255, 62, 62, 235, 1.6)
                ImGui.AddLine(right, top, right, bottom, 255, 62, 62, 235, 1.6)
                ImGui.AddLine(right, bottom, left, bottom, 255, 62, 62, 235, 1.6)
                ImGui.AddLine(left, bottom, left, top, 255, 62, 62, 235, 1.6)
            end

            local name = tostring(target.name or (minigames.GetPlayerName and minigames.GetPlayerName(target.id)) or 'Target')
            local hp, maxHp = 0, 1
            direct_call(function() hp = Natives.InvokeInt(N.GET_ENTITY_HEALTH, ped) or 0 end)
            direct_call(function() maxHp = Natives.InvokeInt(N.GET_ENTITY_MAX_HEALTH, ped) or 1 end)
            if maxHp <= 0 then maxHp = 1 end
            local ratio = math.max(0.0, math.min(1.0, hp / maxHp))

            local targetPos = hint_entity_coord(ped)
            local myId = minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or -1
            local myPed = myId >= 0 and minigames.GetPlayerPed and minigames.GetPlayerPed(myId) or 0
            local myPos = myPed and myPed ~= 0 and hint_entity_coord(myPed) or nil
            local distance = nil
            if targetPos and myPos then
                local dx, dy, dz = targetPos.x-myPos.x, targetPos.y-myPos.y, targetPos.z-myPos.z
                distance = math.sqrt(dx*dx + dy*dy + dz*dz)
            end

            local barW, barH = 74, 6
            local baseX, baseY = hx - barW * 0.5, hy - 34
            ImGui.AddText(hx - 42, hy - 54, 'TARGET: ' .. name, 255, 90, 90, 255)
            ImGui.AddRectFilled(baseX, baseY, baseX + barW, baseY + barH, 28, 28, 30, 220, 1.0)
            local hr = math.floor((1.0 - ratio) * 255)
            local hg = math.floor(ratio * 255)
            ImGui.AddRectFilled(baseX, baseY, baseX + barW * ratio, baseY + barH, hr, hg, 35, 240, 1.0)
            if distance then
                ImGui.AddText(hx - 20, hy - 24, string.format('%.0fm', distance), 235, 235, 235, 245)
            end
        end
    end)

    direct_call(Memory.Free, sxPtr)
    direct_call(Memory.Free, syPtr)
    if not success and G.hintOverlayErrorLogged ~= true then
        G.hintOverlayErrorLogged = true
        log_error('Custom target hint draw failed once | ' .. tostring(err))
    end
end

-- dedicated presentation handler keeps custom esp independent of cherax's
-- indexed esp features and draws only while the timed hint is active.
if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_PRESENT then
    direct_call(function()
        G.hintPresentHandler = EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
            if G.hintActive == true and G.hintUseCustomESP == true then
                G.DrawTargetHintOverlay()
            end
        end)
    end)
end

-- -------------------------------------------------------------------------
-- v0.183 native atmosphere fallback
-- -------------------------------------------------------------------------
local function apply_native_purge_atmosphere(forceCloud)
    if not Natives or not Natives.InvokeVoid then return false end
    -- never apply a native override unless both original world controls were
    -- captured at minigames startup, so restoration always has an authority.
    if not get_startup_backup_entry('weather', nil) or not get_startup_backup_entry('clouds', nil) then
        return false
    end
    local okWeather = false
    direct_call(function()
        Natives.InvokeVoid(N.SET_OVERRIDE_WEATHER, 'HALLOWEEN')
        Natives.InvokeVoid(N.SET_WEATHER_TYPE_NOW_PERSIST, 'HALLOWEEN')
        okWeather = true
    end)

    local now = now_ms()
    if forceCloud == true or now >= (G.nextNativeCloudRefreshMs or 0) then
        direct_call(function()
            Natives.InvokeVoid(N.PRELOAD_CLOUD_HAT, 'Stormy 01')
            Natives.InvokeVoid(N.LOAD_CLOUD_HAT, 'Stormy 01', forceCloud == true and 0.35 or 0.0)
        end)
        G.nextNativeCloudRefreshMs = now + 15000
    end
    G.nativeAtmosphereActive = okWeather or G.nativeAtmosphereActive == true
    return okWeather
end

local function clear_native_purge_atmosphere()
    if not Natives or not Natives.InvokeVoid then return end
    direct_call(function() Natives.InvokeVoid(N.CLEAR_OVERRIDE_WEATHER) end)
    direct_call(function() Natives.InvokeVoid(N.CLEAR_WEATHER_TYPE_PERSIST) end)
    direct_call(function() Natives.InvokeVoid(N.UNLOAD_CLOUD_HAT, 'Stormy 01', 0.0) end)
    G.nativeAtmosphereActive = false
    G.nextNativeCloudRefreshMs = 0
end

local function hint_snapshot_feature(snapshot, seen, key, feature, kind, desired)
    if not feature then return false, 'missing' end
    local playerId = tostring(key or ''):match('^playerESP:(%d+)$')
    local startupEntry = playerId and get_startup_backup_entry('playerEnableESP', tonumber(playerId)) or get_startup_backup_entry(key, nil)
    if not startupEntry then return false, 'not backed up at Minigames load' end
    local identity = tostring(feature)
    if not seen[identity] then
        local current = read_feature_state(feature, kind)
        if current == nil then return false, 'unreadable' end
        snapshot[#snapshot + 1] = { key = key, feature = feature, kind = kind, value = current }
        seen[identity] = true
    end
    local ok = write_feature_state(feature, kind, desired)
    if ok then
        local playerId = tostring(key or ''):match('^playerESP:(%d+)$')
        if playerId then mark_startup_backup_touched('playerEnableESP', tonumber(playerId))
        else mark_startup_backup_touched(key, nil) end
    end
    return ok, 'set'
end

local function set_global_esp_enabled(desired)
    local spec = PURGE_FEATURE_SPECS.enableESP
    local feature = find_cherax_feature(spec)
    if not feature then return false end
    return write_feature_state(feature, spec.kind, desired == true)
end

local function set_hint_flash_phase(enabled, reason)
    local run = G.run
    enabled = enabled == true
    run.hintFlashOn = enabled

    if G.hintUseCheraxESP == true and run.target then
        -- every non-target indexed esp is held off. the global player esp master
        -- may therefore be flashed safely without revealing the rest of the lobby.
        suppress_all_indexed_player_esp()
        write_indexed_player_esp(run.target.id, enabled)
        set_global_esp_enabled(enabled)
    else
        -- safe fallback: never enable all-player cherax esp. the custom renderer
        -- uses the same 3-second flash cadence and only knows about run.target.
        set_global_esp_enabled(false)
    end

    run.hintStatus = enabled and 'FLASH ON: target revealed' or 'FLASH OFF: target hidden'
    run.hintNextFlashAtMs = now_ms() + 3000
    return true
end

local function stop_target_hint_internal(reason)
    if G.hintActive ~= true and #(G.hintSnapshot or {}) == 0 then return true end
    local run = G.run
    if run and run.target then direct_call(write_indexed_player_esp, run.target.id, false) end
    direct_call(set_global_esp_enabled, false)

    local restored, failed = 0, 0
    for index = #(G.hintSnapshot or {}), 1, -1 do
        local entry = G.hintSnapshot[index]
        if write_feature_state(entry.feature, entry.kind, entry.value) then restored = restored + 1 else failed = failed + 1 end
    end
    G.hintSnapshot = {}
    G.hintActive = false
    G.hintUseCheraxESP = false
    G.hintUseCustomESP = false
    G.run.hintActive = false
    G.run.hintFlashOn = false
    G.run.hintNextFlashAtMs = 0
    G.run.hintEndsAtMs = 0
    G.run.hintStatus = 'Flash hint hidden'
    log_info('Flash hint restored | restored=' .. tostring(restored) .. ' | failed=' .. tostring(failed) .. ' | reason=' .. tostring(reason))
    return failed == 0
end

function G.StopTargetHint(reason)
    return stop_target_hint_internal(reason or 'stopped')
end

function G.ScheduleTargetHint(reason)
    stop_target_hint_internal('target changed')
    local run = G.run
    run.hintNextAtMs = now_ms() + 300000
    run.hintStatus = G.config.hardcoreHint ~= false and 'Next flash hint in 5 minutes' or 'Hints disabled'
    log_info('Flash hint scheduled | reason=' .. tostring(reason) .. ' | target=' .. tostring(run.target and run.target.name or 'None'))
end

function G.StartTargetHint(reason)
    local run = G.run
    if run.active ~= true or run.mode ~= 'hunt' or G.config.hardcoreHint == false then return false end
    if not run.target or not identity_matches(run.target) then return false end
    local eligible = G.GetEligibility(run.target.id, true)
    if not eligible then
        run.hintNextAtMs = now_ms() + 10000
        run.hintStatus = 'Flash hint waiting for target availability'
        return false
    end

    stop_target_hint_internal('new flash hint')
    local snapshot, seen = {}, {}
    local changed, missing = 0, {}

    local function set_global(key, desired)
        local spec = PURGE_FEATURE_SPECS[key]
        local feature = find_cherax_feature(spec)
        if not feature then missing[#missing + 1] = key return false end
        if spec.kind == 'list' and (type(desired) == 'string' or type(desired) == 'table') then
            desired = list_option_index(feature, desired)
            if desired == nil then missing[#missing + 1] = key .. ':option' return false end
        elseif spec.kind == 'numeric' and desired == 'MAX' then
            desired = numeric_max_state(feature)
            if desired == nil then missing[#missing + 1] = key .. ':max' return false end
        elseif spec.kind == 'numeric' and type(desired) == 'number' then
            desired = numeric_value_state(feature, desired)
        end
        local ok = hint_snapshot_feature(snapshot, seen, key, feature, spec.kind, desired)
        if ok then changed = changed + 1 end
        return ok
    end

    -- purge esp profile: misc > esp > player. it remains off between flashes.
    -- distance is fixed to cherax's requested 5000 maximum and draw box is 2d.
    set_global('enableESP', false)
    set_global('espOnDead', true)
    set_global('espDistance', 5000)
    set_global('drawBox', { '2D', '2D Box', 'Box 2D' })
    set_global('boxOutline', { 'None', 'Off' })
    set_global('drawBones', { 'Full', 'Full Body' })
    set_global('healthBar', { 'Health Based', 'Health-Based' })

    capture_purge_player_esp_backup()
    local _, indexedPoolSafe = suppress_all_indexed_player_esp()
    local indexedTargetReady = write_indexed_player_esp(run.target.id, false)

    G.hintSnapshot = snapshot
    G.hintUseCheraxESP = indexedPoolSafe == true and indexedTargetReady == true
    G.hintUseCustomESP = G.hintUseCheraxESP ~= true
    G.hintActive = true
    run.hintActive = true
    run.hintTargetIdentity = run.target.identity
    run.hintEndsAtMs = now_ms() + 15000
    run.hintNextAtMs = now_ms() + 300000
    run.hintNextFlashAtMs = 0
    run.hintFlashOn = false

    set_hint_flash_phase(true, reason)
    run.hintStatus = (G.hintUseCheraxESP == true and 'Cherax ESP' or 'safe target overlay') .. ' flashing every 3 sec for 15 sec'
    toast('Flash Hint: ' .. tostring(run.target.name) .. ' pulses for 15 seconds.', 2500)
    log_info('Flash hint active | target=' .. tostring(run.target.name) .. ' | source=' .. (G.hintUseCheraxESP == true and 'Cherax indexed ESP' or 'custom target-only fallback') .. ' | distance=5000 | box=2D | pulse=3s | duration=15s | next=5m | reason=' .. tostring(reason))
    return true
end

local function tick_target_hint(now)
    local run = G.run
    if G.hintActive == true then
        if not run.target or run.hintTargetIdentity ~= run.target.identity or now >= (run.hintEndsAtMs or 0) then
            stop_target_hint_internal('duration ended or target changed')
            return
        end
        if now >= (run.hintNextFlashAtMs or 0) then
            set_hint_flash_phase(run.hintFlashOn ~= true, '3-second pulse')
        end
        return
    end
    if run.active == true and run.mode == 'hunt' and G.config.hardcoreHint ~= false and run.target and now >= (run.hintNextAtMs or 0) then
        G.StartTargetHint('scheduled five-minute flash hint')
    end
end

local function send_team_target_chat()
    local run = G.run
    if run.teamMode ~= true or G.config.teamChatAnnouncements == false or not run.target then return false end
    local teamInfo = G.GetLocalTeamInfo(true)
    if not teamInfo.available then
        run.teamChatStatus = 'No CEO/MC team detected for target briefing'
        return false
    end
    if not GTA or not GTA.SendChatMessageToEveryone then
        run.teamChatStatus = 'Cherax team chat API unavailable'
        return false
    end

    local name = tostring(run.target.name or 'Unknown'):gsub('[\r\n|]', ' ')
    if #name > 22 then name = name:sub(1, 22) end
    local targetTime = format_clock(run.targetDurationMs or 0)
    local remaining = #(run.queue or {})
    local totalTime = format_clock(math.max(0, (run.globalEndMs or now_ms()) - now_ms()))
    local message = 'Next Target to Kill: ' .. name .. ' | ' .. targetTime .. ' | ' .. tostring(remaining) .. ' left | ' .. totalTime .. ' total'

    local ok, err = direct_call(GTA.SendChatMessageToEveryone, message, true)
    if ok then
        run.teamChatStatus = 'Sent: ' .. message
        log_info('Team target briefing sent | ' .. message)
        return true
    end
    run.teamChatStatus = 'Team target briefing failed'
    log_error('Team target briefing failed | ' .. tostring(err))
    return false
end

function G.ResetPurgeEffects(reason)
    stop_target_hint_internal('effect reset')
    return G.RestorePurgePreset(reason or 'manual effect reset')
end

local function feature_state_matches(kind, current, desired)
    if current == nil or desired == nil then return false end
    if kind == 'toggle' then return (current == true) == (desired == true) end
    if kind == 'numeric' then
        if type(current) ~= 'table' or type(desired) ~= 'table' then return false end
        return current.mode == desired.mode and math.abs((tonumber(current.value) or 0) - (tonumber(desired.value) or 0)) < 0.0005
    end
    if kind == 'float' then
        return math.abs((tonumber(current) or 0) - (tonumber(desired) or 0)) < 0.0005
    end
    return tonumber(current) == tonumber(desired)
end

local function enforce_backed_purge_value(key, desired)
    local spec = PURGE_FEATURE_SPECS[key]
    local backupEntry = get_startup_backup_entry(key, nil)
    if not spec or not backupEntry then return false, false end

    local feature = find_cherax_feature(spec) or backupEntry.feature
    if not feature then return false, false end

    if spec.kind == 'list' and (type(desired) == 'string' or type(desired) == 'table') then
        desired = list_option_index(feature, desired)
        if desired == nil then return false, false end
    elseif spec.kind == 'numeric' and type(desired) == 'number' then
        desired = numeric_value_state(feature, desired)
    end

    local current = read_feature_state(feature, spec.kind)
    if feature_state_matches(spec.kind, current, desired) then return true, false end

    local ok = write_feature_state(feature, spec.kind, desired)
    if ok then mark_startup_backup_touched(key, nil) end
    return ok, ok
end

local function tick_purge_world_guard(now)
    local run = G.run
    if run.active ~= true or G.presetActive ~= true then return end
    if now < (run.nextWorldPresetGuardMs or 0) then return end
    run.nextWorldPresetGuardMs = now + 3000

    -- the damage vignette is a core purge presentation effect, independent of
    -- the optional world preset. keep it enabled for the full active lifecycle.
    local critical = {
        { 'damageEffect', true }
    }

    -- gta or another script can resync world settings after the initial write.
    -- reassert only the critical purge clock/weather values when that optional
    -- atmosphere preset is enabled. the startup snapshot remains untouched.
    if G.config.applyAtmospherePreset ~= false then
        critical[#critical + 1] = { 'hour', 0 }
        critical[#critical + 1] = { 'minute', 0 }
        critical[#critical + 1] = { 'second', 0 }
        critical[#critical + 1] = { 'timeScale', 1.0 }
        critical[#critical + 1] = { 'freezeTime', true }
        critical[#critical + 1] = { 'smoothWeather', true }
        critical[#critical + 1] = { 'weather', 'Halloween Rain' }
        critical[#critical + 1] = { 'clouds', 'Stormy 01' }
        critical[#critical + 1] = { 'thunder', true }
    end
    -- player esp is a purge-owned temporary profile in both stages. normal esp
    -- stays off except for the target-only 3-second flash pulses.
    if G.config.disablePlayerESP ~= false then
        critical[#critical + 1] = { 'espDistance', 5000 }
        critical[#critical + 1] = { 'drawBox', { '2D', '2D Box', 'Box 2D' } }
        if G.hintActive ~= true or run.hintFlashOn ~= true then
            critical[#critical + 1] = { 'enableESP', false }
        end
    end

    -- v0.198 phase rule: the opening target is hardcore with no minimap. the
    -- city-wide sweep deliberately turns the minimap back on until the purge ends.
    if run.mode ~= 'hour' then
        if run.stage == 'opening' then
            critical[#critical + 1] = { 'disableMinimap', true }
        elseif run.stage == 'transition' or run.stage == 'city_sweep' then
            critical[#critical + 1] = { 'disableMinimap', false }
        end
    end

    local corrected = 0
    for _, target in ipairs(critical) do
        local ok, changed = enforce_backed_purge_value(target[1], target[2])
        if ok and changed then corrected = corrected + 1 end
    end
    -- force the visible network-session atmosphere only when the optional
    -- world preset is enabled. damage effect remains independent of this toggle.
    if G.config.applyAtmospherePreset ~= false then
        apply_native_purge_atmosphere(false)
    end

    if corrected > 0 then
        run.presetStatus = 'Purge world preset active; corrected ' .. tostring(corrected) .. ' drifted setting' .. (corrected == 1 and '' or 's')
        log_info('Purge world guard corrected drift | changed=' .. tostring(corrected))
    end
end

function G.ApplyPurgePreset(expectedSerial, reason)
    if expectedSerial and G.run.serial ~= expectedSerial then return false end
    if G.run.active ~= true then return false end
    if G.presetActive == true then
        G.run.presetApplied = true
        return true
    end
    if not G.EnsureStartupBackupReady('before Purge preset') then
        G.run.presetApplied = false
        G.run.presetStatus = 'Purge preset blocked because no startup settings backup was available'
        log_error(G.run.presetStatus)
        return false
    end

    G.startupBackup.touched = {}
    G.presetMissing = {}
    local changed = 0

    if G.config.applyAtmospherePreset ~= false then
        local targets = {
            { 'hour', 0 },
            { 'minute', 0 },
            { 'second', 0 },
            { 'timeScale', 1.0 },
            { 'freezeTime', true },
            { 'smoothWeather', true },
            { 'weather', 'Halloween Rain' },
            { 'clouds', 'Stormy 01' },
            { 'thunder', true },
            { 'fog', 0.003 },
            { 'disableLights', true }
        }
        for _, target in ipairs(targets) do
            local ok = snapshot_and_set(target[1], target[2])
            if ok then changed = changed + 1 end
        end
        apply_native_purge_atmosphere(true)
    end

    -- core purge screen treatment: misc > rendering > enable damage effect.
    -- it is independent of the optional world preset and always restores from
    -- the minigames startup backup when the purge lifecycle ends.
    do
        local ok = snapshot_and_set('damageEffect', true)
        if ok then changed = changed + 1 end
    end

    if G.config.disablePlayerESP ~= false or G.run.hardcoreMode == true then
        local ok = snapshot_and_set('enableESP', false)
        if ok then changed = changed + 1 end
        ok = snapshot_and_set('espDistance', 5000)
        if ok then changed = changed + 1 end
        ok = snapshot_and_set('drawBox', { '2D', '2D Box', 'Box 2D' })
        if ok then changed = changed + 1 end
        capture_purge_player_esp_backup()
        suppress_all_indexed_player_esp()
    end

    if G.run.hardcoreMode == true and G.run.mode ~= 'hour' then
        local ok = snapshot_and_set('disableMinimap', true)
        if ok then changed = changed + 1 end
    end

    G.presetActive = true
    G.run.nextWorldPresetGuardMs = now_ms() + 1000
    G.run.presetApplied = true
    G.run.presetChanged = changed
    G.run.presetMissing = #(G.presetMissing or {})
    G.run.presetStatus = 'Applied ' .. tostring(changed) .. ' Cherax settings'
    if #(G.presetMissing or {}) > 0 then
        G.run.presetStatus = G.run.presetStatus .. '; unavailable: ' .. table.concat(G.presetMissing, ', ')
    end
    log_info('Purge preset applied | changed=' .. tostring(changed) .. ' | missing=' .. tostring(#(G.presetMissing or {})) .. ' | reason=' .. tostring(reason))
    return true
end

function G.RestorePurgePreset(reason)
    stop_target_hint_internal('Purge preset restore')
    clear_native_purge_atmosphere()
    local ok, restored, failed = G.RestoreStartupBackup(reason or 'Purge preset restore')
    local playerRestored, playerFailed = restore_purge_player_esp_backup()
    restored = (restored or 0) + playerRestored
    failed = (failed or 0) + playerFailed
    G.presetActive = false
    G.run.nextWorldPresetGuardMs = 0
    G.presetMissing = {}
    G.run.presetApplied = false
    G.run.presetStatus = 'Restored ' .. tostring(restored or 0) .. ' settings from the Minigames startup backup'
    if (failed or 0) > 0 then G.run.presetStatus = G.run.presetStatus .. '; failed: ' .. tostring(failed) end
    log_info('Purge preset restored from startup backup | restored=' .. tostring(restored or 0) .. ' | failed=' .. tostring(failed or 0) .. ' | reason=' .. tostring(reason))
    return ok == true
end

function G.QueueApplyPurgePreset(reason)
    local serial = G.run.serial
    return queue_job(function() G.ApplyPurgePreset(serial, reason) end)
end

function G.QueueRestorePurgePreset(reason)
    G.run.restoreRequested = true
    G.run.restoreReason = tostring(reason or 'Purge restore')
    G.run.restoreRequestedAtMs = now_ms()

    return queue_job(function()
        if G.run.restoreRequested == true then
            local restoreReason = G.run.restoreReason or reason or 'Purge restore'
            G.RestorePurgePreset(restoreReason)
            G.run.restoreRequested = false
            G.run.restoreReason = nil
        end
    end)
end

function G.ApplyHardcoreModeNow(enabled, reason)
    local run = G.run

    -- v0.187: hardcore is mandatory during the normal purge hunt. keep this
    -- compatibility entry point so older ui callbacks cannot accidentally disable it.
    if run.mode == 'hour' then
        run.hardcoreMode = false
        run.hardcoreStatus = 'Purge Hour uses the normal minimap.'
        return true
    end

    enabled = true
    G.config.hardcoreMode = true
    run.hardcoreMode = true

    if run.active ~= true then
        run.hardcoreStatus = 'Hardcore is always enabled when The Purge starts.'
        return true
    end

    if not G.EnsureStartupBackupReady('Hardcore live change') then
        run.hardcoreStatus = 'Hardcore could not apply because the startup backup is unavailable.'
        return false
    end

    local changed, failed = 0, 0
    if enabled then
        local ok = snapshot_and_set('disableMinimap', true)
        if ok then changed = changed + 1 else failed = failed + 1 end
        ok = snapshot_and_set('enableESP', false)
        if ok then changed = changed + 1 else failed = failed + 1 end
        G.ScheduleTargetHint('Hardcore enabled during live run')
        run.hardcoreStatus = 'Hardcore active: minimap disabled and normal Player ESP hidden.'
    else
        local ok = restore_startup_key('disableMinimap', nil)
        if ok then changed = changed + 1 else failed = failed + 1 end

        if G.config.disablePlayerESP == false then
            ok = restore_startup_key('enableESP', nil)
            if ok then changed = changed + 1 else failed = failed + 1 end
        else
            ok = snapshot_and_set('enableESP', false)
            if ok then changed = changed + 1 else failed = failed + 1 end
        end
        if G.config.hardcoreHint ~= false and run.mode == 'hunt' and run.target then
            G.ScheduleTargetHint('Hardcore disabled; target hints remain enabled')
        end
        run.hardcoreStatus = 'Hardcore disabled; minimap returned to its startup value. Target hints remain independent.'
    end

    run.presetStatus = tostring(run.presetStatus or 'Purge preset active') .. ' | ' .. run.hardcoreStatus
    log_info('Hardcore live update | enabled=' .. tostring(enabled) .. ' | changed=' .. tostring(changed) .. ' | failed=' .. tostring(failed) .. ' | reason=' .. tostring(reason))
    return failed == 0
end

function G.QueueHardcoreModeNow(enabled, reason)
    local desired = enabled == true
    return queue_job(function()
        G.ApplyHardcoreModeNow(desired, reason or 'Hardcore UI toggle')
    end)
end

local function mirror_state()
    local run = G.run
    local now = now_ms()
    minigames.S.purgeActive = run.active == true
    minigames.S.purgeHudLive = run.hudLive == true
    minigames.S.purgeHudEnabled = run.hudLive == true or run.active == true
    minigames.S.purgeHudPreviewEnabled = false
    minigames.S.purgePhase = tostring(run.phase or 'IDLE')
    minigames.S.purgeTargetName = tostring(run.target and run.target.name or run.targetName or 'None')
    minigames.S.purgeProgressDone = tonumber(run.done or 0) or 0
    minigames.S.purgeProgressTotal = tonumber(run.total or 0) or 0
    minigames.S.purgeTargetTimeMaxMs = tonumber(run.targetDurationMs or 1) or 1
    minigames.S.purgeGlobalTimeMaxMs = tonumber(run.globalDurationMs or run.hourDurationMs or 1) or 1
    minigames.S.purgeStatusText = tostring(run.status or 'The Purge is idle.')
    minigames.S.purgeTeamMode = run.teamMode == true
    minigames.S.purgeHardcoreMode = run.hardcoreMode == true
    minigames.S.purgeStage = tostring(run.stageLabel or run.stage or 'IDLE')
    local scopeLabel
    if run.stage == 'opening' then scopeLabel = 'FIRST TARGET'
    elseif run.stage == 'transition' then scopeLabel = 'CITYWIDE INTRO'
    elseif run.stage == 'city_sweep' then scopeLabel = 'CITY SWEEP'
    elseif run.mode == 'hour' then scopeLabel = 'PURGE HOUR'
    else scopeLabel = run.wholeLobby == true and 'WHOLE LOBBY' or 'SINGLE TARGET' end
    local combatLabel = run.hardcoreMode == true and (run.teamMode == true and 'HARDCORE TEAM' or 'HARDCORE') or (run.teamMode == true and 'TEAM' or 'SOLO')
    minigames.S.purgeModeLabel = scopeLabel .. ' | ' .. combatLabel
    minigames.S.purgePresetStatus = tostring(run.presetStatus or (G.presetActive == true and 'Purge preset active' or 'Purge preset idle'))
    minigames.S.purgeBackupStatus = tostring(G.startupBackup and G.startupBackup.status or 'Startup backup unavailable')
    minigames.S.purgeBackupReady = G.startupBackup and G.startupBackup.ready == true or false
    minigames.S.purgeHintActive = G.hintActive == true
    if G.hintActive == true then
        local seconds = math.max(0, math.ceil(((run.hintEndsAtMs or now) - now) / 1000))
        minigames.S.purgeHintStatus = 'Target hint visible: ' .. tostring(seconds) .. 's remaining'
    elseif run.active == true and run.mode == 'hunt' and G.config.hardcoreHint ~= false and run.target then
        local seconds = math.max(0, math.ceil(((run.hintNextAtMs or now) - now) / 1000))
        minigames.S.purgeHintStatus = 'Next target hint in ' .. tostring(seconds) .. 's'
    else
        minigames.S.purgeHintStatus = tostring(run.hintStatus or 'Idle')
    end
    minigames.S.purgeTeamChatStatus = tostring(run.teamChatStatus or 'Idle')

    if run.mode == 'hour' then
        minigames.S.purgeTargetTimeMs = 0
        minigames.S.purgeGlobalTimeMs = math.max(0, (run.hourEndMs or now) - now)
    elseif run.mode == 'preparing' then
        minigames.S.purgeTargetTimeMs = tonumber(run.targetDurationMs or 0) or 0
        minigames.S.purgeGlobalTimeMs = tonumber(run.globalDurationMs or 0) or 0
    elseif run.mode == 'stage_transition' then
        minigames.S.purgeTargetTimeMs = 0
        minigames.S.purgeGlobalTimeMs = math.max(0, (run.transitionEndMs or now) - now)
    elseif run.mode == 'victory_wait' then
        minigames.S.purgeTargetTimeMs = 0
        minigames.S.purgeGlobalTimeMs = clamp_int(G.config.purgeHourMinutes, 15, 60) * 60000
    elseif run.mode == 'result' then
        minigames.S.purgeTargetTimeMs = 0
        minigames.S.purgeGlobalTimeMs = 0
    else
        minigames.S.purgeTargetTimeMs = math.max(0, (run.targetEndMs or now) - now)
        minigames.S.purgeGlobalTimeMs = math.max(0, (run.globalEndMs or now) - now)
    end

    minigames.S.purgeExcludedCount = tonumber(run.currentExcluded or run.startExcludedCount or 0) or 0
    minigames.S.purgeAliveTargets = tonumber(run.currentEligible or #(run.queue or {})) or 0
end

local function set_phase(phase, status)
    G.run.phase = tostring(phase or 'IDLE')
    if status then G.run.status = tostring(status) end
    mirror_state()
end

local function remove_queue_index(index, reason)
    local queue = G.run.queue or {}
    local record = table.remove(queue, index)
    if record then
        G.run.total = math.max(G.run.done or 0, (G.run.total or #queue + 1) - 1)
        log_info('Roster target removed | name=' .. tostring(record.name) .. ' | reason=' .. tostring(reason))
    end
    return record
end

local function forget_passive_targets()
    local run = G.run
    local queue = run.queue or {}
    local removed = 0
    local currentRemoved = false

    -- walk backwards so removing entries cannot skip the next record. passive
    -- mode is treated differently from temporary unavailable states: once a
    -- player enters passive mode during the sequential hunt, they are no longer
    -- required for this run and are not rotated to the back of the queue.
    for index = #queue, 1, -1 do
        local record = queue[index]
        if record and identity_matches(record) and is_passive(record.id) then
            if run.target and run.target.identity == record.identity then
                currentRemoved = true
            end
            remove_queue_index(index, 'Passive mode - permanently skipped for this Purge run')
            removed = removed + 1
        end
    end

    if removed > 0 then
        run.passiveSkipped = (tonumber(run.passiveSkipped or 0) or 0) + removed
        run.currentExcluded = math.max(0, tonumber(run.currentExcluded or 0) or 0) + removed
        if currentRemoved then
            stop_target_hint_internal('Current target entered Passive Mode')
            run.target = nil
            run.targetName = 'Skipping Passive Mode player'
            run.targetUnavailableAtMs = 0
            run.targetPauseStartMs = 0
            run.waitingRespawn = false
            run.respawnReadyAtMs = 0
        end
        log_info('Passive Mode roster skip | removed=' .. tostring(removed) .. ' | remaining=' .. tostring(#queue))
    end

    return removed, currentRemoved
end

local function count_live_roster()
    local run = G.run
    local now = now_ms()
    if now - (run.lastRosterCountMs or 0) < 750 then return end
    run.lastRosterCountMs = now

    local eligible, excluded = 0, 0
    for _, record in ipairs(run.queue or {}) do
        if identity_matches(record) then
            local dead = minigames.IsPlayerDead and select(1, minigames.IsPlayerDead(record.id)) or false
            if dead and record.wasDead ~= true then record.needsBounty = true end
            record.wasDead = dead == true

            local ok = false
            if not dead then ok = G.GetEligibility(record.id, true) end
            if ok then eligible = eligible + 1 else excluded = excluded + 1 end
        end
    end
    run.currentEligible = eligible
    run.currentExcluded = excluded
end

local function hunt_instruction(name)
    if G.run.teamMode == true then
        return 'Eliminate ' .. tostring(name) .. '. You or a CEO/MC teammate can claim the target. Do not die.'
    end
    return 'Eliminate ' .. tostring(name) .. ' yourself. Do not die.'
end

local function assign_current_target(reason)
    local run = G.run
    local queue = run.queue or {}

    forget_passive_targets()

    while #queue > 0 and not identity_matches(queue[1]) do
        remove_queue_index(1, 'player left or slot identity changed')
    end

    -- v0.197: never assign a target that has become invalid since the roster
    -- was locked. these states are skipped rather than rotated back into queue.
    while #queue > 0 do
        local record = queue[1]
        local eligible, why = G.GetEligibility(record.id, true, run.teamMode == true)
        if eligible then break end
        local permanentSkip = why == 'Passive mode' or why == 'God mode or invincible'
            or why == 'Outside Los Santos city limits' or why == 'Inside an interior'
            or why == 'Sub-session or activity' or why == 'Left session'
        if not permanentSkip then break end
        remove_queue_index(1, tostring(why) .. ' - skipped before target assignment')
        run.currentExcluded = math.max(0, tonumber(run.currentExcluded or 0) or 0) + 1
        if why == 'Passive mode' then run.passiveSkipped = (tonumber(run.passiveSkipped or 0) or 0) + 1 end
    end

    if #queue == 0 and refill_single_target_from_standby(reason) then
        queue = run.queue or {}
    end

    if #queue == 0 then
        G.CompleteHunt()
        return false
    end

    run.target = queue[1]
    run.targetName = run.target.name
    if run.stage == 'opening' then
        run.targetDurationMs = 60 * 60000
    else
        run.targetDurationMs = clamp_int(G.config.targetMinutes, 5, 10) * 60000
    end
    local targetNow = now_ms()
    run.targetEndMs = targetNow + run.targetDurationMs
    if run.stage == 'opening' and (tonumber(run.globalEndMs or 0) or 0) > targetNow then
        run.targetEndMs = math.min(run.targetEndMs, run.globalEndMs)
    end
    run.targetUnavailableAtMs = 0
    run.targetPauseStartMs = 0
    run.waitingRespawn = false
    run.respawnReadyAtMs = 0
    run.nextTargetAtMs = 0
    run.targetWasDead = minigames.IsPlayerDead and select(1, minigames.IsPlayerDead(run.target.id)) or false
    run.target.wasDead = run.targetWasDead == true
    clear_damage_history(run.target.id)
    if run.target.openingBountyApplied ~= true or run.target.needsBounty == true then
        local applied = apply_bounty(run.target.id, 'target assignment')
        if applied then
            run.target.openingBountyApplied = true
            run.target.needsBounty = false
        end
    end
    run.lastTargetBountyMs = now_ms()
    set_phase('HUNT ACTIVE', hunt_instruction(run.target.name))
    G.ScheduleTargetHint('target assigned')
    send_team_target_chat()
    log_info('Target assigned | player=' .. tostring(run.target.id) .. ' | name=' .. tostring(run.target.name) .. ' | reason=' .. tostring(reason))
    return true
end

local function rotate_current(reason, applyPenalty)
    local run = G.run
    local queue = run.queue or {}
    if #queue == 0 then return assign_current_target(reason) end

    local record = table.remove(queue, 1)
    queue[#queue + 1] = record
    if applyPenalty == true then
        local penalty = clamp_int(G.config.targetTimeoutPenaltySeconds, 0, 120) * 1000
        run.globalEndMs = math.max(now_ms(), (run.globalEndMs or now_ms()) - penalty)
    end
    run.target = nil
    return assign_current_target(reason)
end

function G.Fail(reason)
    stop_target_hint_internal('Purge failed')
    local run = G.run
    if run.active ~= true and run.hudLive ~= true then return end
    run.active = false
    run.mode = 'result'
    run.phase = 'FAILED'
    run.status = tostring(reason or 'The Purge failed.')
    run.hudLive = true
    run.resultDisplayUntilMs = now_ms() + 10000
    run.targetEndMs = now_ms()
    run.globalEndMs = now_ms()
    G.stats.lastResult = 'Failed: ' .. tostring(reason or 'Unknown')
    G.SaveProgress()
    set_intro('PURGE FAILED', 'The run is over', tostring(reason or 'You did not complete the roster'), 'Start a new run when you are ready.', 'Purge failed')
    mirror_state()
    toast(run.status, 6000)
    log_info('Run failed | ' .. tostring(run.status))
    G.QueueRestorePurgePreset('Purge failed')
end

function G.Abandon()
    stop_target_hint_internal('Purge abandoned')
    local run = G.run
    if run.active ~= true then return end
    run.active = false
    run.mode = 'result'
    run.phase = 'ABANDONED'
    run.status = 'The Purge was abandoned.'
    run.hudLive = true
    run.resultDisplayUntilMs = now_ms() + 7000
    run.targetEndMs = now_ms()
    run.globalEndMs = now_ms()
    G.stats.lastResult = 'Abandoned'
    G.SaveProgress()
    mirror_state()
    toast('Run abandoned.', 3000)
    log_info('Run abandoned by user')
    G.QueueRestorePurgePreset('Purge abandoned')
end

local function begin_city_sweep(now)
    local run = G.run
    now = tonumber(now or now_ms()) or now_ms()

    local roster, excluded = G.BuildRoster()
    local openingIdentity = run.openingTargetIdentity
    if openingIdentity then
        for index = #roster, 1, -1 do
            if roster[index] and roster[index].identity == openingIdentity then
                table.remove(roster, index)
            end
        end
    end

    run.stage = 'city_sweep'
    run.stageLabel = 'STAGE 2: CITY SWEEP'
    run.mode = 'hunt'
    run.phase = 'CITY SWEEP ACTIVE'
    run.wholeLobby = true
    run.singleTargetMode = false
    run.hardcoreMode = false
    run.queue = roster
    run.roster = roster
    run.singleTargetStandby = {}
    run.startExcluded = excluded
    run.startExcludedCount = #excluded
    run.done = 0
    run.totalEliminations = 0
    run.openingTargetIdentity = nil
    run.openingTargetName = nil
    run.total = 1
    run.initialTotal = 1
    run.currentEligible = #roster
    run.currentExcluded = #excluded
    run.target = nil
    run.targetName = 'Selecting city target'
    run.targetDurationMs = clamp_int(G.config.targetMinutes, 5, 10) * 60000
    run.globalDurationMs = math.max(run.targetDurationMs, math.max(1, #roster) * run.targetDurationMs)
    run.globalEndMs = now + run.globalDurationMs
    run.transitionEndMs = 0
    run.nextTargetAtMs = 0
    run.targetUnavailableAtMs = 0
    run.targetPauseStartMs = 0
    run.waitingRespawn = false
    run.respawnReadyAtMs = 0
    run.huntCompleted = false

    -- phase 2 intentionally has the minimap on even if the user normally has it
    -- disabled. the startup backup still restores their exact original value when
    -- the complete purge lifecycle ends.
    local minimapOn = snapshot_and_set('disableMinimap', false)
    run.hardcoreStatus = minimapOn and 'Stage 2: minimap enabled.' or 'Stage 2: minimap enable reported unavailable.'

    if #roster == 0 then
        run.status = 'No additional eligible Los Santos targets remain after the opening hunt.'
        log_info('City sweep had no additional eligible targets; completing Purge after opening elimination.')
        G.CompleteHunt()
        return
    end

    for _, record in ipairs(roster) do
        record.openingBountyApplied = false
        record.needsBounty = true
    end

    run.status = 'Session-wide Purge active. Eliminate every eligible Los Santos target once, one at a time.'
    toast('CITYWIDE PURGE ACTIVE: minimap ON, one bounty at a time, ' .. tostring(clamp_int(G.config.targetMinutes, 5, 10)) .. ' minutes per target.', 6500)
    log_info('Stage 2 started | city_targets=' .. tostring(#roster) .. ' | excluded=' .. tostring(#excluded) .. ' | perTargetMinutes=' .. tostring(clamp_int(G.config.targetMinutes, 5, 10)))
    assign_current_target('citywide Purge started')
    mirror_state()
end

local function begin_city_sweep_transition(openingTarget)
    local run = G.run
    stop_target_hint_internal('opening target complete')
    run.stage = 'transition'
    run.stageLabel = 'ESCALATION'
    run.mode = 'stage_transition'
    run.phase = 'PURGE ESCALATION'
    run.target = nil
    run.targetName = 'CITYWIDE PURGE INCOMING'
    run.queue = {}
    run.roster = {}
    run.done = 0
    run.total = 0
    run.targetEndMs = 0
    run.globalEndMs = 0
    run.nextTargetAtMs = 0
    run.transitionEndMs = now_ms() + 8500
    run.hardcoreMode = false
    run.openingTargetIdentity = openingTarget and openingTarget.identity or run.openingTargetIdentity
    run.openingTargetName = openingTarget and openingTarget.name or run.openingTargetName

    -- turn the minimap on before the second-stage intro so the rule change is
    -- visible immediately. player esp remains off except during flash hint pulses.
    snapshot_and_set('disableMinimap', false)
    snapshot_and_set('enableESP', false)
    run.status = 'First target eliminated. Session-wide Purge begins after the HUD intro.'

    set_intro(
        'THE PURGE: CITYWIDE',
        'SESSION-WIDE PURGE',
        'Opening target eliminated. Every eligible player still inside Los Santos is now in the sweep.',
        'Minimap ON. One bounty at a time. ' .. tostring(clamp_int(G.config.targetMinutes, 5, 10)) .. ' minutes per target.',
        'Purge stage transition'
    )
    toast('First target eliminated. The citywide Purge begins now.', 5000)
    log_info('Stage transition started | openingTarget=' .. tostring(run.openingTargetName or 'Unknown') .. ' | introMs=8500')
    mirror_state()
end

function G.CompleteHunt()
    stop_target_hint_internal('Purge completed')
    local run = G.run
    if run.huntCompleted == true then return end
    if (tonumber(run.totalEliminations or run.done or 0) or 0) <= 0 then
        G.Fail('All remaining targets left before you earned a credited elimination.')
        return
    end
    run.huntCompleted = true
    run.phase = 'COMPLETE'
    run.status = 'Opening target and every required city-sweep target were eliminated without dying.'
    run.target = nil
    run.targetName = 'Roster complete'
    run.targetEndMs = now_ms()
    local elapsed = math.max(1, now_ms() - (run.huntStartMs or now_ms()))

    G.stats.unlocked = true
    G.stats.wins = (tonumber(G.stats.wins or 0) or 0) + 1
    if (tonumber(G.stats.bestMs or 0) or 0) <= 0 or elapsed < G.stats.bestMs then G.stats.bestMs = elapsed end
    G.stats.lastResult = 'Victory in ' .. format_clock(elapsed)
    G.SaveProgress()

    -- v0.187: the base hunt is over now. return the user's original minimap
    -- immediately even when purge hour is configured to auto-start afterward.
    local minimapRestored = restore_startup_key('disableMinimap', nil)
    run.hardcoreMode = false
    run.hardcoreStatus = minimapRestored and 'Hunt complete: minimap restored.' or 'Hunt complete: minimap restore reported a failure.'
    log_info('Hunt completion minimap restore | restored=' .. tostring(minimapRestored))
    if G.StopApocalypseTraffic then
        direct_call(function() G.StopApocalypseTraffic('Purge target hunt complete') end)
    end

    set_intro('PURGE COMPLETE', 'LOS SANTOS CLEARED', 'Opening target and city sweep complete.', 'No deaths. Purge Hour begins next.', 'Purge victory')
    toast('Purge complete. Purge Hour unlocked.', 7000)
    log_info('Hunt completed | elapsedMs=' .. tostring(elapsed) .. ' | targets=' .. tostring(run.done or 0))

    if G.config.autoStartPurgeHour ~= false then
        run.purgeHourStartAtMs = now_ms() + 5400
        run.active = true
        run.mode = 'victory_wait'
    else
        run.active = false
        run.mode = 'result'
        run.hudLive = true
        run.resultDisplayUntilMs = now_ms() + 12000
        G.QueueRestorePurgePreset('Purge victory without Purge Hour')
    end
    mirror_state()
end

local function complete_current_target(attribution, killerId)
    stop_target_hint_internal('target eliminated')
    local run = G.run
    local target = run.target
    if not target then return end
    table.remove(run.queue, 1)
    run.done = (run.done or 0) + 1
    run.totalEliminations = (tonumber(run.totalEliminations or 0) or 0) + 1
    run.lastEliminatedIdentity = target.identity
    run.lastEliminatedName = target.name
    run.target = nil
    run.targetName = target.name
    run.nextTargetAtMs = now_ms() + 1600
    run.phase = 'TARGET ELIMINATED'

    local localId = minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or 0
    local killerName = killerId and killerId >= 0 and (minigames.GetPlayerName and minigames.GetPlayerName(killerId) or ('Player ' .. tostring(killerId))) or 'Purge team'
    if killerId == localId or killerId == nil or killerId < 0 then
        run.status = tostring(target.name) .. ' eliminated. Preparing the next target.'
    else
        run.status = tostring(killerName) .. ' eliminated ' .. tostring(target.name) .. ' for the Purge team. Preparing the next target.'
    end
    log_info('Target credited | player=' .. tostring(target.id) .. ' | name=' .. tostring(target.name) .. ' | killer=' .. tostring(killerName) .. ' | attribution=' .. tostring(attribution))
    mirror_state()

    if run.stage == 'opening' then
        begin_city_sweep_transition(target)
        return
    end

    if #(run.queue or {}) == 0 then G.CompleteHunt() end
end

local function handle_target_death()
    local run = G.run
    local target = run.target
    if not target then return end

    local credited, method, killerId = G.WasKilledByPurgeSide(target.id)
    if credited then
        complete_current_target(method, killerId)
        return
    end

    run.waitingRespawn = true
    run.respawnReadyAtMs = 0
    run.targetPauseStartMs = now_ms()
    run.phase = 'TARGET LOST'
    run.status = tostring(target.name) .. ' was killed by someone else. The bounty will return after respawn.'
    if minigames.Player and minigames.Player.bountyApplied then
        minigames.Player.bountyApplied[target.id] = false
        if minigames.Player.bountyAppliedAtMs then minigames.Player.bountyAppliedAtMs[target.id] = 0 end
    end
    log_info('Target stolen or uncredited | name=' .. tostring(target.name) .. ' | attribution=' .. tostring(method))
    mirror_state()
end

function G.StartPurgeHour(manual)
    stop_target_hint_internal('Purge Hour start')
    local run = G.run
    if not G.EnsureStartupBackupReady('Purge Hour safety check') then
        toast('Purge Hour cannot start because Minigames could not back up the Cherax settings it would modify. No settings were changed.', 7000)
        return false
    end
    if manual == true and G.stats.unlocked ~= true then
        toast('Complete The Purge once to unlock Purge Hour.', 4500)
        return false
    end
    if run.active == true and run.mode ~= 'victory_wait' then
        toast('A Purge event is already active.', 3500)
        return false
    end

    local continuingVictory = run.mode == 'victory_wait'
    run.serial = (tonumber(run.serial or 0) or 0) + 1
    run.active = true
    run.hudLive = true
    run.mode = 'hour'
    if not continuingVictory then
        run.teamMode = G.config.teamMode == true
        -- purge hour is the post-hunt reward and keeps the normal minimap available.
        run.hardcoreMode = false
        run.presetApplied = false
        run.presetStatus = 'Purge preset queued'
    end
    run.phase = 'PURGE HOUR'
    run.status = 'All eligible players receive recurring bounties. New players are enrolled automatically.'
    run.target = nil
    run.targetName = 'ALL ELIGIBLE PLAYERS'
    run.hourDurationMs = clamp_int(G.config.purgeHourMinutes, 15, 60) * 60000
    run.hourEndMs = now_ms() + run.hourDurationMs
    run.globalDurationMs = run.hourDurationMs
    run.done = 0
    run.total = 0
    run.hourPlayers = {}
    run.lastHourScanMs = 0
    run.purgeHourStartAtMs = 0
    run.hintActive = false
    run.hintFlashOn = false
    run.hintNextFlashAtMs = 0
    run.hintNextAtMs = 0
    run.hintEndsAtMs = 0
    run.hintStatus = 'Hints are not used during Purge Hour'
    run.teamChatStatus = 'Target briefings are not used during Purge Hour'
    minigames.S.purgeHudPreviewEnabled = false
    minigames.S.purgeHudEnabled = true

    set_intro('PURGE HOUR', 'The session is marked', 'Eligible bounties will return after every death.', run.teamMode == true and 'CEO/MC teammates remain on your side.' or 'New arrivals are enrolled automatically.', 'Purge Hour')
    mirror_state()
    G.QueueApplyPurgePreset('Purge Hour start')
    toast('Purge Hour active for ' .. tostring(G.config.purgeHourMinutes) .. ' minutes.', 6000)
    log_info('Purge Hour started | manual=' .. tostring(manual == true) .. ' | minutes=' .. tostring(G.config.purgeHourMinutes))
    return true
end

local function finish_purge_hour()
    stop_target_hint_internal('Purge Hour complete')
    local run = G.run
    run.active = false
    run.hudLive = true
    run.mode = 'result'
    run.phase = 'COMPLETE'
    run.status = 'Purge Hour has ended.'
    run.targetName = 'Event complete'
    run.resultDisplayUntilMs = now_ms() + 10000
    run.targetEndMs = now_ms()
    run.globalEndMs = now_ms()
    G.stats.lastResult = 'Purge Hour completed'
    G.SaveProgress()
    set_intro('PURGE HOUR COMPLETE', 'The session survived', 'Recurring bounty maintenance has ended.', 'The Purge remains unlocked.', 'Purge Hour complete')
    mirror_state()
    toast('Purge Hour complete.', 5000)
    log_info('Purge Hour ended normally')
    G.QueueRestorePurgePreset('Purge Hour complete')
end

local function tick_purge_hour(now)
    local run = G.run
    if now >= (run.hourEndMs or now) then finish_purge_hour() return end
    if now - (run.lastHourScanMs or 0) < 750 then mirror_state() return end
    run.lastHourScanMs = now

    local seen = {}
    local eligible, excluded = 0, 0
    for _, playerId in ipairs(minigames.S.activePlayers or {}) do
        if not (minigames.IsSelf and minigames.IsSelf(playerId)) then
            local identity, name = get_identity(playerId)
            seen[identity] = true
            local entry = run.hourPlayers[identity]
            if not entry then
                entry = { id = playerId, identity = identity, name = name, wasDead = false, applied = false, pending = false, respawnAtMs = 0 }
                run.hourPlayers[identity] = entry
            end

            local dead = minigames.IsPlayerDead and select(1, minigames.IsPlayerDead(playerId)) or false
            if dead and entry.wasDead ~= true then
                entry.pending = true
                entry.applied = false
                entry.respawnAtMs = 0
                if minigames.Player and minigames.Player.bountyApplied then minigames.Player.bountyApplied[playerId] = false end
            end
            entry.wasDead = dead == true

            local ok = false
            if not dead then ok = G.GetEligibility(playerId, true, run.teamMode == true) end
            if ok then
                eligible = eligible + 1
                if entry.pending == true then
                    if entry.respawnAtMs == 0 then entry.respawnAtMs = now + clamp_int(G.config.respawnGraceSeconds, 3, 10) * 1000 end
                    if now >= entry.respawnAtMs then
                        local applied = apply_bounty(playerId, 'Purge Hour respawn')
                        if applied then entry.pending = false entry.applied = true end
                    end
                elseif entry.applied ~= true then
                    local applied = apply_bounty(playerId, 'Purge Hour enrollment')
                    if applied then entry.applied = true end
                end
            else
                excluded = excluded + 1
            end
        end
    end

    for identity in pairs(run.hourPlayers) do
        if not seen[identity] then run.hourPlayers[identity] = nil end
    end

    run.currentEligible = eligible
    run.currentExcluded = excluded
    run.total = eligible + excluded
    run.done = 0
    mirror_state()
end

function G.Start()
    if G.run.active == true then
        toast('The Purge is already active.', 3500)
        return false
    end

    local ready, reason = G.CheckLocalReady()
    if not ready then toast(reason, 5000) return false end

    if not G.EnsureStartupBackupReady('Purge start safety check') then
        toast('The Purge cannot start because Minigames could not back up the Cherax settings it would modify. No settings were changed.', 7000)
        return false
    end

    -- v0.198: stage 1 begins with exactly one eligible los santos target.
    -- stage 2 rebuilds the city roster only after that opening target is eliminated.
    G.config.wholeLobby = true
    local fullRoster, excluded = G.BuildRoster()
    if #fullRoster == 0 then
        toast('No eligible players are available inside Los Santos. Passive, god mode, outside-city, interior, sub-session, dead, and self players are excluded.', 6500)
        return false
    end

    -- the first shuffled player becomes the one-hour opening target. everyone
    -- else remains a replacement standby only until the opening elimination.
    local roster, standby = {}, {}
    roster[1] = table.remove(fullRoster, 1)
    for _, record in ipairs(fullRoster) do standby[#standby + 1] = record end
    if #roster == 0 then
        toast('No eligible target could be selected.', 5000)
        return false
    end

    local now = now_ms()
    local run = G.run
    run.serial = (tonumber(run.serial or 0) or 0) + 1
    run.active = true
    run.hudLive = true
    run.mode = 'preparing'
    run.phase = 'PREPARING'
    run.status = 'Selecting the opening Los Santos target. Only that player receives a bounty.'
    run.stage = 'opening'
    run.stageLabel = 'STAGE 1: FIRST TARGET'
    run.wholeLobby = false
    run.singleTargetMode = true
    run.singleTargetStandby = standby
    run.teamMode = G.config.teamMode == true
    -- v0.187: every normal purge hunt is hardcore by design.
    run.hardcoreMode = true
    run.presetApplied = false
    run.presetStatus = 'Purge preset queued'
    run.queue = roster
    run.roster = roster
    run.startExcluded = excluded
    run.startExcludedCount = #excluded
    run.done = 0
    run.total = #roster
    run.initialTotal = #roster
    run.passiveSkipped = 0
    run.target = nil
    run.targetName = 'Preparing roster'
    run.huntCompleted = false
    run.initialBountiesReady = false
    run.prepEndMs = now + clamp_int(G.config.preparationSeconds, 5, 30) * 1000
    -- stage 1 is intentionally generous: one target, one hour, no minimap.
    run.targetDurationMs = 60 * 60000
    run.globalDurationMs = 60 * 60000
    run.globalEndMs = 0
    run.huntStartMs = 0
    run.localWasDead = false
    run.currentEligible = #roster
    run.currentExcluded = #excluded
    run.resultDisplayUntilMs = 0
    run.purgeHourStartAtMs = 0
    run.hintActive = false
    run.hintFlashOn = false
    run.hintNextFlashAtMs = 0
    run.hintNextAtMs = 0
    run.hintEndsAtMs = 0
    run.hintStatus = G.config.hardcoreHint ~= false and 'Flash hint: every 5 minutes, 15 seconds, 3-second pulses' or 'Hints disabled'
    run.teamChatStatus = G.config.teamChatAnnouncements ~= false and 'Waiting for first target' or 'Team chat announcements disabled'

    G.stats.attempts = (tonumber(G.stats.attempts or 0) or 0) + 1
    G.stats.lastResult = 'In progress'
    G.SaveProgress()

    minigames.S.purgeHudPreviewEnabled = false
    minigames.S.purgeHudEnabled = true
    reset_intro_copy()
    local scopeText = 'STAGE 1: FIRST TARGET'
    local introLine = run.teamMode == true and 'You or a CEO/MC teammate have 60 minutes to eliminate the marked target.' or 'You have 60 minutes to find and eliminate the marked target.'
    local introFinal = 'Los Santos only. Minimap OFF. Flash Hint reveals only the target.'
    set_intro('THE PURGE (BETA)', scopeText, introLine, introFinal, 'Purge start')
    mirror_state()
    G.QueueApplyPurgePreset('Purge start')

    local serial = run.serial
    queue_job(function()
        if G.run.serial ~= serial or G.run.active ~= true then return end
        -- v0.197: never pre-bounty the roster. each record stays bounty-ready
        -- until it becomes the active queue head.
        for _, record in ipairs(roster) do
            record.openingBountyApplied = false
            record.needsBounty = true
        end
        G.run.initialBountiesReady = true
        G.run.status = 'Opening target ready. Bounty waits for target assignment.'
        mirror_state()
    end)

    local modeLabel = run.hardcoreMode == true and (run.teamMode == true and 'Hardcore Team' or 'Hardcore') or (run.teamMode == true and 'Team' or 'Solo')
    local scopeLabel = 'Opening Target: 60 minutes'
    toast('The Purge is preparing. ' .. scopeLabel .. ' | Mode: ' .. modeLabel .. '.', 5000)
    log_info('Run started | stage=opening | mode=' .. modeLabel .. ' | target=1 | standby=' .. tostring(#(standby or {})) .. ' | excluded=' .. tostring(#excluded) .. ' | globalMs=' .. tostring(run.globalDurationMs))
    return true
end

local function begin_hunt(now)
    local run = G.run
    run.mode = 'hunt'
    run.huntStartMs = now
    run.globalEndMs = now + run.globalDurationMs
    run.localWasDead = false
    assign_current_target('hunt started')
end

local function tick_hunt(now)
    local run = G.run
    tick_target_hint(now)
    if now >= (run.globalEndMs or now) then
        if run.stage == 'opening' then G.Fail('The 60-minute opening-target timer expired.')
        else G.Fail('The city-sweep timer expired.') end
        return
    end

    local localId = minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or 0
    local localDead = minigames.IsPlayerDead and select(1, minigames.IsPlayerDead(localId)) or false
    if localDead and run.localWasDead ~= true then
        run.localWasDead = true
        G.Fail('You died before completing the roster.')
        return
    end
    run.localWasDead = localDead == true

    local passiveRemoved, currentPassiveRemoved = forget_passive_targets()
    if currentPassiveRemoved then
        -- stage 1 has a standby pool. let the normal target selector refill from
        -- it instead of incorrectly treating a passive mode target as a victory.
        assign_current_target('previous target entered Passive Mode and was skipped')
        count_live_roster()
        mirror_state()
        return
    elseif passiveRemoved > 0 and #(run.queue or {}) == 0 then
        assign_current_target('passive targets removed from roster')
        return
    end

    if run.nextTargetAtMs and run.nextTargetAtMs > 0 then
        if now >= run.nextTargetAtMs and run.huntCompleted ~= true then
            run.nextTargetAtMs = 0
            assign_current_target('previous target completed')
        end
        count_live_roster()
        mirror_state()
        return
    end

    local target = run.target
    if not target then assign_current_target('target missing') return end
    if not identity_matches(target) then
        remove_queue_index(1, 'target left or slot reused')
        run.target = nil
        assign_current_target('target unavailable permanently')
        return
    end

    local dead = minigames.IsPlayerDead and select(1, minigames.IsPlayerDead(target.id)) or false
    if dead and run.targetWasDead ~= true then
        run.targetWasDead = true
        handle_target_death()
        return
    end
    run.targetWasDead = dead == true

    if run.waitingRespawn == true then
        if not dead then
            local eligible, reason = G.GetEligibility(target.id, true)
            if eligible then
                if run.respawnReadyAtMs == 0 then
                    run.respawnReadyAtMs = now + clamp_int(G.config.respawnGraceSeconds, 3, 10) * 1000
                    run.status = tostring(target.name) .. ' respawned. Restoring the bounty after spawn protection.'
                elseif now >= run.respawnReadyAtMs then
                    local applied = apply_bounty(target.id, 'stolen target respawn')
                    if applied then
                        target.openingBountyApplied = true
                        target.needsBounty = false
                    end
                    if run.targetPauseStartMs and run.targetPauseStartMs > 0 then
                        run.targetEndMs = run.targetEndMs + (now - run.targetPauseStartMs)
                    end
                    run.targetPauseStartMs = 0
                    run.waitingRespawn = false
                    run.respawnReadyAtMs = 0
                    clear_damage_history(target.id)
                    set_phase('HUNT ACTIVE', hunt_instruction(target.name))
                end
            else
                run.respawnReadyAtMs = 0
                if reason == 'Passive mode' or reason == 'God mode or invincible' or reason == 'Outside Los Santos city limits' or reason == 'Inside an interior' or reason == 'Sub-session or activity' then
                    local label = reason == 'Passive mode' and 'entered Passive Mode' or (reason == 'God mode or invincible' and 'entered God Mode' or (reason == 'Inside an interior' and 'entered an interior' or (reason == 'Sub-session or activity' and 'entered an activity' or 'left Los Santos')))
                    remove_queue_index(1, reason .. ' - permanently skipped after respawn')
                    if reason == 'Passive mode' then run.passiveSkipped = (tonumber(run.passiveSkipped or 0) or 0) + 1 end
                    stop_target_hint_internal('Target ' .. label)
                    run.target = nil
                    run.waitingRespawn = false
                    run.targetPauseStartMs = 0
                    run.targetUnavailableAtMs = 0
                    run.status = tostring(target.name) .. ' ' .. label .. '. Selecting another target inside Los Santos.'
                    toast(run.status, 3500)
                    assign_current_target('target ' .. label .. ' after respawn')
                    return
                end
                run.status = tostring(target.name) .. ' is unavailable after respawn: ' .. tostring(reason) .. '.'
            end
        end
        count_live_roster()
        mirror_state()
        return
    end

    local eligible, reason = G.GetEligibility(target.id, true)
    if not eligible then
        if reason == 'Left session' then
            remove_queue_index(1, reason)
            run.target = nil
            assign_current_target('target left')
            return
        end

        if reason == 'Passive mode' or reason == 'God mode or invincible' or reason == 'Outside Los Santos city limits' or reason == 'Inside an interior' or reason == 'Sub-session or activity' then
            local label = reason == 'Passive mode' and 'entered Passive Mode' or (reason == 'God mode or invincible' and 'entered God Mode' or (reason == 'Inside an interior' and 'entered an interior' or (reason == 'Sub-session or activity' and 'entered an activity' or 'left Los Santos city limits')))
            remove_queue_index(1, reason .. ' - permanently skipped for this Purge run')
            if reason == 'Passive mode' then run.passiveSkipped = (tonumber(run.passiveSkipped or 0) or 0) + 1 end
            stop_target_hint_internal('Target ' .. label)
            run.target = nil
            run.targetUnavailableAtMs = 0
            run.targetPauseStartMs = 0
            run.waitingRespawn = false
            run.respawnReadyAtMs = 0
            run.status = tostring(target.name) .. ' ' .. label .. '. Selecting another target inside Los Santos.'
            toast(run.status, 3500)
            assign_current_target('target ' .. label .. ' and was skipped')
            return
        end

        if run.targetUnavailableAtMs == 0 then
            run.targetUnavailableAtMs = now
            run.targetPauseStartMs = now
            set_phase('TARGET UNAVAILABLE', tostring(target.name) .. ' is unavailable: ' .. tostring(reason) .. '.')
        elseif now - run.targetUnavailableAtMs >= clamp_int(G.config.unavailableRotateSeconds, 5, 30) * 1000 then
            if run.targetPauseStartMs and run.targetPauseStartMs > 0 then
                run.targetEndMs = run.targetEndMs + (now - run.targetPauseStartMs)
            end
            rotate_current('unavailable target rotated: ' .. tostring(reason), false)
            return
        end
        count_live_roster()
        mirror_state()
        return
    elseif run.targetUnavailableAtMs ~= 0 then
        if run.targetPauseStartMs and run.targetPauseStartMs > 0 then
            run.targetEndMs = run.targetEndMs + (now - run.targetPauseStartMs)
        end
        run.targetUnavailableAtMs = 0
        run.targetPauseStartMs = 0
        set_phase('HUNT ACTIVE', hunt_instruction(target.name))
    end

    if now >= (run.targetEndMs or now) then
        rotate_current('target timer expired', true)
        return
    end

    count_live_roster()
    mirror_state()
end

function G.Tick()
    local ok, err = direct_call_trace(function()
        local run = G.run
        local now = now_ms()

        if run.restoreRequested == true and run.active ~= true then
            local restoreReason = run.restoreReason or 'Deferred Purge restore'
            G.RestorePurgePreset(restoreReason)
            run.restoreRequested = false
            run.restoreReason = nil
        end

        if run.active ~= true then
            if run.hudLive == true and run.resultDisplayUntilMs and run.resultDisplayUntilMs > 0 and now >= run.resultDisplayUntilMs then
                run.hudLive = false
                minigames.S.purgeHudEnabled = false
                mirror_state()
            end
            return
        end

        tick_purge_world_guard(now)

        if run.mode == 'preparing' then
            if now >= (run.prepEndMs or now) and run.initialBountiesReady == true and run.presetApplied == true then begin_hunt(now) end
            mirror_state()
            return
        end

        if run.mode == 'hunt' then tick_hunt(now) return end

        if run.mode == 'stage_transition' then
            if now >= (run.transitionEndMs or now) then begin_city_sweep(now) else mirror_state() end
            return
        end

        if run.mode == 'victory_wait' then
            if now >= (run.purgeHourStartAtMs or now) then G.StartPurgeHour(false) else mirror_state() end
            return
        end

        if run.mode == 'hour' then tick_purge_hour(now) return end
    end, debug and debug.traceback or function(e) return tostring(e) end)

    if not ok then
        log_error('Engine tick failed: ' .. tostring(err))
        G.Fail('The Purge engine encountered an error. Check the log.')
    end
end

local function update_sync_state(playerId, node)
    playerId = tonumber(playerId)
    if not playerId or playerId < 0 or playerId > 31 or not node then return end
    local state = G.sync[playerId] or {}
    direct_call(function() if node.bIsPassiveMode ~= nil then state.passive = node.bIsPassiveMode == true end end)
    direct_call(function() if node.TutorialIndex ~= nil then state.tutorialIndex = tonumber(node.TutorialIndex) or 0 end end)
    direct_call(function() if node.TutorialInstanceID ~= nil then state.tutorialInstanceId = tonumber(node.TutorialInstanceID) or 0 end end)
    direct_call(function() if node.PlayerState ~= nil then state.playerState = tonumber(node.PlayerState) or 0 end end)
    direct_call(function() if node.PlayerTeam ~= nil then state.playerTeam = tonumber(node.PlayerTeam) or -1 end end)
    direct_call(function() if node.bInCutscene ~= nil then state.inCutscene = node.bInCutscene == true end end)
    state.updatedAtMs = now_ms()
    G.sync[playerId] = state
end

if EventMgr and EventMgr.RegisterHandler and eLuaEvent then
    if eLuaEvent.CAN_APPLY_NODE_DATA then
        direct_call(function()
            EventMgr.RegisterHandler(eLuaEvent.CAN_APPLY_NODE_DATA, function(isCreate, modelHash, position, netObject, updatedNodes)
                local playerId = netObject and netObject.PlayerId or -1
                if playerId ~= -1 and updatedNodes then
                    direct_call(function()
                        for _, node in ipairs(updatedNodes) do
                            local nodeName = nil
                            direct_call(function() nodeName = node:GetNodeName() end)
                            if nodeName == 'CPlayerGameStateDataNode' then
                                local typed = nil
                                direct_call(function() typed = node:As('CPlayerGameStateDataNode') end)
                                update_sync_state(playerId, typed or node)
                            end
                        end
                    end)
                end
                return true
            end)
        end)
    end

    if eLuaEvent.ON_SYNC_DATA_NODE then
        direct_call(function()
            EventMgr.RegisterHandler(eLuaEvent.ON_SYNC_DATA_NODE, function(nodeType, node, entity, isExclusive, playerId)
                if playerId == -1 and entity then
                    direct_call(function()
                        if entity.NetObject then playerId = entity.NetObject.PlayerId end
                    end)
                end
                local matches = false
                if eSyncDataNode and eSyncDataNode.CPlayerGameStateDataNode then
                    matches = nodeType == eSyncDataNode.CPlayerGameStateDataNode
                end
                if matches then update_sync_state(playerId, node) end
            end)
        end)
    end

    if eLuaEvent.ON_PLAYER_LEFT then
        direct_call(function()
            EventMgr.RegisterHandler(eLuaEvent.ON_PLAYER_LEFT, function(playerId)
                G.sync[playerId] = nil
            end)
        end)
    end

    if eLuaEvent.ON_UNLOAD then
        direct_call(function()
            EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
                G.run.active = false
                G.run.hudLive = false
                direct_call(function() G.RestorePurgePreset('script unload') end)
                G.SaveProgress()
            end)
        end)
    end
end

local previousSchedulerTick = minigames.Scheduler and minigames.Scheduler.Tick
if minigames.Scheduler and previousSchedulerTick then
    function minigames.Scheduler.Tick(...)
        local result = previousSchedulerTick(...)
        G.Tick()
        return result
    end
end

function G.RenderUI()
    if not ImGui then return end
    local run = G.run

    if begin_child('The Purge') then
        ImGui.Text('THE PURGE (BETA)')
        text_wrapped('Stage 1: one target, one bounty, 60 minutes.')
        text_wrapped('Passive or departed targets are skipped and replaced.')
        text_wrapped('Stage 2: city sweep, minimap on, one target at a time.')
        text_wrapped('Startup Backup: ' .. tostring(G.startupBackup.status or 'Pending'))

        if run.active == true then
            if ImGui.Button('ABANDON THE PURGE') then G.Abandon() end
            if run.mode == 'hunt' and G.config.hardcoreHint ~= false then
                same_line()
                if ImGui.Button('FLASH HINT') then G.StartTargetHint('manual hint') end
            end
        else
            if ImGui.Button('START THE PURGE') then G.Start() end
            if G.stats.unlocked == true then
                same_line()
                if ImGui.Button('START PURGE HOUR') then G.StartPurgeHour(true) end
            end
        end
        if ImGui.Button('RESTORE STARTUP SETTINGS') then G.QueueRestorePurgePreset('manual restore button') end
        if run.active == true and G.presetActive ~= true then
            same_line()
            if ImGui.Button('REAPPLY PURGE EFFECTS') then G.QueueApplyPurgePreset('manual reapply button') end
        end
        end_child()
    end

    if begin_child('Purge Settings') then
        local changed = false
        local anyChanged = false

        G.config.wholeLobby = true
        text_wrapped('Flow: 60-minute opening target, then a Los Santos city sweep one target at a time.')

        G.config.teamMode, changed = checkbox('CEO / MC Team Mode', G.config.teamMode)
        anyChanged = anyChanged or changed
        ImGui.Text('Minimap: OFF for Stage 1, ON for Stage 2')
        text_wrapped('Your original minimap setting is restored after the full Purge ends.')
        G.config.hardcoreHint, changed = checkbox('Flash Hint', G.config.hardcoreHint)
        anyChanged = anyChanged or changed
        G.config.teamChatAnnouncements, changed = checkbox('Team Chat Target Announcements', G.config.teamChatAnnouncements)
        anyChanged = anyChanged or changed
        G.config.applyAtmospherePreset, changed = checkbox('Apply Purge World Preset', G.config.applyAtmospherePreset)
        anyChanged = anyChanged or changed
        G.config.disablePlayerESP, changed = checkbox('Disable Player ESP During Purge', G.config.disablePlayerESP)
        anyChanged = anyChanged or changed

        local teamInfo = G.GetLocalTeamInfo(false)
        if G.config.teamMode == true then
            if teamInfo.available then
                ImGui.Text('Detected Team: ' .. tostring(teamInfo.team) .. '    Hunters: ' .. tostring(#(teamInfo.members or {})))
            else
                text_wrapped('No active CEO or MC team was detected. Team Mode will safely fall back to local-player kills until a team is available.')
            end
        end
        if run.active == true then text_wrapped('Hardcore is locked on for the active hunt. Other mode and preset changes apply to the next Purge.') end
        text_wrapped('Damage Effect is temporary and restores afterward.')
        text_wrapped('World: midnight, Halloween Rain, Stormy clouds, lightning, fog, lights off.')
        text_wrapped('ESP: target only, 2D box, distance 5000. Flash: 3 sec on/off for 15 sec.')

        ImGui.Text('Stage 1 Target Time: 60 minutes')
        G.config.targetMinutes, changed = slider_int('Stage 2 Target Timer Minutes', G.config.targetMinutes, 5, 10)
        anyChanged = anyChanged or changed
        G.config.purgeHourMinutes, changed = slider_int('Purge Hour Duration Minutes', G.config.purgeHourMinutes, 15, 60)
        anyChanged = anyChanged or changed
        G.config.unavailableRotateSeconds, changed = slider_int('Unavailable Target Rotation Seconds', G.config.unavailableRotateSeconds, 5, 30)
        anyChanged = anyChanged or changed
        G.config.respawnGraceSeconds, changed = slider_int('Respawn Grace Seconds', G.config.respawnGraceSeconds, 3, 10)
        anyChanged = anyChanged or changed
        G.config.targetTimeoutPenaltySeconds, changed = slider_int('Target Timeout Penalty Seconds', G.config.targetTimeoutPenaltySeconds, 0, 120)
        anyChanged = anyChanged or changed
        G.config.preparationSeconds, changed = slider_int('Preparation Countdown Seconds', G.config.preparationSeconds, 5, 30)
        anyChanged = anyChanged or changed
        G.config.autoStartPurgeHour, changed = checkbox('Start Purge Hour after victory', G.config.autoStartPurgeHour)
        anyChanged = anyChanged or changed
        if anyChanged then G.SaveProgress() end
        end_child()
    end

    if begin_child('Purge Live Status') then
        mirror_state()
        ImGui.Text('Mode: ' .. tostring(minigames.S.purgeModeLabel or 'FIRST TARGET | HARDCORE'))
        ImGui.Text('Stage: ' .. tostring(minigames.S.purgeStage or 'IDLE'))
        ImGui.Text('Phase: ' .. tostring(minigames.S.purgePhase or 'IDLE'))
        ImGui.Text('Target: ' .. tostring(minigames.S.purgeTargetName or 'None'))
        ImGui.Text('Progress: ' .. tostring(minigames.S.purgeProgressDone or 0) .. ' / ' .. tostring(minigames.S.purgeProgressTotal or 0))
        ImGui.Text('Target Time: ' .. format_clock(minigames.S.purgeTargetTimeMs or 0))
        ImGui.Text('Purge Time: ' .. format_clock(minigames.S.purgeGlobalTimeMs or 0))
        ImGui.Text('Eligible: ' .. tostring(minigames.S.purgeAliveTargets or 0) .. '    Excluded: ' .. tostring(minigames.S.purgeExcludedCount or 0))
        text_wrapped('Status: ' .. tostring(minigames.S.purgeStatusText or 'Idle'))
        text_wrapped('Preset: ' .. tostring(minigames.S.purgePresetStatus or 'Idle'))
        text_wrapped('Startup Backup: ' .. tostring(minigames.S.purgeBackupStatus or 'Pending'))
        text_wrapped('Hint: ' .. tostring(minigames.S.purgeHintStatus or 'Idle'))
        if run.teamMode == true then text_wrapped('Team Chat: ' .. tostring(minigames.S.purgeTeamChatStatus or 'Idle')) end
        end_child()
    end

    if begin_child('Current Session Eligibility') then
        local summary = G.GetSessionEligibilitySummary()
        ImGui.Text('Eligible targets now: ' .. tostring(summary.eligible))
        ImGui.Text('Excluded now: ' .. tostring(summary.excluded))
        for reason, count in pairs(summary.reasons) do
            ImGui.Text(tostring(reason) .. ': ' .. tostring(count))
        end
        end_child()
    end

    if begin_child('Purge Record') then
        ImGui.Text('Purge Hour Unlocked: ' .. (G.stats.unlocked and 'Yes' or 'No'))
        ImGui.Text('Attempts: ' .. tostring(G.stats.attempts or 0))
        ImGui.Text('Victories: ' .. tostring(G.stats.wins or 0))
        ImGui.Text('Best Hunt: ' .. ((tonumber(G.stats.bestMs or 0) or 0) > 0 and format_clock(G.stats.bestMs) or 'None'))
        text_wrapped('Last Result: ' .. tostring(G.stats.lastResult or 'None'))
        end_child()
    end

    if ImGui.CollapsingHeader and ImGui.CollapsingHeader('Presentation Test Tools') then
        if ImGui.Button('PREVIEW INTRO + HUD') and P.StartPreview then P.StartPreview() end
        same_line()
        if ImGui.Button('REPLAY INTRO') and P.StartIntro then reset_intro_copy() P.StartIntro('Manual replay') end
        same_line()
        if ImGui.Button('STOP PREVIEW') and P.StopPreview then P.StopPreview() end
    end
end

P.RenderUI = G.RenderUI
G.LoadProgress()
-- reassert the v0.187 rule after loading older progress.ini files that may have
-- saved hardcoremode=false, then persist the migrated value.
G.config.hardcoreMode = true
direct_call(function() G.SaveProgress() end)

-- capture immediately after boot in a deferred worker. this preserves the
-- requirement to save settings as minigames loads without blocking the tab or
-- consuming the startup intro while cherax's full feature tree is scanned.
-- no purge setting can be modified without a matching backup entry.
G.QueueStartupBackup('Minigames load')
