embedded_modules['systems\\ui_subtabs_v185.lua'] = function()
-- minigames v0.185 navigation polish
-- replaces dropdown-driven routing with real nested subtabs.

minigames.UIX = minigames.UIX or {}
minigames.S = minigames.S or {}

local UI = minigames.UIX
local P = minigames.PurgeUI or {}

local function render_wargames_status(activeRound, previousLabel)
    if not UI.Child then return end
    UI.Child(
        'Minigames_WarGamesSummary_v184',
        'Live WarGames Status',
        'WarGames systems continue running while you move between sections.',
        function()
            if UI.StatusRow then
                local selectedVehicle = 'Unknown'
                if minigames.GetVehicleLabelByIndex then
                    direct_call(function()
                        selectedVehicle = minigames.GetVehicleLabelByIndex(
                            minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or 1
                        ) or selectedVehicle
                    end)
                end
                if activeRound and type(activeRound) == 'table' then
                    selectedVehicle = activeRound.label or activeRound.name or activeRound.model or selectedVehicle
                elseif type(activeRound) == 'string' and activeRound ~= '' then
                    selectedVehicle = activeRound
                end

                local playerCount = 0
                if minigames.GetActivePlayerCount then
                    direct_call(function() playerCount = tonumber(minigames.GetActivePlayerCount()) or 0 end)
                elseif Players and Players.Get then
                    direct_call(function() playerCount = #(Players.Get() or {}) end)
                end

                UI.StatusRow('Selected Vehicle', selectedVehicle, 'gold')
                UI.StatusRow('Previous Round', previousLabel or 'None', 'dim')
                UI.StatusRow('Tracked Vehicles', #(minigames.S.spawnedWarGamesVehicles or {}), 'cyan')
                UI.StatusRow('Players', playerCount, 'green')
                UI.StatusRow('Respawn Watcher', minigames.S.respawnWatcherRunning == true and 'ON' or 'OFF', minigames.S.respawnWatcherRunning == true and 'green' or 'dim')
                UI.StatusRow('Last Bounty', minigames.S.lastBountyStatus or 'None', 'white')
            end
        end,
        'red'
    )
end

local function get_wargames_context()
    local activeRound = nil
    local previousLabel = 'None'

    if minigames.WarGames and minigames.WarGames.RefreshWarGamesUiSettings then
        direct_call(minigames.WarGames.RefreshWarGamesUiSettings)
    end
    if minigames.WarGames and minigames.WarGames.GetCurrentRoundVehicle then
        direct_call(function() activeRound = minigames.WarGames.GetCurrentRoundVehicle() end)
    end
    if not activeRound and minigames.WarGames and minigames.WarGames.GetSelectedVehicle then
        direct_call(function() activeRound = minigames.WarGames.GetSelectedVehicle() end)
    end
    if minigames.GetVehicleLabelByIndex then
        direct_call(function()
            previousLabel = minigames.GetVehicleLabelByIndex(
                minigames.S.previousRoundVehicleIndex or minigames.S.roundVehicleIndex or 1
            ) or 'None'
        end)
    end
    return activeRound, previousLabel
end

