embedded_modules['systems\\v186_games_favorites_apocalypse.lua'] = function()
-- minigames v0.186-alpha
-- games hub, favorites, wargames status polish, beast construction state,
-- and optional purge apocalypse traffic.

minigames.S = minigames.S or {}
minigames.UIX = minigames.UIX or {}
minigames.PurgeGame = minigames.PurgeGame or {}
minigames.PurgeUI = minigames.PurgeUI or {}

local UI = minigames.UIX
local G = minigames.PurgeGame
local P = minigames.PurgeUI
local BUILD = 'v0.189-alpha'

-- ============================================================
-- persistent favorites
-- ============================================================
minigames.GameFavorites = minigames.GameFavorites or {
    wargames = true,
    purge = false,
    landonit = false,
    beast = false
}

local FAVORITE_ORDER = { 'wargames', 'purge', 'landonit', 'beast' }
local FAVORITE_LABELS = {
    wargames = 'WarGames',
    purge = 'The Purge',
    landonit = 'Land On It',
    beast = 'Beast'
}

local function favorites_path()
    return tostring(minigames.ROOT or ((os.getenv('USERPROFILE') or '.') .. '\\Documents\\Cherax\\Lua\\Minigames')) .. '\\favorites.ini'
end

local function save_favorites()
    if FileMgr and FileMgr.CreateDir and minigames.ROOT then direct_call(FileMgr.CreateDir, minigames.ROOT) end
    local lines = {}
    for _, key in ipairs(FAVORITE_ORDER) do
        lines[#lines + 1] = tostring(key) .. '=' .. tostring(minigames.GameFavorites[key] == true)
    end
    if FileMgr and FileMgr.WriteFileContent then
        local content = table.concat(lines, '\n')
        local ok = direct_call(FileMgr.WriteFileContent, favorites_path(), content, false)
        if not ok then direct_call(FileMgr.WriteFileContent, favorites_path(), content) end
    end
end

local function load_favorites()
    if not FileMgr or not FileMgr.DoesFileExist or not FileMgr.ReadFileContent then return end
    local exists = false
    direct_call(function() exists = FileMgr.DoesFileExist(favorites_path()) == true end)
    if not exists then return end
    local raw = nil
    direct_call(function() raw = FileMgr.ReadFileContent(favorites_path()) end)
    if type(raw) ~= 'string' then return end
    for line in raw:gmatch('[^\r\n]+') do
        local key, value = line:match('^([^=]+)=(.*)$')
        if key and FAVORITE_LABELS[key] then minigames.GameFavorites[key] = value == 'true' end
    end
end

load_favorites()

local function render_favorite_toggle(key)
    if not ImGui or not ImGui.Checkbox then return end
    local current = minigames.GameFavorites[key] == true
    local ok, value, changed = direct_call(ImGui.Checkbox, 'Favorite##MinigamesFavorite_' .. tostring(key), current)
    if ok and type(value) == 'boolean' and (changed == true or value ~= current) then
        minigames.GameFavorites[key] = value
        save_favorites()
    end
end

local function wargames_online()
    if minigames.S.wargamesSystemsActive == true then return true end
    if minigames.S.wargamesActive == true then return true end
    if minigames.S.warGamesActive == true then return true end
    if minigames.WarGames and minigames.WarGames.S and minigames.WarGames.S.active == true then return true end
    return false
end

local function active_player_count_v186()
    if minigames.GetActivePlayerCount then
        local count = 0
        direct_call(function() count = tonumber(minigames.GetActivePlayerCount()) or 0 end)
        return count
    end
    if Players and Players.Get then
        local list = nil
        direct_call(function() list = Players.Get() end)
        if type(list) == 'table' then return #list end
    end
    return tonumber(minigames.S.activePlayerCount or 0) or 0
end

local function current_vehicle_label_v186()
    if minigames.GetVehicleLabelByIndex then
        local label = nil
        direct_call(function()
            label = minigames.GetVehicleLabelByIndex(minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or 1)
        end)
        if label then return tostring(label) end
    end
    return 'Unknown'
end

local function render_standard_game_header(key, title, subtitle, tone, underConstruction)
    if UI.Text then
        UI.Text(title, tone or 'purple')
        UI.Text(subtitle or '', 'dim', true)
    elseif ImGui and ImGui.Text then
        ImGui.Text(title)
        if subtitle and subtitle ~= '' then ImGui.Text(subtitle) end
    end

    if UI.Child then
        UI.Child(
            'Minigames_GameHeader_v186_' .. tostring(key),
            'Game Options',
            'Adds shortcuts to Home.',
            function()
                render_favorite_toggle(key)
                if underConstruction == true then
                    if UI.Text then UI.Text('THIS SECTION IS UNDER CONSTRUCTION', 'red', true)
                    elseif ImGui and ImGui.TextColored then ImGui.TextColored(1.0, 0.2, 0.2, 1.0, 'THIS SECTION IS UNDER CONSTRUCTION') end
                end
            end,
            tone or 'purple'
        )
    else
        render_favorite_toggle(key)
    end
end

