}
local AT = G.apocalypseTraffic

local TRAFFIC_ENABLE_HASH = 4145109792
local TRAFFIC_VARIETY_HASH = 421893604

local TN = {
    DOES_ENTITY_EXIST = 0x7239B21A38F536BA,
    GET_ENTITY_COORDS = 0x3FEF770D40960D5A,
    IS_ENTITY_DEAD = 0x5F9532F3B5CC2551,
