    GET_PED_IN_VEHICLE_SEAT = 0xBB40DD2270B65366,
    GET_ENTITY_SPEED = 0xD5037BA82E12416F,
    GET_VEHICLE_ESTIMATED_MAX_SPEED = 0x53AF99BAA671CA47,
    SET_VEHICLE_FORWARD_SPEED = 0xAB54A438726D25D5,
