    SET_PED_COMBAT_ABILITY = 0xC7622C0D36B2FDA8,
    SET_PED_COMBAT_RANGE = 0x3C606747B23E497B,
    SET_PED_FLEE_ATTRIBUTES = 0x70A2D1137C8ED7C9,
    SET_PED_KEEP_TASK = 0x971D38760FBC02EF
}

local function at_now()
    if minigames.Now then
        local ok, value = direct_call(minigames.Now)
        if ok and value then return tonumber(value) or 0 end
    end
    if Time and Time.GetEpocheMs then
        local ok, value = direct_call(Time.GetEpocheMs)
        if ok and value then return tonumber(value) or 0 end
    end
    return math.floor((os.clock() or 0) * 1000)
end

local function at_log(message)
    if minigames.LogInfo then minigames.LogInfo('[The Purge] [Traffic] ' .. tostring(message)) end
end

local function at_error(message)
    if minigames.LogError then minigames.LogError('[The Purge] [Traffic] ' .. tostring(message)) end
end

local function normalize(value)
    return tostring(value or ''):lower():gsub('[^%w]+', '')
end

local function get_feature(hash, name)
    if not FeatureMgr then return nil end
    local feature = nil
    if FeatureMgr.GetFeatureByHash then direct_call(function() feature = FeatureMgr.GetFeatureByHash(hash) end) end
    if not feature and FeatureMgr.GetFeature then direct_call(function() feature = FeatureMgr.GetFeature(hash) end) end
    if not feature and name and FeatureMgr.GetFeatureByName then direct_call(function() feature = FeatureMgr.GetFeatureByName(name) end) end
    return feature
end

local function read_toggle(feature)
    if not feature then return nil end
    local value = nil
    direct_call(function()
        if feature.IsToggled then value = feature:IsToggled()
        elseif feature.GetBoolValue then value = feature:GetBoolValue() end
    end)
    return value
end

local function set_toggle(feature, desired)
    if not feature then return false end
    desired = desired == true
    local current = read_toggle(feature)
    if current == desired then return true end
    local ok = false
    if feature.Toggle then
        direct_call(function() feature:Toggle(desired) end)
        ok = read_toggle(feature) == desired
        if not ok then
            direct_call(function() feature:Toggle() end)
            ok = read_toggle(feature) == desired
        end
    end
    if not ok and feature.SetBoolValue then
        direct_call(function() feature:SetBoolValue(desired) end)
        if feature.TriggerCallback then direct_call(function() feature:TriggerCallback() end) end
        ok = read_toggle(feature) == desired
    end
    if not ok and feature.SetValue then
        direct_call(function() feature:SetValue(desired) end)
        if feature.TriggerCallback then direct_call(function() feature:TriggerCallback() end) end
        ok = read_toggle(feature) == desired
    end
    return ok
end

local function get_feature_list(feature)
    local list = nil
    if feature and feature.GetList then direct_call(function() list = feature:GetList() end) end
    return type(list) == 'table' and list or nil
end

local function find_list_index(feature, wanted)
    local list = get_feature_list(feature)
    if not list then return nil end
    local target = normalize(wanted)
    for i, value in ipairs(list) do
        if normalize(value) == target then return i - 1 end
    end
    for i, value in ipairs(list) do
        local cur = normalize(value)
        if cur:find(target, 1, true) or target:find(cur, 1, true) then return i - 1 end
    end
    return nil
end

local function read_combo_toggles(feature)
    local list = get_feature_list(feature)
    if not feature or not list or not feature.IsListIndexToggled then return nil end
    local state = { toggles = {}, count = #list }
    for index = 0, #list - 1 do
        local value = false
        direct_call(function() value = feature:IsListIndexToggled(index) == true end)
        state.toggles[index] = value
    end
    return state
end

local function restore_combo_toggles(feature, state)
    if not feature or not state or not feature.ToggleListIndex then return false end
    local list = get_feature_list(feature)
    if not list then return false end
    local okay = true
    for index = 0, #list - 1 do
        local desired = state.toggles and state.toggles[index] == true or false
        local current = false
        if feature.IsListIndexToggled then direct_call(function() current = feature:IsListIndexToggled(index) == true end) end
        if current ~= desired then
            local ok = direct_call(function() feature:ToggleListIndex(index, desired) end)
            if not ok then okay = false end
        end
    end
    if feature.TriggerCallback then direct_call(function() feature:TriggerCallback() end) end
    return okay
end

local function capture_traffic_backup()
    if AT.backupReady == true and AT.backup then return true end
    local enableFeature = get_feature(TRAFFIC_ENABLE_HASH, 'Enable Custom Traffic Variety')
    local varietyFeature = get_feature(TRAFFIC_VARIETY_HASH, 'Variety Selection')
    local enableState = read_toggle(enableFeature)
    local varietyState = read_combo_toggles(varietyFeature)
    AT.backup = {
        enableFeature = enableFeature,
        enableState = enableState,
        varietyFeature = varietyFeature,
        varietyState = varietyState
    }
    AT.backupReady = enableFeature ~= nil and enableState ~= nil
    if AT.backupReady then
        AT.backupStatus = varietyState and 'Custom Traffic Variety and category selections backed up' or 'Custom Traffic Variety backed up; category selector unavailable'
    else
        AT.backupStatus = 'Cherax Custom Traffic Variety feature unavailable'
    end
    return AT.backupReady
end

local function set_traffic_categories(feature)
    if not feature then return false, 'Variety Selection missing' end
    if not feature.ToggleListIndex then return false, 'Variety Selection is not ComboToggles on this build' end
    local list = get_feature_list(feature)
    if not list or #list == 0 then return false, 'Traffic variety list unavailable' end
    local changed, enabledCount = 0, 0
    for index, label in ipairs(list) do
        local normalized = normalize(label)
        if normalized ~= 'none' and normalized ~= 'off' and normalized ~= 'disabled' then
            local zero = index - 1
            local current = false
            if feature.IsListIndexToggled then direct_call(function() current = feature:IsListIndexToggled(zero) == true end) end
            if current ~= true then
                local ok = direct_call(function() feature:ToggleListIndex(zero, true) end)
                if ok then changed = changed + 1 end
            end
            enabledCount = enabledCount + 1
        end
    end
    if feature.TriggerCallback then direct_call(function() feature:TriggerCallback() end) end
    return enabledCount > 0, 'All traffic families enabled (' .. tostring(enabledCount) .. '), including Emergency + Military'
end

local function clear_purge_traffic_categories(feature)
    if not feature or not feature.ToggleListIndex then return true end
    local okay = true
    local list = get_feature_list(feature) or {}
    for index = 0, #list - 1 do
        local current = false
        if feature.IsListIndexToggled then direct_call(function() current = feature:IsListIndexToggled(index) == true end) end
        if current == true then
            local ok = direct_call(function() feature:ToggleListIndex(index, false) end)
            if not ok then okay = false end
        end
    end
    if feature.TriggerCallback then direct_call(function() feature:TriggerCallback() end) end
    return okay
end

local function apply_builtin_traffic()
    capture_traffic_backup()
    local backup = AT.backup or {}
    local enabled = false
    if backup.enableFeature then enabled = set_toggle(backup.enableFeature, true) end
    local categoriesOk, categoriesStatus = set_traffic_categories(backup.varietyFeature)
    AT.builtInApplied = enabled or categoriesOk
    if enabled and categoriesOk then
        AT.builtInStatus = 'Custom Traffic Variety ON | full traffic pool ON (Emergency + Military included)'
    elseif enabled then
        AT.builtInStatus = 'Custom Traffic Variety ON | ' .. tostring(categoriesStatus)
    else
        AT.builtInStatus = 'Cherax traffic feature unavailable; native apocalypse traffic still active'
    end
    at_log('Built-in traffic apply | ' .. tostring(AT.builtInStatus))
    return AT.builtInApplied
end

local function restore_builtin_traffic()
    -- v0.187 intentionally does not restore a previously-enabled custom traffic
    -- variety state. the requested post-purge baseline is always traffic variety off.
    local backup = AT.backup or {}
    local enableFeature = backup.enableFeature or get_feature(TRAFFIC_ENABLE_HASH, 'Enable Custom Traffic Variety')
    local varietyFeature = backup.varietyFeature or get_feature(TRAFFIC_VARIETY_HASH, 'Variety Selection')
    local okay = true
    if varietyFeature and not clear_purge_traffic_categories(varietyFeature) then okay = false end
    if enableFeature and not set_toggle(enableFeature, false) then okay = false end
    AT.builtInApplied = false
    AT.builtInStatus = okay and 'Custom Traffic Variety OFF | traffic categories cleared' or 'Traffic shutdown completed with one or more failures'
    -- force a fresh capture before a future purge. that next baseline should now
    -- observe the off state established here.
    AT.backup = nil
    AT.backupReady = false
    AT.backupStatus = 'Reset after Purge; fresh OFF baseline pending'
    return okay
end

local function entity_exists(entity)
    if not entity or entity == 0 or not Natives or not Natives.InvokeBool then return false end
    local ok, value = direct_call(Natives.InvokeBool, TN.DOES_ENTITY_EXIST, entity)
    return ok and value == true
end

local function is_player_ped(ped)
    if not ped or ped == 0 or not Natives or not Natives.InvokeBool then return false end
    local ok, value = direct_call(Natives.InvokeBool, TN.IS_PED_A_PLAYER, ped)
    return ok and value == true
end

local function entity_coords(entity)
    if not Natives or not Natives.InvokeV3 then return nil end

    -- cherax invokev3 normally returns x, y, z as three numeric values. some
    -- builds/wrappers can expose a vector-like table instead, so support both.
    local ok, a, b, c = direct_call(function()
        return Natives.InvokeV3(TN.GET_ENTITY_COORDS, entity, true)
    end)
    if not ok or a == nil then return nil end

    if type(a) == "number" then
        return {
            x = tonumber(a) or 0,
            y = tonumber(b) or 0,
            z = tonumber(c) or 0,
        }
    end

    if type(a) == "table" then
        return {
            x = tonumber(a.x or a.X or a[1] or 0) or 0,
            y = tonumber(a.y or a.Y or a[2] or 0) or 0,
            z = tonumber(a.z or a.Z or a[3] or 0) or 0,
        }
    end

    return nil
end

local function distance_between(a, b)
    if not a or not b then return 999999 end
    local dx, dy, dz = a.x - b.x, a.y - b.y, a.z - b.z
    return math.sqrt(dx * dx + dy * dy + dz * dz)
end

local function get_local_ped()
    local localId = minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or 0
    if minigames.GetPlayerPed then
        local ped = 0
        direct_call(function() ped = minigames.GetPlayerPed(localId) or 0 end)
        return ped
    end
    return 0
end

local function player_vehicle_set()
    local set = {}
    if not Natives or not Natives.InvokeInt then return set end
    for playerId = 0, 31 do
        local active = false
        if minigames.IsPlayerActive then direct_call(function() active = minigames.IsPlayerActive(playerId) == true end) end
        if active and minigames.GetPlayerPed then
            local ped = 0
            direct_call(function() ped = minigames.GetPlayerPed(playerId) or 0 end)
            if ped ~= 0 then
                local vehicle = 0
                direct_call(function() vehicle = Natives.InvokeInt(TN.GET_VEHICLE_PED_IS_IN, ped, false) or 0 end)
                if vehicle ~= 0 then set[vehicle] = true end
            end
        end
    end
    return set
end

local function request_control(entity)
    if not Natives or not Natives.InvokeBool then return true end
    local has = false
    direct_call(function() has = Natives.InvokeBool(TN.NETWORK_HAS_CONTROL_OF_ENTITY, entity) == true end)
    if has then return true end
    direct_call(function() Natives.InvokeBool(TN.NETWORK_REQUEST_CONTROL_OF_ENTITY, entity) end)
    direct_call(function() has = Natives.InvokeBool(TN.NETWORK_HAS_CONTROL_OF_ENTITY, entity) == true end)
    return has
end

local function all_vehicles(maxItems)
    local out = {}
    if not PoolMgr or not PoolMgr.GetVehicle then return out end
    local count = 0
    if PoolMgr.GetMaxVehicleCount then
        direct_call(function() count = math.max(0, tonumber(PoolMgr.GetMaxVehicleCount()) or 0) end)
    elseif PoolMgr.GetCurrentVehicleCount then
        direct_call(function() count = math.max(0, tonumber(PoolMgr.GetCurrentVehicleCount()) or 0) end)
    end
    local limit = math.min(math.max(0, count - 1), 255)
    for index = 0, limit do
        local vehicle = nil
        direct_call(function() vehicle = PoolMgr.GetVehicle(index) end)
        if vehicle and vehicle ~= 0 then
            out[#out + 1] = vehicle
            if #out >= (maxItems or 90) then break end
        end
    end
    return out
end

local function all_peds(maxItems)
    local out = {}
    if not PoolMgr or not PoolMgr.GetPed then return out end
    local count = 0
    if PoolMgr.GetMaxPedCount then
        direct_call(function() count = math.max(0, tonumber(PoolMgr.GetMaxPedCount()) or 0) end)
    elseif PoolMgr.GetCurrentPedCount then
        direct_call(function() count = math.max(0, tonumber(PoolMgr.GetCurrentPedCount()) or 0) end)
    end
    local limit = math.min(math.max(0, count - 1), 255)
    for index = 0, limit do
        local ped = nil
        direct_call(function() ped = PoolMgr.GetPed(index) end)
        if ped and ped ~= 0 then
            out[#out + 1] = ped
            if #out >= (maxItems or 120) then break end
        end
    end
    return out
end

local function restore_native_traffic_effects()
    if Natives and Natives.InvokeVoid then
        for vehicle in pairs(AT.fireVehicles or {}) do
            if entity_exists(vehicle) then direct_call(function() Natives.InvokeVoid(TN.STOP_ENTITY_FIRE, vehicle) end) end
        end
        for vehicle, originalHealth in pairs(AT.smokeVehicles or {}) do
            if entity_exists(vehicle) and originalHealth ~= nil then
                direct_call(function() Natives.InvokeVoid(TN.SET_VEHICLE_ENGINE_HEALTH, vehicle, tonumber(originalHealth) or 1000.0) end)
            end
        end
    end
    AT.vehiclesSeen = {}
    AT.smokeVehicles = {}
    AT.fireVehicles = {}
    AT.lastVehicleCount = 0
    AT.lastRiotCount = 0
end

local function process_crazy_traffic(now)
    if now < (AT.lastVehicleTickMs or 0) + 1000 then return end
    AT.lastVehicleTickMs = now
    if not Natives or not Natives.InvokeInt or not Natives.InvokeVoid or not Natives.InvokeFloat then return end

    local localPed = get_local_ped()
    local localPos = entity_exists(localPed) and entity_coords(localPed) or nil
    local occupiedByPlayers = player_vehicle_set()
    local processed = 0

    for _, vehicle in ipairs(all_vehicles(90)) do
        if processed >= 55 then break end
        if entity_exists(vehicle) and not occupiedByPlayers[vehicle] then
            local pos = localPos and entity_coords(vehicle) or nil
            if not localPos or distance_between(localPos, pos) <= 325.0 then
                local driver = 0
                direct_call(function() driver = Natives.InvokeInt(TN.GET_PED_IN_VEHICLE_SEAT, vehicle, -1, false) or 0 end)
                if driver ~= 0 and entity_exists(driver) and not is_player_ped(driver) and request_control(vehicle) then
                    processed = processed + 1
                    local maxSpeed = 42.0
                    direct_call(function() maxSpeed = tonumber(Natives.InvokeFloat(TN.GET_VEHICLE_ESTIMATED_MAX_SPEED, vehicle)) or maxSpeed end)
                    maxSpeed = math.max(32.0, math.min(90.0, maxSpeed))

                    -- aggressive wander plus cruise speed keeps npc drivers moving at
                    -- roughly the vehicle's own estimated top speed instead of using
                    -- one unrealistic fixed speed for every model.
                    direct_call(function() Natives.InvokeVoid(TN.TASK_VEHICLE_DRIVE_WANDER, driver, vehicle, maxSpeed, 1074528293) end)
                    direct_call(function() Natives.InvokeVoid(TN.SET_DRIVE_TASK_CRUISE_SPEED, driver, maxSpeed) end)
                    direct_call(function() Natives.InvokeVoid(TN.SET_PED_KEEP_TASK, driver, true) end)

                    local speed = 0.0
                    direct_call(function() speed = tonumber(Natives.InvokeFloat(TN.GET_ENTITY_SPEED, vehicle)) or 0.0 end)
                    if speed < maxSpeed * 0.72 then
                        direct_call(function() Natives.InvokeVoid(TN.SET_VEHICLE_FORWARD_SPEED, vehicle, maxSpeed * 0.92) end)
                    end

                    if not AT.vehiclesSeen[vehicle] then
                        AT.vehiclesSeen[vehicle] = now
                        local roll = math.random(1, 1000)
                        if roll <= 18 then
                            direct_call(function() Natives.InvokeInt(TN.START_ENTITY_FIRE, vehicle) end)
                            AT.fireVehicles[vehicle] = true
                        elseif roll <= 95 then
                            local originalHealth = nil
                            direct_call(function() originalHealth = tonumber(Natives.InvokeFloat(TN.GET_VEHICLE_ENGINE_HEALTH, vehicle)) end)
                            if originalHealth and originalHealth > 375.0 then
                                AT.smokeVehicles[vehicle] = originalHealth
                                direct_call(function() Natives.InvokeVoid(TN.SET_VEHICLE_ENGINE_HEALTH, vehicle, 350.0) end)
                            end
                        end
                    end
                end
            end
        end
    end
    AT.lastVehicleCount = processed
end

local function ped_is_usable(ped, localPos)
    if not ped or ped == 0 or not entity_exists(ped) or is_player_ped(ped) then return false end
    local dead = false
    if Natives and Natives.InvokeBool then direct_call(function() dead = Natives.InvokeBool(TN.IS_ENTITY_DEAD, ped, false) == true end) end
    if dead then return false end
    local inVehicle = false
    if Natives and Natives.InvokeBool then direct_call(function() inVehicle = Natives.InvokeBool(TN.IS_PED_IN_ANY_VEHICLE, ped, true) == true end) end
    if inVehicle then return false end
    if localPos then
        local pos = entity_coords(ped)
        if distance_between(localPos, pos) > 175.0 then return false end
    end
    return true
end

local function make_ped_fight(attacker, target)
    if not attacker or not target or attacker == target or not Natives or not Natives.InvokeVoid then return false end
    if not request_control(attacker) then return false end
    direct_call(function() Natives.InvokeVoid(TN.SET_PED_FLEE_ATTRIBUTES, attacker, 0, false) end)
    direct_call(function() Natives.InvokeVoid(TN.SET_PED_COMBAT_ABILITY, attacker, 2) end)
    direct_call(function() Natives.InvokeVoid(TN.SET_PED_COMBAT_RANGE, attacker, 2) end)
    direct_call(function() Natives.InvokeVoid(TN.SET_PED_KEEP_TASK, attacker, true) end)
    local ok = direct_call(function() Natives.InvokeVoid(TN.TASK_COMBAT_PED, attacker, target, 0, 16) end)
    return ok
end

local function process_ped_riot(now)
    if now < (AT.lastPedTickMs or 0) + 2500 then return end
    AT.lastPedTickMs = now

    local localPed = get_local_ped()
    local localPos = entity_exists(localPed) and entity_coords(localPed) or nil
    local candidates = {}
    for _, ped in ipairs(all_peds(120)) do
        if ped_is_usable(ped, localPos) then candidates[#candidates + 1] = ped end
        if #candidates >= 42 then break end
    end

    if #candidates < 2 then AT.lastRiotCount = 0 return end

    local tasks = 0
    local maxTasks = math.min(6, math.floor(#candidates / 2))
    for i = 1, maxTasks do
        local attacker = candidates[math.random(1, #candidates)]
        local target = candidates[math.random(1, #candidates)]
        local attempts = 0
        while target == attacker and attempts < 6 do
            target = candidates[math.random(1, #candidates)]
            attempts = attempts + 1
        end
        if attacker ~= target and make_ped_fight(attacker, target) then tasks = tasks + 1 end
    end

    -- very rare san andreas-style moment where one ambient pedestrian chooses
    -- the local player. the cooldown keeps this from becoming constant harassment.
    if localPed ~= 0 and entity_exists(localPed) and now >= (AT.nextLocalPedAttackMs or 0) then
        if math.random(1, 1000) <= 5 then
            local attacker = candidates[math.random(1, #candidates)]
            if make_ped_fight(attacker, localPed) then
                AT.nextLocalPedAttackMs = now + 120000
                at_log('Rare civilian aggression triggered toward local player')
            end
        end
    end

    AT.lastRiotCount = tasks
end

function G.ApplyApocalypseTraffic(reason)
    if G.run and G.run.active ~= true then
        AT.status = 'Ready. Starts with The Purge.'
        return false
    end
    local mode = G.run and tostring(G.run.mode or '') or ''
    if mode ~= 'preparing' and mode ~= 'hunt' then
        AT.status = 'Ready for the next Purge hunt.'
        return false
    end
    if G.config.apocalypseTraffic ~= true then return false end
    if AT.active == true then return true end

    capture_traffic_backup()
    apply_builtin_traffic()
    AT.active = true
    AT.status = 'ACTIVE | max-speed traffic | Emergency + Military | fires + smoke | civilian riot'
    AT.lastVehicleTickMs = 0
    AT.lastPedTickMs = 0
    AT.nextLocalPedAttackMs = at_now() + 90000
    at_log('Apocalypse Traffic enabled | reason=' .. tostring(reason or 'Purge active'))
    return true
end

function G.StopApocalypseTraffic(reason)
    -- always enforce the requested post-purge baseline even if the native chaos
    -- layer was already inactive. this guarantees custom traffic variety is off.
    AT.active = false
    restore_native_traffic_effects()
    local restored = restore_builtin_traffic()
    AT.status = restored and 'Disabled | Custom Traffic Variety forced OFF' or 'Disabled | Traffic Variety shutdown completed with errors'
    at_log('Apocalypse Traffic stopped | reason=' .. tostring(reason or 'Purge ended') .. ' | restored=' .. tostring(restored))
    return restored
end

function G.SetApocalypseTrafficEnabled(enabled, reason)
    G.config.apocalypseTraffic = enabled == true
    local path = tostring(minigames.ROOT or ((os.getenv('USERPROFILE') or '.') .. '\\Documents\\Cherax\\Lua\\Minigames')) .. '\\Purge\\apocalypse.ini'
    if FileMgr and FileMgr.CreateDir then
        direct_call(FileMgr.CreateDir, tostring(minigames.ROOT or '.') .. '\\Purge')
    end
    if FileMgr and FileMgr.WriteFileContent then
        local content = 'Enabled=' .. tostring(G.config.apocalypseTraffic == true)
        local ok = direct_call(FileMgr.WriteFileContent, path, content, false)
        if not ok then direct_call(FileMgr.WriteFileContent, path, content) end
    end

    if G.run and G.run.active == true then
        if G.config.apocalypseTraffic == true then return G.ApplyApocalypseTraffic(reason or 'live toggle')
        else return G.StopApocalypseTraffic(reason or 'live toggle') end
    end
    AT.status = G.config.apocalypseTraffic and 'Enabled for next Purge' or 'Disabled'
    return true
end

local function load_apocalypse_setting()
    local path = tostring(minigames.ROOT or ((os.getenv('USERPROFILE') or '.') .. '\\Documents\\Cherax\\Lua\\Minigames')) .. '\\Purge\\apocalypse.ini'
    if not FileMgr or not FileMgr.DoesFileExist or not FileMgr.ReadFileContent then return end
    local exists = false
    direct_call(function() exists = FileMgr.DoesFileExist(path) == true end)
    if not exists then return end
    local raw = nil
    direct_call(function() raw = FileMgr.ReadFileContent(path) end)
    if type(raw) == 'string' then
        local value = raw:match('Enabled=([^\r\n]+)')
        if value ~= nil then G.config.apocalypseTraffic = value == 'true' end
    end
end

load_apocalypse_setting()
AT.status = G.config.apocalypseTraffic and 'Enabled for next Purge' or 'Disabled'

function G.TickApocalypseTraffic()
    local runActive = G.run and G.run.active == true
    local runMode = G.run and tostring(G.run.mode or '') or ''
    local huntPhase = runMode == 'preparing' or runMode == 'hunt'
    if not runActive or not huntPhase or G.config.apocalypseTraffic ~= true then
        if AT.active == true or AT.builtInApplied == true then G.StopApocalypseTraffic('Purge hunt inactive, completed, or Traffic toggle off') end
        return
    end
    if AT.active ~= true then G.ApplyApocalypseTraffic('Purge runtime guard') end
    if AT.active ~= true then return end
    local now = at_now()
    process_crazy_traffic(now)
    process_ped_riot(now)
end

-- wrap the current purge lifecycle rather than changing the proven v0.185 hunt logic.
local previousApplyPreset = G.ApplyPurgePreset
if previousApplyPreset then
    function G.ApplyPurgePreset(...)
        local result = previousApplyPreset(...)
        if result == true and G.config.apocalypseTraffic == true then
            direct_call(function() G.ApplyApocalypseTraffic('Purge preset applied') end)
        end
        return result
    end
end

local previousRestorePreset = G.RestorePurgePreset
if previousRestorePreset then
    function G.RestorePurgePreset(reason)
        direct_call(function() G.StopApocalypseTraffic(reason or 'Purge restore') end)
        return previousRestorePreset(reason)
    end
end

local previousPurgeTick = G.Tick
if previousPurgeTick then
    function G.Tick(...)
        local result = previousPurgeTick(...)
        local ok, err = direct_call(G.TickApocalypseTraffic)
        if not ok then
            local now = at_now()
            local last = tonumber(minigames.S.apocalypseTrafficLastErrorLogMsV194 or 0) or 0
            if last == 0 or now - last >= 5000 then
                minigames.S.apocalypseTrafficLastErrorLogMsV194 = now
                at_error('Apocalypse Traffic tick failed | ' .. tostring(err))
            end
        end
        return result
    end
end

-- capture the traffic settings after the main script finishes booting, but also
-- capture on demand before the first purge if the feature tree initializes late.
if Script and Script.QueueJob then
    Script.QueueJob(function()
        if Script.Yield then Script.Yield(500) end
        for attempt = 1, 5 do
            if capture_traffic_backup() then break end
            if Script.Yield then Script.Yield(500) end
        end
        at_log('Traffic backup | ' .. tostring(AT.backupStatus))
    end)
else
    capture_traffic_backup()
end

-- ============================================================
-- shared game layout and ui
-- ============================================================
local function get_wargames_context_v186()
    local activeRound = nil
    local previousLabel = 'None'
    if minigames.WarGames and minigames.WarGames.RefreshWarGamesUiSettings then direct_call(minigames.WarGames.RefreshWarGamesUiSettings) end
    if minigames.WarGames and minigames.WarGames.GetCurrentRoundVehicle then direct_call(function() activeRound = minigames.WarGames.GetCurrentRoundVehicle() end) end
    if not activeRound and minigames.WarGames and minigames.WarGames.GetSelectedVehicle then direct_call(function() activeRound = minigames.WarGames.GetSelectedVehicle() end) end
    if minigames.GetVehicleLabelByIndex then
        direct_call(function()
            previousLabel = minigames.GetVehicleLabelByIndex(minigames.S.previousRoundVehicleIndex or minigames.S.roundVehicleIndex or 1) or 'None'
        end)
    end
    return activeRound, previousLabel
end

local function render_wargames_status_v186(activeRound, previousLabel)
    if not UI.Child then return end
    if not wargames_online() then
        UI.Child(
            'Minigames_WarGamesStatus_v186_offline',
            'WarGames Status',
            'Systems are offline.',
            function()
                if UI.StatusRow then UI.StatusRow('Systems', 'OFFLINE', 'red') end
                if UI.Text then UI.Text('Start WarGames for live status.', 'dim', true) end
            end,
            'red'
        )
        return
    end

    UI.Child(
        'Minigames_WarGamesStatus_v186_live',
        'Live WarGames Status',
        'Systems online.',
        function()
            if not UI.StatusRow then return end
            local selectedVehicle = current_vehicle_label_v186()
            if activeRound and type(activeRound) == 'table' then
                selectedVehicle = activeRound.label or activeRound.name or activeRound.model or selectedVehicle
            elseif type(activeRound) == 'string' and activeRound ~= '' then
                selectedVehicle = activeRound
            end
            UI.StatusRow('Systems', 'ONLINE', 'green')
            UI.StatusRow('Selected Vehicle', selectedVehicle, 'gold')
            UI.StatusRow('Previous Round', previousLabel or 'None', 'dim')
            UI.StatusRow('Tracked Vehicles', #(minigames.S.spawnedWarGamesVehicles or {}), 'cyan')
            UI.StatusRow('Players', active_player_count_v186(), 'green')
            UI.StatusRow('Respawn Watcher', minigames.S.respawnWatcherRunning == true and 'ON' or 'OFF', minigames.S.respawnWatcherRunning == true and 'green' or 'dim')
            UI.StatusRow('Last Bounty', minigames.S.lastBountyStatus or 'None', 'white')
        end,
        'red'
    )
end

function UI.RenderWarGames()
    local activeRound, previousLabel = get_wargames_context_v186()
    render_standard_game_header('wargames', 'WARGAMES', 'Vehicle rounds, bounties, respawns.', 'red', false)
    render_wargames_status_v186(activeRound, previousLabel)

    if ImGui and ImGui.BeginTabBar and ImGui.BeginTabItem then
        local opened = false
        direct_call(function() opened = ImGui.BeginTabBar('Minigames_WarGames_Subtabs_v186') end)
        if opened then
            if ImGui.BeginTabItem('Overview') then
                minigames.S.uiWarGamesPageV169 = 0
                if minigames.WarGames and minigames.WarGames.RenderMainTab then minigames.WarGames.RenderMainTab(activeRound, previousLabel) end
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem('Vehicles') then
                minigames.S.uiWarGamesPageV169 = 1
                if minigames.WarGames and minigames.WarGames.RenderVehiclesTab then minigames.WarGames.RenderVehiclesTab(activeRound, previousLabel) end
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem('Bounties') then
                minigames.S.uiWarGamesPageV169 = 2
                if minigames.WarGames and minigames.WarGames.RenderBountiesTab then minigames.WarGames.RenderBountiesTab() end
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem('Teleports') then
                minigames.S.uiWarGamesPageV169 = 3
                if minigames.WarGames and minigames.WarGames.RenderTeleportsTab then minigames.WarGames.RenderTeleportsTab() end
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem('Infantry') then
                minigames.S.uiWarGamesPageV169 = 4
                if minigames.WarGames and minigames.WarGames.RenderInfantryTab then minigames.WarGames.RenderInfantryTab() end
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem('Cleanup') then
                minigames.S.uiWarGamesPageV169 = 5
                if minigames.WarGames and minigames.WarGames.RenderCleanupFairnessTab then minigames.WarGames.RenderCleanupFairnessTab() end
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem('Perks') then
                minigames.S.uiWarGamesPageV169 = 6
                if minigames.WarGames and minigames.WarGames.RenderPerksTab then minigames.WarGames.RenderPerksTab() end
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem('Diagnostics') then
                minigames.S.uiWarGamesPageV169 = 7
                if minigames.WarGames and minigames.WarGames.RenderDebugTab then minigames.WarGames.RenderDebugTab() end
                ImGui.EndTabItem()
            end
            ImGui.EndTabBar()
        elseif minigames.WarGames and minigames.WarGames.RenderMainTab then
            minigames.WarGames.RenderMainTab(activeRound, previousLabel)
        end
    elseif minigames.WarGames and minigames.WarGames.RenderMainTab then
        minigames.WarGames.RenderMainTab(activeRound, previousLabel)
    end
end

local function render_purge_traffic_panel()
    if not UI.Child then return end
    UI.Child(
        'Minigames_PurgeTraffic_v186',
        'Apocalypse Traffic',
        'Optional apocalypse traffic.',
        function()
            if ImGui and ImGui.Checkbox then
                local old = G.config.apocalypseTraffic == true
                local ok, value, changed = direct_call(ImGui.Checkbox, 'Traffic##MinigamesPurgeApocalypseTrafficV186', old)
                if ok and type(value) == 'boolean' and (changed == true or value ~= old) then
                    G.SetApocalypseTrafficEnabled(value, 'Purge Traffic checkbox')
                end
            end
            if UI.StatusRow then
                UI.StatusRow('Traffic', G.config.apocalypseTraffic == true and 'ENABLED' or 'OFF', G.config.apocalypseTraffic == true and 'red' or 'dim')
                UI.StatusRow('Custom Traffic Variety', AT.builtInApplied == true and 'ON' or (G.config.apocalypseTraffic == true and 'ON WHEN PURGE STARTS' or 'OFF'), AT.builtInApplied == true and 'green' or 'dim')
                UI.StatusRow('Variety', G.config.apocalypseTraffic == true and 'EMERGENCY + MILITARY' or 'OFF', G.config.apocalypseTraffic == true and 'gold' or 'dim')
                UI.StatusRow('Traffic Flow', G.config.apocalypseTraffic == true and 'PANIC + COASTING WRECKS' or 'NORMAL', G.config.apocalypseTraffic == true and 'red' or 'dim')
                UI.StatusRow('Wrecks', G.config.apocalypseTraffic == true and 'DAMAGE + FIRE + RARE EXPLOSIONS' or 'OFF', G.config.apocalypseTraffic == true and 'orange' or 'dim')
                UI.StatusRow('Pedestrians', G.config.apocalypseTraffic == true and 'MOSTLY FLEEING + RARE FIGHTS' or 'OFF', G.config.apocalypseTraffic == true and 'red' or 'dim')
            end
            if UI.Text then
                UI.Text('WorldZ ambience: runners, wrecks, one RPG survivor, rare local aggression.', 'dim', true)
                UI.Text('Traffic Variety returns OFF when The Purge ends.', 'dim', true)
                if G.config.apocalypseTraffic == true then UI.Text('Status: ' .. tostring(AT.status), 'white', true) end
                if G.config.apocalypseTraffic == true then UI.Text('Cherax: ' .. tostring(AT.builtInStatus), 'white', true) end
            end
        end,
        'red'
    )
end

function UI.RenderPurgeGame()
