                if UI.StatusRow then
                    UI.StatusRow('Systems', G.run and G.run.active == true and 'ONLINE' or 'OFFLINE', G.run and G.run.active == true and 'green' or 'dim')
                    UI.StatusRow('Scope', 'LOS SANTOS CITY SWEEP', 'gold')
                    UI.StatusRow('Target', G.run and G.run.targetName or 'None', 'red')
                    UI.StatusRow('Hardcore', G.run and G.run.active == true and G.run.mode ~= 'hour' and 'MINIMAP OFF' or 'MINIMAP NORMAL', G.run and G.run.active == true and G.run.mode ~= 'hour' and 'red' or 'green')
                    UI.StatusRow('Flash Hint', '5 MIN / 15 SEC / 3 SEC PULSE', 'purple')
