function UI.RenderFavoriteGameShortcuts()
    local shown = 0
    for _, key in ipairs(FAVORITE_ORDER) do if minigames.GameFavorites[key] == true then shown = shown + 1 end end
    if shown == 0 then
        if UI.Text then UI.Text('Favorite a game in Games.', 'dim', true) end
        return
    end

    if minigames.GameFavorites.wargames == true then home_wargames_shortcuts() end
    if minigames.GameFavorites.purge == true then
        if UI.Spacing then UI.Spacing(1) end
        home_purge_shortcuts()
    end
    if minigames.GameFavorites.landonit == true then
        if UI.Spacing then UI.Spacing(1) end
        home_landonit_shortcuts()
    end
    if minigames.GameFavorites.beast == true then
        if UI.Spacing then UI.Spacing(1) end
        home_beast_shortcuts()
    end
end

