local function render_favorite_quick_actions_v189()
    local shown = 0

    if minigames.GameFavorites.wargames == true then
        shown = shown + 1
        if UI.Text then UI.Text('WARGAMES', 'red') end
        UI.Button('Next Vehicle Round', 'cyan', quick_next_round_v186, -1, 32)
        UI.Button('Spawn Players Above Me', 'blue', quick_spawn_above_v186)
        if UI.SameLine then UI.SameLine() end
        UI.Button('Spawn At Waypoint', 'cyan', quick_spawn_waypoint_v186)
        UI.Button('Force Spawn Selected', 'purple', quick_spawn_all_v186)
        if UI.SameLine then UI.SameLine() end
        UI.Button('Use Vigilante', 'orange', quick_vigilante_v186)
        UI.Button('Bounties To All', 'gold', quick_bounty_v186)
        if UI.SameLine then UI.SameLine() end
        UI.Button('Cleanup Vehicles', 'red', quick_cleanup_v186)
    end

    if minigames.GameFavorites.purge == true then
        if shown > 0 and UI.Spacing then UI.Spacing(1) end
        shown = shown + 1
        if UI.Text then UI.Text('THE PURGE (BETA)', 'red') end
        if G.run and G.run.active == true then
            UI.Button('Abandon The Purge', 'red', function() if G.Abandon then G.Abandon() end end, -1, 32)
            if tostring(G.run.mode or '') == 'hunt' and G.config.hardcoreHint ~= false then
                UI.Button('Flash Hint', 'purple', function() if G.StartTargetHint then G.StartTargetHint('Home Quick Action') end end)
            end
        else
            UI.Button('Start The Purge', 'red', function() if G.Start then G.Start() end end, -1, 32)
        end
        UI.Button(G.config.apocalypseTraffic == true and 'Traffic: ON' or 'Traffic: OFF', G.config.apocalypseTraffic == true and 'red' or 'dim', function()
            if G.SetApocalypseTrafficEnabled then G.SetApocalypseTrafficEnabled(G.config.apocalypseTraffic ~= true, 'Home Quick Action') end
        end, -1, 30)
    end

    if minigames.GameFavorites.landonit == true then
        if shown > 0 and UI.Spacing then UI.Spacing(1) end
        shown = shown + 1
        if UI.Text then UI.Text('LAND ON IT', 'cyan') end
        if UI.RenderFeature and minigames.LandOnIt and minigames.LandOnIt.H then
            UI.RenderFeature(minigames.LandOnIt.H.ACTIVATE)
            UI.RenderFeature(minigames.LandOnIt.H.TP_RUNWAY)
            UI.RenderFeature(minigames.LandOnIt.H.SPAWN_MK1_ALL)
        end
    end

    if minigames.GameFavorites.beast == true then
        if shown > 0 and UI.Spacing then UI.Spacing(1) end
        shown = shown + 1
        if UI.Text then
            UI.Text('BEAST', 'red')
            UI.Text('UNDER CONSTRUCTION', 'red', true)
        end
    end

    if shown == 0 and UI.Text then
        UI.Text('Favorite a game in Games.', 'dim', true)
    end
end

