-- ============================================================
-- embedded module: systems\ui_clarity_v190.lua
-- ============================================================
embedded_modules['systems\\ui_clarity_v190.lua'] = function()
-- minigames v0.190 ui clarity pass.
-- keeps game controls intact while reducing duplicate panels and long copy.

minigames.S = minigames.S or {}
minigames.UIX = minigames.UIX or {}
minigames.GameFavorites = minigames.GameFavorites or {}
minigames.PurgeGame = minigames.PurgeGame or {}
local UI = minigames.UIX
local G = minigames.PurgeGame
local oldPurgeRenderV190 = G.RenderUI

local TAB_TONES = {
    red = {1.00, 0.26, 0.32, 1.00},
    cyan = {0.42, 0.82, 1.00, 1.00},
    gold = {1.00, 0.78, 0.18, 1.00},
    green = {0.30, 1.00, 0.48, 1.00},
    purple = {0.72, 0.42, 1.00, 1.00},
    orange = {1.00, 0.52, 0.12, 1.00},
    blue = {0.24, 0.52, 0.96, 1.00},
    dim = {0.62, 0.64, 0.72, 1.00},
}

local function push_text_tone(tone)
    if not (ImGui and ImGui.PushStyleColor and ImGuiCol and ImGuiCol.Text) then return 0 end
    local c = TAB_TONES[tone or 'red'] or TAB_TONES.red
    local ok = direct_call(ImGui.PushStyleColor, ImGuiCol.Text, c[1], c[2], c[3], c[4])
    return ok and 1 or 0
end

local function pop_text_tone(count)
    if tonumber(count or 0) > 0 and ImGui and ImGui.PopStyleColor then direct_call(ImGui.PopStyleColor, count) end
end

local function begin_colored_tab(label, tone)
    local pushed = push_text_tone(tone)
    local opened = false
    direct_call(function() opened = ImGui.BeginTabItem(label) == true end)
    pop_text_tone(pushed)
    return opened
end

local function save_favorites_v190()
    local root = tostring(minigames.ROOT or ((os.getenv('USERPROFILE') or '.') .. '\\Documents\\Cherax\\Lua\\Minigames'))
    local path = root .. '\\favorites.ini'
    local order = {'wargames', 'purge', 'landonit', 'beast'}
    local lines = {}
    for _, key in ipairs(order) do lines[#lines + 1] = key .. '=' .. tostring(minigames.GameFavorites[key] == true) end
    if FileMgr and FileMgr.WriteFileContent then
        local body = table.concat(lines, '\n')
        local ok = direct_call(FileMgr.WriteFileContent, path, body, false)
        if not ok then direct_call(FileMgr.WriteFileContent, path, body) end
    else
        local f = io.open(path, 'wb')
        if f then f:write(table.concat(lines, '\n')); f:close() end
    end
end

local function favorite_toggle_v190(key)
    if not (ImGui and ImGui.Checkbox) then return end
    local current = minigames.GameFavorites[key] == true
    local ok, value, changed = direct_call(ImGui.Checkbox, 'Favorite##MinigamesV190_' .. key, current)
    if ok and type(value) == 'boolean' and (changed == true or value ~= current) then
        minigames.GameFavorites[key] = value
        save_favorites_v190()
    end
end

local function game_title_v190(key, title, subtitle, tone, allowFavorite)
    if UI.Text then
        UI.Text(title, tone)
        if subtitle and subtitle ~= '' then UI.Text(subtitle, 'dim', true) end
    end
    if allowFavorite == true then favorite_toggle_v190(key) end
    if UI.Spacing then UI.Spacing(1) end
end

local function is_wargames_online_v190()
    if minigames.S.wargamesSystemsActive == true or minigames.S.wargamesActive == true or minigames.S.warGamesActive == true then return true end
    if minigames.WarGames and minigames.WarGames.S and minigames.WarGames.S.active == true then return true end
    return false
end

local function active_players_v190()
    if minigames.GetActivePlayerCount then
        local n = 0
