local function format_ms_v190(ms)
    ms = math.max(0, tonumber(ms or 0) or 0)
    local total = math.floor(ms / 1000)
    return string.format('%02d:%02d', math.floor(total / 60), total % 60)
end

-- multi-color numbers in guide procedures without changing the existing guide data.
local originalTextV190 = UI.Text
local originalGuideV190 = UI.RenderGuide
local guideColorNumbersV190 = false
local NUMBER_TONES_V190 = {'purple', 'cyan', 'green', 'gold', 'orange', 'red', 'blue'}
if originalTextV190 then
    UI.Text = function(value, colorName, wrapped, alpha)
        if guideColorNumbersV190 == true then
            local number = tonumber(tostring(value or ''):match('^(%d+)%.$'))
            if number then colorName = NUMBER_TONES_V190[((number - 1) % #NUMBER_TONES_V190) + 1] end
        end
        return originalTextV190(value, colorName, wrapped, alpha)
    end
end
if originalGuideV190 then
    UI.RenderGuide = function(...)
        guideColorNumbersV190 = true
        local ok, result = direct_call(originalGuideV190, ...)
        guideColorNumbersV190 = false
        if not ok then
            if UI.Text then UI.Text('Guide error: ' .. tostring(result), 'red', true) end
            if minigames.LogError then minigames.LogError('[UI v0.190 Guide] ' .. tostring(result)) end
