local function support_log(eventName, detail, isError)
    local line = tostring(eventName or "SUPPORT")
    if detail and tostring(detail) ~= "" then line = line .. " | " .. tostring(detail) end
    if isError == true then
        if minigames.LogError then minigames.LogError("[Support] " .. line)
        elseif Logger and Logger.LogError then Logger.LogError("[Minigames] [Support] " .. line) end
    else
        if minigames.LogInfo then minigames.LogInfo("[Support] " .. line)
        elseif Logger and Logger.LogInfo then Logger.LogInfo("[Minigames] [Support] " .. line) end
    end
end

