    if GUI and GUI.AddToast then
        direct_call(GUI.AddToast, "Minigames Support", tostring(message or ""), tonumber(duration or 3500) or 3500,
            eToastPos and (eToastPos.TOP_RIGHT or eToastPos.TopRight) or 0)
    end
end

local function trim_trailing_slash(path)
    path = tostring(path or "")
    while #path > 3 and (path:sub(-1) == "\\" or path:sub(-1) == "/") do path = path:sub(1, -2) end
    return path
end

function S.GetMenuRoot()
    local root = nil
    if FileMgr and FileMgr.GetMenuRootPath then
        local ok = direct_call(function() root = FileMgr.GetMenuRootPath() end)
        if ok and root and tostring(root) ~= "" then return trim_trailing_slash(tostring(root)) end
    end

    -- compatibility fallback only. the normal cherax path above is authoritative.
    local luaRoot = tostring(minigames.LUA_ROOT or "")
    local stripped = luaRoot:gsub("[\\/]+Lua$", "")
    if stripped ~= "" and stripped ~= luaRoot then return trim_trailing_slash(stripped) end
    return trim_trailing_slash((os.getenv("USERPROFILE") or ".") .. "\\Documents\\Cherax")
end

function S.GetLuaRoot()
    local menuRoot = S.GetMenuRoot()
    return menuRoot .. "\\Lua"
end

function S.GetModRoot()
    return tostring(minigames.ROOT or (S.GetLuaRoot() .. "\\Minigames"))
end

function S.GetZipPath()
    return S.GetLuaRoot() .. "\\" .. S.ZipFileName
end

function S.GetTempPath()
    return S.GetLuaRoot() .. "\\" .. S.TempFileName
end

function S.GetCheraxLogPath()
    return S.GetMenuRoot() .. "\\Cherax.log"
end

function S.GetSupportInfoPath()
    return S.GetModRoot() .. "\\SUPPORT_INFO.txt"
end

function S.GetUploadSupportPath()
    return S.GetModRoot() .. "\\UPLOAD_SUPPORT.txt"
end

function S.GetStateSnapshotPath()
    return S.GetModRoot() .. "\\STATE_SNAPSHOT.txt"
end

local function file_exists(path)
    path = tostring(path or "")
    if path == "" then return false end
    if FileMgr and FileMgr.DoesFileExist then
        local exists = false
        local ok = direct_call(function() exists = FileMgr.DoesFileExist(path) == true end)
        if ok and exists then return true end
    end
    local f = io.open(path, "rb")
    if f then f:close(); return true end
    return false
end

local function read_file(path)
    local f, err = io.open(tostring(path or ""), "rb")
    if not f then return nil, tostring(err or "open failed") end
    local data = f:read("*a")
    f:close()
    if type(data) ~= "string" then return nil, "read failed" end
    return data
end

local function write_file(path, data)
    local f, err = io.open(tostring(path or ""), "wb")
    if not f then return false, tostring(err or "open failed") end
    local ok, writeErr = direct_call(function() f:write(tostring(data or "")); f:flush() end)
    f:close()
    if not ok then return false, tostring(writeErr or "write failed") end
    return true
end

local function ensure_support_dirs()
    if FileMgr and FileMgr.CreateDir then
        direct_call(function() FileMgr.CreateDir(S.GetModRoot()) end)
    end
end

local function copy_text(value)
    value = tostring(value or "")
    if value == "" then return false end
    if Utils and Utils.SetClipBoardText then
        local ok = direct_call(function() Utils.SetClipBoardText(value, "") end)
        if ok then return true end
    end
    if Utils and Utils.SetClipboardText then
