embedded_modules['systems\\ui_minimal_v192.lua'] = function()
-- minigames v0.193 minimalist interface with automatic config persistence.
-- default pages expose only the controls a new user normally needs.

minigames.S = minigames.S or {}
minigames.UIX = minigames.UIX or {}
minigames.WarGames = minigames.WarGames or {}
minigames.GameFavorites = minigames.GameFavorites or { wargames = true, purge = false, landonit = false, beast = false }
minigames.PurgeGame = minigames.PurgeGame or {}
local UI = minigames.UIX
local G = minigames.PurgeGame

local TONES = {
    red = {1.00, 0.26, 0.32, 1.00},
    cyan = {0.42, 0.82, 1.00, 1.00},
    gold = {1.00, 0.78, 0.18, 1.00},
    green = {0.30, 1.00, 0.48, 1.00},
    purple = {0.72, 0.42, 1.00, 1.00},
    orange = {1.00, 0.52, 0.12, 1.00},
    blue = {0.24, 0.52, 0.96, 1.00},
    dim = {0.62, 0.64, 0.72, 1.00},
}

local function toast(message, duration)
    if minigames.Toast then
        local ok = direct_call(minigames.Toast, "Minigames", tostring(message or ""), tonumber(duration or 3000) or 3000)
        if ok then return end
        direct_call(minigames.Toast, tostring(message or ""), tonumber(duration or 3000) or 3000)
    end
end

local function safe_id(value)
    return tostring(value or "Section"):gsub("[^%w_]", "_")
end

-- keep friendly child titles, but restore unique hidden imgui ids everywhere.
function UI.Child(name, title, subtitle, callback, titleColor)
    local usedChild, open = false, true
    local visibleTitle = tostring(title or name or "Section")
    local internalName = visibleTitle .. "##" .. safe_id(name or visibleTitle)

    if ClickGUI and ClickGUI.BeginCustomChildWindow then
        local ok, result = direct_call(ClickGUI.BeginCustomChildWindow, internalName)
        if ok then usedChild = true; open = result ~= false end
    end

    if open then
        if not usedChild and visibleTitle ~= "" then UI.Text(visibleTitle, titleColor or "purple") end
        if subtitle and subtitle ~= "" then UI.Text(subtitle, "dim", true) end
        if subtitle and subtitle ~= "" and UI.Spacing then UI.Spacing(1) end
        if type(callback) == "function" then
            local ok, err = direct_call(callback)
            if not ok then
                UI.Text("Section error: " .. tostring(err), "red", true)
                if minigames.LogError then minigames.LogError("[UI v0.192] " .. visibleTitle .. " | " .. tostring(err)) end
            end
        end
    end

    if usedChild and open and ClickGUI.EndCustomChildWindow then direct_call(ClickGUI.EndCustomChildWindow) end
    return open
end

local function push_tab_tone(tone)
    if not (ImGui and ImGui.PushStyleColor and ImGuiCol and ImGuiCol.Text) then return 0 end
    local c = TONES[tone or "red"] or TONES.red
    return direct_call(ImGui.PushStyleColor, ImGuiCol.Text, c[1], c[2], c[3], c[4]) and 1 or 0
end

local function begin_tab(label, tone)
    if not (ImGui and ImGui.BeginTabItem) then return false end
    local count = push_tab_tone(tone)
    local open = false
    direct_call(function() open = ImGui.BeginTabItem(label) == true end)
    if count > 0 and ImGui.PopStyleColor then direct_call(ImGui.PopStyleColor, count) end
    return open
end

local function checkbox(label, id, value)
    if not (ImGui and ImGui.Checkbox) then return value == true, false end
    local ok, newValue, changed = direct_call(ImGui.Checkbox, tostring(label) .. "##" .. tostring(id), value == true)
    if ok and type(newValue) == "boolean" then return newValue, changed == true or newValue ~= (value == true) end
    return value == true, false
end

local function collapsing(label, id, defaultOpen)
    if not (ImGui and ImGui.CollapsingHeader) then return false end
    local flags = nil
    if defaultOpen == true and ImGuiTreeNodeFlags and ImGuiTreeNodeFlags.DefaultOpen then flags = ImGuiTreeNodeFlags.DefaultOpen end
    local open = false
    direct_call(function()
        if flags then open = ImGui.CollapsingHeader(tostring(label) .. "##" .. tostring(id), flags) == true
        else open = ImGui.CollapsingHeader(tostring(label) .. "##" .. tostring(id)) == true end
    end)
    return open
end

local function get_feature(hash)
    if not hash or not FeatureMgr then return nil end
    local feature = nil
    if FeatureMgr.GetFeatureByHash then direct_call(function() feature = FeatureMgr.GetFeatureByHash(hash) end) end
    if not feature and FeatureMgr.GetFeature then direct_call(function() feature = FeatureMgr.GetFeature(hash) end) end
    return feature
end

local function get_toggle(hash)
    if minigames.GetFeatureBool and hash then
        local ok, value = direct_call(minigames.GetFeatureBool, hash, false)
        if ok then return value == true end
    end
    local feature = get_feature(hash)
    if feature and feature.IsToggled then
        local ok, value = direct_call(function() return feature:IsToggled() end)
        if ok then return value == true end
    end
    return false
end

local function set_toggle(hash, value)
    local feature = get_feature(hash)
    if not feature then return false end
    if feature.IsToggled then
        local current = nil
        direct_call(function() current = feature:IsToggled() == true end)
        if current == (value == true) then return true end
    end
    if feature.SetToggled then
        local ok = direct_call(function() feature:SetToggled(value == true) end)
        if ok then return true end
    end
    if feature.SetBoolValue then
        local ok = direct_call(function() feature:SetBoolValue(value == true) end)
        if ok then return true end
    end
    if feature.Toggle then
        local ok = direct_call(function() feature:Toggle(value == true) end)
        if ok then return true end
        ok = direct_call(function() feature:Toggle() end)
        if ok then return true end
    end
    return false
end

local function current_vehicle_label()
    if minigames.WarGames and minigames.WarGames.GetCurrentRoundVehicle then
        local vehicle = nil
        direct_call(function() vehicle = minigames.WarGames.GetCurrentRoundVehicle() end)
        if type(vehicle) == "table" then return tostring(vehicle.label or vehicle.model or "Unknown") end
    end
    local pool = minigames.WarGames and minigames.WarGames.VehiclePool or {}
    local index = tonumber(minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or 1) or 1
    local vehicle = pool[index]
    if type(vehicle) == "table" then return tostring(vehicle.label or vehicle.model or "Unknown") end
    return "Not selected"
end

local function active_player_count()
    if tonumber(minigames.S.activePlayerCount) then return tonumber(minigames.S.activePlayerCount) or 0 end
    return #(minigames.S.activePlayers or {})
end

local function wargames_online()
    if minigames.S.wargamesSystemsActive == true or minigames.S.wargamesActive == true or minigames.S.warGamesActive == true then return true end
    if get_toggle(minigames.H and minigames.H.WARGAMES_ACTIVATE_SYSTEMS) then return true end
    if get_toggle(minigames.H and minigames.H.WARGAMES_ACTIVATE_SYSTEMS_NO_BOUNTIES) then return true end
    return false
end

local function config_root_v193()
    return tostring(minigames.ROOT or ((os.getenv("USERPROFILE") or ".") .. "\\Documents\\Cherax\\Lua\\Minigames"))
end

local function config_path_v193()
    return config_root_v193() .. "\\config.ini"
end

local CONFIG_BOOL_FEATURES_V193 = {
    { key = "intro_enabled", getHash = function() return minigames.H and minigames.H.INTRO_TOGGLE end },
    { key = "hud_enabled", getHash = function() return minigames.H and minigames.H.HUD_ENABLED end },
    { key = "hud_show_status", getHash = function() return minigames.H and minigames.H.HUD_SHOW_STATUS end },
    { key = "auto_track_new_players", getHash = function() return minigames.H and minigames.H.AUTO_TRACK_NEW_PLAYERS end },
    { key = "auto_bounty_new_players", getHash = function() return minigames.H and minigames.H.AUTO_BOUNTY_NEW_PLAYERS end },
    { key = "wg_force_plate", getHash = function() return minigames.H and minigames.H.WARGAMES_FORCE_PLATE end },
    { key = "wg_remove_liveries", getHash = function() return minigames.H and minigames.H.WARGAMES_REMOVE_LIVERIES end },
    { key = "wg_randomize_colors", getHash = function() return minigames.H and minigames.H.WARGAMES_RANDOMIZE_COLORS end },
    { key = "wg_randomize_wheel_smoke", getHash = function() return minigames.H and minigames.H.WARGAMES_RANDOMIZE_WHEEL_SMOKE end },
    { key = "wg_auto_cleanup", getHash = function() return minigames.H and minigames.H.WARGAMES_AUTO_CLEANUP_VEHICLES end },
    { key = "wg_prevent_vehicle_spam", getHash = function() return minigames.H and minigames.H.WARGAMES_PREVENT_VEHICLE_SPAM end },
    { key = "wg_auto_fair_enforcement", getHash = function() return minigames.H and minigames.H.WARGAMES_AUTO_FAIR_ENFORCEMENT end },
    { key = "wg_delete_aircraft_grief", getHash = function() return minigames.H and minigames.H.WARGAMES_DELETE_AIRCRAFT_GRIEF end },
    { key = "wg_loyalty_perks", getHash = function() return minigames.H and minigames.H.WARGAMES_LOYALTY_PERKS end },
    { key = "land_disable_mk1_weapons", getHash = function() return minigames.LandOnIt and minigames.LandOnIt.H and minigames.LandOnIt.H.DISABLE_MK1_WEAPONS end },
    { key = "land_random_colors", getHash = function() return minigames.LandOnIt and minigames.LandOnIt.H and minigames.LandOnIt.H.RANDOM_COLORS end },
    { key = "land_tp_before_spawn", getHash = function() return minigames.LandOnIt and minigames.LandOnIt.H and minigames.LandOnIt.H.TP_BEFORE_SPAWN end },
}

local CONFIG_INT_FEATURES_V193 = {
    { key = "wg_round_time_ms", getHash = function() return minigames.H and minigames.H.WARGAMES_VEHICLE_ROUND_TIME_MS end },
}

local CONFIG_PURGE_KEYS_V193 = {
    "wholeLobby",
    "teamMode",
    "hardcoreHint",
    "apocalypseTraffic",
}

local function parse_bool_v193(value)
    value = tostring(value or ""):lower()
    if value == "true" or value == "1" or value == "yes" or value == "on" then return true end
    if value == "false" or value == "0" or value == "no" or value == "off" then return false end
    return nil
end

local function read_config_v193()
    local path = config_path_v193()
    local raw = nil
    if FileMgr and FileMgr.DoesFileExist then
        local exists = false
        direct_call(function() exists = FileMgr.DoesFileExist(path) == true end)
        if not exists then return {} end
    end
    if FileMgr and FileMgr.ReadFileContent then
        direct_call(function() raw = FileMgr.ReadFileContent(path) end)
    else
        local f = io.open(path, "rb")
        if f then raw = f:read("*a"); f:close() end
    end
    local out = {}
    for line in tostring(raw or ""):gmatch("[^\r\n]+") do
        local key, value = line:match("^%s*([%w_]+)%s*=%s*(.-)%s*$")
        if key and value then out[key] = value end
    end
    return out
end

local function config_snapshot_v193()
    local values = {
        auto_save = minigames.S.autoSaveConfigV193 ~= false and "true" or "false",
        bounty_default_v194_applied = minigames.S.bountyDefaultV194Applied == true and "true" or "false",
        wargames_bounties = minigames.S.warGamesUseBountiesV192 == true and "true" or "false",
    }
    for _, spec in ipairs(CONFIG_BOOL_FEATURES_V193) do
        local hash = spec.getHash and spec.getHash() or nil
        if hash then values[spec.key] = get_toggle(hash) and "true" or "false" end
    end
    for _, spec in ipairs(CONFIG_INT_FEATURES_V193) do
        local hash = spec.getHash and spec.getHash() or nil
        if hash and minigames.GetFeatureInt then
            local ok, value = direct_call(minigames.GetFeatureInt, hash, 0)
            if ok then values[spec.key] = tostring(math.floor(tonumber(value or 0) or 0)) end
        end
    end
    G.config = G.config or {}
    for _, key in ipairs(CONFIG_PURGE_KEYS_V193) do
        if G.config[key] ~= nil then values["purge_" .. key] = G.config[key] == true and "true" or "false" end
    end
    return values
end

local CONFIG_ORDER_V193 = {
    "auto_save", "bounty_default_v194_applied", "wargames_bounties",
    "intro_enabled", "hud_enabled", "hud_show_status",
    "auto_track_new_players", "auto_bounty_new_players",
    "wg_round_time_ms", "wg_force_plate", "wg_remove_liveries",
    "wg_randomize_colors", "wg_randomize_wheel_smoke", "wg_auto_cleanup",
    "wg_prevent_vehicle_spam", "wg_auto_fair_enforcement",
    "wg_delete_aircraft_grief", "wg_loyalty_perks",
    "purge_wholeLobby", "purge_teamMode", "purge_hardcoreHint", "purge_apocalypseTraffic",
    "land_disable_mk1_weapons", "land_random_colors", "land_tp_before_spawn",
}

local function config_body_v193()
    local values = config_snapshot_v193()
    local lines = {
        "# Minigames automatic configuration",
        "# Saved as settings change. Do not edit while GTA V is running.",
    }
    for _, key in ipairs(CONFIG_ORDER_V193) do
        if values[key] ~= nil then lines[#lines + 1] = key .. "=" .. tostring(values[key]) end
    end
    return table.concat(lines, "\n") .. "\n"
end

local function write_config_v193(force)
    if force ~= true and minigames.S.autoSaveConfigV193 == false then return false end
    local root = config_root_v193()
    local path = config_path_v193()
    if FileMgr and FileMgr.CreateDir then direct_call(FileMgr.CreateDir, root) end
    local body = config_body_v193()
    local ok = false
    if FileMgr and FileMgr.WriteFileContent then
        ok = direct_call(FileMgr.WriteFileContent, path, body, false)
        if not ok then ok = direct_call(FileMgr.WriteFileContent, path, body) end
    else
        local f = io.open(path, "wb")
        if f then f:write(body); f:close(); ok = true end
    end
    minigames.S.configAutoSaveStatusV193 = ok and "Saved" or "Save failed"
    if ok then minigames.S.configLastSavedBodyV193 = body end
    return ok
end

local function queue_config_save_v193()
    if minigames.S.autoSaveConfigV193 == false then return end
    minigames.S.configAutoSaveDirtyV193 = true
    if minigames.S.configAutoSaveQueuedV193 == true then return end
    minigames.S.configAutoSaveQueuedV193 = true
    local function worker()
        if Script and Script.Yield then direct_call(Script.Yield, 350) end
        minigames.S.configAutoSaveDirtyV193 = false
        write_config_v193(false)
        minigames.S.configAutoSaveQueuedV193 = false
        if minigames.S.configAutoSaveDirtyV193 == true then queue_config_save_v193() end
    end
    if Script and Script.QueueJob then Script.QueueJob(worker) else worker() end
end

local function apply_config_v193()
    local values = read_config_v193()
    local savedAuto = parse_bool_v193(values.auto_save)
    if savedAuto ~= nil then minigames.S.autoSaveConfigV193 = savedAuto else minigames.S.autoSaveConfigV193 = true end

    -- v0.194 migration: v0.193 wrote wargames bounties on as the implicit
    -- default. there is no reliable way to distinguish that generated value
    -- from a deliberate choice, so migrate once to the safer off default.
    -- after the marker is written, the user's explicit choice is preserved.
    local bountyMigrationApplied = parse_bool_v193(values.bounty_default_v194_applied) == true
    if bountyMigrationApplied then
        minigames.S.warGamesUseBountiesV192 = parse_bool_v193(values.wargames_bounties) == true
    else
        minigames.S.warGamesUseBountiesV192 = false
        minigames.S.bountyDefaultV194Applied = true
        minigames.S.autoBountyNewPlayers = false
        minigames.S.autoBountyEnabled = false
        minigames.S.autoBountyRunning = false
        if minigames.H and minigames.H.AUTO_BOUNTY_NEW_PLAYERS then
            set_toggle(minigames.H.AUTO_BOUNTY_NEW_PLAYERS, false)
        end
    end

    for _, spec in ipairs(CONFIG_BOOL_FEATURES_V193) do
        local saved = parse_bool_v193(values[spec.key])
        -- the v0.194 bounty migration owns this one setting on its first run.
        if spec.key == "auto_bounty_new_players" and not bountyMigrationApplied then saved = false end
        local hash = spec.getHash and spec.getHash() or nil
        if saved ~= nil and hash then set_toggle(hash, saved) end
    end
    if not bountyMigrationApplied then
        minigames.S.autoBountyNewPlayers = false
        minigames.S.autoBountyEnabled = false
        minigames.S.autoBountyRunning = false
    end
    for _, spec in ipairs(CONFIG_INT_FEATURES_V193) do
        local hash = spec.getHash and spec.getHash() or nil
        local saved = tonumber(values[spec.key])
        if hash and saved and minigames.SetFeatureInt then direct_call(minigames.SetFeatureInt, hash, math.floor(saved)) end
    end
    G.config = G.config or {}
    for _, key in ipairs(CONFIG_PURGE_KEYS_V193) do
        local saved = parse_bool_v193(values["purge_" .. key])
        if saved ~= nil then G.config[key] = saved end
    end
    minigames.S.configAutoSaveLoadedV193 = true
    minigames.S.configAutoSaveStatusV193 = next(values) and "Loaded" or "Ready"
    if not bountyMigrationApplied then
        -- persist the migration marker and off bounty baseline immediately.
        write_config_v193(true)
    elseif not next(values) and minigames.S.autoSaveConfigV193 ~= false then
        queue_config_save_v193()
    end
end

minigames.ConfigV193 = minigames.ConfigV193 or {}
minigames.ConfigV193.Path = config_path_v193
minigames.ConfigV193.Save = function() return write_config_v193(true) end
minigames.ConfigV193.QueueSave = queue_config_save_v193
minigames.ConfigV193.Reload = apply_config_v193
minigames.S.autoSaveConfigV193 = minigames.S.autoSaveConfigV193 ~= false

apply_config_v193()

-- automatically persist feature controls rendered by the minimalist ui without
-- forcing each game module to implement its own save button.
local tracked_feature_kind_v193 = {}
for _, spec in ipairs(CONFIG_BOOL_FEATURES_V193) do
    local hash = spec.getHash and spec.getHash() or nil
    if hash then tracked_feature_kind_v193[tostring(hash)] = "bool" end
end
for _, spec in ipairs(CONFIG_INT_FEATURES_V193) do
    local hash = spec.getHash and spec.getHash() or nil
    if hash then tracked_feature_kind_v193[tostring(hash)] = "int" end
end

local previousRenderFeatureV193 = UI.RenderFeature
if previousRenderFeatureV193 then
    function UI.RenderFeature(hash)
        local kind = hash and tracked_feature_kind_v193[tostring(hash)] or nil
        local before = nil
        if kind == "bool" then before = get_toggle(hash)
        elseif kind == "int" and minigames.GetFeatureInt then before = minigames.GetFeatureInt(hash, 0) end
        local ok = previousRenderFeatureV193(hash)
        if kind then
            local after = nil
            if kind == "bool" then after = get_toggle(hash)
            elseif kind == "int" and minigames.GetFeatureInt then after = minigames.GetFeatureInt(hash, 0) end
            if after ~= before then queue_config_save_v193() end
        end
        return ok
    end
end

local function save_favorites()
    local root = tostring(minigames.ROOT or ((os.getenv("USERPROFILE") or ".") .. "\\Documents\\Cherax\\Lua\\Minigames"))
    local path = root .. "\\favorites.ini"
    if FileMgr and FileMgr.CreateDir then direct_call(FileMgr.CreateDir, root) end
    local order = {"wargames", "purge", "landonit", "beast"}
    local lines = {}
    for _, key in ipairs(order) do lines[#lines + 1] = key .. "=" .. tostring(minigames.GameFavorites[key] == true) end
    local body = table.concat(lines, "\n")
    if FileMgr and FileMgr.WriteFileContent then
        local ok = direct_call(FileMgr.WriteFileContent, path, body, false)
        if not ok then direct_call(FileMgr.WriteFileContent, path, body) end
    else
        local f = io.open(path, "wb")
        if f then f:write(body); f:close() end
    end
end

local function render_favorite(key)
    local current = minigames.GameFavorites[key] == true
    local value, changed = checkbox("Favorite", "MinigamesFavoriteV192_" .. key, current)
    if changed then minigames.GameFavorites[key] = value; save_favorites() end
end

local function render_game_header(key, title, subtitle, tone, favorite)
    UI.Text(title, tone or "purple")
    if subtitle and subtitle ~= "" then UI.Text(subtitle, "dim", true) end
    if favorite == true then render_favorite(key) end
    if UI.Spacing then UI.Spacing(1) end
end

local function force_wargames_automatic_defaults(reason)
    reason = tostring(reason or "WarGames activation")
    set_toggle(minigames.H and minigames.H.WARGAMES_SPAWN_VEHICLE_ON_PLAYER_RESPAWN, true)
    set_toggle(minigames.H and minigames.H.WARGAMES_AUTO_RANDOM_VEHICLE_ROUNDS, true)
    set_toggle(minigames.H and minigames.H.WARGAMES_RESPAWN_TICK, true)
    set_toggle(minigames.H and minigames.H.AUTO_TRACK_NEW_PLAYERS, true)
    minigames.S.spawnVehicleOnPlayerRespawn = true
    minigames.S.spawnVehiclesOnRespawn = true
    minigames.S.respawnWatcherRunning = true
    minigames.S.autoRandomVehicleRounds = true
    minigames.S.autoVehicleRounds = true
    minigames.S.autoTrackNewPlayers = true
    if minigames.WarGames and minigames.WarGames.EnableRespawnVehiclesForAllCurrentPlayers then
        direct_call(minigames.WarGames.EnableRespawnVehiclesForAllCurrentPlayers)
    end
    minigames.S.lastWarGamesMinimalAutomationV192 = "Respawn Vehicles ON | Random Rounds ON | " .. reason
end

-- apply the requested automatic defaults no matter which established activation
-- path is used. existing wargames logic remains the source of truth.
local previousPerformModeV192 = minigames.PerformWarGamesModeChangeV169
if previousPerformModeV192 then
    function minigames.PerformWarGamesModeChangeV169(mode)
        local result = previousPerformModeV192(mode)
        mode = tostring(mode or "off")
        if mode == "bounties" or mode == "no_bounties" then force_wargames_automatic_defaults("mode=" .. mode) end
        return result
    end
end

local previousActivationAutomationV192 = minigames.WarGames.ApplyActivationAutomationV136
if previousActivationAutomationV192 then
    function minigames.WarGames.ApplyActivationAutomationV136(reason)
        local result = previousActivationAutomationV192(reason)
        force_wargames_automatic_defaults(reason or "legacy activation")
        return result
    end
end

minigames.S.warGamesUseBountiesV192 = minigames.S.warGamesUseBountiesV192 == true

local function set_wargames_bounties_v193(enabled)
    enabled = enabled == true
    if minigames.S.warGamesUseBountiesV192 == enabled then return end
    minigames.S.warGamesUseBountiesV192 = enabled
    minigames.S.autoBountyNewPlayers = enabled
    if minigames.H and minigames.H.AUTO_BOUNTY_NEW_PLAYERS then set_toggle(minigames.H.AUTO_BOUNTY_NEW_PLAYERS, enabled) end
    if not enabled then
        minigames.S.autoBountyEnabled = false
        minigames.S.autoBountyRunning = false
    end
    if wargames_online() and minigames.RequestWarGamesModeV169 then
        minigames.RequestWarGamesModeV169(enabled and "bounties" or "no_bounties")
    end
    queue_config_save_v193()
end

local function render_wargames_bounties_v193(label, id)
    local value, changed = checkbox(label or "Bounties", id or "WGBountiesV193", minigames.S.warGamesUseBountiesV192 == true)
    if changed then set_wargames_bounties_v193(value) end
end

local function request_wargames(enabled)
    if not minigames.RequestWarGamesModeV169 then return end
    if enabled == true then
        minigames.RequestWarGamesModeV169(minigames.S.warGamesUseBountiesV192 == true and "bounties" or "no_bounties")
    else
        minigames.RequestWarGamesModeV169("off")
    end
end

