local quickTpBusyV213 = false
local function queue_wargames_quick_tp(label, callback)
    if quickTpBusyV213 then toast('A WarGames move job is already running.', 2500); return false end
    if not (Script and Script.QueueJob) then toast('Script.QueueJob is unavailable.', 3500); return false end
    quickTpBusyV213 = true
    Script.QueueJob(function()
        local ok, err = direct_call_trace(callback, debug and debug.traceback or function(e) return tostring(e) end)
        quickTpBusyV213 = false
        if not ok then
            if minigames.LogError then minigames.LogError('[WarGames Quick TP] ' .. tostring(label) .. ' failed: ' .. tostring(err)) end
            toast(tostring(label) .. ' failed. Check Cherax.log.', 4500)
        end
    end)
    return true
end

