            if minigames.WarGames and minigames.WarGames.TeleportEveryoneToWaypointV150 then minigames.WarGames.TeleportEveryoneToWaypointV150() end
        end)
    end)
end

local function format_clock_v213(seconds, includeHours)
    seconds = math.max(0, math.floor(tonumber(seconds or 0) or 0))
    if includeHours then
        return string.format('%02d:%02d:%02d', math.floor(seconds / 3600), math.floor((seconds % 3600) / 60), seconds % 60)
    end
    return string.format('%02d:%02d', math.floor(seconds / 60), seconds % 60)
end

local function render_wargames_clock_v213()
    local limits = minigames.UsageLimits
    if not limits then return end
    local active = limits.Runtime and limits.Runtime.wargames and limits.Runtime.wargames.active == true
    local runLeft = limits.GetRuntimeRemainingSeconds and limits.GetRuntimeRemainingSeconds('wargames') or 1800
    local dailyLeft = limits.GetDailyTimeRemainingSeconds and limits.GetDailyTimeRemainingSeconds('wargames') or 5400
    local used = limits.GetStartsUsed and limits.GetStartsUsed('wargames') or 0
    local remaining = limits.GetStartsRemaining and limits.GetStartsRemaining('wargames') or math.max(0, 3 - used)
    local tone = runLeft <= 60 and 'red' or (runLeft <= 300 and 'gold' or 'green')
    UI.Text('WARGAMES CLOCK', 'gold')
    if UI.StatusRow then
        UI.StatusRow(active and 'Run Time Left' or 'Next Run', format_clock_v213(runLeft, false), active and tone or 'cyan')
        if limits.IgnoreDailyLimitForTesting == true then
            UI.StatusRow('Starts Today', 'UNLIMITED TESTING', 'purple')
            UI.StatusRow('Starts Remaining', 'UNLIMITED', 'purple')
            UI.StatusRow('Daily Time Remaining', 'UNLIMITED', 'purple')
        else
            UI.StatusRow('Starts Today', tostring(used) .. ' / 3', used >= 3 and 'red' or 'green')
            UI.StatusRow('Starts Remaining', tostring(remaining), remaining <= 0 and 'red' or 'cyan')
            UI.StatusRow('Daily Time Remaining', dailyLeft < 0 and 'UNLIMITED' or format_clock_v213(dailyLeft, true), dailyLeft == 0 and 'red' or 'gold')
        end
    else
        UI.Text('Run: ' .. format_clock_v213(runLeft, false) .. ' | Starts: ' .. (limits.IgnoreDailyLimitForTesting == true and 'UNLIMITED' or (tostring(used) .. '/3')) .. ' | Daily: ' .. (dailyLeft < 0 and 'UNLIMITED' or format_clock_v213(dailyLeft, true)), tone, true)
    end
end

