local function set_arena_waypoint(index)
    local locations = minigames.WarGames and minigames.WarGames.Teleports and minigames.WarGames.Teleports.Locations or {}
    local location = locations[index]
    if not location then toast("Arena location unavailable.", 3000); return false end

    local x = tonumber(location.x) or 0
    local y = tonumber(location.y) or 0
    local ok = false

    -- set_new_waypoint. calling through invokevoid matches the cherax native
    -- wrapper used elsewhere in this project and avoids table/api differences.
    if Natives and Natives.InvokeVoid then
        ok = direct_call(function() Natives.InvokeVoid(0xFE43368D2AA4F2FC, x, y) end)
    end
    if not ok and HUD and HUD.SET_NEW_WAYPOINT then
        ok = direct_call(HUD.SET_NEW_WAYPOINT, x, y)
    end

    if ok then
        minigames.S.warGamesArenaWaypointStatusV192 = "Waypoint set: " .. tostring(location.label or location.id or index)
        toast(minigames.S.warGamesArenaWaypointStatusV192, 3000)
        return true
    end

    minigames.S.warGamesArenaWaypointStatusV192 = "Waypoint unavailable"
    toast("Could not set the arena waypoint.", 3500)
    return false
end

local function render_wargames_arena()
    UI.Text("THIS SECTION IS IN BETA", "red")
    UI.Child("Minigames_WG_Arena_V192", "Arena", "Select a location, set a waypoint, then use the proven waypoint teleport.", function()
        local locations = minigames.WarGames and minigames.WarGames.Teleports and minigames.WarGames.Teleports.Locations or {}
        local names = {}
        for i, location in ipairs(locations) do names[i] = tostring(location.label or location.id or ("Arena " .. i)) end
        if #names == 0 then UI.Text("No arena locations loaded.", "red", true); return end
        minigames.S.warGamesArenaIndexV192 = math.max(0, math.min(#names - 1, math.floor(tonumber(minigames.S.warGamesArenaIndexV192 or 0) or 0)))
        local index, changed = UI.Combo("Arena##WarGamesArenaV192", minigames.S.warGamesArenaIndexV192, names, 10)
        if changed then minigames.S.warGamesArenaIndexV192 = index end
        UI.Button("Set Waypoint##WGSetArenaWaypointV192", "gold", function() set_arena_waypoint((minigames.S.warGamesArenaIndexV192 or 0) + 1) end)
        UI.SameLine()
        UI.Button("TP Players To Waypoint##WGTPArenaWaypointV192", "cyan", function()
            if minigames.WarGames and minigames.WarGames.TeleportEveryoneToWaypointV150 then minigames.WarGames.TeleportEveryoneToWaypointV150() end
