local function format_ms(ms)
    ms = math.max(0, tonumber(ms or 0) or 0)
    local sec = math.floor(ms / 1000)
    return string.format("%02d:%02d", math.floor(sec / 60), sec % 60)
end

local function save_purge()
    if G.SaveProgress then direct_call(G.SaveProgress) end
end

local function purge_toggle(label, key)
    G.config = G.config or {}
    local value, changed = checkbox(label, "PurgeV192_" .. tostring(key), G.config[key] == true)
    if changed then
        if key == "apocalypseTraffic" and G.SetApocalypseTrafficEnabled then G.SetApocalypseTrafficEnabled(value, "v0.192 Purge Config")
        else G.config[key] = value; save_purge() end
        queue_config_save_v193()
    end
end

