function UI.RenderPlayers()
    UI.Text("PLAYERS", "cyan")
    UI.Text("Automatic enrollment and a simple player picker.", "dim", true)
    UI.Spacing(1)

    UI.Child("Minigames_Players_Automation_V192", "Automation", "Only the two player automations used by Minigames.", function()
        if UI.RenderFeature then
            UI.RenderFeature(minigames.H and minigames.H.AUTO_TRACK_NEW_PLAYERS)
            UI.RenderFeature(minigames.H and minigames.H.AUTO_BOUNTY_NEW_PLAYERS)
        end
    end, "cyan")

    UI.Child("Minigames_Players_Detected_V192", "Detected Players", "Choose a player only when you need one.", function()
        if minigames.EnsurePlayersFresh then direct_call(minigames.EnsurePlayersFresh) elseif minigames.RefreshPlayers then direct_call(minigames.RefreshPlayers) end
        local players = minigames.S.activePlayers or {}
        if #players == 0 then UI.Text("No players detected.", "dim", true); return end
        local names, selectedIndex = {}, 0
        for index, playerId in ipairs(players) do
            local name = minigames.GetPlayerName and minigames.GetPlayerName(playerId) or ("Player " .. tostring(playerId))
            names[index] = "[" .. tostring(playerId) .. "] " .. tostring(name)
            if tonumber(playerId) == tonumber(minigames.S.selectedPlayerId) then selectedIndex = index - 1 end
        end
        local index, changed = UI.Combo("Player##DetectedPlayersV192", selectedIndex, names, 10)
        if changed then
            local playerId = players[index + 1]
            if playerId ~= nil and minigames.SelectPlayer then direct_call(minigames.SelectPlayer, playerId) end
        end
        if UI.StatusRow then
            UI.StatusRow("Players", #players, "green")
            UI.StatusRow("Selected", minigames.GetPlayerName and minigames.GetPlayerName(minigames.S.selectedPlayerId or players[index + 1]) or names[index + 1], "purple")
        end
    end, "purple")
end

local function logo_srv_v192()
    UI.publicUrinalLogo = UI.publicUrinalLogo or {}
    local state = UI.publicUrinalLogo
    if state.srv then return state.srv end
    local path = tostring(state.path or ((minigames.ASSETS_ROOT or ((minigames.ROOT or "") .. "\\assets")) .. "\\" .. tostring(UI.publicUrinalLogoFile or "Public_Urinal.png")))
    if path == "" then return nil end
    if not (Texture and Texture.LoadTexture and Texture.GetTexture) then return nil end
    local textureId = nil
    direct_call(function() textureId = Texture.LoadTexture(path) end)
    if not textureId or tonumber(textureId) == 0 then
        if minigames.DownloadPublicUrinalLogoV169 and state.queued ~= true then direct_call(minigames.DownloadPublicUrinalLogoV169, false) end
        return nil
    end
    local texture, srv = nil, nil
    direct_call(function() texture = Texture.GetTexture(textureId); srv = texture and texture:GetCurrent() or nil end)
    if srv then state.textureId = textureId; state.srv = srv end
    return srv
end

function UI.DrawPublicUrinalLogo(size)
    size = tonumber(size or 148) or 148
    local srv = logo_srv_v192()
    if not srv then
        UI.Text("Public_Urinal logo loading...", "dim", true)
        return false
    end
    if not (ImGui and ImGui.GetCursorScreenPos) then return false end
    local x, y = 0, 0
    local a, b = ImGui.GetCursorScreenPos()
    if type(a) == "number" then x, y = tonumber(a) or 0, tonumber(b) or 0
    elseif type(a) == "table" then x = tonumber(a.x or a.X or a[1] or 0) or 0; y = tonumber(a.y or a.Y or a[2] or 0) or 0 end

    if ImGui.Dummy then
        direct_call(ImGui.Dummy, size, size)
    elseif ImGui.Button then
        local pushed = 0
        if ImGui.PushStyleColor and ImGuiCol then
            if ImGuiCol.Button then direct_call(ImGui.PushStyleColor, ImGuiCol.Button, 0, 0, 0, 0); pushed = pushed + 1 end
            if ImGuiCol.ButtonHovered then direct_call(ImGui.PushStyleColor, ImGuiCol.ButtonHovered, 0, 0, 0, 0); pushed = pushed + 1 end
            if ImGuiCol.ButtonActive then direct_call(ImGui.PushStyleColor, ImGuiCol.ButtonActive, 0, 0, 0, 0); pushed = pushed + 1 end
        end
        direct_call(ImGui.Button, "##MinigamesPublicUrinalLogoV192", size, size)
        if pushed > 0 and ImGui.PopStyleColor then direct_call(ImGui.PopStyleColor, pushed) end
    end

    if ImGui.AddImageRounded then
        direct_call(ImGui.AddImageRounded, srv, x, y, x + size, y + size, 0, 0, 1, 1, 0xFFFFFFFF, 0.0)
        return true
    elseif ImGui.AddImage then
        direct_call(ImGui.AddImage, srv, x, y, x + size, y + size)
        return true
    end
    return false
end

local function center_logo(size)
    if not (ImGui and ImGui.GetContentRegionAvail and ImGui.GetCursorPosX and ImGui.SetCursorPosX) then return UI.DrawPublicUrinalLogo(size) end
    local avail = nil
    local current = 0
    direct_call(function() avail = ImGui.GetContentRegionAvail() end)
    direct_call(function() current = tonumber(ImGui.GetCursorPosX() or 0) or 0 end)
    local width = 0
    if type(avail) == "number" then width = tonumber(avail) or 0
    elseif type(avail) == "table" then width = tonumber(avail.x or avail.X or avail[1] or 0) or 0 end
    if width > size then direct_call(ImGui.SetCursorPosX, current + math.max(0, (width - size) * 0.5)) end
    return UI.DrawPublicUrinalLogo(size)
end

local COMMUNITY_DISCORD_V194 = "https://discord.gg/PjZUBMtD3"

local function credits_copy_and_open_discord_v194()
    local copied, opened = false, false
    if Utils and Utils.SetClipBoardText then copied = direct_call(Utils.SetClipBoardText, COMMUNITY_DISCORD_V194, "") end
    if not copied and Utils and Utils.SetClipboardText then copied = direct_call(Utils.SetClipboardText, COMMUNITY_DISCORD_V194) end
    if not copied and ImGui and ImGui.SetClipboardText then copied = direct_call(ImGui.SetClipboardText, COMMUNITY_DISCORD_V194) end

    if Utils and Utils.OpenURL then
        local ok, result = direct_call(function() return Utils.OpenURL(COMMUNITY_DISCORD_V194) end)
        opened = ok and result ~= false
    elseif Utils and Utils.OpenUrl then
        local ok, result = direct_call(function() return Utils.OpenUrl(COMMUNITY_DISCORD_V194) end)
        opened = ok and result ~= false
    elseif GUI and GUI.OpenURL then
        local ok, result = direct_call(function() return GUI.OpenURL(COMMUNITY_DISCORD_V194) end)
        opened = ok and result ~= false
    end

    if opened and copied then toast("Discord opened and invite copied.", 3500)
    elseif copied then toast("Discord invite copied.", 3000)
    elseif opened then toast("Discord opened.", 3000)
    else toast("Could not open or copy the Discord invite.", 4000) end
    return copied, opened
end

