        return UI.DrawPublicUrinalLogo(size)
    end

    local savedX, savedY = 0, 0
    direct_call(function() savedX = tonumber(ImGui.GetCursorPosX() or 0) or 0 end)
    direct_call(function() savedY = tonumber(ImGui.GetCursorPosY() or 0) or 0 end)
    local avail, width = nil, 0
    if ImGui.GetContentRegionAvail then direct_call(function() avail = ImGui.GetContentRegionAvail() end) end
    if type(avail) == "number" then width = tonumber(avail) or 0
    elseif type(avail) == "table" then width = tonumber(avail.x or avail.X or avail[1] or 0) or 0 end

    local targetX = savedX + 300
    if width > 360 then targetX = savedX + math.max(250, width - size - 38) end
    direct_call(ImGui.SetCursorPosX, targetX)
    direct_call(ImGui.SetCursorPosY, savedY + 8)
    local drawn = UI.DrawPublicUrinalLogo(size)
    direct_call(ImGui.SetCursorPosX, savedX)
    direct_call(ImGui.SetCursorPosY, savedY)
    return drawn
end

