            end)
        end, "purple")
        ImGui.EndTabItem()
    end
    if begin_tab("Support", "gold") then
        UI.Child("Minigames_Config_Support_V192", "Support & Diagnostics", "For issue reports.", render_support_ui, "gold")
        ImGui.EndTabItem()
    end
    if begin_tab("Advanced", "dim") then
        UI.Text("Advanced settings", "gold")
        UI.Text("Full legacy controls are kept here for experienced users and troubleshooting.", "dim", true)
        if oldConfigV192 then oldConfigV192() end
        ImGui.EndTabItem()
    end
    ImGui.EndTabBar()
end

