        if opened then
            if ImGui.BeginTabItem("Home") then UI.RenderHome(); ImGui.EndTabItem() end
            if ImGui.BeginTabItem("Games") then UI.RenderGames(); ImGui.EndTabItem() end
            if ImGui.BeginTabItem("Players") then UI.RenderPlayers(); ImGui.EndTabItem() end
            if ImGui.BeginTabItem("Config") then UI.RenderConfig(); ImGui.EndTabItem() end
            if ImGui.BeginTabItem("Guide") then UI.RenderGuide(); ImGui.EndTabItem() end
            if ImGui.BeginTabItem("Credits") then UI.RenderCredits(); ImGui.EndTabItem() end
            ImGui.EndTabBar()
        else UI.RenderHome() end
    else UI.RenderHome() end
    if UI.PopTabStyle then UI.PopTabStyle(pushed) end
    if UI.RenderSettingsResetPopupV169 then UI.RenderSettingsResetPopupV169() end
end

