local function __mg_execute_embedded_module(relativePath)
    local normalized = __mg_normalize_module_path(relativePath)
    local module = embedded_modules[normalized]

    if not module then
        local message = "Embedded module not found: " .. tostring(normalized)
        __mg_loader_error(message)
        error(message)
    end

    if MINIGAMES_VERBOSE_BOOT_LOGS_V205 == true and Logger and Logger.LogInfo then
        Logger.LogInfo("[Minigames] Loading embedded module: " .. normalized)
    end

    local ok, err = direct_call(module)
    if not ok then
        local message =
            "Failed loading embedded module " ..
            tostring(normalized) .. " | " .. tostring(err)

        __mg_loader_error(message)
        error(message)
    end
end

-- ============================================================
-- embedded module: systems\v196_purge_worldz.lua
-- ============================================================
embedded_modules['systems\\v196_purge_worldz.lua'] = function()
-- minigames v0.196-alpha
-- replaces the old max-speed purge traffic tick with a lower-force apocalyptic
-- ambience layer inspired by world war z / gta sa riot energy. player vehicles
-- are never modified. the existing cherax custom traffic variety integration is
-- preserved and still returns off when the purge ends.

minigames.S = minigames.S or {}
minigames.PurgeGame = minigames.PurgeGame or {}
local G = minigames.PurgeGame
G.config = G.config or {}
G.apocalypseTraffic = G.apocalypseTraffic or {}
local AT = G.apocalypseTraffic

G.PurgeWorldZ = G.PurgeWorldZ or {
    active = false,
    runSerial = 0,
    vehicleSeen = {},
    vehicleSnapshot = {},
    pedSeen = {},
    touchedPeds = {},
    pendingCoast = {},
    pendingExplosion = {},
    rpgPed = 0,
    rpgAssignedThisRun = false,
    lastVehicleTickMs = 0,
    lastPedTickMs = 0,
    lastSceneTickMs = 0,
    nextLocalAggressorMs = 0,
    lastVehicleCount = 0,
    lastPedCount = 0,
    lastIdea = 'Ready',
}
local WZ = G.PurgeWorldZ

-- 30 implemented ambience ideas. these are intentionally randomized and
-- performance-limited rather than all firing at once.
WZ.ideas = {
    [1]  = 'Smoke-trailing survivor car',
    [2]  = 'Burning roadside wreck',
    [3]  = 'Driverless coasting vehicle',
    [4]  = 'Panicked driver bailout',
    [5]  = 'Crushed-body wreck',
    [6]  = 'Shredded-tyre vehicle',
    [7]  = 'Smashed-window survivor car',
    [8]  = 'Missing-door wreck',
    [9]  = 'Dead-headlight vehicle',
    [10] = 'Abandoned car alarm',
