}

local SIGNATURE_IDEAS = {
    [1] = 'Burning traffic wreck',
    [2] = 'Catastrophic smashed vehicle',
    [3] = 'Driverless ghost traffic',
    [4] = 'Alarm-and-hazard roadblock',
    [5] = 'Smoldering limping survivor car',
    [6] = 'Safe delayed vehicle explosion',
    [7] = 'Collapsed emergency response vehicle',
    [8] = 'Abandoned military evacuation vehicle',
    [9] = 'Grounded panic-driver traffic',
    [10] = 'Civilian stampede with riot pocket',
}
V.signatureIdeas = SIGNATURE_IDEAS

local EMERGENCY_MODELS = { 'police3', 'ambulance', 'firetruk', 'police2' }
local MILITARY_MODELS = { 'barracks', 'crusader', 'barracks2', 'riot' }

local function now_ms()
    if minigames.Now then local ok, value = direct_call(minigames.Now); if ok and value then return tonumber(value) or 0 end end
    if Time and Time.GetEpocheMs then local ok, value = direct_call(Time.GetEpocheMs); if ok and value then return tonumber(value) or 0 end end
    return math.floor((os.clock() or 0) * 1000)
end

local function log(message)
    if minigames.LogInfo then minigames.LogInfo('[The Purge] [v0.199] ' .. tostring(message)) end
end

local function entity_exists(entity)
    if not entity or entity == 0 or not Natives or not Natives.InvokeBool then return false end
    local ok, value = direct_call(Natives.InvokeBool, H.DOES_ENTITY_EXIST, entity)
    return ok and value == true
end

local function request_control(entity)
    if not entity_exists(entity) then return false end
    if not Natives or not Natives.InvokeBool then return true end
    local has = false
    direct_call(function() has = Natives.InvokeBool(H.NETWORK_HAS_CONTROL_OF_ENTITY, entity) == true end)
    if has then return true end
    direct_call(function() Natives.InvokeBool(H.NETWORK_REQUEST_CONTROL_OF_ENTITY, entity) end)
    direct_call(function() has = Natives.InvokeBool(H.NETWORK_HAS_CONTROL_OF_ENTITY, entity) == true end)
    return has
end

local function coords(entity)
    if not Natives or not Natives.InvokeV3 then return nil end
    local ok, a, b, c = direct_call(function() return Natives.InvokeV3(H.GET_ENTITY_COORDS, entity, true) end)
    if not ok or a == nil then return nil end
    if type(a) == 'number' then return { x = tonumber(a) or 0, y = tonumber(b) or 0, z = tonumber(c) or 0 } end
    if type(a) == 'table' then
        return {
            x = tonumber(a.x or a.X or a[1]) or 0,
            y = tonumber(a.y or a.Y or a[2]) or 0,
            z = tonumber(a.z or a.Z or a[3]) or 0,
        }
    end
    return nil
end

local function distance(a, b)
    if not a or not b then return 999999.0 end
    local dx, dy, dz = a.x - b.x, a.y - b.y, a.z - b.z
    return math.sqrt(dx * dx + dy * dy + dz * dz)
end

local function local_player_id()
    return minigames.GetLocalPlayerId and minigames.GetLocalPlayerId() or 0
end

local function player_active(id)
    if minigames.IsPlayerActive then
        local ok, value = direct_call(minigames.IsPlayerActive, id)
        return ok and value == true
    end
    return false
end

local function player_ped(id)
    if not minigames.GetPlayerPed then return 0 end
    local ped = 0
    direct_call(function() ped = minigames.GetPlayerPed(id) or 0 end)
    return ped
end

local function is_player_ped(ped)
    if not ped or ped == 0 or not Natives or not Natives.InvokeBool then return false end
    local ok, value = direct_call(Natives.InvokeBool, H.IS_PED_A_PLAYER, ped)
    return ok and value == true
end

local function all_player_positions()
    local out = {}
    for id = 0, 31 do
        if player_active(id) then
            local ped = player_ped(id)
            if entity_exists(ped) then out[#out + 1] = coords(ped) end
        end
    end
    return out
end

local function safe_from_players(pos, radius)
    if not pos then return false end
    for _, playerPos in ipairs(all_player_positions()) do
        if playerPos and distance(pos, playerPos) < (radius or 80.0) then return false end
    end
    return true
end

-- ============================================================
-- anti-map-cheat: keep esc/settings available, hide player blips instead.
-- ============================================================
local function should_hide_player_blips()
    local run = G.run or {}
    if run.active ~= true then return false end
    local stage = tostring(run.stage or '')
    return stage == 'opening' or stage == 'transition' or stage == 'city_sweep'
end

local function blip_exists(blip)
    if not blip or blip == 0 or not Natives or not Natives.InvokeBool then return false end
    local ok, value = direct_call(Natives.InvokeBool, H.DOES_BLIP_EXIST, blip)
    return ok and value == true
end

local function hide_remote_player_blips()
    if not Natives or not Natives.InvokeInt or not Natives.InvokeVoid then return end
    local selfId = local_player_id()
    local hidden = 0
    for id = 0, 31 do
        if id ~= selfId and player_active(id) then
            local ped = player_ped(id)
            if entity_exists(ped) then
                local blip = 0
                direct_call(function() blip = Natives.InvokeInt(H.GET_BLIP_FROM_ENTITY, ped) or 0 end)
                if blip ~= 0 and blip_exists(blip) then
                    if V.blipBackup[blip] == nil then
                        local alpha = 255
                        direct_call(function() alpha = tonumber(Natives.InvokeInt(H.GET_BLIP_ALPHA, blip)) or 255 end)
                        V.blipBackup[blip] = { alpha = alpha, playerId = id }
                    end
                    direct_call(function() Natives.InvokeVoid(H.SET_BLIP_ALPHA, blip, 0) end)
                    hidden = hidden + 1
                end
            end
        end
    end
    V.blipsHidden = hidden > 0
end

local function restore_remote_player_blips()
    if Natives and Natives.InvokeVoid then
        for blip, entry in pairs(V.blipBackup or {}) do
            if blip_exists(blip) then
                direct_call(function() Natives.InvokeVoid(H.SET_BLIP_ALPHA, blip, math.max(0, math.min(255, tonumber(entry.alpha) or 255))) end)
            end
        end
    end
    V.blipBackup = {}
    V.blipsHidden = false
end

-- ============================================================
-- stage 2 rendering: misc > rendering > huffing timecycle.
-- ============================================================
local function read_toggle(feature)
    if not feature then return nil end
    local value = nil
    direct_call(function()
        if feature.IsToggled then value = feature:IsToggled()
        elseif feature.GetBoolValue then value = feature:GetBoolValue() end
    end)
    return value
end

local function set_toggle(feature, desired)
    if not feature then return false end
    desired = desired == true
    local current = read_toggle(feature)
    if current == desired then return true end
    if feature.Toggle then
        direct_call(function() feature:Toggle(desired) end)
        if read_toggle(feature) == desired then return true end
        direct_call(function() feature:Toggle() end)
        if read_toggle(feature) == desired then return true end
    end
    if feature.SetBoolValue then
        direct_call(function() feature:SetBoolValue(desired) end)
        if feature.TriggerCallback then direct_call(function() feature:TriggerCallback() end) end
        if read_toggle(feature) == desired then return true end
    end
    if feature.SetValue then
        direct_call(function() feature:SetValue(desired) end)
        if feature.TriggerCallback then direct_call(function() feature:TriggerCallback() end) end
        if read_toggle(feature) == desired then return true end
    end
    return false
end

local function find_huffing_feature()
    if V.huffingFeature then return V.huffingFeature end
    if not FeatureMgr then return nil end
    local names = { 'Huffing Timecycle', 'Huffing timecycle', 'Huffing Time Cycle' }
    if FeatureMgr.GetFeatureByName then
        for _, name in ipairs(names) do
            local feature = nil
            direct_call(function() feature = FeatureMgr.GetFeatureByName(name) end)
            if feature then V.huffingFeature = feature return feature end
        end
    end
    if FeatureMgr.GetAllFeatures then
        local all = nil
        direct_call(function() all = FeatureMgr.GetAllFeatures() end)
        if type(all) == 'table' then
            for _, feature in pairs(all) do
                local featureName = ''
                direct_call(function()
                    if feature.GetName then featureName = tostring(feature:GetName(false) or '')
                    else featureName = tostring(feature.Name or '') end
                end)
                for _, wanted in ipairs(names) do
                    if featureName == wanted then V.huffingFeature = feature return feature end
                end
            end
        end
    end
    return nil
end

local function stage2_visual_active()
    local run = G.run or {}
    if run.active ~= true then return false end
    local stage = tostring(run.stage or '')
    return stage == 'transition' or stage == 'city_sweep'
end

local function enable_huffing_timecycle()
    local feature = find_huffing_feature()
    if not feature then
        if V.huffingWarned ~= true then
            V.huffingWarned = true
            log('Huffing Timecycle feature was not found; Stage 2 continues without it.')
        end
        return false
    end
    if V.huffingCaptured ~= true then
        V.huffingBackup = read_toggle(feature)
        V.huffingCaptured = true
    end
    local ok = set_toggle(feature, true)
    V.huffingActive = ok == true
    return ok
end

local function restore_huffing_timecycle()
    if V.huffingCaptured ~= true then
        V.huffingActive = false
        return true
    end
    local feature = find_huffing_feature()
    local desired = V.huffingBackup == true
    local ok = feature and set_toggle(feature, desired) or false
    V.huffingCaptured = false
    V.huffingBackup = nil
    V.huffingActive = false
    return ok
end

local function tick_stage_visuals()
    local now = now_ms()
    if now < (V.lastStageGuardMs or 0) + 750 then return end
    V.lastStageGuardMs = now

    if should_hide_player_blips() then hide_remote_player_blips()
    elseif next(V.blipBackup or {}) ~= nil then restore_remote_player_blips() end

    if stage2_visual_active() then
        if read_toggle(find_huffing_feature()) ~= true then enable_huffing_timecycle() end
    elseif V.huffingCaptured == true or V.huffingActive == true then
        restore_huffing_timecycle()
    end
end

-- ============================================================
-- worldz signature scenes
-- ten obvious vehicle/ped scenes layered over the existing 30 ambience ideas.
-- ============================================================
local function get_driver(vehicle)
    if not Natives or not Natives.InvokeInt then return 0 end
    local ped = 0
    direct_call(function() ped = Natives.InvokeInt(H.GET_PED_IN_VEHICLE_SEAT, vehicle, -1, false) or 0 end)
    return ped
end

local function player_vehicle_set()
    local set = {}
    if not Natives or not Natives.InvokeInt then return set end
    for id = 0, 31 do
        if player_active(id) then
            local ped = player_ped(id)
            if entity_exists(ped) then
                local vehicle = 0
                direct_call(function() vehicle = Natives.InvokeInt(H.GET_VEHICLE_PED_IS_IN, ped, false) or 0 end)
                if vehicle ~= 0 then set[vehicle] = true end
            end
        end
    end
    return set
end

local function all_vehicles(maxItems)
    local out = {}
    if not PoolMgr or not PoolMgr.GetVehicle then return out end
    local maximum = 0
    if PoolMgr.GetMaxVehicleCount then direct_call(function() maximum = tonumber(PoolMgr.GetMaxVehicleCount()) or 0 end) end
    if maximum <= 0 and PoolMgr.GetCurrentVehicleCount then direct_call(function() maximum = tonumber(PoolMgr.GetCurrentVehicleCount()) or 0 end) end
    maximum = math.min(math.max(maximum, 0), 512)
    for index = 0, math.max(0, maximum - 1) do
        local vehicle = 0
        direct_call(function() vehicle = PoolMgr.GetVehicle(index) or 0 end)
        if vehicle ~= 0 then
            out[#out + 1] = vehicle
            if #out >= (maxItems or 140) then break end
        end
    end
    return out
end

local function damage_vehicle(vehicle, engine, body, petrol)
    if not Natives or not Natives.InvokeVoid then return end
    direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_ENGINE_HEALTH, vehicle, engine + 0.0) end)
    direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_BODY_HEALTH, vehicle, body + 0.0) end)
    direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_PETROL_TANK_HEALTH, vehicle, petrol + 0.0) end)
    direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_DIRT_LEVEL, vehicle, 15.0) end)
end

local function smash_vehicle(vehicle, severity)
    severity = math.max(1, math.min(4, tonumber(severity) or 2))
    if not Natives or not Natives.InvokeVoid then return end
    damage_vehicle(vehicle, severity >= 4 and 90.0 or 220.0, severity >= 3 and 130.0 or 350.0, severity >= 4 and 120.0 or 350.0)
    direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_DAMAGE, vehicle, 0.4, 1.1, 0.15, 3000.0, 1000.0, true) end)
    for window = 0, math.min(3, severity) do direct_call(function() Natives.InvokeVoid(H.SMASH_VEHICLE_WINDOW, vehicle, window) end) end
    for _ = 1, severity do
        local tyre = math.random(0, 5)
        direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_TYRE_BURST, vehicle, tyre, true, 1000.0) end)
    end
    if severity >= 3 then direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_DOOR_BROKEN, vehicle, math.random(0, 3), false) end) end
end

local function set_hazards(vehicle, enabled)
    if not Natives or not Natives.InvokeVoid then return end
    direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_INDICATOR_LIGHTS, vehicle, 0, enabled == true) end)
    direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_INDICATOR_LIGHTS, vehicle, 1, enabled == true) end)
end

local function start_vehicle_fire(vehicle)
    if not Natives or not Natives.InvokeInt then return false end
    local ok = direct_call(function() Natives.InvokeInt(H.START_ENTITY_FIRE, vehicle) end)
    return ok
end

local function apply_signature_vehicle(vehicle, idea, now)
    if not entity_exists(vehicle) or not request_control(vehicle) or not Natives or not Natives.InvokeVoid then return false end
    local driver = get_driver(vehicle)
    if driver ~= 0 and is_player_ped(driver) then return false end
    local pos = coords(vehicle)
    V.lastSignature = tostring(idea) .. '/10 ' .. tostring(SIGNATURE_IDEAS[idea] or 'WorldZ scene')

    if idea == 1 then
        -- visibly burning but not instantly exploding.
        damage_vehicle(vehicle, 120.0, 380.0, 350.0)
        if safe_from_players(pos, 28.0) then start_vehicle_fire(vehicle) end
        set_hazards(vehicle, true)
    elseif idea == 2 then
        smash_vehicle(vehicle, 4)
        direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_ENGINE_ON, vehicle, false, true, true) end)
        direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_UNDRIVEABLE, vehicle, true) end)
        direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_HANDBRAKE, vehicle, true) end)
    elseif idea == 3 then
        -- keep this rare so the apocalypse is not just everyone exiting cars.
        if driver ~= 0 and entity_exists(driver) then
            direct_call(function() Natives.InvokeVoid(H.TASK_LEAVE_VEHICLE, driver, vehicle, 4160) end)
            V.pendingGhost = V.pendingGhost or {}
            V.pendingGhost[vehicle] = now + 1700
        elseif safe_from_players(pos, 35.0) then
            direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_ENGINE_ON, vehicle, true, true, false) end)
            direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_FORWARD_SPEED, vehicle, 8.0 + math.random() * 3.0) end)
        end
    elseif idea == 4 then
        smash_vehicle(vehicle, 2)
        direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_ENGINE_ON, vehicle, false, true, true) end)
        direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_HANDBRAKE, vehicle, true) end)
        direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_ALARM, vehicle, true) end)
        direct_call(function() Natives.InvokeVoid(H.START_VEHICLE_ALARM, vehicle) end)
        set_hazards(vehicle, true)
    elseif idea == 5 then
        damage_vehicle(vehicle, 260.0, 470.0, 520.0)
        direct_call(function() Natives.InvokeVoid(H.SMASH_VEHICLE_WINDOW, vehicle, math.random(0, 3)) end)
        if driver ~= 0 and entity_exists(driver) then
            local speed = 11.0 + math.random() * 5.0
            direct_call(function() Natives.InvokeVoid(H.TASK_VEHICLE_DRIVE_WANDER, driver, vehicle, speed, 786603) end)
            direct_call(function() Natives.InvokeVoid(H.SET_DRIVE_TASK_CRUISE_SPEED, driver, speed) end)
            direct_call(function() Natives.InvokeVoid(H.SET_PED_KEEP_TASK, driver, true) end)
        end
    elseif idea == 6 then
        damage_vehicle(vehicle, 105.0, 260.0, 100.0)
        if safe_from_players(pos, 80.0) then
            start_vehicle_fire(vehicle)
            V.pendingExplosions[vehicle] = now + math.random(7000, 15000)
        end
    elseif idea == 9 then
        if driver ~= 0 and entity_exists(driver) then
            local speed = 18.0 + math.random() * 6.0
            direct_call(function() Natives.InvokeVoid(H.TASK_VEHICLE_DRIVE_WANDER, driver, vehicle, speed, 786603) end)
            direct_call(function() Natives.InvokeVoid(H.SET_DRIVE_TASK_CRUISE_SPEED, driver, speed) end)
            direct_call(function() Natives.InvokeVoid(H.SET_PED_KEEP_TASK, driver, true) end)
            if math.random(1, 3) == 1 then direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_TYRE_BURST, vehicle, math.random(0, 5), true, 1000.0) end) end
        else
            damage_vehicle(vehicle, 300.0, 500.0, 550.0)
        end
    else
        smash_vehicle(vehicle, 2)
    end
    return true
end

local function process_pending_signature(now)
    local playerVehicles = player_vehicle_set()
    for vehicle, when in pairs(V.pendingExplosions or {}) do
        if now >= when then
            V.pendingExplosions[vehicle] = nil
            if entity_exists(vehicle) and not playerVehicles[vehicle] and safe_from_players(coords(vehicle), 95.0) and request_control(vehicle) then
                direct_call(function() Natives.InvokeVoid(H.EXPLODE_VEHICLE, vehicle, true, false) end)
            end
        end
    end
    for vehicle, when in pairs(V.pendingGhost or {}) do
        if now >= when then
            V.pendingGhost[vehicle] = nil
            if entity_exists(vehicle) and not playerVehicles[vehicle] and get_driver(vehicle) == 0 and safe_from_players(coords(vehicle), 35.0) and request_control(vehicle) then
                direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_ENGINE_ON, vehicle, true, true, false) end)
                direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_FORWARD_SPEED, vehicle, 7.0 + math.random() * 4.0) end)
            end
        end
    end
end

local function run_signature_vehicle_pass(now)
    if now < (V.lastVehiclePassMs or 0) + 1800 then return end
    V.lastVehiclePassMs = now
    process_pending_signature(now)

    local lp = player_ped(local_player_id())
    local localPos = entity_exists(lp) and coords(lp) or nil
    local playerVehicles = player_vehicle_set()
    local candidates = {}
    for _, vehicle in ipairs(all_vehicles(150)) do
        if entity_exists(vehicle) and not playerVehicles[vehicle] and not V.signatureSeen[vehicle] then
            local pos = coords(vehicle)
            if not localPos or (pos and distance(localPos, pos) <= 310.0) then
                local driver = get_driver(vehicle)
                if driver == 0 or not is_player_ped(driver) then candidates[#candidates + 1] = vehicle end
            end
        end
    end

    -- apply only a handful each pass, but heavily favor obvious visual damage/fire.
    local applied = 0
    local maxApply = math.min(5, #candidates)
    local weighted = { 1,1,1,1, 2,2,2,2, 4,4,4, 5,5,5, 6, 9,9, 3 }
    while applied < maxApply and #candidates > 0 do
        local pick = math.random(1, #candidates)
        local vehicle = table.remove(candidates, pick)
        V.signatureSeen[vehicle] = now
        local idea = weighted[math.random(1, #weighted)]
        if apply_signature_vehicle(vehicle, idea, now) then applied = applied + 1 end
    end
    V.lastSignatureCount = applied
end

local function cleanup_spawned_setpieces()
    if Natives and Natives.InvokeVoid then
        for vehicle in pairs(V.spawnedVehicles or {}) do
            if entity_exists(vehicle) and request_control(vehicle) then
                direct_call(function() Natives.InvokeVoid(H.STOP_ENTITY_FIRE, vehicle) end)
                direct_call(function() Natives.InvokeVoid(H.DELETE_ENTITY, vehicle) end)
            end
        end
    end
    V.spawnedVehicles = {}
    V.signatureSeen = {}
    V.pendingExplosions = {}
    V.pendingGhost = {}
    V.nextSetPieceMs = 0
    V.setPieceQueued = false
    V.lastSignature = 'Ready'
    V.lastSignatureCount = 0
end

local function spawn_setpiece_job()
    V.setPieceQueued = false
    if not G.run or G.run.active ~= true or G.config.apocalypseTraffic ~= true then return end
    if not GTA or not GTA.SpawnVehicleForPlayer then return end

    local spawnedCount = 0
    for vehicle in pairs(V.spawnedVehicles or {}) do
        if entity_exists(vehicle) then spawnedCount = spawnedCount + 1 else V.spawnedVehicles[vehicle] = nil end
    end
    if spawnedCount >= 3 then return end

    local emergency = math.random(1, 100) <= 58
    local models = emergency and EMERGENCY_MODELS or MILITARY_MODELS
    local model = models[math.random(1, #models)]
    local forward = 70.0 + math.random() * 45.0
    local vehicle = 0
    local ok, result = direct_call(GTA.SpawnVehicleForPlayer, model, local_player_id(), forward)
    if ok then vehicle = tonumber(result) or 0 end
    if vehicle == 0 or not entity_exists(vehicle) then
        log('Signature set-piece spawn unavailable | model=' .. tostring(model))
        return
    end

    V.spawnedVehicles[vehicle] = { model = model, emergency = emergency, createdAt = now_ms() }
    if request_control(vehicle) then
        if emergency then
            V.lastSignature = '7/10 ' .. SIGNATURE_IDEAS[7]
            smash_vehicle(vehicle, 3)
            direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_SIREN, vehicle, true) end)
            direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_LIGHTS, vehicle, 2) end)
            set_hazards(vehicle, true)
            if math.random(1, 3) == 1 and safe_from_players(coords(vehicle), 35.0) then start_vehicle_fire(vehicle) end
            if math.random(1, 5) == 1 and safe_from_players(coords(vehicle), 95.0) then V.pendingExplosions[vehicle] = now_ms() + math.random(9000, 18000) end
        else
            V.lastSignature = '8/10 ' .. SIGNATURE_IDEAS[8]
            smash_vehicle(vehicle, 3)
            direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_ENGINE_ON, vehicle, false, true, true) end)
            direct_call(function() Natives.InvokeVoid(H.SET_VEHICLE_HANDBRAKE, vehicle, true) end)
            set_hazards(vehicle, true)
            if math.random(1, 6) == 1 and safe_from_players(coords(vehicle), 95.0) then V.pendingExplosions[vehicle] = now_ms() + math.random(12000, 22000) end
        end
    end
    log('Signature set-piece spawned | ' .. tostring(V.lastSignature) .. ' | model=' .. tostring(model))
end

local function maybe_spawn_setpiece(now)
    if now < (V.nextSetPieceMs or 0) then return end
    V.nextSetPieceMs = now + math.random(32000, 52000)
    if V.setPieceQueued == true then return end
    V.setPieceQueued = true
    if Script and Script.QueueJob then
        local ok = direct_call(Script.QueueJob, spawn_setpiece_job)
        if not ok then V.setPieceQueued = false end
    else
        spawn_setpiece_job()
    end
end

local function worldz_signature_active()
    local run = G.run or {}
    if run.active ~= true or G.config.apocalypseTraffic ~= true then return false end
    local stage = tostring(run.stage or '')
    return stage == 'opening' or stage == 'transition' or stage == 'city_sweep'
end

local function tick_signature_worldz()
    if not worldz_signature_active() then
        if next(V.spawnedVehicles or {}) ~= nil or next(V.pendingExplosions or {}) ~= nil then cleanup_spawned_setpieces() end
        return
    end
    local now = now_ms()
    run_signature_vehicle_pass(now)
    maybe_spawn_setpiece(now)
end

-- keep cleanup coupled to the existing apocalypse traffic lifecycle.
local previousStopApocalypse = G.StopApocalypseTraffic
if previousStopApocalypse then
    function G.StopApocalypseTraffic(reason)
        cleanup_spawned_setpieces()
        return previousStopApocalypse(reason)
    end
end

-- main script worker wrapper. no heavy entity work is performed from imgui callbacks.
local previousTick = G.Tick
if previousTick then
    function G.Tick(...)
        local result = previousTick(...)
        local okVisual, errVisual = direct_call(tick_stage_visuals)
        if not okVisual and minigames.LogError then minigames.LogError('[Minigames] [The Purge] v0.199 stage visual tick failed | ' .. tostring(errVisual)) end
        local okWorld, errWorld = direct_call(tick_signature_worldz)
        if not okWorld then
            local now = now_ms()
            local last = tonumber(minigames.S.purgeV199WorldZErrorMs or 0) or 0
            if last == 0 or now - last >= 5000 then
                minigames.S.purgeV199WorldZErrorMs = now
                if minigames.LogError then minigames.LogError('[Minigames] [The Purge] v0.199 WorldZ signature tick failed | ' .. tostring(errWorld)) end
            end
        end
        return result
    end
end

-- blip suppression is deliberately the only per-frame job here. this catches
-- rockstar recreating player blips while the pause map or expanded radar is open.
if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_PRESENT then
    direct_call(function()
        V.blipPresentHandler = EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
            local now = now_ms()
            if now < (V.lastBlipPresentMs or 0) + 120 then return end
            V.lastBlipPresentMs = now
            if should_hide_player_blips() then
                hide_remote_player_blips()
            elseif next(V.blipBackup or {}) ~= nil then
                restore_remote_player_blips()
            end
        end)
    end)
end

-- ensure every exit path returns map visibility and temporary rendering state.
local previousRestorePreset = G.RestorePurgePreset
if previousRestorePreset then
    function G.RestorePurgePreset(reason)
        restore_remote_player_blips()
        restore_huffing_timecycle()
        cleanup_spawned_setpieces()
        return previousRestorePreset(reason)
    end
end

function G.GetPurgeAntiCheatStatusV199()
    return should_hide_player_blips() and 'Player blips hidden from minimap and pause map' or 'Idle'
end

function G.GetPurgeHuffingStatusV199()
    if stage2_visual_active() then return V.huffingActive and 'Huffing Timecycle ON' or 'Huffing Timecycle pending/unavailable' end
    return 'Huffing Timecycle OFF'
end

function G.GetWorldZSignatureStatusV199()
    return tostring(V.lastSignature or 'Ready')
end

minigames.S.purgeStealthWorldZV199 = true
log('v0.199 loaded | player-map blip blackout | Stage 2 Huffing Timecycle | 10 signature apocalypse scenes')
end


-- ============================================================
-- embedded module: systems\\usage_limits_v204.lua
-- ============================================================
embedded_modules['systems\\usage_limits_v204.lua'] = function()
-- minigames v0.204-alpha
-- host-only activation, session-size, and daily-use safeguards.
--
-- rules:
--   * the local player must be session host to start an activity.
--   * 20 or more session players are required to start an activity.
--   * a running activity is never stopped if host changes or the lobby drops below 20.
--   * unlimited successful starts are enabled temporarily for testing.
--   * wargames lasts 30 minutes per run; other playable minigames retain 60-minute runs.
--   * historical daily-use state remains preserved in minigames\daily_limits.ini but is ignored in testing mode.
--   * future donor access can bypass daily/runtime limits by changing one flag;
--     the session host and 20-player start requirements remain enforced.

minigames = minigames or {}
minigames.S = minigames.S or {}
minigames.UsageLimits = minigames.UsageLimits or {}
local L = minigames.UsageLimits
local UI = minigames.UI or {}
local G = minigames.PurgeGame or {}

L.MinimumPlayers = 20
L.MaximumRuntimeSeconds = 60 * 60
L.WarGamesMaximumRuntimeSeconds = 30 * 60
L.WarGamesMaximumStartsPerDay = 3
L.MaximumStartsPerDay = {
    wargames = L.WarGamesMaximumStartsPerDay,
    purge = 1,
    landonit = 1,
}
L.UnlimitedDailyAccess = L.UnlimitedDailyAccess == true -- future donor hook, off for now
L.IgnoreDailyLimitForTesting = true
L.Path = tostring(minigames.ROOT or ((os.getenv('USERPROFILE') or '.') .. '\\Documents\\Cherax\\Lua\\Minigames')) .. '\\daily_limits.ini'
L.TempPath = L.Path .. '.tmp'
L.GameOrder = { 'wargames', 'purge', 'landonit' }
L.GameNames = {
    wargames = 'WarGames',
    purge = 'The Purge',
    landonit = 'Land On It',
}
L.Runtime = L.Runtime or {
    wargames = { active = false, reserved = false, startedEpoch = 0 },
    purge = { active = false, reserved = false, startedEpoch = 0 },
    landonit = { active = false, reserved = false, startedEpoch = 0 },
}
L.State = L.State or { date = '', games = {} }
L._internalStop = false

local function now_ms()
    if Time and Time.GetEpocheMs then
        local ok, value = direct_call(Time.GetEpocheMs)
        if ok and tonumber(value) then return tonumber(value) end
    end
    return math.floor((os.clock and os.clock() or 0) * 1000)
end

local function today_key()
    local ok, value = direct_call(os.date, '%Y-%m-%d')
    if ok and type(value) == 'string' and value ~= '' then return value end
    return tostring(math.floor((os.time and os.time() or 0) / 86400))
end

local function notify(message, duration)
    message = tostring(message or '')
    duration = tonumber(duration or 5000) or 5000
    if minigames.Toast then
        local ok = direct_call(minigames.Toast, 'Minigames Limits', message, duration)
        if ok then return end
    end
    if GUI and GUI.AddToast then
        direct_call(GUI.AddToast, 'Minigames Limits', message, duration)
    end
end

local function log(message)
    if minigames.LogInfo then direct_call(minigames.LogInfo, '[v0.204 Access] ' .. tostring(message or '')) end
end

local function parse_bool(value)
    value = tostring(value or ''):lower()
    if value == 'true' or value == '1' or value == 'yes' then return true end
    if value == 'false' or value == '0' or value == 'no' then return false end
    return nil
end

local function new_day_state(day)
    local games = {}
    for _, key in ipairs(L.GameOrder) do
        games[key] = { used = false, startedAt = 0, startCount = 0 }
    end
    return { date = tostring(day or today_key()), games = games }
end

local function ensure_game_state(key)
    L.State.games = L.State.games or {}
    L.State.games[key] = L.State.games[key] or { used = false, startedAt = 0, startCount = 0 }
    return L.State.games[key]
end

local function read_file(path)
    local f = io.open(tostring(path or ''), 'rb')
    if not f then return nil end
    local body = f:read('*a')
    f:close()
    return body
end

function L.Save()
    local root = tostring(minigames.ROOT or '')
    if root ~= '' and FileMgr and FileMgr.CreateDir then direct_call(FileMgr.CreateDir, root) end
    local lines = {
        '# Minigames daily activity limits',
        '# Session Host + 20 players required to start. Unlimited starts are enabled for testing. WarGames remains 30 minutes per run.',
        'rules_version=214',
        'date=' .. tostring(L.State.date or today_key()),
    }
    for _, key in ipairs(L.GameOrder) do
        local entry = ensure_game_state(key)
        lines[#lines + 1] = key .. '_used=' .. tostring(entry.used == true)
        lines[#lines + 1] = key .. '_started_at=' .. tostring(math.floor(tonumber(entry.startedAt or 0) or 0))
        lines[#lines + 1] = key .. '_start_count=' .. tostring(math.floor(tonumber(entry.startCount or 0) or 0))
    end
    local body = table.concat(lines, '\n') .. '\n'

    local wrote = false
    local f = io.open(L.TempPath, 'wb')
    if f then
        f:write(body)
        f:close()
        wrote = true
    elseif FileMgr and FileMgr.WriteFileContent then
        local ok, result = direct_call(FileMgr.WriteFileContent, L.TempPath, body, false)
        wrote = ok and result ~= false
    end
    if not wrote then return false end

    direct_call(os.remove, L.Path)
    local renamed = os.rename(L.TempPath, L.Path)
    if not renamed then
        local out = io.open(L.Path, 'wb')
        if out then out:write(body); out:close(); direct_call(os.remove, L.TempPath); return true end
        if FileMgr and FileMgr.WriteFileContent then
            local ok, result = direct_call(FileMgr.WriteFileContent, L.Path, body, false)
            direct_call(os.remove, L.TempPath)
            return ok and result ~= false
        end
        return false
    end
    return true
end

function L.Load()
    local state = new_day_state(today_key())
    local body = read_file(L.Path)
    local rulesVersion = ''
    if body and body ~= '' then
        local values = {}
        for line in body:gmatch('[^\r\n]+') do
            local key, value = line:match('^%s*([%w_]+)%s*=%s*(.-)%s*$')
            if key and value then values[key] = value end
        end
        rulesVersion = tostring(values.rules_version or '')
        state.date = tostring(values.date or state.date)
        for _, key in ipairs(L.GameOrder) do
            local entry = state.games[key]
            entry.used = parse_bool(values[key .. '_used']) == true
            entry.startedAt = tonumber(values[key .. '_started_at'] or 0) or 0
            entry.startCount = tonumber(values[key .. '_start_count'] or 0) or 0
        end
        -- v0.212 counted test activations internally while deliberately not
        -- consuming daily access. clear those temporary counts exactly once.
        if rulesVersion ~= '214' then
            local warGames = state.games.wargames
            if warGames and warGames.used ~= true then
                warGames.startedAt = 0
                warGames.startCount = 0
            end
        end
    end
    L.State = state
    L.EnsureCurrentDay()
    if rulesVersion ~= '214' then L.Save() end
end

function L.EnsureCurrentDay()
    local day = today_key()
    if tostring(L.State.date or '') == day then return false end

    local previousRuntime = {}
    for _, key in ipairs(L.GameOrder) do
        local runtime = L.Runtime[key] or {}
        previousRuntime[key] = runtime.active == true
    end

    L.State = new_day_state(day)
    -- a game crossing midnight consumes the new day's activation too. this
    -- prevents a single uninterrupted run from being followed by another full
    -- run immediately after it ends in the same calendar day.
    for _, key in ipairs(L.GameOrder) do
        if previousRuntime[key] then
            local entry = ensure_game_state(key)
            entry.startedAt = tonumber(L.Runtime[key].startedEpoch or os.time()) or os.time()
            entry.startCount = 1
            entry.used = entry.startCount >= (tonumber(L.MaximumStartsPerDay[key] or 1) or 1)
        end
    end
    L.Save()
    log('Daily limit state reset for ' .. day)
    return true
end

function L.GetSessionPlayerCount()
    local best = nil
    if Players and Players.Get then
        local ok, list = direct_call(Players.Get)
        if ok and type(list) == 'table' then
            local count = 0
            for _ in pairs(list) do count = count + 1 end
            if count > 0 then best = count end
        end
    end
    local tracked = tonumber(minigames.S.activePlayerCount)
    if tracked and tracked > 0 and (not best or tracked > best) then best = tracked end
    if type(minigames.S.activePlayers) == 'table' then
        local count = 0
        for _ in pairs(minigames.S.activePlayers) do count = count + 1 end
        if count > 0 and (not best or count > best) then best = count end
    end
    return best
end

function L.GetMaximumStartsPerDay(key)
    return math.max(1, math.floor(tonumber((L.MaximumStartsPerDay or {})[key] or 1) or 1))
end

function L.GetRuntimeLimitSeconds(key)
    if key == 'wargames' then return tonumber(L.WarGamesMaximumRuntimeSeconds or 1800) or 1800 end
    return tonumber(L.MaximumRuntimeSeconds or 3600) or 3600
end

function L.GetStartsUsed(key)
    L.EnsureCurrentDay()
    local entry = ensure_game_state(key)
    return math.max(0, math.floor(tonumber(entry.startCount or 0) or 0))
end

function L.GetStartsRemaining(key)
    if L.UnlimitedDailyAccess == true or L.IgnoreDailyLimitForTesting == true then return -1 end
    return math.max(0, L.GetMaximumStartsPerDay(key) - L.GetStartsUsed(key))
end

function L.IsUsedToday(key)
    L.EnsureCurrentDay()
    if L.UnlimitedDailyAccess == true or L.IgnoreDailyLimitForTesting == true then return false end
    return L.GetStartsUsed(key) >= L.GetMaximumStartsPerDay(key)
end

function L.GetRuntimeRemainingSeconds(key)
    local runtime = L.Runtime[key] or {}
    local limit = L.GetRuntimeLimitSeconds(key)
    if runtime.active ~= true then return limit end
    local started = tonumber(runtime.startedEpoch or 0) or 0
    if started <= 0 then return limit end
    local now = os.time and os.time() or started
    return math.max(0, limit - math.max(0, now - started))
end

function L.GetDailyTimeRemainingSeconds(key)
    if L.UnlimitedDailyAccess == true or L.IgnoreDailyLimitForTesting == true then return -1 end
    local limit = L.GetRuntimeLimitSeconds(key)
    local remainingStarts = L.GetStartsRemaining(key)
    local runtime = L.Runtime[key] or {}
    if runtime.active == true then
        return L.GetRuntimeRemainingSeconds(key) + (remainingStarts * limit)
    end
    return remainingStarts * limit
end

L.NetworkHostPlayerHash = 0x8251FB94DC4FDFC8
L.LocalPlayerIdHash = 0x4F8644AF03D0E0D6

local function normalize_edition_code(value)
    local edition = string.upper(tostring(value or ''))
    edition = edition:gsub('^%s+', ''):gsub('%s+$', '')
    edition = edition:gsub('BATTLEYE', 'BE'):gsub('%s+', ' ')
    return edition
end

function L.GetEditionInfo()
    local raw = ''
    if Cherax and Cherax.GetEdition then
        direct_call(function() raw = normalize_edition_code(Cherax.GetEdition()) end)
    end

    if raw == 'LE' then return 'Standard/Premium (Legacy)', 'Standard/Premium', 'Legacy', false, true, raw end
    if raw == 'EE' then return 'Standard/Premium (Enhanced)', 'Standard/Premium', 'Enhanced', false, true, raw end
    if raw == 'LE BE' then return 'Prime (Legacy)', 'Prime', 'Legacy', true, true, raw end
    if raw == 'EE BE' then return 'Prime (Enhanced)', 'Prime', 'Enhanced', true, true, raw end
    return 'Unknown Cherax Edition', 'Unknown', 'Unknown', nil, false, raw ~= '' and raw or 'Unknown'
end

function L.GetLocalPlayerId()
    local value = nil
    if GTA and GTA.GetLocalPlayerId then
        local ok, result = direct_call(GTA.GetLocalPlayerId)
        if ok then value = tonumber(result) end
    end
    if (value == nil or value < 0 or value > 31) and Natives and Natives.InvokeInt then
        local ok, result = direct_call(Natives.InvokeInt, L.LocalPlayerIdHash)
        if ok then value = tonumber(result) end
    end
    if value == nil or value < 0 or value > 31 then return nil end
    return math.floor(value)
end

function L.GetSessionHostId()
    if not Natives or not Natives.InvokeInt then return nil end
    local ok, result = direct_call(Natives.InvokeInt, L.NetworkHostPlayerHash)
    local value = ok and tonumber(result) or nil
    if value == nil or value < 0 or value > 31 then return nil end
    return math.floor(value)
end

function L.GetPlayerNameSafe(playerId)
    playerId = tonumber(playerId)
    if playerId == nil then return 'Unknown' end
    if Players and Players.GetName then
        local ok, value = direct_call(Players.GetName, playerId)
        if ok and value and tostring(value) ~= '' then return tostring(value) end
    end
    if playerId == L.GetLocalPlayerId() then return 'You' end
    return 'Player ' .. tostring(playerId)
end

function L.IsLocalSessionHost()
    local localId = L.GetLocalPlayerId()
    local hostId = L.GetSessionHostId()
    if localId == nil then return false, 'Local player unavailable', nil, nil end
    if hostId == nil then return false, 'Session Host unavailable', nil, localId end
    if localId == hostId then return true, 'YOU ARE HOST', hostId, localId end
    return false, 'Host: ' .. L.GetPlayerNameSafe(hostId), hostId, localId
end

function L.CanStart(key, quiet)
    L.EnsureCurrentDay()
    local name = L.GameNames[key] or tostring(key)

    -- host is checked only when starting. a running game is deliberately not
    -- stopped if host changes later, matching the existing 20-player rule.
    local isHost, hostStatus = L.IsLocalSessionHost()
    if not isHost then
        if quiet ~= true then
            notify(name .. ' can only be started by the Session Host. ' .. tostring(hostStatus or 'Host status unavailable') .. '.', 6500)
        end
        return false, 'session-host-required'
    end

    local count = L.GetSessionPlayerCount()
    if not count then
        if quiet ~= true then notify(name .. ' cannot start until the session player list is available.', 5500) end
        return false, 'player-count-unavailable'
    end
    if count < L.MinimumPlayers then
        if quiet ~= true then
            notify(name .. ' requires 20 or more players to start. Current session: ' .. tostring(count) .. '.', 6000)
        end
        return false, 'under-player-minimum'
    end
    if L.UnlimitedDailyAccess ~= true and L.IgnoreDailyLimitForTesting ~= true and L.IsUsedToday(key) then
        if quiet ~= true then
            local maximum = L.GetMaximumStartsPerDay(key)
            notify(name .. ' has reached today\'s ' .. tostring(maximum) .. '-start limit.', 6500)
        end
        return false, 'daily-use-consumed'
    end
    return true, 'allowed'
end

function L.ReserveStart(key)
    local runtime = L.Runtime[key]
    if not runtime then return false end
    if runtime.active == true or runtime.reserved == true then return true end
    local allowed = L.CanStart(key, false)
    if not allowed then return false end
    runtime.reserved = true
    runtime.reservedAtMs = now_ms()
    return true
end

function L.CommitStart(key)
    local runtime = L.Runtime[key]
    if not runtime then return false end
    if runtime.active == true then return true end

    -- recheck session host and the full 20-player requirement at the exact
    -- activation commit point. a reservation never consumes daily access by
    -- itself and never lets a below-minimum session activate.
    local isHost, hostStatus = L.IsLocalSessionHost()
    if not isHost then
        notify((L.GameNames[key] or tostring(key)) .. ' activation cancelled. You are no longer Session Host. ' .. tostring(hostStatus or ''), 6500)
        runtime.reserved = false
        runtime.reservedAtMs = 0
        return false
    end

    local count = L.GetSessionPlayerCount()
    if not count or count < L.MinimumPlayers then
        local currentText = count and tostring(count) or 'unavailable'
        notify((L.GameNames[key] or tostring(key)) .. ' activation cancelled. 20 players are required at startup; current session: ' .. currentText .. '. Unlimited testing starts remain available.', 7000)
        runtime.reserved = false
        runtime.reservedAtMs = 0
        return false
    end

    local allowed = true
    if runtime.reserved ~= true then allowed = L.CanStart(key, false) end
    if not allowed then return false end

    runtime.active = true
    runtime.reserved = false
    runtime.reservedAtMs = 0
    runtime.startedEpoch = os.time and os.time() or 0
    runtime.startedMs = now_ms()

    if L.UnlimitedDailyAccess ~= true and L.IgnoreDailyLimitForTesting ~= true then
        local entry = ensure_game_state(key)
        entry.startedAt = runtime.startedEpoch
        entry.startCount = (tonumber(entry.startCount or 0) or 0) + 1
        entry.used = entry.startCount >= L.GetMaximumStartsPerDay(key)
        L.Save()
    end

    local limitMinutes = math.floor(L.GetRuntimeLimitSeconds(key) / 60)
    local used = L.GetStartsUsed(key)
    local maximum = L.GetMaximumStartsPerDay(key)
    if L.IgnoreDailyLimitForTesting == true then
        notify((L.GameNames[key] or tostring(key)) .. ' started. Unlimited starts are enabled for testing. Maximum runtime: ' .. tostring(limitMinutes) .. ' minutes.', 6500)
        log((L.GameNames[key] or key) .. ' activation committed | starts=unlimited-testing | runtimeMinutes=' .. tostring(limitMinutes))
    else
        notify((L.GameNames[key] or tostring(key)) .. ' started. Start ' .. tostring(used) .. ' of ' .. tostring(maximum) .. ' today. Maximum runtime: ' .. tostring(limitMinutes) .. ' minutes.', 6500)
        log((L.GameNames[key] or key) .. ' activation committed | starts=' .. tostring(used) .. '/' .. tostring(maximum) .. ' | runtimeMinutes=' .. tostring(limitMinutes))
    end
    return true
end

function L.MarkStopped(key)
    local runtime = L.Runtime[key]
    if not runtime then return end
    runtime.active = false
    runtime.reserved = false
    runtime.reservedAtMs = 0
    runtime.startedEpoch = 0
    runtime.startedMs = 0
end

local function get_feature(hash)
    if not hash or not FeatureMgr or not FeatureMgr.GetFeature then return nil end
    local ok, feature = direct_call(FeatureMgr.GetFeature, hash)
    if ok then return feature end
    return nil
end

local function feature_is_on(feature)
    if not feature or not feature.IsToggled then return false end
    local ok, value = direct_call(function() return feature:IsToggled() == true end)
    return ok and value == true
end

local function set_feature_on(featureOrHash, value)
    local feature = featureOrHash
    if type(featureOrHash) == 'number' or type(featureOrHash) == 'string' then
        feature = get_feature(featureOrHash)
    end
    if not feature then return false end
    local desired = value == true
    if feature_is_on(feature) == desired then return true end
    if feature.SetToggled then
        local ok = direct_call(function() feature:SetToggled(desired) end)
        if ok then return true end
    end
    if feature.SetBoolValue then
        local ok = direct_call(function() feature:SetBoolValue(desired) end)
        if ok then return true end
    end
    if feature.Toggle then
        local ok = direct_call(function() feature:Toggle(desired) end)
        if ok then return true end
        ok = direct_call(function() feature:Toggle() end)
        if ok then return true end
    end
    return false
end

local function wargames_active()
    if minigames.S.wargamesSystemsActive == true or minigames.S.wargamesActive == true or minigames.S.warGamesActive == true then return true end
    if minigames.H then
        if feature_is_on(get_feature(minigames.H.WARGAMES_ACTIVATE_SYSTEMS)) then return true end
        if feature_is_on(get_feature(minigames.H.WARGAMES_ACTIVATE_SYSTEMS_NO_BOUNTIES)) then return true end
    end
    return false
end

local function purge_active()
    return G and G.run and G.run.active == true
end

local function landonit_active()
    if minigames.LandOnIt and minigames.LandOnIt.S and minigames.LandOnIt.S.active == true then return true end
    if minigames.LandOnIt and minigames.LandOnIt.H then
        return feature_is_on(get_feature(minigames.LandOnIt.H.ACTIVATE))
    end
    return false
end

local function actual_active(key)
    if key == 'wargames' then return wargames_active() end
    if key == 'purge' then return purge_active() end
    if key == 'landonit' then return landonit_active() end
    return false
end

local function stop_for_limit(key)
    if L._internalStop == true then return end
    L._internalStop = true
    if key == 'wargames' then
        if minigames.RequestWarGamesModeV169 then direct_call(minigames.RequestWarGamesModeV169, 'off') end
        if minigames.H then
            set_feature_on(minigames.H.WARGAMES_ACTIVATE_SYSTEMS, false)
            set_feature_on(minigames.H.WARGAMES_ACTIVATE_SYSTEMS_NO_BOUNTIES, false)
        end
        if minigames.WarGames and minigames.WarGames.DeactivateSystems then direct_call(minigames.WarGames.DeactivateSystems) end
    elseif key == 'purge' then
        if G and G.Abandon and purge_active() then direct_call(G.Abandon) end
    elseif key == 'landonit' then
        if minigames.LandOnIt and minigames.LandOnIt.H then set_feature_on(minigames.LandOnIt.H.ACTIVATE, false) end
        if minigames.LandOnIt and minigames.LandOnIt.S then minigames.LandOnIt.S.active = false end
        if minigames.SetLandOnItActive then direct_call(minigames.SetLandOnItActive, false) end
    end
    L.MarkStopped(key)
    L._internalStop = false
    local limitMinutes = math.floor(L.GetRuntimeLimitSeconds(key) / 60)
    notify((L.GameNames[key] or tostring(key)) .. ' ended after reaching the ' .. tostring(limitMinutes) .. '-minute runtime limit.', 7000)
    log((L.GameNames[key] or key) .. ' stopped at ' .. tostring(limitMinutes) .. '-minute limit')
end

-- main wargames ui routing. off is always permitted. starting reserves the
-- daily use, then the first successful systems tick commits it.
local previousRequestWarGames = minigames.RequestWarGamesModeV169
if previousRequestWarGames then
    function minigames.RequestWarGamesModeV169(mode)
        mode = tostring(mode or 'off')
        if (mode == 'bounties' or mode == 'no_bounties') and not wargames_active() and L.Runtime.wargames.active ~= true then
            if not L.ReserveStart('wargames') then return false end
        end
        return previousRequestWarGames(mode)
    end
end

local function guard_wargames_tick(original, feature, ...)
    local on = feature_is_on(feature)
    if on and L.Runtime.wargames.active ~= true then
        if L.Runtime.wargames.reserved ~= true and not L.CanStart('wargames', false) then
            set_feature_on(feature, false)
            return true
        end
        if not L.CommitStart('wargames') then
            set_feature_on(feature, false)
            return true
        end
    end
    return original(feature, ...)
end

local previousSystemsTick = minigames.WarGames and minigames.WarGames.SystemsTick
if previousSystemsTick then
    function minigames.WarGames.SystemsTick(feature, ...)
        return guard_wargames_tick(previousSystemsTick, feature, ...)
    end
end

local previousSystemsNoBountyTick = minigames.WarGames and minigames.WarGames.SystemsNoBountyTick
if previousSystemsNoBountyTick then
    function minigames.WarGames.SystemsNoBountyTick(feature, ...)
        return guard_wargames_tick(previousSystemsNoBountyTick, feature, ...)
    end
end

-- the purge start is synchronous, so daily use is committed only after its own
-- eligibility/settings checks successfully create an active run.
local previousPurgeStart = G and G.Start
if previousPurgeStart then
    function G.Start(...)
        if purge_active() then return previousPurgeStart(...) end
        if not L.CanStart('purge', false) then return false end
        local result = previousPurgeStart(...)
        if result ~= false and purge_active() then L.CommitStart('purge') end
        return result
    end
end

-- land on it's original feature callback writes s.active before calling setstatus.
-- intercept that same callback path so a blocked activation is reversed immediately.
local previousLandStatus = minigames.LandOnIt and minigames.LandOnIt.SetStatus
if previousLandStatus then
    function minigames.LandOnIt.SetStatus(status)
        local text = tostring(status or '')
        if text:find('active=true', 1, true) and L.Runtime.landonit.active ~= true then
            if not L.CommitStart('landonit') then
                if minigames.LandOnIt.H then set_feature_on(minigames.LandOnIt.H.ACTIVATE, false) end
                minigames.LandOnIt.S.active = false
                if minigames.SetLandOnItActive then direct_call(minigames.SetLandOnItActive, false) end
                return previousLandStatus('Land On It active=false | activation blocked by Minigames limits')
            end
        elseif text:find('active=false', 1, true) then
            L.MarkStopped('landonit')
        end
        return previousLandStatus(status)
    end
end

local function format_remaining(seconds)
    seconds = math.max(0, math.floor(tonumber(seconds or 0) or 0))
    return string.format('%02d:%02d', math.floor(seconds / 60), seconds % 60)
end

function L.GetGameStatus(key)
    L.EnsureCurrentDay()
    local runtime = L.Runtime[key] or {}
    if runtime.active == true then
        return 'ACTIVE  ' .. format_remaining(L.GetRuntimeRemainingSeconds(key)) .. ' left', 'green'
    end
    if L.UnlimitedDailyAccess == true or L.IgnoreDailyLimitForTesting == true then return 'UNLIMITED STARTS', 'purple' end
    local used = L.GetStartsUsed(key)
    local maximum = L.GetMaximumStartsPerDay(key)
    if used >= maximum then return 'USED  ' .. tostring(used) .. ' / ' .. tostring(maximum), 'gold' end
    return 'AVAILABLE  ' .. tostring(used) .. ' / ' .. tostring(maximum) .. ' used', 'cyan'
end

function L.RenderHomeNotice()
    local count = L.GetSessionPlayerCount()
    local countText = count and (tostring(count) .. ' / ' .. tostring(L.MinimumPlayers)) or 'Waiting...'
    local countTone = count and count >= L.MinimumPlayers and 'green' or 'red'
    local editionLabel, _, _, isPrime, recognizedEdition = L.GetEditionInfo()
    local editionTone = recognizedEdition and (isPrime == true and 'purple' or 'cyan') or 'gold'
    local isHost, hostStatus = L.IsLocalSessionHost()
    local hostTone = isHost and 'green' or 'red'
    local accessTone = isHost and count and count >= L.MinimumPlayers and 'green' or 'red'
    local function body()
        if UI.StatusRow then
            UI.StatusRow('Cherax Edition', editionLabel, editionTone)
            UI.StatusRow('Session Host', hostStatus, hostTone)
            UI.StatusRow('Players to Start', countText, countTone)
            UI.StatusRow('WarGames Access', 'Unlimited starts for testing', 'purple')
            UI.StatusRow('WarGames Runtime', '30 minutes per start', 'cyan')
            UI.StatusRow('Other Playable Games', 'Unlimited starts / 60 minutes each', 'dim')
            for _, key in ipairs(L.GameOrder) do
                local status, tone = L.GetGameStatus(key)
                UI.StatusRow(L.GameNames[key], status, tone)
            end
        else
            UI.Text(editionLabel, editionTone)
            UI.Text('Session Host: ' .. tostring(hostStatus), hostTone)
            UI.Text('20+ players required to start.', countTone)
            UI.Text('Unlimited starts are enabled for testing. WarGames remains 30 minutes per run; other playable games remain 60 minutes per run.', 'purple', true)
        end
        UI.Text('Only the Session Host can activate a minigame.', 'white', true)
        UI.Text('A running game stays on if host changes or the lobby later falls below 20 players.', 'dim', true)
    end

    if UI.Child then
        UI.Child('Minigames_Access_Rules_V213', 'ACCESS RULES', 'Host + 20 players required to start.', body, accessTone)
    else
        UI.Text('ACCESS RULES', accessTone)
        body()
    end
    if UI.Spacing then UI.Spacing(1) end
end

local previousRenderHome = UI.RenderHome
if previousRenderHome then
    function UI.RenderHome()
        L.RenderHomeNotice()
        return previousRenderHome()
    end
end

local function monitor_once()
    L.EnsureCurrentDay()
    local now = now_ms()
    for _, key in ipairs(L.GameOrder) do
        local runtime = L.Runtime[key]
        if runtime.reserved == true and now - (tonumber(runtime.reservedAtMs or now) or now) > 10000 then
            runtime.reserved = false
            runtime.reservedAtMs = 0
        end

        local actual = actual_active(key)
        if actual and runtime.active ~= true then
            if not L.CommitStart(key) then
                stop_for_limit(key)
            end
        elseif not actual and runtime.active == true then
            L.MarkStopped(key)
        end

        if runtime.active == true and L.UnlimitedDailyAccess ~= true then
            local started = tonumber(runtime.startedEpoch or 0) or 0
            if started > 0 and (os.time and os.time() or started) - started >= L.GetRuntimeLimitSeconds(key) then
                stop_for_limit(key)
            end
        end
    end
end

L.Load()
if Script and Script.RegisterLooped then
    Script.RegisterLooped(function()
        monitor_once()
        if Script.Yield then Script.Yield(500) end
    end)
elseif Script and Script.QueueJob then
    Script.QueueJob(function()
        while true do
            monitor_once()
            if Script.Yield then Script.Yield(500) else break end
        end
    end)
end

if Script and Script.QueueJob then
    Script.QueueJob(function()
        if Script.Yield then Script.Yield(2200) end
        notify('Unlimited starts are enabled for testing. WarGames remains 30 minutes per run. Session Host + 20 players are still required.', 7500)
    end)
end

minigames.VERSION = 'v0.204-alpha'
minigames.BUILD_DATE = '2026-07-31'
minigames.S.usageLimitsBuildV203 = true
minigames.S.usageLimitsBuildV204 = true
minigames.S.usageLimitsBuildV205 = true
minigames.S.minimumPlayersToStartV203 = L.MinimumPlayers
minigames.S.maximumMinigameRuntimeSecondsV203 = L.MaximumRuntimeSeconds
minigames.S.warGamesMaximumRuntimeSecondsV213 = L.WarGamesMaximumRuntimeSeconds
minigames.S.warGamesMaximumStartsPerDayV213 = L.WarGamesMaximumStartsPerDay
minigames.S.dailyMinigameUsagePathV203 = L.Path
minigames.S.unlimitedDailyStartsTestingV212 = true
minigames.S.warGamesThreeStartsThirtyMinutesV213 = false
minigames.S.unlimitedStartsTestingV214 = true
local detectedEditionLabel, detectedTier, detectedFamily, detectedPrime, detectedRecognized, detectedRaw = L.GetEditionInfo()
minigames.S.detectedCheraxEditionV204 = detectedEditionLabel
minigames.S.detectedCheraxTierV204 = detectedTier
minigames.S.detectedCheraxGameFamilyV204 = detectedFamily
