minigames.S.detectedCheraxEditionRecognizedV204 = detectedRecognized == true
minigames.S.detectedCheraxEditionCodeV204 = detectedRaw
log('Loaded | Session Host + 20-player activation gate | edition=' .. tostring(detectedEditionLabel) .. ' | unlimited starts testing | WarGames 30 minutes per run | other games 60 minutes per run')
end


-- ============================================================
-- embedded module: systems\access_gui_v205.lua
-- ============================================================
embedded_modules['systems\\access_gui_v205.lua'] = function()
-- minigames v0.205-alpha
-- interactive wargames access confirmation and blocked-use messaging.

minigames = minigames or {}
minigames.S = minigames.S or {}
minigames.AccessPopupV205 = minigames.AccessPopupV205 or {}
local P = minigames.AccessPopupV205
local L = minigames.UsageLimits

P.visible = P.visible == true
P.kind = P.kind or 'confirm'
P.gameKey = P.gameKey or 'wargames'
P.mode = P.mode or 'no_bounties'
P.reason = P.reason or 'allowed'
P.title = P.title or 'WARGAMES ACCESS'
P.message = P.message or ''
P.detail = P.detail or ''
P._bypassRequest = false
P._legacyPromptOpen = false
P.Generation = (tonumber(_G.MinigamesAccessPopupGenerationV205 or 0) or 0) + 1
_G.MinigamesAccessPopupGenerationV205 = P.Generation
local generation = P.Generation

local function count_players()
    return L and L.GetSessionPlayerCount and L.GetSessionPlayerCount() or nil
end

local function host_status()
    if L and L.IsLocalSessionHost then
        local isHost, status = L.IsLocalSessionHost()
        return isHost == true, tostring(status or 'Session Host unavailable')
    end
    return false, 'Session Host unavailable'
end

local function used_today()
    return L and L.IsUsedToday and L.IsUsedToday('wargames') == true
end

local function is_wargames_active()
    if L and L.Runtime and L.Runtime.wargames and L.Runtime.wargames.active == true then return true end
    return minigames.S.wargamesSystemsActive == true or minigames.S.wargamesActive == true or minigames.S.warGamesActive == true
end

local function popup_text_for_reason(reason)
    local count = count_players()
    local isHost, hostText = host_status()
    if reason == 'daily-use-consumed' then
        return 'WARGAMES TESTING ACCESS',
            'Unlimited starts are currently enabled for testing.',
            'Each WarGames run remains limited to 30 minutes.'
    elseif reason == 'under-player-minimum' then
        return '20 PLAYERS REQUIRED',
            'WarGames needs at least 20 players before it can begin.',
            'Current session: ' .. tostring(count or 0) .. ' / 20. This attempt was not counted against today.'
    elseif reason == 'player-count-unavailable' then
        return 'PLAYER LIST NOT READY',
            'Minigames could not verify the session player count yet.',
            'Wait a moment and try again. This attempt was not counted against today.'
    elseif reason == 'session-host-required' then
        return 'SESSION HOST REQUIRED',
            'Only the Session Host can activate WarGames.',
            tostring(hostText) .. '. This attempt was not counted against today.'
    end
    return 'WARGAMES UNAVAILABLE',
        'WarGames cannot start right now.',
        'Host: ' .. tostring(isHost and 'Ready' or hostText) .. ' | Players: ' .. tostring(count or 0) .. ' / 20'
end

function P.ShowBlocked(reason, mode)
    P.kind = 'blocked'
    P.reason = tostring(reason or 'blocked')
    P.mode = tostring(mode or 'no_bounties')
    P.title, P.message, P.detail = popup_text_for_reason(P.reason)
    P.visible = true
    P.openedAtMs = Time and Time.GetEpocheMs and Time.GetEpocheMs() or 0
    return false
end

function P.ShowConfirm(mode)
    P.kind = 'confirm'
    P.reason = 'allowed'
    P.mode = tostring(mode or 'no_bounties')
    P.title = 'START WARGAMES?'
    P.message = 'Teleport the session into position, then activate WarGames Systems.'
    P.detail = 'Recommended: teleport everyone above you or to your waypoint first. Unlimited starts remain enabled for testing.'
    P.visible = true
    P.openedAtMs = Time and Time.GetEpocheMs and Time.GetEpocheMs() or 0
    return true
end

function P.Close()
    P.visible = false
    P._legacyPromptOpen = false
end

local previousRequestWarGamesV205 = minigames.RequestWarGamesModeV169
P.PreviousRequestWarGamesV205 = previousRequestWarGamesV205

if previousRequestWarGamesV205 then
    function minigames.RequestWarGamesModeV169(mode)
        mode = tostring(mode or 'off')

        if mode == 'off' then
            P.Close()
            return previousRequestWarGamesV205(mode)
        end

        -- bounty preference changes during an already-active wargames session do
        -- not open another start prompt or consume another daily activation.
        if is_wargames_active() or P._bypassRequest == true then
            return previousRequestWarGamesV205(mode)
        end

        local allowed, reason = L.CanStart('wargames', true)
        if not allowed then
            return P.ShowBlocked(reason, mode)
        end

        return P.ShowConfirm(mode)
    end
end

function P.ConfirmStart()
    local allowed, reason = L.CanStart('wargames', true)
    if not allowed then
        return P.ShowBlocked(reason, P.mode)
    end

    P._bypassRequest = true
    local ok, result = direct_call(previousRequestWarGamesV205, P.mode)
    P._bypassRequest = false

    if not ok or result == false then
        P.kind = 'blocked'
        P.title = 'WARGAMES COULD NOT START'
        P.message = 'The activation worker did not accept the request.'
        P.detail = 'No start was consumed. Unlimited testing starts remain available. Try again or create a Support ZIP.'
        P.visible = true
        return false
    end

    P.kind = 'starting'
    P.title = 'STARTING WARGAMES'
    P.message = 'The deferred WarGames activation worker has accepted the request.'
    P.detail = 'Unlimited testing starts remain available after WarGames systems come online.'
    P.startRequestedAtMs = Time and Time.GetEpocheMs and Time.GetEpocheMs() or 0
    P.visible = true
    return true
end

-- legacy feature toggles can bypass the minimalist ui. intercept their first
-- on tick, turn them back off, and route the user through the same confirmation.
local function wrap_legacy_tick(name, mode)
    if not minigames.WarGames or type(minigames.WarGames[name]) ~= 'function' then return end
    local original = minigames.WarGames[name]
    minigames.WarGames[name] = function(feature, ...)
        local on = false
        if feature and feature.IsToggled then
            local ok, value = direct_call(function() return feature:IsToggled() end)
            on = ok and value == true
        end

        local runtime = L.Runtime and L.Runtime.wargames or nil
        if on and not is_wargames_active() and not (runtime and runtime.reserved == true) and P._bypassRequest ~= true then
            if feature and feature.SetToggled then direct_call(function() feature:SetToggled(false) end) end
            local allowed, reason = L.CanStart('wargames', true)
            if allowed then P.ShowConfirm(mode) else P.ShowBlocked(reason, mode) end
            return true
        end
        return original(feature, ...)
    end
end

wrap_legacy_tick('SystemsTick', 'bounties')
wrap_legacy_tick('SystemsNoBountyTick', 'no_bounties')

-- replace the minimap-side compact wargames hud with the interactive activation
-- window. other minigames retain their existing hud behavior.
local previousCompactHudV205 = minigames.DrawCompactMinigamesHud
if previousCompactHudV205 then
    function minigames.DrawCompactMinigamesHud(...)
        if is_wargames_active() or P.visible == true then return end
        return previousCompactHudV205(...)
    end
end

local colors = {
    red = {0.95, 0.16, 0.12, 1.0},
    green = {0.26, 0.90, 0.42, 1.0},
    gold = {1.00, 0.72, 0.18, 1.0},
    cyan = {0.25, 0.82, 1.00, 1.0},
    white = {0.95, 0.95, 0.97, 1.0},
    dim = {0.62, 0.64, 0.70, 1.0},
}

local function text_colored(color, text)
    local c = colors[color] or colors.white
    ImGui.TextColored(c[1], c[2], c[3], c[4], tostring(text or ''))
end

local function status_row(label, value, color)
    ImGui.TextDisabled(tostring(label or ''))
    ImGui.SameLine()
    local x = ImGui.GetCursorPosX and ImGui.GetCursorPosX() or 0
    if ImGui.SetCursorPosX then ImGui.SetCursorPosX(math.max(x, 255)) end
    text_colored(color or 'white', value)
end

local function colored_button(label, base, hover, active, width, height)
    ImGui.PushStyleColor(ImGuiCol.Button, base[1], base[2], base[3], base[4])
    ImGui.PushStyleColor(ImGuiCol.ButtonHovered, hover[1], hover[2], hover[3], hover[4])
    ImGui.PushStyleColor(ImGuiCol.ButtonActive, active[1], active[2], active[3], active[4])
    local clicked = ImGui.Button(label, width, height)
    ImGui.PopStyleColor(3)
    return clicked == true
end

local function runtime_remaining_text()
    local remaining = L and L.GetRuntimeRemainingSeconds and L.GetRuntimeRemainingSeconds('wargames') or 1800
    remaining = math.max(0, math.floor(tonumber(remaining or 0) or 0))
    return string.format('%02d:%02d', math.floor(remaining / 60), remaining % 60)
end

local function starts_text()
    if L and L.IgnoreDailyLimitForTesting == true then return 'UNLIMITED' end
    local used = L and L.GetStartsUsed and L.GetStartsUsed('wargames') or 0
    local maximum = L and L.GetMaximumStartsPerDay and L.GetMaximumStartsPerDay('wargames') or 3
    return tostring(used) .. ' / ' .. tostring(maximum) .. ' USED'
end

local function daily_time_text()
    local remaining = L and L.GetDailyTimeRemainingSeconds and L.GetDailyTimeRemainingSeconds('wargames') or 5400
    if remaining < 0 then return 'UNLIMITED' end
    remaining = math.max(0, math.floor(remaining))
    return string.format('%02d:%02d:%02d', math.floor(remaining / 3600), math.floor((remaining % 3600) / 60), remaining % 60)
end

local function run_quick_action(action)
    if action == 'test' then
        if minigames.WarGames and minigames.WarGames.SpawnVehicleOnAll then
            direct_call(minigames.WarGames.SpawnVehicleOnAll, false)
        elseif minigames.TriggerFeature and minigames.H and minigames.H.WARGAMES_SPAWN_ALL then
            direct_call(minigames.TriggerFeature, minigames.H.WARGAMES_SPAWN_ALL)
        end
    elseif action == 'next' then
        if minigames.WarGames and minigames.WarGames.NextVehicle then
            direct_call(minigames.WarGames.NextVehicle)
        elseif minigames.TriggerFeature and minigames.H and minigames.H.WARGAMES_NEXT_VEHICLE then
            direct_call(minigames.TriggerFeature, minigames.H.WARGAMES_NEXT_VEHICLE)
        end
    elseif action == 'random' then
        if minigames.RandomVehicleRoundNow then
            direct_call(minigames.RandomVehicleRoundNow, 'v0.205 access GUI')
        elseif minigames.WarGames and minigames.WarGames.RollRandomRoundVehicle then
            direct_call(minigames.WarGames.RollRandomRoundVehicle)
        elseif minigames.TriggerFeature and minigames.H and minigames.H.WARGAMES_ROLL_RANDOM_ROUND_VEHICLE then
            direct_call(minigames.TriggerFeature, minigames.H.WARGAMES_ROLL_RANDOM_ROUND_VEHICLE)
        end
    end
end

P.quickTeleportBusy = P.quickTeleportBusy == true
P.lastRecommendedTeleport = P.lastRecommendedTeleport or 'Not used yet'

local function queue_recommended_teleport(label, callback)
    if P.quickTeleportBusy == true then
        if minigames.Toast then minigames.Toast('WarGames Setup', 'A teleport job is already running.', 3000) end
        return false
    end
    if not (Script and Script.QueueJob) then
        if minigames.Toast then minigames.Toast('WarGames Setup', 'Script.QueueJob is unavailable.', 4000) end
        return false
    end

    P.quickTeleportBusy = true
    P.lastRecommendedTeleport = tostring(label or 'Teleport') .. ' queued'
    Script.QueueJob(function()
        local ok, result, status = direct_call_trace(
            callback,
            debug and debug.traceback or function(err) return tostring(err) end
        )
        P.quickTeleportBusy = false

        if not ok then
            P.lastRecommendedTeleport = tostring(label or 'Teleport') .. ' failed'
            if minigames.LogError then minigames.LogError('[WarGames Setup] ' .. tostring(label) .. ' failed: ' .. tostring(result)) end
            if minigames.Toast then minigames.Toast('WarGames Setup', tostring(label) .. ' failed. Check Cherax.log.', 4500) end
            return
        end

        if result == false then
            P.lastRecommendedTeleport = tostring(label or 'Teleport') .. ': ' .. tostring(status or 'not completed')
        else
            P.lastRecommendedTeleport = tostring(label or 'Teleport') .. ' requested'
        end
    end)
    return true
end

local function teleport_players_above_me()
    if minigames.WarGames and minigames.WarGames.TeleportEveryoneAboveMeV150 then
        return minigames.WarGames.TeleportEveryoneAboveMeV150()
    end
    return false, 'Teleport Everyone Above Me is unavailable'
end

local function teleport_players_to_waypoint()
    if minigames.WarGames and minigames.WarGames.TeleportEveryoneToWaypointV150 then
        return minigames.WarGames.TeleportEveryoneToWaypointV150()
    end
    return false, 'Teleport Everyone To Waypoint is unavailable'
end

function P.Render()
    if P.visible ~= true then return end
    if _G.MinigamesAccessPopupGenerationV205 ~= generation then return end
    if not (ImGui and ImGui.Begin and ImGui.End and ImGui.GetDisplaySize) then return end

    if P.kind == 'starting' then
        if is_wargames_active() then
            P.kind = 'active'
            P.title = 'WARGAMES SYSTEMS ONLINE'
            P.message = 'WarGames is active. Respawn vehicles and random rounds are automatic.'
            P.detail = P.mode == 'bounties' and 'Current mode: Bounties ON.' or 'Current mode: Bounties OFF.'
        else
            local now = Time and Time.GetEpocheMs and Time.GetEpocheMs() or 0
            if tonumber(P.startRequestedAtMs or 0) > 0 and now - tonumber(P.startRequestedAtMs or 0) > 15000 then
                local allowed, reason = L.CanStart('wargames', true)
                if not allowed then
                    P.ShowBlocked(reason, P.mode)
                else
                    P.kind = 'blocked'
                    P.title = 'WARGAMES START TIMED OUT'
                    P.message = 'WarGames did not report that its systems came online.'
                    P.detail = 'Unlimited testing starts remain available. Try again after checking the WarGames systems.'
                end
            end
        end
    elseif P.kind == 'active' and not is_wargames_active() then
        P.Close()
        return
    end

    local pushedColors, pushedVars, began = 0, 0, false
    local ok, err = direct_call(function()
        local screenW, screenH = ImGui.GetDisplaySize()
        local windowW, windowH = 650, 535
        ImGui.SetNextWindowPos((screenW - windowW) / 2, (screenH - windowH) / 2, ImGuiCond.Always)
        ImGui.SetNextWindowSize(windowW, windowH, ImGuiCond.Always)
        if ImGui.SetNextWindowFocus then ImGui.SetNextWindowFocus() end

        ImGui.PushStyleColor(ImGuiCol.WindowBg, 0.035, 0.035, 0.045, 0.985); pushedColors = pushedColors + 1
        ImGui.PushStyleColor(ImGuiCol.Border, 0.86, 0.10, 0.08, 0.95); pushedColors = pushedColors + 1
        ImGui.PushStyleColor(ImGuiCol.Separator, 0.72, 0.10, 0.08, 0.75); pushedColors = pushedColors + 1
        ImGui.PushStyleVar(ImGuiStyleVar.WindowRounding, 10.0); pushedVars = pushedVars + 1
        ImGui.PushStyleVar(ImGuiStyleVar.WindowBorderSize, 2.0); pushedVars = pushedVars + 1
        ImGui.PushStyleVar(ImGuiStyleVar.WindowPadding, 24.0, 20.0); pushedVars = pushedVars + 1

        local flags = ImGuiWindowFlags.NoTitleBar + ImGuiWindowFlags.NoResize + ImGuiWindowFlags.NoMove + ImGuiWindowFlags.NoCollapse + ImGuiWindowFlags.NoScrollbar
        local open = ImGui.Begin('##MinigamesWarGamesAccessV205', true, flags)
        began = true
        if open then
            ImGui.SetWindowFontScale(1.35)
            text_colored('red', 'MINIGAMES  |  WARGAMES')
            ImGui.SetWindowFontScale(1.0)
            ImGui.Separator()
            ImGui.Spacing()

            local titleTone = (P.kind == 'confirm' or P.kind == 'active') and 'green' or (P.kind == 'starting' and 'gold' or 'red')
            text_colored(titleTone, P.title)
            ImGui.TextWrapped(tostring(P.message or ''))
            ImGui.Spacing()
            text_colored('dim', P.detail)
            ImGui.Spacing()
            ImGui.Separator()
            ImGui.Spacing()

            local count = count_players()
            local isHost, hostText = host_status()
            local modeText = P.mode == 'bounties' and 'Bounties ON' or 'Bounties OFF'
            status_row('Session Host', isHost and 'YOU ARE HOST' or hostText, isHost and 'green' or 'red')
            status_row('Players', tostring(count or 0) .. ' / 20 required', count and count >= 20 and 'green' or 'red')
            status_row('WarGames Mode', modeText, P.mode == 'bounties' and 'gold' or 'cyan')
            status_row('Starts Remaining', starts_text(), (L and L.IgnoreDailyLimitForTesting == true) and 'purple' or (used_today() and 'red' or 'green'))
            status_row(P.kind == 'active' and 'Run Time Left' or 'Maximum Runtime', P.kind == 'active' and runtime_remaining_text() or '30 MINUTES', 'cyan')
            status_row('Daily Time Remaining', daily_time_text(), 'gold')
            status_row('Activation Limit', (L and L.IgnoreDailyLimitForTesting == true) and 'UNLIMITED FOR TESTING' or '3 STARTS PER DAY', 'purple')

            if ImGui.ProgressBar then
                ImGui.Spacing()
                local fraction = math.min(1.0, math.max(0.0, (tonumber(count or 0) or 0) / 20.0))
                ImGui.ProgressBar(fraction, -1, 20, tostring(count or 0) .. ' / 20 PLAYERS')
            end

            ImGui.Spacing()
            ImGui.Separator()
            ImGui.Spacing()

            if P.kind == 'confirm' then
                text_colored('gold', 'RECOMMENDED: Teleport everyone first, then activate WarGames Systems.')
                text_colored('dim', 'Choose Above Me for your current area, or set a waypoint and use To Waypoint.')
                ImGui.Spacing()
                if colored_button('TELEPORT PLAYERS ABOVE ME##MinigamesWGSetupAboveV101', {0.10,0.34,0.62,1}, {0.14,0.46,0.78,1}, {0.07,0.25,0.48,1}, 285, 38) then
                    queue_recommended_teleport('Players Above Me', teleport_players_above_me)
                end
                ImGui.SameLine()
                if colored_button('TELEPORT PLAYERS TO WAYPOINT##MinigamesWGSetupWaypointV101', {0.08,0.48,0.58,1}, {0.12,0.62,0.74,1}, {0.05,0.36,0.46,1}, 285, 38) then
                    queue_recommended_teleport('Players To Waypoint', teleport_players_to_waypoint)
                end
                ImGui.Spacing()
                text_colored('dim', 'Setup Status: ' .. tostring(P.lastRecommendedTeleport or 'Not used yet'))
                ImGui.Spacing()
                if colored_button('ACTIVATE WARGAMES SYSTEMS##MinigamesWGConfirmV101', {0.10,0.58,0.22,1}, {0.14,0.72,0.29,1}, {0.08,0.45,0.17,1}, 285, 42) then
                    P.ConfirmStart()
                end
                ImGui.SameLine()
                if colored_button('CANCEL##MinigamesWGCancelV101', {0.45,0.10,0.10,1}, {0.62,0.14,0.14,1}, {0.34,0.07,0.07,1}, 285, 42) then
                    P.Close()
                end
            elseif P.kind == 'active' then
                text_colored('green', 'WarGames is live. Use the quick controls below or close this window.')
                ImGui.Spacing()
                if colored_button('TEST##MinigamesWGTestV205', {0.34,0.16,0.58,1}, {0.44,0.22,0.72,1}, {0.26,0.11,0.46,1}, 180, 38) then run_quick_action('test') end
                ImGui.SameLine()
                if colored_button('NEXT VEHICLE##MinigamesWGNextV205', {0.08,0.42,0.58,1}, {0.12,0.56,0.74,1}, {0.05,0.32,0.46,1}, 180, 38) then run_quick_action('next') end
                ImGui.SameLine()
                if colored_button('RANDOM##MinigamesWGRandomV205', {0.64,0.42,0.08,1}, {0.80,0.56,0.12,1}, {0.50,0.31,0.05,1}, 180, 38) then run_quick_action('random') end
                ImGui.Spacing()
                if colored_button('CLOSE WINDOW##MinigamesWGActiveCloseV205', {0.35,0.10,0.10,1}, {0.52,0.14,0.14,1}, {0.26,0.07,0.07,1}, -1, 34) then P.Close() end
            elseif P.kind == 'starting' then
                text_colored('gold', 'Starting systems. Please wait...')
                ImGui.Spacing()
                if colored_button('CLOSE WINDOW##MinigamesWGStartingCloseV205', {0.35,0.10,0.10,1}, {0.52,0.14,0.14,1}, {0.26,0.07,0.07,1}, -1, 38) then P.Close() end
            else
                text_colored('green', 'Blocked attempts do not affect unlimited testing access.')
                ImGui.Spacing()
                if colored_button('OK##MinigamesWGBlockedOKV205', {0.55,0.10,0.09,1}, {0.72,0.14,0.12,1}, {0.42,0.07,0.06,1}, -1, 42) then
                    P.Close()
                end
            end
        end
    end)

    if began then direct_call(ImGui.End) end
    if pushedVars > 0 and ImGui.PopStyleVar then direct_call(ImGui.PopStyleVar, pushedVars) end
    if pushedColors > 0 and ImGui.PopStyleColor then direct_call(ImGui.PopStyleColor, pushedColors) end

    if not ok then
        P.visible = false
        if minigames.LogError then minigames.LogError('[Access GUI v0.205] render error: ' .. tostring(err)) end
    end
end

if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_PRESENT then
    direct_call(function() EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, P.Render) end)
end

minigames.S.accessGuiBuildV205 = true
minigames.S.warGamesInteractiveActivationV205 = true
minigames.S.hideCompactWarGamesHudV205 = true
minigames.VERSION = 'v0.205-alpha'
minigames.BUILD_DATE = '2026-08-02'
end

-- ============================================================
