embedded_modules['systems\\messenger_v206.lua'] = function()
-- minigames v0.207-alpha
-- gta phone-text-only messenger. session host is not required for messaging.
-- all native/network work is queued outside clickgui rendering.

minigames = minigames or {}
minigames.S = minigames.S or {}
minigames.Messenger = minigames.Messenger or {}
minigames.UIX = minigames.UIX or {}

local M = minigames.Messenger
local UI = minigames.UIX
local Limits = minigames.UsageLimits or {}

M.Native = {
    NETWORK_SEND_TEXT_MESSAGE = 0x3A214F2EC889B100,
    NETWORK_HANDLE_FROM_PLAYER = 0x388EB2B86C73B6B3,
    NETWORK_IS_HANDLE_VALID = 0x6F79B93B0A8E4133,
}

M.Path = tostring(minigames.ROOT or ((os.getenv('USERPROFILE') or '.') .. '\\Documents\\Cherax\\Lua\\Minigames')) .. '\\messenger.ini'
M.TempPath = M.Path .. '.tmp'
M.ProbeDir = tostring(minigames.ROOT or ((os.getenv('USERPROFILE') or '.') .. '\\Documents\\Cherax\\Lua\\Minigames')) .. '\\Diagnostics'
M.ProbePath = M.ProbeDir .. '\\messenger_phone_probe.log'
M.MaxMessageLength = 64
M.Settings = M.Settings or {
    autoEnabled = false,
    phoneEnabled = true,
    chatFallback = false,
    deliveryMode = 0, -- phone text only
    messageLabel = 'EVENT CONTROL',
    recipientMode = 0, -- 0 everyone, 1 selected player
    selectedPlayerId = -1,
    draft = '',
    newQuickReply = '',
    recipientDelayMs = 900,
    announceStart = true,
    announceVote = true,
    announceMinute = true,
    announceVehicle = true,
    announceRoundStart = true,
    announceEnd = true,
}

M.CustomReplies = M.CustomReplies or {}
M.History = M.History or {}
M.PlayerCache = M.PlayerCache or {}
M.Pending = M.Pending or {}
M.WorkerRunning = M.WorkerRunning == true
M.LastBroadcastMs = tonumber(M.LastBroadcastMs or 0) or 0
M.LastRefreshMs = tonumber(M.LastRefreshMs or 0) or 0
M.LastRecipientId = tonumber(M.LastRecipientId or -1) or -1
M.LastStatus = tostring(M.LastStatus or 'Ready')
M.LastTransport = tostring(M.LastTransport or 'Not tested')
M.LastResult = tostring(M.LastResult or 'No messages sent yet')
M.LastHandleRoute = tostring(M.LastHandleRoute or 'Not tested')
M.LastHandleStatus = tostring(M.LastHandleStatus or 'No handle probe yet')
M.LastPhonePlayer = tostring(M.LastPhonePlayer or 'None')
M.Stats = M.Stats or { broadcasts = 0, phoneSent = 0, chatSent = 0, failed = 0 }
M.Auto = M.Auto or {
    initialized = false,
    previousOnline = false,
    previousRoundIndex = -1,
    previousRoundStartedAt = 0,
    voteSentForRound = 0,
    minuteSentForRound = 0,
    lastTickMs = 0,
}

local DELIVERY_NAMES = {
    'Phone Text',
}

local BUILTIN_REPLIES = {
    { label = 'WarGames Started', text = 'WarGames is now active. Prepare for the first vehicle round.' },
    { label = 'Vote For Vehicle', text = 'What vehicle would you like next? Vote in chat!' },
    { label = 'One Minute', text = 'Next vehicle round begins in 1 minute!' },
    { label = 'Vehicle Chosen', text = 'Next vehicle chosen: {vehicle}.' },
    { label = 'Round Active', text = '{vehicle} Warfare is now active. Survive the round!' },
    { label = 'WarGames Ended', text = 'WarGames has ended. Thanks for playing!' },
    { label = 'The Purge', text = 'The Purge is now active. Stay inside Los Santos and survive.' },
    { label = 'Land On It', text = 'Land On It is starting. Get ready for the next landing challenge.' },
}

local function now_ms()
    if minigames.Now then
        local ok, value = direct_call(minigames.Now)
        if ok and tonumber(value) then return tonumber(value) end
    end
    if Time and Time.GetEpocheMs then
        local ok, value = direct_call(Time.GetEpocheMs)
        if ok and tonumber(value) then return tonumber(value) end
    end
    return math.floor((os.clock and os.clock() or 0) * 1000)
end

local function yield_ms(ms)
    if Script and Script.Yield then direct_call(Script.Yield, tonumber(ms or 0) or 0) end
end

local function notify(message, duration)
    message = tostring(message or '')
    duration = tonumber(duration or 5000) or 5000
    if minigames.Toast then
        local ok = direct_call(minigames.Toast, 'Minigames Messenger', message, duration)
        if ok then return end
    end
    if GUI and GUI.AddToast then direct_call(GUI.AddToast, 'Minigames Messenger', message, duration) end
end

local function log_info(message)
    if minigames.LogInfo then direct_call(minigames.LogInfo, '[Messenger] ' .. tostring(message or '')) end
end

local function log_error(message)
    if minigames.LogError then direct_call(minigames.LogError, '[Messenger] ' .. tostring(message or '')) end
end

local function append_probe(message)
    local line = tostring(message or ''):gsub('[\r\n]+', ' ')
    if FileMgr and FileMgr.CreateDir then direct_call(FileMgr.CreateDir, M.ProbeDir) end
    local file = io.open(M.ProbePath, 'ab')
    if not file then return false end
    local stamp = os.date and os.date('%Y-%m-%d %H:%M:%S') or tostring(now_ms())
    file:write('[' .. tostring(stamp) .. '] ' .. line .. '\n')
    file:close()
    return true
end

local function trim(value)
    return tostring(value or ''):gsub('^%s+', ''):gsub('%s+$', '')
end

local function clean_line(value)
    value = tostring(value or ''):gsub('[\r\n]+', ' '):gsub('|', '/')
    return trim(value)
end

local function cap_message(value)
    value = clean_line(value)
    if #value > M.MaxMessageLength then value = value:sub(1, M.MaxMessageLength) end
    return value
end

local function parse_bool(value, fallback)
    value = tostring(value or ''):lower()
    if value == 'true' or value == '1' or value == 'yes' or value == 'on' then return true end
    if value == 'false' or value == '0' or value == 'no' or value == 'off' then return false end
    return fallback == true
end

local function local_player_id()
    if Limits.GetLocalPlayerId then
        local ok, value = direct_call(Limits.GetLocalPlayerId)
        if ok and tonumber(value) then return math.floor(tonumber(value)) end
    end
    if GTA and GTA.GetLocalPlayerId then
        local ok, value = direct_call(GTA.GetLocalPlayerId)
        if ok and tonumber(value) then return math.floor(tonumber(value)) end
    end
    return -1
end

local function is_host()
    if Limits.IsLocalSessionHost then
        local ok, result, status = direct_call(Limits.IsLocalSessionHost)
        if ok then return result == true, tostring(status or '') end
    end
    return false, 'Session Host status unavailable'
end

local function wargames_online()
    if Limits.Runtime and Limits.Runtime.wargames and Limits.Runtime.wargames.active == true then return true end
    return minigames.S.wargamesSystemsActive == true or minigames.S.wargamesActive == true or minigames.S.warGamesActive == true
end

local function current_vehicle_label()
    local label = nil
    if minigames.GetVehicleLabelByIndex then
        direct_call(function() label = minigames.GetVehicleLabelByIndex(minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or 1) end)
    end
    if not label or tostring(label) == '' or tostring(label) == 'None' then
        label = minigames.S.currentRoundVehicleName or minigames.S.currentRoundVehicleModel or 'Unknown Vehicle'
    end
    return tostring(label or 'Unknown Vehicle')
end

local function session_player_count()
    if Limits.GetSessionPlayerCount then
        local ok, value = direct_call(Limits.GetSessionPlayerCount)
        if ok and tonumber(value) then return math.floor(tonumber(value)) end
    end
    return #M.PlayerCache + 1
end

function M.ExpandTemplate(message)
    message = tostring(message or '')
    message = message:gsub('{vehicle}', current_vehicle_label())
    message = message:gsub('{players}', tostring(session_player_count()))
    message = message:gsub('{time}', os.date and os.date('%H:%M') or '')
    return cap_message(message)
end

function M.FormatMessage(message)
    message = M.ExpandTemplate(message)
    local label = clean_line(M.Settings.messageLabel)
    if label ~= '' then message = '[' .. label .. '] ' .. message end
    return cap_message(message)
end

local function read_file(path)
    local f = io.open(tostring(path or ''), 'rb')
    if not f then return nil end
    local body = f:read('*a')
    f:close()
    return body
end

function M.Save()
    local root = tostring(minigames.ROOT or '')
    if root ~= '' and FileMgr and FileMgr.CreateDir then direct_call(FileMgr.CreateDir, root) end
    local S = M.Settings
    local lines = {
        '# Minigames Messenger settings',
        'auto_enabled=' .. tostring(S.autoEnabled == true),
        'phone_enabled=' .. tostring(S.phoneEnabled ~= false),
        'chat_fallback=false',
        'delivery_mode=0',
        'message_label=' .. clean_line(S.messageLabel),
        'recipient_delay_ms=' .. tostring(math.floor(tonumber(S.recipientDelayMs or 900) or 900)),
        'draft=' .. clean_line(S.draft),
        'announce_start=' .. tostring(S.announceStart ~= false),
        'announce_vote=' .. tostring(S.announceVote ~= false),
        'announce_minute=' .. tostring(S.announceMinute ~= false),
        'announce_vehicle=' .. tostring(S.announceVehicle ~= false),
        'announce_round_start=' .. tostring(S.announceRoundStart ~= false),
        'announce_end=' .. tostring(S.announceEnd ~= false),
    }
    for i = 1, math.min(#M.CustomReplies, 8) do
        lines[#lines + 1] = 'quick_' .. tostring(i) .. '=' .. clean_line(M.CustomReplies[i])
    end
    local body = table.concat(lines, '\n') .. '\n'
    local f = io.open(M.TempPath, 'wb')
    if not f then return false end
    f:write(body)
    f:close()
    direct_call(os.remove, M.Path)
    local ok = os.rename(M.TempPath, M.Path)
    if not ok then
        local out = io.open(M.Path, 'wb')
        if not out then return false end
        out:write(body)
        out:close()
        direct_call(os.remove, M.TempPath)
    end
    return true
end

function M.Load()
    local body = read_file(M.Path)
    if not body or body == '' then return false end
    local values = {}
    for line in body:gmatch('[^\r\n]+') do
        local key, value = line:match('^%s*([%w_]+)%s*=%s*(.-)%s*$')
        if key then values[key] = value end
    end
    local S = M.Settings
    S.autoEnabled = parse_bool(values.auto_enabled, S.autoEnabled)
    S.phoneEnabled = parse_bool(values.phone_enabled, S.phoneEnabled)
    S.chatFallback = false
    S.deliveryMode = 0
    S.messageLabel = clean_line(values.message_label or S.messageLabel)
    S.recipientDelayMs = math.max(500, math.min(2500, math.floor(tonumber(values.recipient_delay_ms or S.recipientDelayMs or 900) or 900)))
    S.draft = clean_line(values.draft or S.draft)
    S.announceStart = parse_bool(values.announce_start, S.announceStart)
    S.announceVote = parse_bool(values.announce_vote, S.announceVote)
    S.announceMinute = parse_bool(values.announce_minute, S.announceMinute)
    S.announceVehicle = parse_bool(values.announce_vehicle, S.announceVehicle)
    S.announceRoundStart = parse_bool(values.announce_round_start, S.announceRoundStart)
    S.announceEnd = parse_bool(values.announce_end, S.announceEnd)
    M.CustomReplies = {}
    for i = 1, 8 do
        local value = clean_line(values['quick_' .. tostring(i)])
        if value ~= '' then M.CustomReplies[#M.CustomReplies + 1] = value end
    end
    return true
end

local function player_name(playerId)
    if Limits.GetPlayerNameSafe then
        local ok, value = direct_call(Limits.GetPlayerNameSafe, playerId)
        if ok and value then return tostring(value) end
    end
    if Players and Players.GetName then
        local ok, value = direct_call(Players.GetName, playerId)
        if ok and value and tostring(value) ~= '' then return tostring(value) end
    end
    return 'Player ' .. tostring(playerId)
end

local function player_exists(playerId)
    if not Players or not Players.GetById then return false end
    local ok, player = direct_call(Players.GetById, tonumber(playerId) or -1)
    return ok and player ~= nil
end

function M.RefreshPlayers(force)
    local now = now_ms()
    if force ~= true and now - (M.LastRefreshMs or 0) < 2500 then return M.PlayerCache end
    M.LastRefreshMs = now
    local localId = local_player_id()
    local list = {}
    for playerId = 0, 31 do
        if playerId ~= localId and player_exists(playerId) then
            list[#list + 1] = { id = playerId, name = player_name(playerId) }
        end
    end
    table.sort(list, function(a, b) return tostring(a.name):lower() < tostring(b.name):lower() end)
    M.PlayerCache = list
    if M.Settings.selectedPlayerId ~= -1 then
        local found = false
        for _, entry in ipairs(list) do if entry.id == M.Settings.selectedPlayerId then found = true break end end
        if not found then M.Settings.selectedPlayerId = -1 end
    end
    return list
end

local function make_gamer_candidates(playerId)
    local candidates = {}
    local seen = {}

    local function add_candidate(buffer, route, rockstarId)
        if not buffer or not buffer.GetBuffer then return end
        local ptr, size = nil, nil
        direct_call(function()
            ptr = buffer:GetBuffer()
            if buffer.GetSize then size = buffer:GetSize() end
        end)
        ptr = tonumber(ptr)
        size = tonumber(size)
        if not ptr or ptr == 0 or seen[ptr] then return end
        seen[ptr] = true
        candidates[#candidates + 1] = {
            buffer = buffer,
            ptr = ptr,
            size = size or 0,
            route = tostring(route or 'Unknown'),
            rockstarId = tonumber(rockstarId),
        }
    end

    -- route 1: build a gamerhandle directly from the player's rockstar id.
    if Players and Players.GetById and GamerHandle and GamerHandle.New then
        local okPlayer, player = direct_call(Players.GetById, playerId)
        if okPlayer and player and player.GetGamerInfo then
            local okInfo, info = direct_call(function() return player:GetGamerInfo() end)
            local rid = okInfo and info and tonumber(info.RockstarId) or nil
            if rid then
                local okHandle, handle = direct_call(GamerHandle.New, rid)
                if okHandle and handle then
                    local valid = true
                    if handle.IsValid then
                        local okValid, result = direct_call(function() return handle:IsValid() end)
                        if okValid then valid = result == true end
                    end
                    if valid and handle.ToBuffer then
                        local okBuffer, buffer = direct_call(function() return handle:ToBuffer() end)
                        if okBuffer then add_candidate(buffer, 'RockstarId -> GamerHandle -> Buffer', rid) end
                    end
                end
            end
        end
    end

    -- route 2: let gta populate a fresh gamerhandlebuffer from the player index.
    if GamerHandleBuffer and GamerHandleBuffer.New and Natives and Natives.InvokeVoid then
        local okBuffer, buffer = direct_call(GamerHandleBuffer.New)
        if okBuffer and buffer and buffer.GetBuffer and buffer.GetSize then
            local ptr, size = nil, nil
            direct_call(function() ptr = buffer:GetBuffer(); size = buffer:GetSize() end)
            ptr, size = tonumber(ptr), tonumber(size)
            if ptr and ptr ~= 0 and size and size > 0 then
                local okFill = direct_call(Natives.InvokeVoid, M.Native.NETWORK_HANDLE_FROM_PLAYER, playerId, ptr, size)
                if okFill then
                    local valid = true
                    if Natives.InvokeBool then
                        local okValid, result = direct_call(Natives.InvokeBool, M.Native.NETWORK_IS_HANDLE_VALID, ptr, size)
                        if okValid then valid = result == true end
                    end
                    if valid then add_candidate(buffer, 'NETWORK_HANDLE_FROM_PLAYER -> Buffer', nil) end
                end
            end
        end
    end

    return candidates
end

function M.SendPhoneText(playerId, message)
    if M.Settings.phoneEnabled == false then return false, 'phone-disabled' end
    if not Natives or not Natives.InvokeBool then return false, 'native-api-unavailable' end

    local name = player_name(playerId)
    M.LastPhonePlayer = tostring(name) .. ' [' .. tostring(playerId) .. ']'
    local candidates = make_gamer_candidates(playerId)
    if #candidates == 0 then
        M.LastHandleRoute = 'Unavailable'
        M.LastHandleStatus = 'No valid GamerHandle candidate'
        append_probe('player=' .. tostring(playerId) .. ' name=' .. tostring(name) .. ' result=no-handle-candidate')
        return false, 'gamer-handle-unavailable'
    end

    local failures = {}
    for index, candidate in ipairs(candidates) do
        M.LastHandleRoute = candidate.route
        M.LastHandleStatus = 'Trying route ' .. tostring(index) .. '/' .. tostring(#candidates)
        local ok, result = direct_call(Natives.InvokeBool, M.Native.NETWORK_SEND_TEXT_MESSAGE, tostring(message), candidate.ptr)
        local detail = 'player=' .. tostring(playerId) ..
            ' name=' .. tostring(name) ..
            ' route=' .. tostring(candidate.route) ..
            ' bufferSize=' .. tostring(candidate.size or 0) ..
            ' rid=' .. tostring(candidate.rockstarId or 'n/a') ..
            ' nativeOk=' .. tostring(ok) ..
            ' nativeResult=' .. tostring(result)
        append_probe(detail)
        if ok and result == true then
            M.LastHandleStatus = 'Phone native returned true'
            return true, 'phone-text via ' .. tostring(candidate.route)
        end
        failures[#failures + 1] = tostring(candidate.route) .. ': ' .. (ok and 'native-returned-false' or tostring(result))
        yield_ms(50)
    end

    M.LastHandleStatus = table.concat(failures, ' | ')
    return false, M.LastHandleStatus
end

function M.SendChatToPlayer(playerId, message)
    if not GTA or not GTA.SendChatMessageToPlayer then return false, 'chat-api-unavailable' end
    local ok, err = direct_call(GTA.SendChatMessageToPlayer, playerId, tostring(message), false)
    if ok then return true, 'session-chat' end
    return false, tostring(err)
end

function M.SendOne(playerId, message, deliveryMode)
    -- v0.207 is deliberately phone-only. no host check and no session-chat fallback.
    return M.SendPhoneText(playerId, message)
end

local function add_history(target, message, result, success)
    local timeText = os.date and os.date('%H:%M:%S') or tostring(now_ms())
    table.insert(M.History, 1, {
        time = timeText,
        target = tostring(target or 'Unknown'),
        message = tostring(message or ''),
        result = tostring(result or ''),
        success = success == true,
    })
    while #M.History > 30 do table.remove(M.History) end
end

local function collect_recipients(mode, selectedPlayerId)
    M.RefreshPlayers(true)
    if mode == 'selected' then
        local id = tonumber(selectedPlayerId or -1) or -1
        if id >= 0 and player_exists(id) then return { { id = id, name = player_name(id) } } end
        return {}
    end
    local out = {}
    for _, entry in ipairs(M.PlayerCache) do out[#out + 1] = { id = entry.id, name = entry.name } end
    return out
end

function M.QueueMessage(message, mode, selectedPlayerId, source, options)
    message = M.FormatMessage(message)
    if message == '' then notify('Enter a message first.', 3500); return false end
    if #M.Pending >= 10 then notify('Messenger queue is full. Please wait.', 4000); return false end
    M.Pending[#M.Pending + 1] = {
        message = message,
        mode = tostring(mode or 'everyone'),
        selectedPlayerId = tonumber(selectedPlayerId or -1) or -1,
        source = tostring(source or 'manual'),
        requiresWarGames = options and options.requiresWarGames == true,
        queuedAt = now_ms(),
    }
    M.LastStatus = 'Queued: ' .. tostring(source or 'message')
    M.StartWorker()
    return true
end

function M.StartWorker()
    if M.WorkerRunning then return end
    if not Script or not Script.QueueJob then
        M.LastStatus = 'Script.QueueJob unavailable'
        notify('Messenger cannot start because Script.QueueJob is unavailable.', 5500)
        return
    end
    M.WorkerRunning = true
    Script.QueueJob(function()
        while #M.Pending > 0 do
            local request = table.remove(M.Pending, 1)
            if request.requiresWarGames and not wargames_online() then
                add_history('Automatic', request.message, 'Skipped because WarGames ended', false)
            else
                local recipients = collect_recipients(request.mode, request.selectedPlayerId)
                if #recipients == 0 then
                    M.LastStatus = 'No valid recipients'
                    add_history('Nobody', request.message, 'No valid recipients', false)
                else
                    local sent, failed, phoneCount, chatCount = 0, 0, 0, 0
                    for _, recipient in ipairs(recipients) do
                        if player_exists(recipient.id) then
                            local ok, transport = M.SendOne(recipient.id, request.message, M.Settings.deliveryMode)
                            if ok then
                                sent = sent + 1
                                M.LastRecipientId = recipient.id
                                if tostring(transport):find('phone%-text') then phoneCount = phoneCount + 1 else chatCount = chatCount + 1 end
                            else
                                failed = failed + 1
                                log_error('Send failed | player=' .. tostring(recipient.id) .. ' | ' .. tostring(transport))
                            end
                            yield_ms(M.Settings.recipientDelayMs)
                        end
                    end
                    M.Stats.broadcasts = (M.Stats.broadcasts or 0) + 1
                    M.Stats.phoneSent = (M.Stats.phoneSent or 0) + phoneCount
                    M.Stats.chatSent = (M.Stats.chatSent or 0) + chatCount
                    M.Stats.failed = (M.Stats.failed or 0) + failed
                    M.LastTransport = phoneCount > 0 and 'Phone Text' or 'No delivery'
                    M.LastResult = 'Sent ' .. tostring(sent) .. ' | Failed ' .. tostring(failed)
                    M.LastStatus = M.LastResult
                    add_history(request.mode == 'selected' and player_name(request.selectedPlayerId) or 'Everyone', request.message, M.LastResult .. ' via ' .. M.LastTransport, sent > 0)
                    log_info('Broadcast complete | source=' .. tostring(request.source) .. ' | recipients=' .. tostring(#recipients) .. ' | sent=' .. tostring(sent) .. ' | failed=' .. tostring(failed) .. ' | transport=' .. tostring(M.LastTransport))
                    if request.source == 'manual' then notify('Message complete. ' .. M.LastResult, 4500) end
                end
            end
            if #M.Pending > 0 then yield_ms(4500) end
        end
        M.WorkerRunning = false
    end)
end

function M.SendDraft()
    local mode = M.Settings.recipientMode == 1 and 'selected' or 'everyone'
    return M.QueueMessage(M.Settings.draft, mode, M.Settings.selectedPlayerId, 'manual')
end

function M.SendQuick(text, source)
    return M.QueueMessage(text, 'everyone', -1, source or 'quick')
end

function M.PreviewLocal(message)
    local formatted = M.FormatMessage(message)
    if formatted == '' then notify('Nothing to preview.', 3000); return false end
    if GTA and GTA.AddChatMessageToPool then
        local id = local_player_id()
        local ok = direct_call(GTA.AddChatMessageToPool, id >= 0 and id or 0, formatted, false)
        if ok then notify('Local preview added to your chat only.', 3000); return true end
    end
    notify(formatted, 5000)
    return true
end

local function queue_auto(message, source, requiresWarGames)
    if M.Settings.autoEnabled ~= true then return false end
    return M.QueueMessage(message, 'everyone', -1, source, { requiresWarGames = requiresWarGames == true })
end

function M.AutoTick()
    local now = now_ms()
    if now - (M.Auto.lastTickMs or 0) < 500 then return end
    M.Auto.lastTickMs = now
    M.RefreshPlayers(false)

    local online = wargames_online()
    local roundIndex = math.floor(tonumber(minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or -1) or -1)
    local roundStartedAt = tonumber(minigames.S.roundStartedAtMs or 0) or 0

    if not M.Auto.initialized then
        M.Auto.initialized = true
        M.Auto.previousOnline = online
        M.Auto.previousRoundIndex = roundIndex
        M.Auto.previousRoundStartedAt = roundStartedAt
        return
    end

    if online and not M.Auto.previousOnline and M.Settings.autoEnabled and M.Settings.announceStart ~= false then
        queue_auto('WarGames is now active. Prepare for the first vehicle round.', 'auto-start', true)
    elseif not online and M.Auto.previousOnline and M.Settings.autoEnabled and M.Settings.announceEnd ~= false then
        queue_auto('WarGames has ended. Thanks for playing!', 'auto-end', false)
    end

    if online then
        local roundChanged = roundIndex ~= M.Auto.previousRoundIndex or (roundStartedAt > 0 and roundStartedAt ~= M.Auto.previousRoundStartedAt)
        if roundChanged and roundIndex >= 0 then
            M.Auto.voteSentForRound = 0
            M.Auto.minuteSentForRound = 0
            if M.Settings.autoEnabled and M.Settings.announceVehicle ~= false then
                queue_auto('Next vehicle chosen: {vehicle}.', 'auto-vehicle', true)
            end
            if M.Settings.autoEnabled and M.Settings.announceRoundStart ~= false then
                queue_auto('{vehicle} Warfare is now active. Survive the round!', 'auto-round-start', true)
            end
        end

        local duration = tonumber(minigames.S.vehicleRoundTimeMs or 180000) or 180000
        if roundStartedAt > 0 and duration > 0 then
            local remaining = duration - (now - roundStartedAt)
            if duration >= 120000 and remaining <= 90000 and remaining > 60000 and M.Auto.voteSentForRound ~= roundStartedAt then
                M.Auto.voteSentForRound = roundStartedAt
                if M.Settings.autoEnabled and M.Settings.announceVote ~= false then
                    queue_auto('What vehicle would you like next? Vote in chat!', 'auto-vote', true)
                end
            end
            if duration >= 70000 and remaining <= 60000 and remaining > 0 and M.Auto.minuteSentForRound ~= roundStartedAt then
                M.Auto.minuteSentForRound = roundStartedAt
                if M.Settings.autoEnabled and M.Settings.announceMinute ~= false then
                    queue_auto('Next vehicle round begins in 1 minute!', 'auto-minute', true)
                end
            end
        end
    end

    M.Auto.previousOnline = online
    M.Auto.previousRoundIndex = roundIndex
    M.Auto.previousRoundStartedAt = roundStartedAt
end

local function checkbox(label, id, value)
    if not ImGui or not ImGui.Checkbox then return value == true, false end
    local ok, a, b = direct_call(ImGui.Checkbox, tostring(label) .. '##' .. tostring(id), value == true)
    if ok and type(a) == 'boolean' then return a, b == true or a ~= (value == true) end
    return value == true, false
end

local function input_text(label, id, value, maxLength)
    value = tostring(value or '')
    if not ImGui or not ImGui.InputText then return value, false end
    local ok, a, b = direct_call(ImGui.InputText, tostring(label) .. '##' .. tostring(id), value, tonumber(maxLength or 255) or 255)
    if not ok then return value, false end
    if type(a) == 'string' then return a, b == true or a ~= value end
    if type(b) == 'string' then return b, a == true or b ~= value end
    return value, false
end

local function save_if_changed(changed)
