end

local function render_recipient_picker()
    M.RefreshPlayers(false)
    local modeNames = { 'Everyone', 'Selected Player' }
    local newMode, changed = UI.Combo('Recipients##MessengerRecipientModeV206', M.Settings.recipientMode or 0, modeNames, 2)
    if changed then M.Settings.recipientMode = newMode; M.Save() end

    local names = { 'Choose a player' }
    local ids = { -1 }
    local selectedIndex = 0
    for i, entry in ipairs(M.PlayerCache) do
        names[#names + 1] = tostring(entry.name)
        ids[#ids + 1] = entry.id
        if entry.id == M.Settings.selectedPlayerId then selectedIndex = i end
    end
    if M.Settings.recipientMode == 1 then
        local newIndex, playerChanged = UI.Combo('Player##MessengerPlayerV206', selectedIndex, names, math.min(#names, 12))
        if playerChanged then
            M.Settings.selectedPlayerId = ids[newIndex + 1] or -1
            M.Save()
        end
    end

    if UI.Button then
        UI.Button('EVERYONE##MessengerEveryoneV206', 'purple', function() M.Settings.recipientMode = 0; M.Save() end, 180, 30)
        if UI.SameLine then UI.SameLine() end
        UI.Button('MOST RECENT##MessengerRecentV206', 'cyan', function()
            if M.LastRecipientId and M.LastRecipientId >= 0 and player_exists(M.LastRecipientId) then
                M.Settings.recipientMode = 1
                M.Settings.selectedPlayerId = M.LastRecipientId
                M.Save()
            else notify('No recent recipient is available.', 3000) end
        end, 180, 30)
        if UI.SameLine then UI.SameLine() end
        UI.Button('CLEAR RECIPIENT##MessengerClearRecipientV206', 'red', function() M.Settings.selectedPlayerId = -1; M.Save() end, 180, 30)
    end
end

