            if minigames.S.showMessengerTab == true and ImGui.BeginTabItem('Messenger') then UI.RenderMessenger(); ImGui.EndTabItem() end
            if ImGui.BeginTabItem('Players') then UI.RenderPlayers(); ImGui.EndTabItem() end
            if ImGui.BeginTabItem('Config') then UI.RenderConfig(); ImGui.EndTabItem() end
            if ImGui.BeginTabItem('Guide') then UI.RenderGuide(); ImGui.EndTabItem() end
            if ImGui.BeginTabItem('Credits') then UI.RenderCredits(); ImGui.EndTabItem() end
