-- ============================================================
-- embedded module: systems\messenger_probe_v208.lua
-- ============================================================
embedded_modules['systems\\messenger_probe_v208.lua'] = function()
-- minigames v0.208-alpha
-- safe, paced phone-message transport lab.
-- tests one selected player only. no session host requirement.

minigames = minigames or {}
minigames.S = minigames.S or {}
minigames.Messenger = minigames.Messenger or {}
minigames.UIX = minigames.UIX or {}

local M = minigames.Messenger
local UI = minigames.UIX

M.PhoneLab = M.PhoneLab or {}
local L = M.PhoneLab

local H = {
    SEND_TEXT = 0x3A214F2EC889B100,
    HANDLE_FROM_PLAYER = 0x388EB2B86C73B6B3,
    HANDLE_FROM_USER_ID = 0xDCD51DD8F87AEC5C,
    HANDLE_FROM_MEMBER_ID = 0xA0FD21BED61E5C4C,
    HANDLE_VALID = 0x6F79B93B0A8E4133,
    GET_PLAYER_FROM_HANDLE = 0xCE5F689CF5A0A49D,
    GAMERTAG_START = 0x9F0C0A981D73FA56,
    GAMERTAG_PENDING = 0xB071E27958EF4CF0,
    GAMERTAG_SUCCEEDED = 0xFD00798DBA7523DD,
    GET_GAMERTAG = 0x426141162EBE5CDB,
    IS_GAMER_IN_SESSION = 0x0F10B05DDF8D16E9,
}

L.SelectedPlayerId = tonumber(L.SelectedPlayerId or (M.Settings and M.Settings.selectedPlayerId) or -1) or -1
L.DelayMs = math.max(2000, math.min(6000, tonumber(L.DelayMs or 3000) or 3000))
L.Running = L.Running == true
L.StopRequested = false
L.CurrentMethod = tonumber(L.CurrentMethod or 0) or 0
L.Completed = tonumber(L.Completed or 0) or 0
L.NativePositive = tonumber(L.NativePositive or 0) or 0
L.LastResult = tostring(L.LastResult or 'Not started')
L.Results = L.Results or {}
L.TargetCache = L.TargetCache or {}
L.LogPath = tostring(M.ProbeDir or ((minigames.ROOT or '.') .. '\\Diagnostics')) .. '\\phone_method_lab.log'
L.SummaryPath = tostring(M.ProbeDir or ((minigames.ROOT or '.') .. '\\Diagnostics')) .. '\\phone_method_summary.txt'

local function now_ms()
    if minigames.Now then
        local ok, value = direct_call(minigames.Now)
        if ok and tonumber(value) then return tonumber(value) end
    end
    if Time and Time.GetEpocheMs then
        local ok, value = direct_call(Time.GetEpocheMs)
        if ok and tonumber(value) then return tonumber(value) end
    end
    return math.floor((os.clock and os.clock() or 0) * 1000)
end

local function yield_ms(ms)
    if Script and Script.Yield then direct_call(Script.Yield, tonumber(ms or 0) or 0) end
end

local function notify(message, duration)
    if minigames.Toast then
        local ok = direct_call(minigames.Toast, 'Phone Method Lab', tostring(message or ''), tonumber(duration or 4500) or 4500)
        if ok then return end
    end
    if GUI and GUI.AddToast then direct_call(GUI.AddToast, 'Phone Method Lab', tostring(message or ''), tonumber(duration or 4500) or 4500) end
end

local function color_log(colorName, message)
    local text = tostring(message or '')
    if Logger and Logger.Log and eLogColor then
        local color = eLogColor[colorName] or eLogColor.CYAN
        local ok = direct_call(Logger.Log, color, 'Minigames Phone Lab', text)
        if ok then return end
    end
    if Logger and Logger.LogInfo then direct_call(Logger.LogInfo, '[Minigames Phone Lab] ' .. text) end
end

local function ensure_diag_dir()
    if FileMgr and FileMgr.CreateDir and M.ProbeDir then direct_call(FileMgr.CreateDir, M.ProbeDir) end
end

local function append_log(line)
    ensure_diag_dir()
    local f = io.open(L.LogPath, 'ab')
    if not f then return false end
    local stamp = os.date and os.date('%Y-%m-%d %H:%M:%S') or tostring(now_ms())
    f:write('[' .. tostring(stamp) .. '] ' .. tostring(line or ''):gsub('[\r\n]+', ' ') .. '\n')
    f:close()
    return true
end

local function player_exists(pid)
    if not Players or not Players.GetById then return false end
    local ok, player = direct_call(Players.GetById, tonumber(pid) or -1)
    return ok and player ~= nil
end

local function player_name(pid)
    if Players and Players.GetName then
        local ok, value = direct_call(Players.GetName, tonumber(pid) or -1)
        if ok and value and tostring(value) ~= '' then return tostring(value) end
    end
    return 'Player ' .. tostring(pid)
end

local function player_rid(pid)
    if not Players or not Players.GetById then return nil, 'Players.GetById unavailable' end
    local okPlayer, player = direct_call(Players.GetById, pid)
    if not okPlayer or not player then return nil, 'player unavailable' end
    if not player.GetGamerInfo then return nil, 'GetGamerInfo unavailable' end
    local okInfo, info = direct_call(function() return player:GetGamerInfo() end)
    if not okInfo or not info then return nil, 'GamerInfo unavailable' end
    local rid = tonumber(info.RockstarId)
    if not rid then return nil, 'RockstarId unavailable' end
    return rid
end

local function ptr_from_buffer(buffer)
    if not buffer or not buffer.GetBuffer then return nil, nil end
    local ptr, size
    local ok = direct_call(function()
        ptr = tonumber(buffer:GetBuffer())
        if buffer.GetSize then size = tonumber(buffer:GetSize()) end
    end)
    if not ok or not ptr or ptr == 0 then return nil, nil end
    return ptr, size or 13
end

local function candidate_from_rid(pid, mode)
    local rid, err = player_rid(pid)
    if not rid then return nil, err end
    if not GamerHandle or not GamerHandle.New then return nil, 'GamerHandle.New unavailable' end

    local handle
    if mode == 'empty' or mode == 'platform0' or mode == 'platform3' then
        local ok, value = direct_call(GamerHandle.New)
        if not ok or not value then return nil, 'empty GamerHandle unavailable' end
        handle = value
        direct_call(function() handle.RockstarId = rid end)
        direct_call(function() handle.UNK1 = 0 end)
        if mode == 'platform0' then direct_call(function() handle.Platform = 0 end) end
        if mode == 'platform3' then direct_call(function() handle.Platform = 3 end) end
    else
        local ok, value = direct_call(GamerHandle.New, rid)
        if not ok or not value then return nil, 'GamerHandle.New(rid) failed' end
        handle = value
    end

    if not handle.ToBuffer then return nil, 'GamerHandle.ToBuffer unavailable' end
    local okBuffer, buffer = direct_call(function() return handle:ToBuffer() end)
    if not okBuffer or not buffer then return nil, 'ToBuffer failed' end

    if mode == 'roundtrip' then
        if not buffer.ToHandle then return nil, 'Buffer.ToHandle unavailable' end
        local okHandle2, handle2 = direct_call(function() return buffer:ToHandle() end)
        if not okHandle2 or not handle2 or not handle2.ToBuffer then return nil, 'roundtrip ToHandle failed' end
        local okBuffer2, buffer2 = direct_call(function() return handle2:ToBuffer() end)
        if not okBuffer2 or not buffer2 then return nil, 'roundtrip ToBuffer failed' end
        handle, buffer = handle2, buffer2
    end

    local ptr, size = ptr_from_buffer(buffer)
    if not ptr then return nil, 'buffer pointer unavailable' end
    return { ptr = ptr, size = size, owner = { handle, buffer }, route = 'RID/' .. tostring(mode or 'direct'), rid = rid }
end

local function candidate_from_player_buffer(pid, sizeMode, roundtrip)
    if not GamerHandleBuffer or not GamerHandleBuffer.New then return nil, 'GamerHandleBuffer.New unavailable' end
    if not Natives or not Natives.InvokeVoid then return nil, 'native API unavailable' end
    local okBuffer, buffer = direct_call(GamerHandleBuffer.New)
    if not okBuffer or not buffer then return nil, 'buffer allocation failed' end
    local ptr, reported = ptr_from_buffer(buffer)
    if not ptr then return nil, 'buffer pointer unavailable' end
    local size = sizeMode == '13' and 13 or reported
    if not size or size <= 0 then size = 13 end
    local okFill, fillErr = direct_call(Natives.InvokeVoid, H.HANDLE_FROM_PLAYER, pid, ptr, size)
    if not okFill then return nil, 'NETWORK_HANDLE_FROM_PLAYER failed: ' .. tostring(fillErr) end

    local owner = { buffer }
    if roundtrip then
        if not buffer.ToHandle then return nil, 'Buffer.ToHandle unavailable' end
        local okH, handle = direct_call(function() return buffer:ToHandle() end)
        if not okH or not handle or not handle.ToBuffer then return nil, 'buffer roundtrip failed' end
        local okB, buffer2 = direct_call(function() return handle:ToBuffer() end)
        if not okB or not buffer2 then return nil, 'roundtrip buffer failed' end
        ptr, reported = ptr_from_buffer(buffer2)
        if not ptr then return nil, 'roundtrip pointer unavailable' end
        owner = { buffer, handle, buffer2 }
        size = reported or 13
    end
    return { ptr = ptr, size = size, owner = owner, route = 'PLAYER_BUFFER/' .. tostring(sizeMode) .. (roundtrip and '/roundtrip' or '') }
end

local function candidate_raw(pid, source)
    if not Memory or not Memory.Alloc or not Memory.Free or not Memory.MemSet then return nil, 'Memory API unavailable' end
    if not Natives or not Natives.InvokeVoid then return nil, 'native API unavailable' end
    local ptr = tonumber(Memory.Alloc(256))
    if not ptr or ptr == 0 then return nil, 'Memory.Alloc failed' end
    direct_call(Memory.MemSet, ptr, 0, 256)
    local ok, err
    if source == 'player' then
        ok, err = direct_call(Natives.InvokeVoid, H.HANDLE_FROM_PLAYER, pid, ptr, 13)
    else
        local rid, ridErr = player_rid(pid)
        if not rid then direct_call(Memory.Free, ptr); return nil, ridErr end
        local hash = source == 'user_id' and H.HANDLE_FROM_USER_ID or H.HANDLE_FROM_MEMBER_ID
        ok, err = direct_call(Natives.InvokeVoid, hash, tostring(rid), ptr, 13)
    end
    if not ok then direct_call(Memory.Free, ptr); return nil, tostring(err) end
    return {
        ptr = ptr,
        size = 13,
        route = 'RAW/' .. tostring(source),
        cleanup = function() direct_call(Memory.Free, ptr) end,
    }
end

local function build_candidate(pid, kind)
    if kind == 'rid' then return candidate_from_rid(pid, 'direct') end
    if kind == 'rid_roundtrip' then return candidate_from_rid(pid, 'roundtrip') end
    if kind == 'rid_empty' then return candidate_from_rid(pid, 'empty') end
    if kind == 'rid_platform0' then return candidate_from_rid(pid, 'platform0') end
    if kind == 'rid_platform3' then return candidate_from_rid(pid, 'platform3') end
    if kind == 'player_reported' then return candidate_from_player_buffer(pid, 'reported', false) end
    if kind == 'player_13' then return candidate_from_player_buffer(pid, '13', false) end
    if kind == 'player_roundtrip' then return candidate_from_player_buffer(pid, '13', true) end
    if kind == 'raw_player' then return candidate_raw(pid, 'player') end
    if kind == 'raw_user' then return candidate_raw(pid, 'user_id') end
    if kind == 'raw_member' then return candidate_raw(pid, 'member_id') end
    return nil, 'unknown candidate kind'
end

local function invoke_native(mode, message, ptr)
    if not Natives then return false, 'Natives unavailable', false end
    if mode == 'bool' then
        if not Natives.InvokeBool then return false, 'InvokeBool unavailable', false end
        local ok, result = direct_call(Natives.InvokeBool, H.SEND_TEXT, message, ptr)
        return ok and result == true, ok and ('bool=' .. tostring(result)) or tostring(result), ok
    elseif mode == 'int' then
        if not Natives.InvokeInt then return false, 'InvokeInt unavailable', false end
        local ok, result = direct_call(Natives.InvokeInt, H.SEND_TEXT, message, ptr)
        return ok and tonumber(result) ~= 0, ok and ('int=' .. tostring(result)) or tostring(result), ok
    elseif mode == 'void' then
        if not Natives.InvokeVoid then return false, 'InvokeVoid unavailable', false end
        local ok, result = direct_call(Natives.InvokeVoid, H.SEND_TEXT, message, ptr)
        return false, ok and 'void call completed; receipt unknown' or tostring(result), ok
    elseif mode == 'wrapper' then
        if not NETWORK or not NETWORK.NETWORK_SEND_TEXT_MESSAGE then return false, 'NETWORK wrapper unavailable', false end
        local ok, result = direct_call(NETWORK.NETWORK_SEND_TEXT_MESSAGE, message, ptr)
        return ok and result == true, ok and ('wrapper=' .. tostring(result)) or tostring(result), ok
    end
    return false, 'unknown invoke mode', false
end

local function invoke_context(context, invokeMode, message, ptr)
    if not Script or not Script.ExecuteAsScript then return false, 'ExecuteAsScript unavailable', false end
    local positive, detail, called = false, 'context did not execute', false
    local ok, err = direct_call(function()
        Script.ExecuteAsScript(context, function()
            positive, detail, called = invoke_native(invokeMode, message, ptr)
        end)
    end)
    if not ok then return false, 'context ' .. tostring(context) .. ': ' .. tostring(err), false end
    return positive, tostring(context) .. ': ' .. tostring(detail), called
end

local function run_preflight(kind, candidate, pid)
    if not kind then return true, 'no preflight' end
    if not Natives then return false, 'Natives unavailable' end
    if kind == 'valid' then
        local ok, result = direct_call(Natives.InvokeBool, H.HANDLE_VALID, candidate.ptr, candidate.size or 13)
        return ok and result == true, 'handle-valid=' .. tostring(ok and result or result)
    elseif kind == 'player_roundtrip' then
        local ok, result = direct_call(Natives.InvokeInt, H.GET_PLAYER_FROM_HANDLE, candidate.ptr)
        return ok and tonumber(result) == tonumber(pid), 'handle-player=' .. tostring(ok and result or result)
    elseif kind == 'session' then
        local ok, result = direct_call(Natives.InvokeBool, H.IS_GAMER_IN_SESSION, candidate.ptr)
        return ok and result == true, 'in-session=' .. tostring(ok and result or result)
    elseif kind == 'gamertag' then
        local started = false
        direct_call(function() started = Natives.InvokeBool(H.GAMERTAG_START, candidate.ptr) == true end)
        if started then
            for _ = 1, 20 do
                local pending = false
                direct_call(function() pending = Natives.InvokeBool(H.GAMERTAG_PENDING) == true end)
                if not pending then break end
                yield_ms(50)
            end
        end
        local succeeded, tag = false, ''
        direct_call(function() succeeded = Natives.InvokeBool(H.GAMERTAG_SUCCEEDED) == true end)
        if succeeded and Natives.InvokeString then direct_call(function() tag = tostring(Natives.InvokeString(H.GET_GAMERTAG, candidate.ptr) or '') end) end
        return succeeded, 'gamertag-start=' .. tostring(started) .. ' succeeded=' .. tostring(succeeded) .. ' tag=' .. tostring(tag)
    end
    return true, 'unknown preflight skipped'
end

L.Methods = {
    { 'RID buffer + InvokeBool',                 'rid',              'bool' },
    { 'RID buffer + NETWORK wrapper',            'rid',              'wrapper' },
    { 'RID buffer + InvokeInt',                  'rid',              'int' },
    { 'RID buffer + InvokeVoid',                 'rid',              'void' },
    { 'RID buffer in freemode',                  'rid',              'bool', 'freemode' },
    { 'RID buffer in cellphone_flashhand',       'rid',              'bool', 'cellphone_flashhand' },
    { 'RID buffer in cellphone_controller',      'rid',              'bool', 'cellphone_controller' },
    { 'RID buffer in apptextmessage',            'rid',              'bool', 'apptextmessage' },
    { 'RID buffer roundtrip',                    'rid_roundtrip',    'bool' },
    { 'Empty GamerHandle with RockstarId',       'rid_empty',        'bool' },
    { 'Empty GamerHandle RID + Platform 0',      'rid_platform0',    'bool' },
    { 'Empty GamerHandle RID + Platform 3',      'rid_platform3',    'bool' },
    { 'Player buffer using reported size',       'player_reported',  'bool' },
    { 'Player buffer using native size 13',      'player_13',        'bool' },
    { 'Player size 13 + NETWORK wrapper',        'player_13',        'wrapper' },
    { 'Player size 13 + InvokeInt',              'player_13',        'int' },
    { 'Player size 13 + InvokeVoid',             'player_13',        'void' },
    { 'Reported-size buffer in freemode',        'player_reported',  'bool', 'freemode' },
    { 'Size-13 buffer in freemode',              'player_13',        'bool', 'freemode' },
    { 'Size-13 buffer in cellphone_flashhand',   'player_13',        'bool', 'cellphone_flashhand' },
    { 'Size-13 buffer in cellphone_controller',  'player_13',        'bool', 'cellphone_controller' },
    { 'Size-13 buffer in apptextmessage',        'player_13',        'bool', 'apptextmessage' },
    { 'Size-13 + handle-valid preflight',        'player_13',        'bool', nil, 'valid' },
    { 'Size-13 + player roundtrip preflight',    'player_13',        'bool', nil, 'player_roundtrip' },
    { 'Size-13 + gamertag preflight',            'player_13',        'bool', nil, 'gamertag' },
    { 'Size-13 + in-session preflight',          'player_13',        'bool', nil, 'session' },
    { 'Player buffer ToHandle/ToBuffer roundtrip','player_roundtrip','bool' },
    { 'Raw 256-byte player handle, size 13',     'raw_player',       'bool' },
    { 'Raw handle from Rockstar ID string',      'raw_user',         'bool' },
    { 'Raw handle from member ID string',        'raw_member',       'bool' },
}

local function test_message(index)
    return string.format('MG PHONE TEST %02d | reply %02d if received', index, index)
end

local function write_summary(pid)
    ensure_diag_dir()
    local lines = {
        'MINIGAMES PHONE METHOD LAB',
        '===========================',
        '',
        'Version: v0.208-alpha',
        'Target: ' .. player_name(pid) .. ' [' .. tostring(pid) .. ']',
        'Completed: ' .. tostring(L.Completed) .. ' / ' .. tostring(#L.Methods),
        'Native-positive calls: ' .. tostring(L.NativePositive),
        'Important: a native true result does not prove the recipient received the phone text.',
        'Ask the tester which numbered MG PHONE TEST messages appeared.',
        '',
        'RESULTS',
        '-------',
    }
    for i, method in ipairs(L.Methods) do
        local result = L.Results[i]
        lines[#lines + 1] = string.format('%02d. %s | %s', i, method[1], result and result.detail or 'not run')
    end
    local f = io.open(L.SummaryPath, 'wb')
    if f then f:write(table.concat(lines, '\n') .. '\n'); f:close(); return true end
    return false
end

function L.RunMethod(index, pid)
    local method = L.Methods[index]
    if not method then return false, 'unknown method' end
    if not player_exists(pid) then return false, 'target left session' end

    local candidate, buildErr = build_candidate(pid, method[2])
    if not candidate then return false, 'builder failed: ' .. tostring(buildErr) end

    local preflightOk, preflightDetail = run_preflight(method[5], candidate, pid)
    local message = test_message(index)
    local positive, invokeDetail, called
    if method[4] then
        positive, invokeDetail, called = invoke_context(method[4], method[3], message, candidate.ptr)
    else
        positive, invokeDetail, called = invoke_native(method[3], message, candidate.ptr)
    end
    if candidate.cleanup then direct_call(candidate.cleanup) end

    local detail = 'route=' .. tostring(candidate.route) ..
        ' | preflight=' .. tostring(preflightOk) .. ' (' .. tostring(preflightDetail) .. ')' ..
        ' | called=' .. tostring(called) .. ' | ' .. tostring(invokeDetail)
    return positive == true, detail, called == true
end

function L.StartAll()
    if L.Running then notify('The 30-method test is already running.', 3500); return false end
    local pid = tonumber(L.SelectedPlayerId or -1) or -1
    if pid < 0 or not player_exists(pid) then notify('Choose one tester first.', 4000); return false end
    if not Script or not Script.QueueJob then notify('Script.QueueJob is unavailable.', 4500); return false end

    L.Running = true
    L.StopRequested = false
    L.CurrentMethod = 0
    L.Completed = 0
    L.NativePositive = 0
    L.Results = {}
    L.LastResult = 'Starting 30 methods for ' .. player_name(pid)
    append_log('RUN START | target=' .. player_name(pid) .. ' [' .. tostring(pid) .. '] | delay=' .. tostring(L.DelayMs))
    color_log('MAGENTA', 'Starting 30 phone methods for ' .. player_name(pid) .. '. Ask them to report the numbered messages received.')
    notify('30-method phone test started. About ' .. tostring(math.ceil((L.DelayMs * #L.Methods) / 60000)) .. ' minute(s).', 6000)

    Script.QueueJob(function()
        for index, method in ipairs(L.Methods) do
            if L.StopRequested then
                L.LastResult = 'Stopped after method ' .. tostring(L.Completed)
                append_log('RUN STOPPED | completed=' .. tostring(L.Completed))
                color_log('YELLOW', L.LastResult)
                break
            end
            if not player_exists(pid) then
                L.LastResult = 'Target left the session at method ' .. tostring(index)
                append_log('RUN ABORTED | ' .. L.LastResult)
                color_log('RED', L.LastResult)
                break
            end

            L.CurrentMethod = index
            color_log('CYAN', string.format('%02d/30 %s', index, method[1]))
            local ok, detail, called = L.RunMethod(index, pid)
            L.Completed = index
            if ok then L.NativePositive = L.NativePositive + 1 end
            L.Results[index] = { ok = ok, called = called, detail = detail }
            L.LastResult = string.format('%02d %s | %s', index, method[1], detail)
            append_log(string.format('METHOD %02d | %s | positive=%s | called=%s | %s', index, method[1], tostring(ok), tostring(called), detail))
            if ok then
                color_log('GREEN', string.format('%02d native returned positive. Receipt still needs tester confirmation.', index))
            elseif called then
                color_log('YELLOW', string.format('%02d call completed but did not return positive.', index))
            else
                color_log('RED', string.format('%02d could not execute: %s', index, detail))
            end

            if index < #L.Methods and not L.StopRequested then yield_ms(L.DelayMs) end
        end

        write_summary(pid)
        L.Running = false
        L.CurrentMethod = 0
        if not L.StopRequested and L.Completed >= #L.Methods then
            L.LastResult = 'All 30 methods completed. Ask the tester which numbers arrived.'
            append_log('RUN COMPLETE | nativePositive=' .. tostring(L.NativePositive))
            color_log('MAGENTA', L.LastResult)
            notify('All 30 methods completed. Ask the tester which numbers arrived.', 7000)
        else
            notify(L.LastResult, 5000)
        end
    end)
    return true
end

function L.Stop()
    if not L.Running then notify('No phone test is running.', 3000); return end
    L.StopRequested = true
    L.LastResult = 'Stop requested after current method.'
    notify(L.LastResult, 3500)
end

local function render_target_picker()
    if M.RefreshPlayers then direct_call(M.RefreshPlayers, true) end
    local names, ids = { 'Choose one tester' }, { -1 }
    local current = 0
    for i, entry in ipairs(M.PlayerCache or {}) do
        names[#names + 1] = tostring(entry.name)
        ids[#ids + 1] = tonumber(entry.id) or -1
        if tonumber(entry.id) == tonumber(L.SelectedPlayerId) then current = i end
    end
    if UI.Combo then
        local index, changed = UI.Combo('Tester##PhoneLabTesterV208', current, names, math.min(#names, 12))
        if changed then
            L.SelectedPlayerId = ids[(tonumber(index) or 0) + 1] or -1
            if M.Settings then M.Settings.selectedPlayerId = L.SelectedPlayerId end
            if M.Save then direct_call(M.Save) end
        end
    end
end

function UI.RenderPhoneMethodLab()
    UI.Text('30 METHOD PHONE LAB', 'red')
    UI.Text('One button tests thirty phone-text variants against one selected tester. No Session Host required.', 'dim', true)
    UI.Text('The tester should write down every numbered message that reaches their GTA phone.', 'gold', true)

    UI.Child('PhoneLab_Target_V208', 'TEST TARGET', 'Selected player only. This never broadcasts the probe to the whole session.', function()
        render_target_picker()
        if UI.StatusRow then
            UI.StatusRow('Target', L.SelectedPlayerId >= 0 and player_name(L.SelectedPlayerId) or 'NOT SELECTED', L.SelectedPlayerId >= 0 and 'cyan' or 'red')
            UI.StatusRow('Pacing', tostring(L.DelayMs) .. ' ms between methods', 'green')
            UI.StatusRow('Estimated Time', tostring(math.ceil((L.DelayMs * #L.Methods) / 60000)) .. ' minute(s)', 'purple')
        end
        if ImGui and ImGui.SliderInt then
            local ok, value, changed = direct_call(ImGui.SliderInt, 'Delay Between Methods##PhoneLabDelayV208', math.floor(L.DelayMs), 2000, 6000)
            if ok and type(value) == 'number' and (changed == true or value ~= L.DelayMs) then L.DelayMs = math.floor(value) end
        end
    end, 'cyan')

    UI.Child('PhoneLab_Run_V208', 'ONE PRESS TEST', 'Sends MG PHONE TEST 01 through 30, one method at a time.', function()
        if UI.Button then
            UI.Button('RUN ALL 30 METHODS##PhoneLabRunAllV208', 'green', function() L.StartAll() end, 320, 38)
            if UI.SameLine then UI.SameLine() end
            UI.Button('STOP AFTER CURRENT METHOD##PhoneLabStopV208', 'red', function() L.Stop() end, 260, 38)
        end
        if UI.StatusRow then
            UI.StatusRow('Status', L.Running and 'RUNNING' or 'IDLE', L.Running and 'gold' or 'green')
            UI.StatusRow('Progress', tostring(L.Completed) .. ' / ' .. tostring(#L.Methods), 'cyan')
            UI.StatusRow('Current Method', L.CurrentMethod > 0 and (string.format('%02d', L.CurrentMethod) .. ' ' .. tostring(L.Methods[L.CurrentMethod][1])) or 'None', 'purple')
            UI.StatusRow('Native Positive', tostring(L.NativePositive), L.NativePositive > 0 and 'green' or 'dim')
        end
        UI.Text(tostring(L.LastResult), 'dim', true)
        UI.Text('A positive native return is only a clue. The recipient must confirm which numbered phone messages actually appeared.', 'gold', true)
    end, 'green')

    UI.Child('PhoneLab_Methods_V208', 'METHODS', 'Thirty safe transport variants discovered from Cherax handle APIs, GTA native wrappers, and the supplied dump symbols.', function()
        for i, method in ipairs(L.Methods) do
            local result = L.Results[i]
            local color = result and (result.ok and 'green' or (result.called and 'gold' or 'red')) or 'dim'
            UI.Text(string.format('%02d. %s', i, method[1]), color, true)
        end
    end, 'purple')

    UI.Child('PhoneLab_Files_V208', 'DIAGNOSTICS', '', function()
        UI.Text('Detailed log: ' .. tostring(L.LogPath), 'dim', true)
        UI.Text('Summary: ' .. tostring(L.SummaryPath), 'dim', true)
        UI.Text('Private GTA executable functions found in the dumps are intentionally not called by this automated lab because unverified signatures could crash the game.', 'red', true)
    end, 'gold')
end

minigames.S.messengerPhoneLabV208 = true
minigames.VERSION = 'v0.208-alpha'
minigames.BUILD_DATE = '2026-08-02'
color_log('MAGENTA', 'v0.208 Phone Method Lab loaded | 30 paced methods | selected tester only | no host requirement')
end


-- ============================================================
-- embedded module: systems\messenger_delivery_v209.lua
-- ============================================================
embedded_modules['systems\\messenger_delivery_v209.lua'] = function()
-- minigames v0.209-alpha
-- confirmed gta phone-text delivery using raw handle routes 28, 29 and 30.
-- method 28 is primary. a false native return is still considered a completed
-- delivery attempt because live testing confirmed receipt for all three routes.

minigames = minigames or {}
minigames.S = minigames.S or {}
minigames.Messenger = minigames.Messenger or {}

local M = minigames.Messenger

local H = {
    SEND_TEXT = 0x3A214F2EC889B100,
    HANDLE_FROM_PLAYER = 0x388EB2B86C73B6B3,
    HANDLE_FROM_USER_ID = 0xDCD51DD8F87AEC5C,
    HANDLE_FROM_MEMBER_ID = 0xA0FD21BED61E5C4C,
}

M.LastDeliveryMethod = tostring(M.LastDeliveryMethod or 'METHOD 28 PRIMARY')
M.LastNativeResult = tostring(M.LastNativeResult or 'Not attempted')
M.SenderIdentityVisible = true
M.AnonymousPresentationOnly = true

local function yield_ms(ms)
    if Script and Script.Yield then direct_call(Script.Yield, tonumber(ms or 0) or 0) end
end

local function player_name(pid)
    if Players and Players.GetName then
        local ok, value = direct_call(Players.GetName, tonumber(pid) or -1)
        if ok and value and tostring(value) ~= '' then return tostring(value) end
    end
    return 'Player ' .. tostring(pid)
end

local function player_rid(pid)
    if not Players or not Players.GetById then return nil, 'Players.GetById unavailable' end
    local okPlayer, player = direct_call(Players.GetById, tonumber(pid) or -1)
    if not okPlayer or not player then return nil, 'player unavailable' end
    if not player.GetGamerInfo then return nil, 'GetGamerInfo unavailable' end
    local okInfo, info = direct_call(function() return player:GetGamerInfo() end)
    if not okInfo or not info then return nil, 'GamerInfo unavailable' end
    local rid = tonumber(info.RockstarId)
    if not rid then return nil, 'RockstarId unavailable' end
    return rid
end

local function append_probe(line)
    if M.ProbeDir and FileMgr and FileMgr.CreateDir then direct_call(FileMgr.CreateDir, M.ProbeDir) end
    local path = M.ProbePath or ((minigames.ROOT or '.') .. '\\Diagnostics\\messenger_phone_probe.log')
    local f = io.open(path, 'ab')
    if not f then return end
    local stamp = os.date and os.date('%Y-%m-%d %H:%M:%S') or tostring(os.clock())
    f:write('[' .. tostring(stamp) .. '] ' .. tostring(line or ''):gsub('[\r\n]+', ' ') .. '\n')
    f:close()
end

local function allocate_raw_handle()
    if not Memory or not Memory.Alloc or not Memory.Free or not Memory.MemSet then
        return nil, 'Memory raw-handle API unavailable'
    end
    local okAlloc, ptr = direct_call(Memory.Alloc, 256)
    ptr = okAlloc and tonumber(ptr) or nil
    if not ptr or ptr == 0 then return nil, 'Memory.Alloc failed' end
    local okZero = direct_call(Memory.MemSet, ptr, 0, 256)
    if not okZero then
        direct_call(Memory.Free, ptr)
        return nil, 'Memory.MemSet failed'
    end
    return ptr
end

local function build_raw_handle(pid, method)
    if not Natives or not Natives.InvokeVoid then return nil, 'native API unavailable' end
    local ptr, allocErr = allocate_raw_handle()
    if not ptr then return nil, allocErr end

    local ok, err
    if method == 28 then
        ok, err = direct_call(Natives.InvokeVoid, H.HANDLE_FROM_PLAYER, tonumber(pid) or -1, ptr, 13)
    else
        local rid, ridErr = player_rid(pid)
        if not rid then direct_call(Memory.Free, ptr); return nil, ridErr end
        local hash = method == 29 and H.HANDLE_FROM_USER_ID or H.HANDLE_FROM_MEMBER_ID
        ok, err = direct_call(Natives.InvokeVoid, hash, tostring(rid), ptr, 13)
    end

    if not ok then
        direct_call(Memory.Free, ptr)
        return nil, tostring(err)
    end
    return ptr
end

local function attempt_method(pid, message, method)
    local ptr, buildErr = build_raw_handle(pid, method)
    if not ptr then return false, false, 'builder failed: ' .. tostring(buildErr) end

    local called, nativeResult = direct_call(Natives.InvokeBool, H.SEND_TEXT, tostring(message), ptr)
    direct_call(Memory.Free, ptr)

    local route = method == 28 and 'RAW/player' or (method == 29 and 'RAW/user_id' or 'RAW/member_id')
    local detail = 'method=' .. tostring(method) ..
        ' route=' .. tostring(route) ..
        ' called=' .. tostring(called) ..
        ' nativeResult=' .. tostring(nativeResult)
    append_probe('player=' .. tostring(pid) .. ' name=' .. player_name(pid) .. ' ' .. detail)

    if called then
        -- live testing showed the native can return false while the message is received.
        return true, nativeResult == true, detail
    end
    return false, false, detail
end

function M.SendPhoneText(playerId, message)
    if M.Settings and M.Settings.phoneEnabled == false then return false, 'phone-disabled' end
    if not Natives or not Natives.InvokeBool or not Natives.InvokeVoid then return false, 'native-api-unavailable' end

    local pid = tonumber(playerId or -1) or -1
    M.LastPhonePlayer = player_name(pid) .. ' [' .. tostring(pid) .. ']'

    local failures = {}
    for _, method in ipairs({28, 29, 30}) do
        local called, positive, detail = attempt_method(pid, message, method)
        if called then
            M.LastDeliveryMethod = 'METHOD ' .. tostring(method)
            M.LastHandleRoute = method == 28 and 'RAW/player' or (method == 29 and 'RAW/user_id' or 'RAW/member_id')
            M.LastNativeResult = tostring(positive)
            M.LastHandleStatus = 'Call completed. Receipt may succeed even when nativeResult=false.'
            return true, 'phone-text attempted via method ' .. tostring(method)
        end
        failures[#failures + 1] = 'M' .. tostring(method) .. ': ' .. tostring(detail)
        yield_ms(50)
    end

    M.LastDeliveryMethod = 'METHODS 28-30 FAILED TO EXECUTE'
    M.LastHandleStatus = table.concat(failures, ' | ')
    append_probe('player=' .. tostring(pid) .. ' name=' .. player_name(pid) .. ' all confirmed routes failed to execute | ' .. M.LastHandleStatus)
    return false, M.LastHandleStatus
end

minigames.S.messengerConfirmedRawDeliveryV209 = true
minigames.S.messengerMethod28PrimaryV209 = true
minigames.S.messengerSenderIdentityVisibleV209 = true
minigames.VERSION = 'v0.209-alpha'
minigames.BUILD_DATE = '2026-08-02'

if minigames.LogInfo then
    direct_call(minigames.LogInfo, '[Messenger] v0.209 loaded | method 28 primary | 29/30 execution fallbacks | GTA sender name remains visible')
end
end



-- ============================================================
-- embedded module: systems\messenger_sender_lab_v210.lua
-- ============================================================
embedded_modules['systems\\messenger_sender_lab_v210.lua'] = function()
-- minigames v0.210-alpha
-- focused sender-identity lab. all thirty tests use only the three raw
-- recipient handle builders confirmed by live testing (methods 28, 29, 30).
-- the gta dumps expose rage::cmsgtextmessage.m_gamerid, m_text and m_teamonly,
-- so this lab tests the remaining safe hypothesis: whether the caller script
-- context or native wrapper changes how gta fills the sender gamer id.

minigames = minigames or {}
minigames.S = minigames.S or {}
minigames.Messenger = minigames.Messenger or {}
minigames.UIX = minigames.UIX or {}

local M = minigames.Messenger
local UI = minigames.UIX
M.PhoneLab = M.PhoneLab or {}
local L = M.PhoneLab

local H = {
    SEND_TEXT = 0x3A214F2EC889B100,
    HANDLE_FROM_PLAYER = 0x388EB2B86C73B6B3,
    HANDLE_FROM_USER_ID = 0xDCD51DD8F87AEC5C,
    HANDLE_FROM_MEMBER_ID = 0xA0FD21BED61E5C4C,
}

L.SelectedPlayerId = tonumber(L.SelectedPlayerId or (M.Settings and M.Settings.selectedPlayerId) or -1) or -1
L.DelayMs = math.max(2000, math.min(6000, tonumber(L.DelayMs or 3000) or 3000))
L.Running = false
L.StopRequested = false
L.CurrentMethod = 0
L.Completed = 0
L.NativePositive = 0
L.LastResult = 'Not started'
L.Results = {}
L.LogPath = tostring(M.ProbeDir or ((minigames.ROOT or '.') .. '\\Diagnostics')) .. '\\phone_sender_lab.log'
L.SummaryPath = tostring(M.ProbeDir or ((minigames.ROOT or '.') .. '\\Diagnostics')) .. '\\phone_sender_summary.txt'

local function now_ms()
    if minigames.Now then local ok, v = direct_call(minigames.Now); if ok and tonumber(v) then return tonumber(v) end end
    if Time and Time.GetEpocheMs then local ok, v = direct_call(Time.GetEpocheMs); if ok and tonumber(v) then return tonumber(v) end end
    return math.floor((os.clock and os.clock() or 0) * 1000)
end

local function yield_ms(ms)
    if Script and Script.Yield then direct_call(Script.Yield, tonumber(ms or 0) or 0) end
end

local function notify(message, duration)
    if minigames.Toast then local ok = direct_call(minigames.Toast, 'Sender Identity Lab', tostring(message or ''), tonumber(duration or 4500) or 4500); if ok then return end end
    if GUI and GUI.AddToast then direct_call(GUI.AddToast, 'Sender Identity Lab', tostring(message or ''), tonumber(duration or 4500) or 4500) end
end

local function color_log(colorName, message)
    local text = tostring(message or '')
    if Logger and Logger.Log and eLogColor then
        local color = eLogColor[colorName] or eLogColor.CYAN
        local ok = direct_call(Logger.Log, color, 'Minigames Sender Lab', text)
        if ok then return end
    end
    if Logger and Logger.LogInfo then direct_call(Logger.LogInfo, '[Minigames Sender Lab] ' .. text) end
end

local function ensure_diag_dir()
    if FileMgr and FileMgr.CreateDir and M.ProbeDir then direct_call(FileMgr.CreateDir, M.ProbeDir) end
end

local function append_log(line)
    ensure_diag_dir()
    local f = io.open(L.LogPath, 'ab')
    if not f then return false end
    local stamp = os.date and os.date('%Y-%m-%d %H:%M:%S') or tostring(now_ms())
    f:write('[' .. tostring(stamp) .. '] ' .. tostring(line or ''):gsub('[\\r\\n]+', ' ') .. '\\n')
    f:close()
    return true
end

local function player_exists(pid)
    if not Players or not Players.GetById then return false end
    local ok, player = direct_call(Players.GetById, tonumber(pid) or -1)
    return ok and player ~= nil
end

local function player_name(pid)
    if Players and Players.GetName then
        local ok, value = direct_call(Players.GetName, tonumber(pid) or -1)
        if ok and value and tostring(value) ~= '' then return tostring(value) end
    end
    return 'Player ' .. tostring(pid)
end

local function player_rid(pid)
    if not Players or not Players.GetById then return nil, 'Players.GetById unavailable' end
    local okPlayer, player = direct_call(Players.GetById, tonumber(pid) or -1)
    if not okPlayer or not player then return nil, 'player unavailable' end
    if not player.GetGamerInfo then return nil, 'GetGamerInfo unavailable' end
    local okInfo, info = direct_call(function() return player:GetGamerInfo() end)
    if not okInfo or not info then return nil, 'GamerInfo unavailable' end
    local rid = tonumber(info.RockstarId)
    if not rid then return nil, 'RockstarId unavailable' end
    return rid
end

local function allocate_raw_handle()
    if not Memory or not Memory.Alloc or not Memory.Free or not Memory.MemSet then return nil, 'Memory raw-handle API unavailable' end
    local okAlloc, ptr = direct_call(Memory.Alloc, 256)
    ptr = okAlloc and tonumber(ptr) or nil
    if not ptr or ptr == 0 then return nil, 'Memory.Alloc failed' end
    if not direct_call(Memory.MemSet, ptr, 0, 256) then
        direct_call(Memory.Free, ptr)
        return nil, 'Memory.MemSet failed'
    end
    return ptr
end

local function build_raw_handle(pid, route)
    if not Natives or not Natives.InvokeVoid then return nil, 'native API unavailable' end
    local ptr, allocErr = allocate_raw_handle()
    if not ptr then return nil, allocErr end

    local ok, err
    if route == 28 then
        ok, err = direct_call(Natives.InvokeVoid, H.HANDLE_FROM_PLAYER, tonumber(pid) or -1, ptr, 13)
    else
        local rid, ridErr = player_rid(pid)
        if not rid then direct_call(Memory.Free, ptr); return nil, ridErr end
        local hash = route == 29 and H.HANDLE_FROM_USER_ID or H.HANDLE_FROM_MEMBER_ID
        ok, err = direct_call(Natives.InvokeVoid, hash, tostring(rid), ptr, 13)
    end

    if not ok then direct_call(Memory.Free, ptr); return nil, tostring(err) end
    return ptr
end

local function invoke_direct(mode, message, ptr)
    if not Natives then return false, false, 'Natives unavailable' end
    if mode == 'bool' then
        if not Natives.InvokeBool then return false, false, 'InvokeBool unavailable' end
        local called, result = direct_call(Natives.InvokeBool, H.SEND_TEXT, message, ptr)
        return called, called and result == true, called and ('bool=' .. tostring(result)) or tostring(result)
    elseif mode == 'int' then
        if not Natives.InvokeInt then return false, false, 'InvokeInt unavailable' end
        local called, result = direct_call(Natives.InvokeInt, H.SEND_TEXT, message, ptr)
        return called, called and tonumber(result) ~= 0, called and ('int=' .. tostring(result)) or tostring(result)
    elseif mode == 'void' then
        if not Natives.InvokeVoid then return false, false, 'InvokeVoid unavailable' end
        local called, result = direct_call(Natives.InvokeVoid, H.SEND_TEXT, message, ptr)
        return called, false, called and 'void call completed' or tostring(result)
    elseif mode == 'wrapper' then
        if not NETWORK or not NETWORK.NETWORK_SEND_TEXT_MESSAGE then return false, false, 'NETWORK wrapper unavailable' end
        local called, result = direct_call(NETWORK.NETWORK_SEND_TEXT_MESSAGE, message, ptr)
        return called, called and result == true, called and ('wrapper=' .. tostring(result)) or tostring(result)
    end
    return false, false, 'unknown invoke mode'
end

local function invoke_in_context(context, mode, message, ptr)
    if not Script or not Script.ExecuteAsScript then return false, false, 'ExecuteAsScript unavailable' end
    local called, positive, detail = false, false, 'context callback not reached'
    local ok, err = direct_call(function()
        Script.ExecuteAsScript(context, function()
            called, positive, detail = invoke_direct(mode, message, ptr)
        end)
    end)
    if not ok then return false, false, 'context ' .. tostring(context) .. ' failed: ' .. tostring(err) end
    return called, positive, tostring(context) .. ': ' .. tostring(detail)
end

local routeNames = { [28] = 'RAW/player', [29] = 'RAW/user_id', [30] = 'RAW/member_id' }
local variants = {
    { 'Direct InvokeBool', 'bool' },
    { 'Direct InvokeInt', 'int' },
    { 'Direct InvokeVoid', 'void' },
    { 'NETWORK wrapper', 'wrapper' },
    { 'freemode context', 'bool', 'freemode' },
    { 'cellphone_flashhand context', 'bool', 'cellphone_flashhand' },
    { 'cellphone_controller context', 'bool', 'cellphone_controller' },
    { 'apptextmessage context', 'bool', 'apptextmessage' },
    { 'social_controller context', 'bool', 'social_controller' },
    { 'main_persistent context', 'bool', 'main_persistent' },
}

L.Methods = {}
for _, route in ipairs({28, 29, 30}) do
    for _, variant in ipairs(variants) do
        L.Methods[#L.Methods + 1] = {
            name = 'Method ' .. tostring(route) .. ' | ' .. tostring(variant[1]),
            route = route,
            mode = variant[2],
            context = variant[3],
        }
    end
end

local function test_message(index)
    return string.format('MG ANON %02d | Reply A=anonymous or N=name shown', index)
end

local function write_summary(pid)
    ensure_diag_dir()
    local lines = {
        'MINIGAMES SENDER IDENTITY LAB',
        '===============================',
        '',
        'Version: v0.210-alpha',
        'Target: ' .. player_name(pid) .. ' [' .. tostring(pid) .. ']',
        'Completed: ' .. tostring(L.Completed) .. ' / ' .. tostring(#L.Methods),
        'Native-positive calls: ' .. tostring(L.NativePositive),
        '',
        'TESTER INSTRUCTIONS',
        'For each MG ANON number received, record A if no sender username appeared,',
        'or N if the sender username was still visible.',
        '',
        'DUMP FINDING',
        'The supplied GTA dump identifies rage::CMsgTextMessage fields m_GamerId,',
        'm_Text and m_TeamOnly. These tests therefore keep the three confirmed',
        'recipient builders and vary only the safe invocation/caller context.',
        '',
        'RESULTS',
        '-------',
    }
    for i, method in ipairs(L.Methods) do
        local result = L.Results[i]
        lines[#lines + 1] = string.format('%02d. %s | %s', i, method.name, result and result.detail or 'not run')
    end
    local f = io.open(L.SummaryPath, 'wb')
    if f then f:write(table.concat(lines, '\\n') .. '\\n'); f:close(); return true end
    return false
end

function L.RunMethod(index, pid)
    local method = L.Methods[index]
    if not method then return false, false, 'unknown method' end
    if not player_exists(pid) then return false, false, 'target left session' end

    local ptr, buildErr = build_raw_handle(pid, method.route)
    if not ptr then return false, false, 'builder failed: ' .. tostring(buildErr) end

    local message = test_message(index)
    local called, positive, invokeDetail
    if method.context then
        called, positive, invokeDetail = invoke_in_context(method.context, method.mode, message, ptr)
    else
        called, positive, invokeDetail = invoke_direct(method.mode, message, ptr)
    end
    direct_call(Memory.Free, ptr)

    local detail = 'route=' .. tostring(routeNames[method.route]) ..
        ' | context=' .. tostring(method.context or 'direct') ..
        ' | mode=' .. tostring(method.mode) ..
        ' | called=' .. tostring(called) ..
        ' | positive=' .. tostring(positive) ..
        ' | ' .. tostring(invokeDetail)
    return called == true, positive == true, detail
end

function L.StartAll()
    if L.Running then notify('The sender test is already running.', 3500); return false end
    local pid = tonumber(L.SelectedPlayerId or -1) or -1
    if pid < 0 or not player_exists(pid) then notify('Choose one consenting tester first.', 4500); return false end
    if not Script or not Script.QueueJob then notify('Script.QueueJob is unavailable.', 4500); return false end

    L.Running = true
    L.StopRequested = false
    L.CurrentMethod = 0
    L.Completed = 0
    L.NativePositive = 0
    L.Results = {}
    L.LastResult = 'Starting focused sender test for ' .. player_name(pid)
    append_log('RUN START | target=' .. player_name(pid) .. ' [' .. tostring(pid) .. '] | delay=' .. tostring(L.DelayMs))
    color_log('MAGENTA', 'Starting 30 sender-identity tests for ' .. player_name(pid) .. '. Only raw routes 28, 29 and 30 are used.')
    notify('Sender test started. Ask the tester to record A or N for each number.', 6500)

    Script.QueueJob(function()
        for index, method in ipairs(L.Methods) do
            if L.StopRequested then
                L.LastResult = 'Stopped after method ' .. tostring(L.Completed)
                append_log('RUN STOPPED | completed=' .. tostring(L.Completed))
                color_log('YELLOW', L.LastResult)
                break
            end
            if not player_exists(pid) then
                L.LastResult = 'Target left the session at method ' .. tostring(index)
                append_log('RUN ABORTED | ' .. L.LastResult)
                color_log('RED', L.LastResult)
                break
            end

            L.CurrentMethod = index
            color_log('CYAN', string.format('%02d/30 %s', index, method.name))
            local called, positive, detail = L.RunMethod(index, pid)
            L.Completed = index
            if positive then L.NativePositive = L.NativePositive + 1 end
            L.Results[index] = { called = called, positive = positive, detail = detail }
            L.LastResult = string.format('%02d %s | %s', index, method.name, detail)
            append_log(string.format('METHOD %02d | %s | %s', index, method.name, detail))
            if called then
                color_log(positive and 'GREEN' or 'YELLOW', string.format('%02d call completed. Tester must report A or N.', index))
            else
                color_log('RED', string.format('%02d could not execute: %s', index, detail))
            end

            if index < #L.Methods and not L.StopRequested then yield_ms(L.DelayMs) end
        end

        write_summary(pid)
        L.Running = false
        L.CurrentMethod = 0
        if not L.StopRequested and L.Completed >= #L.Methods then
            L.LastResult = 'All 30 focused tests completed. Ask which numbers were anonymous.'
            append_log('RUN COMPLETE | nativePositive=' .. tostring(L.NativePositive))
            color_log('MAGENTA', L.LastResult)
            notify(L.LastResult, 7000)
        else
            notify(L.LastResult, 5000)
        end
    end)
    return true
end

function L.Stop()
    if not L.Running then notify('No sender test is running.', 3000); return end
    L.StopRequested = true
    L.LastResult = 'Stop requested after current method.'
    notify(L.LastResult, 3500)
end

local function render_target_picker()
    if M.RefreshPlayers then direct_call(M.RefreshPlayers, true) end
    local names, ids = { 'Choose one tester' }, { -1 }
    local current = 0
    for i, entry in ipairs(M.PlayerCache or {}) do
        names[#names + 1] = tostring(entry.name)
        ids[#ids + 1] = tonumber(entry.id) or -1
        if tonumber(entry.id) == tonumber(L.SelectedPlayerId) then current = i end
    end
    if UI.Combo then
        local index, changed = UI.Combo('Tester##SenderLabTesterV210', current, names, math.min(#names, 12))
        if changed then
            L.SelectedPlayerId = ids[(tonumber(index) or 0) + 1] or -1
            if M.Settings then M.Settings.selectedPlayerId = L.SelectedPlayerId end
            if M.Save then direct_call(M.Save) end
        end
    end
end

function UI.RenderPhoneMethodLab()
    UI.Text('30 METHOD SENDER LAB', 'red')
    UI.Text('Only the three confirmed raw phone routes are used: 28, 29 and 30.', 'gold', true)
    UI.Text('The lab tests ten safe caller/invocation variants per route. It does not patch GTA memory or impersonate another player.', 'dim', true)

    UI.Child('SenderLab_Target_V210', 'TEST TARGET', 'Selected consenting tester only. Never broadcast this diagnostic session-wide.', function()
        render_target_picker()
        if UI.StatusRow then
            UI.StatusRow('Target', L.SelectedPlayerId >= 0 and player_name(L.SelectedPlayerId) or 'NOT SELECTED', L.SelectedPlayerId >= 0 and 'cyan' or 'red')
            UI.StatusRow('Routes', '28 + 29 + 30 ONLY', 'green')
            UI.StatusRow('Pacing', tostring(L.DelayMs) .. ' ms', 'green')
            UI.StatusRow('Estimated Time', tostring(math.ceil((L.DelayMs * #L.Methods) / 60000)) .. ' minute(s)', 'purple')
        end
        if ImGui and ImGui.SliderInt then
            local ok, value, changed = direct_call(ImGui.SliderInt, 'Delay Between Methods##SenderLabDelayV210', math.floor(L.DelayMs), 2000, 6000)
            if ok and type(value) == 'number' and (changed == true or value ~= L.DelayMs) then L.DelayMs = math.floor(value) end
        end
    end, 'cyan')

    UI.Child('SenderLab_Run_V210', 'ONE PRESS TEST', 'Sends MG ANON 01 through 30. Tester records A for anonymous or N when your name appears.', function()
        if UI.Button then
            UI.Button('RUN 30 SENDER TESTS##SenderLabRunV210', 'green', function() L.StartAll() end, 320, 38)
            if UI.SameLine then UI.SameLine() end
            UI.Button('STOP AFTER CURRENT##SenderLabStopV210', 'red', function() L.Stop() end, 250, 38)
        end
        if UI.StatusRow then
            UI.StatusRow('Status', L.Running and 'RUNNING' or 'IDLE', L.Running and 'gold' or 'green')
            UI.StatusRow('Progress', tostring(L.Completed) .. ' / 30', 'cyan')
            UI.StatusRow('Current', L.CurrentMethod > 0 and (string.format('%02d', L.CurrentMethod) .. ' ' .. tostring(L.Methods[L.CurrentMethod].name)) or 'None', 'purple')
            UI.StatusRow('Native Positive', tostring(L.NativePositive), L.NativePositive > 0 and 'green' or 'dim')
        end
        UI.Text(tostring(L.LastResult), 'dim', true)
        UI.Text('A false native return can still deliver. Only the tester can confirm whether the sender name disappeared.', 'gold', true)
    end, 'green')

    UI.Child('SenderLab_Methods_V210', 'METHODS', 'Ten variants for each confirmed raw recipient-handle route.', function()
        for i, method in ipairs(L.Methods) do
            local result = L.Results[i]
            local color = result and (result.called and 'gold' or 'red') or 'dim'
            UI.Text(string.format('%02d. %s', i, method.name), color, true)
        end
    end, 'purple')

    UI.Child('SenderLab_Files_V210', 'DIAGNOSTICS', '', function()
        UI.Text('Detailed log: ' .. tostring(L.LogPath), 'dim', true)
        UI.Text('Summary: ' .. tostring(L.SummaryPath), 'dim', true)
        UI.Text('Dump finding: CMsgTextMessage contains a sender Gamer ID field. If all 30 show your name, true anonymity is not available through NETWORK_SEND_TEXT_MESSAGE.', 'red', true)
    end, 'gold')
end

M.ShowAdvancedPhoneLab = true
minigames.S.messengerSenderLabV210 = true
minigames.S.messengerOnlyConfirmedRoutesV210 = true
minigames.VERSION = 'v0.210-alpha'
minigames.BUILD_DATE = '2026-08-02'
color_log('MAGENTA', 'v0.210 Sender Identity Lab loaded | 30 tests | raw routes 28/29/30 only | no host requirement')
end



-- ============================================================
-- embedded module: systems\wargames_chat_v211.lua
-- ============================================================
embedded_modules['systems\\wargames_chat_v211.lua'] = function()
-- minigames v0.211-alpha
-- wargames-only custom session chat. phone-text delivery and non-wargames
-- announcements are intentionally excluded from the production messenger ui.

minigames = minigames or {}
minigames.S = minigames.S or {}
minigames.Messenger = minigames.Messenger or {}
minigames.WarGamesChat = minigames.WarGamesChat or {}
minigames.UIX = minigames.UIX or {}

local M = minigames.Messenger
local C = minigames.WarGamesChat
local UI = minigames.UIX
local Limits = minigames.UsageLimits or {}

local DEFAULTS = {
    enabled = false,
    prefixEnabled = true,
    prefix = 'WARGAMES',
    localEcho = true,
    queueGapMs = 2500,
    announceStart = true,
    announceVote = true,
    announceMinute = true,
    announceVehicle = true,
    announceRound = true,
    announceEnd = true,
    startMessage = 'WarGames is now active! Prepare for the first vehicle round.',
    voteMessage = 'Vote in chat: What vehicle should be next?',
    minuteMessage = 'Next vehicle round begins in 1 minute!',
    vehicleMessage = 'Next vehicle chosen: {vehicle}',
    roundMessage = '{vehicle} Warfare is now active. Survive!',
    endMessage = 'WarGames has ended. Thanks for playing!',
    manualMessage = 'Vote in chat for the next WarGames vehicle!',
}

C.Path = tostring(minigames.ROOT or ((os.getenv('USERPROFILE') or '.') .. '\\Documents\\Cherax\\Lua\\Minigames')) .. '\\wargames_chat.ini'
C.TempPath = C.Path .. '.tmp'
C.MaxMessageLength = 180
C.Settings = C.Settings or {}
C.Queue = C.Queue or {}
C.History = C.History or {}
C.WorkerRunning = C.WorkerRunning == true
C.LastStatus = tostring(C.LastStatus or 'Ready')
C.LastMessage = tostring(C.LastMessage or 'No WarGames chat sent yet')
C.LastSource = tostring(C.LastSource or 'None')
C.LastSendMs = tonumber(C.LastSendMs or 0) or 0
C.Stats = C.Stats or { sent = 0, failed = 0, skipped = 0 }
C.Auto = C.Auto or {
    initialized = false,
    previousOnline = false,
    previousRoundIndex = -1,
    previousRoundStartedAt = 0,
    voteSentForRound = 0,
    minuteSentForRound = 0,
    lastTickMs = 0,
}

for key, value in pairs(DEFAULTS) do
    if C.Settings[key] == nil then C.Settings[key] = value end
end

local function now_ms()
    if minigames.Now then
        local ok, value = direct_call(minigames.Now)
        if ok and tonumber(value) then return tonumber(value) end
    end
    if Time and Time.GetEpocheMs then
        local ok, value = direct_call(Time.GetEpocheMs)
        if ok and tonumber(value) then return tonumber(value) end
    end
    return math.floor((os.clock and os.clock() or 0) * 1000)
end

local function yield_ms(ms)
    if Script and Script.Yield then direct_call(Script.Yield, tonumber(ms or 0) or 0) end
end

local function clean_line(value)
    value = tostring(value or ''):gsub('[\r\n]+', ' '):gsub('|', '/')
    return value:gsub('^%s+', ''):gsub('%s+$', '')
end

local function parse_bool(value, fallback)
    value = tostring(value or ''):lower()
    if value == 'true' or value == '1' or value == 'yes' or value == 'on' then return true end
    if value == 'false' or value == '0' or value == 'no' or value == 'off' then return false end
    return fallback == true
end

local function cap_message(value)
    value = clean_line(value)
    if #value > C.MaxMessageLength then value = value:sub(1, C.MaxMessageLength) end
    return value
end

local function toast(message, duration)
    if minigames.Toast then
        local ok = direct_call(minigames.Toast, 'WarGames Chat', tostring(message or ''), tonumber(duration or 4000) or 4000)
        if ok then return end
    end
    if GUI and GUI.AddToast then direct_call(GUI.AddToast, 'WarGames Chat', tostring(message or ''), tonumber(duration or 4000) or 4000) end
end

local function log_info(message)
    if minigames.LogInfo then direct_call(minigames.LogInfo, '[WarGames Chat] ' .. tostring(message or '')) end
end

local function log_error(message)
    if minigames.LogError then direct_call(minigames.LogError, '[WarGames Chat] ' .. tostring(message or '')) end
end

local function local_player_id()
    if Limits.GetLocalPlayerId then
        local ok, value = direct_call(Limits.GetLocalPlayerId)
        if ok and tonumber(value) then return math.floor(tonumber(value)) end
    end
    if GTA and GTA.GetLocalPlayerId then
        local ok, value = direct_call(GTA.GetLocalPlayerId)
        if ok and tonumber(value) then return math.floor(tonumber(value)) end
    end
    return 0
end

local function wargames_online()
    if Limits.Runtime and Limits.Runtime.wargames and Limits.Runtime.wargames.active == true then return true end
    return minigames.S.wargamesSystemsActive == true or minigames.S.wargamesActive == true or minigames.S.warGamesActive == true
end

local function current_vehicle_label()
    local label = nil
    if minigames.GetVehicleLabelByIndex then
        direct_call(function() label = minigames.GetVehicleLabelByIndex(minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or 1) end)
    end
    if not label or tostring(label) == '' or tostring(label) == 'None' then
        label = minigames.S.currentRoundVehicleName or minigames.S.currentRoundVehicleModel or 'Unknown Vehicle'
    end
    return tostring(label or 'Unknown Vehicle')
end

local function session_player_count()
    if Limits.GetSessionPlayerCount then
        local ok, value = direct_call(Limits.GetSessionPlayerCount)
        if ok and tonumber(value) then return math.floor(tonumber(value)) end
    end
    local count = 1
    if Players and Players.Get then
        local ok, list = direct_call(Players.Get)
        if ok and type(list) == 'table' then count = #list end
    end
    return count
end

function C.ExpandTemplate(message)
    message = tostring(message or '')
    message = message:gsub('{vehicle}', current_vehicle_label())
    message = message:gsub('{players}', tostring(session_player_count()))
    message = message:gsub('{time}', os.date and os.date('%H:%M') or '')
    return cap_message(message)
end

function C.FormatMessage(message)
    message = C.ExpandTemplate(message)
    if C.Settings.prefixEnabled == true then
        local prefix = clean_line(C.Settings.prefix)
        if prefix ~= '' then message = '[' .. prefix .. '] ' .. message end
    end
    return cap_message(message)
end

local function add_history(source, message, result, success)
    table.insert(C.History, 1, {
        time = os.date and os.date('%H:%M:%S') or tostring(now_ms()),
        source = tostring(source or 'Unknown'),
        message = tostring(message or ''),
        result = tostring(result or ''),
        success = success == true,
    })
    while #C.History > 30 do table.remove(C.History) end
end

function C.Save()
    local root = tostring(minigames.ROOT or '')
    if root ~= '' and FileMgr and FileMgr.CreateDir then direct_call(FileMgr.CreateDir, root) end
    local S = C.Settings
    local lines = {
        '# Minigames WarGames-only chat settings',
        'enabled=' .. tostring(S.enabled == true),
        'prefix_enabled=' .. tostring(S.prefixEnabled == true),
        'prefix=' .. clean_line(S.prefix),
        'local_echo=' .. tostring(S.localEcho == true),
        'queue_gap_ms=' .. tostring(math.floor(tonumber(S.queueGapMs or 2500) or 2500)),
        'announce_start=' .. tostring(S.announceStart ~= false),
        'announce_vote=' .. tostring(S.announceVote ~= false),
        'announce_minute=' .. tostring(S.announceMinute ~= false),
        'announce_vehicle=' .. tostring(S.announceVehicle ~= false),
        'announce_round=' .. tostring(S.announceRound ~= false),
        'announce_end=' .. tostring(S.announceEnd ~= false),
        'start_message=' .. clean_line(S.startMessage),
        'vote_message=' .. clean_line(S.voteMessage),
        'minute_message=' .. clean_line(S.minuteMessage),
        'vehicle_message=' .. clean_line(S.vehicleMessage),
        'round_message=' .. clean_line(S.roundMessage),
        'end_message=' .. clean_line(S.endMessage),
        'manual_message=' .. clean_line(S.manualMessage),
    }
    local body = table.concat(lines, '\n') .. '\n'
    local f = io.open(C.TempPath, 'wb')
    if not f then return false end
    f:write(body)
    f:close()
    direct_call(os.remove, C.Path)
    local ok = os.rename(C.TempPath, C.Path)
    if not ok then
        local out = io.open(C.Path, 'wb')
        if not out then return false end
        out:write(body)
        out:close()
        direct_call(os.remove, C.TempPath)
    end
    return true
end

function C.Load()
    local f = io.open(C.Path, 'rb')
    if not f then return false end
    local body = f:read('*a') or ''
    f:close()
    local values = {}
    for line in body:gmatch('[^\r\n]+') do
        local key, value = line:match('^%s*([%w_]+)%s*=%s*(.-)%s*$')
        if key then values[key] = value end
    end
    local S = C.Settings
    S.enabled = parse_bool(values.enabled, S.enabled)
    S.prefixEnabled = parse_bool(values.prefix_enabled, S.prefixEnabled)
    S.prefix = clean_line(values.prefix or S.prefix)
    S.localEcho = parse_bool(values.local_echo, S.localEcho)
    S.queueGapMs = math.max(1000, math.min(8000, math.floor(tonumber(values.queue_gap_ms or S.queueGapMs or 2500) or 2500)))
    S.announceStart = parse_bool(values.announce_start, S.announceStart)
    S.announceVote = parse_bool(values.announce_vote, S.announceVote)
    S.announceMinute = parse_bool(values.announce_minute, S.announceMinute)
    S.announceVehicle = parse_bool(values.announce_vehicle, S.announceVehicle)
    S.announceRound = parse_bool(values.announce_round, S.announceRound)
    S.announceEnd = parse_bool(values.announce_end, S.announceEnd)
    S.startMessage = clean_line(values.start_message or S.startMessage)
    S.voteMessage = clean_line(values.vote_message or S.voteMessage)
    S.minuteMessage = clean_line(values.minute_message or S.minuteMessage)
    S.vehicleMessage = clean_line(values.vehicle_message or S.vehicleMessage)
    S.roundMessage = clean_line(values.round_message or S.roundMessage)
    S.endMessage = clean_line(values.end_message or S.endMessage)
    S.manualMessage = clean_line(values.manual_message or S.manualMessage)
    return true
end

function C.RestoreDefaults()
    for key, value in pairs(DEFAULTS) do C.Settings[key] = value end
    C.Save()
    C.LastStatus = 'WarGames chat defaults restored'
    toast(C.LastStatus, 3000)
end

function C.SendNow(rawMessage, source)
    local message = C.FormatMessage(rawMessage)
    if message == '' then return false, 'empty message' end
    if not GTA or not GTA.SendChatMessageToEveryone then return false, 'GTA.SendChatMessageToEveryone unavailable' end

    local ok, err = direct_call(GTA.SendChatMessageToEveryone, message, false)
    if not ok then return false, tostring(err) end

    if C.Settings.localEcho == true and GTA.AddChatMessageToPool then
        direct_call(GTA.AddChatMessageToPool, local_player_id(), message, false)
    end

    C.LastSendMs = now_ms()
    C.LastMessage = message
    C.LastSource = tostring(source or 'WarGames')
    C.LastStatus = 'Sent to session chat'
    C.Stats.sent = (C.Stats.sent or 0) + 1
    add_history(source, message, 'Sent to session chat', true)
    log_info('Sent | source=' .. tostring(source or 'WarGames') .. ' | message=' .. message)
    return true, 'session-chat'
end

function C.Enqueue(rawMessage, source, requiresWarGames)
    rawMessage = clean_line(rawMessage)
    if rawMessage == '' then toast('Enter a WarGames message first.', 3500); return false end
    if requiresWarGames == true and not wargames_online() then
        C.Stats.skipped = (C.Stats.skipped or 0) + 1
        C.LastStatus = 'WarGames is not active. Message was not sent.'
        add_history(source, rawMessage, C.LastStatus, false)
        toast(C.LastStatus, 4000)
        return false
    end
    if #C.Queue >= 12 then toast('WarGames chat queue is full.', 3500); return false end
    C.Queue[#C.Queue + 1] = {
        message = rawMessage,
        source = tostring(source or 'WarGames'),
        requiresWarGames = requiresWarGames == true,
    }
    C.LastStatus = 'Queued: ' .. tostring(source or 'WarGames')
    C.StartWorker()
    return true
end

function C.StartWorker()
    if C.WorkerRunning then return end
    if not Script or not Script.QueueJob then
        C.LastStatus = 'Script.QueueJob unavailable'
        toast(C.LastStatus, 4500)
        return
    end
    C.WorkerRunning = true
    Script.QueueJob(function()
        while #C.Queue > 0 do
            local request = table.remove(C.Queue, 1)
            if request.requiresWarGames and not wargames_online() then
                C.Stats.skipped = (C.Stats.skipped or 0) + 1
                add_history(request.source, request.message, 'Skipped because WarGames ended', false)
            else
                local ok, result = C.SendNow(request.message, request.source)
                if not ok then
                    C.Stats.failed = (C.Stats.failed or 0) + 1
                    C.LastStatus = 'Send failed: ' .. tostring(result)
                    add_history(request.source, request.message, C.LastStatus, false)
                    log_error(C.LastStatus)
                end
            end
            if #C.Queue > 0 then yield_ms(C.Settings.queueGapMs) end
        end
        C.WorkerRunning = false
    end)
end

function C.SendManual()
    if now_ms() - (C.LastManualSendMs or 0) < 5000 then
        toast('Please wait 5 seconds before another manual WarGames message.', 3500)
        return false
    end
    C.LastManualSendMs = now_ms()
    return C.Enqueue(C.Settings.manualMessage, 'manual', true)
end

function C.LocalPreview(rawMessage)
    local message = C.FormatMessage(rawMessage)
    if message == '' then toast('Nothing to preview.', 2500); return false end
    if GTA and GTA.AddChatMessageToPool then
        local ok = direct_call(GTA.AddChatMessageToPool, local_player_id(), message, false)
        if ok then toast('Local preview added to your chat only.', 2500); return true end
    end
    toast(message, 5000)
    return true
end

local function queue_auto(message, source, requiresWarGames)
    if C.Settings.enabled ~= true then return false end
    return C.Enqueue(message, source, requiresWarGames == true)
end

function C.AutoTick()
    local now = now_ms()
    if now - (C.Auto.lastTickMs or 0) < 500 then return end
    C.Auto.lastTickMs = now

    local online = wargames_online()
    local roundIndex = math.floor(tonumber(minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or -1) or -1)
    local roundStartedAt = tonumber(minigames.S.roundStartedAtMs or 0) or 0

    if not C.Auto.initialized then
        C.Auto.initialized = true
        C.Auto.previousOnline = online
        C.Auto.previousRoundIndex = roundIndex
        C.Auto.previousRoundStartedAt = roundStartedAt
        return
    end

    if online and not C.Auto.previousOnline and C.Settings.enabled and C.Settings.announceStart ~= false then
        queue_auto(C.Settings.startMessage, 'WarGames started', true)
    elseif not online and C.Auto.previousOnline and C.Settings.enabled and C.Settings.announceEnd ~= false then
        queue_auto(C.Settings.endMessage, 'WarGames ended', false)
    end

    if online then
        local roundChanged = roundIndex ~= C.Auto.previousRoundIndex or (roundStartedAt > 0 and roundStartedAt ~= C.Auto.previousRoundStartedAt)
        if roundChanged and roundIndex >= 0 then
            C.Auto.voteSentForRound = 0
            C.Auto.minuteSentForRound = 0
            if C.Settings.enabled and C.Settings.announceVehicle ~= false then
                queue_auto(C.Settings.vehicleMessage, 'Vehicle selected', true)
            end
            if C.Settings.enabled and C.Settings.announceRound ~= false then
                queue_auto(C.Settings.roundMessage, 'Round started', true)
            end
        end

        local duration = tonumber(minigames.S.vehicleRoundTimeMs or 180000) or 180000
        if roundStartedAt > 0 and duration > 0 then
            local remaining = duration - (now - roundStartedAt)
            if duration >= 120000 and remaining <= 90000 and remaining > 60000 and C.Auto.voteSentForRound ~= roundStartedAt then
                C.Auto.voteSentForRound = roundStartedAt
                if C.Settings.enabled and C.Settings.announceVote ~= false then
                    queue_auto(C.Settings.voteMessage, 'Vehicle vote', true)
                end
            end
            if duration >= 70000 and remaining <= 60000 and remaining > 0 and C.Auto.minuteSentForRound ~= roundStartedAt then
                C.Auto.minuteSentForRound = roundStartedAt
                if C.Settings.enabled and C.Settings.announceMinute ~= false then
                    queue_auto(C.Settings.minuteMessage, 'One-minute warning', true)
                end
            end
        end
    end

    C.Auto.previousOnline = online
    C.Auto.previousRoundIndex = roundIndex
    C.Auto.previousRoundStartedAt = roundStartedAt
end

local function checkbox(label, id, value)
    if not ImGui or not ImGui.Checkbox then return value == true, false end
    local ok, a, b = direct_call(ImGui.Checkbox, tostring(label) .. '##' .. tostring(id), value == true)
    if ok and type(a) == 'boolean' then return a, b == true or a ~= (value == true) end
    return value == true, false
end

local function input_text(label, id, value, maxLength)
    value = tostring(value or '')
    if not ImGui or not ImGui.InputText then return value, false end
    local ok, a, b = direct_call(ImGui.InputText, tostring(label) .. '##' .. tostring(id), value, tonumber(maxLength or 180) or 180)
    if not ok then return value, false end
    if type(a) == 'string' then return a, b == true or a ~= value end
    if type(b) == 'string' then return b, a == true or b ~= value end
    return value, false
end

local function render_event_row(title, toggleKey, messageKey, id, tone)
    local enabled, changed = checkbox(title, 'WGChatToggle_' .. id, C.Settings[toggleKey] ~= false)
    if changed then C.Settings[toggleKey] = enabled; C.Save() end
    local value, textChanged = input_text('Message', 'WGChatMessage_' .. id, C.Settings[messageKey], C.MaxMessageLength)
    if textChanged then C.Settings[messageKey] = value; C.Save() end
    UI.Button('PREVIEW##WGChatPreview_' .. id, 'cyan', function() C.LocalPreview(C.Settings[messageKey]) end, 120, 27)
    UI.SameLine()
    UI.Button('SEND TEST##WGChatTest_' .. id, tone or 'purple', function() C.Enqueue(C.Settings[messageKey], 'test-' .. id, false) end, 140, 27)
end

function C.Render()
    if UI.Text then
        UI.Text('WARGAMES AUTO CHAT', 'red')
        UI.Text('Custom session-chat announcements for WarGames only. No phone texts and no other minigame messages.', 'dim', true)
    end

    UI.Child('WarGamesChat_Status_V211', 'WarGames Chat Status', '', function()
        if UI.StatusRow then
            UI.StatusRow('WarGames', wargames_online() and 'ACTIVE' or 'IDLE', wargames_online() and 'green' or 'dim')
            UI.StatusRow('Automatic Phone Texts', C.Settings.enabled and 'ON' or 'OFF', C.Settings.enabled and 'green' or 'gold')
            UI.StatusRow('Chat API', GTA and GTA.SendChatMessageToEveryone and 'AVAILABLE' or 'UNAVAILABLE', GTA and GTA.SendChatMessageToEveryone and 'green' or 'red')
            UI.StatusRow('Queued', tostring(#C.Queue), #C.Queue > 0 and 'gold' or 'dim')
            UI.StatusRow('Last Status', C.LastStatus, 'cyan')
        else
            UI.Text('WarGames: ' .. (wargames_online() and 'ACTIVE' or 'IDLE'), wargames_online() and 'green' or 'dim')
            UI.Text('Last Status: ' .. tostring(C.LastStatus), 'cyan', true)
        end
    end, 'red')

    UI.Child('WarGamesChat_Settings_V211', 'Automatic WarGames Chat', 'Messages are queued and paced to avoid chat flooding.', function()
        local value, changed = checkbox('Enable WarGames Auto Chat', 'WGChatEnabledV211', C.Settings.enabled)
        if changed then C.Settings.enabled = value; C.Save() end
        value, changed = checkbox('Add Message Prefix', 'WGChatPrefixEnabledV211', C.Settings.prefixEnabled)
        if changed then C.Settings.prefixEnabled = value; C.Save() end
        value, changed = checkbox('Show Local Echo', 'WGChatLocalEchoV211', C.Settings.localEcho)
        if changed then C.Settings.localEcho = value; C.Save() end
        local text, textChanged = input_text('Prefix', 'WGChatPrefixV211', C.Settings.prefix, 24)
        if textChanged then C.Settings.prefix = text; C.Save() end
        UI.Text('Template variables: {vehicle}  {players}  {time}', 'gold', true)
    end, 'purple')

    UI.Child('WarGamesChat_Messages_V211', 'Custom WarGames Messages', 'Edit each announcement, then preview locally or send a live test.', function()
        render_event_row('WarGames Started', 'announceStart', 'startMessage', 'start', 'green')
        UI.Spacing(1)
        render_event_row('Vehicle Voting Prompt', 'announceVote', 'voteMessage', 'vote', 'purple')
        UI.Spacing(1)
        render_event_row('One-Minute Warning', 'announceMinute', 'minuteMessage', 'minute', 'cyan')
        UI.Spacing(1)
        render_event_row('Vehicle Selected', 'announceVehicle', 'vehicleMessage', 'vehicle', 'gold')
        UI.Spacing(1)
        render_event_row('Round Started', 'announceRound', 'roundMessage', 'round', 'red')
        UI.Spacing(1)
        render_event_row('WarGames Ended', 'announceEnd', 'endMessage', 'end', 'green')
    end, 'red')

    UI.Child('WarGamesChat_Manual_V211', 'Custom WarGames Broadcast', 'This button only sends while WarGames is active.', function()
        local value, changed = input_text('Custom Message', 'WGChatManualV211', C.Settings.manualMessage, C.MaxMessageLength)
        if changed then C.Settings.manualMessage = value; C.Save() end
        UI.Button('SEND TO SESSION CHAT##WGChatManualSendV211', 'green', function() C.SendManual() end, 250, 34)
        UI.SameLine()
        UI.Button('LOCAL PREVIEW##WGChatManualPreviewV211', 'cyan', function() C.LocalPreview(C.Settings.manualMessage) end, 180, 34)
    end, 'gold')

    UI.Child('WarGamesChat_Actions_V211', 'Settings', '', function()
        UI.Button('SAVE WARGAMES CHAT##WGChatSaveV211', 'green', function()
            C.Save(); C.LastStatus = 'WarGames chat settings saved'; toast(C.LastStatus, 2500)
        end, 220, 30)
        UI.SameLine()
        UI.Button('RESTORE DEFAULTS##WGChatDefaultsV211', 'red', function() C.RestoreDefaults() end, 200, 30)
    end, 'purple')

    UI.Child('WarGamesChat_History_V211', 'Recent WarGames Chat', '', function()
        if #C.History == 0 then
            UI.Text('No WarGames chat messages sent yet.', 'dim')
        else
            for index = 1, math.min(#C.History, 12) do
                local row = C.History[index]
                local tone = row.success and 'green' or 'red'
                UI.Text(tostring(row.time) .. ' | ' .. tostring(row.source) .. ' | ' .. tostring(row.result), tone, true)
                UI.Text(tostring(row.message), 'dim', true)
            end
        end
        UI.Button('CLEAR HISTORY##WGChatClearHistoryV211', 'red', function() C.History = {}; C.LastStatus = 'History cleared' end, -1, 28)
    end, 'cyan')
end

