local function now_ms()
    if minigames.Now then local ok, value = direct_call(minigames.Now); if ok and tonumber(value) then return tonumber(value) end end
    if Time and Time.GetEpocheMs then local ok, value = direct_call(Time.GetEpocheMs); if ok and tonumber(value) then return tonumber(value) end end
    return math.floor((os.clock and os.clock() or 0) * 1000)
end

local function clean(value)
    value = tostring(value or ''):gsub('[\r\n]+', ' ')
    return value:gsub('^%s+', ''):gsub('%s+$', '')
end

local function lower(value) return string.lower(clean(value)) end

local function toast(message, duration)
    if minigames.Toast then local ok = direct_call(minigames.Toast, 'WarGames Voting', tostring(message or ''), tonumber(duration or 3500) or 3500); if ok then return end end
    if GUI and GUI.AddToast then direct_call(GUI.AddToast, 'WarGames Voting', tostring(message or ''), tonumber(duration or 3500) or 3500) end
end

local function log_info(message)
    if minigames.LogInfo then direct_call(minigames.LogInfo, '[WarGames Voting] ' .. tostring(message or '')) end
end

local function wargames_online()
    if Limits.Runtime and Limits.Runtime.wargames and Limits.Runtime.wargames.active == true then return true end
    return minigames.S.wargamesSystemsActive == true or minigames.S.wargamesActive == true or minigames.S.warGamesActive == true
end

local function replace_vehicle(template, label)
    return tostring(template or ''):gsub('{vehicle}', tostring(label or 'Unknown Vehicle'))
end

local function pick_message(kind, label)
    local pool = C.MessagePoolsV213[kind] or {}
    if #pool == 0 then return '' end
    local last = tonumber(V.lastChoice[kind] or 0) or 0
    local index = math.random(1, #pool)
    if #pool > 1 and index == last then index = (index % #pool) + 1 end
    V.lastChoice[kind] = index
    return replace_vehicle(pool[index], label)
end

local function reset_vote(keepPending)
    V.active = false
    V.roundStartedAt = 0
    V.candidates = {}
    V.votesByPlayer = {}
    V.counts = {0, 0, 0}
    if not keepPending then
        V.pendingWinner = nil
        V.pendingForRound = 0
    end
end

local function candidate_name(candidate)
    return tostring(candidate and (candidate.label or candidate.model) or 'Unknown')
end

local function choose_candidates()
    local pool = minigames.WarGames and minigames.WarGames.VehiclePool or {}
    if #pool < 3 then return nil end
    local current = math.floor(tonumber(minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or 0) or 0)
    local indices = {}
    for index = 1, #pool do if index ~= current then indices[#indices + 1] = index end end
    if #indices < 3 then for index = 1, #pool do indices[#indices + 1] = index end end
    for i = #indices, 2, -1 do local j = math.random(1, i); indices[i], indices[j] = indices[j], indices[i] end
    local out, seen = {}, {}
    for _, index in ipairs(indices) do
        if not seen[index] then
            local vehicle = pool[index]
            if vehicle then
                seen[index] = true
                out[#out + 1] = { index = index, label = tostring(vehicle.label or vehicle.model or ('Vehicle ' .. tostring(index))), model = tostring(vehicle.model or '') }
                if #out == 3 then break end
            end
        end
    end
    return #out == 3 and out or nil
end

local function vote_options_text(candidates)
    return ' Type 1 for ' .. candidate_name(candidates[1]) .. ', 2 for ' .. candidate_name(candidates[2]) .. ', or 3 for ' .. candidate_name(candidates[3]) .. '.'
end

function C.OpenSmartVoteV213(roundStartedAt, manual)
    if not wargames_online() then toast('WarGames must be active to open voting.', 3500); return false end
    local candidates = choose_candidates()
    if not candidates then toast('At least three WarGames vehicles are required.', 4000); return false end
    reset_vote(false)
    V.active = true
    V.roundStartedAt = tonumber(roundStartedAt or minigames.S.roundStartedAtMs or now_ms()) or now_ms()
    V.openedForRound = V.roundStartedAt
    V.candidates = candidates
    local prompt = pick_message('vote') .. vote_options_text(candidates)
    C.Enqueue(prompt, manual and 'Manual smart vote' or 'Smart vehicle vote', true)
    log_info('Vote opened | round=' .. tostring(V.roundStartedAt) .. ' | 1=' .. candidate_name(candidates[1]) .. ' | 2=' .. candidate_name(candidates[2]) .. ' | 3=' .. candidate_name(candidates[3]))
    return true
end

local function recompute_counts()
    local counts = {0, 0, 0}
    for _, choice in pairs(V.votesByPlayer or {}) do if choice >= 1 and choice <= 3 then counts[choice] = counts[choice] + 1 end end
    V.counts = counts
    return counts
end

local function choose_winner(counts)
    local best = math.max(counts[1] or 0, counts[2] or 0, counts[3] or 0)
    local tied = {}
    for i = 1, 3 do if (counts[i] or 0) == best then tied[#tied + 1] = i end end
    return tied[math.random(1, #tied)], best
end

function C.CloseSmartVoteV213(manual)
    if not V.active or #V.candidates ~= 3 then return false end
    local counts = recompute_counts()
    local winnerSlot, winnerVotes = choose_winner(counts)
    local winner = V.candidates[winnerSlot]
    V.active = false
    V.closedForRound = V.roundStartedAt
    V.pendingWinner = winner
    V.pendingForRound = V.roundStartedAt
    local summary = ' Votes: ' .. candidate_name(V.candidates[1]) .. '=' .. tostring(counts[1]) .. ' | ' .. candidate_name(V.candidates[2]) .. '=' .. tostring(counts[2]) .. ' | ' .. candidate_name(V.candidates[3]) .. '=' .. tostring(counts[3]) .. '.'
    C.Enqueue(pick_message('vehicle', candidate_name(winner)) .. summary, manual and 'Manual vote result' or 'Vehicle vote result', true)
    C.Enqueue(pick_message('minute'), 'One-minute warning', true)
    log_info('Vote closed | winner=' .. candidate_name(winner) .. ' | votes=' .. tostring(winnerVotes) .. ' | counts=' .. table.concat(counts, ','))
    return true
end

local function apply_pending_winner(roundStartedAt)
    local winner = V.pendingWinner
    if not winner or V.pendingForRound ~= roundStartedAt then return false end
    V.pendingWinner = nil
    V.appliedForRound = roundStartedAt
    if minigames.WarGames and minigames.WarGames.SelectVehicleExact then
        local ok, result = direct_call(minigames.WarGames.SelectVehicleExact, winner.index, 'Smart Phone Vote v0.215')
        if not ok or result == false then
            log_info('Winner apply failed | ' .. tostring(result))
            return false
        end
        if C.Settings.enabled and C.Settings.announceRound ~= false then
            C.Enqueue(pick_message('round', candidate_name(winner)), 'Round started', true)
        end
        log_info('Winner applied | ' .. candidate_name(winner) .. ' | index=' .. tostring(winner.index))
        return true
    end
    return false
end

local function player_id_from_object(playerObj)
    local id = nil
    direct_call(function() id = tonumber(playerObj.PlayerId) end)
    if id == nil then direct_call(function() id = tonumber(playerObj:GetPlayerId()) end) end
    return id and math.floor(id) or -1
end

local function strip_hash_garbage(text)
    text = tostring(text or '')
    local body = text:match('^(.-)[0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F][0-9a-fA-F]+$')
    return clean(body or text)
end

local function parse_choice(message)
    local text = lower(strip_hash_garbage(message))
    local number = tonumber(text)
    if number and number >= 1 and number <= 3 and math.floor(number) == number then return number end
    for i, candidate in ipairs(V.candidates or {}) do
        if text == lower(candidate.label) or (candidate.model ~= '' and text == lower(candidate.model)) then return i end
    end
    return nil
end

function C.OnChatVoteV213(playerObj, message, isTeam)
    if VS.smartVotingEnabled ~= true or not V.active or not wargames_online() then return false end
    if isTeam == true then return false end
    local playerId = player_id_from_object(playerObj)
    local choice = parse_choice(message)
    if playerId < 0 or not choice then return false end
    local stamp = now_ms()
    local key = tostring(playerId) .. '|' .. lower(message)
    local previous = tonumber(V.recentMessages[key] or 0) or 0
    if stamp - previous < 1500 then return false end
    V.recentMessages[key] = stamp
    V.votesByPlayer[playerId] = choice
    recompute_counts()
    log_info('Vote recorded | player=' .. tostring(playerId) .. ' | choice=' .. tostring(choice) .. ' | vehicle=' .. candidate_name(V.candidates[choice]))
    return false
end

if EventMgr and EventMgr.RegisterHandler and eLuaEvent and eLuaEvent.ON_CHAT_MESSAGE then
    direct_call(function() V.chatHandlerId = EventMgr.RegisterHandler(eLuaEvent.ON_CHAT_MESSAGE, C.OnChatVoteV213) end)
end

function C.AutoTick()
    local now = now_ms()
    if now - (C.Auto.lastTickMs or 0) < 250 then return end
    C.Auto.lastTickMs = now
    local online = wargames_online()
    local roundStartedAt = tonumber(minigames.S.roundStartedAtMs or 0) or 0
    local roundIndex = math.floor(tonumber(minigames.S.roundVehicleIndex or minigames.S.selectedVehicleIndex or -1) or -1)

    if not C.Auto.initialized then
        C.Auto.initialized = true
        C.Auto.previousOnline = online
        C.Auto.previousRoundIndex = roundIndex
        C.Auto.previousRoundStartedAt = roundStartedAt
        V.lastOnline = online
        V.lastRoundStartedAt = roundStartedAt
        return
    end

    if online and not C.Auto.previousOnline then
        reset_vote(false)
        if C.Settings.enabled and C.Settings.announceStart ~= false then C.Enqueue(pick_message('start'), 'WarGames started', true) end
    elseif not online and C.Auto.previousOnline then
        if C.Settings.enabled and C.Settings.announceEnd ~= false then C.Enqueue(pick_message('finish'), 'WarGames ended', false) end
        reset_vote(false)
    end

    if online and roundStartedAt > 0 then
        local roundChanged = roundStartedAt ~= C.Auto.previousRoundStartedAt or roundIndex ~= C.Auto.previousRoundIndex
        if roundChanged then
            reset_vote(false)
            if C.Settings.enabled and C.Settings.announceRound ~= false then C.Enqueue(pick_message('round', (C.ExpandTemplate and C.ExpandTemplate('{vehicle}') or 'Vehicle')), 'Round started', true) end
        end

        local duration = tonumber(minigames.S.vehicleRoundTimeMs or 180000) or 180000
        local remaining = duration - (now - roundStartedAt)
        if C.Settings.enabled == true and VS.smartVotingEnabled == true and duration >= 120000 then
            if remaining <= VS.openAtRemainingMs and remaining > VS.closeAtRemainingMs and V.openedForRound ~= roundStartedAt then
                C.OpenSmartVoteV213(roundStartedAt, false)
            end
            if V.active and V.roundStartedAt == roundStartedAt and remaining <= VS.closeAtRemainingMs and remaining > 0 and V.closedForRound ~= roundStartedAt then
                C.CloseSmartVoteV213(false)
            end
            if V.pendingWinner and V.pendingForRound == roundStartedAt and remaining <= VS.applyAtRemainingMs and remaining > -3000 then
                apply_pending_winner(roundStartedAt)
            end
        end
    end

    C.Auto.previousOnline = online
    C.Auto.previousRoundIndex = roundIndex
    C.Auto.previousRoundStartedAt = tonumber(minigames.S.roundStartedAtMs or roundStartedAt) or roundStartedAt
end

local function checkbox(label, id, value)
    if not ImGui or not ImGui.Checkbox then return value == true, false end
    local ok, a, b = direct_call(ImGui.Checkbox, tostring(label) .. '##' .. tostring(id), value == true)
    if ok and type(a) == 'boolean' then return a, b == true or a ~= (value == true) end
    return value == true, false
end

local function queue_ui_job(name, fn)
    if not (Script and Script.QueueJob) then toast('Script.QueueJob unavailable.', 3500); return end
    Script.QueueJob(function()
        local ok, err = direct_call_trace(fn, debug and debug.traceback or function(e) return tostring(e) end)
        if not ok then log_info(tostring(name) .. ' failed: ' .. tostring(err)); toast(tostring(name) .. ' failed. Check Cherax.log.', 4500) end
    end)
end

local function show_pool(title, kind, tone)
    UI.Text(title, tone or 'cyan')
    for index, message in ipairs(C.MessagePoolsV213[kind] or {}) do UI.Text(tostring(index) .. '. ' .. tostring(message), 'dim', true) end
end

