            UI.Text('2. ' .. candidate_name(V.candidates[2]) .. '  [' .. tostring(counts[2]) .. ']', 'white', true)
            UI.Text('3. ' .. candidate_name(V.candidates[3]) .. '  [' .. tostring(counts[3]) .. ']', 'white', true)
        elseif V.pendingWinner then
            UI.Text('Next vehicle: ' .. candidate_name(V.pendingWinner), 'green', true)
