    end, 'red')

    UI.Child('WarGamesChat_Settings_V213', 'AUTOMATION', 'The vote opens with 90 seconds left and closes with 60 seconds left.', function()
        local value, changed = checkbox('Enable WarGames Phone Texts', 'WGChatEnabledV213', C.Settings.enabled)
        if changed then C.Settings.enabled = value; C.Save() end
