        value, changed = checkbox('Enable Manual Broadcast Buttons', 'WGManualBroadcastV213', VS.manualBroadcastEnabled)
        if changed then VS.manualBroadcastEnabled = value end
        UI.Text('Vote input accepts 1, 2, 3, the vehicle label, or the model name.', 'gold', true)
        UI.Text('Each player has one active vote. A later valid vote replaces the earlier vote.', 'dim', true)
        UI.Button('OPEN TEST VOTE NOW##WGOpenVoteV213', 'purple', function() queue_ui_job('Open vote', function() C.OpenSmartVoteV213(minigames.S.roundStartedAtMs or now_ms(), true) end) end, 210, 30)
        UI.SameLine()
        UI.Button('CLOSE VOTE NOW##WGCloseVoteV213', 'gold', function() queue_ui_job('Close vote', function() C.CloseSmartVoteV213(true) end) end, 210, 30)
    end, 'purple')

    UI.Child('WarGamesChat_Messages_V213', 'RANDOM MESSAGE POOLS', 'The same message is never selected twice in a row for its category.', function()
        show_pool('WarGames Started', 'start', 'green'); UI.Spacing(1)
        show_pool('Vehicle Vote', 'vote', 'purple'); UI.Spacing(1)
        show_pool('One-Minute Warning', 'minute', 'cyan'); UI.Spacing(1)
        show_pool('Vehicle Selected', 'vehicle', 'gold'); UI.Spacing(1)
        show_pool('Round Started', 'round', 'red'); UI.Spacing(1)
        show_pool('WarGames Ended', 'finish', 'green')
    end, 'gold')

    if VS.manualBroadcastEnabled then
        UI.Child('WarGamesChat_Manual_V213', 'MANUAL WARGAMES BROADCASTS', 'Optional. These never send automatically.', function()
            for index, message in ipairs(C.MessagePoolsV213.manual) do
                UI.Button('SEND ' .. tostring(index) .. '##WGManualV213_' .. tostring(index), index == 1 and 'cyan' or (index == 2 and 'purple' or 'gold'), function()
                    C.Enqueue(message, 'Manual WarGames broadcast', true)
                end, -1, 29)
