                local row = C.History[index]
                UI.Text(tostring(row.time) .. ' | ' .. tostring(row.source) .. ' | ' .. tostring(row.result), row.success and 'green' or 'red', true)
                UI.Text(tostring(row.message), 'dim', true)
            end
        end
        UI.Button('CLEAR HISTORY##WGClearHistoryV213', 'red', function() C.History = {}; C.LastStatus = 'History cleared' end, -1, 28)
    end, 'cyan')
