-- ============================================================
-- embedded module: systems\wargames_phone_v215.lua
-- ============================================================
embedded_modules['systems\\wargames_phone_v215.lua'] = function()
-- minigames v1.0.0 production
-- wargames outbound delivery is phone-text only. smart voting continues to
-- listen to on_chat_message for votes, but no wargames announcement is sent
-- to public session chat. methods 28, 29 and 30 remain the only transports.

minigames = minigames or {}
minigames.S = minigames.S or {}
minigames.Messenger = minigames.Messenger or {}
minigames.WarGamesChat = minigames.WarGamesChat or {}

local M = minigames.Messenger
local C = minigames.WarGamesChat
local Limits = minigames.UsageLimits or {}

local PHONE_LIMIT = 64
local PLAYER_FIRST = 0
local PLAYER_LAST = 31
local PLAYER_GAP_MS = 85
local CHUNK_GAP_MS = 350

local function yield_ms(ms)
    if Script and Script.Yield then direct_call(Script.Yield, tonumber(ms or 0) or 0) end
end

local function now_ms()
    if minigames.Now then
        local ok, value = direct_call(minigames.Now)
        if ok and tonumber(value) then return tonumber(value) end
    end
    if Time and Time.GetEpocheMs then
        local ok, value = direct_call(Time.GetEpocheMs)
        if ok and tonumber(value) then return tonumber(value) end
    end
    return math.floor((os.clock and os.clock() or 0) * 1000)
end

local function clean_line(value)
    value = tostring(value or ''):gsub('[\r\n]+', ' ')
    return value:gsub('^%s+', ''):gsub('%s+$', '')
end

local function local_player_id()
    if Limits.GetLocalPlayerId then
        local ok, value = direct_call(Limits.GetLocalPlayerId)
        if ok and tonumber(value) then return math.floor(tonumber(value)) end
    end
    if GTA and GTA.GetLocalPlayerId then
        local ok, value = direct_call(GTA.GetLocalPlayerId)
        if ok and tonumber(value) then return math.floor(tonumber(value)) end
    end
    return 0
end

local function player_exists(pid)
    if not Players or not Players.GetById then return false end
    local ok, player = direct_call(Players.GetById, tonumber(pid) or -1)
    return ok and player ~= nil
end

local function collect_recipients()
    local recipients = {}
    local localId = local_player_id()
    for pid = PLAYER_FIRST, PLAYER_LAST do
        if pid ~= localId and player_exists(pid) then recipients[#recipients + 1] = pid end
    end
    return recipients
end

local function split_phone_text(value)
    local remaining = clean_line(value)
    local chunks = {}
    while remaining ~= '' do
        if #remaining <= PHONE_LIMIT then
            chunks[#chunks + 1] = remaining
            break
        end

        local window = remaining:sub(1, PHONE_LIMIT)
        local splitAt = nil
        for index = #window, 25, -1 do
            if window:sub(index, index):match('%s') then
                splitAt = index
                break
            end
        end

        if splitAt then
            chunks[#chunks + 1] = clean_line(remaining:sub(1, splitAt - 1))
            remaining = clean_line(remaining:sub(splitAt + 1))
        else
            chunks[#chunks + 1] = remaining:sub(1, PHONE_LIMIT)
            remaining = clean_line(remaining:sub(PHONE_LIMIT + 1))
        end
    end
    return chunks
end

local function add_history(source, message, result, success)
    C.History = C.History or {}
    table.insert(C.History, 1, {
        time = os.date and os.date('%H:%M:%S') or tostring(now_ms()),
        source = tostring(source or 'WarGames'),
        message = tostring(message or ''),
        result = tostring(result or ''),
        success = success == true,
    })
    while #C.History > 30 do table.remove(C.History) end
end

local function log_info(message)
    if minigames.LogInfo then direct_call(minigames.LogInfo, '[WarGames Phone] ' .. tostring(message or '')) end
end

local function log_error(message)
    if minigames.LogError then direct_call(minigames.LogError, '[WarGames Phone] ' .. tostring(message or '')) end
end

local function toast(message, duration)
    if minigames.Toast then
        local ok = direct_call(minigames.Toast, 'WarGames Phone', tostring(message or ''), tonumber(duration or 4000) or 4000)
        if ok then return end
    end
    if GUI and GUI.AddToast then direct_call(GUI.AddToast, 'WarGames Phone', tostring(message or ''), tonumber(duration or 4000) or 4000) end
end

M.Settings = M.Settings or {}
M.Settings.phoneEnabled = true
M.Settings.deliveryMode = 0
C.MaxMessageLength = 256
M.SendOne = function(playerId, message)
    return M.SendPhoneText(playerId, message)
end

function C.SendNow(rawMessage, source)
    local message = C.FormatMessage and C.FormatMessage(rawMessage) or clean_line(rawMessage)
    message = clean_line(message)
    if message == '' then return false, 'empty message' end
    if type(M.SendPhoneText) ~= 'function' then
        C.LastStatus = 'Phone transport unavailable'
        add_history(source, message, C.LastStatus, false)
        return false, 'M.SendPhoneText unavailable'
    end

    local recipients = collect_recipients()
    if #recipients == 0 then
        C.LastStatus = 'No remote players available for phone delivery'
        add_history(source, message, C.LastStatus, false)
        return false, 'no recipients'
    end

    local chunks = split_phone_text(message)
    if #chunks == 0 then return false, 'empty phone chunks' end

    local playerSucceeded = {}
    local playerFailed = {}
    local attempts = 0

    for chunkIndex, chunk in ipairs(chunks) do
        for _, pid in ipairs(recipients) do
            attempts = attempts + 1
            local okCall, sent, result = direct_call(M.SendPhoneText, pid, chunk)
            local success = okCall and sent == true
            if success then
                if playerFailed[pid] ~= true then playerSucceeded[pid] = true end
            else
                playerFailed[pid] = true
                playerSucceeded[pid] = nil
                log_error('Delivery failed | player=' .. tostring(pid) .. ' | chunk=' .. tostring(chunkIndex) .. '/' .. tostring(#chunks) .. ' | ' .. tostring(result or sent))
            end
            yield_ms(PLAYER_GAP_MS)
        end
        if chunkIndex < #chunks then yield_ms(CHUNK_GAP_MS) end
    end

    local successCount, failureCount = 0, 0
    for _, pid in ipairs(recipients) do
        if playerSucceeded[pid] == true and playerFailed[pid] ~= true then successCount = successCount + 1 else failureCount = failureCount + 1 end
    end

    C.LastSendMs = now_ms()
    C.LastMessage = message
    C.LastSource = tostring(source or 'WarGames')
    M.LastTransport = 'Phone Text Methods 28/29/30'
    M.Stats = M.Stats or {}
    M.Stats.phoneSent = (tonumber(M.Stats.phoneSent or 0) or 0) + successCount

    local resultText = 'Phone text attempted for ' .. tostring(successCount) .. '/' .. tostring(#recipients) .. ' players'
    if #chunks > 1 then resultText = resultText .. ' in ' .. tostring(#chunks) .. ' chunks' end
    resultText = resultText .. ' | methods 28 -> 29 -> 30'

    local anySuccess = successCount > 0
    C.LastStatus = resultText
    C.Stats = C.Stats or { sent = 0, failed = 0, skipped = 0 }
    if anySuccess then C.Stats.sent = (tonumber(C.Stats.sent or 0) or 0) + 1
    else C.Stats.failed = (tonumber(C.Stats.failed or 0) or 0) + 1 end
    add_history(source, message, resultText, anySuccess)
    log_info('Sent | source=' .. tostring(source or 'WarGames') .. ' | recipients=' .. tostring(#recipients) .. ' | successful=' .. tostring(successCount) .. ' | failed=' .. tostring(failureCount) .. ' | attempts=' .. tostring(attempts) .. ' | chunks=' .. tostring(#chunks) .. ' | message=' .. message)

    if not anySuccess then return false, resultText end
    return true, 'phone-text-methods-28-29-30'
end

function C.LocalPreview(rawMessage)
    local message = C.FormatMessage and C.FormatMessage(rawMessage) or clean_line(rawMessage)
    local chunks = split_phone_text(message)
    if #chunks == 0 then toast('Nothing to preview.', 2500); return false end
    toast('Phone preview (' .. tostring(#chunks) .. ' text' .. (#chunks == 1 and '' or 's') .. '): ' .. table.concat(chunks, ' | '), 7000)
    return true
end

C.DeliveryModeV215 = 'GTA_PHONE_TEXT_ONLY'
C.PhoneMethodsV215 = {28, 29, 30}
C.PhoneCharacterLimitV215 = PHONE_LIMIT
C.LastStatus = 'Ready | GTA phone text methods 28 -> 29 -> 30'
minigames.S.warGamesPhoneOnlyV215 = true
minigames.S.warGamesSessionChatDisabledV215 = true
minigames.S.showMessengerTab = false
minigames.S.messengerHiddenForProductionV100 = true

-- the production ui no longer exposes messenger settings. keep automatic
-- wargames phone announcements enabled so the hidden transport remains useful.
C.Settings = C.Settings or {}
C.Settings.enabled = true
if C.Save then direct_call(C.Save) end

minigames.VERSION = 'v1.0.0'
minigames.BUILD_DATE = '2026-08-02'

log_info('Production loaded | Messenger tab hidden | automatic WarGames GTA phone delivery enabled | method 28 primary | methods 29/30 execution fallbacks | 64-character chunking')
end

local function __mg_run_embedded_boot()
    __mg_loader_wait(1000)

    _G.minigames = _G.minigames or {}

    minigames.NAME = "Minigames"
    minigames.TITLE = "MiniGames"
    minigames.SUBTITLE = "Turn the lobby into your personal playground."
    minigames.VERSION = script_version
    minigames.BUILD_DATE = script_release_date
    minigames.AUTHOR = "Public_Urinal"
    minigames.HELP = "ChatGPT"

    minigames.LUA_ROOT =
        (os.getenv("USERPROFILE") or ".") ..
        "\\Documents\\Cherax\\Lua"

    minigames.ROOT = minigames.LUA_ROOT .. "\\Minigames"
    minigames.ASSETS_ROOT = minigames.ROOT .. "\\assets"
    minigames.SYSTEMS_ROOT = minigames.ROOT .. "\\systems"
    minigames.WARGAMES_ROOT = minigames.ROOT .. "\\WarGames"
    minigames.DRIFTGOD_ROOT = minigames.ROOT .. "\\DriftGod"
    minigames.BEAST_ROOT = minigames.ROOT .. "\\Beast"
    minigames.WARGAMES_VEHICLES_ROOT =
        minigames.WARGAMES_ROOT .. "\\Vehicles"

    minigames.LoadFile = __mg_execute_embedded_module

    minigames.S = minigames.S or {}
    minigames.S.cleanBootConsoleV205 = true
    minigames.S.verboseBootLogsV205 = false

    -- exact v0.164 module order.
    minigames.LoadFile("core.lua")
    minigames.LoadFile("settings.lua")

    if minigames.SafeMkdir then
        minigames.SafeMkdir(minigames.ROOT)
        minigames.SafeMkdir(minigames.ASSETS_ROOT)
    end

    local assetOk, assetStatus, assetPath =
        __mg_ensure_intro_logo_asset(
            minigames.ASSETS_ROOT,
            minigames.LUA_ROOT,
            false
        )

    minigames.S = minigames.S or {}
    minigames.S.introLogoRemoteEnabled = true
    minigames.S.introLogoRemoteUrl =
        MINIGAMES_INTRO_LOGO_REMOTE_URL
    minigames.S.introLogoRemoteCacheFile =
        "assets/" .. MINIGAMES_INTRO_LOGO_FILE
    minigames.S.introLogoRemoteStatus =
        tostring(assetStatus or "unknown")
    minigames.S.introLogoRemotePath =
        tostring(assetPath or "")
    -- v0.202 official-brand migration. always point the intro renderer at the
    -- new github-backed logo even when an older config saved the legacy name.
    minigames.S.introLogoFile = MINIGAMES_INTRO_LOGO_FILE

    minigames.DownloadIntroLogoAssetV169 =
        function(force)
            local ok, status, path =
                __mg_ensure_intro_logo_asset(
                    minigames.ASSETS_ROOT,
                    minigames.LUA_ROOT,
                    force == true
                )

            minigames.S.introLogoRemoteStatus =
                tostring(status or "unknown")
            minigames.S.introLogoRemotePath =
                tostring(path or "")

            if ok and minigames.IntroLogo then
                minigames.IntroLogo.textureId = nil
                minigames.IntroLogo.textureSrv = nil
                minigames.IntroLogo.warned = false
            end

            if ok then
                __mg_loader_log(
                    "Intro logo asset ready | " ..
                    tostring(status) ..
                    " | path=" .. tostring(path)
                )
            else
                __mg_loader_error(
                    "Intro logo asset download failed | " ..
                    tostring(status)
                )
            end

            return ok, status, path
        end

    if assetOk then
        __mg_loader_log(
            "Intro logo asset ready | " ..
            tostring(assetStatus) ..
            " | path=" .. tostring(assetPath)
        )
    else
        __mg_loader_error(
            "Intro logo asset unavailable; text fallback remains active | " ..
            tostring(assetStatus) ..
            " | expected GitHub path=Minigames/assets/" ..
            MINIGAMES_INTRO_LOGO_FILE
        )
    end

    minigames.LoadFile("assets\\vehicles.lua")
    minigames.LoadFile("systems\\ascii_banner.lua")

    minigames.LoadFile("systems\\players.lua")
    minigames.LoadFile("systems\\teleport.lua")
    minigames.LoadFile("systems\\bounty.lua")
    minigames.LoadFile("systems\\upgrades.lua")
    minigames.LoadFile("systems\\vehicle_spawn.lua")
    minigames.LoadFile("systems\\vehicle_spawn_prime.lua")
    minigames.LoadFile("systems\\vehicle_tracking.lua")
    minigames.LoadFile("systems\\pedwars_entity_cleanup.lua")
    minigames.LoadFile("systems\\vehicle_rounds.lua")
    minigames.LoadFile("systems\\fair_vehicle_enforcement.lua")
    minigames.LoadFile("systems\\respawn.lua")
    minigames.LoadFile("systems\\weapons.lua")
    minigames.LoadFile("systems\\debug.lua")
    minigames.LoadFile("systems\\scheduler.lua")

    minigames.LoadFile("WarGames\\init.lua")
    minigames.LoadFile("LandOnIt\\init.lua")
    minigames.LoadFile("DriftGod\\init.lua")
    minigames.LoadFile("Beast\\init.lua")

    minigames.LoadFile("systems\\adaptive_hud.lua")
    minigames.LoadFile("ui.lua")
    minigames.LoadFile("systems\\intro_logo.lua")
    minigames.LoadFile("startup.lua")
    minigames.LoadFile("systems\\cherax_vehicle_spam_protection.lua")
    minigames.LoadFile("systems\\wargames_force_bounty_60s.lua")
    minigames.LoadFile("systems\\ui_overhaul_v169.lua")
    minigames.LoadFile("systems\\ui_product_polish_v169.lua")
    minigames.LoadFile("systems\\ui_guide_credits_v170.lua")
    minigames.LoadFile("systems\\ui_minimal_v172.lua")
    minigames.LoadFile("systems\\bounty_auto_enroll_v173.lua")
    minigames.LoadFile("systems\\purge_ui_v175.lua")
    minigames.LoadFile("systems\\purge_game_v185.lua")
    minigames.LoadFile("systems\\ui_subtabs_v185.lua")
    minigames.LoadFile("systems\\v186_games_favorites_apocalypse.lua")
    minigames.LoadFile("systems\\ui_clarity_v190.lua")
    minigames.LoadFile("systems\\support_diagnostics_v192.lua")
    minigames.LoadFile("systems\\ui_minimal_v192.lua")
    minigames.LoadFile("systems\\v196_purge_worldz.lua")
    minigames.LoadFile("systems\\usage_limits_v204.lua")
    minigames.LoadFile("systems\\access_gui_v205.lua")

    -- v1.0.1 production: preserve the phone/message code in this single file,
    -- but do not execute it or register its handlers.
    minigames.S = minigames.S or {}
    minigames.S.showMessengerTab = false
    minigames.S.messengerHiddenForProductionV100 = true
    minigames.S.warGamesPhoneOnlyV215 = false
    minigames.S.warGamesSessionChatDisabledV215 = false
    minigames.S.warGamesPhoneMessagesDisabledV101 = true
    minigames.S.warGamesSmartVotingDisabledV101 = true
    minigames.S.warGamesAnnouncementsDisabledV101 = true
    minigames.VERSION = script_version
    minigames.BUILD_DATE = script_release_date

    -- restore the full minigames intro only after the complete script is ready.
    -- a short deferred start prevents module registration and the startup
    -- settings backup from consuming the visible portion of the animation.
    minigames.S = minigames.S or {}
    minigames.S.introEnabled = true
    minigames.S.introLogoEnabled = true
    if minigames.IntroLogo and minigames.IntroLogo.ApplyFinalDefaults then
        direct_call(function() minigames.IntroLogo.ApplyFinalDefaults() end)
    end

    local function __mg_start_restored_intro()
        if minigames.IntroLogo and minigames.IntroLogo.StartIntro then
            direct_call(function() minigames.IntroLogo.StartIntro('post-boot Minigames intro restore') end)
        elseif minigames.ResetIntro then
            direct_call(function() minigames.ResetIntro() end)
        else
            minigames.S.introStartMs = minigames.Now and minigames.Now() or 0
        end
    end

    if Script and Script.QueueJob then
        Script.QueueJob(function()
            if Script.Yield then Script.Yield(750) end
            __mg_start_restored_intro()
        end)
    else
        __mg_start_restored_intro()
    end

    minigames.S = minigames.S or {}
    minigames.S.singleFileBuildV169 = true
    minigames.S.singleFileEmbeddedModuleCountV169 = 69
    minigames.S.singleFileRemoteAssetBuildV169 = true
    minigames.S.singleFileEmbeddedLogoBytesV169 = 0
    minigames.S.introLogoExpectedBytesV169 =
        MINIGAMES_INTRO_LOGO_EXPECTED_SIZE
    minigames.S.introLogoExpectedSha256V169 =
        MINIGAMES_INTRO_LOGO_SHA256

    minigames.S.cleanBootConsoleV205 = false

    local function console_color(name, fallback)
        if not eLogColor then return nil end
        return eLogColor[name] or eLogColor[fallback or "LIGHTCYAN"] or eLogColor.LIGHTCYAN
    end

    local function console_line(message, color_name)
        local color = console_color(color_name, "WHITE")
        local text = tostring(message or "")

        -- cherax adds a timestamp and logger prefix before every entry. clear the
        -- generated wrapper line with carriage returns, then draw only our text.
        local clean_text = "\r" .. string.rep(" ", 160) .. "\r" .. text

        if Logger and Logger.Log and color ~= nil then
            Logger.Log(color, "", clean_text)
            return
        end

        if Logger and Logger.LogInfo then
            Logger.LogInfo(clean_text)
        end
    end

    local separator = "──────────────────────────────────────────────────────────────────────────────"
    local art = minigames.AsciiBanner and minigames.AsciiBanner.MinigamesArt or "MINIGAMES"

    -- cherax applies one color to each logger entry. the wrapper-clearing prefix
    -- hides its timestamp and empty logger tag while preserving the requested
    -- per-entry colors. phone and start-rule rows remain hidden.
    console_line(separator, "WHITE")
    console_line(art, "RED")
    console_line(separator, "WHITE")
    console_line("MINIGAMES", "RED")
    console_line("Version: " .. script_version, "GREEN")
    console_line("Last Release: " .. script_release_date, "LIGHTBLUE")
    console_line("Core Modes: WarGames | The Purge | Land On It | DriftGod | Beast", "YELLOW")
    console_line("Daily Starts: UNLIMITED FOR TESTING", "YELLOW")
    console_line(separator, "WHITE")
    console_line("Enjoy Minigames ツ", "WHITE")
end

_G.MinigamesSingleFileBootQueuedV169 =
    _G.MinigamesSingleFileBootQueuedV169 == true

if EventMgr and EventMgr.RegisterHandler and
    eLuaEvent and eLuaEvent.ON_UNLOAD then
    direct_call(function()
        EventMgr.RegisterHandler(
            eLuaEvent.ON_UNLOAD,
            function()
                _G.MinigamesSingleFileBootQueuedV169 = false
                _G.MinigamesBootQueued = false
            end
        )
    end)
end

if _G.MinigamesSingleFileBootQueuedV169 ~= true then
    _G.MinigamesSingleFileBootQueuedV169 = true
    _G.MinigamesBootQueued = true

    if Script and Script.QueueJob then
        Script.QueueJob(function()
            local ok, err = direct_call(__mg_run_embedded_boot)

            if not ok then
                _G.MinigamesSingleFileBootQueuedV169 = false
                _G.MinigamesBootQueued = false
                __mg_loader_error("Boot failed: " .. tostring(err))
            end
        end)

        __mg_loader_log(
            "Single-file deferred boot queued | version=" ..
            script_version
        )
    else
        __mg_loader_log(
            "Script.QueueJob unavailable; using direct boot fallback."
        )

        local ok, err = direct_call(__mg_run_embedded_boot)
        if not ok then
            _G.MinigamesSingleFileBootQueuedV169 = false
            _G.MinigamesBootQueued = false
            __mg_loader_error("Boot failed: " .. tostring(err))
        end
    end
else
    __mg_loader_log("Single-file boot already queued.")
end
